def _sequence_mutation_argument_ids(
    operation: str, edges: Iterable[tuple[int, str]],
) -> tuple[int, ...]:
    """Return the argument occurrences retained by the mutation fact.

    This is the existing SOURCE_SEQUENCE_MUTATION contract: positional
    arguments, plus ``sort(key=...)`` because that callable controls the
    mutation order. Keep the ordinary call writer and loop-effect writer on
    this one projection so their same source call cannot publish competing
    facts. Keyword mutation options not represented by the incumbent page
    shape remain outside this fact.
    """

    return tuple(
        int(value_id)
        for value_id, role in edges
        if str(role).startswith("arg")
        or (str(operation) == "sort" and str(role) == "kw:key")
    )


_NUMERIC_FEATURE_TYPES = {
    frozenset({"precision"}): "Precision",
    frozenset({"complex", "precision"}): "ComplexPrecision",
    frozenset({"rational"}): "Rational",
    frozenset({"rational", "precision"}): "RationalPrecision",
    frozenset({"complex", "rational"}): "ComplexRational",
    frozenset({"complex", "rational", "precision"}): (
        "ComplexRationalPrecision"
    ),
}
_NUMERIC_TYPE_FEATURES = {
    name: features for features, name in _NUMERIC_FEATURE_TYPES.items()
}


@dataclass(frozen=True)
class NumericFeatureDescriptor:
    """One authored numeric wrapper contract, before repository SSA.

    This is the source-facing description shared by boundary expansion,
    operator selection, and method selection.  A composite annotation is not
    a scalar with an interesting name: its feature set determines its owned
    component paths, and Precision determines how many scalar limbs each leaf
    owns.
    """

    type_name: str
    features: frozenset[str]
    limbs: int = 1
    element_type: str | None = None

    @property
    def coefficient_paths(self) -> tuple[tuple[str, ...], ...]:
        paths: tuple[tuple[str, ...], ...] = ((),)
        if "complex" in self.features:
            paths = (("real",), ("imag",))
        if "rational" in self.features:
            paths = tuple(
                (*path, component)
                for path in paths
                for component in ("numerator", "denominator")
            )
        return paths

    @property
    def scalar_components(self) -> int:
        width = self.limbs if "precision" in self.features else 1
        return len(self.coefficient_paths) * width

    @property
    def operators(self) -> tuple[str, ...]:
        operations = ["add", "sub", "mul", "truediv", "neg"]
        if "rational" in self.features:
            operations.append("pow_integer")
        return tuple(operations)

    @property
    def methods(self) -> tuple[str, ...]:
        methods = ["collapse"]
        if self.features == frozenset({"precision"}):
            methods.extend(("sqrt", "exp", "log"))
        if "rational" in self.features:
            methods.extend(("components", "reciprocal"))
            if "complex" not in self.features:
                methods.append("quotient")
        if "complex" in self.features:
            methods.extend(("collapse_components", "conjugate"))
        return tuple(methods)

    def receipt(self) -> dict[str, Any]:
        return {
            "type_name": self.type_name,
            "features": tuple(sorted(self.features)),
            "limbs": int(self.limbs),
            "element_type": self.element_type,
            "coefficient_paths": self.coefficient_paths,
            "scalar_components": self.scalar_components,
            "operators": self.operators,
            "methods": self.methods,
        }


def numeric_feature_descriptor(
    annotation: str | ast.AST | None,
) -> NumericFeatureDescriptor | None:
    """Normalize one supported numeric annotation into its complete shape."""

    if annotation is None:
        return None
    try:
        parsed = (
            annotation
            if isinstance(annotation, ast.AST)
            else ast.parse(str(annotation), mode="eval").body
        )
    except SyntaxError:
        return None
    target = parsed.value if isinstance(parsed, ast.Subscript) else parsed
    type_name = (
        target.id if isinstance(target, ast.Name)
        else target.attr if isinstance(target, ast.Attribute)
        else None
    )
    features = _NUMERIC_TYPE_FEATURES.get(str(type_name))
    if features is None:
        return None

    limbs, element_type = 1, None
    if isinstance(parsed, ast.Subscript):
        index = parsed.slice
        parts = index.elts if isinstance(index, ast.Tuple) else (index,)
        for part in parts:
            if isinstance(part, ast.Constant) and isinstance(part.value, int):
                limbs = max(int(part.value), 1)
            elif isinstance(part, ast.Name):
                element_type = part.id
            elif isinstance(part, ast.Constant) and isinstance(part.value, str):
                element_type = part.value
    if "precision" not in features:
        limbs = 1
    return NumericFeatureDescriptor(
        str(type_name), features, limbs, element_type,
    )


def join_numeric_feature_descriptors(
    *descriptors: NumericFeatureDescriptor | None,
) -> NumericFeatureDescriptor | None:
    """Canonical feature union and widest Precision contract."""

    present = tuple(descriptor for descriptor in descriptors if descriptor)
    if not present:
        return None
    features = frozenset().union(*(item.features for item in present))
    type_name = _NUMERIC_FEATURE_TYPES.get(features)
    if type_name is None:
        return None
    limbs = max(item.limbs for item in present)
    element_type = _widest_element(*(
        item.element_type for item in present
    ))
    return NumericFeatureDescriptor(
        type_name, features, limbs, element_type,
    )


def _numeric_feature_descriptor_from_receipt(
    receipt: Mapping[str, Any] | None,
) -> NumericFeatureDescriptor | None:
    """Recover the normalized descriptor carried by a graph value."""

    if not receipt:
        return None
    features = frozenset(map(str, receipt.get("features") or ()))
    type_name = str(receipt.get("type_name") or "")
    if not type_name or _NUMERIC_FEATURE_TYPES.get(features) != type_name:
        return None
    return NumericFeatureDescriptor(
        type_name=type_name,
        features=features,
        limbs=max(int(receipt.get("limbs") or 1), 1),
        element_type=(
            None if receipt.get("element_type") is None
            else str(receipt["element_type"])
        ),
    )


def numeric_feature_field_projection(
    descriptor: NumericFeatureDescriptor,
    attribute: str,
) -> NumericFeatureDescriptor | None:
    """Return the exact wrapper held by one structural coefficient field.

    Composite numeric wrappers are nested algebra, not packed anonymous
    scalars. ``real``/``imag`` remove the complex layer and
    ``numerator``/``denominator`` remove the rational layer. Precision width
    is orthogonal to both and therefore survives every projection unchanged.
    An empty feature set denotes an ordinary tensor coefficient and returns
    ``None``.
    """

    features = set(descriptor.features)
    attribute = str(attribute)
    if attribute in {"real", "imag"} and "complex" in features:
        features.remove("complex")
    elif attribute in {"numerator", "denominator"} and "rational" in features:
        features.remove("rational")
    else:
        return None
    projected = frozenset(features)
    if not projected:
        return None
    type_name = _NUMERIC_FEATURE_TYPES.get(projected)
    if type_name is None:
        return None
    return NumericFeatureDescriptor(
        type_name=type_name,
        features=projected,
        limbs=(descriptor.limbs if "precision" in projected else 1),
        element_type=descriptor.element_type,
    )


def numeric_feature_method_components(
    descriptor: NumericFeatureDescriptor,
    method: str,
) -> tuple[tuple[tuple[str, ...], NumericFeatureDescriptor | None], ...]:
    """Describe the ordered structural results of a numeric intrinsic."""

    if str(method) != "components":
        return ()
    if "complex" in descriptor.features:
        fields = ("real", "imag")
    elif "rational" in descriptor.features:
        fields = ("numerator", "denominator")
    else:
        return ()
    return tuple(
        ((field,), numeric_feature_field_projection(descriptor, field))
        for field in fields
    )


def _record_numeric_annotation_descriptors(graph: Any) -> dict[str, Any]:
    """Publish normalized numeric contracts at topology-reducer entry.

    Raw annotation spellings remain available for source archaeology. This
    adjacent table is the executable meaning consumed by operators, methods,
    calls, and ABI expansion, so none of those stages has to reinterpret an
    annotation independently.
    """

    target = getattr(graph, "G", graph)
    metadata = getattr(target, "graph", None)
    if not isinstance(metadata, dict):
        return {}
    by_function = metadata.get("function_parameter_annotations") or {}
    normalized: dict[str, dict[str, dict[str, Any]]] = {}
    for function_name, parameters in by_function.items():
        described = {}
        for parameter, annotation in (parameters or {}).items():
            descriptor = numeric_feature_descriptor(annotation)
            if descriptor is not None:
                described[str(parameter)] = descriptor.receipt()
        if described:
            normalized[function_name] = described
    metadata["function_parameter_numeric_descriptors"] = normalized

    local = {}
    for name, annotation in (metadata.get("type_annotations") or {}).items():
        descriptor = numeric_feature_descriptor(annotation)
        if descriptor is not None:
            local[str(name)] = descriptor.receipt()
    metadata["local_numeric_descriptors"] = local
    return {
        "parameters": normalized,
        "locals": local,
    }


def _canonical_source_class_identity(class_identity: Any) -> str:
    """One concordance identity for the primitive classes Python aliases."""
    from ...compiler.concordance_declarations import (
        canonical_python_type_identity,
    )

    return canonical_python_type_identity(class_identity)


def _concord_source_value_class(
    scope: str,
    value_id: int,
    class_identity: str,
    *,
    precision_limbs: int = 1,
    source: str,
    provenance: Any = None,
) -> tuple[str, int]:
    """Commit the class and precision width carried by a source value.

    ``provenance`` is the ``Derived`` cells the caller read (plan 60,
    section 3.9): the ingestion-side writers pass them; a caller that has
    not yet routed its cells posts ``Unsourced(HELPER_CALLER_UNROUTED)``
    under the latch, which lists it by enclosing function as the worklist.
    The ``source`` free string stays in the fact until every caller carries
    an edge.
    """

    from ...compiler.concordance_declarations import (
        REDUCTION, SOURCE_VALUE_CLASS,
    )
    from ...compiler.identity_concordance import Derived, Mode

    book = current_identity_book()
    page = book.page(SOURCE_VALUE_CLASS)
    row = (scope, int(value_id))
    proposed = (
        _canonical_source_class_identity(class_identity),
        max(int(precision_limbs or 1), 1),
    )
    incumbent = page.latest(row)
    if incumbent is not None:
        recorded = (str(incumbent[0]), int(incumbent[1]))
        if recorded != proposed:
            from ...compiler.identity_concordance import attach_failure_claim

            error = ValueError(
                "source value class concordance disagreement for "
                f"{scope!r} value {value_id}: recorded={recorded!r}, "
                f"recorded_source={tuple(incumbent[2:])!r}, "
                f"{source} says {proposed!r}"
            )
            # Refused here, not through ``post``: hand the claim to the
            # failure report so its concordance neighborhood is shown.
            attach_failure_claim(
                book, error, SOURCE_VALUE_CLASS, row,
                (*proposed, str(source)), REDUCTION, provenance,
                Mode.CONCORD,
            )
            raise error
        if isinstance(provenance, Derived):
            # CONCORD owns exactly this case: the fact remains unchanged while
            # every independently established predecessor edge is retained.
            # Returning before this post severed later call/annotation paths
            # whenever an earlier reduction had already named the same class.
            book.post(
                SOURCE_VALUE_CLASS, row, incumbent, stage=REDUCTION,
                provenance=provenance, mode=Mode.CONCORD,
            )
        return recorded
    if not isinstance(provenance, Derived):
        raise ValueError(
            f"source_value_class: no source cell for {row!r} -- the caller "
            f"({source}) passed no Derived cells"
        )
    book.post(
        SOURCE_VALUE_CLASS, row, (*proposed, str(source)), stage=REDUCTION,
        provenance=provenance, mode=Mode.CONCORD,
    )
    return proposed


def _source_numeric_scope(graph: Any, fallback: str = "<module>") -> Any:
    """Return an exact authored identity or a book-minted synthetic scope.

    ``fallback`` is diagnostic text only. Local names and reconstructed
    owner.name spellings must never identify concordance rows.
    """

    target = getattr(graph, "G", graph)
    metadata = target.graph
    specialized = metadata.get("source_numeric_scope")
    if specialized is not None:
        return specialized
    identity = metadata.get("authored_function_identity")
    if identity is not None:
        return tuple(identity)
    scope = metadata.get("source_numeric_base_scope")
    if scope is None:
        scope = current_identity_book().mint_scope("synthetic numeric graph")
        metadata["source_numeric_base_scope"] = scope
    return scope


def _post_source_span(node: Any, stage: Any = None) -> Any:
    """The ``source_span`` cell of an authored AST node, by its stamped row
    (``graph_express2.post_source_span``); ``None`` for anything that is
    not a stamped source construct."""

    if not isinstance(node, ast.AST):
        return None
    from ...transmogrifier.graph.graph_express2 import post_source_span

    return post_source_span(None, node, stage=stage)


def _parameter_argument(statement: Any, name: str) -> ast.arg | None:
    """The ``ast.arg`` of parameter ``name`` on one definition, or None."""

    arguments = getattr(statement, "args", None)
    if arguments is None:
        return None
    for argument in (
        *arguments.posonlyargs, *arguments.args, *arguments.kwonlyargs,
        *((arguments.vararg,) if arguments.vararg else ()),
        *((arguments.kwarg,) if arguments.kwarg else ()),
    ):
        if argument.arg == name:
            return argument
    return None


def _parameter_default_expression(statement: Any, name: str) -> ast.AST | None:
    """The authored default expression of parameter ``name``, or None."""

    arguments = getattr(statement, "args", None)
    if arguments is None:
        return None
    positional = (*arguments.posonlyargs, *arguments.args)
    defaults = arguments.defaults
    for argument, default in zip(
        positional[len(positional) - len(defaults):], defaults,
    ):
        if argument.arg == name:
            return default
    for argument, default in zip(arguments.kwonlyargs, arguments.kw_defaults):
        if argument.arg == name and default is not None:
            return default
    return None


def post_scalar_parameter(
    graph: Any, node_id: int, name: str, statement: Any,
) -> Any:
    """One ``scalar_parameter`` row for Input ``node_id`` of parameter
    ``name`` (plan 60, section 3.5): DERIVED from (i) the parameter's
    ``parameter_annotation`` row when the annotation named a scalar type,
    else (ii) the span of its scalar literal default, and always the
    Input's own identity cell.  The row lives in the scope of that cell."""

    book = current_identity_book()
    input_cell = node_identity_cell(graph, int(node_id))
    annotation_cell = None
    statement_row = getattr(statement, "_turing_source_span_row", None)
    if isinstance(statement_row, tuple):
        annotation_cell = book.latest_ref(
            _PARAMETER_ANNOTATION,
            (statement_row[0], statement_row[1], str(name)),
        )
    default_span = (
        None if annotation_cell is not None
        else _post_source_span(_parameter_default_expression(statement, name))
    )
    return book.post(
        _SCALAR_PARAMETER, (input_cell.row[0], int(node_id)),
        _ValueKind.SCALAR, stage=_FUNCTION_SUBGRAPH,
        provenance=_Derived(tuple(
            cell for cell in (annotation_cell, default_span, input_cell)
            if cell is not None
        )),
        mode=_Mode.CONCORD,
    )


def node_ingestion_scopes(graph: Any) -> tuple[Any, ...]:
    """The scopes ``node_identity_cell`` reads a node's ``ingestion_value``
    row in, in order: this reduction's ``operand_position_scope``, then the
    build's ``ingestion_value_scope``.  Empty: the graph has no identity
    scope, and ``node_identity_cell`` refuses it."""

    metadata = getattr(getattr(graph, "G", graph), "graph", {}) or {}
    return tuple(
        scope for scope in (
            metadata.get("operand_position_scope"),
            metadata.get("ingestion_value_scope"),
        )
        if scope is not None
    )


def node_identity_cell(graph: Any, node_id: int) -> Any:
    """The cell that identifies graph node ``node_id`` (plan 60, seam 1).

    After the canonical relabel it is the node's ``canonical_value`` row
    cell (scope ``lexical_read_scope``); before it, the node's
    ``ingestion_value`` row cell -- posted by ``new_node`` in this
    reduction's ingestion scope (``operand_position_scope``) or by
    ``ProcessGraph.ensure_node`` in the build's ``ingestion_value_scope``.
    A node with no row yet raises: a writer with no cell is a bug upstream.
    """

    from ...compiler.concordance_declarations import (
        CANONICAL_VALUE, INGESTION_VALUE,
    )

    book = current_identity_book()
    metadata = getattr(getattr(graph, "G", graph), "graph", {}) or {}
    node_id = int(node_id)
    if metadata.get("canonical_value_ids"):
        scope = metadata.get("lexical_read_scope")
        if scope is not None:
            cell = book.latest_ref(CANONICAL_VALUE, (scope, node_id))
            if cell is not None:
                return cell
    scopes = node_ingestion_scopes(graph)
    for scope in scopes:
        cell = book.latest_ref(INGESTION_VALUE, (scope, node_id))
        if cell is not None:
            return cell
    if not scopes:
        raise ValueError(
            f"node {node_id} has no ingestion scope: the graph was neither "
            "built by build_from_ast nor entered lexical normalization"
        )
    data = getattr(graph, "G", graph).nodes.get(node_id) or {}
    # A node is registered when it is made (``new_node`` / ``ensure_node``);
    # one with no row is a creation that skipped the book, named here.
    raise ValueError(
        f"node {node_id} ({data.get('type')!r} {data.get('label')!r}) has no "
        f"identity row under {scopes!r}: it was created without being "
        "registered on the book"
    )


def post_derived_node_identity(
    graph: Any, node_id: int, cells: Iterable[Any], *, stage: Any,
) -> Any:
    """Post a synthesized node's ``ingestion_value`` row DERIVED from
    ``cells`` (what the node stands for) in the scope ``node_identity_cell``
    reads first, and return its cell (edges lane C).

    For writers that add a node outside ``new_node`` (a dispatch Store, an
    output Store): call before the node's operands are written, so
    ``_set_operands`` finds the consumer's row instead of posting its
    Unsourced fallback.  A node that already has a row, a graph with no
    ingestion scope, or no cell: nothing is posted (``None`` / the
    existing cell)."""

    from ...compiler.identity_concordance import Mode

    existing = _posted_node_identity_cell(graph, int(node_id))
    if existing is not None:
        return existing
    scopes = node_ingestion_scopes(graph)
    cells = tuple(dict.fromkeys(cell for cell in cells if cell is not None))
    if not scopes or not cells:
        return None
    data = getattr(graph, "G", graph).nodes.get(node_id) or {}
    return current_identity_book().post(
        _INGESTION_VALUE, (scopes[0], int(node_id)),
        _NodeFact(
            str(data.get("type") or ""), str(data.get("op") or ""),
            str(data.get("label") or ""),
        ),
        stage=stage, provenance=_Derived(cells), mode=Mode.CONCORD,
    )


def _posted_node_identity_cell(graph: Any, node_id: int) -> Any:
    """``node_identity_cell`` without its Unsourced fallback: the node's
    posted ``canonical_value`` / ``ingestion_value`` cell, or ``None``."""

    from ...compiler.concordance_declarations import (
        CANONICAL_VALUE, INGESTION_VALUE,
    )

    book = current_identity_book()
    metadata = getattr(getattr(graph, "G", graph), "graph", {}) or {}
    if metadata.get("canonical_value_ids"):
        scope = metadata.get("lexical_read_scope")
        if scope is not None:
            cell = book.latest_ref(CANONICAL_VALUE, (scope, int(node_id)))
            if cell is not None:
                return cell
    for scope in node_ingestion_scopes(graph):
        cell = book.latest_ref(INGESTION_VALUE, (scope, int(node_id)))
        if cell is not None:
            return cell
    return None


def _node_identity_cells(graph: Any, *node_ids: Any) -> tuple:
    """The identity cells of graph nodes ``node_ids`` (``node_identity_cell``
    each: a node with no row raises there), deduplicated in order -- the
    ``Derived`` cells of a fact a reducer pass read from those nodes."""

    return tuple(dict.fromkeys(
        node_identity_cell(graph, int(node_id)) for node_id in node_ids
    ))


def _source_cells(cells: Iterable[Any]) -> tuple:
    """``cells`` as ``Derived`` takes them: deduplicated in order, without
    the ``None`` of an optional secondary cell that is absent.  An empty
    set is the book's refusal to make, not this module's."""

    return tuple(dict.fromkeys(cell for cell in cells if cell is not None))


def post_indexed_store_site(
    graph: Any, scope: Any, target: Any, effect_node_ids: Iterable[int],
) -> Any:
    """Mint the identity of an indexed store that has no authored node of
    its own (``m[:2] -= t``: the target Subscript node is the read).

    One ``indexed_store_site`` row ``(scope, NEW)``, NOVEL(
    INDEXED_STORE_SITE_MINT, (target span cell, effect cell)): rooted at the
    authored target's ``source_span`` row, with the nodes at the authored
    effect (the target read, the stored value) as provenance -- one node
    cell, or a ``cell_set`` row DERIVED from several.  ``None`` when the
    target is no stamped source construct (a synthesized target): the
    store then stays ``Unsourced`` and the latch lists it.
    """

    from ...compiler.concordance_declarations import (
        CELL_SET, INDEXED_STORE_SITE, INDEXED_STORE_SITE_MINT,
        IndexedStoreSiteFact,
    )
    from ...compiler.identity_concordance import NEW, Novel

    span = _post_source_span(target)
    if span is None:
        return None
    book = current_identity_book()
    effects = tuple(dict.fromkeys(
        node_identity_cell(graph, int(node))
        for node in effect_node_ids
        if node is not None and int(node) in getattr(graph, "G", graph)
    ))
    if not effects:
        return None
    if len(effects) == 1:
        effect = effects[0]
    else:
        effect = book.post(
            CELL_SET, (scope, book.page(CELL_SET).scope_row_count(scope) + 1),
            tuple(cell.key for cell in effects),
            stage=_REDUCTION, provenance=_Derived(effects), mode=_Mode.CONCORD,
        )
    return book.post(
        INDEXED_STORE_SITE, (scope, NEW), IndexedStoreSiteFact(span),
        stage=_REDUCTION,
        provenance=Novel(INDEXED_STORE_SITE_MINT, (span, effect)),
        mode=_Mode.CONCORD,
    )


def indexed_store_site_span(
    graph: Any, node_id: int,
) -> tuple[int, int, int, int] | None:
    """The authored span positions of an indexed store's site, read from
    the book: node identity cell -> (``canonical_value`` ->)
    ``ingestion_value`` -> ``indexed_store_site`` along posted edges, then
    the site's ``source_span`` cell.  ``None`` when the node's identity
    does not derive from a site.  The positions only order; the site cell
    is the identity."""

    from ...compiler.concordance_declarations import (
        CANONICAL_VALUE, INDEXED_STORE_SITE, INGESTION_VALUE, SOURCE_SPAN,
    )

    book = current_identity_book()
    cell = _posted_node_identity_cell(graph, node_id)
    identity_pages = {CANONICAL_VALUE.name, INGESTION_VALUE.name}
    frontier = [cell] if cell is not None else []
    seen: set = set()
    while frontier:
        ref = frontier.pop()
        if ref.key in seen:
            continue
        seen.add(ref.key)
        if ref.page.name == INDEXED_STORE_SITE.name:
            site = book.page(INDEXED_STORE_SITE).latest(ref.row)
            span = book.page(SOURCE_SPAN).latest(site.span.row)
            if span is None or span.lineno < 0:
                return None
            return (
                int(span.lineno), int(span.col_offset),
                int(span.end_lineno), int(span.end_col_offset),
            )
        if ref.page.name not in identity_pages:
            continue
        frontier.extend(
            source for source, _stage in book.edges_into(ref)
            if source.page.name in identity_pages | {INDEXED_STORE_SITE.name}
        )
    return None


def specialize_python_precision_widths(graph: Any) -> bool:
    """Refresh Precision identity after exact callsite specialization.

    Source reduction necessarily sees a generic function before callsite
    planning proves structural parameters such as ``limbs``.  A width chosen
    there is therefore provisional.  This pass runs on the clean specialized
    graph, gives that specialization its own concordance scope, and repeats
    only the existing Precision identity decisions: call result width,
    arithmetic spelling, and boundary width.  It does not merge, inline, or
    execute specializations.
    """

    target_wrapper = graph
    target = getattr(graph, "G", graph)
    metadata = getattr(target, "graph", {})
    specializations = dict(metadata.get("planner_specializations") or {})

    def stable(value: Any) -> Any:
        if isinstance(value, Mapping):
            return tuple(sorted(
                (str(key), stable(item)) for key, item in value.items()
            ))
        if isinstance(value, (tuple, list)):
            return tuple(stable(item) for item in value)
        if isinstance(value, (str, bytes, bool, int, float, type(None))):
            return value
        return repr(value)

    authored_scope = metadata.get("authored_function_identity")
    if authored_scope is not None:
        authored_scope = tuple(authored_scope)
    else:
        # Synthetic graphs retain their book-minted identity across copies.
        authored_scope = metadata.get("source_numeric_base_scope")
        if authored_scope is None:
            authored_scope = current_identity_book().mint_scope("synthetic numeric graph")
            metadata["source_numeric_base_scope"] = authored_scope
    parameter_classes = dict(metadata.get("planner_parameter_classes") or {})
    parameter_class_cells = dict(
        metadata.get("planner_parameter_class_cells") or {}
    )
    # An exact iterable domain is part of this specialization, not an
    # annotation to inherit from the generic function. Normalize the existing
    # target identity through read-scope copies, so equal domains share a
    # variant while bool/int/unknown domains cannot collide in one scope.
    from ...compiler.identity_concordance import _canonical_identity_base
    from ...compiler.concordance_declarations import CANONICAL_VALUE, INGESTION_VALUE, CELL_SET
    class_book = current_identity_book()
    exact_iterated_classes = {}
    iterable_domains = {}
    for node_id, data in target.nodes(data=True):
        actual_class = (data.get("attributes") or {}).get("callsite_iterable_element_class_cell")
        if actual_class is None:
            continue
        value_id = int(data.get("value_id", node_id))
        if (not isinstance(actual_class, _Ref) or actual_class.page != _SOURCE_VALUE_CLASS
                or actual_class.row[1] != value_id):
            raise ValueError("callsite iterable class Ref does not name its canonical target")
        fact = class_book.page(_SOURCE_VALUE_CLASS).cell(actual_class.row, actual_class.column)
        if not isinstance(fact, tuple) or len(fact) < 2:
            raise ValueError("callsite iterable class Ref has no class fact")
        canonical_target = _canonical_identity_base(class_book, node_identity_cell(target_wrapper, int(node_id)))
        pending, visited, related = [actual_class], set(), False
        while pending:
            source = pending.pop()
            if source in visited:
                continue
            visited.add(source)
            if source.page in {CANONICAL_VALUE, INGESTION_VALUE}:
                related |= _canonical_identity_base(class_book, source) == canonical_target
            elif source.page in {_SOURCE_VALUE_CLASS, CELL_SET}:
                pending.extend(parent for parent, _stage in class_book.edges_into(source))
        if not related:
            raise ValueError("callsite iterable class Ref does not derive from its canonical target")
        domain = (_canonical_source_class_identity(fact[0]), int(fact[1]))
        prior = iterable_domains.setdefault(canonical_target.key, domain)
        if prior != domain:
            raise ValueError("one canonical iterable target has conflicting class domains")
        exact_iterated_classes[value_id] = (actual_class, fact, canonical_target)
    receipt = tuple(sorted(
        (str(name), stable(value))
        for name, value in specializations.items()
    )) + tuple(
        (f"class:{name}", stable(value))
        for name, value in sorted(parameter_classes.items())
    ) + tuple(
        (("iterated_class", identity), domain)
        for identity, domain in sorted(iterable_domains.items(), key=lambda item: repr(item[0]))
    )
    digest = hashlib.sha256(repr(receipt).encode("utf-8")).hexdigest()[:16]
    scope = (authored_scope, "specialization", digest)
    from ...compiler.concordance_declarations import (
        SOURCE_NUMERIC_SPECIALIZATION as _SOURCE_NUMERIC_SPECIALIZATION,
        SOURCE_NUMERIC_SPECIALIZATION_PAGE as _SPECIALIZATION_PAGE,
    )
    identity_page = current_identity_book().page(
        "source_numeric_specialization_concordance"
    )
    identity_row = (authored_scope, digest)
    identity_fact = (scope, receipt)
    incumbent = identity_page.latest(identity_row)
    if incumbent is not None and tuple(incumbent) != identity_fact:
        raise ValueError(
            "source numeric specialization concordance disagreement for "
            f"{identity_row!r}: recorded={incumbent!r}, "
            f"proposed={identity_fact!r}"
        )
    if incumbent is None:
        from ...compiler.identity_concordance import Novel as _Novel

        specialization_book = current_identity_book()
        # The graph names its function by address (``function_ref``); the
        # ``function_address`` row whose fact is that address is its cell.
        authored_cell = None
        authored_address = metadata.get("function_ref")
        address_page = specialization_book.pages.get(_FUNCTION_ADDRESS.name)
        if authored_address is not None and address_page is not None:
            authored_cell = next((
                specialization_book.latest_ref(_FUNCTION_ADDRESS, row)
                for row in address_page.rows()
                if address_page.latest(row) == int(authored_address)
            ), None)
        # The specialization is its authored function with some inputs
        # known: NOVEL from the authored function's address cell.
        if authored_cell is None:
            raise ValueError(
                f"{_SPECIALIZATION_PAGE}: no source cell for "
                f"{identity_row!r} -- the graph's function_ref has no "
                "function_address row on the book"
            )
        causes = tuple(dict.fromkeys((authored_cell, *(cell for actual, _fact, target_cell
                     in exact_iterated_classes.values() for cell in (actual, target_cell)))))
        source = authored_cell
        if len(causes) > 1:
            source = specialization_book.post(
                CELL_SET, (scope, specialization_book.page(CELL_SET).scope_row_count(scope) + 1),
                tuple(cell.key for cell in causes), stage=_REDUCTION,
                provenance=_Derived(causes), mode=_Mode.CONCORD,
            )
        specialization_book.post(
            _SPECIALIZATION_PAGE, identity_row, identity_fact,
            stage=_REDUCTION,
            provenance=_Novel(_SOURCE_NUMERIC_SPECIALIZATION, (source,)),
            mode=_Mode.CONCORD,
        )
    metadata["source_numeric_scope"] = scope
    metadata["source_numeric_specialization_receipt"] = receipt
    # A specialization is its authored function with some inputs known: the
    # authored function's committed facts hold in it (never a sibling
    # specialization's, which were decided for other inputs).
    specialization_book = current_identity_book()
    class_page = specialization_book.page(
        "source_value_class_concordance"
    )
    # worst_penalty(spans: StepSpans) is called with Metrics, which exposes
    # the same declared publication view. The annotation is still a view;
    # the actual object is Metrics. Its exact caller class is already on
    # this specialization's receipt, so copying StepSpans into the fresh
    # Input identity would create a false conflict before the actual below.
    exact_parameter_ids = {
        int(node_id) for node_id, data in target.nodes(data=True)
        if data.get("type") == "Input"
        and (name := (data.get("attributes") or {}).get("binding_name")) is not None
        and str(name) in parameter_classes
        and tuple(parameter_class_cells.get(str(name)) or ())
    }
    if authored_scope != scope:
        inherited_classes = {}
        for row in tuple(class_page.rows()):
            if (
                isinstance(row, tuple) and len(row) == 2
                and row[0] == authored_scope
                and row[1] in target
                and row[1] not in exact_parameter_ids
            ):
                history = class_page.history(row)
                inherited_classes[int(row[1])] = (
                    history[-1][1], tuple(_Ref(_SOURCE_VALUE_CLASS, row, column)
                                          for column, _fact in history),
                )
        # last([False, True]) can keep its canonical loop target while
        # folding changes the numeric specialization scope. The existing
        # callsite producer retains the exact target class Ref for precisely
        # that handoff. It owns this projection, including an explicit
        # unknown class; the generic list[int] declaration does not.
        for value_id, (actual_class, fact, _target_cell) in exact_iterated_classes.items():
            inherited_classes[value_id] = (fact, (actual_class,))
        specialization_cell = specialization_book.latest_ref(_SPECIALIZATION_PAGE, identity_row)
        for value_id, (fact, sources) in inherited_classes.items():
            current = class_page.latest((scope, value_id))
            if current is None or value_id in exact_iterated_classes:
                proposed = current if current is not None and current[:2] == fact[:2] else fact
                specialization_book.post(
                    _SOURCE_VALUE_CLASS, (scope, value_id), proposed,
                    stage=_REDUCTION,
                    provenance=_Derived(tuple(dict.fromkeys((*sources, specialization_cell)))),
                    mode=_Mode.CONCORD,
                )
    # The parameters are what the call passed: concord them in this scope.
    for node_id, data in target.nodes(data=True):
        if data.get("type") != "Input":
            continue
        name = (data.get("attributes") or {}).get("binding_name")
        if name is None or str(name) not in parameter_classes:
            continue
        class_identity, limbs = parameter_classes[str(name)]
        specialization_cell = specialization_book.latest_ref(
            _SPECIALIZATION_PAGE, identity_row,
        )
        class_sources = tuple(dict.fromkeys((
            node_identity_cell(target_wrapper, int(node_id)),
            *tuple(parameter_class_cells.get(str(name)) or ()),
            specialization_cell,
        )))
        _concord_source_value_class(
            scope, int(node_id), str(class_identity),
            precision_limbs=int(limbs),
            source=f"specialization call argument {name}",
            provenance=(
                _Derived(class_sources) if class_sources else None
            ),
        )
    # A Precision parameter is where this scope's Precision interval begins:
    # the value enters here already assembled at its concorded width (its
    # limbs are supplied by the caller), so it opens the interval as a pack.
    for node_id, data in target.nodes(data=True):
        if data.get("type") != "Input":
            continue
        fact = class_page.latest((scope, int(node_id)))
        if (
            isinstance(fact, tuple) and len(fact) >= 2
            and str(fact[0]).rsplit(".", 1)[-1] == "Precision"
        ):
            _concord_source_precision_boundary(
                scope, int(node_id), "pack", int(node_id),
                precision_limbs=max(int(fact[1]), 1),
                cells=(
                    *_node_identity_cells(target_wrapper, node_id),
                    specialization_book.latest_ref(
                        _SOURCE_VALUE_CLASS, (scope, int(node_id)),
                    ),
                ),
            )

    def static_int(expression: ast.AST) -> int | None:
        try:
            value = ast.literal_eval(expression)
        except (TypeError, ValueError, SyntaxError):
            if not isinstance(expression, ast.Name):
                return None
            value = specializations.get(expression.id)
        if isinstance(value, bool):
            return None
        try:
            return max(int(value), 1)
        except (TypeError, ValueError, OverflowError):
            return None

    def is_precision(identity: Any) -> bool:
        return (
            identity is not None
            and str(identity).rsplit(".", 1)[-1] == "Precision"
        )

    function_table = getattr(target_wrapper, "function_table", None)

    def tensor_descriptor(value_id: int) -> dict[str, Any] | None:
        if int(value_id) not in target:
            return None
        descriptor = target.nodes[int(value_id)].get("tensor")
        if isinstance(descriptor, Mapping) and tuple(
            descriptor.get("shape") or ()
        ):
            return copy.deepcopy(dict(descriptor))

        # Exact callsite planning publishes return extents to the concordance
        # because specialized graphs are disposable copies.  Numeric
        # specialization runs on another such copy, so a private ``tensor``
        # field is not an adequate hand-off.  Read the same authored value
        # row used by ``publish_call_result_shape`` before concluding that a
        # Precision promotion is scalar.
        from ...compiler.identity_concordance import (
            proven_shape_of,
            shape_scope_of,
        )

        data = target.nodes[int(value_id)]
        source_value_id = int(data.get("value_id", value_id))
        extents = proven_shape_of(shape_scope_of(metadata), source_value_id)
        if extents:
            materialized = (
                copy.deepcopy(dict(descriptor))
                if isinstance(descriptor, Mapping) else {}
            )
            materialized["shape"] = tuple(extents)
            materialized["rank"] = len(extents)
            materialized.setdefault("dtype", "float64")
            return materialized
        return (
            copy.deepcopy(dict(descriptor))
            if isinstance(descriptor, Mapping) else None
        )

    def publish_tensor(value_id: int, descriptor: Any) -> None:
        if not isinstance(descriptor, Mapping):
            return
        extents = tuple(descriptor.get("shape") or ())
        if not extents:
            return
        materialized = copy.deepcopy(dict(descriptor))
        materialized["shape"] = extents
        materialized.setdefault("rank", len(extents))
        target.nodes[int(value_id)]["tensor"] = materialized
        from ...compiler.identity_concordance import (
            record_proven_shape,
            shape_scope_of,
        )

        record_proven_shape(
            shape_scope_of(metadata), int(value_id), extents,
            materialized.get("dtype"), level=None,
        )

    def call_return_identity(
        attributes: Mapping[str, Any], expression: ast.Call,
    ) -> tuple[str | None, int | None, dict[str, Any] | None, tuple]:
        """Read the authored return class and exact specialized limbs.

        The fourth element is the callee return value's
        ``source_value_class`` cell when the class was read from it.
        """

        class_identity = attributes.get(
            "result_class_ref", attributes.get("class_ref")
        )
        reference = attributes.get(
            "callee_ref", attributes.get("method_ref")
        )
        callee = None
        return_tensor = None
        callee_class_cells: tuple = ()
        if reference is not None and function_table is not None:
            try:
                callee = function_table.entry(int(reference)).graph
            except (KeyError, TypeError, ValueError):
                callee = None
        if class_identity is None and callee is not None:
            outputs = tuple(callee.G.graph.get("function_outputs") or ())
            identities = callee.G.graph.get("identity_table") or {}
            candidates = tuple(
                int(value_id)
                for output in outputs
                for value_id in identities.get(str(output), ())
                if int(value_id) in callee.G
            )
            for value_id in reversed(candidates):
                candidate, _width = _resolved_source_value_class(
                    callee.G, value_id
                )
                if candidate is not None:
                    class_identity = candidate
                    callee_class_cells = _source_cells((
                        current_identity_book().latest_ref(
                            _SOURCE_VALUE_CLASS,
                            (_source_numeric_scope(callee.G), int(value_id)),
                        ),
                    ))
                    descriptor = callee.G.nodes[value_id].get("tensor")
                    if isinstance(descriptor, Mapping):
                        return_tensor = copy.deepcopy(dict(descriptor))
                    break
            if os.environ.get("TURING_DEBUG_PRECISION_SPECIALIZATION"):
                logger.warning(
                    "PRECISION-RETURN-IDENTITY caller=%s reference=%s "
                    "outputs=%r candidates=%r descriptors=%r",
                    authored_scope, reference, outputs, candidates,
                    tuple(
                        (value_id, _resolved_source_value_class(
                            callee.G, value_id
                        ))
                        for value_id in candidates
                    ),
                )
        width = None
        if callee is not None:
            positional = tuple(map(str,
                callee.G.graph.get("positional_parameters")
                or callee.G.graph.get("function_parameters")
                or ()
            ))
            if "limbs" in positional:
                position = positional.index("limbs")
                if position < len(expression.args):
                    width = static_int(expression.args[position])
        return (
            None if class_identity is None else str(class_identity),
            width,
            return_tensor,
            callee_class_cells,
        )

    changed = False
    precision_flow_widths: dict[int, int] = {}
    precision_flow_tensors: dict[int, dict[str, Any]] = {}
    # The width argument is an authored part of both Precision constructors
    # and Precision.of.  Calls returning Precision through a helper retain
    # the same proof when that call passes this specialization's exact limbs
    # parameter; the class identity was already established by source
    # reduction and is not guessed here.
    for node_id, data in tuple(target.nodes(data=True)):
        expression = data.get("expr_obj")
        attributes = data.setdefault("attributes", {})
        if not isinstance(expression, ast.Call):
            continue
        class_identity, call_width, return_tensor, callee_class_cells = (
            call_return_identity(attributes, expression)
        )
        if not is_precision(class_identity):
            continue
        width = None
        if len(expression.args) >= 2 and (
            isinstance(expression.func, ast.Name)
            and expression.func.id == "Precision"
            or isinstance(expression.func, ast.Attribute)
            and expression.func.attr == "of"
        ):
            width = static_int(expression.args[1])
        if width is None:
            width = call_width
        if width is None:
            for argument in expression.args:
                if (
                    isinstance(argument, ast.Name)
                    and argument.id in specializations
                    and argument.id == "limbs"
                ):
                    width = static_int(argument)
                    break
        if width is None:
            continue
        prior = int(attributes.get("precision_limbs") or 1)
        attributes["precision_limbs"] = int(width)
        attributes["result_class_ref"] = str(class_identity)
        if return_tensor is not None:
            publish_tensor(int(node_id), return_tensor)
        # DERIVED from the call and its operands (the width is read off the
        # authored arguments), the call's own class cell when source
        # reduction already named it, and the callee return value's class
        # cell when the class was read from the callee.
        _concord_source_value_class(
            scope, int(node_id), str(class_identity),
            precision_limbs=int(width),
            source="callsite-specialized Precision result",
            provenance=_Derived(_source_cells((
                *_node_identity_cells(target_wrapper, node_id, *(
                    int(parent) for parent, _role in data.get("parents", ())
                    if int(parent) in target
                )),
                current_identity_book().latest_ref(
                    _SOURCE_VALUE_CLASS, (scope, int(node_id)),
                ),
                *callee_class_cells,
            ))),
        )
        value_id = next((
            int(parent) for parent, role in data.get("parents", ())
            if str(role) in {"arg:0", "arg0"}
        ), None)
        is_promotion = (
            isinstance(expression.func, ast.Attribute)
            and expression.func.attr == "of"
        )
        is_pack = (
            isinstance(expression.func, ast.Name)
            and expression.func.id == "Precision"
        )
        if value_id is not None and is_promotion:
            attributes["python_precision_boundary"] = "promote"
            for field in (
                "callee_ref", "method_ref", "constructor_ref", "class_ref",
            ):
                attributes.pop(field, None)
            accessor_id = id(expression.func)
            if accessor_id in target:
                accessor_attributes = target.nodes[accessor_id].setdefault(
                    "attributes", {}
                )
                for field in (
                    "callee_ref", "method_ref", "bound_method_ref",
                ):
                    accessor_attributes.pop(field, None)
                accessor_attributes["python_precision_boundary"] = (
                    "promote-selector"
                )
            data["type"] = "Cast"
            data["op"] = "Cast"
            _replace_inputs(
                target_wrapper, int(node_id), ((int(value_id), "operand"),)
            )
            _concord_source_precision_boundary(
                scope, int(node_id), "promote", int(value_id),
                precision_limbs=int(width),
                cells=_node_identity_cells(target_wrapper, node_id, value_id),
            )
            source_tensor = tensor_descriptor(int(value_id))
            if source_tensor is not None:
                publish_tensor(int(node_id), source_tensor)
        elif value_id is not None and is_pack and value_id in target:
            value_attributes = target.nodes[value_id].get("attributes") or {}
            leaves = tuple(map(int,
                value_attributes.get("aggregate_leaf_value_ids")
                or value_attributes.get("materialized_value_ids")
                or value_attributes.get("materialized_source_value_ids")
                or ()
            ))
            if len(leaves) >= int(width) and all(
                leaf in target for leaf in leaves[:int(width)]
            ):
                leaves = leaves[:int(width)]
                attributes["python_precision_boundary"] = "pack"
                attributes["precision_pack_source_id"] = int(value_id)
                attributes["precision_pack_limb_ids"] = leaves
                for field in (
                    "callee_ref", "method_ref", "constructor_ref", "class_ref",
                ):
                    attributes.pop(field, None)
                data["type"] = PRECISION_PACK_NAME
                data["op"] = PRECISION_PACK_NAME
                _replace_inputs(
                    target_wrapper, int(node_id), tuple(
                        (leaf, f"limb:{index}")
                        for index, leaf in enumerate(leaves)
                    )
                )
                pack_book = current_identity_book()
                pack_page = pack_book.page(_SOURCE_PRECISION_PACK)
                pack_row = (scope, int(node_id))
                pack_fact = (leaves, int(width), int(value_id))
                incumbent_pack = pack_page.latest(pack_row)
                if (
                    incumbent_pack is not None
                    and tuple(incumbent_pack) != pack_fact
                ):
                    raise ValueError(
                        "source precision pack concordance disagreement for "
                        f"{pack_row!r}: recorded={incumbent_pack!r}, "
                        f"proposed={pack_fact!r}"
                    )
                # The pack is the aggregate's limbs: DERIVED from the pack
                # node, the aggregate and every limb it was cut into.
                pack_cells = _node_identity_cells(
                    target_wrapper, node_id, value_id, *leaves,
                )
                pack_book.post(
                    _SOURCE_PRECISION_PACK, pack_row, pack_fact,
                    stage=_REDUCTION, provenance=_Derived(pack_cells),
                    mode=_Mode.CONCORD,
                )
                _concord_source_precision_boundary(
                    scope, int(node_id), "pack", int(value_id),
                    precision_limbs=int(width), cells=pack_cells,
                )
                source_tensor = tensor_descriptor(int(leaves[0]))
                if source_tensor is not None:
                    publish_tensor(int(node_id), source_tensor)
        precision_flow_widths[int(node_id)] = int(width)
        seeded_tensor = tensor_descriptor(int(node_id))
        if seeded_tensor is not None:
            precision_flow_tensors[int(node_id)] = seeded_tensor
        changed = changed or prior != int(width)

    # Calls inside comprehensions return through LoopResult/tuple projection
    # nodes before the named value reaches arithmetic.  Those nodes are
    # structural carriers, not new numeric decisions.  Follow their exact
    # producer edges and refresh only values source reduction already proved
    # to be Precision; no unrelated value acquires a class here.
    for node_id, data in tuple(target.nodes(data=True)):
        identity, width = _resolved_source_value_class(target, int(node_id))
        if is_precision(identity) and int(width) > 1:
            precision_flow_widths[int(node_id)] = int(width)
            seeded_tensor = tensor_descriptor(int(node_id))
            if seeded_tensor is not None:
                precision_flow_tensors[int(node_id)] = seeded_tensor
    if os.environ.get("TURING_DEBUG_PRECISION_SPECIALIZATION"):
        for node_id, data in tuple(target.nodes(data=True)):
            if authored_scope not in {
                "compile_interpolant", "_wide_from_columns", "_pick_columns",
                "selected", "_locate_nearer_columns",
            }:
                break
            attributes = data.get("attributes") or {}
            expression = data.get("expr_obj")
            if (
                int(node_id) in precision_flow_widths
                or is_precision(attributes.get(
                    "result_class_ref", attributes.get("class_ref")
                ))
                or isinstance(expression, (ast.BinOp, ast.Call))
                or authored_scope == "selected"
                or authored_scope == "_locate_nearer_columns"
                or authored_scope == "_wide_from_columns"
                and int(node_id) in {51, 52, 58, 59, 60, 62, 66, 75}
            ):
                logger.warning(
                    "PRECISION-SPECIALIZATION scope=%s node=%s type=%s "
                    "class=%s width=%s flow=%s tensor=%r parents=%r "
                    "aggregate=%r binding=%r",
                    scope, node_id, data.get("type"),
                    attributes.get(
                        "result_class_ref", attributes.get("class_ref")
                    ), attributes.get("precision_limbs"),
                    precision_flow_widths.get(int(node_id)),
                    data.get("tensor"),
                    data.get("parents"),
                    attributes.get("aggregate_leaf_value_ids"),
                    attributes.get("binding_name"),
                )
                if (
                    authored_scope == "_wide_from_columns"
                    and int(node_id) in {
                        50, 51, 52, 59, 60, 62, 66, 75, 76, 77, 78, 79,
                        80, 81,
                    }
                    or authored_scope == "compile_interpolant"
                    or authored_scope == "_locate_nearer_columns"
                ):
                    logger.warning(
                        "PRECISION-SPECIALIZATION-DETAIL scope=%s node=%s "
                        "attributes=%r parents=%r children=%r expression=%s",
                        scope, node_id, attributes, data.get("parents"),
                        data.get("children"),
                        ast.dump(expression, include_attributes=False)
                        if isinstance(expression, ast.AST) else None,
                    )
    propagated = True
    while propagated:
        propagated = False
        for node_id, data in tuple(target.nodes(data=True)):
            parent_widths = tuple(
                precision_flow_widths[int(parent)]
                for parent, _role in data.get("parents", ())
                if int(parent) in precision_flow_widths
            )
            if not parent_widths:
                continue
            parent_tensors = tuple(
                precision_flow_tensors[int(parent)]
                for parent, _role in data.get("parents", ())
                if int(parent) in precision_flow_tensors
                and tuple(
                    precision_flow_tensors[int(parent)].get("shape") or ()
                )
            )
            width = max(parent_widths)
            if precision_flow_widths.get(int(node_id), 1) < width:
                precision_flow_widths[int(node_id)] = int(width)
                propagated = True
            if parent_tensors and int(node_id) not in precision_flow_tensors:
                selected_tensor = max(
                    parent_tensors,
                    key=lambda item: len(tuple(item.get("shape") or ())),
                )
                precision_flow_tensors[int(node_id)] = copy.deepcopy(
                    selected_tensor
                )
                propagated = True
            attributes = data.setdefault("attributes", {})
            class_identity = attributes.get(
                "result_class_ref", attributes.get("class_ref")
            )
            if not is_precision(class_identity):
                continue
            prior = int(attributes.get("precision_limbs") or 1)
            if prior == width:
                continue
            attributes["precision_limbs"] = int(width)
            attributes["result_class_ref"] = str(class_identity)
            if int(node_id) in precision_flow_tensors:
                publish_tensor(
                    int(node_id), precision_flow_tensors[int(node_id)]
                )
            # DERIVED from the value, the producers whose width flowed into
            # it, and the value's own class cell the class was read from.
            _concord_source_value_class(
                scope, int(node_id), str(class_identity),
                precision_limbs=int(width),
                source="callsite-specialized Precision producer flow",
                provenance=_Derived(_source_cells((
                    *_node_identity_cells(target_wrapper, node_id, *(
                        int(parent) for parent, _role in data.get("parents", ())
                        if int(parent) in precision_flow_widths
                    )),
                    current_identity_book().latest_ref(
                        _SOURCE_VALUE_CLASS, (scope, int(node_id)),
                    ),
                ))),
            )
            changed = True

    operator_page = current_identity_book().page(_SOURCE_PRECISION_OPERATOR)
    settled = True
    while settled:
        settled = False
        for node_id, data in tuple(target.nodes(data=True)):
            expression = data.get("expr_obj")
            if not isinstance(expression, (ast.BinOp, ast.UnaryOp)):
                continue
            parents = {
                str(role): int(parent)
                for parent, role in data.get("parents", ())
                if int(parent) in target
            }
            operand_ids = (
                (parents.get("lhs"), parents.get("rhs"))
                if isinstance(expression, ast.BinOp)
                else (parents.get("operand"),)
            )
            if any(value_id is None for value_id in operand_ids):
                continue
            descriptors = tuple(
                (
                    ("Precision", precision_flow_widths[int(value_id)])
                    if int(value_id) in precision_flow_widths
                    else _resolved_source_value_class(
                        target, int(value_id)
                    )
                )
                for value_id in operand_ids
            )
            precision = tuple(
                descriptor for descriptor in descriptors
                if is_precision(descriptor[0])
            )
            if not precision:
                continue
            width = max(descriptor[1] for descriptor in precision)
            operation = _qualified_handler(
                "binop" if isinstance(expression, ast.BinOp) else "unaryop",
                expression.op,
                limbs=width,
            )
            class_identity = str(precision[0][0])
            attributes = data.setdefault("attributes", {})
            prior = (
                str(data.get("op") or data.get("type")),
                int(attributes.get("precision_limbs") or 1),
            )
            data["type"] = operation
            data["op"] = operation
            attributes.update({
                "python_precision_operator": True,
                "precision_limbs": int(width),
                "result_class_ref": class_identity,
            })
            operand_tensors = tuple(
                precision_flow_tensors.get(int(value_id))
                or tensor_descriptor(int(value_id))
                for value_id in operand_ids
            )
            shaped_operands = tuple(
                descriptor for descriptor in operand_tensors
                if isinstance(descriptor, Mapping)
                and tuple(descriptor.get("shape") or ())
            )
            if shaped_operands:
                result_tensor = max(
                    shaped_operands,
                    key=lambda item: len(tuple(item.get("shape") or ())),
                )
                publish_tensor(int(node_id), result_tensor)
                precision_flow_tensors[int(node_id)] = copy.deepcopy(
                    result_tensor
                )
            # DERIVED from the operator, its operands and the operands'
            # class cells the Precision width was read from.
            _concord_source_value_class(
                scope, int(node_id), class_identity,
                precision_limbs=int(width),
                source="callsite-specialized Precision operator",
                provenance=_Derived(_source_cells((
                    *_node_identity_cells(
                        target_wrapper, node_id, *operand_ids,
                    ),
                    *(
                        current_identity_book().latest_ref(
                            _SOURCE_VALUE_CLASS, (scope, int(value_id)),
                        )
                        for value_id in operand_ids
                    ),
                ))),
            )
            precision_flow_widths[int(node_id)] = int(width)
            row = (scope, int(node_id))
            fact = (
                str(operation), int(operand_ids[0]), class_identity,
                int(width),
            )
            incumbent = operator_page.latest(row)
            if incumbent is not None and tuple(incumbent) != fact:
                raise ValueError(
                    "source precision operator concordance disagreement for "
                    f"{row!r}: recorded={incumbent!r}, proposed={fact!r}"
                )
            # The operation is read off the operator node and its operands.
            current_identity_book().post(
                _SOURCE_PRECISION_OPERATOR, row, fact, stage=_REDUCTION,
                provenance=_Derived(_node_identity_cells(
                    target_wrapper, node_id, *operand_ids,
                )),
                mode=_Mode.CONCORD,
            )
            now = (str(operation), int(width))
            if prior != now:
                settled = True
                changed = True

    for node_id, data in tuple(target.nodes(data=True)):
        expression = data.get("expr_obj")
        attributes = data.setdefault("attributes", {})
        boundary = attributes.get("python_precision_boundary")
        if (
            boundary is None
            and isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Attribute)
            and expression.func.attr == "collapse"
        ):
            boundary = "collapse"
        if not (
            isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Attribute)
            and boundary in {"promote", "collapse"}
        ):
            continue
        operand_id = next((
            int(parent) for parent, role in data.get("parents", ())
            if str(role) == "operand"
        ), None)
        if operand_id is None:
            continue
        if boundary == "promote":
            width = static_int(expression.args[1]) if (
                len(expression.args) >= 2
            ) else None
        else:
            _identity, width = _resolved_source_value_class(
                target, operand_id
            )
            if not is_precision(_identity):
                continue
        if width is None:
            continue
        prior = int(attributes.get("precision_limbs") or 1)
        attributes.update({
            "python_precision_boundary": str(boundary),
            "precision_limbs": int(width),
        })
        if boundary == "collapse":
            for field in (
                "callee_ref", "method_ref", "constructor_ref", "class_ref",
            ):
                attributes.pop(field, None)
            accessor_id = id(expression.func)
            if accessor_id in target:
                accessor_attributes = target.nodes[accessor_id].setdefault(
                    "attributes", {}
                )
                for field in (
                    "callee_ref", "method_ref", "bound_method_ref",
                ):
                    accessor_attributes.pop(field, None)
                accessor_attributes["python_precision_boundary"] = (
                    "collapse-selector"
                )
            data["type"] = "Cast"
            data["op"] = "Cast"
            _replace_inputs(
                target_wrapper, int(node_id), ((int(operand_id), "operand"),)
            )
        _concord_source_precision_boundary(
            scope, int(node_id), str(boundary), int(operand_id),
            precision_limbs=int(width),
            cells=_node_identity_cells(target_wrapper, node_id, operand_id),
        )
        changed = changed or prior != int(width)
    return changed


def _resolved_source_value_class(
    graph: Any,
    value_id: Any,
) -> tuple[str | None, int]:
    """What this value is: its concorded class and width, or unknown."""

    target = getattr(graph, "G", graph)
    if not isinstance(value_id, int) or value_id not in target:
        return None, 1
    fact = current_identity_book().page(
        "source_value_class_concordance"
    ).latest((_source_numeric_scope(target), int(value_id)))
    if not isinstance(fact, tuple) or len(fact) < 2:
        return None, 1
    return str(fact[0]), max(int(fact[1]), 1)


def _indexed_store_source(graph: Any, value_id: Any) -> Any:
    """The sequence an ``IndexedStore`` chain writes, by its ``base`` edges."""

    target = getattr(graph, "G", graph)
    seen: set[int] = set()
    while (
        isinstance(value_id, int)
        and value_id in target
        and value_id not in seen
        and target.nodes[value_id].get("type") == "IndexedStore"
    ):
        seen.add(value_id)
        value_id = next(
            (
                parent
                for parent, role in target.nodes[value_id].get("parents") or ()
                if role == "base"
            ),
            None,
        )
    return value_id


def _is_row_collection(graph: Any, value_id: Any) -> bool:
    """Whether a subscript base is a list or dict, which takes no array mask.

    Program: ``def bump(xs: list[int], n): for i in range(4): xs[i % 2] +=
    n`` with the caller reading its own list (corpus c375).  Wrong record:
    the annotated formal has no concorded class during reduction, so the
    masked-update rule rebound ``xs`` to a ``where`` value and the caller's
    list never changed (13 for -53, silently).  Rule: besides the concorded
    class, the formal's ``aggregate_kind`` (from its annotation) says it is
    a list.
    """

    target = getattr(graph, "G", graph)
    if _resolved_source_value_class(graph, value_id)[0] in {
        "builtins.list", "builtins.dict",
    }:
        return True
    if not isinstance(value_id, int) or value_id not in target:
        return False
    attributes = target.nodes[value_id].get("attributes") or {}
    return attributes.get("aggregate_kind") in {"list", "dict"}


def _concorded_numeric_descriptor(
    graph: Any, value_id: Any,
) -> NumericFeatureDescriptor | None:
    """What this numeral value is, from the concordance (or unknown)."""

    class_identity, limbs = _resolved_source_value_class(graph, value_id)
    if class_identity is None:
        return None
    return numeric_feature_descriptor(
        class_identity.rsplit(".", 1)[-1]
        + (f"[{int(limbs)}]" if int(limbs) > 1 else "")
    )


def _concord_numeric_feature_projection(
    scope: str,
    result_id: int,
    receiver_id: int,
    attribute: str,
    component_path: tuple[str, ...],
    descriptor: NumericFeatureDescriptor | None,
    *,
    cells: Iterable[Any],
) -> tuple[Any, ...]:
    """Commit one structural numeric field projection to the identity book.

    ``cells``: the identity cells of the projected result and its receiver
    (the caller's graph wrapper names them); the row is DERIVED from them.
    A same-fact re-post is CONCORD: the edge is recorded, no cell written.
    """

    book = current_identity_book()
    page = book.page(_SOURCE_NUMERIC_COMPONENT)
    row = (scope, int(result_id))
    fact = (
        int(receiver_id), str(attribute), tuple(map(str, component_path)),
        None if descriptor is None else descriptor.receipt(),
    )
    incumbent = page.latest(row)
    if incumbent is not None and tuple(incumbent) != fact:
        raise ValueError(
            "source numeric component concordance disagreement for "
            f"{row!r}: recorded={incumbent!r}, proposed={fact!r}"
        )
    book.post(
        _SOURCE_NUMERIC_COMPONENT, row, fact, stage=_REDUCTION,
        provenance=_Derived(_source_cells(cells)), mode=_Mode.CONCORD,
    )
    return fact


def _concord_source_precision_boundary(
    scope: str,
    value_id: int,
    boundary: str,
    operand_id: int,
    *,
    precision_limbs: int,
    cells: Iterable[Any],
) -> tuple[str, int, int]:
    """Commit one authored Precision boundary independently of graph copies.

    ``cells``: the identity cells of the boundary value and its operand (the
    caller's graph wrapper names them); the row is DERIVED from them.  A
    same-fact re-post is CONCORD: the edge is recorded, no cell written.
    """

    book = current_identity_book()
    page = book.page(_SOURCE_PRECISION_BOUNDARY)
    row = (scope, int(value_id))
    proposed = (
        str(boundary),
        int(operand_id),
        max(int(precision_limbs or 1), 1),
    )
    incumbent = page.latest(row)
    if incumbent is not None and tuple(incumbent) != proposed:
        raise ValueError(
            "source precision boundary concordance disagreement for "
            f"{row!r}: recorded={incumbent!r}, proposed={proposed!r}"
        )
    book.post(
        _SOURCE_PRECISION_BOUNDARY, row, proposed, stage=_REDUCTION,
        provenance=_Derived(_source_cells(cells)), mode=_Mode.CONCORD,
    )
    return proposed


def _concorded_static_parameter_bindings(
    definition: Any,
    parameter_names: tuple[str, ...],
) -> dict[str, Any]:
    """Return parameters whose discovered identity is compile-time static.

    Source pursuit has already bound a classmethod receiver to the class that
    Python supplies for that call.  That binding is the identity fact.  The
    reducer used to ignore it because the spelling also appeared in the
    authored parameter list, then separately interpreted the same class as a
    runtime RECORD contract.  Commit the discovered identity once so lexical
    resolution and storage classification consume the same decision.
    """

    if not isinstance(definition, (ast.FunctionDef, ast.AsyncFunctionDef)):
        return {}
    if not any(
        isinstance(decorator, ast.Name) and decorator.id == "classmethod"
        for decorator in definition.decorator_list
    ):
        return {}
    positional = (*definition.args.posonlyargs, *definition.args.args)
    if not positional:
        return {}
    receiver_name = str(positional[0].arg)
    if receiver_name not in parameter_names:
        return {}
    value = dict(getattr(definition, "_python_bindings", {}) or {}).get(
        receiver_name
    )
    if not inspect.isclass(value):
        return {}
    source_identity = getattr(definition, "_python_source_identity", None)
    scope = (
        tuple(map(str, source_identity))
        if isinstance(source_identity, tuple)
        else (str(getattr(definition, "name", "<function>")),)
    )
    descriptor = (
        "static_class",
        str(getattr(value, "__module__", "")),
        str(getattr(value, "__qualname__", getattr(value, "__name__", ""))),
    )
    book = current_identity_book()
    page = book.page(_SOURCE_PARAMETER_IDENTITY)
    row = (scope, receiver_name)
    incumbent = page.latest(row)
    if incumbent is not None and tuple(incumbent) != descriptor:
        raise ValueError(
            "source parameter identity concordance disagreement for "
            f"{scope!r}.{receiver_name}: recorded={incumbent!r}, "
            f"resolved={descriptor!r}"
        )
    # The binding is a fact of the authored parameter and of the class
    # pursuit bound it to: DERIVED from the parameter's ``source_span`` cell
    # and the class's ``static_symbol_definition`` cell.
    book.post(
        _SOURCE_PARAMETER_IDENTITY, row, descriptor, stage=_REDUCTION,
        provenance=_Derived(_source_cells((
            _post_source_span(positional[0]),
            _static_symbol_definition_cell(value),
        ))),
        mode=_Mode.CONCORD,
    )
    return {receiver_name: value}


def _known_parameter_memory_contracts(
    definition: Any,
    parameter_names: tuple[str, ...],
    *,
    method_owner: str | None,
    static_parameter_names: frozenset[str] = frozenset(),
) -> tuple[ParameterContract, ...]:
    """Describe parameter storage only when source pursuit proved its kind.

    The records direct raw SSA data; they do not create wrapper objects or
    runtime dispatch.  Once one parameter has a proven aggregate/record kind,
    the complete ordered signature is recorded so argument positions remain
    unambiguous.  Unproved parameters retain the scalar/value defaults.
    """

    bindings = dict(getattr(definition, "_python_bindings", {}) or {})
    storage_by_name: dict[str, ParameterStorage] = {}
    for index, name in enumerate(parameter_names):
        if name in static_parameter_names:
            continue
        value = bindings.get(name)
        if any(value is kind for kind in (list, set, dict, tuple)):
            storage_by_name[name] = ParameterStorage.TABLE
        elif inspect.isclass(value):
            storage_by_name[name] = ParameterStorage.RECORD
        elif index == 0 and method_owner is not None:
            storage_by_name[name] = ParameterStorage.RECORD
    if not storage_by_name:
        return ()
    return tuple(
        ParameterContract(
            name,
            transfer=(
                ParameterTransfer.ALIAS
                if name in storage_by_name
                else ParameterTransfer.VALUE
            ),
            access=(
                ParameterAccess.INOUT
                if name in storage_by_name
                else ParameterAccess.IN
            ),
            storage=storage_by_name.get(name, ParameterStorage.SCALAR),
            scope=(
                ParameterScope.CALLER
                if name in storage_by_name
                else ParameterScope.LOCAL
            ),
        )
        for name in parameter_names
    )


@dataclass(frozen=True)
class _StaticPythonReference:
    """Ephemeral resolved Python object; never emitted as a graph value.

    ``occurrence``: the authored AST expression whose resolution produced
    this reference (the use).  A StaticReference node is cached per object
    and shared by every use, so the node's row derives from the referenced
    definition and each use posts its own ``static_reference_use`` row from
    this occurrence (edges lane C).  Not part of equality."""

    value: Any
    path: str
    occurrence: Any = _dataclass_field(default=None, compare=False, hash=False)


def _static_symbol_definition_cell(target: Any) -> Any:
    """The ``static_symbol_definition`` cell of a compiler-only reference
    that is not a function-table entry, or ``None`` when the object declares
    no module and no name (edges lane C).

    The row is the object's own declared identity: ``(__module__,
    __qualname__, receiver)``, the receiver being the bound object's
    declared identity for a bound method (two receivers of one function are
    two symbols).  DERIVED from the book's row for the same definition when
    one exists (``backward_rule_definition`` for a helper compiled beside the
    rules, ``class_declaration`` for a class ingested from source); else the
    NOVEL(INGEST_SOURCE) root of an external declaration ingested by
    reference."""

    from ...compiler.concordance_declarations import (
        BACKWARD_RULE_DEFINITION, CLASS_DECLARATION, INGESTION, INGEST_SOURCE,
        STATIC_SYMBOL_DEFINITION, StaticSymbolFact, StaticSymbolKind,
    )
    from ...compiler.identity_concordance import Novel

    def declared(obj: Any) -> tuple[str, str] | None:
        if isinstance(obj, types.ModuleType):
            return (str(obj.__name__), "")
        module = getattr(obj, "__module__", None)
        if module is None:
            # A slot/method descriptor of a builtin class (``dict.keys``),
            # or a builtin classmethod bound to its class
            # (``dict.fromkeys``), declares no module of its own: it is
            # declared where its class is.
            owner_class = getattr(obj, "__objclass__", None)
            if owner_class is None:
                bound_to = getattr(obj, "__self__", None)
                if isinstance(bound_to, type):
                    owner_class = bound_to
                elif bound_to is not None and not isinstance(
                    bound_to, types.ModuleType,
                ):
                    # A builtin method bound to an instance (``"".join``)
                    # is declared where the instance's class is.
                    owner_class = type(bound_to)
            module = getattr(owner_class, "__module__", None)
        qualname = getattr(obj, "__qualname__", None) or getattr(
            obj, "__name__", None,
        )
        if not isinstance(module, str) or not isinstance(qualname, str):
            return None
        return (module, qualname)

    receiver = ""
    function = target
    descriptor_class = (
        getattr(target, "__objclass__", None)
        if isinstance(target, (
            types.MethodDescriptorType, types.WrapperDescriptorType,
            types.ClassMethodDescriptorType,
        )) else None
    )
    if inspect.ismethod(target) or (
        isinstance(target, types.BuiltinMethodType)
        and getattr(target, "__self__", None) is not None
        and not isinstance(target.__self__, types.ModuleType)
    ):
        bound = target.__self__
        bound_identity = declared(bound if isinstance(bound, type) else type(bound))
        receiver = "" if bound_identity is None else ".".join(bound_identity)
        function = getattr(target, "__func__", target)
    elif descriptor_class is not None:
        # An unbound method of a builtin class: its receiver is that class.
        bound_identity = declared(descriptor_class)
        receiver = "" if bound_identity is None else ".".join(bound_identity)
    identity = declared(function)
    if identity is None:
        return None
    if isinstance(target, types.ModuleType):
        kind = StaticSymbolKind.MODULE
    elif receiver:
        kind = StaticSymbolKind.BOUND_METHOD
    elif isinstance(target, type):
        kind = StaticSymbolKind.CLASS
    elif isinstance(target, types.FunctionType):
        kind = StaticSymbolKind.FUNCTION
    elif isinstance(target, types.BuiltinFunctionType):
        kind = StaticSymbolKind.BUILTIN
    else:
        kind = StaticSymbolKind.OTHER
    code = getattr(function, "__code__", None)
    digest = (
        hashlib.sha256(
            code.co_code + repr(tuple(code.co_names)).encode("utf-8")
        ).hexdigest()
        if isinstance(code, types.CodeType) else None
    )
    book = current_identity_book()
    row = (*identity, receiver)
    existing = book.latest_ref(STATIC_SYMBOL_DEFINITION, row)
    if existing is not None:
        return existing
    upstream = tuple(
        cell for cell in (
            book.latest_ref(BACKWARD_RULE_DEFINITION, identity),
            book.latest_ref(CLASS_DECLARATION, identity),
        )
        if cell is not None
    )
    return book.post(
        STATIC_SYMBOL_DEFINITION, row, StaticSymbolFact(kind, digest),
        stage=INGESTION,
        provenance=(
            _Derived(upstream) if upstream else Novel(INGEST_SOURCE, ())
        ),
        mode=_Mode.CONCORD,
    )


def _authored_node_cell(graph: Any, node: Any) -> Any:
    """The identity cell of the graph node that carries the authored AST
    ``node``: by the AST's id when the graph still keys nodes by it, else
    by the AST object the node's ``expr_obj`` holds (a function subgraph
    relabels its nodes but keeps the authored object).  ``None`` when no
    node carries it."""

    if not isinstance(node, ast.AST):
        return None
    if id(node) in graph.G:
        return node_identity_cell(graph, id(node))
    carrier = next((
        candidate for candidate, data in graph.G.nodes(data=True)
        if data.get("expr_obj") is node
    ), None)
    return None if carrier is None else node_identity_cell(graph, carrier)


def _occurrence_cell(graph: Any, occurrence: Any) -> Any:
    """The cell of an authored occurrence (the AST node a use resolved
    from): its posted ingestion / canonical cell, else its ``source_span``
    cell, else ``None``.  Never posts a fallback row."""

    if not isinstance(occurrence, ast.AST):
        return None
    cell = _posted_node_identity_cell(graph, id(occurrence))
    return cell if cell is not None else _post_source_span(occurrence)


def _reference_has_pursuable_source(value: Any) -> bool:
    """Whether a resolved Python object still has source to pursue into.

    This is the same test the frontend's pursuit
    (``graph_express2._source_ast_definition``) uses to decide the irreducible
    boundary: a function or class whose ``inspect.getsource`` succeeds is
    pursuable; a module, builtin, C-extension, or anything with no readable
    source is irreducible -- terminal. Kept here (not imported) so the reducer
    carries no dependency on the frontend module.
    """

    import inspect

    if inspect.ismethod(value):
        value = value.__func__
    if not (inspect.isfunction(value) or inspect.isclass(value)):
        return False
    try:
        inspect.getsource(value)
    except (OSError, TypeError):
        return False
    return True


# The export table: which graph node types are runnable definitions
# (functions/methods), and how to read each one's own name off it. Python's
# three cases are the built-in defaults; a foreign language's ingestion
# (oop_language_translations.py's install_c_role_schemas, for C's
# pycparser.c_ast.FuncDef, say) extends this the same way role_schemas
# itself is extended -- registering its own node-type name and a callable
# to read that type's own name field, rather than this reducer growing an
# isinstance branch per language. This is the frontend-side half of
# FunctionTable already being "shared function references for ProcessGraph
# and SSA compilation" (function_table.py's own docstring) -- the table was
# already meant to be language-neutral; only *populating* it was Python-AST-
# specific until this registry existed.
_RUNNABLE_DEFINITION_NAME_EXTRACTORS: dict[str, Callable[[Any], str]] = {
    "FunctionDef": lambda node: str(node.name),
    "AsyncFunctionDef": lambda node: str(node.name),
    "Lambda": lambda node: (
        f"<lambda:{getattr(node, 'lineno', 0)}:"
        f"{getattr(node, 'col_offset', 0)}>"
    ),
}


def register_runnable_definition_type(
    type_name: str, name_extractor: Callable[[Any], str],
) -> None:
    """Register a foreign language's function/method-definition node type.

    ``type_name`` is ``type(node).__name__`` for that language's own
    function-definition node class (``"FuncDef"`` for ``pycparser``, say).
    ``name_extractor`` reads that node's own name (``pycparser.c_ast.FuncDef``
    keeps it at ``node.decl.name``, not ``node.name``, so this cannot be one
    generic ``.name`` access across languages). Idempotent: re-registering
    the same type name overwrites, it does not duplicate or error.
    """

    _RUNNABLE_DEFINITION_NAME_EXTRACTORS[str(type_name)] = name_extractor


def is_runnable_definition(node: Any) -> bool:
    """Is ``node`` a registered function/method-definition node, in any
    registered language -- the export-table membership test."""

    return type(node).__name__ in _RUNNABLE_DEFINITION_NAME_EXTRACTORS


def runnable_definition_name(node: Any) -> str:
    """The name of a registered function/method-definition node."""

    return _RUNNABLE_DEFINITION_NAME_EXTRACTORS[type(node).__name__](node)


# Same export-table pattern, for the two other node shapes call/return
# ownership walking needs to recognize: a call, and a return-shaped node.
# "Return" is deliberately one shared key for every registered language
# rather than a per-language key -- pycparser's own Return node is *also*
# literally named "Return" (not a naming collision to route around, an
# actual shared vocabulary word both languages use for the same construct).
#
# The returned value itself is read from the graph's own dependency
# structure (a node's "value"/"expr" parent-edge role -- role_schemas'
# Return: {"up": {"value": 1}} for Python, {"up": {"expr": 1}} for C), never
# from the raw source node's own attributes. This is deliberate, not
# incidental: everywhere else this session resolved a value this way
# (ShellMemoryReference.base_node_id, _resolve_reference_node in
# glsl_deployment_strategy.py) it went through the graph's own parents/role
# edges, not getattr on expr_obj -- the graph is the abstract, language-
# neutral representation; the raw node is not, and reaching back into it
# here would just reintroduce a second, Python-shaped assumption
# (node.value vs node.expr) into code meant to be language-neutral.
_CALL_SHAPED_TYPE_NAMES: set[str] = {"Call"}
_RETURN_VALUE_ROLES: set[str] = {"value", "expr"}


def register_call_shaped_type(type_name: str) -> None:
    """Register a foreign language's call-expression node type name."""

    _CALL_SHAPED_TYPE_NAMES.add(str(type_name))


def register_return_value_role(role: str) -> None:
    """Register a foreign language's own parent-edge role name for "this is
    the value a return-shaped node returns" (role_schemas' own "up" key for
    that language's Return-equivalent node)."""

    _RETURN_VALUE_ROLES.add(str(role))


def source_child_nodes(node: Any) -> tuple[Any, ...]:
    """Every direct child of a source node, in any registered language.

    The one traversal primitive a language must supply. Python spells it
    ``ast.iter_child_nodes``; pycparser spells it ``node.children()``
    (yielding ``(role_name, child)`` pairs). Neither understands the other:
    ``ast.NodeVisitor.generic_visit`` requires ``node._fields``, which
    pycparser nodes do not have, which is why walking a C body with an
    ``ast`` visitor raises ``AttributeError: 'Decl' object has no attribute
    '_fields'`` rather than simply finding nothing.

    Dispatch is on the protocol the node actually implements, not on a
    registered type name, because that is what genuinely varies -- and it
    means a third frontend whose nodes are ``ast``-shaped or
    ``children()``-shaped needs no registration here at all.
    """

    if isinstance(node, ast.AST):
        return tuple(ast.iter_child_nodes(node))
    children = getattr(node, "children", None)
    if callable(children):
        return tuple(child for _role, child in children())
    return ()


def source_body_statements(definition: Any) -> tuple[Any, ...]:
    """The ordered statements making up a function definition's body.

    Python keeps them directly on ``FunctionDef.body``; C wraps them in a
    ``Compound`` whose ``block_items`` holds the list (and which may be
    ``None`` for an empty body).
    """

    body = getattr(definition, "body", None)
    if body is None:
        return ()
    if isinstance(body, list):
        return tuple(body)
    block_items = getattr(body, "block_items", None)
    if block_items is not None:
        return tuple(block_items)
    # A lambda-style single-expression body is itself the only statement.
    return (body,)


def source_walk(node: Any) -> tuple[Any, ...]:
    """``ast.walk`` for any registered language, via ``source_child_nodes``.

    Callers filter the result with ``isinstance`` against the constructs
    they care about. That stays correct for a foreign language rather than
    merely not crashing: C genuinely has no ``ast.ExceptHandler`` and no
    Python-style ``for``, so a scan for those legitimately finds nothing,
    which is the right answer and not a silent gap.
    """

    collected: list[Any] = []
    stack = [node]
    while stack:
        current = stack.pop()
        collected.append(current)
        stack.extend(source_child_nodes(current))
    return tuple(collected)


def _source_read_names(node: Any) -> set[str]:
    """Lexical loads, including AugAssign's syntactic Store/read operand."""
    # ``if add & mask: flags &= ~mask`` first reads flags at an AugAssign
    # target, whose AST context is Store. The old Load-only entry scan minted
    # flags inside the true arm; resetting that environment discarded the
    # update and minted a second flags Input at the return. All control entry
    # snapshots must include this read before either arm/iteration is reduced.
    members = source_walk(node)
    return {
        member.id for member in members
        if isinstance(member, ast.Name) and isinstance(member.ctx, ast.Load)
    } | {
        member.target.id for member in members
        if isinstance(member, ast.AugAssign) and isinstance(member.target, ast.Name)
    }


def _source_entry_names(node: Any) -> set[str]:
    """Names whose entry version a control statement can observe: the names
    it reads (``_source_read_names``) and the names it binds in its own
    scope.  A name bound in one arm or iteration merges with its entry
    version on the path that did not bind it."""
    # Program: ``def root(n, t): if n > 0: t = n * 2; return t + n`` (corpus
    # c390).  Wrong record: ``t`` is a parameter only rebound inside the arm,
    # so no Input was minted before the snapshot; the merge found no entry
    # version, built no Phi, dropped the arm's binding, and the return read
    # a parameter Input minted afterwards: 4 for n=3, t=1 (Python 9).  Rule:
    # a parameter a control statement binds exists from function entry, the
    # same as one it reads.  Nested function, class and lambda bodies and
    # comprehension targets bind their own scope, not this one.
    bound: set[str] = set()
    stack = [node]
    while stack:
        current = stack.pop()
        if current is not node and isinstance(
            current, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef),
        ):
            bound.add(current.name)
            continue
        if isinstance(current, ast.Lambda):
            continue
        if isinstance(current, ast.Name) and isinstance(current.ctx, ast.Store):
            bound.add(current.id)
        elif isinstance(current, (ast.Import, ast.ImportFrom)):
            bound.update(
                (alias.asname or alias.name).split(".")[0]
                for alias in current.names
            )
        elif isinstance(current, ast.ExceptHandler) and current.name:
            bound.add(current.name)
        children = source_child_nodes(current)
        if isinstance(current, ast.comprehension):
            children = tuple(
                child for child in children if child is not current.target
            )
        stack.extend(children)
    return _source_read_names(node) | bound


def function_parameter_names(definition: Any) -> tuple[str, ...]:
    """A function definition's declared parameter names, in order.

    Genuinely per-language grammar rather than shared vocabulary, so this
    is one of the few places a language really must be taught its own
    shape: Python hangs them off ``FunctionDef.args`` as ``arg`` nodes
    across three lists (positional-only, ordinary, keyword-only), while C
    reaches ``FuncDef -> decl -> type -> args.params`` to a list of
    ``Decl`` nodes whose ``.name`` is a plain string.
    """

    arguments = getattr(definition, "args", None)
    if arguments is not None and hasattr(arguments, "posonlyargs"):
        return tuple(
            argument.arg
            for argument in (
                *arguments.posonlyargs,
                *arguments.args,
                *arguments.kwonlyargs,
                *((arguments.vararg,) if arguments.vararg is not None else ()),
                *((arguments.kwarg,) if arguments.kwarg is not None else ()),
            )
        )
    declaration = getattr(definition, "decl", None)
    if declaration is not None:
        parameter_list = getattr(getattr(declaration, "type", None), "args", None)
        return tuple(
            str(parameter.name)
            for parameter in (getattr(parameter_list, "params", None) or ())
            if getattr(parameter, "name", None) is not None
        )
    return ()


def _record_owned_calls_and_returns(
    graph: Any,
    owner_reference: Any,
    function_node_id: int,
    call_owners: dict[int, Any],
    function_return_values: dict[int, list[int]],
) -> None:
    """Walk ``graph.G`` (not the raw source tree) to find every call/return
    belonging to the function at ``function_node_id``, stopping at any
    nested function/method-definition boundary -- the graph-based,
    language-neutral replacement for a source-tree ``ast.NodeVisitor`` walk,
    which cannot walk a foreign language's own node types at all (a
    ``pycparser`` node has no ``_fields`` attribute Python's
    ``ast.NodeVisitor.generic_visit`` requires). Bounded, not
    ``nx.ancestors``' full transitive closure: a nested definition's own
    calls/returns belong to *it*, not this enclosing function, the same
    rule the original visitor's ``visit_FunctionDef`` returning ``None``
    (not recursing) enforced.
    """

    visited: set[int] = set()
    stack = list(graph.G.predecessors(function_node_id))
    while stack:
        node_id = stack.pop()
        if node_id in visited or node_id not in graph.G:
            continue
        visited.add(node_id)
        data = graph.G.nodes[node_id]
        expression = data.get("expr_obj")
        if node_id != function_node_id and is_runnable_definition(expression):
            # A nested definition owns its own calls/returns; do not
            # descend into it from here.
            continue
        node_type = str(data.get("type"))
        if node_type in _CALL_SHAPED_TYPE_NAMES:
            call_owners[node_id] = owner_reference
        if node_type == "Return":
            # The returned value's own node id, read off the Return node's
            # graph-native parent edges (role "value" for Python, "expr" for
            # C) -- never off the raw source node's attributes. Already a
            # graph node id (an "up" edge's producer), not a raw object,
            # so it needs no id()/wrapping before use.
            value_node_id = next(
                (
                    parent_id
                    for parent_id, role in (data.get("parents") or ())
                    if str(role) in _RETURN_VALUE_ROLES
                ),
                None,
            )
            if value_node_id is not None:
                function_return_values.setdefault(
                    function_node_id, [],
                ).append(value_node_id)
        stack.extend(graph.G.predecessors(node_id))


# Source-language node type name -> the canonical SSA vocabulary spelling it
# universalizes to. The point of routing through the registry rather than
# hardcoding strings here is that a second language's own spelling for the
# same construct lands on the *same* canonical type: C's ``FuncCall`` and
# Python's ``Call`` both become "Call", so downstream passes see one
# vocabulary instead of one per frontend. Extend by registering the foreign
# spelling in ssa_registry.py (c_ssa_equivalents, say) and naming its node
# type here -- not by adding a branch downstream.
_AST_PROCESS_GRAPH_ALIASES = {
    "Name": ast_ssa_name_map["name"].value,
    "Assign": ast_ssa_name_map["assign"].value,
    "Call": ast_ssa_name_map["call"].value,
    # C (pycparser c_ast), joining the same canonical spellings above.
    # StructRef is C's field read (``self->value``), the same reading
    # Python's ``attribute:load`` has -- both are Load.
    "ID": c_ssa_name_map["id"].value,
    "Assignment": c_ssa_name_map["assignment"].value,
    "FuncCall": c_ssa_name_map["funccall"].value,
    "StructRef": c_ssa_name_map["structref"].value,
}

# C node types that exist only to spell out a *type*, carrying no runtime
# value of their own. Python's grammar has no equivalent (it is untyped at
# the syntax level), which is why this set has no Python counterpart --
# these are stripped for the same reason ast.Nonlocal/ast.Global are:
# compile-time syntax, not operations. ``Decl`` is deliberately NOT here --
# it carries both the declared name and its initializer, so it is a real
# binding event, not type machinery.
_C_COMPILE_TIME_SYNTAX = frozenset({
    "TypeDecl",
    "FuncDecl",
    "PtrDecl",
    "ArrayDecl",
    "IdentifierType",
    "ParamList",
    "Typedef",
    "Struct",
    "Union",
    "Enum",
})

_BITOPS_TO_EXECUTABLE = {
    # Bitwise operators resolve to their lowercase canonical executable names,
    # the ones every numeric table registers (``fused_ir.ELEMENTWISE_BINARY``,
    # ``canonical_elementwise_op``, the WASM/C/GLSL backends). Left as the bare
    # Handler names (``And``/``Or``/``Not``/``Shl``/``Shr``) they are recognized
    # only by the SymPy-spelling path in ``abstract_tensor_funcs`` and silently
    # drop out of any consumer keyed on the canonical set -- e.g. the structural
    # region builder ``dispatch_region_to_fused_program``. ``Xor`` was already
    # mapped; the rest were the asymmetry that made ``^`` reachable but ``&``,
    # ``|``, ``~``, ``<<``, ``>>`` not.
    "And": "bitand",
    "Or": "bitor",
    "Xor": "bitxor",
    "Not": "invert",
    "Shl": "shl",
    "Shr": "shr",
    "Neg": "neg",
    "Eq": "equal",
    "Ne": "not_equal",
    "Lt": "less",
    "Le": "less_equal",
    "Gt": "greater",
    "Ge": "greater_equal",
    "MatMul": "matmul",
    "LAnd": "logical_and",
    "LOr": "logical_or",
    "LNot": "logical_not",
}


#: Element types a precision operation can be emitted at, widest first. The
#: ORDER is the dispatch rule: where two operands disagree, the wider type
#: wins, because narrowing is a loss and a loss should be asked for rather
#: than inherited from whichever operand happened to be on the left.
PRECISION_ELEMENT_TYPES: tuple[tuple[str, str], ...] = (
    ("float64", "f64"),
    ("float32", "f32"),
    ("float16", "f16"),
)

#: Spellings that mean the same element type.
PRECISION_TYPE_ALIASES = {"double": "float64", "float": "float32",
                          "f64": "float64", "f32": "float32", "f16": "float16"}

#: Operations closed over the limb representation. A sum, difference,
#: product, quotient, square root, exponential, logarithm or negation of limbed
#: value, so each has a wider counterpart meaning the same thing. Nothing else
#: belongs: there
#: is no wider form of a reduction or a reshape that would be right, so those
#: keep their ordinary name and a destination refuses the operand rather than
#: reading its limbs as channels.
#: Spelled exactly as ``ast_ssa_name_map`` resolves them, which is not
#: uniform -- four are capitalised and ``neg`` is not, and there is no
#: ``truediv`` at this layer, only ``Div``. Keying on a tidied-up spelling
#: silently misses and falls through to the ordinary operation.
PRECISION_CLOSED_OPERATIONS = (
    "Add", "Sub", "Mul", "Div", "Sqrt", "Exp", "Log", "neg",
)

#: The greatest width represented in the legacy inspectable qualified-name
#: catalogue. Repository lowering consumes the singular operation plus its
#: explicit ``precision_limbs`` attribute and is not bounded by this table.
PRECISION_LIMB_LIMIT = 8


def _build_precision_operator_names() -> dict:
    """Every precision operator name, generated once at import.

    Built here rather than formatted at each call so the set of names a
    destination may receive is a fixed, inspectable table -- a backend can be
    checked against it, and a name that is not in it is a name nothing agreed
    to emit.
    """

    names = {}
    for operation in PRECISION_CLOSED_OPERATIONS:
        for element, tag in PRECISION_ELEMENT_TYPES:
            for limbs in range(2, PRECISION_LIMB_LIMIT + 1):
                names[(operation, element, limbs)] = (
                    f"{operation.lower()}_{tag}_p{limbs}_r{limbs}"
                )
    return names


#: (operation, element type, limbs) -> the name a destination implements.
#: NOT what ingestion plants. A specific name fixes an operating width and a
#: return width, and neither is known at the point an operand is read: fusion
#: may run a batch at a width no single operation had, and whether a result
#: stays limbed is a property of its CONSUMER, which does not exist yet. These
#: are computed from the surviving operations once planning has run.
PRECISION_OPERATOR_NAMES = _build_precision_operator_names()

#: What ingestion plants: one name per operation, carrying no width.
#: Enough for an identity to know which operation this is, and -- because
#: nothing downstream recognises it either -- enough to keep the node out of
#: the fusion planner's induced subgraph, which is what carries it intact.
PRECISION_SINGULAR_NAMES = {
    operation: f"precision_{operation.lower()}"
    for operation in PRECISION_CLOSED_OPERATIONS
}
PRECISION_PACK_NAME = "precision_pack"


def _widest_element(*declared: Optional[str]) -> Optional[str]:
    """The widest element type among the operands, or ``None`` if none say.

    Highest precision decides: an operation between a wide operand and a
    narrow one is emitted at the wide type, so meeting a narrower value never
    silently costs digits the caller already paid for.
    """

    order = {element: rank for rank, (element, _tag)
             in enumerate(PRECISION_ELEMENT_TYPES)}
    best, best_rank = None, len(order)
    for value in declared:
        if not value:
            continue
        element = PRECISION_TYPE_ALIASES.get(str(value), str(value))
        rank = order.get(element)
        if rank is not None and rank < best_rank:
            best, best_rank = element, rank
    return best


def _parameter_declaration(graph: Any, name: str) -> Optional[str]:
    """A parameter's declared type, when every function declaring it agrees.

    ``annotate_types`` captures annotated ASSIGNMENTS only -- its
    ``_TypeAnnotator`` has no visitor for ``ast.arg`` -- so a declaration
    written on a parameter never reaches ``type_annotations``. It is not
    lost, though: ``build_from_ast`` already unparses every parameter
    annotation into ``function_parameter_annotations``, keyed by function
    identity. This reads that rather than teaching the annotator a second
    way to learn the same fact.

    The walk does not carry which function it is inside, so a name is only
    honoured when every function that declares it declares it identically.
    Where two disagree the answer is None and the operand reads as ordinary
    -- a miss, never a wrong width, which is the right way round for
    something whose failure is silent.
    """

    try:
        by_function = graph.G.graph.get("function_parameter_annotations") or {}
    except AttributeError:
        return None
    declared = {
        str((parameters or {}).get(name))
        for parameters in by_function.values()
        if (parameters or {}).get(name)
    }
    return declared.pop() if len(declared) == 1 else None


def _operand_numeric_descriptor(
    graph: Any, node: ast.AST,
) -> NumericFeatureDescriptor | None:
    """An operand's complete declared numeric feature contract.

    The declaration is what the source says the value IS -- captured by
    ``annotate_types`` at ingestion and kept as ``type_annotations``. Parameter
    annotations use the exact spelling retained by ``build_from_ast``. The
    result describes every wrapper axis before an operator is chosen.

    An INDEXED operand is read through to the name it indexes: ``a[i]`` where
    ``a`` is declared carries ``a``'s width. Limbs are a channel in the last
    dimension, so subscripting an array of precision values selects one of
    them and does not consume that axis -- the element is as limbed as the
    array. Without this the declaration survives only on operands spelled as
    bare names, which excludes every kernel that walks an array, and the loss
    is silent: the operation simply lowers as ordinary arithmetic.
    """

    while isinstance(node, ast.Subscript):
        node = node.value
    if not isinstance(node, ast.Name):
        return None
    try:
        annotations = graph.G.graph.get("type_annotations") or {}
    except AttributeError:
        return None
    declared = annotations.get(node.id) or _parameter_declaration(
        graph, node.id
    )
    if not declared:
        return None
    descriptor = numeric_feature_descriptor(str(declared))
    if descriptor is not None:
        graph.G.graph.setdefault(
            "numeric_annotation_descriptors", {}
        )[str(declared)] = descriptor.receipt()
    return descriptor


def _operand_precision(graph: Any, node: ast.AST) -> tuple[int, Optional[str]]:
    """Compatibility view consumed by the established Precision pipeline."""

    descriptor = _operand_numeric_descriptor(graph, node)
    if descriptor is None or descriptor.features != frozenset({"precision"}):
        return 1, None
    return descriptor.limbs, descriptor.element_type


def _qualified_handler(prefix: str, operator: ast.AST, *, limbs: int = 1,
                       dtype: Optional[str] = None) -> str:
    """The operator's identity, singular-precision when an operand is limbed.

    Most limbs and highest precision decide what the operation IS; the caller
    passes what the operands declared and the widest of each governs. But the
    name planted here stays unspecific about width, because the width it is
    finally emitted at is not yet knowable -- fusion may batch it at a width
    no operand had, and whether it returns a limbed result depends on a
    consumer that does not exist at this point in the walk. The measured
    limbs and element type ride along as attributes for the pass that does
    know, once planning has settled which operations survived unfused.
    """

    spelling = f"{prefix}:{type(operator).__name__.lower()}"
    handler = ast_ssa_name_map.get(spelling)
    if handler is None:
        raise KeyError(f"no existing operator alias for {spelling!r}")
    canonical = _BITOPS_TO_EXECUTABLE.get(handler.value, handler.value)
    width = max(int(limbs or 1), 1)
    if width <= 1:
        return canonical
    return PRECISION_SINGULAR_NAMES.get(str(canonical), canonical)


def _c_qualified_handler(prefix: str, operator: str) -> str:
    """``_qualified_handler`` for C, whose operators are strings not classes.

    Python spells an operator as a child *node class* (``ast.Add``, hence
    ``binop:add``); pycparser spells it as a plain string attribute on the
    parent (``BinaryOp.op == '+'``, hence ``binaryop:+``). Two surface
    spellings, one canonical Handler -- which is the whole point of the
    registry, and why this returns the identical vocabulary
    ``_qualified_handler`` does rather than a parallel C-flavored one.
    """

    spelling = f"{prefix}:{str(operator).lower()}"
    handler = c_ssa_name_map.get(spelling)
    if handler is None:
        raise KeyError(f"no existing C operator alias for {spelling!r}")
    return _BITOPS_TO_EXECUTABLE.get(handler.value, handler.value)


def _c_constant_value(expression: Any) -> Any:
    """A ``pycparser`` Constant's real Python value.

    pycparser keeps every literal as the *source text* plus a type name
    (``Constant(type='int', value='10')`` -- the value is the string "10",
    not the integer 10). Downstream compiler stages treat ``data["constant"]``
    as a real value, so the conversion has to happen here, at the one place
    C literals are canonicalized, rather than being re-derived (or silently
    left as a string) at each consumer.
    """

    raw = str(getattr(expression, "value", ""))
    kind = str(getattr(expression, "type", ""))
    if "char" in kind:
        return raw.strip("'")
    if "string" in kind:
        return raw.strip('"')
    if "float" in kind or "double" in kind:
        return float(raw.rstrip("fFlL"))
    if "int" in kind:
        # C integer literals carry base prefixes and width/sign suffixes that
        # Python's int() will not accept directly (0x1FUL, 10u, 07).
        text = raw.rstrip("uUlL")
        return int(text, 0) if text else 0
    return raw


# The type given to a node standing in for something ingestion could not
# translate. Mangled data is mangled data: it needs a real, named, *non*
# operation rather than either a silent hole or a hard stop.
#
# This type name MUST NEVER be added to any operator table -- not
# ``operator_defs.operator_signatures``' executable entries, not
# ``graph_deep_compiler``'s ``op_table``, not ``ssa_webgpu_backend``'s
# ``_BINARY``/``_UNARY``, not ``fused_ir``'s ``ELEMENTWISE_*``. Its safety is
# structural, not a matter of anyone remembering to check: because no table
# maps it, every backend that meets it already reports it through that
# backend's own existing "no instruction for this" path. Nothing can quietly
# treat it as zero, which is the one line this repository does not cross --
# never silently produce a plausible wrong number.
#
# It is deliberately *one* generic type carrying free-text provenance, not a
# taxonomy of failure kinds. A closed enum of defect categories would need a
# central owner to admit every new construct a contributor or agent adds --
# exactly the bottleneck ``role_schemas``,
# ``_RUNNABLE_DEFINITION_NAME_EXTRACTORS`` and the ssa_registry spelling
# tables exist to remove. ``operator_signatures`` falls back to 'Default'
# for an unrecognized type, so a graph carrying these still finalizes and
# stays walkable; the translation simply reports how far it got.
UNTRANSLATED_NODE_TYPE = "Untranslated"


# How completely the affected construct survived translation. This is an
# ordered *scale*, not a taxonomy -- which is why it is a closed set where
# ``reason`` is deliberately free text. A scale has rungs that mean
# something relative to each other and can be compared and sorted; a
# taxonomy of failure kinds would need a central owner to admit every new
# construct a contributor or agent introduces, which is the bottleneck this
# module keeps removing. Add a rung only if it is genuinely between or
# beyond these, never to describe a new *kind* of failure.
#
# Nothing here is binary. A translation is not "worked" or "failed": it
# reached some depth and stopped, and how far it reached is the useful
# fact. ``complete`` on the backend artifacts is the cheapest summary of
# this scale, not a replacement for it.
TRANSLATION_ABSENT = "absent"      # nothing of the construct translated
TRANSLATION_PARTIAL = "partial"    # some constituents translated, some not
TRANSLATION_DEGRADED = "degraded"  # fully translated, reduced fidelity
TRANSLATION_UNKNOWN = "unknown"    # not determinable at this pass

TRANSLATION_GRADES = (
    TRANSLATION_ABSENT,
    TRANSLATION_PARTIAL,
    TRANSLATION_DEGRADED,
    TRANSLATION_UNKNOWN,
)


@dataclass(frozen=True)
class GraphTranslationShortfall:
    """One construct graph ingestion could not fully translate.

    Same contract the backend shortfall records already use
    (``WasmShortfall``, ``WGSLShortfall``): structured fields for the parts
    worth querying across many programs, and one free-text ``reason`` so
    reporting something new never requires extending a type. Recorded on
    ``graph.G.graph["translation_shortfalls"]``, alongside the existing
    ``state_machine_control_shortfalls``.

    ``grade`` carries how far the translation got, and ``observed``/
    ``expected`` the countable evidence behind that grade (operands
    resolved out of operands required, say). A reader deciding whether a
    specimen is solid enough to reason about needs the degree, not just the
    fact -- and a caller aggregating across many programs needs the counts,
    not a prose summary of them.
    """

    pass_name: str
    node_id: int
    operation: str
    role: str
    source_span: str
    reason: str
    grade: str = TRANSLATION_UNKNOWN
    observed: int = 0
    expected: int = 0

    @property
    def coverage(self) -> float | None:
        """Fraction of the construct that translated, when countable."""

        if self.expected <= 0:
            return None
        return self.observed / self.expected

    def format(self) -> str:
        where = f" at {self.source_span}" if self.source_span else ""
        role = f" ({self.role})" if self.role else ""
        ratio = (
            f" [{self.observed}/{self.expected}]" if self.expected else ""
        )
        return (
            f"{self.pass_name}: {self.operation}{role}{where} "
            f"<{self.grade}{ratio}>: {self.reason}"
        )


# Cap on a folded sequence, so `[0] * 10**9` is refused rather than
# materialized. A refused fold is not a failure: it falls through to the
# ordinary path and reports itself there like anything else.
_MAX_FOLDED_SEQUENCE_ELEMENTS = 1 << 20


def _static_sequence_literal(expression: Any) -> Any:
    """Fold literal sequence replication (``[0] * 256``) to its value.

    Returns the folded list, or ``None`` when this is not that construct.

    ``[0] * 256`` is **Python list replication, not arithmetic** -- but the
    AST spells it ``BinOp(op=Mult)``, so canonicalization would otherwise
    rewrite it into a ``Mul`` dataflow operation that was never arithmetic.
    Its operands are not in the graph either (a literal list inside a
    comprehension is never descended into), so the ``Mul`` ends up with two
    absent operands.

    This is compile-time table allocation -- the shape a decoder's lookup
    tables are declared in -- and its value is knowable now, so it becomes
    constant data. Only the both-operands-literal case folds; anything
    depending on a runtime value is left alone.
    """

    if not isinstance(expression, ast.BinOp) or not isinstance(
        expression.op, ast.Mult
    ):
        return None
    for sequence_node, count_node in (
        (expression.left, expression.right),
        (expression.right, expression.left),
    ):
        if not isinstance(sequence_node, (ast.List, ast.Tuple)):
            continue
        try:
            sequence = ast.literal_eval(sequence_node)
            count = ast.literal_eval(count_node)
        except (ValueError, TypeError, SyntaxError, MemoryError):
            return None
        if isinstance(count, bool) or not isinstance(count, int):
            return None
        if count < 0:
            return None
        if len(sequence) * count > _MAX_FOLDED_SEQUENCE_ELEMENTS:
            return None
        return list(sequence) * count
    return None


def _source_span(expression: Any) -> str:
    line = getattr(expression, "lineno", None)
    if line is None:
        return ""
    column = getattr(expression, "col_offset", None)
    return f"line {line}" + (f":{column}" if column is not None else "")


def record_translation_shortfall(
    graph: Any,
    *,
    pass_name: str,
    node_id: int,
    operation: str,
    reason: str,
    role: str = "",
    source_span: str = "",
    grade: str = TRANSLATION_UNKNOWN,
    observed: int = 0,
    expected: int = 0,
) -> None:
    """Accumulate one graph-level shortfall instead of raising.

    Ingestion reports the way the backends already do -- a partial
    translation is a real, inspectable result, not a failure. Raising here
    would surface exactly one defect per run of a multi-minute build, when
    the same run could have named every one of them.
    """

    existing = graph.G.graph.get("translation_shortfalls") or ()
    graph.G.graph["translation_shortfalls"] = (
        *existing,
        GraphTranslationShortfall(
            pass_name=str(pass_name),
            node_id=int(node_id),
            operation=str(operation),
            role=str(role),
            source_span=str(source_span),
            reason=str(reason),
            grade=str(grade),
            observed=int(observed),
            expected=int(expected),
        ),
    )


_first = operator.itemgetter(0)
_second = operator.itemgetter(1)


#: Book pages whose facts name an operand position ``(role, ordinal)`` of a
#: consumer node.  A position is an identity: when a node's operand list is
#: rewritten, every one of these follows the operand to its new position.
#: ``lexical_read_binding`` rows are ``(scope, consumer, role, ordinal) ->
#: binding``; ``consumer_operand`` rows are ``(scope, consumer, value) ->
#: ((role, ordinal), ...)``.
_OPERAND_POSITION_ROW_PAGES = ("lexical_read_binding",)
_OPERAND_POSITION_FACT_PAGES = ("consumer_operand",)


def _operand_position_scope(graph: Any) -> Any:
    """The book scope this graph's operand-position rows are keyed in."""

    graph_data = getattr(getattr(graph, "G", None), "graph", None) or {}
    scope = graph_data.get("operand_position_scope")
    if scope is None:
        scope = graph_data.get("lexical_read_scope")
    if scope is None:
        # Step 9 (plan 100, 1.1): an edge ``build_from_ast`` writes before
        # any reduction is keyed in the build's ingestion scope -- the
        # scope ``ensure_node`` posted the nodes under.  The canonical
        # relabel moves these rows to the read scope with every other
        # operand-position row.
        scope = graph_data.get("ingestion_value_scope")
    return None if scope is None else tuple(scope)


#: The scope an operand rewrite is tagged under when its graph has none
#: (neither built by ``build_from_ast`` nor entered normalization): the
#: ``Unsourced(NO_OPERAND_POSITION_SCOPE)`` row of plan 70 section 3.
_UNSCOPED_OPERANDS = ("unscoped_operands", 0)


#: A parent with this many ``children`` is indexed by consumer id; fewer are
#: scanned, which is cheaper than keeping an index.
_CHILD_INDEX_MIN = 32
#: ``G -> {parent: (children list, {consumer id: entries}, len)}``: how many
#: ``children`` entries of a hub name each consumer, so appending a consumer
#: to a parent with C children does not rescan the C.  An entry is trusted
#: only while it describes the list now in ``children`` (same object, same
#: length); every ``children`` write here replaces the list, so a write
#: anywhere else (or an in-place append) just makes the index rebuild.
_CHILD_INDEX: "weakref.WeakKeyDictionary[Any, dict]" = weakref.WeakKeyDictionary()


def _child_counts(G: Any, parent: Any, children: Any) -> dict | None:
    """The ``{consumer id: entries}`` index of ``children`` (a list of
    ``(consumer, role)``), kept per graph and parent; None if unindexable."""

    try:
        per_graph = _CHILD_INDEX.get(G)
        if per_graph is None:
            per_graph = _CHILD_INDEX[G] = {}
        entry = per_graph.get(parent)
        if entry is not None and entry[0] is children and entry[2] == len(children):
            return entry[1]
        counts: dict = {}
        for child in children:
            counts[child[0]] = counts.get(child[0], 0) + 1
        per_graph[parent] = (children, counts, len(children))
        return counts
    except TypeError:
        return None


def _materialize_operands(
    graph: Any,
    node_id: Any,
    old_parents: Any,
    parents: Any,
    edge_payload: Mapping[str, Any] | None,
    *,
    tail_from: int | None = None,
) -> None:
    """Make ``children`` and the networkx edges agree with ``parents``.

    The operand list is the fact (``identity_transition``); ``parents``,
    ``children`` and ``graph.G.edges`` are its three materializations and
    ``_set_operands`` writes all three (plan 100, 1.1).  For every parent
    that left the list its ``children`` entries naming this consumer and
    the edge go; for every parent in the list the edge exists (its ``role``
    is the parent's first role here) and ``children`` holds exactly one
    ``(consumer, role)`` per role, stale role spellings replaced in place
    so sibling order is kept.  A parent that is not a node is skipped:
    networkx would create it (see ``_replace_inputs``).

    ``tail_from`` is the caller's word that ``parents[:tail_from]`` is
    ``old_parents`` unchanged (``_set_operands`` checks it) and that those
    parents are already materialized: only the operands from ``tail_from``
    on are written, so appending to an N-operand list costs the appended
    operands, not N.  It applies when no appended operand is already an
    operand; otherwise the whole list is written as usual.
    """

    G = graph.G
    if tail_from is not None:
        known = set(map(_first, old_parents))
        if any(parent in known for parent, _role in parents[tail_from:]):
            tail_from = None
    by_parent: dict[Any, list[Any]] = {}
    for parent, role in (parents if tail_from is None else parents[tail_from:]):
        roles = by_parent.setdefault(parent, [])
        if role not in roles:
            roles.append(role)
    for parent in (
        () if tail_from is not None
        else dict.fromkeys(parent for parent, _role in old_parents)
    ):
        if parent in by_parent or parent not in G:
            continue
        parent_data = G.nodes[parent]
        if parent_data.get("children"):
            parent_data["children"] = [
                child for child in parent_data["children"]
                if child[0] != node_id
            ]
        if G.has_edge(parent, node_id):
            G.remove_edge(parent, node_id)
    payload_items = tuple(dict(edge_payload or {}).items())
    for parent, roles in by_parent.items():
        if parent not in G:
            continue
        if G.has_edge(parent, node_id):
            G.edges[parent, node_id]["role"] = roles[0]
        else:
            # A set in the payload is per edge: parents added by one call
            # must not share it (``extra`` collects each edge's own records).
            G.add_edge(parent, node_id, role=roles[0], **{
                key: (set(value) if isinstance(value, set) else value)
                for key, value in payload_items
            })
        parent_data = G.nodes[parent]
        stored = parent_data.get("children")
        if isinstance(stored, list) and len(stored) >= _CHILD_INDEX_MIN:
            counts = _child_counts(G, parent, stored)
            if counts is not None and not counts.get(node_id):
                # This consumer has no entry under the parent: they all go
                # at the end, as the rebuild below would put them.
                rebuilt = [*stored, *((node_id, role) for role in roles)]
                parent_data["children"] = rebuilt
                counts[node_id] = len(roles)
                _CHILD_INDEX[G][parent] = (rebuilt, counts, len(rebuilt))
                continue
        children = list(stored or ())
        present = [tuple(child) for child in children if child[0] == node_id]
        if (
            len(present) == len(roles)
            and {child[1] for child in present} == set(roles)
        ):
            continue
        pending = list(roles)
        rebuilt: list = []
        for child in children:
            if child[0] != node_id:
                rebuilt.append(child)
            elif child[1] in pending:
                pending.remove(child[1])
                rebuilt.append(child)
            elif pending:
                rebuilt.append((node_id, pending.pop(0)))
        rebuilt.extend((node_id, role) for role in pending)
        parent_data["children"] = rebuilt


def _set_operands(
    graph: Any,
    node_id: Any,
    parents: Any,
    *,
    cause: str | _Transform,
    same: Mapping[Any, Any] | None = None,
    fork_from: Mapping[tuple[Any, int], tuple[Any, ...]] | None = None,
    edge_payload: Mapping[str, Any] | None = None,
    materialize: bool = True,
    append_only: bool = False,
) -> None:
    """The one writer of a node's operand list, recorded on the book.

    ``cause`` names the rewrite that changed the list: a registered
    ``Transform`` (its name is recorded) or, for callers not yet migrated,
    the legacy string.  Plan 70 section 3 has every append/move/retire/fork
    posted through ``IdentityBook.post`` on page ``identity_transition``
    (declared by step 5; the Append post landed with step 9, plan 100 1.2):
    a new position with no move source and no fork is
    ``OperandAppend(cause, operand)`` DERIVED(operand node cell, consumer
    node cell); a graph with no operand-position scope posts one
    ``Unsourced(NO_OPERAND_POSITION_SCOPE)`` row per rewrite under
    ``_UNSCOPED_OPERANDS``, which the audit lists.

    Step 9 also makes this the writer of the other two copies of every
    operand edge: ``children`` on the parents and the networkx edge
    (``_materialize_operands``).  ``edge_payload`` is extra edge data for
    a new edge (``build_from_ast``'s ``extra`` set); ``materialize=False``
    is for the canonical relabel only, whose edges are already relabeled
    by ``add_edges_from`` while this call moves the rows.  ``append_only``
    is the caller's word that it adds operands at the end of a list whose
    other operands are already materialized (authoring an edge);
    the call checks the list really is the old one plus a tail and, if
    so, writes only the tail -- no earlier position can have moved -- so
    authoring a node's N operands one by one is O(N) in all, not O(N^2).
    A list that is not old-plus-tail takes the general path.

    Facts keyed by an operand position (the binding one operand read, see
    ``_OPERAND_POSITION_ROW_PAGES``) must name the same operand after any
    rewrite.  A rewrite that renames roles (a call rebuilt from ``args`` to
    ``arg:0``), drops an operand (shifting later ordinals of its role) or
    swaps the operand's id (``same``: old parent id -> new parent id) moves
    positions.  Old and new positions are paired by operand identity, in
    order, so one value read at two positions pairs position by position.

    Every change is one operator on page ``identity_transition``, row
    ``(scope, consumer, role, ordinal)`` of the position it acts on:
    ``("move", consumer, new role, new ordinal, cause)``, ``("retire",
    None, None, None, cause)`` when the operand left the list, and at the
    new position ``("fork", source node, source role, source ordinal,
    cause)`` for ``fork_from`` -- a new position fed by an occurrence whose
    read was committed at another node's position (a method call's
    receiver, read first by its attribute load).  Every position-keyed page
    follows.  A vacated position with no successor is revised to None, so a
    later operand that shifts into it never inherits another's fact.

    Found by: ``AbstractTensor.minimum(dt_cap, remainder)`` inside
    ``run_superstep``'s while loop.  The read of ``dt_cap`` was committed at
    ``(call, 'args', 0)``; ``_replace_inputs`` then rebuilt the call's
    operands as ``arg:0``/``arg:1`` and the control lowering, reading
    ``(call, 'arg:0', 0)``, found no binding for a carried value.
    """

    if node_id not in graph.G:
        return
    data = graph.G.nodes[node_id]
    old_parents = list(data.get("parents") or ())
    parents = list(parents)
    prefix = len(old_parents)
    tail_only = bool(
        append_only and not same and not fork_from
        and parents[:prefix] == old_parents
    )
    data["parents"] = parents
    if materialize:
        _materialize_operands(
            graph, node_id, old_parents, parents, edge_payload,
            tail_from=prefix if tail_only else None,
        )
    scope = _operand_position_scope(graph)
    if tail_only:
        # Old positions are untouched; only the tail's positions are new.
        old = []
        new = []
        seen = collections.Counter(map(_second, old_parents))
        tail_positions = []
        for parent_id, role in parents[prefix:]:
            ordinal = seen[role]
            seen[role] = ordinal + 1
            tail_positions.append((role, ordinal, parent_id))
    else:
        old = list(_operand_positions(old_parents))
        new = list(_operand_positions(parents))
    cause_name = cause.name if isinstance(cause, _Transform) else str(cause)
    if scope is None:
        if (not tail_positions) if tail_only else new == old:
            return
        raise ValueError(
            f"identity_transition: no source cell for node {node_id} -- "
            "the operand rewrite was made with no operand-position scope"
        )
    renamed = dict(same or {})
    taken: set[int] = set()
    moves: dict[tuple[Any, int], tuple[Any, int] | None] = {}
    forks: dict[tuple[Any, int], tuple[Any, ...]] = {}
    if tail_only:
        # Every old operand keeps its position (an identity move, which
        # posts nothing); the tail's positions are the appends.
        appends = tail_positions
    else:
        # Candidate new positions per parent value, ascending: matching an
        # old operand scans only the positions that hold ITS value, not
        # every operand of the node (the all-pairs scan made a node with N
        # operands cost ~N^3).
        new_by_parent: dict[Any, list[int]] = {}
        for index, (_new_role, _new_ordinal, new_parent) in enumerate(new):
            new_by_parent.setdefault(new_parent, []).append(index)
        for role, ordinal, parent in old:
            target = renamed.get(parent, parent)
            match = None
            candidates = new_by_parent.get(target, ())
            # The same role first: an unmoved operand keeps its position
            # even when its value also appears at another position.
            for index in candidates:
                if index not in taken and new[index][0] == role:
                    match = index
                    break
            if match is None:
                for index in candidates:
                    if index not in taken:
                        match = index
                        break
            if match is None:
                moves[(role, ordinal)] = None
                continue
            taken.add(match)
            moves[(role, ordinal)] = (new[match][0], new[match][1])
        new_positions = {(role, ordinal) for role, ordinal, _parent in new}
        forks = {
            position: source
            for position, source in dict(fork_from or {}).items()
            if position in new_positions
        }
        # An Append: a new position no old position moved into and no fork
        # feeds (plan 70 section 3; plan 100 1.2).
        occupied = {target for target in moves.values() if target is not None}
        appends = [
            (role, ordinal, parent)
            for role, ordinal, parent in new
            if (role, ordinal) not in occupied and (role, ordinal) not in forks
        ]
    if not forks and not appends and all(
        source == target for source, target in moves.items()
    ):
        return
    from ...compiler.concordance_declarations import (
        IDENTITY_TRANSITION, LEXICAL_READ_BINDING, OPERAND_FORK, OPERAND_MOVE,
        OPERAND_POSITION, OPERAND_POSITION_VACATED, OPERAND_RETIRE,
        OperandAppend, OperandFork, OperandMove, OperandRetire,
    )
    from ...compiler.identity_concordance import Novel as _Novel

    cause = cause_name
    book = current_identity_book()
    transition_page = book.page(IDENTITY_TRANSITION)
    read_page = book.page(LEXICAL_READ_BINDING)
    consumer_cell = node_identity_cell(graph, node_id)

    def position_cell(consumer: Any, role: Any, ordinal: Any) -> Any:
        """The cell that records an operand position: its latest
        ``identity_transition`` cell, else its ``lexical_read_binding``
        cell, else the consumer node's identity cell."""

        for page in (IDENTITY_TRANSITION, LEXICAL_READ_BINDING):
            cell = book.latest_ref(page, (scope, consumer, role, ordinal))
            if cell is not None:
                return cell
        return consumer_cell

    def post_transition(row: tuple, fact: Any, transform: Any, operand: Any) -> Any:
        """One operator on ``identity_transition``: NOVEL(transform,
        (operand cell,)) on a row with no NEW -- the origin edge names what
        the position was moved, retired or forked from (plan 70, section 3;
        plan 80 B1.3)."""

        return book.post(
            IDENTITY_TRANSITION, row, fact,
            stage=OPERAND_POSITION,
            provenance=_Novel(transform, (operand,)),
            mode=_Mode.REVISE,
        )

    transitions: dict[tuple, Any] = {}
    for (role, ordinal), target in moves.items():
        if target == (role, ordinal):
            continue
        row = (scope, node_id, role, ordinal)
        operand = position_cell(node_id, role, ordinal)
        if target is None:
            transitions[(role, ordinal)] = post_transition(
                row, OperandRetire(cause), OPERAND_RETIRE, operand,
            )
        else:
            transitions[(role, ordinal)] = post_transition(
                row, OperandMove(cause, node_id, *target), OPERAND_MOVE, operand,
            )
    for (role, ordinal), source in forks.items():
        transitions[(role, ordinal)] = post_transition(
            (scope, node_id, role, ordinal), OperandFork(cause, *source),
            OPERAND_FORK, position_cell(*source),
        )
    for role, ordinal, parent in appends:
        if parent not in graph.G:
            # An operand that is not a node has no cell (``_replace_inputs``
            # stands an UNTRANSLATED node in for it before calling here).
            continue
        row = (scope, node_id, role, ordinal)
        # A position that existed before (retired, then fed again) derives
        # from its previous cell too: the history is one row, and the new
        # source set is what admits the revision.
        previous = book.latest_ref(IDENTITY_TRANSITION, row)
        transitions[(role, ordinal)] = book.post(
            IDENTITY_TRANSITION, row, OperandAppend(cause, parent),
            stage=OPERAND_POSITION,
            provenance=_Derived(tuple(
                cell for cell in (
                    node_identity_cell(graph, parent), consumer_cell, previous,
                )
                if cell is not None
            )),
            mode=_Mode.REVISE,
        )
    # A position that keeps its place (an identity move) carries its own
    # fact to itself: nothing to read, nothing to write -- unless a fork
    # also feeds that position, where "already has a fact" decides.  Only
    # positions that move (or are forked into) have their rows read, once.
    moved_sources = {
        source: target for source, target in moves.items()
        if target != source or source in forks
    }
    # The transition cell of the move INTO each position (targets are unique).
    arrived_from = {
        moved_to: source for source, moved_to in moves.items()
        if moved_to is not None and source in transitions
    }
    for name in _OPERAND_POSITION_ROW_PAGES:
        page = book.page(name)
        facts = {
            source: page.latest((scope, node_id, *source))
            for source in moved_sources
        }
        arriving = {
            target: facts[source]
            for source, target in moved_sources.items()
            if target is not None and facts[source] is not None
        }
        for target, source in forks.items():
            fact = page.latest((scope, *source))
            if fact is not None and target not in arriving:
                arriving[target] = fact
        for source, fact in facts.items():
            if fact is not None and source not in arriving:
                # The vacated position: an ``Unresolved`` revision (readers
                # take it as absence) DERIVED from the transition (move,
                # retire) that vacated it -- every moved source has one
                # above.
                vacated_by = transitions[source]
                book.post(
                    book.registry.page(name), (scope, node_id, *source),
                    _Unresolved(OPERAND_POSITION_VACATED, read=(vacated_by,)),
                    stage=OPERAND_POSITION,
                    provenance=_Derived((vacated_by,)),
                    mode=_Mode.REVISE,
                )
        for target, fact in arriving.items():
            if page.latest((scope, node_id, *target)) != fact:
                # The arriving fact derives from the position's transition
                # cell (the move's source position, or the fork's target),
                # whatever the fact's type (a str binding or an Unresolved
                # carried along); a position nothing moved into has no
                # arrival to record.
                cause_cell = (
                    transitions[arrived_from[target]]
                    if target in arrived_from else transitions.get(target)
                )
                if cause_cell is None:
                    raise ValueError(
                        f"{name}: operand position {(scope, node_id, *target)!r} "
                        "receives a fact with no transition into it"
                    )
                book.post(
                    book.registry.page(name), (scope, node_id, *target), fact,
                    stage=OPERAND_POSITION,
                    provenance=_Derived((cause_cell,)),
                    mode=_Mode.REVISE,
                )
    # Positions that all keep their place and operands that keep their id
    # leave every ``(scope, consumer, value)`` row as it is.
    positions_moved = (
        any(renamed.get(parent, parent) != parent for _r, _o, parent in old)
        if renamed else False
    ) or any(target != source for source, target in moves.items())
    for name in _OPERAND_POSITION_FACT_PAGES:
        page = book.page(name)
        if not positions_moved:
            continue
        declared = book.registry.page(name)
        for _role, _ordinal, parent in old:
            row = (scope, node_id, parent)
            positions = page.latest(row)
            if not positions:
                continue
            moved = tuple(
                moves.get(tuple(position), tuple(position))
                for position in positions
            )
            moved = tuple(position for position in moved if position is not None)
            target_row = (scope, node_id, renamed.get(parent, parent))
            # The operand's position set derives from the transitions of
            # the positions that moved (or were retired) and from the row
            # it revises.
            position_cells = tuple(dict.fromkeys(
                cell for cell in (
                    *(transitions.get(tuple(position)) for position in positions),
                    book.latest_ref(declared, row),
                )
                if cell is not None
            ))
            if target_row != row:
                book.post(
                    declared, row, (), stage=OPERAND_POSITION,
                    provenance=_Derived(position_cells), mode=_Mode.REVISE,
                )
            if page.latest(target_row) != moved:
                book.post(
                    declared, target_row, moved, stage=OPERAND_POSITION,
                    provenance=_Derived(tuple(dict.fromkeys((
                        *position_cells, book.latest_ref(declared, row),
                    )))),
                    mode=_Mode.REVISE,
                )


def _post_copy_on_read_fork(
    book: Any,
    source: tuple,
    forked: tuple,
    cause: str,
    stage: Any,
    *,
    members: frozenset,
    universe: frozenset,
    projecting: bool,
) -> None:
    """Post a copy-on-read fork's ``scope_origin`` fact (with its declared
    projection), register the projection and the read-through, and copy NO
    row.  The one body of ``fork_read_scope`` and
    ``fork_operand_position_scope``; each names its scope, stage, and the
    nodes the fork holds.

    ``members`` are the nodes the fork holds and ``universe`` the nodes of the
    graph it was cut from (empty when unknown); ``projecting`` says the fork
    holds ONLY ``members`` of the node-keyed rows of its source (an induced
    subgraph), else it holds them all."""

    from ...compiler.concordance_declarations import (
        READ_SCOPE_NODE_KEYED_PAGES, SCOPE_ORIGIN, SCOPE_REGISTRY,
        ScopeFork, ScopeProjection,
    )

    # Query the complement directly. Materializing universe - members made
    # every bootstrap function fork allocate another source-sized set, even
    # though its read-time projection already stores universe and members.
    inherited = book.__dict__.get("scope_projections", {}).get(source)
    # Every callee copy is its own variant (design section 7.1): the
    # planner's specialization rows -- the literal / default fold and the
    # tensor descriptors proven for the SOURCE graph's callers -- are not
    # inherited (``READ_THROUGH_EXCLUDED_PAGES``).  The copy's writers post
    # its own rows under the forked scope from ITS callsite; a copy never
    # carries a literal proven for another caller.  The forked scope is
    # therefore the copy's own specialization scope.
    node_keyed = frozenset(READ_SCOPE_NODE_KEYED_PAGES)
    # The projection's counts: how many of the source's node-keyed rows the
    # copy holds, lacks (rows of source nodes), or never could (retired ids).
    # Counted, not copied -- only a declared projection states them.
    carried = excluded = stale = 0
    if projecting:
        for page in tuple(book.pages.values()):
            if page.name not in node_keyed:
                continue
            for row in page.scope_rows(source):
                if len(row) < 2 or not isinstance(row[1], int):
                    continue
                if inherited is not None and inherited.excludes(row[1]):
                    # The source scope does not hold this node either (a row
                    # here would be its Unresolved read receipt).
                    excluded += 1
                elif row[1] not in members:
                    # A node the copy does not hold: of a source node
                    # (read-refused), or of an id retired before the copy
                    # was cut.
                    if row[1] in universe:
                        excluded += 1
                    else:
                        stale += 1
                else:
                    carried += 1
    # The fork's origin is its own fact on ``scope_origin``, DERIVED from the
    # source scope's registry cell.
    projection = None
    if projecting:
        digest = hashlib.sha1(
            ",".join(map(str, sorted(members, key=repr))).encode("ascii")
        ).hexdigest()
        projection = ScopeProjection(
            pages=tuple(sorted(node_keyed)), node_count=len(members),
            node_digest=digest,
            source_node_count=len(universe) + sum(
                member not in universe for member in members
            ),
            rows_carried=carried, rows_excluded=excluded, rows_stale=stale,
        )
    source_cell = book.latest_ref(SCOPE_REGISTRY, source)
    origin_cell = book.post(
        SCOPE_ORIGIN, (forked,),
        ScopeFork(source, str(cause), projection, copy_on_read=True),
        stage=stage,
        provenance=_Derived((source_cell,)),
        mode=_Mode.CONCORD,
    )
    # The refusal: the nodes this copy lacks, and those its source lacked.
    # Registered as the complement of the copy's own nodes in the (shared)
    # node set of its source, plus the source scope's own refusal: one
    # source-sized set per region, retained for the whole compile, was the
    # cost of spelling it as ``not_held | inherited.excluded``.  A fork cut
    # for a subgraph also READS only its own nodes' rows (``restricts``).
    if projecting or inherited is not None:
        book.register_scope_projection(
            forked, node_keyed,
            universe=universe if projecting else None,
            held=members, inherited=inherited, restricts=projecting,
        )
    # From here the fork reads through to its source.
    book.register_read_through(forked, source, origin_cell)


def fork_read_scope(
    graph: Any, cause: str, *, source_graph: Any = None,
) -> None:
    """Give a graph copy its own read scope: a COPY-ON-READ fork of its
    source's rows.

    The copy's graph names a freshly minted scope, and a read under it
    (the binding each operand read, loop carried bindings, operand
    structure -- every page row whose first element is the scope) answers as
    the source's row did when the fork was made.  No row is copied here: a
    row under the fork gets its own cell when it is first WRITTEN (a callsite
    fold removing an operand revises only the copy's row) or named as a
    source, and that cell is what the eager copy posted -- column 0, the
    source's fact, DERIVED from the source's cell at stage
    ``read_scope_fork`` (``IdentityBook._materialise_row``).  Sharing one
    scope, a fold in one specialization retired rows the original and every
    other specialization read; a fork's reads are the snapshot the copy was,
    and its writes are its own.  Page ``scope_origin`` row ``(new scope,)``
    records ``ScopeFork(source scope, cause, projection, copy_on_read=True)``,
    and the book holds the chain (``IdentityBook.register_read_through``).

    ``source_graph`` is the graph ``graph`` was cut from when ``graph`` is a
    PROPER induced subgraph of it (a planned dispatch region).  The copy then
    holds only the rows of its own nodes on the node-keyed pages
    (``READ_SCOPE_NODE_KEYED_PAGES``: ``row[1]`` is the consumer / value id):
    a read through the fork of the source's other nodes' rows is refused, and
    of an id that was a node of neither graph finds nothing.  That is a
    declared projection, not a silent filter: the ``scope_origin`` fact
    carries a ``ScopeProjection`` (the pages, the node count and digest, the
    rows carried / of source nodes the copy lacks / of retired ids), and a
    read under the forked scope of a node-keyed row of a source node the copy
    lacks is refused (``ProjectedScopeRead``, after an ``Unresolved`` row with
    a declared reason is posted at the key).  A copy of a projected scope
    inherits the refusal for the nodes its source never held.
    """

    graph_data = graph.G.graph
    source = graph_data.get("lexical_read_scope")
    if source is None:
        return
    source = tuple(source)
    book = current_identity_book()
    forked = book.mint_scope(f"{source[0]}|fork", _READ_SCOPE_FORK)
    projecting = source_graph is not None and len(graph.G) > 0
    _post_copy_on_read_fork(
        book, source, forked, cause, _READ_SCOPE_FORK,
        members=frozenset(graph.G.nodes) if projecting else frozenset(),
        universe=(
            frozenset(source_graph.G.nodes) if projecting else frozenset()
        ),
        projecting=projecting,
    )
    graph_data["lexical_read_scope"] = forked
    if tuple(graph_data.get("operand_position_scope") or ()) == source:
        graph_data["operand_position_scope"] = forked


def fork_operand_position_scope(
    graph: Any, members: Any, cause: str, *, source_graph: Any = None,
) -> None:
    """Give an extracted subgraph its own operand-position scope.

    A subgraph copied out of a source graph (``copy.copy`` + ``subgraph``)
    inherits the source's metadata, so its operand rewrites would post into
    the SOURCE graph's operand-position scope: the function-subgraph filter
    retired the source's rows for positions the source still has.  One
    operand table written by two graphs is one identity with two writers.

    As ``fork_read_scope`` forks a read scope, this is a COPY-ON-READ fork
    (``_post_copy_on_read_fork``) of the source's operand-position scope,
    cut for an induced subgraph: a scope is minted by the book and its origin
    is posted on ``scope_origin`` (stage FUNCTION_SUBGRAPH) DERIVED from the
    source scope's registry cell, carrying the declared projection onto
    ``members``.  No row is copied.  A read under the fork of an operand-
    position row (``identity_transition`` and the position-keyed pages) whose
    consumer is one of ``members`` answers as the source's row did when the
    fork was made; the row is written under the fork -- column 0 the source's
    fact, DERIVED from the source's cell -- when an operand rewrite first
    revises it or a cell names it as a source
    (``IdentityBook._materialise_row``).  A consumer outside ``members``
    holds no row here: its read finds nothing, or is refused when the node is
    one of ``source_graph``'s (``ProjectedScopeRead``).  The subgraph then
    names the fork; the source's rows are never written by the subgraph
    again.
    """

    graph_data = graph.G.graph
    source = _operand_position_scope(graph)
    if source is None:
        return
    members = frozenset(members)
    book = current_identity_book()
    forked = book.mint_scope(f"{source[0]}|operands", _FUNCTION_SUBGRAPH)
    _post_copy_on_read_fork(
        book, source, forked, cause, _FUNCTION_SUBGRAPH,
        members=members,
        universe=(
            frozenset(source_graph.G.nodes) if source_graph is not None
            else frozenset()
        ),
        projecting=True,
    )
    graph_data["operand_position_scope"] = forked


def _append_operand(graph: Any, node_id: Any, parent: Any, role: str) -> None:
    """Append one operand through ``_set_operands`` unless already present.

    An append takes the next ordinal of its role, so no existing position
    moves; it goes through the one writer so the operand list has one."""

    parents = list(graph.G.nodes[node_id].get("parents") or ())
    if (parent, role) not in parents:
        _set_operands(
            graph, node_id, [*parents, (parent, role)], cause=_APPEND_OPERAND,
        )


def _replace_inputs(
    graph: Any,
    node_id: int,
    inputs: tuple[tuple[int, str], ...],
    *,
    fork_from: Mapping[tuple[Any, int], tuple[Any, ...]] | None = None,
) -> None:
    """Replace one wrapper's incoming topology with executable operands.

    An operand that is not in the graph is replaced by an explicit
    ``UNTRANSLATED_NODE_TYPE`` node rather than passed to ``add_edge``.
    NetworkX *creates* an absent endpoint rather than raising, which turned
    a missing operand into a node with no ``type``, no ``expr_obj`` and no
    ``label`` -- invisible here and fatal thousands of nodes later, as a
    bare ``KeyError('type')`` naming nothing. The placeholder keeps the
    consuming operation's arity intact (an operation silently short an
    operand is a *wrong* program, not a smaller one) while making it
    honestly inexecutable.
    """

    # Edges that are not operand positions (a static reference's ``callee``
    # edge written beside the list) go with the old topology; the operand
    # edges themselves are rewritten by ``_set_operands`` below.
    operand_parents = {
        parent for parent, _role in (
            graph.G.nodes[node_id].get("parents") or ()
        )
    } if node_id in graph.G else set()
    for predecessor in tuple(graph.G.predecessors(node_id)):
        if predecessor in operand_parents:
            continue
        graph.G.remove_edge(predecessor, node_id)
        graph.G.nodes[predecessor]["children"] = [
            (child_id, role)
            for child_id, role in graph.G.nodes[predecessor].get(
                "children", ()
            )
            if child_id != node_id
        ]
    consumer = graph.G.nodes[node_id] if node_id in graph.G else {}
    expected = len(inputs)
    present = sum(1 for operand, _role in inputs if operand in graph.G)
    # The grade describes the *construct*, not the individual operand: an
    # operation with one of two operands resolved is partially translated,
    # even though each absent operand is individually absent.
    grade = TRANSLATION_ABSENT if present == 0 else TRANSLATION_PARTIAL
    resolved: list[tuple[int, str]] = []
    for predecessor, role in inputs:
        if predecessor not in graph.G:
            predecessor = _untranslated_operand(
                graph,
                consumer_id=node_id,
                consumer=consumer,
                role=role,
                absent_id=predecessor,
                grade=grade,
                observed=present,
                expected=expected,
            )
        resolved.append((predecessor, role))
    _set_operands(
        graph, node_id, resolved, cause=_REPLACE_INPUTS, fork_from=fork_from,
    )


def _untranslated_operand(
    graph: Any,
    *,
    consumer_id: int,
    consumer: Any,
    role: str,
    absent_id: int,
    grade: str = TRANSLATION_UNKNOWN,
    observed: int = 0,
    expected: int = 0,
) -> int:
    """Materialize one explicit stand-in for an operand that never arrived."""

    expression = consumer.get("expr_obj") if hasattr(consumer, "get") else None
    operation = str(consumer.get("type") or type(expression).__name__)
    span = _source_span(expression)
    label = f"untranslated[{operation}.{role}]"
    placeholder_id = id(label)
    while placeholder_id in graph.G:
        # ``id`` of a fresh string is unique among live objects, but this
        # label is not retained, so a later identical label could reuse the
        # address. Step off any collision rather than silently aliasing two
        # unrelated stand-ins onto one node.
        placeholder_id += 1
    graph.G.add_node(
        placeholder_id,
        label=label,
        type=UNTRANSLATED_NODE_TYPE,
        op=UNTRANSLATED_NODE_TYPE.lower(),
        expr_obj=None,
        extra_args={},
        domain_node=None,
        store_id=None,
        parents=[],
        children=[],
        attributes={
            "untranslated": True,
            "consumer_node": int(consumer_id),
            "consumer_operation": operation,
            "operand_role": str(role),
            "absent_node_id": int(absent_id),
            "source_span": span,
            "translation_grade": str(grade),
            "translated_operands": int(observed),
            "expected_operands": int(expected),
        },
    )
    # The stand-in's ``ingestion_value`` row (edges lane C): DERIVED from
    # the consumer that lacks the operand and the absent operand's own row
    # when the book still has it (a node reduced away keeps its row).
    scopes = node_ingestion_scopes(graph)
    if scopes:
        from ...compiler.concordance_declarations import REDUCTION
        from ...compiler.identity_concordance import Mode

        cells = tuple(dict.fromkeys(
            cell for cell in (
                _posted_node_identity_cell(graph, int(consumer_id)),
                _posted_node_identity_cell(graph, int(absent_id)),
            )
            if cell is not None
        ))
        if cells:
            current_identity_book().post(
                _INGESTION_VALUE, (scopes[0], int(placeholder_id)),
                _NodeFact(
                    UNTRANSLATED_NODE_TYPE,
                    UNTRANSLATED_NODE_TYPE.lower(), label,
                ),
                stage=REDUCTION, provenance=_Derived(cells), mode=Mode.CONCORD,
            )
    record_translation_shortfall(
        graph,
        pass_name="process-graph-operands",
        node_id=consumer_id,
        operation=operation,
        role=role,
        source_span=span,
        grade=grade,
        observed=observed,
        expected=expected,
        reason=(
            "operand was never ingested as a graph node; a non-operation "
            "stands in its place so the translation reports rather than "
            "computes"
        ),
    )
    return placeholder_id


def _remove_node(graph: Any, node_id: int) -> None:
    """Remove one reduced-away node and its cached adjacency metadata."""

    if node_id not in graph.G:
        return
    # The removed node's own positions retire through the one writer, which
    # also clears its parents' ``children`` entries and edges.
    _set_operands(graph, node_id, [], cause=_REMOVE_NODE)
    for successor in tuple(graph.G.successors(node_id)):
        _set_operands(graph, successor, [
            (parent_id, role)
            for parent_id, role in graph.G.nodes[successor].get(
                "parents", ()
            )
            if parent_id != node_id
        ], cause=_REMOVE_NODE)
    graph.roots = [root for root in graph.roots if root != node_id]
    graph.G.remove_node(node_id)


def _concord_lexical_reads(
    graph: Any, scope: str, occurrence_id: int, binding: str,
    *, binding_cell: Any = None,
) -> None:
    """Commit, per consumer edge, the binding one ``Name`` occurrence read.

    Page ``lexical_read_binding`` row ``(scope, consumer id, role,
    ordinal)`` holds the authored binding that operand read; ``ordinal``
    counts earlier parents with the same role (a tuple's ``elts``).  The value the edge points at
    may later be rebound (a loop header, a loop result port); the binding
    it read never changes, which is what lets those rebindings choose per
    read instead of per value.
    """

    from ...compiler.concordance_declarations import (
        LEXICAL_READ_BINDING, OPERAND_POSITION,
    )

    book = current_identity_book()

    def commit(row: tuple, *cells: Any) -> None:
        """One read: DERIVED(the cells of the nodes it relates) -- the
        binding cell is always among them (see below)."""

        book.post(
            LEXICAL_READ_BINDING, row, str(binding),
            stage=OPERAND_POSITION, provenance=_Derived(_source_cells(cells)),
            mode=_Mode.CONCORD,
        )

    # The read is a fact of the occurrence before it is one of any consumer:
    # a keyword argument's wrapper (and with it the Name node) can be absent
    # from the function subgraph, leaving the read with no consumer edge.
    # Row ``(scope, "occurrence", id, 0)`` is the source a later operand
    # position forks from (``_set_operands``).  It is keyed like every row
    # of the declared page (scope, consumer, role, ordinal): an occurrence is
    # one read, ordinal 0.  The three-key form left the fork source two
    # fields long, and the typed ``OperandFork(cause, consumer, role,
    # ordinal)`` refused it: ``for name, limit in channels.items()`` (the
    # audit mapping case) raised TypeError missing ``source_ordinal``.
    # The occurrence's row derives from the occurrence node's cell, a
    # consumer's from the occurrence's and the consumer's own.
    occurrence_cell = (
        node_identity_cell(graph, occurrence_id)
        if occurrence_id in graph.G else None
    )
    # The spelling is not an identity.  In particular, selecting the highest
    # NAME_BINDING version here can attach an earlier occurrence to a later
    # rebinding after its AST wrapper has dissolved.  The caller holds the
    # exact environment version at the read and passes that Ref.  Without that
    # Ref there is no sourced binding fact to publish; downstream therefore
    # observes the row as unresolved/absent even when the occurrence survives.
    if binding_cell is None:
        return
    commit(
        (scope, "occurrence", int(occurrence_id), 0),
        occurrence_cell, binding_cell,
    )
    if occurrence_id not in graph.G:
        return
    for consumer in tuple(graph.G.successors(occurrence_id)):
        for role, ordinal, parent_id in _operand_positions(
            graph.G.nodes[consumer].get("parents", ())
        ):
            if parent_id == occurrence_id:
                commit(
                    (scope, consumer, role, ordinal), occurrence_cell,
                    binding_cell,
                    node_identity_cell(graph, consumer),
                )


def _operand_positions(parents: Any):
    """Each ``(role, ordinal, parent)``: the operand's stable position."""

    seen: dict[Any, int] = {}
    for parent_id, role in parents:
        ordinal = seen.get(role, 0)
        seen[role] = ordinal + 1
        yield role, ordinal, parent_id


def lexical_read_binding(
    graph: Any, consumer: int, role: Any, ordinal: int = 0,
) -> str | None:
    """The authored binding one operand of ``consumer`` read, if any (a
    vacated position's ``Unresolved`` revision reads as none)."""

    scope = (getattr(graph, "graph", None) or {}).get("lexical_read_scope")
    if scope is None:
        return None
    consumer = consumer if isinstance(consumer, str) else int(consumer)
    fact = current_identity_book().page("lexical_read_binding").latest(
        (tuple(scope), consumer, role, int(ordinal))
    )
    return fact if isinstance(fact, str) else None


def _redirect_value(
    graph: Any,
    old_id: int,
    producer_id: int,
) -> None:
    """Fan every use of one lexical occurrence out from its value producer."""

    if old_id == producer_id or old_id not in graph.G:
        return
    for successor in tuple(graph.G.successors(old_id)):
        successor_data = graph.G.nodes[successor]
        replacement = []
        for parent_id, role in successor_data.get("parents", ()):
            replacement.append(
                (producer_id if parent_id == old_id else parent_id, role)
            )
        _set_operands(
            graph, successor, replacement, cause=_REDIRECT_VALUE,
            same={old_id: producer_id},
        )
    graph.roots = [
        producer_id if root == old_id else root for root in graph.roots
    ]
    _remove_node(graph, old_id)


# --------------------------------------------------------------------------
# Step 3 (plan 70): the reducer's field state lives on the book.  The four
# private dicts ``_normalize_lexical_values`` used to keep are read views over
# the pages below; the reducer's only private state is a cursor of cells.
# --------------------------------------------------------------------------


def _cell_node_id(cell: Any) -> int | None:
    """The graph node id a node identity cell names: its VALUE_ID row element.

    A node identity cell is a row on whichever page identifies nodes
    (``ingestion_value`` before the canonical relabel, ``canonical_value``
    after); the id is read from the row through the page's declared shape,
    never by position.
    """

    if not isinstance(cell, _Ref):
        return None
    for declared, item in zip(cell.page.row_fields, cell.row):
        if declared.kind is _RowFieldKind.VALUE_ID and isinstance(item, int):
            return int(item)
    return None


def _cell_fact(book: Any, cell: Any) -> Any:
    """The fact stored at ``cell``, or None when the cell does not exist."""

    if not isinstance(cell, _Ref):
        return None
    page = book.pages.get(cell.page.name)
    if page is None:
        return None
    return page.cell(cell.row, cell.column)


class _FieldStateView(Mapping):
    """``(receiver, field) -> node id`` over the reducer's field-state cursor.

    ``member`` selects ``FieldState.value`` (the ``attribute_value_nodes``
    view) or ``FieldState.effect`` (``attribute_effect_nodes``).  Iteration
    is the cursor's recorded order, which is the order the old dicts had.  A
    cursor cell whose fact is ``Unresolved`` is absent: readers see absence.
    Read-only: a stray write raises at its site instead of being tagged.
    """

    __slots__ = ("_cursor", "_member")

    def __init__(self, cursor: dict, member: str) -> None:
        self._cursor = cursor
        self._member = member

    def _node(self, key: Any) -> int | None:
        cell = self._cursor.get(key)
        fact = _cell_fact(current_identity_book(), cell)
        if not isinstance(fact, _FieldState):
            return None
        return _cell_node_id(getattr(fact, self._member))

    def __getitem__(self, key: Any) -> int:
        try:
            node = self._node(key)
        except TypeError:
            raise KeyError(key) from None
        if node is None:
            raise KeyError(key)
        return node

    def __iter__(self):
        for key in tuple(self._cursor):
            if self._node(key) is not None:
                yield key

    def __len__(self) -> int:
        return sum(1 for _ in self)

    def __repr__(self) -> str:
        return f"_FieldStateView({self._member!r}, {dict(self)!r})"

    def __reduce__(self):
        return (dict, (dict(self),))


class _ReturnSiteView(Mapping):
    """``return span -> legacy receipt`` over one return-site page.

    The page rows are keyed by the return site's node identity cell; the
    legacy receipts (``return_slot_values``, ``return_record_field_states``,
    ``return_container_kinds``) were keyed by the returned expression's
    source span, so ``spans`` maps each site cell to the span it was posted
    for.  Rows are read under the graph's current operand-position scope
    (the ingestion scope while reducing, the canonical scope after
    ``_relabel_field_state_pages``), so the same view follows the relabel.
    Read-only; pickles as the plain dict it presents.
    """

    __slots__ = ("_book", "_graph", "_page", "_spans", "_project")

    def __init__(
        self, book: Any, graph: Any, page: Any, spans: dict, project: Any,
    ) -> None:
        self._book = book
        self._graph = graph
        self._page = page
        self._spans = spans
        self._project = project

    def _rows_by_site(self) -> dict:
        scope = _operand_position_scope(self._graph)
        stored = self._book.pages.get(self._page.name)
        if scope is None or stored is None:
            return {}
        by_site: dict = {}
        for row in stored.scope_rows(scope):
            by_site.setdefault(row[1], []).append(row)
        if self._page is _RETURN_SITE_SLOT:
            # ``def f(...) -> tuple[int, ...]: ... return ()`` (and the
            # ``return ()`` arm of ``-> tuple[int,int] | None``): the site
            # posts a RETURN_SITE_CONTAINER (TUPLE) row and zero
            # RETURN_SITE_SLOT rows, so the slot view built its sites from
            # the slot page alone and the zero-length arm was ABSENT, which
            # ``arm_return_control`` and the loop composer read as "not a
            # return" (the guard If lost its CondBr).  A site whose
            # container row exists but has no slot rows is an authored
            # return of zero slots: its slot span is ``()``.
            container = self._book.pages.get(_RETURN_SITE_CONTAINER.name)
            if container is not None:
                for row in container.scope_rows(scope):
                    by_site.setdefault(row[1], [])
        return by_site

    def _items(self):
        book = self._book
        stored = book.pages.get(self._page.name)
        for site, rows in self._rows_by_site().items():
            span = self._spans.get(site)
            if span is None:
                continue
            yield span, self._project(
                book, tuple((row, stored.latest(row)) for row in rows)
            )

    def __getitem__(self, key: Any):
        for span, receipt in self._items():
            if span == key:
                return receipt
        raise KeyError(key)

    def __iter__(self):
        for span, _receipt in self._items():
            yield span

    def __len__(self) -> int:
        return sum(1 for _ in self._items())

    def __repr__(self) -> str:
        return f"_ReturnSiteView({self._page.name!r}, {dict(self)!r})"

    def __reduce__(self):
        return (dict, (dict(self),))


def _return_slot_receipt(book: Any, rows: tuple) -> tuple:
    """``return_slot_values`` receipt: node id per slot, None when Unresolved."""

    slots = sorted(rows, key=lambda item: int(item[0][2]))
    return tuple(_cell_node_id(fact) for _row, fact in slots)


def _return_field_state_receipt(book: Any, rows: tuple) -> tuple:
    """``return_record_field_states`` receipt: ``(receiver, field, value id)``
    per field-state cell the site carries; an Unresolved state is absent."""

    receipt = []
    for row, fact in rows:
        state = _cell_fact(book, fact)
        if not isinstance(state, _FieldState):
            continue
        value = _cell_node_id(state.value)
        if value is None:
            continue
        receipt.append((int(row[2]), str(row[3]), value))
    return tuple(receipt)


def _return_container_receipt(book: Any, rows: tuple) -> Any:
    """``return_container_kinds`` receipt: the container kind's name."""

    for _row, fact in rows:
        if isinstance(fact, _ContainerKind):
            return fact.value
    return None


def _relabel_field_state_pages(book: Any, read_scope: Any, mapping: Any) -> None:
    """Re-post this reduction's field-state and return-site rows under the
    canonical scope ``read_scope`` (plan 70, sections 1.3 S10 and 2).

    Rows were posted under ``(read_scope, "ingestion")`` with ingestion ids
    and node identity cells in the ingestion id space.  Each is posted again
    under ``read_scope`` with the receiver's canonical id and every node
    cell re-pointed at its ``canonical_value`` cell, DERIVED(the ingestion
    cell, those canonical cells) at the canonical-relabel stage.  Nothing is
    rewritten in place; the ingestion rows remain the history.  A revision
    whose node left the graph before the relabel (no canonical id) is not
    re-posted, which is what the in-place comprehensions this replaces did.
    """

    ingestion_scope = (read_scope, "ingestion")
    stage = _CANONICAL_RELABEL_STAGE

    def canonical_cell(cell: Any) -> Any:
        node_id = _cell_node_id(cell)
        if node_id is None or node_id not in mapping:
            return None
        return book.latest_ref(_CANONICAL_VALUE, (read_scope, mapping[node_id]))

    # ingestion field-state cell -> its canonical re-post, so return-site
    # rows and Unresolved ``read`` tuples can name the canonical cells.
    relabeled: dict = {}
    field_page = book.pages.get(_REDUCER_FIELD_STATE.name)
    if field_page is not None:
        for row in field_page.scope_rows(ingestion_scope):
            receiver = row[1]
            if receiver not in mapping:
                continue
            canonical_row = (read_scope, mapping[receiver], row[2])
            for column, fact in field_page.history(row):
                source = _Ref(_REDUCER_FIELD_STATE, row, column)
                if isinstance(fact, _Unresolved):
                    read = tuple(relabeled.get(cell, cell) for cell in fact.read)
                    new_fact: Any = _Unresolved(fact.reason, read)
                    cells: tuple = (source,)
                elif isinstance(fact, _FieldState):
                    value = canonical_cell(fact.value)
                    effect = canonical_cell(fact.effect)
                    if value is None or effect is None:
                        continue
                    new_fact = _FieldState(fact.kind, value, effect)
                    cells = (source, value, effect)
                else:
                    continue
                relabeled[source] = book.post(
                    _REDUCER_FIELD_STATE, canonical_row, new_fact,
                    stage=stage, provenance=_Derived(cells), mode=_Mode.REVISE,
                )
    static_page = book.pages.get(_STATIC_ATTRIBUTE_STATE.name)
    if static_page is not None:
        for row in static_page.scope_rows(ingestion_scope):
            for column, fact in static_page.history(row):
                source = _Ref(_STATIC_ATTRIBUTE_STATE, row, column)
                value = canonical_cell(fact)
                if value is None:
                    continue
                book.post(
                    _STATIC_ATTRIBUTE_STATE, (read_scope, *row[1:]), value,
                    stage=stage, provenance=_Derived((source, value)),
                    mode=_Mode.REVISE,
                )
    slot_page = book.pages.get(_RETURN_SITE_SLOT.name)
    if slot_page is not None:
        for row in slot_page.scope_rows(ingestion_scope):
            column, fact = slot_page.history(row)[-1]
            source = _Ref(_RETURN_SITE_SLOT, row, column)
            value = canonical_cell(fact)
            if value is None:
                new_fact = _Unresolved(_RETURN_SLOT_NOT_A_VALUE, (source,))
                cells = (source,)
            else:
                new_fact = value
                cells = (source, value)
            book.post(
                _RETURN_SITE_SLOT, (read_scope, *row[1:]), new_fact,
                stage=stage, provenance=_Derived(cells), mode=_Mode.CONCORD,
            )
    container_page = book.pages.get(_RETURN_SITE_CONTAINER.name)
    if container_page is not None:
        for row in container_page.scope_rows(ingestion_scope):
            column, fact = container_page.history(row)[-1]
            source = _Ref(_RETURN_SITE_CONTAINER, row, column)
            book.post(
                _RETURN_SITE_CONTAINER, (read_scope, *row[1:]), fact,
                stage=stage, provenance=_Derived((source,)), mode=_Mode.CONCORD,
            )
    # ``return_output_arms`` (one row per function whose returns disagree on
    # arity): the output's id follows ``mapping``; the arm cells (container
    # cells, site cell, member cells) are re-pointed at the re-posts above.
    arms_page = book.pages.get(_RETURN_OUTPUT_ARMS.name)
    if arms_page is not None:
        for row in arms_page.scope_rows(ingestion_scope):
            output = row[1]
            if output not in mapping:
                continue
            column, fact = arms_page.history(row)[-1]
            source = _Ref(_RETURN_OUTPUT_ARMS, row, column)
            canonical_row = (read_scope, mapping[output])
            if isinstance(fact, _Unresolved):
                book.post(
                    _RETURN_OUTPUT_ARMS, canonical_row,
                    _Unresolved(fact.reason, tuple(
                        relabeled.get(cell, cell) for cell in fact.read
                    )),
                    stage=stage, provenance=_Derived((source,)),
                    mode=_Mode.CONCORD,
                )
                continue
            arms = tuple(
                _ReturnArm(
                    arm.site,
                    book.latest_ref(
                        _RETURN_SITE_CONTAINER,
                        (read_scope, *arm.container.row[1:]),
                    ) or arm.container,
                    arm.length, arm.absent, arm.tail,
                )
                for arm in fact.arms
            )
            members = tuple(
                canonical_cell(cell) for cell in fact.member_cells
            )
            if any(cell is None for cell in members):
                continue
            book.post(
                _RETURN_OUTPUT_ARMS, canonical_row,
                _ReturnOutputArms(fact.kind, arms, fact.width, members),
                stage=stage,
                provenance=_Derived(tuple(dict.fromkeys(
                    (source, *(arm.container for arm in arms), *members)
                ))),
                mode=_Mode.CONCORD,
            )
    # ``semantic_output``: one row per authored output position; the output
    # value's id follows ``mapping`` and its cell is the canonical one.
    semantic_page = book.pages.get(_SEMANTIC_OUTPUT.name)
    if semantic_page is not None:
        for row in semantic_page.scope_rows(ingestion_scope):
            column, fact = semantic_page.history(row)[-1]
            if fact[1] not in mapping:
                continue
            source = _Ref(_SEMANTIC_OUTPUT, row, column)
            value = book.latest_ref(
                _CANONICAL_VALUE, (read_scope, mapping[fact[1]]),
            )
            cells = (source,) if value is None else (source, value)
            book.post(
                _SEMANTIC_OUTPUT, (read_scope, row[1]),
                (fact[0], int(mapping[fact[1]])),
                stage=stage, provenance=_Derived(cells), mode=_Mode.CONCORD,
            )
    site_page = book.pages.get(_RETURN_SITE_FIELD_STATE.name)
    if site_page is not None:
        for row in site_page.scope_rows(ingestion_scope):
            receiver = row[2]
            if receiver not in mapping:
                continue
            column, fact = site_page.history(row)[-1]
            source = _Ref(_RETURN_SITE_FIELD_STATE, row, column)
            canonical_row = (read_scope, row[1], mapping[receiver], row[3])
            if isinstance(fact, _Unresolved):
                read = tuple(relabeled.get(cell, cell) for cell in fact.read)
                book.post(
                    _RETURN_SITE_FIELD_STATE, canonical_row,
                    _Unresolved(fact.reason, read), stage=stage,
                    provenance=_Derived((source,)), mode=_Mode.CONCORD,
                )
                continue
            state = relabeled.get(fact)
            if state is None:
                continue
            book.post(
                _RETURN_SITE_FIELD_STATE, canonical_row, state, stage=stage,
                provenance=_Derived((source, state)), mode=_Mode.CONCORD,
            )


def _mint_settled_node(
    graph: Any,
    node_type: str,
    label: str,
    *,
    attributes: dict[str, Any] | None = None,
    parents: tuple[tuple[int, str], ...] = (),
    source_cell: Any = None,
    cause: Any = _REDUCER_SYNTHESIS,
) -> int:
    """Mint one reducer node in a function graph that has already been
    canonically relabelled (``new_node`` of ``_normalize_lexical_values`` is
    that pass's own minter).

    The node's identity row is posted by ``post_derived_node_identity`` in
    the scope ``node_identity_cell`` reads (the relabelled graph's
    ``operand_position_scope``), DERIVED from ``source_cell``; its operands
    are written by the one operand writer.  No source cells: refused, as
    ``new_node`` refuses -- creation is registration.
    """

    from ...compiler.process_graph_value_ids import next_process_value_id

    cells = (
        (source_cell,) if isinstance(source_cell, _Ref)
        else tuple(dict.fromkeys(
            cell for cell in (source_cell or ()) if isinstance(cell, _Ref)
        ))
    )
    if not cells:
        raise ValueError(
            f"_mint_settled_node({node_type!r}, {label!r}): no source -- a "
            "synthesized node derives from the cells it stands on"
        )
    node_id = next_process_value_id(graph)
    graph.G.add_node(
        node_id,
        label=label,
        type=node_type,
        op=node_type.lower(),
        expr_obj=None,
        extra_args={},
        domain_node=None,
        store_id=None,
        parents=[],
        children=[],
        attributes=dict(attributes or {}),
    )
    cell = post_derived_node_identity(
        graph, int(node_id), cells, stage=_REDUCTION,
    )
    if cell is None:
        graph.G.remove_node(node_id)
        raise ValueError(
            f"_mint_settled_node({node_type!r}, {label!r}): the graph has "
            "no identity scope to register the node in"
        )
    _set_operands(graph, node_id, list(parents), cause=cause)
    return int(node_id)


def _link_integer_glyph_formatter_calls(
    graph: Any,
    function_table: Any,
    *,
    row: tuple,
    glyph_cell: Any,
    components: Any,
    value_class_scope: Any,
    format_spec_scopes: tuple,
    new_node: Any,
) -> list:
    """Give each formatted scalar component of one glyph recipe whose operand
    is a concorded ``int`` its authored formatter call, and REVISE the recipe
    row to name it.

    A formatted scalar is an ordinary call to the authored decimal (or
    ``#x`` hex) formatter.  Its graph identity derives from the exact glyph
    recipe cell, the value-class cell the ``int`` was read from and the
    format-spec recipe cell; the callee address is the exact FunctionTable
    entry declared from that helper's source span.  ``callee_ref`` is only
    the graph read view of that pair.

    Formatter selection is a read of the value-class concordance.
    Parameter / local / call / literal graph shapes are deliberately
    irrelevant: their respective producers must all carry the same class
    fact to this value before formatting can occur.  The recipe is linked
    when it is authored (``_normalize_lexical_values``) and again once the
    call-edge class facts have settled (``propagate_call_formal_numeric_types``
    publishes an unannotated formal's class from its call actuals after
    every recipe exists), so the second read is the same read, later.

    The recipe already has the only lossless native representations
    admitted here: exact record and tuple projections, resident StringTable
    tokens, and the authored integer formatter.  An unknown scalar ``!r``
    has no representation fact.  It is kept unresolved; calling a host
    interpreter would replace the missing concordance edge with a different
    runtime and make the product Python-dependent.
    """

    from ...compiler.string_table import string_token

    book = current_identity_book()
    components = list(components)
    if glyph_cell is None:
        return components
    formatter_entry = next((
        entry
        for entry in function_table
        if str(entry.qualified_name) == (
            "src.compiler.glyph_sequence_format."
            "decimal_integer_glyph_tokens"
        )
    ), None)
    prefixed_hex_formatter_entry = next((
        entry
        for entry in function_table
        if str(entry.qualified_name) == (
            "src.compiler.glyph_sequence_format."
            "prefixed_lower_hex_integer_glyph_tokens"
        )
    ), None)
    rewritten_components = list(components)
    for ordinal, component in enumerate(components):
        if (
            component.kind != "formatted"
            or component.operand_value_id is None
            or component.formatted_sequence_value_id is not None
        ):
            continue
        value_class_cell = book.latest_ref(
            _SOURCE_VALUE_CLASS,
            (value_class_scope, int(component.operand_value_id)),
        )
        value_class_fact = (
            None if value_class_cell is None else
            book.page(_SOURCE_VALUE_CLASS).cell(
                value_class_cell.row,
                value_class_cell.column,
            )
        )
        value_class_identity = (
            str(value_class_fact[0])
            if isinstance(value_class_fact, tuple)
            and value_class_fact else None
        )
        integer_value = value_class_identity in {
            "int", "builtins.int",
        }
        format_spec_cell = None
        format_tokens = None
        if component.format_spec_value_id is not None:
            format_spec_rows = tuple(
                (scope, int(component.format_spec_value_id))
                for scope in format_spec_scopes
            )
            format_spec_cell = next((
                cell for candidate in format_spec_rows
                if (cell := book.latest_ref(
                    _SOURCE_GLYPH_SEQUENCE, candidate,
                )) is not None
            ), None)
            format_spec_fact = (
                None if format_spec_cell is None else
                book.page(_SOURCE_GLYPH_SEQUENCE).cell(
                    format_spec_cell.row,
                    format_spec_cell.column,
                )
            )
            if (
                isinstance(format_spec_fact, _SourceGlyphSequence)
                and all(
                    item.kind == "literal"
                    for item in format_spec_fact.components
                )
            ):
                format_tokens = tuple(
                    token
                    for item in format_spec_fact.components
                    for token in item.glyph_tokens
                )
        integer_formatter_entry = (
            formatter_entry
            if component.format_spec_value_id is None
            and component.conversion in {-1, ord("r")}
            else prefixed_hex_formatter_entry
            if component.conversion == -1
            and format_tokens == (
                int(string_token("#")),
                int(string_token("x")),
            )
            else None
        )
        integer_formatter_name = (
            None if integer_formatter_entry is None else
            str(integer_formatter_entry.qualified_name).rsplit(
                ".", 1,
            )[-1]
        )
        typed_integer_format = (
            component.projection_kind == "scalar"
            and integer_value
            and integer_formatter_entry is not None
        )
        if not typed_integer_format:
            continue
        call_id = new_node(
            "Call",
            str(integer_formatter_name),
            attributes={
                "callee_ref": int(
                    integer_formatter_entry.reference.address
                ),
                "callee_resolution": "source-glyph-formatter",
                "producer_kind": "formatted_glyph_sequence",
                "aggregate_kind": "list",
                "sequence_key_columns": (),
                "sequence_column_count": 1,
                "sequence_writable": True,
                "sequence_element_dtypes": ("int64",),
                "sequence_column_dtypes": ("int64",),
                "source_glyph_component": (row, int(ordinal)),
            },
            parents=((int(component.operand_value_id), "arg:0"),),
            source_cell=tuple(dict.fromkeys(filter(None, (
                glyph_cell,
                value_class_cell,
                format_spec_cell,
            )))),
        )
        rewritten_components[ordinal] = _dataclass_replace(
            component,
            formatted_sequence_value_id=int(call_id),
        )
    if tuple(rewritten_components) != tuple(components):
        revised_fact = _SourceGlyphSequence(tuple(rewritten_components))
        call_cells = tuple(
            node_identity_cell(
                graph,
                int(component.formatted_sequence_value_id),
            )
            for component in rewritten_components
            if component.kind == "formatted"
            and component.formatted_sequence_value_id is not None
            and int(component.formatted_sequence_value_id) in graph.G
        )
        book.post(
            _SOURCE_GLYPH_SEQUENCE,
            row,
            revised_fact,
            stage=_REDUCTION,
            provenance=_Derived(tuple(dict.fromkeys((
                glyph_cell, *call_cells,
            )))),
            mode=_Mode.REVISE,
        )
    return rewritten_components


_BUILTIN_SCALAR_INTEGER_OPERATORS = (
    ast.Add, ast.Sub, ast.Mult, ast.FloorDiv, ast.Mod,
    ast.LShift, ast.RShift, ast.BitAnd, ast.BitOr, ast.BitXor,
)
_BUILTIN_SCALAR_FLOAT_OPERATORS = (
    ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod,
)


def _builtin_scalar_operator_class(expression: Any, operand_classes: tuple) -> str | None:
    """Python's own result class of a builtin scalar operator, or None.

    Defined only where the operand classes decide it: ``int`` arithmetic is
    ``int`` (``/`` is ``float``), any ``float`` operand makes ``float``,
    ``bool`` bitwise operators stay ``bool`` and ``bool`` arithmetic is
    ``int``.  ``**`` is excluded (``2 ** -1`` is a ``float``, ``(-8.0) **
    (1/3)`` a ``complex``): its class is not a function of the operand
    classes.
    """
    classes = tuple(operand_classes)
    if any(item not in {"builtins.int", "builtins.bool", "builtins.float"}
           for item in classes):
        return None
    if isinstance(expression, ast.BinOp) and len(classes) == 2:
        if "builtins.float" in classes:
            return (
                "builtins.float"
                if isinstance(expression.op, _BUILTIN_SCALAR_FLOAT_OPERATORS)
                else None
            )
        if isinstance(expression.op, ast.Div):
            return "builtins.float"
        if (
            classes == ("builtins.bool", "builtins.bool")
            and isinstance(expression.op, (ast.BitAnd, ast.BitOr, ast.BitXor))
        ):
            return "builtins.bool"
        if isinstance(expression.op, _BUILTIN_SCALAR_INTEGER_OPERATORS):
            return "builtins.int"
        return None
    if isinstance(expression, ast.UnaryOp) and len(classes) == 1:
        if isinstance(expression.op, ast.Not):
            return "builtins.bool"
        if classes[0] == "builtins.float":
            return (
                "builtins.float"
                if isinstance(expression.op, (ast.UAdd, ast.USub)) else None
            )
        if isinstance(expression.op, (ast.UAdd, ast.USub, ast.Invert)):
            return "builtins.int"
    return None


def _propagate_builtin_scalar_operator_classes(graph: Any) -> bool:
    """Publish the class of every builtin scalar operator result.

    Program: ``k = value_id + 1; return f"legacy#{k}"`` with ``value_id:
    int`` (and ``id_space.describe``'s ``serial_of(...)``, seven bootstrap
    units in all).  Wrong record: an operator result had no
    ``source_value_class`` row, so the integer glyph formatter was never
    linked and materialization refused "formatted glyph component has no
    resident producer".  Rule: an operator over operands whose class rows
    are builtin ``int``/``bool``/``float`` has the class Python defines for
    it, DERIVED from the operator node's cell and the operand class cells;
    a result whose class the operands do not decide gets no row.  Returns
    whether a row was added (the numeric fixed point repeats on change).
    """

    from ...compiler.concordance_declarations import SOURCE_VALUE_CLASS

    book = current_identity_book()
    target = getattr(graph, "G", graph)
    scope = _source_numeric_scope(graph)
    page = book.page(SOURCE_VALUE_CLASS)
    changed = False
    for node_id, data in tuple(target.nodes(data=True)):
        expression = data.get("expr_obj")
        conditional_phi = (
            str(data.get("type") or data.get("op") or "").casefold() == "phi"
            and (data.get("attributes") or {}).get("source_conditional_id") is not None
        )
        if conditional_phi:
            roles = ("body", "orelse")
        elif isinstance(expression, ast.BinOp):
            roles = ("lhs", "rhs")
        elif isinstance(expression, ast.UnaryOp):
            roles = ("operand",)
        else:
            continue
        value_id = int(data.get("value_id", node_id))
        if page.latest((scope, value_id)) is not None:
            continue
        parents = {str(role): int(parent) for parent, role in data.get("parents") or ()}
        expected_roles = {*roles, "test"} if conditional_phi else set(roles)
        if set(parents) != expected_roles:
            continue
        operand_ids = tuple(
            int(target.nodes[parents[role]].get("value_id", parents[role]))
            if parents[role] in target else parents[role]
            for role in roles
        )
        operand_cells = tuple(
            book.latest_ref(SOURCE_VALUE_CLASS, (scope, operand_id))
            for operand_id in operand_ids
        )
        if any(cell is None for cell in operand_cells):
            continue
        operand_classes = tuple(
            _canonical_source_class_identity(
                book.page(SOURCE_VALUE_CLASS).cell(cell.row, cell.column)[0]
            )
            for cell in operand_cells
        )
        result_limbs = 1
        if conditional_phi:
            # The optional fingerprint's present and computed arms both
            # prove int, but their control-owned merge previously lost that
            # class. A merge inherits a scalar class only when EVERY exact
            # arm proves the same class and precision; unknown/mixed arms
            # never become the type of a convenient predecessor.
            arm_facts = tuple(page.cell(cell.row, cell.column) for cell in operand_cells)
            same_arms = len({(fact[0], int(fact[1])) for fact in arm_facts}) == 1
            result_class = operand_classes[0] if same_arms and operand_classes[0] in {
                "builtins.int", "builtins.bool", "builtins.float",
            } else None
            result_limbs = int(arm_facts[0][1])
        else:
            result_class = _builtin_scalar_operator_class(expression, operand_classes)
        if result_class is None:
            continue
        node_cell = node_identity_cell(graph, int(node_id))
        _concord_source_value_class(
            scope, value_id, result_class,
            precision_limbs=result_limbs,
            source="conditional scalar arm classes" if conditional_phi else "builtin scalar operator result",
            provenance=_Derived(tuple(dict.fromkeys(
                cell for cell in (node_cell, *operand_cells, *(
                    (node_identity_cell(graph, parents["test"]),) if conditional_phi else ()
                ))
                if cell is not None
            ))),
        )
        changed = True
    return changed


def _relink_settled_glyph_formatters(graph: Any, function_table: Any) -> None:
    """Relink canonical glyph recipes after call-edge classes settle.

    The program ``def f(x): return f"{x!r}"`` called once as ``f(a)`` with
    ``a: int`` lowered its recipe with the formatted component unresolved
    (``projection='scalar'``, no resident producer): the formal ``x`` has no
    annotation, so its class row is published by the call-edge settlement
    (``propagate_call_formal_numeric_types``: ``call actual render:0``),
    which runs after every function's recipe was authored and linked.  The
    rule now holding: the formatter link is the same read of the
    value-class row, repeated once the call-edge facts have settled; the
    recipe is REVISED from its cell and the new call's cell, and the call
    carries its ``call_binding`` row as a recipe-time formatter call does.

    The same timing applies to ``line.strip()`` when ``line`` is an
    unannotated formal or loop binding whose ``str`` class arrives from a
    call edge.  Its authored Call and receiver edge are still present here;
    revise the scalar component to the same resident StringTable projection
    that recipe-time recognition publishes, then retire the Call only when
    that formatted component is its sole consumer.
    """

    from ...compiler.planner_concordance_posts import _post_call_binding

    book = current_identity_book()
    metadata = graph.G.graph
    glyph_scope = metadata.get("source_glyph_sequence_scope")
    if glyph_scope is None:
        return
    value_class_scope = _source_numeric_scope(graph)
    for node_id, data in tuple(graph.G.nodes(data=True)):
        attributes = data.get("attributes") or {}
        row = attributes.get("source_glyph_sequence_row")
        if row is None or tuple(row[0]) != tuple(glyph_scope):
            continue
        glyph_cell = book.latest_ref(_SOURCE_GLYPH_SEQUENCE, tuple(row))
        if glyph_cell is None:
            continue
        fact = book.page(_SOURCE_GLYPH_SEQUENCE).cell(
            glyph_cell.row, glyph_cell.column,
        )
        if not isinstance(fact, _SourceGlyphSequence):
            continue
        settled_components = list(fact.components)
        settled_sources = [glyph_cell]
        settled_strip_operations = []
        for ordinal, component in enumerate(fact.components):
            if (
                component.kind != "formatted"
                or component.projection_kind != "scalar"
                or component.operand_value_id is None
                or component.formatted_sequence_value_id is not None
            ):
                continue
            operation_id = int(component.operand_value_id)
            if operation_id not in graph.G:
                continue
            operation_data = graph.G.nodes[operation_id]
            expression = operation_data.get("expr_obj")
            if not (
                isinstance(expression, ast.Call)
                and isinstance(expression.func, ast.Attribute)
                and expression.func.attr == "strip"
                and not expression.args
                and not expression.keywords
            ):
                continue
            receiver_id = next((
                int(parent)
                for parent, role in operation_data.get("parents", ())
                if str(role) == "operand"
            ), None)
            receiver_class, _receiver_width = (
                _resolved_source_value_class(graph, receiver_id)
            )
            if (
                receiver_id is None
                or _canonical_source_class_identity(receiver_class)
                != "builtins.str"
            ):
                continue
            operation_cell = node_identity_cell(graph, operation_id)
            receiver_cell = node_identity_cell(graph, receiver_id)
            receiver_class_cell = book.latest_ref(
                _SOURCE_VALUE_CLASS,
                (value_class_scope, int(receiver_id)),
            )
            sources = tuple(dict.fromkeys(filter(None, (
                operation_cell, receiver_cell, receiver_class_cell,
            ))))
            operation_data.setdefault("attributes", {}).update({
                "result_class_ref": "str",
                "string_token_transform": "strip",
            })
            _concord_source_value_class(
                value_class_scope,
                operation_id,
                "str",
                source="builtins.str.strip result",
                provenance=_Derived(sources),
            )
            settled_components[ordinal] = _dataclass_replace(
                component,
                operand_value_id=receiver_id,
                projection_kind="string_token",
                projection_source_value_id=receiver_id,
                projection_transform="strip",
                projection_operation_cell=operation_cell,
            )
            settled_sources.extend(sources)
            settled_strip_operations.append((
                operation_id, receiver_id, int(component.component_value_id),
            ))
        if tuple(settled_components) != tuple(fact.components):
            glyph_cell = book.post(
                _SOURCE_GLYPH_SEQUENCE,
                tuple(row),
                _SourceGlyphSequence(tuple(settled_components)),
                stage=_REDUCTION,
                provenance=_Derived(tuple(dict.fromkeys(settled_sources))),
                mode=_Mode.REVISE,
            )
            fact = book.page(_SOURCE_GLYPH_SEQUENCE).cell(
                glyph_cell.row, glyph_cell.column,
            )
            for operation_id, receiver_id, component_id in (
                settled_strip_operations
            ):
                graph.G.nodes[component_id].setdefault(
                    "attributes", {}
                ).update({
                    "producer_kind": "formatted_glyph_sequence",
                    "aggregate_kind": "list",
                    "sequence_key_columns": (),
                    "sequence_column_count": 1,
                    "sequence_writable": True,
                    "sequence_element_dtypes": ("int64",),
                })
                consumers = {
                    int(child)
                    for child, _role in (
                        graph.G.nodes[operation_id].get("children") or ()
                    )
                }
                if consumers == {component_id}:
                    _redirect_value(graph, operation_id, receiver_id)
        if not any(
            component.kind == "formatted"
            and component.projection_kind == "scalar"
            and component.operand_value_id is not None
            and component.formatted_sequence_value_id is None
            for component in fact.components
        ):
            continue
        components = _link_integer_glyph_formatter_calls(
            graph, function_table,
            row=tuple(row), glyph_cell=glyph_cell,
            components=fact.components,
            value_class_scope=value_class_scope,
            format_spec_scopes=(tuple(glyph_scope),),
            new_node=lambda node_type, label, *, attributes=None,
            parents=(), source_cell=None: _mint_settled_node(
                graph, node_type, label, attributes=attributes,
                parents=parents, source_cell=source_cell,
            ),
        )
        if tuple(components) == tuple(fact.components):
            continue
        for ordinal, component in enumerate(components):
            if (
                component.kind != "formatted"
                or component.formatted_sequence_value_id is None
                or fact.components[ordinal].formatted_sequence_value_id
                is not None
            ):
                continue
            call_id = int(component.formatted_sequence_value_id)
            graph.G.nodes[call_id].setdefault("attributes", {})[
                "source_glyph_component"
            ] = (tuple(row), int(ordinal))
            graph.G.nodes[int(component.component_value_id)].setdefault(
                "attributes", {}
            ).update({
                "producer_kind": "formatted_glyph_sequence",
                "aggregate_kind": "list",
                "sequence_key_columns": (),
                "sequence_column_count": 1,
                "sequence_writable": True,
                "sequence_element_dtypes": ("int64",),
                "source_glyph_component": (tuple(row), int(ordinal)),
            })
            _post_call_binding(
                graph, call_id,
                int(graph.G.nodes[call_id]["attributes"]["callee_ref"]),
                "callsite_shell",
            )



def _declared_sequence_return(definition: Any) -> bool:
    """True when the function's DECLARED return annotation is a sequence type.

    ``list``, ``list[...]``, ``List[...]``, ``Sequence[...]`` or a variadic
    ``tuple[T, ...]`` (the Ellipsis ends the TOP-LEVEL parameters), with one
    outer ``| None`` / ``Optional[...]`` tolerated.  A Tuple/List display at a
    return site of such a function is ONE sequence value (arity 1), not
    flattened into structural output slots; fixed ``tuple[A, B]``, ``Any`` and
    no annotation keep the flattening.
    """

    annotation = getattr(definition, "returns", None)
    if isinstance(annotation, ast.Constant) and isinstance(annotation.value, str):
        try:
            annotation = ast.parse(annotation.value, mode="eval").body
        except SyntaxError:
            return False

    def is_none(member: Any) -> bool:
        return (
            isinstance(member, ast.Constant) and member.value is None
        ) or (isinstance(member, ast.Name) and member.id == "None")

    def container_name(node: Any) -> str:
        return (
            node.id if isinstance(node, ast.Name)
            else node.attr if isinstance(node, ast.Attribute)
            else ""
        )

    if isinstance(annotation, ast.BinOp) and isinstance(annotation.op, ast.BitOr):
        concrete = tuple(
            member for member in (annotation.left, annotation.right)
            if not is_none(member)
        )
        if len(concrete) != 1:
            return False
        annotation = concrete[0]
    elif (
        isinstance(annotation, ast.Subscript)
        and container_name(annotation.value) == "Optional"
    ):
        annotation = annotation.slice
    name = container_name(
        annotation.value if isinstance(annotation, ast.Subscript) else annotation
    )
    if name in {"list", "List"}:
        return True
    if not isinstance(annotation, ast.Subscript):
        return False
    if name == "Sequence":
        return True
    if name in {"tuple", "Tuple"}:
        parameters = (
            tuple(annotation.slice.elts)
            if isinstance(annotation.slice, ast.Tuple)
            else (annotation.slice,)
        )
        return (
            len(parameters) == 2
            and isinstance(parameters[-1], ast.Constant)
            and parameters[-1].value is Ellipsis
        )
    return False


def _return_display_flattens(definition: Any, returned: Any) -> bool:
    """Whether a returned Tuple/List display is flattened into output slots."""

    return isinstance(returned, (ast.Tuple, ast.List)) and not (
        _declared_sequence_return(definition)
    )


def _normalize_lexical_values(
    function_graph: Any,
    statement: ast.FunctionDef | ast.AsyncFunctionDef,
    static_bindings: dict[str, Any],
    function_table: FunctionTable,
    lexical_function_bindings: dict[str, Any] | None = None,
    closure_aggregate_kinds: dict[str, str] | None = None,
    local_aggregate_kinds: dict[str, str] | None = None,
    local_mapping_contracts: Mapping[str, Mapping[str, Any]] | None = None,
    closure_names: Iterable[str] = (),
    method_owner: str | None = None,
    class_field_aggregate_kinds: Mapping[tuple[str, str], str] | None = None,
    class_field_mapping_contracts: Mapping[
        tuple[str, str], Mapping[str, Any]
    ] | None = None,
    class_field_sequence_dtypes: Mapping[
        tuple[str, str], tuple[str, ...]
    ] | None = None,
    class_field_sequence_element_classes: Mapping[
        tuple[str, str], str
    ] | None = None,
    class_field_sequence_records: Mapping[
        tuple[str, str], str
    ] | None = None,
    class_field_storage_contracts: Mapping[
        tuple[str, str], Mapping[str, Any]
    ] | None = None,
    class_field_classes: Mapping[tuple[str, str], str] | None = None,
    static_parameter_bindings: Mapping[str, Any] | None = None,
    authored_definitions_by_name: Mapping[
        str, tuple[ast.FunctionDef | ast.AsyncFunctionDef, ...]
    ] | None = None,
) -> dict[int, tuple[str, ...]]:
    """Resolve unique lexical occurrences into a monotonic value DAG.

    AST ingestion intentionally gives every ``Name`` occurrence its own node.
    At topological reduction, loads are consolidated against the definition
    visible at that program point.  Consumers then fan out directly from the
    defining value; source-language ``Load`` and ``Store`` wrappers disappear.
    """

    # The module a bare name in this definition resolves in first
    # (``FunctionTable.lexical_reference``): ``re.compile``'s ``_compile``
    # is ``re._compile``, never ``re._compiler._compile``.
    statement_identity = getattr(statement, "_python_source_identity", None)
    statement_module = (
        str(statement_identity[0])
        if isinstance(statement_identity, tuple) and len(statement_identity) == 2
        else None
    )
    graph = function_graph
    environment: dict[str, int] = {}
    static_environment: dict[str, _StaticPythonReference] = {}
    deleted_names: set[str] = set()
    identity_bindings: dict[str, list[int]] = {}
    # Exact AST ownership of assignment sites, not a source-line containment
    # guess. ``position = size`` executed inside a retained loop captures
    # THIS iteration's size; the same assignment before it freezes its seed.
    binding_loop_owners = {}
    ownership_frontier = [(statement, None)]
    while ownership_frontier:
        member, owner = ownership_frontier.pop()
        if isinstance(member, ast.Name) and isinstance(member.ctx, ast.Store):
            binding_loop_owners[id(member)] = owner
        if member is not statement and isinstance(member, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
            continue
        child_owner = id(member) if isinstance(member, (ast.For, ast.While, ast.AsyncFor)) else owner
        ownership_frontier.extend((child, child_owner) for child in ast.iter_child_nodes(member))
    ingestion_definitions: dict[str, list[tuple[int, dict[str, Any]]]] = {}
    loop_target_bindings_by_ast: dict[int, int] = {}
    static_reference_nodes: dict[tuple[int, str], int] = {}
    first_class_function_nodes: dict[int, int] = {}
    # StaticReference node -> the definition cell its row derives from; every
    # use row cites it (edges lane C).
    static_reference_definition_cells: dict[int, Any] = {}
    materialized_attribute_nodes: dict[int, int] = {}
    static_constant_nodes: dict[str, int] = {}
    # The reducer's field state is on the book (page ``reducer_field_state``,
    # one row per ``(scope, receiver, field)``, one revision per write or
    # merge; plan 70 section 1).  The only private state kept here is the
    # CURSOR: for every field row this reduction has touched, the cell that
    # is the field's current state at this program point.  The book is
    # append-only, so an arm's revisions stay on the row as history; the
    # cursor is captured at a conditional's entry and reset at each arm's
    # boundary, and the merge names the arm cells by their captured Refs.
    field_state_cursor: dict[tuple[int, str], _Ref] = {}
    #: ``(receiver name, field)`` pairs assigned anywhere in the body of each
    #: loop being reduced, innermost last.  The reducer merges no field state
    #: at a loop, so the first pass over a body sees no cursor for a field
    #: the body itself rewrites later; that read is not the construction's.
    loop_body_field_writes: list[frozenset[tuple[str, str]]] = []
    #: Local names passed (as an argument or a method receiver) to a call
    #: that may store into them.  A record this function constructs has no
    #: field storage the reducer reloads after such a call, so a later read
    #: of its field is refused rather than answered from the cursor.
    storing_call_receivers: set[str] = set()
    storing_call_effects: dict[int, list[int]] = {}
    #: The same names for each loop being reduced, innermost last: a call
    #: later in the body stores before the next iteration's read.
    loop_body_storing_receivers: list[frozenset[str]] = []
    storing_definitions = dict(authored_definitions_by_name or {})
    #: ``acc.add`` in ``acc.add(b)`` is a method lookup, not a field read.
    method_lookup_ids = {
        id(node.func) for node in ast.walk(statement)
        if isinstance(node, ast.Call)
    }
    parameter_store_cache: dict[tuple[int, str], bool] = {}

    def parameter_may_store(definition: Any, name: str) -> bool:
        """Whether ``definition`` may store into its parameter ``name``.

        Proven read-only only when every use is a loaded ``name.field``
        operand, or ``name.method(...)`` of a read-only method of that name.
        Anything else (a field or element store, the bare name escaping
        into a call, a return or an assignment) may store."""

        key = (id(definition), str(name))
        if key in parameter_store_cache:
            return parameter_store_cache[key]
        parameter_store_cache[key] = False  # recursion: assume read-only
        parents = {
            id(child): node
            for node in ast.walk(definition)
            for child in ast.iter_child_nodes(node)
        }
        stores = False
        for node in ast.walk(definition):
            if not (isinstance(node, ast.Name) and node.id == name):
                continue
            if isinstance(node.ctx, (ast.Store, ast.Del)):
                stores = True
                break
            attribute = parents.get(id(node))
            if not (
                isinstance(attribute, ast.Attribute)
                and attribute.value is node
                and isinstance(attribute.ctx, ast.Load)
            ):
                stores = True
                break
            outer = parents.get(id(attribute))
            if isinstance(outer, ast.Call) and outer.func is attribute:
                if callee_may_store(attribute.attr, receiver=True):
                    stores = True
                    break
                continue
            if isinstance(outer, ast.Attribute) or (
                isinstance(outer, ast.Subscript)
                and not isinstance(outer.ctx, ast.Load)
            ):
                stores = True
                break
        parameter_store_cache[key] = stores
        return stores

    def callee_may_store(
        callee: str, *, receiver: bool = False, position: int | None = None,
        keyword: str | None = None,
    ) -> bool:
        """Whether every authored definition named ``callee`` may store
        into the argument at ``position``/``keyword`` (its receiver when
        ``receiver``).  An unknown callee may store."""

        definitions = tuple(storing_definitions.get(str(callee), ()))
        if not definitions:
            return True
        for definition in definitions:
            arguments = (
                *definition.args.posonlyargs, *definition.args.args,
            )
            if receiver:
                index = 0
            elif position is not None:
                index = int(position) + (
                    1 if str(callee) != "__init__"
                    and arguments and arguments[0].arg in {"self"}
                    else 0
                )
            else:
                index = None
            if index is not None:
                if index >= len(arguments):
                    return True
                name = arguments[index].arg
            else:
                names = {
                    argument.arg for argument in (
                        *arguments, *definition.args.kwonlyargs,
                    )
                }
                if keyword not in names:
                    return True
                name = str(keyword)
            if parameter_may_store(definition, name):
                return True
        return False

    def storing_call_names(node: ast.AST) -> set[str]:
        """Names in ``node`` that a call may store into."""

        names: set[str] = set()
        for call in source_walk(node):
            if not isinstance(call, ast.Call):
                continue
            if (
                isinstance(call.func, ast.Attribute)
                and isinstance(call.func.value, ast.Name)
                and callee_may_store(call.func.attr, receiver=True)
            ):
                names.add(str(call.func.value.id))
            callee = (
                call.func.id if isinstance(call.func, ast.Name)
                else call.func.attr if isinstance(call.func, ast.Attribute)
                else None
            )
            for index, argument in enumerate(call.args):
                if isinstance(argument, ast.Name) and (
                    callee is None
                    or callee_may_store(callee, position=index)
                ):
                    names.add(str(argument.id))
            for keyword in call.keywords:
                if isinstance(keyword.value, ast.Name) and (
                    callee is None or keyword.arg is None
                    or callee_may_store(callee, keyword=keyword.arg)
                ):
                    names.add(str(keyword.value.id))
        return names
    #: Per loop being reduced, innermost last: ``(receiver, field) ->
    #: (name, pre-loop value id)`` for the fields of locally constructed
    #: records that the loop body writes.  At the loop exit each becomes a
    #: carried binding ``name.field`` (initial, body-exit value), exactly as
    #: a rebound name is carried.
    loop_field_entry_values: list[dict[tuple[int, str], tuple[str, int]]] = []

    def concord_carried_field_read(
        expression: ast.Attribute, receiver: int, attribute_id: int,
    ) -> None:
        """A read of a loop-carried field names its binding ``name.field``
        on its consumer edges, as a Name read does: the loop's header and
        exit choose per read, and an unattributed read of the initial is
        refused there."""

        if not isinstance(expression.value, ast.Name):
            return
        key = (int(receiver), str(expression.attr))
        cursor_cell = field_state_cursor.get(key)
        state = field_state_at(cursor_cell)
        carried = any(key in entries for entries in loop_field_entry_values) or (
            isinstance(state, _FieldState)
            and state.kind is _FieldStateKind.LOOP_EXIT
        )
        if not carried:
            return
        _concord_lexical_reads(
            graph, ingestion_read_scope, int(attribute_id),
            f"{expression.value.id}.{expression.attr}",
            binding_cell=cursor_cell or current_name_binding_cell(
                str(expression.value.id), int(receiver),
            ),
        )

    def constructed_field_value(name: str, attr: str) -> int | None:
        """The current value of field ``attr`` of the record ``name`` this
        function constructed: the field-state cursor's value, else the
        constructor argument that initialised it.  None when neither is
        known (no constructor schema, a nested call)."""

        receiver = environment.get(name)
        if not isinstance(receiver, int) or receiver not in graph.G:
            return None
        receiver_data = graph.G.nodes[int(receiver)]
        construction = receiver_data.get("expr_obj")
        class_identity = (receiver_data.get("attributes") or {}).get("class_ref")
        if not isinstance(construction, ast.Call) or class_identity is None:
            return None
        state = field_state_at(field_state_cursor.get((int(receiver), str(attr))))
        if isinstance(state, _FieldState):
            value = _cell_node_id(state.value)
            return int(value) if value is not None and value in graph.G else None
        if state is not None:
            return None
        records = dict(
            (graph.G.graph.get("program_abi") or {}).get("records") or {}
        )
        matching = tuple(
            record for record_name, record in records.items()
            if str(record_name) == str(class_identity)
            or str(record.get("identity") or record_name) == str(class_identity)
            or str(record.get("identity") or record_name).endswith(
                "." + str(class_identity)
            )
        )
        if len(matching) != 1 or matching[0].get("constructor_complete") is False:
            # A projection view is not a constructor schema: its field order
            # is not the constructor's argument order (``self.b = a``).
            return None
        field_names = tuple(map(str, dict(matching[0].get("fields") or {})))
        field_expression = next((
            keyword.value for keyword in construction.keywords
            if keyword.arg == attr
        ), None)
        if field_expression is None and attr in field_names:
            position = field_names.index(attr)
            if position < len(construction.args):
                field_expression = construction.args[position]
        if field_expression is None:
            return None
        value = resolve_expression(field_expression)
        return int(value) if isinstance(value, int) and value in graph.G else None

    # The most recent node that mutated ``(receiver_node_id, attr)`` --
    # a whole-attribute ``SetAttr`` or an element-wise ``obj.field[i, j] =``
    # ``IndexedStore``.  A later bare read of the same field consults this so
    # the read is ordered after the write instead of depending only on the
    # unchanged receiver node (see the read side in ``resolve_expression``).
    # Read view over ``FieldState.effect`` of the cursor cells.
    attribute_effect_nodes: Mapping[tuple[int, str], int] = _FieldStateView(
        field_state_cursor, "effect",
    )
    # Current field value, separate from the ordered write event. Explicit
    # GetAttr nodes remain in the graph for record-ABI projection; this view
    # only supplies exact incoming values when source control joins a write.
    # Read view over ``FieldState.value`` of the cursor cells.
    attribute_value_nodes: Mapping[tuple[int, str], int] = _FieldStateView(
        field_state_cursor, "value",
    )
    # Return-site receipts are pages keyed by the return site's node cell;
    # the legacy receipts were keyed by source span.  Site cell -> span.
    return_site_spans: dict[_Ref, tuple[int, int, int, int]] = {}
    parameter_names = set(function_parameter_names(statement))
    closure_names = frozenset(map(str, closure_names))
    static_parameter_bindings = dict(static_parameter_bindings or {})
    value_class_scope = _source_numeric_scope(
        graph, getattr(statement, "name", "<function>")
    )
    from ...compiler.concordance_declarations import SOURCE_LITERAL_VALUE
    for literal_id, literal_data in tuple(graph.G.nodes(data=True)):
        literal_expression = literal_data.get("expr_obj")
        if not isinstance(literal_expression, ast.Constant):
            continue
        literal_book = current_identity_book()
        literal_book.post(
            SOURCE_LITERAL_VALUE,
            (value_class_scope, int(literal_id)),
            literal_expression.value,
            stage=_REDUCTION,
            provenance=_Derived((node_identity_cell(graph, int(literal_id)),)),
            mode=_Mode.CONCORD,
        )
        literal_cell = literal_book.latest_ref(
            SOURCE_LITERAL_VALUE,
            (value_class_scope, int(literal_id)),
        )
        literal_class = (
            "builtins.bool"
            if isinstance(literal_expression.value, bool)
            else "builtins.int"
            if isinstance(literal_expression.value, int)
            else "builtins.float"
            if isinstance(literal_expression.value, float)
            else "builtins.str"
            if isinstance(literal_expression.value, str)
            else None
        )
        if literal_class is not None:
            _concord_source_value_class(
                value_class_scope,
                int(literal_id),
                literal_class,
                source="source literal value",
                provenance=_Derived((literal_cell,)),
            )
    # One reduction is one scope of read facts, minted by the book: rows at
    # ingestion ids (object addresses, unique only within this reduction)
    # and, after canonical renumbering, at canonical ids.  The graph names
    # its reduction scope, so every copy of it (a specialization) reads the
    # facts this reduction committed.
    read_scope = current_identity_book().mint_scope(
        f"lexical_reads:{value_class_scope}"
    )
    ingestion_read_scope = (read_scope, "ingestion")
    # The operand-position scope the graph arrived with: an extracted
    # subgraph's own fork (``fork_operand_position_scope``), else the build
    # scope.  The canonical relabel continues ITS rows, not the source's.
    entry_operand_scope = graph.G.graph.get("operand_position_scope")
    # Operand-position facts are keyed in the ingestion scope until canonical
    # renumbering; ``_set_operands`` moves them with every operand rewrite.
    graph.G.graph["operand_position_scope"] = ingestion_read_scope
    field_state_book = current_identity_book()
    # Exact lexical aliases introduced by ``with book.borrowed('page') as
    # rows``.  The module-level page declaration fact owns both the fact
    # class and the ordered row-key ABI; calls below retain its cell instead
    # of rebuilding either from a local variable name.
    borrowed_page_bindings: dict[str, _Ref] = {}
    # An aggregate field can acquire its tuple layout from the exact Page key
    # position that consumes it. Keep the receiver/field identity so a later
    # occurrence (including a repr projection synthesized below) reads the
    # same declaration cell instead of copying a guessed tuple schema.
    page_key_field_schemas: dict[tuple[int, str], _Ref] = {}
    declared_pages = dict(
        graph.G.graph.get("declared_page_fact_classes") or {}
    )
    declared_page_bindings = dict(
        graph.G.graph.get("declared_page_bindings") or {}
    )

    def source_page_declaration(cell: Any) -> _SourcePageFactClass | None:
        """Resolve one Page value through its authoritative source cell."""

        if not isinstance(cell, _Ref) or cell.page != _SOURCE_PAGE_FACT_CLASS:
            return None
        book = current_identity_book()
        if book.latest_ref(_SOURCE_PAGE_FACT_CLASS, cell.row) != cell:
            return None
        fact = book.page(_SOURCE_PAGE_FACT_CLASS).cell(
            cell.row, cell.column,
        )
        if not isinstance(fact, _SourcePageFactClass):
            return None
        if (
            len(cell.row) != 2
            or str(cell.row[1]) != str(fact.page_name)
            or not str(fact.class_identity)
            or not isinstance(fact.row_fields, tuple)
        ):
            return None
        return fact

    def page_fact_class_name(cell: Any) -> str | None:
        """The page's fact class as the class table names it: the
        ``class_declaration`` row the page declaration derives from (its
        ``class_identity`` is the module-qualified spelling)."""

        if source_page_declaration(cell) is None:
            return None
        class_cell = next((
            source for source, _stage in current_identity_book().edges_into(cell)
            if source.page == _CLASS_DECLARATION
        ), None)
        return None if class_cell is None else str(class_cell.row[1])
    for owner in ast.walk(statement):
        if not isinstance(owner, (ast.With, ast.AsyncWith)):
            continue
        for item in owner.items:
            context = item.context_expr
            if not (
                isinstance(item.optional_vars, ast.Name)
                and isinstance(context, ast.Call)
                and isinstance(context.func, ast.Attribute)
                and context.func.attr == "borrowed"
                and len(context.args) == 1
                and isinstance(context.args[0], ast.Constant)
                and isinstance(context.args[0].value, str)
            ):
                continue
            declared = declared_pages.get(str(context.args[0].value))
            if declared is not None:
                declaration_cell = declared[1]
                if source_page_declaration(declaration_cell) is not None:
                    borrowed_page_bindings[str(item.optional_vars.id)] = (
                        declaration_cell
                    )
    page_key_binding_field_schemas: dict[tuple[str, str], _Ref] = {}
    ambiguous_page_key_binding_fields: set[tuple[str, str]] = set()
    for candidate in ast.walk(statement):
        if not (
            isinstance(candidate, ast.Call)
            and isinstance(candidate.func, ast.Attribute)
            and candidate.func.attr == "latest"
            and isinstance(candidate.func.value, ast.Name)
            and len(candidate.args) == 1
            and isinstance(candidate.args[0], ast.Attribute)
            and isinstance(candidate.args[0].value, ast.Name)
        ):
            continue
        declaration_cell = borrowed_page_bindings.get(
            candidate.func.value.id
        )
        if source_page_declaration(declaration_cell) is None:
            continue
        field_key = (
            str(candidate.args[0].value.id),
            str(candidate.args[0].attr),
        )
        incumbent = page_key_binding_field_schemas.get(field_key)
        if field_key in ambiguous_page_key_binding_fields:
            continue
        if incumbent is not None and incumbent != declaration_cell:
            page_key_binding_field_schemas.pop(field_key, None)
            ambiguous_page_key_binding_fields.add(field_key)
        else:
            page_key_binding_field_schemas[field_key] = declaration_cell

    def post_source_literal_glyph_sequence(node_id: int) -> Any:
        """Publish one authored string literal before graph rewriting.

        The literal's reversible glyph sequence is a source fact over its
        ingestion identity.  Canonical relabeling may derive a new row from
        this cell, but no later pass is allowed to reconstruct the payload by
        rereading ``expr_obj`` after wrappers and identities have changed.
        """

        if int(node_id) not in graph.G:
            return None
        data = graph.G.nodes[int(node_id)]
        expression = data.get("expr_obj")
        if not (
            isinstance(expression, ast.Constant)
            and isinstance(expression.value, str)
        ):
            return None
        from ...compiler.string_table import string_token

        row = (value_class_scope, int(node_id))
        fact = _SourceGlyphSequence((_SourceGlyphComponent(
            kind="literal",
            component_value_id=int(node_id),
            operand_value_id=None,
            glyph_tokens=tuple(
                int(string_token(character))
                for character in expression.value
            ),
            conversion=-1,
            format_spec_value_id=None,
            projection_kind="literal",
            record_identity=None,
        ),))
        book = current_identity_book()
        page = book.page(_SOURCE_GLYPH_SEQUENCE)
        incumbent = page.latest(row)
        if incumbent is not None and incumbent != fact:
            raise ValueError(
                "source literal glyph sequence concordance disagreement for "
                f"{row!r}: recorded={incumbent!r}, proposed={fact!r}"
            )
        cell = book.latest_ref(_SOURCE_GLYPH_SEQUENCE, row)
        if cell is None:
            source_cell = node_identity_cell(graph, int(node_id))
            if source_cell is None:
                return None
            cell = book.post(
                _SOURCE_GLYPH_SEQUENCE,
                row,
                fact,
                stage=_REDUCTION,
                provenance=_Derived((source_cell,)),
                mode=_Mode.CONCORD,
            )
        data.setdefault("attributes", {})[
            "source_literal_glyph_sequence_row"
        ] = row
        return cell

    # Do this while every authored Constant still has its ingestion identity.
    # A restored literal created later calls the same writer immediately.
    for literal_node_id in tuple(graph.G.nodes):
        post_source_literal_glyph_sequence(int(literal_node_id))
    # The legacy return receipts are read views over the return-site pages,
    # keyed by span through ``return_site_spans`` and read under the graph's
    # current operand-position scope (plan 70, section 2).
    #
    # The site cell -> span join is the graph's own record, not only the
    # views': the views pickle as the plain span-keyed dicts they present,
    # and a ``return <name>`` site's occurrence node (the cell's node) is
    # removed when the name resolves, so across the worker boundary
    # (``_dump_scoped_resolved_process_graph``) nothing else carried which
    # authored exit each span is.  Observed on ``prefixed_lower_hex_
    # integer_glyph_tokens`` (census 2026-10-17, unit 47): its three
    # ``return result`` sites reached the worker with no site cell, the
    # control builder stamped no ``return_site_cell`` on the early-return
    # edges, and the composing unit's audit refused the product
    # ("return-site-edge-disagreement").  ``return_site_cells`` reads this
    # join first; the scoped-input acceptance roots its cells.
    graph.G.graph["return_site_spans"] = return_site_spans
    graph.G.graph["return_slot_values"] = _ReturnSiteView(
        field_state_book, graph, _RETURN_SITE_SLOT, return_site_spans,
        _return_slot_receipt,
    )
    graph.G.graph["return_record_field_states"] = _ReturnSiteView(
        field_state_book, graph, _RETURN_SITE_FIELD_STATE, return_site_spans,
        _return_field_state_receipt,
    )
    graph.G.graph["return_container_kinds"] = _ReturnSiteView(
        field_state_book, graph, _RETURN_SITE_CONTAINER, return_site_spans,
        _return_container_receipt,
    )

    def field_state_row(receiver: int, attr: str) -> tuple:
        return (ingestion_read_scope, int(receiver), str(attr))

    def receiver_class_identity(receiver: int) -> str | None:
        """The receiver's class as the source-value class concordance holds
        it, else as its ``result_class_ref`` graph view names it."""

        fact = field_state_book.page(
            "source_value_class_concordance"
        ).latest((value_class_scope, int(receiver)))
        if isinstance(fact, tuple) and fact:
            return str(fact[0])
        if receiver in graph.G:
            attributes = graph.G.nodes[receiver].get("attributes") or {}
            for key in ("result_class_ref", "class_ref"):
                if attributes.get(key) is not None:
                    return str(attributes[key])
        return None

    def field_schema_cell(receiver: int, attr: str) -> _Ref | None:
        """The ``class_field_declaration`` cell for the receiver's class and
        ``attr`` when the class is known and step 2 posted the row."""

        class_identity = receiver_class_identity(receiver)
        return declared_field_schema_cell(class_identity, attr)

    def declared_field_schema_cell(
        class_identity: str | None, attr: str,
    ) -> _Ref | None:
        if class_identity is None:
            return None
        page = field_state_book.pages.get(_CLASS_FIELD_DECLARATION.name)
        if page is None:
            return None
        # Imported Vocabulary publishes both Vocabulary and its qualified
        # alias.  Suffix matching made that one exact owner look ambiguous,
        # so every dictionary GetAttr lost its declaration cell.  The
        # authored module and exact receiver owner already name the row.
        if isinstance(value_class_scope, tuple) and value_class_scope:
            exact_row = (
                str(value_class_scope[0]), str(class_identity), str(attr),
            )
            if page.latest(exact_row) is not None:
                return field_state_book.latest_ref(
                    _CLASS_FIELD_DECLARATION, exact_row,
                )
        imported_classes = {
            id(value): value for name, value in dict(static_bindings or {}).items()
            if isinstance(value, type) and (
                str(name) == str(class_identity)
                or f"{value.__module__}.{value.__qualname__}" == str(class_identity)
            )
        }
        if len(imported_classes) == 1:
            declared_class = next(iter(imported_classes.values()))
            exact_row = (str(declared_class.__module__),
                         str(declared_class.__qualname__), str(attr))
            if page.latest(exact_row) is not None:
                return field_state_book.latest_ref(_CLASS_FIELD_DECLARATION, exact_row)
        matches = tuple(
            row for row in page.rows()
            if len(row) == 3
            and (
                str(row[1]) == str(class_identity)
                or str(row[1]).endswith("." + str(class_identity))
            )
            and str(row[2]) == str(attr)
            and page.latest(row) is not None
        )
        if len(matches) != 1:
            return None
        return field_state_book.latest_ref(
            _CLASS_FIELD_DECLARATION, matches[0]
        )

    def field_state_sources(receiver: int, attr: str, *cells: Any) -> tuple:
        """DERIVED cells for a field-state post: the receiver's node cell,
        the field schema cell when it exists (else the receiver's cell
        again, which dedups), then ``cells`` in order."""

        receiver_cell = node_identity_cell(graph, int(receiver))
        schema = field_schema_cell(receiver, attr) or receiver_cell
        ordered: list = []
        for cell in (receiver_cell, schema, *cells):
            if isinstance(cell, _Ref) and cell not in ordered:
                ordered.append(cell)
        return tuple(ordered)

    def post_field_state(
        receiver: int,
        attr: str,
        kind: Any,
        value_id: int,
        effect_id: int,
        *,
        sources: tuple,
        stage: Any,
    ) -> _Ref:
        """One REVISE on the field's row; the cursor moves to the new cell."""

        cell = field_state_book.post(
            _REDUCER_FIELD_STATE, field_state_row(receiver, attr),
            _FieldState(
                kind,
                node_identity_cell(graph, int(value_id)),
                node_identity_cell(graph, int(effect_id)),
            ),
            stage=stage, provenance=_Derived(sources), mode=_Mode.REVISE,
        )
        field_state_cursor[(int(receiver), str(attr))] = cell
        return cell

    def field_state_at(cell: Any) -> Any:
        return _cell_fact(field_state_book, cell)

    #: A bare ``return name`` has no consumer edge: its value becomes a root.
    #: The bindings each returned root value was returned under, each with
    #: the ``Name`` occurrences that returned it (their span cells stand for
    #: the read when the root node is gone from the graph).
    return_root_bindings: dict[int, dict[str, list[ast.Name]]] = {}
    # A parameter annotated with an ingested class name gives a
    # receiver a real, known class identity at ingestion -- enough to
    # resolve ``receiver.attr`` through the class's own navigation table
    # (below) instead of inventing a name for it.  Only a bare ``Name``
    # annotation naming a class this source itself defines counts; anything
    # else leaves the receiver's class unknown here, and attribute access on
    # it is not slot-resolvable. Numeric wrapper annotations are allowed to be
    # generic (``ComplexRationalPrecision[2]``): source admission has already
    # made their class identity part of this same navigation table, and the
    # normalized descriptor supplies the bare authoritative identity.
    #
    # ``build_class_navigation_table`` needs only ``map_ir`` (ingestion-time,
    # AST-derived) and ``function_table`` for method references; both are
    # already populated on ``graph`` before reduction runs -- but this
    # function is called once per *function* being reduced, and
    # ``build_class_navigation_table`` is a real, previously whole-
    # compilation-scoped call (``aot_compile.py``, after all reduction
    # finishes).  Memoized on the graph itself so it still runs exactly
    # once per graph, not once per method of a retained class with many
    # methods -- calling it repeatedly, interleaved with other functions'
    # own active reduction, is not a cost concern here so much as an
    # unreviewed-reentrancy risk against shared reduction state.
    navigation_table = graph.G.graph.get("_class_navigation_table")
    if navigation_table is None:
        navigation_table = build_class_navigation_table(graph)
        graph.G.graph["_class_navigation_table"] = navigation_table
    parameter_class_names: dict[str, str] = {}
    parameter_numeric_descriptors: dict[str, NumericFeatureDescriptor] = {}
    parameter_aggregate_kinds: dict[str, str] = {}
    parameter_sequence_record_widths: dict[str, int] = {}
    parameter_sequence_element_classes: dict[str, str] = {}
    parameter_mapping_value_classes: dict[str, str] = {}
    known_class_identities = {
        record.identity for record in navigation_table.classes
    }
    # Imported authored classes are resolved into the function's static
    # bindings before lexical normalization.  Their local binding name is
    # the same identity used by the imported field-schema indexes below
    # (``from ...dt_scaler import Metrics`` -> ``Metrics``); admit that exact
    # declared parameter class alongside source-local navigation records.
    known_class_identities.update(
        str(name)
        for name, value in dict(static_bindings or {}).items()
        if (
            isinstance(value, type)
            and value is not Any
            and value is not object
        )
    )
    # Program: ``close_region_feed_set(program: FusedProgram)``, a nested
    # function whose ``FusedProgram`` is an imported class.  Wrong record:
    # SOURCE_VALUE_CLASS was posted under the bare spelling ``FusedProgram``
    # while the ProgramABI contract carries the canonical identity, so one
    # class had two keys.  Rule: a class admitted through ``static_bindings``
    # is posted under that record's canonical identity (module.qualname),
    # never its spelling; source-local records are already canonical.
    canonical_known_class_identities = {
        str(name): f"{value.__module__}.{value.__qualname__}"
        for name, value in dict(static_bindings or {}).items()
        if (
            isinstance(value, type)
            and value is not Any
            and value is not object
        )
    }
    canonical_known_class_identities.update({
        record.identity: record.identity for record in navigation_table.classes
    })
    primitive_class_identities = {
        "bool": "builtins.bool",
        "builtins.bool": "builtins.bool",
        "float": "builtins.float",
        "builtins.float": "builtins.float",
        "int": "builtins.int",
        "builtins.int": "builtins.int",
        "str": "builtins.str",
        "builtins.str": "builtins.str",
    }

    local_class_declarations: dict[str, tuple[str, Any]] = {}
    local_sequence_element_declarations: dict[str, tuple[str, Any]] = {}
    source_identity = getattr(statement, "_python_source_identity", None)
    function_identity = (
        str(source_identity[1])
        if isinstance(source_identity, tuple) and len(source_identity) == 2
        else str(getattr(
            statement, "_turing_source_qualname", statement.name,
        ))
    )
    source_schema = dict(
        (graph.G.graph.get("map_ir") or {}).get("schema") or {}
    )
    annotation_page = _ANNOTATION_DECLARATION
    for function_schema in tuple(source_schema.get("functions") or ()):
        if str(function_schema.get("identity") or "") != function_identity:
            continue
        for declaration in tuple(function_schema.get("locals") or ()):
            try:
                annotation_expression = ast.parse(
                    str(declaration.get("annotation") or ""), mode="eval",
                ).body
            except SyntaxError:
                continue
            name = str(declaration["name"])
            span_row = tuple(declaration.get("ast_node_id") or ())
            annotation_cell = (
                current_identity_book().latest_ref(
                    annotation_page,
                    (span_row[0], str(span_row[1]), name),
                )
                if len(span_row) >= 2 else None
            )
            if isinstance(annotation_expression, ast.Subscript):
                aggregate = annotation_expression.value
                aggregate_name = (
                    aggregate.id if isinstance(aggregate, ast.Name)
                    else aggregate.attr if isinstance(aggregate, ast.Attribute)
                    else ""
                )
                element = annotation_expression.slice
                if (
                    isinstance(element, ast.Tuple)
                    and len(element.elts) == 2
                    and isinstance(element.elts[1], ast.Constant)
                    and element.elts[1].value is Ellipsis
                ):
                    element = element.elts[0]
                element_name = (
                    element.id if isinstance(element, ast.Name)
                    else element.attr if isinstance(element, ast.Attribute)
                    else None
                )
                element_class = primitive_class_identities.get(
                    str(element_name)
                ) or (
                    str(element_name)
                    if element_name in known_class_identities else None
                )
                if (
                    aggregate_name in {
                        "Sequence", "Iterable", "Collection", "List", "list",
                        "Tuple", "tuple", "Set", "set", "FrozenSet",
                        "frozenset",
                    }
                    and element_class is not None
                    and annotation_cell is not None
                ):
                    local_sequence_element_declarations[name] = (
                        str(element_class), annotation_cell,
                    )
            annotation_members = [annotation_expression]
            class_identities = []
            valid_class_annotation = True
            while annotation_members:
                member = annotation_members.pop()
                if isinstance(member, ast.BinOp) and isinstance(
                    member.op, ast.BitOr,
                ):
                    annotation_members.extend((member.right, member.left))
                elif (
                    isinstance(member, ast.Constant) and member.value is None
                ) or (
                    isinstance(member, ast.Name) and member.id == "None"
                ):
                    continue
                elif (
                    isinstance(member, ast.Name)
                    and member.id in known_class_identities
                ):
                    class_identities.append(member.id)
                elif (
                    member is annotation_expression
                    and isinstance(member, ast.Name)
                    and member.id in primitive_class_identities
                ):
                    # A bare primitive annotation (``x: str``) declares the
                    # local's class exactly; a ``T | None`` union does not
                    # (the None arm has no single class), so it is not
                    # admitted here.
                    class_identities.append(
                        primitive_class_identities[member.id]
                    )
                else:
                    valid_class_annotation = False
                    break
            distinct_class_identities = tuple(dict.fromkeys(
                class_identities
            ))
            if (
                not valid_class_annotation
                or len(distinct_class_identities) != 1
            ):
                continue
            annotation = distinct_class_identities[0]
            local_class_declarations[name] = (
                annotation,
                annotation_cell,
            )

    def annotation_aggregate_kind(annotation: ast.AST | None) -> str | None:
        if isinstance(annotation, ast.Name) and annotation.id in {
            "list", "set", "frozenset", "dict", "tuple", "bytes",
            "bytearray",
        }:
            return annotation.id
        if isinstance(annotation, ast.Subscript):
            return annotation_aggregate_kind(annotation.value)
        if isinstance(annotation, ast.BinOp) and isinstance(
            annotation.op, ast.BitOr,
        ):
            kinds = tuple(filter(None, (
                annotation_aggregate_kind(annotation.left),
                annotation_aggregate_kind(annotation.right),
            )))
            return kinds[0] if len(set(kinds)) == 1 else None
        return None

    for argument in (
        *statement.args.posonlyargs,
        *statement.args.args,
        *statement.args.kwonlyargs,
    ):
        annotation = argument.annotation
        numeric_descriptor = numeric_feature_descriptor(annotation)
        declared_class_identity = (
            numeric_descriptor.type_name
            if numeric_descriptor is not None
            else annotation.id if isinstance(annotation, ast.Name) else None
        )
        if numeric_descriptor is not None:
            parameter_class_names[argument.arg] = str(
                numeric_descriptor.type_name
            )
            parameter_numeric_descriptors[argument.arg] = numeric_descriptor
        elif (
            declared_class_identity is not None
            and declared_class_identity in known_class_identities
        ):
            parameter_class_names[argument.arg] = declared_class_identity
        elif str(declared_class_identity) in primitive_class_identities:
            parameter_class_names[argument.arg] = (
                primitive_class_identities[str(declared_class_identity)]
            )
        aggregate_kind = annotation_aggregate_kind(annotation)
        if aggregate_kind is not None:
            parameter_aggregate_kinds[argument.arg] = aggregate_kind
        aggregate_annotation = annotation
        if isinstance(annotation, ast.BinOp) and isinstance(annotation.op, ast.BitOr):
            # Vocabulary._intern_validated_span's optional fingerprint has
            # tuple[int, int] | None. Its present-arm indexed values lost
            # their class because only the outer aggregate reader unwrapped
            # the union. An optional container retains its element contract;
            # this does not claim the container itself is always present.
            pending_annotations = [annotation]
            present_annotations = []
            while pending_annotations:
                member = pending_annotations.pop()
                if isinstance(member, ast.BinOp) and isinstance(member.op, ast.BitOr):
                    pending_annotations.extend((member.left, member.right))
                elif isinstance(member, ast.Constant) and member.value is None:
                    continue
                else:
                    present_annotations.append(member)
            if len(present_annotations) == 1:
                aggregate_annotation = present_annotations[0]
        # Lane D, D2.  Program: ``def bump(d: dict[int, int], n): d[0] +=
        # n``.  A mapping annotation names its value class second; nothing
        # recorded it, so the formal's rows took the float64 domain default
        # and the int64 store disagreed with them.  Rule: ``dict[K, V]``
        # with a primitive ``V`` declares the mapping's value class (kept
        # apart from the sequence element class: iterating a dict yields
        # its keys).
        if (
            isinstance(aggregate_annotation, ast.Subscript) and aggregate_kind == "dict"
            and isinstance(aggregate_annotation.slice, ast.Tuple)
            and len(aggregate_annotation.slice.elts) == 2
            and isinstance(aggregate_annotation.slice.elts[1], ast.Name)
            and aggregate_annotation.slice.elts[1].id in primitive_class_identities
        ):
            parameter_mapping_value_classes[argument.arg] = (
                primitive_class_identities[aggregate_annotation.slice.elts[1].id]
            )
        if isinstance(aggregate_annotation, ast.Subscript) and aggregate_kind in {
            "list", "set", "frozenset", "tuple",
        }:
            element = aggregate_annotation.slice
            element_identity = (
                element.id if isinstance(element, ast.Name) else None
            )
            # Lane D, D2.  Program: ``def first(xs: tuple[int, int]): return
            # xs[0]`` (corpus c184).  A tuple annotation spells one class per
            # position, so its slice is a Tuple, not a Name, and nothing was
            # recorded: the callee's rows took the float64 domain default.
            # Rule: a tuple annotation whose positions all name one class
            # (``tuple[int, int]``, or ``tuple[int, ...]``) declares that
            # element class; positions of different classes declare none.
            if (
                aggregate_kind == "tuple"
                and isinstance(element, ast.Tuple)
                and element.elts
            ):
                positions = [
                    item for item in element.elts
                    if not (
                        isinstance(item, ast.Constant)
                        and item.value is Ellipsis
                    )
                ]
                names = {
                    item.id if isinstance(item, ast.Name) else None
                    for item in positions
                }
                if len(names) == 1 and None not in names and (
                    len(positions) == len(element.elts)
                    or (len(positions) == 1 and len(element.elts) == 2)
                ):
                    element_identity = next(iter(names))
            if element_identity in primitive_class_identities:
                parameter_sequence_element_classes[argument.arg] = (
                    primitive_class_identities[element_identity]
                )
            elif element_identity in known_class_identities:
                parameter_sequence_element_classes[argument.arg] = str(
                    element_identity
                )
    for parameter_name, record in dict(
        graph.G.graph.get("parameter_sequence_record_abi") or {}
    ).items():
        # NOT named ``fields``: this function also closes over
        # ``static_reference_node``, which calls ``dataclasses.fields``. A
        # local of that name here makes ``fields`` a local of the WHOLE
        # enclosing scope, so the nested call resolves to this cell instead
        # of the import and raises "cannot access free variable 'fields'"
        # on any path that reaches the nested function before this loop.
        record_fields = tuple(dict(record.get("fields") or {}))
        if not record_fields:
            continue
        parameter_aggregate_kinds[str(parameter_name)] = str(
            record.get("aggregate_kind") or "tuple"
        )
        parameter_sequence_record_widths[str(parameter_name)] = len(record_fields)
    # Source pursuit records an explicitly constructed local aggregate by
    # its class (``opt_subs = {}`` -> ``opt_subs: dict``).  For a nested
    # function that name is captured runtime storage, not a compile-time
    # reference to the ``dict`` constructor.  Preserve that distinction at
    # the function boundary so indexed mutation receives a real SSA input.
    parameter_aggregate_kinds.update(closure_aggregate_kinds or {})
    parameter_aggregate_kinds.update(local_aggregate_kinds or {})
    parameter_aggregate_kinds.update(
        dict(
            getattr(statement, "_python_aggregate_binding_kinds", {}) or {}
        )
    )

    def _resolve_instance_attribute_slot(
        class_identity: str, attribute_name: str
    ) -> int | None:
        """A field's real position in ``class_identity``'s layout, or ``None``.

        Permission evaluation here is deliberately permissive: this call
        resolves *structural* identity for SSA construction (which slot),
        the same question ``resolve_dot`` answers for real elsewhere in the
        compiler -- it does not enforce access policy.  A denied/ambiguous
        resolution is a fact about the source (an unknown or non-attribute
        member), not a security decision, so it is treated as "not slot-
        resolvable" rather than raised.
        """

        try:
            member = navigation_table.resolve_dot(
                canonical_known_class_identities.get(class_identity, class_identity),
                attribute_name,
                lambda _identity, _permissions: True,
                receiver_kind="instance",
            )
        except (KeyError, PermissionError):
            return None
        return member.slot if member.kind == "attribute" else None
    exception_local_names = {
        target.id
        for handler in (
            node
            for node in source_walk(statement)
            if isinstance(node, ast.ExceptHandler)
        )
        for body_node in handler.body
        for assignment in source_walk(body_node)
        if isinstance(assignment, (ast.Assign, ast.AnnAssign, ast.AugAssign))
        for target in (
            (*assignment.targets,)
            if isinstance(assignment, ast.Assign)
            else (assignment.target,)
        )
        if isinstance(target, ast.Name)
    }
    scalar_loop_target_ast_ids: set[int] = set()

    def target_name_nodes(target: ast.AST) -> tuple[ast.Name, ...]:
        if isinstance(target, ast.Name):
            return (target,)
        if isinstance(target, (ast.Tuple, ast.List)):
            return tuple(
                name
                for element in target.elts
                for name in target_name_nodes(element)
            )
        return ()

    for loop in source_walk(statement):
        if not (
            isinstance(loop, ast.For)
            and isinstance(loop.iter, ast.Call)
            and isinstance(loop.iter.func, ast.Name)
        ):
            continue
        if loop.iter.func.id == "range":
            scalar_loop_target_ast_ids.update(
                id(name) for name in target_name_nodes(loop.target)
            )
        elif loop.iter.func.id == "enumerate":
            if isinstance(loop.target, (ast.Tuple, ast.List)) and loop.target.elts:
                scalar_loop_target_ast_ids.update(
                    id(name)
                    for name in target_name_nodes(loop.target.elts[0])
                )
    scalar_loop_binding_ids: set[int] = set()
    # Every ``return`` of THIS function names its output slots -- not only a
    # return that happens to sit at the top level of the body. Scanning
    # ``source_body_statements`` alone left a function whose returns are all
    # inside a loop or conditional (``while True: ... return a, b, c``)
    # with no ``function_outputs`` at all, so the per-Return identity
    # recording below never ran, the hierarchy plan built its PlanCall with
    # ``result_bindings=()``, and every caller bound zero of the callee's
    # outputs ("unmaterialized_result", 15 real outputs unbound -- diagnosed
    # against the real managed-tire compile, ``step_with_dt_control_used``).
    # Nested definitions own their own returns and are not walked into.
    def function_return_statements(definition: Any) -> tuple[Any, ...]:
        returns: list[Any] = []
        stack = list(reversed(source_body_statements(definition)))
        while stack:
            current = stack.pop()
            if isinstance(current, (
                ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda, ast.ClassDef,
            )):
                continue
            if isinstance(current, ast.Return):
                returns.append(current)
                continue
            stack.extend(reversed(source_child_nodes(current)))
        return tuple(returns)

    return_expression_lists = tuple(
        (
            tuple(returned.elts)
            if _return_display_flattens(statement, returned)
            else (returned,)
        )
        for return_statement in function_return_statements(statement)
        for returned in (return_statement.value,)
        if returned is not None
    )
    # ``return_arms_kind``: the classification of a function whose returns
    # disagree on arity (None when they agree, or when they cannot be
    # classified).  Read by the Return reduction (which then names the one
    # output instead of binding per-slot) and by ``post_return_output_arms``.
    return_arms_kind: _ReturnArmsKind | None = None
    return_arms_unclassified = False
    # In-flight cells of each reduced return site (site cell, container
    # cell, slot cells, authored-None flag): the cells ``book.post``
    # returned, collected only so ``post_return_output_arms`` can derive the
    # arms record from them at the end of the walk.
    return_arm_posts: list = []
    # Site cells of the returns that are the function's final top-level
    # statement (the lexical epilogue's edge; see ``ReturnArm.tail``).
    return_tail_sites: set = set()
    if return_expression_lists:
        arities = {len(expressions) for expressions in return_expression_lists}
        if len(arities) != 1:
            # ``_resolved`` (``-> tuple[int, int] | None``: ``return None`` /
            # ``return row, column``) and ``-> tuple[int, ...]`` (``return ()``
            # / ``return (n,)``).  The record here was
            # ``function_output_shortfall``, which nothing read, so no
            # ``function_outputs`` existed and each return became its own
            # Phi layout.  Rule now holding: the returns are the ARMS of one
            # output ``result_0``, classified from the AUTHORED arms alone:
            # an authored ``None`` constant arm (length 0, absent) makes it
            # an OPTIONAL_AGGREGATE (present arms must agree in length >= 1);
            # no absent arm and unequal lengths is VARIADIC; anything else is
            # Unresolved(return_arms_unclassified), posted at the end of the
            # walk.
            arm_shapes = []
            for return_statement in function_return_statements(statement):
                returned_arm = return_statement.value
                if returned_arm is None:
                    continue
                absent_arm = (
                    isinstance(returned_arm, ast.Constant)
                    and returned_arm.value is None
                )
                arm_shapes.append((
                    absent_arm,
                    0 if absent_arm
                    else len(returned_arm.elts)
                    if _return_display_flattens(statement, returned_arm)
                    else 1,
                ))
            present_lengths = {
                length for absent_arm, length in arm_shapes if not absent_arm
            }
            if any(absent_arm for absent_arm, _length in arm_shapes):
                if len(present_lengths) == 1 and min(present_lengths) >= 1:
                    return_arms_kind = _ReturnArmsKind.OPTIONAL_AGGREGATE
            elif len(present_lengths) > 1:
                return_arms_kind = _ReturnArmsKind.VARIADIC
            if return_arms_kind is None:
                return_arms_unclassified = True
            else:
                graph.G.graph["function_outputs"] = ("result_0",)
                graph.G.graph["positional_output_names"] = ("result_0",)
        else:
            arity = next(iter(arities))
            # A slot keeps its authored name only when EVERY return spells
            # that slot as the same name; otherwise it is positional.
            slot_names = []
            positional_names = []
            for index in range(arity):
                names = {
                    expressions[index].id
                    if isinstance(expressions[index], ast.Name)
                    else None
                    for expressions in return_expression_lists
                }
                if len(names) == 1 and None not in names:
                    slot_names.append(names.pop())
                else:
                    slot_names.append(f"result_{index}")
                    positional_names.append(slot_names[-1])
            graph.G.graph["function_outputs"] = tuple(slot_names)
            # A positional slot's identity history is a list of ALTERNATIVE
            # return values (one per return site), not the version chain of
            # a rebound variable. Consumers that merge variable versions
            # across conditionals (`_ordinary_conditional_control_programs`)
            # must not treat it as one, or every earlier return's value is
            # aliased onto the next return's (measured as degenerate
            # `Phi [329, 329]` merges and "last return wins" outputs).
            graph.G.graph["positional_output_names"] = tuple(positional_names)
    def new_node(
        node_type: str,
        label: str,
        *,
        attributes: dict[str, Any] | None = None,
        parents: tuple[tuple[int, str], ...] = (),
        source: Any = None,
        source_cell: Any = None,
        cause: Any = _REDUCER_SYNTHESIS,
    ) -> int:
        # ``cause``: the Transform the caller names for this node's operand
        # edges (plan 100, 1.2); ``REDUCER_SYNTHESIS`` for a caller that
        # names none.
        # ``source_cell``: the cell of the authored construct this node
        # stands for when that construct must not become the node's
        # lexical ``source_span`` (an Input for an ``ast.arg``); it names
        # the ``ingestion_value`` row's provenance only.
        # Value ids are identities: never hand out an id freed by an earlier
        # removal.  The per-graph watermark only moves forward (see
        # src.compiler.process_graph_value_ids for the shared rule).
        metadata = graph.G.graph
        node_id = max(
            int(metadata.get("value_id_watermark", -1)),
            max((int(existing) for existing in graph.G.nodes), default=-1),
        ) + 1
        metadata["value_id_watermark"] = node_id
        # A synthesized node has no `expr_obj`, so nothing downstream can
        # place it lexically unless the authored statement it stands for is
        # recorded here. `source` is that statement/expression: its span is
        # stamped as the node-level `source_span` every lexical-ownership
        # test reads first (e.g. loop_composer's `is_lexical_body_node`),
        # while `expr_obj` stays None so the node is never mistaken for the
        # authored expression itself.
        node_source_span = (
            {
                "line": getattr(source, "lineno", None),
                "column": getattr(source, "col_offset", None),
                "end_line": getattr(source, "end_lineno", None),
                "end_column": getattr(source, "end_col_offset", None),
            }
            if source is not None and getattr(source, "lineno", None) is not None
            else None
        )
        graph.G.add_node(
            node_id,
            label=label,
            type=node_type,
            op=node_type.lower(),
            expr_obj=None,
            extra_args={},
            domain_node=None,
            store_id=None,
            parents=[],
            children=[],
            attributes=dict(attributes or {}),
            **({"source_span": node_source_span} if node_source_span else {}),
        )
        if node_type in {"Const", "Constant"}:
            graph.G.nodes[node_id]["constant"] = (
                attributes or {}
            ).get("value")
        # Every reducer-synthesized node is an ``ingestion_value`` row in
        # this reduction's ingestion scope (plan 60, section 3.1 (c)):
        # DERIVED from the span of the authored ``source`` it stands for,
        # else Unsourced(SYNTHESIZED_NO_SOURCE) under the latch -- the
        # latch lists every caller that passes no source (Phis, captured
        # Inputs, static constants) as step 3's worklist.
        # ``source_cell`` may be several cells (edges lane C): a Phi derives
        # from its incoming values, a StaticReference from its definition.
        if isinstance(source_cell, _Ref):
            cells = (source_cell,)
        elif isinstance(source_cell, tuple):
            cells = tuple(dict.fromkeys(
                cell for cell in source_cell if isinstance(cell, _Ref)
            ))
        else:
            cells = ()
        if not cells:
            span = _post_source_span(source)
            cells = () if span is None else (span,)
        if not cells:
            # Creation is registration: a node stands for an authored
            # construct (``source``) or derives from cells (``source_cell``).
            graph.G.remove_node(node_id)
            raise ValueError(
                f"new_node({node_type!r}, {label!r}): no source -- a "
                "synthesized node names the authored construct it stands "
                "for or the cells it derives from"
            )
        current_identity_book().post(
            _INGESTION_VALUE, (ingestion_read_scope, int(node_id)),
            _NodeFact(str(node_type), str(node_type.lower()), str(label)),
            stage=_REDUCTION,
            provenance=_Derived(cells),
            mode=_Mode.CONCORD,
        )
        # The operand edges after the node's row exists: each Append
        # derives from the operand cell and this consumer cell (plan 100,
        # 1.2); the one writer materializes ``children`` and the edges.
        _set_operands(graph, node_id, list(parents), cause=cause)
        return node_id

    def aggregate_position_cell(
        consumer_id: int, role: str, ordinal: int,
    ) -> _Ref | None:
        """Exact operand-slot cell for an authored aggregate member."""

        from ...compiler.concordance_declarations import OperandMove

        book = current_identity_book()
        for scope in dict.fromkeys(filter(None, (
            graph.G.graph.get("operand_position_scope"),
            entry_operand_scope,
            graph.G.graph.get("ingestion_value_scope"),
        ))):
            row = (
                tuple(scope), int(consumer_id), str(role), int(ordinal),
            )
            for page in (_IDENTITY_TRANSITION, _LEXICAL_READ_BINDING):
                cell = book.latest_ref(page, row)
                if cell is not None:
                    return cell
            # A role-renaming rewrite records its transition on the source
            # position.  The target position deliberately has no duplicate
            # fact unless a lexical-read row also moved there.  Follow the
            # typed OperandMove relation to that exact source cell instead
            # of treating the absent target row as an absent edge.
            moved_cells = []
            transition_page = book.page(_IDENTITY_TRANSITION)
            for source_row in transition_page.scope_rows(tuple(scope)):
                if (
                    len(source_row) != 4
                    or int(source_row[1]) != int(consumer_id)
                ):
                    continue
                fact = transition_page.latest(source_row)
                if (
                    isinstance(fact, OperandMove)
                    and int(fact.consumer) == int(consumer_id)
                    and str(fact.role) == str(role)
                    and int(fact.ordinal) == int(ordinal)
                ):
                    moved_cells.append(
                        book.latest_ref(_IDENTITY_TRANSITION, source_row)
                    )
            moved_cells = tuple(dict.fromkeys(filter(None, moved_cells)))
            if len(moved_cells) == 1:
                return moved_cells[0]
            if len(moved_cells) > 1:
                raise ValueError(
                    "aggregate operand position has multiple move sources: "
                    f"consumer={int(consumer_id)} role={role!r} "
                    f"ordinal={int(ordinal)} cells={moved_cells!r}"
                )
        return None

    def post_source_aggregate_layout(
        value_id: int,
        aggregate_kind: str,
        members: tuple[_SourceAggregateMember, ...],
        *,
        conditional_cell: _Ref | None = None,
        arm_layout_cells: tuple[_Ref, ...] = (),
    ) -> _Ref:
        """Publish the reducer's immutable aggregate semantic layout."""

        book = current_identity_book()
        row = (value_class_scope, int(value_id))
        fact = _SourceAggregateLayout(
            str(aggregate_kind), tuple(members), conditional_cell,
            tuple(arm_layout_cells),
        )
        incumbent = book.page(_SOURCE_AGGREGATE_LAYOUT).latest(row)
        if incumbent is not None and incumbent != fact:
            raise ValueError(
                "source aggregate layout concordance disagreement for "
                f"{row!r}: recorded={incumbent!r}, proposed={fact!r}"
            )
        cell = book.latest_ref(_SOURCE_AGGREGATE_LAYOUT, row)
        if cell is None:
            sources = [node_identity_cell(graph, int(value_id))]
            sources.extend(arm_layout_cells)
            if conditional_cell is not None:
                sources.append(conditional_cell)
            for member in members:
                sources.append(member.value_cell)
                sources.extend(member.source_cells)
            cell = book.post(
                _SOURCE_AGGREGATE_LAYOUT, row, fact,
                stage=_REDUCTION,
                provenance=_Derived(tuple(dict.fromkeys(
                    source for source in sources
                    if isinstance(source, _Ref)
                ))),
                mode=_Mode.CONCORD,
            )
        graph.G.nodes[int(value_id)].setdefault("attributes", {})[
            "source_aggregate_layout_row"
        ] = row
        return cell

    def source_aggregate_layout(value_id: int):
        row = (value_class_scope, int(value_id))
        cell = current_identity_book().latest_ref(
            _SOURCE_AGGREGATE_LAYOUT, row,
        )
        if cell is None:
            return None, None
        return (
            current_identity_book().page(_SOURCE_AGGREGATE_LAYOUT).cell(
                cell.row, cell.column,
            ),
            cell,
        )

    def post_conditional_aggregate_layout(
        merged_id: int, test_id: int, body_id: int, else_id: int,
        conditional_cell: _Ref | None,
    ) -> _Ref | None:
        """Build one aggregate Phi from the two exact arm layouts."""

        body_layout, body_layout_cell = source_aggregate_layout(body_id)
        else_layout, else_layout_cell = source_aggregate_layout(else_id)
        if not (
            isinstance(body_layout, _SourceAggregateLayout)
            and isinstance(else_layout, _SourceAggregateLayout)
            and body_layout.aggregate_kind == else_layout.aggregate_kind
            and len(body_layout.members) == len(else_layout.members)
        ):
            return None
        incumbent, incumbent_cell = source_aggregate_layout(merged_id)
        if incumbent is not None:
            if not (
                isinstance(incumbent, _SourceAggregateLayout)
                and incumbent.aggregate_kind == body_layout.aggregate_kind
                and len(incumbent.members) == len(body_layout.members)
                and incumbent.conditional_cell == conditional_cell
                and tuple(incumbent.arm_layout_cells)
                == (body_layout_cell, else_layout_cell)
            ):
                raise ValueError(
                    "conditional aggregate layout changed across reduction: "
                    f"value={int(merged_id)} recorded={incumbent!r}"
                )
            return incumbent_cell
        members = []
        for index, (body_member, else_member) in enumerate(zip(
            body_layout.members, else_layout.members,
        )):
            member_sources = tuple(dict.fromkeys(filter(None, (
                body_layout_cell, else_layout_cell,
                body_member.value_cell, else_member.value_cell,
                *body_member.source_cells, *else_member.source_cells,
                conditional_cell,
            ))))
            if int(body_member.value_id) == int(else_member.value_id):
                member_id = int(body_member.value_id)
                member_cell = body_member.value_cell
            else:
                member_id = new_node(
                    "Phi", f"aggregate member {index}",
                    attributes={
                        "source_conditional_id": int(test_id),
                        "aggregate_parent_value_id": int(merged_id),
                        "aggregate_index": int(index),
                    },
                    parents=(
                        (int(test_id), "test"),
                        (int(body_member.value_id), "body"),
                        (int(else_member.value_id), "orelse"),
                    ),
                    source_cell=member_sources,
                )
                body_tensor = graph.G.nodes[int(
                    body_member.value_id
                )].get("tensor")
                else_tensor = graph.G.nodes[int(
                    else_member.value_id
                )].get("tensor")
                if body_tensor is not None and body_tensor == else_tensor:
                    graph.G.nodes[int(member_id)]["tensor"] = dict(body_tensor)
                member_cell = node_identity_cell(graph, int(member_id))
                nested = post_conditional_aggregate_layout(
                    int(member_id), int(test_id),
                    int(body_member.value_id), int(else_member.value_id),
                    conditional_cell,
                )
                if nested is not None:
                    graph.G.nodes[int(member_id)].setdefault(
                        "attributes", {}
                    )["producer_kind"] = "aggregate_phi"
            members.append(_SourceAggregateMember(
                int(member_id), member_cell, member_sources,
            ))
        graph.G.nodes[int(merged_id)].setdefault("attributes", {}).update({
            "producer_kind": "aggregate_phi",
            "aggregate_kind": str(body_layout.aggregate_kind),
            "aggregate_leaf_value_ids": tuple(
                int(member.value_id) for member in members
            ),
        })
        return post_source_aggregate_layout(
            int(merged_id), str(body_layout.aggregate_kind), tuple(members),
            conditional_cell=conditional_cell,
            arm_layout_cells=(body_layout_cell, else_layout_cell),
        )

    def parameter_argument(name: str) -> ast.arg | None:
        """The ``ast.arg`` of parameter ``name`` on the reduced definition."""

        return _parameter_argument(statement, name)

    def post_name_binding(
        name: str, value: int, *, authored: bool, span_positions: tuple,
        context_sha256: str, cells: tuple,
    ) -> Any:
        """One ``name_binding`` row ``(ingestion scope, name, version)`` for
        the binding ``identity_bindings`` just recorded (plan 60, section
        3.2): ``version`` is the value's position in that name's list --
        exactly the ``enumerate`` the identity table uses -- and the row is
        DERIVED from the value's ``ingestion_value`` cell and ``cells``."""

        versions = identity_bindings.get(str(name), ())
        version = len(versions)
        for index in range(len(versions) - 1, -1, -1):
            if versions[index] == value:
                version = index
                break
        row = (ingestion_read_scope, str(name), int(version))
        book = current_identity_book()
        existing = book.latest_ref(_NAME_BINDING, row)
        if existing is not None:
            return existing
        sources: list = [node_identity_cell(graph, int(value))]
        for cell in cells:
            if isinstance(cell, _Ref) and cell not in sources:
                sources.append(cell)
        return book.post(
            _NAME_BINDING, row,
            _BindingFact(
                int(value), bool(authored), tuple(span_positions),
                str(context_sha256),
            ),
            stage=_REDUCTION, provenance=_Derived(tuple(sources)),
            mode=_Mode.CONCORD,
        )

    def current_name_binding_cell(name: str, value: int) -> Any:
        """The exact binding version held by ``environment[name]`` now."""

        versions = identity_bindings.get(str(name), ())
        # ``identity_bindings`` is an append-only history across all visited
        # control arms, while ``environment`` is restored to an arm's entry
        # snapshot before reducing its sibling.  Consequently the binding
        # currently held by the environment is not necessarily the last
        # history row: a terminal fast path can read the loop seed after a
        # later fallthrough path has already published its carried update.
        # Select the latest history row for the exact value the environment
        # holds.  This is still an identity lookup, never a spelling-only
        # guess; if the value has no authored binding row, publish no read.
        version = next((
            index for index in range(len(versions) - 1, -1, -1)
            if int(versions[index]) == int(value)
        ), None)
        if version is None:
            return None
        return current_identity_book().latest_ref(
            _NAME_BINDING,
            (ingestion_read_scope, str(name), int(version)),
        )

    def input_value(
        name: str, *, binding_kind: str, occurrence: Any = None,
    ) -> int:
        value = environment.get(name)
        if value is not None:
            return value
        aggregate_kind = parameter_aggregate_kinds.get(name)
        attributes = {
            "binding_name": name,
            "binding_kind": binding_kind,
        }
        source_page_cell = declared_page_bindings.get(str(name))
        page_declaration = source_page_declaration(source_page_cell)
        if page_declaration is not None:
            # This free name is not an unexplained host object.  It is the
            # value authored by the exact module-level ``declare_page`` call
            # whose concordance cell is retained here.  ``Page`` is already
            # a ProgramABI record; name it as such so ordinary call/record
            # propagation carries the source declaration through every
            # function/SCC cut without reading the live Python object.
            attributes.update({
                "result_class_ref": "Page",
                "program_abi_record_identity": "Page",
                "source_page_declaration_cell": source_page_cell,
            })
        class_identity = parameter_class_names.get(name)
        numeric_descriptor = parameter_numeric_descriptors.get(name)
        annotation_cell = current_identity_book().latest_ref(
            _PARAMETER_ANNOTATION,
            (*tuple(value_class_scope), str(name)),
        )
        annotation_fact = (
            None if annotation_cell is None else
            current_identity_book().page(_PARAMETER_ANNOTATION).cell(
                annotation_cell.row, annotation_cell.column,
            )
        )
        if numeric_descriptor is None and annotation_fact is not None:
            numeric_descriptor = numeric_feature_descriptor(annotation_fact)
        if class_identity is None and numeric_descriptor is not None:
            class_identity = str(numeric_descriptor.type_name)
        if class_identity is None:
            class_identity = primitive_class_identities.get(
                str(annotation_fact)
            )
        if class_identity is not None:
            # A typed parameter already IS an instance of its declared class.
            # ``class_ref`` has the narrower, executable meaning "this node
            # constructs an instance" throughout deployment planning.  Giving
            # it to an Input caused every numeric wrapper parameter to acquire
            # a synthetic ``__init__`` call, after which the linker exported
            # the constructor's private frame as thousands of root formals.
            # The source-value class concordance below is authoritative for
            # receiver identity; ``result_class_ref`` is its graph view.
            attributes["result_class_ref"] = class_identity
        if numeric_descriptor is not None:
            attributes.update({
                "numeric_feature_descriptor": numeric_descriptor.receipt(),
                "precision_limbs": numeric_descriptor.limbs,
            })
        if aggregate_kind is not None:
            attributes.update({
                "producer_kind": "aggregate_parameter",
                "aggregate_kind": aggregate_kind,
                "sequence_key_columns": (
                    (0,)
                    if aggregate_kind in {"set", "frozenset", "dict"}
                    else ()
                ),
                "sequence_column_count": (
                    2 if aggregate_kind == "dict" else
                    parameter_sequence_record_widths.get(name, 1)
                ),
                "sequence_writable": aggregate_kind not in {
                    "tuple", "frozenset", "bytes",
                },
                **dict((local_mapping_contracts or {}).get(name) or {}),
            })
            element_class = parameter_sequence_element_classes.get(name)
            if element_class is not None:
                # The parameter annotation is the exact authority for the
                # class of each iterated value.  Keep that authority attached
                # to sequence-preserving projections so a loop binding can
                # publish its own SOURCE_VALUE_CLASS row from the same cell.
                attributes.update({
                    "sequence_element_class_ref": str(element_class),
                    "sequence_element_annotation_cell": annotation_cell,
                })
            value_class = parameter_mapping_value_classes.get(name)
            if value_class is not None and annotation_cell is not None:
                attributes.update({
                    "mapping_value_class_ref": str(value_class),
                    "mapping_value_annotation_cell": annotation_cell,
                })
        scalar_parameters = tuple(
            graph.G.graph.get("scalar_parameters") or ()
        )
        if name in scalar_parameters:
            # The read view of the ``scalar_parameter`` row posted below.
            attributes["value_kind"] = "scalar"
        # The Input stands for the authored ``ast.arg``: its
        # ``ingestion_value`` row derives from that span (a captured or
        # external name has no arg and stays Unsourced under the latch).
        argument = parameter_argument(name)
        argument_span = _post_source_span(argument)
        # No ``ast.arg``: a captured / external / exception name.  The Input
        # stands for the free name the authored ``occurrence`` reads (the
        # handler that binds an exception name); its row derives from that
        # occurrence's cell (edges lane C).  A module global's binding is
        # Python state the book never ingests, so the read is the source.
        value = new_node(
            "Input",
            name,
            attributes=attributes,
            source_cell=(
                argument_span if argument_span is not None
                else source_page_cell
                if page_declaration is not None
                else _occurrence_cell(graph, occurrence)
            ),
        )
        environment[name] = value
        identity_bindings.setdefault(name, []).append(value)
        ingestion_definitions.setdefault(name, []).append((value, {}))
        # The Input's ``name_binding`` row: DERIVED from its own
        # ``ingestion_value`` cell and the ``ast.arg`` span (plan 60, 3.2).
        input_cell = node_identity_cell(graph, int(value))
        post_name_binding(
            name, value, authored=True, span_positions=(None,) * 4,
            context_sha256="", cells=(argument_span,),
        )
        # The parameter's ``parameter_annotation`` row (``build_from_ast``
        # posted it for a top-level function or class member).
        if name in scalar_parameters:
            # (i) a scalar annotation: DERIVED from the annotation row;
            # (ii) a scalar literal default: DERIVED from the default's
            # span (plan 60, section 3.5).  The Input's own cell always.
            post_scalar_parameter(graph, int(value), name, statement)
        # Same program/rule as ``canonical_known_class_identities``: a
        # spelling admitted from ``known_class_identities`` posts as its
        # canonical identity (every admitted spelling has one by construction).
        posted_class_identity = (
            canonical_known_class_identities[class_identity]
            if class_identity in canonical_known_class_identities
            and numeric_descriptor is None
            else class_identity
        )
        if class_identity is not None:
            _concord_source_value_class(
                value_class_scope,
                value,
                posted_class_identity,
                precision_limbs=(
                    numeric_descriptor.limbs
                    if numeric_descriptor is not None else 1
                ),
                source=f"parameter annotation {name}",
                provenance=_Derived(tuple(
                    cell for cell in (annotation_cell, input_cell, argument_span)
                    if cell is not None
                )),
            )
        if page_declaration is not None:
            _concord_source_value_class(
                value_class_scope,
                value,
                "Page",
                source="authored source page declaration",
                provenance=_Derived(tuple(filter(None, (
                    source_page_cell, input_cell,
                )))),
            )
        return value

    lexical_free_names_by_reference: dict[int, tuple[str, ...]] = {}

    def captured_authored_parameters() -> tuple[str, ...]:
        """Authored parameters read by a nested lexical scope.

        Python's symbol table is the authoritative closure record. Without
        materializing these outer identities, ``root(..., gain)`` where only
        ``blend`` reads ``gain`` loses the outer Input and grows one anonymous
        frame slot per callsite. The same loss removes ``static_bindings``
        from ``_normalize_lexical_values`` even though nested
        ``resolve_expression`` consumes that mapping.
        """

        try:
            source = ast.unparse(ast.Module(body=[statement], type_ignores=[]))
            module_table = symtable.symtable(
                source, "<turing-closure-parameters>", "exec",
            )
            owner = next(
                child for child in module_table.get_children()
                if child.get_name() == statement.name
            )
        except (StopIteration, SyntaxError, TypeError, ValueError):
            return ()
        free_names: set[str] = set()
        pending = list(owner.get_children())
        while pending:
            child = pending.pop()
            child_free_names = tuple(
                symbol.get_name()
                for symbol in child.get_symbols()
                if symbol.is_free()
            )
            free_names.update(child_free_names)
            reference = (lexical_function_bindings or {}).get(
                child.get_name()
            )
            if reference is not None:
                lexical_free_names_by_reference[int(reference.address)] = (
                    child_free_names
                )
            pending.extend(child.get_children())
        # A nested function can capture a sibling function whose own closure
        # owns the data cell.  The compiler flattens that Python function-cell
        # indirection into call boundaries, so carry the sibling's data
        # requirements transitively.  For example ``reduce_statement``
        # captures ``resolve_expression`` and the latter captures the outer
        # ``static_bindings`` parameter; the outer parameter must remain live
        # at calls to ``reduce_statement`` even though that spelling is not a
        # direct free symbol in its Python symbol table.
        changed = True
        while changed:
            changed = False
            for reference_address, names in tuple(
                lexical_free_names_by_reference.items()
            ):
                expanded = list(names)
                for name in names:
                    dependency = (lexical_function_bindings or {}).get(name)
                    if dependency is None:
                        continue
                    expanded.extend(lexical_free_names_by_reference.get(
                        int(dependency.address), (),
                    ))
                normalized = tuple(dict.fromkeys(expanded))
                if normalized != names:
                    lexical_free_names_by_reference[reference_address] = (
                        normalized
                    )
                    changed = True
        return tuple(
            name for name in function_parameter_names(statement)
            if name in free_names
        )

    # These are existing authored parameter identities, not new ABI values.
    # Establish them before nested-call reconstruction so every closure edge
    # carries the same object from its enclosing frame.
    for captured_parameter in captured_authored_parameters():
        input_value(captured_parameter, binding_kind="parameter")

    def record_ingestion_definition(
        name: str, value: int, target: ast.AST,
    ) -> None:
        """Record an authored binding, never a read or SSA-only artifact."""

        value_data = graph.G.nodes.get(int(value), {})
        dependency_shape = tuple(
            (str(role), str(graph.G.nodes[parent].get("op", "unknown")))
            for parent, role in value_data.get("parents", ())
            if parent in graph.G
        )
        source_span = {
            "line": getattr(target, "lineno", None),
            "column": getattr(target, "col_offset", None),
            "end_line": getattr(target, "end_lineno", None),
            "end_column": getattr(target, "end_col_offset", None),
        }
        context = {
            "spelling": str(name),
            "node_kind": type(target).__name__,
            "target": ast.dump(target, include_attributes=False),
            "producer_op": str(value_data.get("op", "unknown")),
            "dependency_shape": dependency_shape,
            "source_span": source_span,
        }
        context_tokens = structural_context_tokens(context)
        context_sha256 = hashlib.sha256(
            json.dumps(context, sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest()
        # The token payload stays here for the ``ingestion_identity_table``
        # view (``BindingFact`` carries the sha, not the tokens); the binding
        # itself is the ``name_binding`` row posted below, DERIVED from the
        # value's ``ingestion_value`` cell and the target's span.
        ingestion_definitions.setdefault(str(name), []).append((
            int(value), {
                **source_span,
                "context": context,
                "context_tokens": context_tokens,
                "context_token_ids": tuple(
                    encode_identity_tokens({"token": token})
                    for token in context_tokens
                ),
                "context_sha256": context_sha256,
            },
        ))
        post_name_binding(
            str(name), int(value), authored=True,
            span_positions=(
                source_span["line"], source_span["column"],
                source_span["end_line"], source_span["end_column"],
            ),
            context_sha256=context_sha256,
            cells=(_post_source_span(target),),
        )

    def static_constant(
        name: str, value: Any, *, occurrence: Any = None,
        definition: Any = None,
    ) -> int:
        """One Constant per compile-time binding ``name``, shared by every
        read.  Edges lane C: the node's row derives from the receiver's
        definition cell (``definition``, an attribute of a static object)
        and the first reading ``occurrence``; every read, cached or new,
        posts its own ``static_reference_use`` row."""

        existing = static_constant_nodes.get(name)
        if existing is not None:
            return post_static_reference_use(occurrence, existing, name)
        python_special_case = interpret_python_static_value(
            value,
            path=name,
        )
        if python_special_case is not None:
            value = python_special_case.constant
            attributes = {
                **python_special_case.attributes,
                "binding_name": name,
            }
        else:
            attributes = {"value": value, "binding_name": name}
        if isinstance(value, dict) and all(
            isinstance(key, (bool, int, float, str))
            and isinstance(item, (bool, int, float, str))
            for key, item in value.items()
        ):
            # Keep an immutable module mapping as structural source, not an
            # opaque scalar constant.  The repository-SSA lowerer materializes
            # these exact rows into a local keyed table, so dynamic source keys
            # use the same lookup path as ordinary authored dictionaries.
            attributes.update({
                "producer_kind": "compile_time_mapping",
                "aggregate_kind": "dict",
                "sequence_key_columns": (0,),
                "sequence_column_count": 2,
                "sequence_writable": False,
                "compile_time_mapping_items": tuple(value.items()),
            })
        if isinstance(value, (set, frozenset)) and all(
            isinstance(item, (bool, int, float, str)) for item in value
        ):
            ordered_items = tuple(sorted(
                value,
                key=lambda item: (
                    str(type(item).__module__),
                    str(type(item).__qualname__),
                    repr(item),
                ),
            ))
            item_dtypes = {
                "bool" if isinstance(item, bool)
                else "int64" if isinstance(item, (int, str))
                else "float64"
                for item in ordered_items
            }
            attributes.update({
                "producer_kind": "compile_time_sequence",
                "aggregate_kind": type(value).__name__,
                "sequence_key_columns": (0,),
                "sequence_column_count": 1,
                "sequence_writable": isinstance(value, set),
                "compile_time_sequence_items": ordered_items,
                **(
                    {"sequence_column_dtypes": (next(iter(item_dtypes)),)}
                    if len(item_dtypes) == 1 else {}
                ),
            })
        node_id = new_node(
            "Constant",
            name,
            attributes=attributes,
            source_cell=(definition, _occurrence_cell(graph, occurrence)),
        )
        static_scalar_class = (
            "builtins.bool" if isinstance(value, bool)
            else "builtins.int" if isinstance(value, int)
            else "builtins.float" if isinstance(value, float)
            else "builtins.str" if isinstance(value, str)
            else None
        )
        if static_scalar_class is not None:
            _concord_source_value_class(
                value_class_scope,
                int(node_id),
                static_scalar_class,
                source="resolved static scalar binding",
                provenance=_Derived((
                    node_identity_cell(graph, int(node_id)),
                )),
            )
        if definition is not None:
            static_reference_definition_cells[int(node_id)] = definition
        static_constant_nodes[name] = node_id
        return post_static_reference_use(occurrence, node_id, name)

    def is_static_literal(value: Any) -> bool:
        if value is None or value is Ellipsis or isinstance(
            value,
            (bool, bytes, complex, float, int, str),
        ):
            return True
        if isinstance(value, (tuple, list, set, frozenset)):
            return all(is_static_literal(item) for item in value)
        if isinstance(value, dict):
            return all(
                is_static_literal(key) and is_static_literal(item)
                for key, item in value.items()
            )
        return False

    def function_address_cell(address: int) -> Any:
        """The table's ``function_address`` cell for ``address``, or None."""

        try:
            entry = function_table.entry(int(address))
        except KeyError:
            return None
        return current_identity_book().latest_ref(
            _FUNCTION_ADDRESS, (function_address_identity(entry),),
        )

    def post_static_reference_use(
        occurrence: Any, node_id: int, path: str,
    ) -> int:
        """One ``static_reference_use`` row for the authored occurrence that
        resolved to the shared StaticReference ``node_id`` (edges lane C):
        DERIVED(the occurrence's cell, the definition cell, the node's
        cell).  A reference with no authored occurrence (made by the
        reducer, not read from source) posts nothing.  Returns
        ``node_id``."""

        from ...compiler.concordance_declarations import (
            STATIC_REFERENCE_USE, StaticReferenceUseFact,
        )

        use_cell = _occurrence_cell(graph, occurrence)
        if use_cell is None:
            return node_id
        cells = tuple(dict.fromkeys(
            cell for cell in (
                use_cell,
                static_reference_definition_cells.get(int(node_id)),
                _posted_node_identity_cell(graph, int(node_id)),
            )
            if cell is not None
        ))
        current_identity_book().post(
            STATIC_REFERENCE_USE,
            (ingestion_read_scope, int(id(occurrence)), int(node_id)),
            StaticReferenceUseFact(str(path)),
            stage=_REDUCTION, provenance=_Derived(cells), mode=_Mode.CONCORD,
        )
        return node_id

    def static_reference_node(reference: _StaticPythonReference) -> int:
        """Materialize one compiler reference without exposing its Python value.

        The node is cached per object and shared by every use: its
        ``ingestion_value`` row derives from the referenced definition (the
        table's ``function_address`` row, else the object's
        ``static_symbol_definition`` row), and every use posts its own
        ``static_reference_use`` row from ``reference.occurrence``."""

        key = (id(reference.value), reference.path)
        existing = static_reference_nodes.get(key)
        if existing is not None and existing in graph.G:
            cached = graph.G.nodes[existing]
            if (cached.get("type") == "StaticReference" and
                    (cached.get("attributes") or {}).get("static_python_reference") == reference.path):
                return post_static_reference_use(
                    reference.occurrence, existing, reference.path,
                )
        # Lexical normalization can remove an already-resolved reference
        # projection. Recreate its compiler symbol from the real reference;
        # the cache must never publish a removed or repurposed graph node.
        target = reference.value
        target_name = str(getattr(target, "__name__", ""))
        class_descriptor = graph.G.graph.get("class_table", {}).get(
            target_name
        )
        if class_descriptor is not None and is_dataclass(target):
            # Imported dataclasses enter the function table as structural
            # class references, but their defining ClassDef belongs to a
            # different source unit.  Recover the constructor schema here so
            # omitted literal defaults (for example SuperstepPlan.eps) remain
            # compiler facts instead of disappearing into Python reflection
            # at execution time.
            dataclass_fields = tuple(fields(target))
            class_descriptor["fields"] = tuple(
                field.name for field in dataclass_fields
            )
            defaults = dict(class_descriptor.get("field_defaults") or {})
            for field in dataclass_fields:
                if field.default is not MISSING and is_static_literal(
                    field.default
                ):
                    defaults[field.name] = copy.deepcopy(field.default)
            class_descriptor["field_defaults"] = defaults
        function_reference = (
            function_table.lexical_reference(target_name) if target_name else None
        )
        target_identity = (
            str(getattr(target, "__module__", "") or ""),
            str(getattr(target, "__qualname__", "") or ""),
        )
        if all(target_identity):
            # A static reference names its exact object: its definition is
            # the entry declared with that (module, qualname), never the
            # last function that happened to share its bare name (``re``'s
            # ``_compile`` versus ``re._compiler._compile``).  A builtin
            # has no source definition at all.
            exact = function_table.reference_by_source_identity(
                target_identity,
            )
            if exact is not None:
                function_reference = exact
            elif target_identity[0] == "builtins":
                function_reference = None
        if getattr(target, "__self__", None) is not None:
            # A bound runtime/builtin method is identified by both callable
            # and receiver.  Linking it to an unrelated source method by the
            # final spelling alone (for example ContextVar.get versus a
            # user class's get) discards the receiver and is never valid.
            function_reference = None
        attributes = {
            "static_python_reference": reference.path,
            "reference_kind": (
                "function_subgraph"
                if function_reference is not None
                else (
                    "class_subgraphs"
                    if class_descriptor is not None
                    else "static_symbol"
                )
            ),
        }
        if function_reference is not None:
            attributes["function_ref"] = function_reference.address
        if class_descriptor is not None:
            attributes["class_ref"] = target_name
        from ...compiler.concordance_declarations import (
            STATIC_SYMBOL_UNDECLARED,
        )

        definition_cell = (
            function_address_cell(function_reference.address)
            if function_reference is not None else None
        )
        if definition_cell is None:
            definition_cell = _static_symbol_definition_cell(target)
        # An object that declares no identity (an instance held by a class
        # attribute: ``registry.handler``) has no definition row.  The node
        # then stands for the authored occurrence that resolved it, exactly
        # as a free-name Input stands for the read that binds it: its row
        # derives from that occurrence's cell (edges lane C).  The shared
        # node takes no lexical ``source_span`` from one of its uses.
        node_id = new_node(
            "StaticReference",
            reference.path,
            attributes=attributes,
            source_cell=(
                definition_cell if definition_cell is not None
                else _occurrence_cell(graph, reference.occurrence)
            ),
        )
        if definition_cell is not None:
            static_reference_definition_cells[int(node_id)] = definition_cell
        static_reference_nodes[key] = node_id
        return post_static_reference_use(
            reference.occurrence, node_id, reference.path,
        )

    def first_class_function_node(
        name: str, reference: Any, *, occurrence: Any = None,
    ) -> int:
        """Represent a source function used as data by its table address.

        Cached per address and shared by every use: the node's
        ``ingestion_value`` row derives from the table's ``function_address``
        row, and each authored ``occurrence`` posts its own
        ``static_reference_use`` row (edges lane C)."""

        address = int(reference.address)
        existing = first_class_function_nodes.get(address)
        if existing is not None:
            return post_static_reference_use(occurrence, existing, name)
        definition_cell = function_address_cell(address)
        node_id = new_node(
            "StaticReference",
            name,
            attributes={
                "function_ref": address,
                "first_class_function_ref": address,
                "reference_kind": "function_subgraph",
            },
            source_cell=definition_cell,
        )
        if definition_cell is not None:
            static_reference_definition_cells[int(node_id)] = definition_cell
        # The node IS the function's address: DERIVED from the table's
        # ``function_address`` row and the node's own cell (plan 60, 3.8).
        post_callable_identity(int(node_id), address)
        first_class_function_nodes[address] = node_id
        return post_static_reference_use(occurrence, node_id, name)

    def post_callable_identity(node_id: int, address: int) -> None:
        """One CONCORD ``callable_identity_concordance`` row ``(numeric
        scope, node) -> address``; a repeat is the same fact and records
        its edge.  A table entry the address does not name (declared on
        another table) leaves the row Unsourced(HELPER_CALLER_UNROUTED)."""

        book = current_identity_book()
        address_cell = None
        try:
            entry = function_table.entry(int(address))
        except KeyError:
            entry = None
        if entry is not None:
            address_cell = book.latest_ref(
                _FUNCTION_ADDRESS, (function_address_identity(entry),),
            )
        cells = tuple(
            cell for cell in (
                address_cell, node_identity_cell(graph, int(node_id)),
            )
            if cell is not None
        )
        book.post(
            _CALLABLE_IDENTITY, (_source_numeric_scope(graph), int(node_id)),
            int(address), stage=_REDUCTION,
            provenance=_Derived(cells), mode=_Mode.CONCORD,
        )

    def bind_loop_target(target: ast.AST) -> None:
        if isinstance(target, ast.Name):
            target_identity = id(target)
            value = loop_target_bindings_by_ast.get(target_identity)
            if value is None:
                # The loop target binds this Input: its row derives from the
                # target's own cell (edges lane C), never from a span stamp
                # that would make the Input lexically owned.
                value = new_node(
                    "Input",
                    target.id,
                    attributes={
                        "binding_name": target.id,
                        "binding_kind": "loop",
                        **(
                            {"result_class_ref": local_class_declarations[
                                target.id
                            ][0]}
                            if target.id in local_class_declarations else {}
                        ),
                        **(
                            {
                                "producer_kind": "aggregate_loop_target",
                                "aggregate_kind": parameter_aggregate_kinds[target.id],
                                "sequence_key_columns": (
                                    (0,) if parameter_aggregate_kinds[target.id]
                                    in {"set", "dict"} else ()
                                ),
                                "sequence_column_count": (
                                    2 if parameter_aggregate_kinds[target.id]
                                    == "dict" else 1
                                ),
                                "sequence_writable": (
                                    parameter_aggregate_kinds[target.id]
                                    not in {"tuple", "bytes"}
                                ),
                            }
                            if target.id in parameter_aggregate_kinds else {}
                        ),
                    },
                    source_cell=_occurrence_cell(graph, target),
                )
                local_class_declaration = local_class_declarations.get(
                    target.id
                )
                if local_class_declaration is not None:
                    class_identity, annotation_cell = local_class_declaration
                    class_sources = tuple(filter(None, (
                        node_identity_cell(graph, int(value)),
                        annotation_cell,
                    )))
                    _concord_source_value_class(
                        value_class_scope,
                        int(value),
                        class_identity,
                        source=f"authored local annotation {target.id}",
                        provenance=(
                            _Derived(class_sources) if class_sources else None
                        ),
                    )
                loop_target_bindings_by_ast[target_identity] = value
                identity_bindings.setdefault(target.id, []).append(value)
                # The loop target's ``name_binding`` row: DERIVED from the
                # Input's own node cell and the target's span (plan 60, 3.2).
                post_name_binding(
                    target.id, value, authored=False,
                    span_positions=(None,) * 4, context_sha256="",
                    cells=(_post_source_span(target),),
                )
            if target_identity in scalar_loop_target_ast_ids:
                scalar_loop_binding_ids.add(value)
            environment[target.id] = value
            _remove_node(graph, id(target))
            return
        if isinstance(target, (ast.Tuple, ast.List)):
            for element in target.elts:
                bind_loop_target(element)

    def concord_iterated_target_class(
        iterator_value: int | None, target: ast.AST,
    ) -> None:
        """Project one declared sequence element class to its loop binding."""

        if (
            not isinstance(iterator_value, int)
            or iterator_value not in graph.G
            or not isinstance(target, ast.Name)
        ):
            return
        iterator_attributes = (
            graph.G.nodes[int(iterator_value)].get("attributes") or {}
        )
        class_identity = iterator_attributes.get(
            "sequence_element_class_ref"
        )
        annotation_cell = iterator_attributes.get(
            "sequence_element_annotation_cell"
        )
        if (
            class_identity is None
            and iterator_attributes.get("extraction_identity")
            == "builtins.range"
        ):
            # Program: ``sum(i * 3 for i in range(n))``.  Wrong record: the
            # comprehension target ``i`` had no ``source_value_class`` row,
            # so ``i * 3`` had none either and the generator's resident row
            # was committed as the descriptor domain's provisional float64
            # (the sum then refused a float row).  Rule: ``builtins.range``
            # yields ``int``; the call's exact extraction identity is the
            # declaration, its node cell the source.
            class_identity = "builtins.int"
            annotation_cell = node_identity_cell(graph, int(iterator_value))
        target_value = loop_target_bindings_by_ast.get(id(target))
        if (
            class_identity is None
            or annotation_cell is None
            or target_value is None
            or int(target_value) not in graph.G
        ):
            return
        target_attributes = graph.G.nodes[int(target_value)].setdefault(
            "attributes", {}
        )
        target_attributes["result_class_ref"] = str(class_identity)
        sources = tuple(dict.fromkeys(filter(None, (
            annotation_cell,
            node_identity_cell(graph, int(iterator_value)),
            node_identity_cell(graph, int(target_value)),
        ))))
        _concord_source_value_class(
            value_class_scope,
            int(target_value),
            str(class_identity),
            source="declared sequence element projection",
            provenance=_Derived(sources),
        )

    def loop_target_names(target: ast.AST) -> tuple[str, ...]:
        if isinstance(target, ast.Name):
            return (target.id,)
        if isinstance(target, (ast.Tuple, ast.List)):
            return tuple(
                name
                for element in target.elts
                for name in loop_target_names(element)
            )
        return ()

    def iterated_record_identities(
        iterator_value: int | None,
    ) -> tuple[str | None, str | None]:
        """Records retained on the exact iterable ancestry."""

        mapping_value_record = None
        sequence_value_record = None
        pending = (
            [int(iterator_value)]
            if isinstance(iterator_value, int) else []
        )
        visited: set[int] = set()
        while pending and (
            mapping_value_record is None
            and sequence_value_record is None
        ):
            candidate = pending.pop()
            if candidate in visited or candidate not in graph.G:
                continue
            visited.add(candidate)
            candidate_data = graph.G.nodes[candidate]
            candidate_attributes = candidate_data.get("attributes") or {}
            mapping_value_record = candidate_attributes.get(
                "mapping_value_record"
            )
            sequence_value_record = candidate_attributes.get(
                "sequence_value_record"
            )
            if (
                mapping_value_record is None
                and sequence_value_record is None
            ):
                pending.extend(
                    int(parent)
                    for parent, role in candidate_data.get("parents", ())
                    if str(role) in {
                        "operand", "value", "base", "object", "receiver",
                    }
                )
        return mapping_value_record, sequence_value_record

    restored_literal_nodes: dict[int, int] = {}

    def post_source_sort_contract(call_id: int, call: ast.Call) -> None:
        """Commit list.sort/sorted keyword policy at its source call writer."""

        from ...compiler.concordance_declarations import (
            SOURCE_SORT_CONTRACT, SourceSortContract,
        )
        if call_id not in graph.G:
            return
        attributes = graph.G.nodes[call_id].setdefault("attributes", {})
        if attributes.get("source_sort_contract_row") is not None:
            return
        keywords = {keyword.arg: keyword for keyword in call.keywords}
        kind, arguments, column, reverse = (
            "sort_key_unsupported", (), None, False,
        )
        if None not in keywords and not set(keywords) - {"key", "reverse"}:
            reverse_keyword = keywords.get("reverse")
            valid_reverse = (
                reverse_keyword is None
                or isinstance(reverse_keyword.value, ast.Constant)
                and isinstance(reverse_keyword.value.value, bool)
            )
            if valid_reverse:
                reverse = bool(
                    reverse_keyword.value.value
                    if reverse_keyword is not None else False
                )
                key_keyword = keywords.get("key")
                if key_keyword is None or (
                    isinstance(key_keyword.value, ast.Constant)
                    and key_keyword.value.value is None
                ):
                    kind, column = "value", 0
                elif isinstance(key_keyword.value, ast.Lambda):
                    key_lambda = key_keyword.value
                    parameters = tuple((
                        *key_lambda.args.posonlyargs, *key_lambda.args.args,
                    ))
                    body = key_lambda.body
                    if len(parameters) == 1 and (
                        isinstance(body, ast.Name)
                        and body.id == parameters[0].arg
                    ):
                        kind, column = "sort_key_column", 0
                    elif (
                        len(parameters) == 1
                        and isinstance(body, ast.Subscript)
                        and isinstance(body.value, ast.Name)
                        and body.value.id == parameters[0].arg
                        and isinstance(body.slice, ast.Constant)
                        and isinstance(body.slice.value, int)
                        and int(body.slice.value) >= 0
                    ):
                        kind = "sort_key_column"
                        column = int(body.slice.value)
                elif (
                    isinstance(key_keyword.value, ast.Attribute)
                    and key_keyword.value.attr == "__getitem__"
                ):
                    source_receiver = key_keyword.value.value
                    bound_mapping = (
                        environment.get(source_receiver.id)
                        if isinstance(source_receiver, ast.Name) else None
                    )
                    key_node = next((
                        int(parent)
                        for parent, role in graph.G.nodes[call_id].get(
                            "parents"
                        ) or ()
                        if str(role) == "kw:key" and int(parent) in graph.G
                    ), None)
                    mapping_node = (
                        int(bound_mapping)
                        if isinstance(bound_mapping, int) else
                        None if key_node is None else next((
                        int(parent)
                        for parent, role in graph.G.nodes[key_node].get(
                            "parents"
                        ) or ()
                        if str(role) == "value" and int(parent) in graph.G
                        ), None)
                    )
                    if mapping_node is not None:
                        kind, arguments, column = (
                            "sort_key_mapping_getitem", (mapping_node,), 0,
                        )
        row = (value_class_scope, int(call_id))
        is_sorted_call = (
            isinstance(call.func, ast.Name) and call.func.id == "sorted"
        )
        destination_value_id = int(call_id) if is_sorted_call else None
        source_value_id = None
        if is_sorted_call and call.args:
            source_expression = call.args[0]
            source_value_id = (
                environment.get(source_expression.id)
                if isinstance(source_expression, ast.Name) else None
            )
            if source_value_id is None:
                source_value_id = next((
                    int(parent)
                    for parent, role in graph.G.nodes[call_id].get(
                        "parents"
                    ) or ()
                    if str(role) == "arg:0"
                ), None)
        elif isinstance(call.func, ast.Attribute):
            receiver_expression = call.func.value
            destination_value_id = (
                environment.get(receiver_expression.id)
                if isinstance(receiver_expression, ast.Name) else None
            )
            if destination_value_id is None:
                destination_value_id = next((
                    int(parent)
                    for parent, role in graph.G.nodes[call_id].get(
                        "parents"
                    ) or ()
                    if str(role) == "operand"
                ), None)
        source_policy = "duplicates"
        source_policy_cell = None
        if is_sorted_call and source_value_id is not None:
            source_kind = None
            if isinstance(call.args[0], ast.Name):
                statement_row = getattr(
                    statement, "_turing_source_span_row", None
                )
                if isinstance(statement_row, tuple):
                    source_policy_cell = current_identity_book().latest_ref(
                        _PARAMETER_ANNOTATION,
                        (
                            statement_row[0], statement_row[1],
                            str(call.args[0].id),
                        ),
                    )
                if source_policy_cell is not None:
                    annotation = current_identity_book().page(
                        _PARAMETER_ANNOTATION
                    ).cell(
                        source_policy_cell.row,
                        source_policy_cell.column,
                    )
                    try:
                        annotation_expression = ast.parse(
                            str(annotation), mode="eval",
                        ).body
                    except SyntaxError:
                        annotation_expression = None
                    source_kind = annotation_aggregate_kind(
                        annotation_expression
                    )
            if source_kind is None and int(source_value_id) in graph.G:
                source_kind = (
                    graph.G.nodes[int(source_value_id)].get("attributes")
                    or {}
                ).get("aggregate_kind")
                # A constructed aggregate's ingestion cell is its exact
                # source contract. Parameters instead use their annotation
                # cell above, which declares the collection kind explicitly.
                source_policy_cell = source_policy_cell or node_identity_cell(
                    graph, int(source_value_id)
                )
            if source_kind in {"dict", "set", "frozenset"}:
                source_policy = "unique"
            elif source_kind in {
                "list", "tuple", "bytes", "bytearray",
            }:
                source_policy = "duplicates"
        if is_sorted_call and source_value_id is not None and any(
            int(output["result_value_id"]) == int(source_value_id)
            for _node, _data in graph.G.nodes(data=True)
            for output in (_data.get("attributes") or {}).get(
                "loop_iteration_outputs", ()
            )
        ):
            # ``sorted(<comprehension>)``: the source of this sort is the
            # collection the comprehension's loop writes, and that value's
            # final identity is minted later, by the loop composer, as the
            # loop's collection port (it supersedes the comprehension).
            # Posting the contract here would name the superseded id.  The
            # contract's policy and key are known now; its source identity is
            # not.  Leave the call carrying them, and the composer posts the
            # one contract (destination = this call, source = the port).
            attributes["source_sort_contract_pending"] = {
                "argument_kind": kind,
                "argument_value_ids": tuple(int(a) for a in arguments),
                "key_column": column,
                "reverse": reverse,
                "policy": source_policy,
            }
            return
        sources = [node_identity_cell(graph, int(call_id))]
        for value_id in (destination_value_id, source_value_id):
            if value_id is not None and int(value_id) in graph.G:
                sources.append(node_identity_cell(graph, int(value_id)))
        sources.extend(
            node_identity_cell(graph, int(parent))
            for parent, role in graph.G.nodes[call_id].get("parents") or ()
            if str(role).startswith("kw:") and int(parent) in graph.G
        )
        if source_policy_cell is not None:
            sources.append(source_policy_cell)
        cell = current_identity_book().post(
            SOURCE_SORT_CONTRACT, row,
            SourceSortContract(
                kind, tuple(arguments), column, reverse,
                None if destination_value_id is None else int(destination_value_id),
                "sorted" if is_sorted_call else "sort",
                source_policy,
                None if source_value_id is None else int(source_value_id),
            ),
            stage=_REDUCTION,
            provenance=_Derived(tuple(dict.fromkeys(sources))),
            mode=_Mode.CONCORD,
        )
        attributes["source_sort_contract_row"] = cell.row

    def control_arm_class_refinement(
        target: ast.AST, binding: str, receiver_id: int,
    ) -> tuple[str | None, tuple[_Ref, ...]]:
        """Class proof owned by the exact control arm containing ``target``.

        This refines only the guarded use.  The optional producer itself is
        deliberately not stamped as globally non-None.
        """

        def contains(root: ast.AST, sought: ast.AST) -> bool:
            return any(member is sought for member in ast.walk(root))

        receiver_attributes = (
            graph.G.nodes[int(receiver_id)].get("attributes") or {}
            if int(receiver_id) in graph.G else {}
        )
        optional_class = receiver_attributes.get(
            "optional_result_class_ref"
        )
        declaration_cell = receiver_attributes.get(
            "source_page_declaration_cell"
        )
        declaration = source_page_declaration(declaration_cell)
        if declaration is None:
            optional_class = None

        def rejects_optional_absence(test: ast.AST) -> bool:
            return (
                optional_class is not None
                and isinstance(test, ast.Compare)
                and isinstance(test.left, ast.Name)
                and test.left.id == binding
                and len(test.ops) == 1
                and isinstance(test.ops[0], ast.Is)
                and len(test.comparators) == 1
                and isinstance(test.comparators[0], ast.Constant)
                and test.comparators[0].value is None
            )

        def guard(test: ast.AST):
            positive = True
            if isinstance(test, ast.UnaryOp) and isinstance(test.op, ast.Not):
                positive = False
                test = test.operand
            if not (
                isinstance(test, ast.Call)
                and isinstance(test.func, ast.Name)
                and test.func.id == "isinstance"
                and len(test.args) == 2
                and isinstance(test.args[0], ast.Name)
                and test.args[0].id == binding
                and isinstance(test.args[1], ast.Name)
            ):
                return None
            return str(test.args[1].id), positive, test

        def walk(block: list[ast.stmt]):
            carried: tuple[str | None, tuple[_Ref, ...]] = (None, ())
            for member in block:
                if not contains(member, target):
                    if (
                        isinstance(member, ast.If)
                        and not member.orelse
                        and member.body
                        and isinstance(member.body[-1], (
                            ast.Return, ast.Raise, ast.Continue, ast.Break,
                        ))
                    ):
                        matched = guard(member.test)
                        if matched is not None and not matched[1]:
                            class_identity, _positive, condition = matched
                            module_identity = str(getattr(
                                condition, "_turing_source_module", "",
                            ))
                            carried = (
                                class_identity,
                                tuple(dict.fromkeys(filter(None, (
                                    _authored_node_cell(graph, condition),
                                    current_identity_book().latest_ref(
                                        _CLASS_DECLARATION,
                                        (module_identity, class_identity),
                                    ),
                                )))),
                            )
                        elif rejects_optional_absence(member.test):
                            carried = (
                                str(optional_class),
                                tuple(dict.fromkeys(filter(None, (
                                    node_identity_cell(
                                        graph, id(member.test),
                                    ),
                                    declaration_cell,
                                )))),
                            )
                    continue
                if isinstance(member, ast.If):
                    matched = guard(member.test)
                    in_body = any(contains(child, target) for child in member.body)
                    in_else = any(contains(child, target) for child in member.orelse)
                    if matched is not None:
                        class_identity, positive, condition = matched
                        if (
                            in_body and positive
                            or in_else and not positive
                        ):
                            module_identity = str(getattr(
                                condition, "_turing_source_module", "",
                            ))
                            class_cell = current_identity_book().latest_ref(
                                _CLASS_DECLARATION,
                                (module_identity, class_identity),
                            )
                            return class_identity, tuple(dict.fromkeys(filter(
                                None, (
                                    _authored_node_cell(graph, condition),
                                    class_cell,
                                ),
                            )))
                    nested = walk(list(
                        member.body if in_body else member.orelse
                    ))
                    if nested[0] is not None:
                        return nested
                for field_name in ("body", "orelse", "finalbody"):
                    nested_block = getattr(member, field_name, None)
                    if isinstance(nested_block, list) and any(
                        contains(child, target) for child in nested_block
                    ):
                        nested = walk(list(nested_block))
                        if nested[0] is not None:
                            return nested
                return carried
            return carried

        refined = walk(list(statement.body))
        if refined[0] is not None:
            return refined

        if optional_class is None:
            return None, ()
        for candidate in ast.walk(statement):
            if not isinstance(candidate, ast.BoolOp) or not isinstance(
                candidate.op, (ast.And, ast.Or),
            ):
                continue
            for ordinal, value in enumerate(candidate.values):
                if ordinal == 0 or not contains(value, target):
                    continue
                earlier = candidate.values[:ordinal]
                none_comparison = next((
                    item for item in earlier
                    if isinstance(item, ast.Compare)
                    and isinstance(item.left, ast.Name)
                    and item.left.id == binding
                    and len(item.ops) == 1
                    and isinstance(
                        item.ops[0],
                        ast.IsNot if isinstance(candidate.op, ast.And)
                        else ast.Is,
                    )
                    and len(item.comparators) == 1
                    and isinstance(item.comparators[0], ast.Constant)
                    and item.comparators[0].value is None
                ), None)
                if none_comparison is None:
                    continue
                return str(optional_class), tuple(dict.fromkeys(filter(None, (
                    _authored_node_cell(graph, none_comparison),
                    receiver_attributes.get("source_page_declaration_cell"),
                ))))
        return None, ()

    def concord_string_partition_member(
        base_id: int,
        member_index: int,
        projected_id: int,
    ) -> bool:
        """Commit one exact member of a proven ``str.partition`` result."""

        if (
            int(base_id) not in graph.G
            or int(projected_id) not in graph.G
            or int(member_index) not in {0, 1, 2}
        ):
            return False
        base_data = graph.G.nodes[int(base_id)]
        base_expression = base_data.get("expr_obj")
        if not (
            isinstance(base_expression, ast.Call)
            and isinstance(base_expression.func, ast.Attribute)
            and base_expression.func.attr == "partition"
        ):
            return False
        receiver_id = next((
            int(parent)
            for parent, role in base_data.get("parents", ())
            if str(role) == "operand" and int(parent) in graph.G
        ), None)
        if receiver_id is None:
            return False
        book = current_identity_book()
        receiver_class_cell = book.latest_ref(
            _SOURCE_VALUE_CLASS,
            (value_class_scope, int(receiver_id)),
        )
        receiver_class_fact = (
            None if receiver_class_cell is None else
            book.page(_SOURCE_VALUE_CLASS).cell(
                receiver_class_cell.row,
                receiver_class_cell.column,
            )
        )
        if not (
            isinstance(receiver_class_fact, tuple)
            and receiver_class_fact
            and str(receiver_class_fact[0]) in {
                "str", "builtins.str", "<class 'str'>",
            }
        ):
            return False
        sources = tuple(dict.fromkeys(filter(None, (
            receiver_class_cell,
            node_identity_cell(graph, int(base_id)),
            aggregate_position_cell(int(base_id), "operand", 0),
            node_identity_cell(graph, int(projected_id)),
            aggregate_position_cell(int(projected_id), "base", 0),
            aggregate_position_cell(int(projected_id), "index", 0),
        ))))
        _concord_source_value_class(
            value_class_scope,
            int(projected_id),
            "str",
            source="str.partition member projection",
            provenance=_Derived(sources),
        )
        return True

    def resolve_expression(expression: ast.AST | None) -> int | None:
        result = resolve_expression_value(expression)
        if isinstance(expression, ast.Call):
            # IdentityBook.project_cells evaluates clock=projected.clock
            # before IdentityPage(..., book=projected) can touch the book.
            # Publish possible call stores only after resolving that call's
            # operands. Recursive expression resolution preserves left/right
            # order, so acc.add(b) + acc.total still refuses its stale read.
            names = storing_call_names(expression)
            storing_call_receivers.update(names)
            if isinstance(result, int) and result in graph.G and isinstance(
                graph.G.nodes[result].get("expr_obj"), ast.Call,
            ):
                for name in names:
                    actual = environment.get(name)
                    if isinstance(actual, int):
                        effects = storing_call_effects.setdefault(int(actual), [])
                        if result not in effects:
                            effects.append(int(result))
        return result

    def resolve_expression_value(expression: ast.AST | None) -> int | None:
        if expression is None:
            return None
        if isinstance(expression, ast.UnaryOp) and isinstance(expression.op, ast.UAdd):
            # The operator pass has already retired +value as an identity
            # projection. Its authored operand, not the missing wrapper node,
            # is the value this later lexical/return reader must resolve.
            return resolve_expression(expression.operand)
        if isinstance(expression, ast.Constant) and id(expression) not in graph.G:
            # Structural reduction can remove a keyword wrapper and its leaf
            # before lexical call binding. A live use still has the exact
            # authored literal; materialize it, rather than drop the operand.
            if id(expression) not in restored_literal_nodes:
                restored_literal_nodes[id(expression)] = new_node(
                    "Constant", repr(expression.value),
                    attributes={"value": expression.value}, source=expression,
                )
                post_source_literal_glyph_sequence(
                    restored_literal_nodes[id(expression)]
                )
            return restored_literal_nodes[id(expression)]
        if isinstance(expression, ast.NamedExpr):
            value = resolve_expression(expression.value)
            bind_target(expression.target, value)
            node_id = id(expression)
            if isinstance(value, int):
                _redirect_value(graph, node_id, value)
            else:
                _remove_node(graph, node_id)
            return value
        if isinstance(
            expression,
            (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp),
        ):
            # Comprehensions and generator expressions have owned their own
            # scope since Python 3.0: a `for x in ...` target inside one is
            # never visible outside it, even when an outer variable of the
            # same name already exists or gets bound later. (The one
            # exception, a `:=` walrus target, deliberately leaks to the
            # enclosing scope per PEP 572 -- that goes through bind_target,
            # not bind_loop_target, and is untouched here.) Without this,
            # a comprehension's `for` target silently overwrote (or was
            # later mistaken for) an unrelated same-named binding elsewhere
            # in the function -- for example `tuple(f(x) for x in seq)`
            # followed later by an ordinary `for x in other:` picking up
            # the comprehension's already-evaporated node as its own
            # "before this loop" value, and crashing much later with
            # "missing ProcessGraph input" once that node was removed.
            comprehension_target_names = {
                name
                for generator in expression.generators
                for name in loop_target_names(generator.target)
            }
            shadowed_bindings = {
                name: environment[name]
                for name in comprehension_target_names
                if name in environment
            }
            for generator in expression.generators:
                resolve_expression(generator)
            if isinstance(expression, ast.DictComp):
                resolve_expression(expression.key)
                resolve_expression(expression.value)
            else:
                resolve_expression(expression.elt)
            node_id = id(expression)
            if (
                not isinstance(expression, ast.GeneratorExp)
                and node_id in graph.G
            ):
                aggregate_kind = {
                    ast.ListComp: "list",
                    ast.SetComp: "set",
                    ast.DictComp: "dict",
                }[type(expression)]
                graph.G.nodes[node_id].setdefault(
                    "attributes", {}
                ).update({
                    # A comprehension is a dynamic resident sequence built
                    # by its producer loop, not a closure aggregate whose
                    # complete member identities are statically available.
                    "producer_kind": "sequence_materialization",
                    "aggregate_kind": aggregate_kind,
                    "sequence_key_columns": (
                        (0,) if aggregate_kind in {"set", "dict"} else ()
                    ),
                    "sequence_column_count": (
                        2 if aggregate_kind == "dict" else 1
                    ),
                    "sequence_writable": True,
                })
            if isinstance(expression, (ast.ListComp, ast.SetComp, ast.DictComp)):
                if isinstance(expression, ast.DictComp):
                    key_id = resolve_expression(expression.key)
                    item_id = resolve_expression(expression.value)
                    attributes = graph.G.nodes[node_id].setdefault("attributes", {})
                    value_id = attributes.get("sequence_row_value_id")
                    if value_id is None and isinstance(key_id, int) and isinstance(item_id, int):
                        value_id = new_node(
                            "Tuple", "dictionary comprehension row",
                            parents=((key_id, "elts"), (item_id, "elts")),
                            attributes={"producer_kind": "aggregate", "aggregate_kind": "tuple",
                                "aggregate_leaf_value_ids": (key_id, item_id),
                                "sequence_column_count": 2, "sequence_writable": False},
                            source=expression,
                        )
                        post_source_aggregate_layout(
                            int(value_id), "tuple", tuple(
                                _SourceAggregateMember(
                                    int(member_id),
                                    node_identity_cell(graph, int(member_id)),
                                    (aggregate_position_cell(
                                        int(value_id), "elts", int(index),
                                    ),),
                                )
                                for index, member_id in enumerate((
                                    int(key_id), int(item_id),
                                ))
                            ),
                        )
                        attributes["sequence_row_value_id"] = value_id
                    if isinstance(value_id, int):
                        _replace_inputs(graph, node_id, tuple(
                            (int(parent), role)
                            for parent, role in graph.G.nodes[node_id].get("parents", ())
                            if role not in {"key", "value", "elt"}
                        ) + ((value_id, "elt"),))
                else:
                    value_id = resolve_expression(expression.elt)
                if (
                    isinstance(value_id, int)
                    and value_id in graph.G
                    and node_id in graph.G
                ):
                    value_attributes = (
                        graph.G.nodes[value_id].get("attributes") or {}
                    )
                    row_leaves = tuple(map(
                        int,
                        value_attributes.get(
                            "aggregate_leaf_value_ids", ()
                        ),
                    ))
                    if (
                        value_attributes.get("aggregate_kind") == "tuple"
                        and len(row_leaves) > 1
                    ):
                        # A comprehension over a tuple expression authors a
                        # fixed-width resident row sequence.  Publish that
                        # width at normalization time, where the element and
                        # its aggregate leaves are both known; leaving the
                        # default width of one makes every downstream backend
                        # see an impossible two-value insertion into a scalar
                        # arena.
                        graph.G.nodes[node_id].setdefault(
                            "attributes", {}
                        )["sequence_column_count"] = len(row_leaves)
                # Python emits one comprehension element only after every
                # generator and filter has selected the innermost iteration.
                # Publishing the same materialization on each generator made
                # an outer loop append the inner target after the inner loop
                # had exited (observed on ``_result_layout``'s ``i.args``).
                # The nested loop structure still comes from every generator;
                # only the element-write effect belongs to the last one.
                for generator in expression.generators[-1:]:
                    generator_id = id(generator)
                    if (
                        generator_id in graph.G
                        and isinstance(value_id, int)
                        and value_id in graph.G
                        and node_id in graph.G
                    ):
                        attributes = graph.G.nodes[
                            generator_id
                        ].setdefault("attributes", {})
                        outputs = list(
                            attributes.get("loop_iteration_outputs", ())
                        )
                        outputs.append({
                            "value_id": value_id,
                            "result_value_id": node_id,
                            "materializer_node_id": node_id,
                        })
                        attributes["loop_iteration_outputs"] = tuple(outputs)
            for name in comprehension_target_names:
                if name in shadowed_bindings:
                    environment[name] = shadowed_bindings[name]
                else:
                    environment.pop(name, None)
            return node_id if node_id in graph.G else None
        if isinstance(expression, ast.IfExp):
            test_value = resolve_expression(expression.test)
            body_value = resolve_expression(expression.body)
            else_value = resolve_expression(expression.orelse)
            node_id = id(expression)
            if node_id in graph.G:
                # ``x if isinstance(x, T) else normalize_T(x)`` is an
                # authored type-normalization idiom, not runtime branching.
                # A constructor/factory opts in declaratively through its
                # Python identity program's ``ensures_schema_type`` attribute.
                # Keep that ordinary operator as the sole SSA producer; the
                # type guard and merge then disappear without specializing on
                # a Python object or inventing backend-specific machinery.
                def dotted_name(value: ast.AST) -> str | None:
                    parts = []
                    while isinstance(value, ast.Attribute):
                        parts.append(str(value.attr))
                        value = value.value
                    if isinstance(value, ast.Name):
                        parts.append(str(value.id))
                        return ".".join(reversed(parts))
                    return None

                guard = expression.test
                if (
                    isinstance(guard, ast.Call)
                    and isinstance(guard.func, ast.Name)
                    and guard.func.id == "isinstance"
                    and len(guard.args) == 2
                    and isinstance(test_value, int)
                    and test_value in graph.G
                ):
                    test_attributes = graph.G.nodes[test_value].get(
                        "attributes"
                    ) or {}
                    test_program = test_attributes.get(
                        "python_identity_program"
                    ) or {}
                    subject_id = next((
                        int(parent)
                        for parent, role in graph.G.nodes[test_value].get(
                            "parents", ()
                        )
                        if str(role) == "arg:0"
                    ), None)
                    normalized_id = (
                        int(else_value)
                        if isinstance(else_value, int) else None
                    )
                    normalized_data = (
                        graph.G.nodes[normalized_id]
                        if normalized_id is not None
                        and normalized_id in graph.G else {}
                    )
                    normalized_attributes = normalized_data.get(
                        "attributes"
                    ) or {}
                    ensured_type = normalized_attributes.get(
                        "ensures_schema_type"
                    )
                    normalized_subject = next((
                        int(parent)
                        for parent, role in normalized_data.get("parents", ())
                        if str(role) == "arg:0"
                    ), None)
                    guarded_type = dotted_name(guard.args[1])
                    if os.environ.get("TURING_DEBUG_TYPE_NORMALIZATION"):
                        logger.warning(
                            "type-normalization candidate line=%s "
                            "test_program=%r subject=%r body=%r "
                            "normalized=%r normalized_subject=%r "
                            "ensured_type=%r guarded_type=%r "
                            "guard_receipt=%r normalizer_receipt=%r "
                            "test_attributes=%r normalized_attributes=%r",
                            getattr(expression, "lineno", None),
                            test_program,
                            subject_id,
                            body_value,
                            normalized_id,
                            normalized_subject,
                            ensured_type,
                            guarded_type,
                            getattr(guard, "_extraction_contract", None),
                            getattr(expression.orelse, "_extraction_contract", None),
                            test_attributes,
                            normalized_attributes,
                        )
                    if (
                        test_program.get("object_type")
                        == "schema_type_guard"
                        and subject_id is not None
                        and body_value == subject_id
                        and normalized_subject == subject_id
                        and ensured_type
                        and guarded_type
                        and (
                            str(ensured_type) == guarded_type
                            or str(ensured_type).endswith(
                                "." + guarded_type
                            )
                        )
                    ):
                        normalization_descriptor = (
                            int(subject_id),
                            int(normalized_id),
                            str(ensured_type),
                            str(guarded_type),
                        )
                        normalization_book = current_identity_book()
                        normalization_page = normalization_book.page(
                            _SOURCE_TYPE_NORMALIZATION
                        )
                        normalization_row = (
                            value_class_scope, int(node_id)
                        )
                        normalization_incumbent = normalization_page.latest(
                            normalization_row
                        )
                        if (
                            normalization_incumbent is not None
                            and tuple(normalization_incumbent)
                            != normalization_descriptor
                        ):
                            raise ValueError(
                                "source type normalization concordance "
                                f"disagreement for {normalization_row!r}: "
                                f"recorded={normalization_incumbent!r}, "
                                f"resolved={normalization_descriptor!r}"
                            )
                        # The guard relates the ifexp, its subject and the
                        # normalizing call: DERIVED from those nodes.
                        normalization_book.post(
                            _SOURCE_TYPE_NORMALIZATION, normalization_row,
                            normalization_descriptor, stage=_REDUCTION,
                            provenance=_Derived(_node_identity_cells(
                                graph, node_id, subject_id, normalized_id,
                            )),
                            mode=_Mode.CONCORD,
                        )
                        graph.G.nodes[normalized_id].setdefault(
                            "attributes", {}
                        )["source_type_normalization"] = {
                            "guard": "schema_type_guard",
                            "schema_type": str(ensured_type),
                            "source_ifexp": int(node_id),
                        }
                        _redirect_value(graph, node_id, normalized_id)
                        return normalized_id
                parents = tuple(
                    (value, role)
                    for value, role in (
                        (test_value, "test"),
                        (body_value, "body"),
                        (else_value, "orelse"),
                    )
                    if isinstance(value, int)
                )
                _replace_inputs(graph, node_id, parents)
                contracts = []
                for value in (body_value, else_value):
                    if not isinstance(value, int) or value not in graph.G:
                        contracts.append(None)
                        continue
                    attributes = graph.G.nodes[value].get("attributes") or {}
                    kind = attributes.get("aggregate_kind")
                    contracts.append(
                        None if kind is None else (
                            str(kind),
                            tuple(attributes.get("sequence_key_columns", ())),
                            int(attributes.get("sequence_column_count", 1)),
                            bool(attributes.get("sequence_writable", True)),
                        )
                    )
                if contracts[0] is not None and contracts[0] == contracts[1]:
                    kind, key_columns, column_count, writable = contracts[0]
                    graph.G.nodes[node_id].setdefault(
                        "attributes", {}
                    ).update({
                        "producer_kind": "aggregate_merge",
                        "aggregate_kind": kind,
                        "sequence_key_columns": key_columns,
                        "sequence_column_count": column_count,
                        "sequence_writable": writable,
                    })
                    # Expression-form conditional selection has the same
                    # aggregate semantics as the statement/name Phi handled
                    # above.  Publish its exact member joins on the incumbent
                    # SOURCE_AGGREGATE_LAYOUT page; aggregate metadata alone
                    # leaves a tuple as one unexplained scalar when a
                    # comprehension inserts the selected row.
                    if all(isinstance(value, int) for value in (
                        test_value, body_value, else_value,
                    )):
                        post_conditional_aggregate_layout(
                            int(node_id), int(test_value), int(body_value),
                            int(else_value), _post_source_span(expression),
                        )
            return node_id if node_id in graph.G else None
        if isinstance(expression, ast.comprehension):
            iterator_value = resolve_expression(expression.iter)
            bind_loop_target(expression.target)
            concord_iterated_target_class(
                iterator_value, expression.target,
            )
            node_id = id(expression)
            if node_id in graph.G:
                graph.G.nodes[node_id].setdefault("attributes", {})[
                    "loop_target_bindings"
                ] = {
                    name: environment[name]
                    for name in loop_target_names(expression.target)
                }
            mapping_value_record, sequence_value_record = (
                iterated_record_identities(iterator_value)
            )
            target_value = (
                loop_target_bindings_by_ast.get(id(expression.target))
                if isinstance(expression.target, ast.Name) else None
            )
            if target_value is not None and target_value in graph.G:
                target_attributes = graph.G.nodes[target_value].setdefault(
                    "attributes", {}
                )
                if (
                    mapping_value_record is not None
                    and isinstance(expression.iter, ast.Call)
                    and isinstance(expression.iter.func, ast.Attribute)
                    and expression.iter.func.attr == "values"
                ):
                    target_attributes["result_class_ref"] = str(
                        mapping_value_record
                    )
                elif sequence_value_record is not None:
                    target_attributes["result_class_ref"] = str(
                        sequence_value_record
                    )
            for condition in expression.ifs:
                resolve_expression(condition)
            return node_id if node_id in graph.G else None
        if isinstance(expression, ast.Name):
            node_id = id(expression)
            if isinstance(expression.ctx, ast.Load):
                if expression.id in static_parameter_bindings:
                    _remove_node(graph, node_id)
                    return _StaticPythonReference(
                        static_parameter_bindings[expression.id],
                        expression.id,
                        occurrence=expression,
                    )
                static_reference = static_environment.get(expression.id)
                if static_reference is not None:
                    _remove_node(graph, node_id)
                    if isinstance(static_reference, _StaticPythonReference):
                        # This read is the use, not the binding that stored
                        # the reference (edges lane C).
                        return _dataclass_replace(
                            static_reference, occurrence=expression,
                        )
                    return static_reference
                producer_id = environment.get(expression.id)
                if (
                    producer_id is None
                    and (
                        expression.id in closure_names
                        or expression.id in (closure_aggregate_kinds or {})
                    )
                ):
                    producer_id = input_value(
                        expression.id,
                        binding_kind="closure",
                        occurrence=expression,
                    )
                static_value = static_bindings.get(expression.id)
                function_reference = (
                    (lexical_function_bindings or {}).get(expression.id)
                    or function_table.lexical_reference(
                        expression.id, module=statement_module,
                    )
                )
                if (
                    producer_id is None
                    and expression.id not in parameter_names
                    and function_reference is not None
                ):
                    _remove_node(graph, node_id)
                    return first_class_function_node(
                        expression.id,
                        function_reference,
                        occurrence=expression,
                    )
                if (
                    producer_id is None
                    and expression.id not in parameter_names
                    and static_value is not None
                    and isinstance(
                        static_value,
                        (
                            types.ModuleType,
                            type,
                            types.FunctionType,
                            types.BuiltinFunctionType,
                            types.MethodType,
                        ),
                    )
                ):
                    _remove_node(graph, node_id)
                    return _StaticPythonReference(
                        static_value,
                        expression.id,
                        occurrence=expression,
                    )
                if (
                    producer_id is None
                    and expression.id not in parameter_names
                    and expression.id in static_bindings
                    and is_static_literal(static_value)
                ):
                    constant_id = static_constant(
                        expression.id,
                        static_value,
                        occurrence=expression,
                    )
                    _redirect_value(graph, node_id, constant_id)
                    return constant_id
                if (
                    producer_id is None
                    and expression.id not in parameter_names
                    and expression.id in static_bindings
                    and isinstance(static_value, (tuple, list))
                    and static_value
                ):
                    # A module table of source functions (``CASES = (f, g)``)
                    # is as static as a table of numbers: each element is a
                    # FunctionTable address.  The address is found by the
                    # declared source identity the table was built from
                    # (``module.qualname``, stamped by source pursuit), so a
                    # same-named function elsewhere can never be selected.
                    def table_reference(item: Any) -> Any:
                        if not isinstance(item, types.FunctionType):
                            return None
                        qualified = ".".join(filter(None, (
                            str(getattr(item, "__module__", "") or ""),
                            str(getattr(item, "__qualname__", "") or ""),
                        )))
                        try:
                            entry = function_table.entry(qualified)
                        except KeyError:
                            return None
                        if entry.qualified_name != qualified:
                            return None
                        return entry.reference

                    references = tuple(
                        table_reference(item) for item in static_value
                    )
                    if any(reference is not None for reference in references) and all(
                        reference is not None or is_static_literal(item)
                        for item, reference in zip(static_value, references)
                    ):
                        element_ids = tuple(
                            first_class_function_node(
                                str(item.__name__), reference,
                                occurrence=expression,
                            )
                            for item, reference in zip(
                                static_value, references,
                            )
                            if reference is not None
                        )
                        table = tuple(
                            FunctionReference(int(reference.address))
                            if reference is not None else item
                            for item, reference in zip(
                                static_value, references,
                            )
                        )
                        constant_id = static_constant(
                            expression.id,
                            table if isinstance(static_value, tuple)
                            else list(table),
                            occurrence=expression,
                        )
                        graph.G.nodes[constant_id].setdefault(
                            "attributes", {},
                        )["static_callable_element_ids"] = element_ids
                        _redirect_value(graph, node_id, constant_id)
                        return constant_id
                if producer_id is None:
                    producer_id = input_value(
                        expression.id,
                        binding_kind=(
                            "parameter"
                            if expression.id in parameter_names
                            else "exception"
                            if expression.id in exception_local_names
                            else "external"
                        ),
                        occurrence=expression,
                    )
                # Which binding each consumer read is a fact of this read,
                # not of the value: two names can hold one value (``second
                # = value``) and a loop carries one of them while the other
                # stays put.  Commit it before the occurrence dissolves into
                # a plain value edge.
                _concord_lexical_reads(
                    graph, ingestion_read_scope, node_id, expression.id,
                    binding_cell=current_name_binding_cell(
                        expression.id, producer_id,
                    ),
                )
                _redirect_value(graph, node_id, producer_id)
                return producer_id
            return environment.get(expression.id)
        if isinstance(expression, ast.Attribute):
            if (
                isinstance(expression.value, ast.Name)
                and expression.value.id not in environment
                and expression.value.id not in parameter_names
                and expression.value.id in static_bindings
            ):
                _remove_node(graph, id(expression.value))
                receiver = _StaticPythonReference(
                    static_bindings[expression.value.id],
                    expression.value.id,
                    occurrence=expression.value,
                )
            else:
                receiver = resolve_expression(expression.value)
            if isinstance(receiver, _StaticPythonReference):
                # A compile-time receiver's field, assigned earlier in this
                # reduction: page ``static_attribute_state`` row (scope,
                # receiver path, field) holds the RHS node's identity cell.
                assigned_cell = field_state_book.latest_ref(
                    _STATIC_ATTRIBUTE_STATE,
                    (ingestion_read_scope, receiver.path, expression.attr),
                )
                assigned_value = _cell_node_id(field_state_at(assigned_cell))
                if assigned_value is not None:
                    _redirect_value(graph, id(expression), assigned_value)
                    return assigned_value
                try:
                    value = getattr(receiver.value, expression.attr)
                except AttributeError:
                    pass
                else:
                    node_id = id(expression)
                    if is_static_literal(value):
                        constant_id = static_constant(
                            f"{receiver.path}.{expression.attr}",
                            value,
                            occurrence=expression,
                            definition=_static_symbol_definition_cell(
                                receiver.value,
                            ),
                        )
                        _redirect_value(graph, node_id, constant_id)
                        return constant_id
                    _remove_node(graph, node_id)
                    return _StaticPythonReference(
                        value,
                        f"{receiver.path}.{expression.attr}",
                        occurrence=expression,
                    )
            elif isinstance(receiver, int):
                expression_id = id(expression)
                attribute_id = (
                    expression_id
                    if expression_id in graph.G
                    else materialized_attribute_nodes.get(expression_id)
                )
                if attribute_id is None:
                    # The read IS the authored ``Attribute`` expression.
                    attribute_id = new_node(
                        "GetAttr",
                        f"getattr[{expression.attr}]",
                        attributes={
                            "attribute": expression.attr,
                            "source_type": "Attribute",
                        },
                        source=expression,
                    )
                    materialized_attribute_nodes[expression_id] = attribute_id
                # A field read immediately from an authored record
                # construction is the exact constructor argument.  Preserve
                # that identity directly, especially when the argument is a
                # first-class function reference: manufacturing a GetAttr
                # value here loses the function-table address before record
                # materialization and leaves a later call with no callee.
                receiver_data = graph.G.nodes.get(int(receiver), {})
                receiver_expression = receiver_data.get("expr_obj")
                receiver_class = (
                    receiver_data.get("attributes") or {}
                ).get("class_ref")
                stable_method_lookup = False
                lookup_class = receiver_class_identity(int(receiver))
                if lookup_class is not None and id(expression) in method_lookup_ids:
                    try:
                        declared_member = navigation_table.resolve_dot(
                            canonical_known_class_identities.get(lookup_class, lookup_class),
                            expression.attr, lambda _identity, _permissions: True,
                            receiver_kind="instance",
                        )
                    except (KeyError, PermissionError):
                        pass
                    else:
                        stable_method_lookup = declared_member.kind == "method"
                records = dict(
                    (graph.G.graph.get("program_abi") or {}).get("records")
                    or {}
                )
                matching_records = tuple(
                    record
                    for name, record in records.items()
                    if receiver_class is not None
                    and (
                        str(name) == str(receiver_class)
                        or str(record.get("identity") or name)
                        == str(receiver_class)
                        or str(record.get("identity") or name).endswith(
                            "." + str(receiver_class)
                        )
                    )
                )
                # The constructor argument is the field's value only while
                # nothing has touched the field since construction.  The
                # read's field-state cursor is that record: a write, merge or
                # loop exit there means the argument is a stale value.
                # Folding past it returned ``S(0)``'s 0 for ``if c > 0:
                # s.n = 1; return s.n`` and dropped every later write.
                constructed_state = field_state_at(
                    field_state_cursor.get(
                        (int(receiver), str(expression.attr))
                    )
                )
                call_stored_field = (
                    isinstance(receiver_expression, ast.Call)
                    and receiver_class is not None
                    and isinstance(expression.value, ast.Name)
                    and id(expression) not in method_lookup_ids
                    and (
                        str(expression.value.id) in storing_call_receivers
                        or any(
                            str(expression.value.id) in names
                            for names in loop_body_storing_receivers
                        )
                    )
                )
                call_reload_slot = (
                    _resolve_instance_attribute_slot(receiver_class, expression.attr)
                    if call_stored_field else None
                )
                if call_stored_field and call_reload_slot is None:
                    # ``acc.add(b); return acc.total`` (or a free function
                    # storing into ``acc``) answered the construction's value:
                    # the call's store into the record is not reloaded here.
                    raise ValueError(
                        "local record field read after a call that may store "
                        f"into it has no reloaded value: "
                        f"{expression.value.id}.{expression.attr} at line "
                        f"{getattr(expression, 'lineno', '?')} "
                        "(record_stored_by_call)"
                    )
                if (
                    isinstance(receiver_expression, ast.Call)
                    and not call_stored_field
                    and not stable_method_lookup
                    and len(matching_records) == 1
                    and isinstance(constructed_state, _FieldState)
                    and constructed_state.kind in {
                        _FieldStateKind.WRITTEN,
                        _FieldStateKind.MERGED,
                        _FieldStateKind.ARM_SELECTED,
                        _FieldStateKind.LOOP_EXIT,
                    }
                ):
                    # The field of a record this function constructed has no
                    # storage of its own: its current value IS the value the
                    # cursor names (the last write, or the merge/loop-exit
                    # version of the writes), exactly as a static receiver's
                    # assigned field is read above.
                    current_value = _cell_node_id(constructed_state.value)
                    if current_value is not None and current_value in graph.G:
                        concord_carried_field_read(
                            expression, int(receiver), int(attribute_id),
                        )
                        _redirect_value(
                            graph, int(attribute_id), int(current_value)
                        )
                        return int(current_value)
                rewritten_by_enclosing_loop = (
                    isinstance(expression.value, ast.Name)
                    and any(
                        (str(expression.value.id), str(expression.attr))
                        in writes
                        and (int(receiver), str(expression.attr))
                        not in entries
                        for writes, entries in zip(
                            loop_body_field_writes, loop_field_entry_values,
                        )
                    )
                )
                if (
                    isinstance(receiver_expression, ast.Call)
                    and not call_stored_field
                    and not stable_method_lookup
                    and len(matching_records) == 1
                    and (
                        rewritten_by_enclosing_loop
                        or (
                            isinstance(constructed_state, _Unresolved)
                            and constructed_state.reason
                            == _LOOP_EXIT_FIELD_STATE_UNMERGED
                        )
                    )
                ):
                    # A record this function constructed has no field storage;
                    # its field's value is the field-state cursor, and the
                    # reducer merges no field state at a loop.  Say so rather
                    # than read the constructor argument or nothing.
                    raise ValueError(
                        "local record field written in a loop has no merged "
                        f"value: {getattr(expression.value, 'id', '?')}."
                        f"{expression.attr} at line "
                        f"{getattr(expression, 'lineno', '?')} "
                        "(loop_exit_field_state_unmerged)"
                    )
                if (
                    isinstance(receiver_expression, ast.Call)
                    and not call_stored_field
                    and not stable_method_lookup
                    and len(matching_records) == 1
                    and (
                        constructed_state is None
                        or (
                            isinstance(constructed_state, _FieldState)
                            and constructed_state.kind
                            is _FieldStateKind.OBSERVED
                        )
                    )
                ):
                    field_names = tuple(
                        map(
                            str,
                            dict(matching_records[0].get("fields") or {}),
                        )
                    )
                    field_expression = next((
                        keyword.value
                        for keyword in receiver_expression.keywords
                        if keyword.arg == expression.attr
                    ), None)
                    if field_expression is None and expression.attr in field_names:
                        position = field_names.index(expression.attr)
                        if position < len(receiver_expression.args):
                            field_expression = receiver_expression.args[position]
                    if field_expression is not None:
                        field_value = resolve_expression(field_expression)
                        if isinstance(field_value, int) and (
                            constructed_state is None
                            or _cell_node_id(constructed_state.value)
                            == int(field_value)
                        ):
                            field_attributes = (
                                graph.G.nodes.get(field_value, {}).get(
                                    "attributes"
                                ) or {}
                            )
                            function_ref = field_attributes.get(
                                "first_class_function_ref"
                            )
                            if function_ref is not None:
                                # Scope spelled as every other numeric fact
                                # (``_source_numeric_scope``): the bare
                                # function name dropped the method owner and
                                # could give one value two rows.  One
                                # CONCORD post: a different address is the
                                # disagreement; the same one records the
                                # edge, no second column (plan 60, 3.8).
                                post_callable_identity(
                                    int(field_value), int(function_ref),
                                )
                            concord_carried_field_read(
                                expression, int(receiver), int(attribute_id),
                            )
                            _redirect_value(
                                graph, int(attribute_id), int(field_value)
                            )
                            return int(field_value)
                read_inputs: list[tuple[int, str]] = [(receiver, "value")]
                if call_stored_field:
                    read_inputs.extend(
                        (effect, "after_write")
                        for effect in storing_call_effects.get(int(receiver), ())
                        if effect in graph.G and effect != attribute_id
                    )
                # The cursor cell's effect, when that cell is a write or a
                # merge: an OBSERVED cell's effect is a read, and a read is
                # never ordered after another read.
                current_state = field_state_at(
                    field_state_cursor.get((int(receiver), str(expression.attr)))
                )
                last_write = (
                    _cell_node_id(current_state.effect)
                    if isinstance(current_state, _FieldState)
                    and current_state.kind is not _FieldStateKind.OBSERVED
                    else None
                )
                if isinstance(current_state, _Unresolved) and current_state.reason == _LOOP_EXIT_FIELD_STATE_UNMERGED:
                    # An unknown final field VALUE does not make the known
                    # loop-exit ordering unknown. The unresolved book fact
                    # names the construct that has to finish before this
                    # read; keep that causal edge without claiming a field
                    # merge/value or running a zero-trip body's store.
                    for cell in current_state.read:
                        exit_id = _cell_node_id(cell)
                        if exit_id in graph.G and isinstance(
                            graph.G.nodes[exit_id].get('expr_obj'), (ast.For, ast.While)
                        ):
                            read_inputs.append((exit_id, 'after_write'))
                # Order this read after the most recent recorded write to the
                # same field -- a whole-attribute ``SetAttr`` or an
                # element-wise ``obj.field[i, j] = ...`` ``IndexedStore`` --
                # so the scheduler cannot place a stale read before the
                # write that produced the field's current contents (see
                # ``attribute_effect_nodes``/``bind_target``). This is a pure
                # ordering edge, not a value producer: the read still reads
                # through ``receiver``, an in-place mutation.
                if (
                    last_write is not None
                    and last_write in graph.G
                    and last_write != attribute_id
                ):
                    read_inputs.append((last_write, "after_write"))
                _replace_inputs(
                    graph,
                    attribute_id,
                    tuple(read_inputs),
                )
                if isinstance(expression.value, ast.Name):
                    # Mirror ``SetAttr``'s ``attribute_slot`` (see
                    # ``bind_target``) on the read side: the field's real
                    # position in its class's declared instance storage, not
                    # a name invented at this call site.
                    class_identity = parameter_class_names.get(
                        expression.value.id
                    ) or receiver_class
                    if class_identity is not None:
                        slot = _resolve_instance_attribute_slot(
                            class_identity, expression.attr
                        )
                        if slot is not None:
                            graph.G.nodes[attribute_id].setdefault(
                                "attributes", {}
                            )["attribute_slot"] = (class_identity, slot)
                # ``resolve_expression`` may redirect an authored receiver to
                # its canonical value and retire the occurrence node.  The
                # safe lookup above is the exact post-redirection graph view;
                # do not index the retired spelling again here.
                receiver_attributes = receiver_data.get("attributes") or {}
                receiver_fact = current_identity_book().page(
                    "source_value_class_concordance"
                ).latest((value_class_scope, int(receiver)))
                refined_class, refinement_cells = (
                    control_arm_class_refinement(
                        expression, expression.value.id, int(receiver),
                    )
                    if isinstance(expression.value, ast.Name)
                    else (None, ())
                )
                receiver_class = (
                    str(method_owner)
                    if (
                        method_owner is not None
                        and isinstance(expression.value, ast.Name)
                        and expression.value.id in {"self", "cls"}
                    )
                    else refined_class or receiver_class_identity(receiver)
                )
                if receiver_class is not None and expression.attr == "value":
                    # Enum.value is an authored projection.  Its semantic
                    # alternatives come from the Enum declaration itself;
                    # its resident carrier is the declaration's fixed-width
                    # token/value cell.  Do not inspect a host Enum member or
                    # infer the result from the carrier dtype.
                    module_identity = (
                        str(value_class_scope[0])
                        if isinstance(value_class_scope, tuple)
                        and value_class_scope else ""
                    )
                    enum_class_identity = str(receiver_class)
                    qualified_enum_identity = ".".join(filter(None, (
                        module_identity,
                        enum_class_identity,
                    )))
                    qualified_enum_class_cell = (
                        current_identity_book().latest_ref(
                            _CLASS_DECLARATION,
                            (module_identity, qualified_enum_identity),
                        )
                        if qualified_enum_identity != enum_class_identity
                        else None
                    )
                    if qualified_enum_class_cell is not None:
                        enum_class_identity = qualified_enum_identity
                    enum_value_cell = current_identity_book().latest_ref(
                        _SOURCE_ENUM_GLYPH_TABLE,
                        (module_identity, enum_class_identity),
                    )
                    enum_value_fact = (
                        None if enum_value_cell is None else
                        current_identity_book().page(
                            _SOURCE_ENUM_GLYPH_TABLE
                        ).cell(enum_value_cell.row, enum_value_cell.column)
                    )
                    enum_value_identities = tuple(sorted(dict.fromkeys(
                        str(identity)
                        for identity in getattr(
                            enum_value_fact, "value_identities", (),
                        )
                        if str(identity)
                    )))
                    if enum_value_identities:
                        enum_projection_attributes = graph.G.nodes[
                            attribute_id
                        ].setdefault("attributes", {})
                        enum_projection_attributes.update({
                            "value_kind": "scalar",
                            "program_abi_storage": "scalar",
                            "program_abi_dtype": "int64",
                            "program_abi_rank": 0,
                            "enum_value_identities": enum_value_identities,
                            "enum_declaration_cell": enum_value_cell,
                            # Enum.value projects the semantic base class but
                            # reads the receiver's already resident fixed-
                            # width token/value carrier.
                            "enum_value_receiver_id": int(receiver),
                        })
                        graph.G.nodes[attribute_id]["tensor"] = {
                            "shape": (), "dtype": "int64",
                        }
                        if len(enum_value_identities) == 1:
                            enum_projection_attributes["result_class_ref"] = (
                                enum_value_identities[0]
                            )
                            enum_value_sources = _source_cells((
                                node_identity_cell(graph, int(attribute_id)),
                                current_identity_book().latest_ref(
                                    _SOURCE_VALUE_CLASS,
                                    (value_class_scope, int(receiver)),
                                ),
                                qualified_enum_class_cell,
                                enum_value_cell,
                            ))
                            _concord_source_value_class(
                                value_class_scope,
                                int(attribute_id),
                                enum_value_identities[0],
                                source="declared Enum.value projection",
                                provenance=_Derived(enum_value_sources),
                            )
                if refined_class is not None:
                    graph.G.nodes[attribute_id].setdefault(
                        "attributes", {}
                    )["source_class_refinement_cells"] = tuple(
                        refinement_cells
                    )
                receiver_numeric = (
                    None if not isinstance(receiver_fact, tuple)
                    else numeric_feature_descriptor(
                        str(receiver_fact[0]).rsplit(".", 1)[-1]
                        + (
                            f"[{int(receiver_fact[1])}]"
                            if int(receiver_fact[1]) > 1 else ""
                        )
                    )
                )
                projected_numeric = (
                    None if receiver_numeric is None
                    else numeric_feature_field_projection(
                        receiver_numeric, expression.attr
                    )
                )
                if (
                    receiver_numeric is not None
                    and (
                        (expression.attr in {"real", "imag"}
                         and "complex" in receiver_numeric.features)
                        or (expression.attr in {"numerator", "denominator"}
                            and "rational" in receiver_numeric.features)
                    )
                ):
                    projected_attributes = graph.G.nodes[
                        attribute_id
                    ].setdefault("attributes", {})
                    component_path = (
                        *tuple(receiver_attributes.get(
                            "numeric_component_path", ()
                        )),
                        str(expression.attr),
                    )
                    projected_attributes.update({
                        "numeric_component_path": component_path,
                        "numeric_component_receiver_id": int(receiver),
                        "numeric_component_attribute": str(expression.attr),
                        "precision_limbs": (
                            int(projected_numeric.limbs)
                            if projected_numeric is not None else 1
                        ),
                    })
                    if projected_numeric is not None:
                        projected_attributes.update({
                            "numeric_feature_descriptor": (
                                projected_numeric.receipt()
                            ),
                            "result_class_ref": projected_numeric.type_name,
                        })
                        # DERIVED from the projection, its receiver and
                        # the receiver's class cell the fact was read from.
                        _concord_source_value_class(
                            value_class_scope,
                            int(attribute_id),
                            projected_numeric.type_name,
                            precision_limbs=projected_numeric.limbs,
                            source="numeric-component-projection",
                            provenance=_Derived(_source_cells((
                                *_node_identity_cells(
                                    graph, attribute_id, receiver,
                                ),
                                current_identity_book().latest_ref(
                                    _SOURCE_VALUE_CLASS,
                                    (value_class_scope, int(receiver)),
                                ),
                            ))),
                        )
                    _concord_numeric_feature_projection(
                        value_class_scope,
                        int(attribute_id),
                        int(receiver),
                        str(expression.attr),
                        component_path,
                        projected_numeric,
                        cells=_node_identity_cells(
                            graph, attribute_id, receiver,
                        ),
                    )
                declared_callable_field = None
                declared_receiver_field = None
                if receiver_class is not None:
                    repository_records = dict(
                        (graph.G.graph.get("program_abi") or {}).get(
                            "records"
                        ) or {}
                    )
                    matching_receiver_records = tuple(
                        record
                        for name, record in repository_records.items()
                        if (
                            str(name) == str(receiver_class)
                            or str(record.get("identity") or name)
                            == str(receiver_class)
                            or str(record.get("identity") or name).endswith(
                                "." + str(receiver_class)
                            )
                        )
                    )
                    receiver_binding_name = receiver_attributes.get(
                        "binding_name"
                    )
                    parameter_receiver_record = dict(
                        graph.G.graph.get("parameter_record_abi") or {}
                    ).get(str(receiver_binding_name))
                    if parameter_receiver_record is not None:
                        matching_receiver_records = (
                            *matching_receiver_records,
                            parameter_receiver_record,
                        )
                    matching_receiver_records = tuple({
                        repr(record): record
                        for record in matching_receiver_records
                    }.values())
                    if len(matching_receiver_records) == 1:
                        candidate_field = dict(
                            matching_receiver_records[0].get("fields") or {}
                        ).get(str(expression.attr))
                        if isinstance(candidate_field, Mapping):
                            declared_receiver_field = dict(candidate_field)
                        if (
                            isinstance(candidate_field, Mapping)
                            and str(candidate_field.get("storage") or "")
                            == "reference"
                            and candidate_field.get("callable_signature")
                            is not None
                        ):
                            declared_callable_field = dict(candidate_field)
                if (
                    declared_receiver_field is not None
                    and str(declared_receiver_field.get("storage") or "")
                    == "keyed"
                ):
                    graph.G.nodes[attribute_id].setdefault(
                        "attributes", {}
                    ).update({
                        "producer_kind": "record_field",
                        "aggregate_kind": "dict",
                        "sequence_key_columns": (0,),
                        "sequence_column_count": 2,
                        "sequence_writable": bool(
                            declared_receiver_field.get("mutable", False)
                        ),
                        "record_field": (
                            str(receiver_class), str(expression.attr)
                        ),
                        "mapping_key_dtype": "int64",
                        "mapping_value_dtype": str(
                            declared_receiver_field.get("dtype") or "unknown"
                        ),
                        **({
                            "mapping_value_tensor": True,
                            "mapping_value_python_type": "AbstractTensor",
                        } if declared_receiver_field.get("value_tensor") else {}),
                        **({
                            "mapping_value_record": str(
                                declared_receiver_field["value_record"]
                            ),
                        } if declared_receiver_field.get("value_record")
                           is not None else {}),
                    })
                if declared_callable_field is not None:
                    graph.G.nodes[attribute_id].setdefault(
                        "attributes", {}
                    ).update({
                        "producer_kind": "record_field",
                        "record_field": (
                            str(receiver_class), str(expression.attr)
                        ),
                        "callable_reference_field": True,
                        "callable_signature": str(
                            declared_callable_field["callable_signature"]
                        ),
                        "callable_optional": bool(
                            declared_callable_field.get("optional", False)
                        ),
                    })
                field_kind = (
                    (class_field_aggregate_kinds or {}).get((
                        str(receiver_class), str(expression.attr)
                    ))
                    if receiver_class is not None else None
                )
                field_storage = (
                    dict((class_field_storage_contracts or {}).get((
                        str(receiver_class), str(expression.attr)
                    )) or {})
                    if receiver_class is not None else {}
                )
                refined_field_cell = declared_field_schema_cell(
                    receiver_class, expression.attr,
                )
                if refined_field_cell is not None:
                    graph.G.nodes[attribute_id].setdefault("attributes", {})[
                        "field_declaration_cell"
                    ] = refined_field_cell
                refined_field_fact = (
                    None if refined_field_cell is None
                    else field_state_book.page(
                        _CLASS_FIELD_DECLARATION
                    ).cell(
                        refined_field_cell.row,
                        refined_field_cell.column,
                    )
                )
                refined_annotation = str(getattr(
                    refined_field_fact, "annotation", "",
                )).rsplit(".", 1)[-1]
                semantic_field_class = (
                    (class_field_classes or {}).get((
                        str(receiver_class), str(expression.attr)
                    ))
                    if receiver_class is not None else None
                )
                declared_field_class = None
                if declared_receiver_field is not None:
                    declared_aggregate = str(
                        declared_receiver_field.get("aggregate_kind") or ""
                    ).casefold()
                    declared_dtype = str(
                        declared_receiver_field.get("dtype") or ""
                    ).casefold()
                    declared_field_class = {
                        "str": "builtins.str",
                        "bool": "builtins.bool",
                        "int": "builtins.int",
                        "int32": "builtins.int",
                        "int64": "builtins.int",
                        "float": "builtins.float",
                        "float32": "builtins.float",
                        "float64": "builtins.float",
                    }.get(declared_aggregate) or (
                        # ``dtype`` is the class of the value read only for a
                        # scalar field.  For a keyed, table or span field it is
                        # the element dtype of the aggregate (a dict of int64
                        # values is not an int), and the field's class is the
                        # one its own declaration states.
                        {
                            "bool": "builtins.bool",
                            "int": "builtins.int",
                            "int32": "builtins.int",
                            "int64": "builtins.int",
                            "float": "builtins.float",
                            "float32": "builtins.float",
                            "float64": "builtins.float",
                        }.get(declared_dtype)
                        if str(
                            declared_receiver_field.get("storage") or ""
                        ) in {"", "scalar"}
                        else None
                    )
                if (
                    declared_field_class is not None
                    and (
                        semantic_field_class is not None
                        or (
                            refined_annotation
                            and not _canonical_source_class_identity(
                                refined_annotation
                            ).startswith("builtins.")
                        )
                    )
                ):
                    # The ProgramABI field describes the physical carrier (an
                    # Enum is a resident int64).  A declared non-primitive
                    # class owns the semantic class of the read; the carrier's
                    # dtype never overrides it.
                    declared_field_class = None
                if declared_field_class is not None:
                    field_class_sources = tuple(dict.fromkeys(filter(None, (
                        node_identity_cell(graph, int(attribute_id)),
                        *tuple(refinement_cells),
                    ))))
                    graph.G.nodes[attribute_id].setdefault(
                        "attributes", {}
                    )["result_class_ref"] = declared_field_class
                    _concord_source_value_class(
                        value_class_scope,
                        int(attribute_id),
                        declared_field_class,
                        source="source Page fact field ABI",
                        provenance=(
                            _Derived(field_class_sources)
                            if field_class_sources else None
                        ),
                    )
                if refined_annotation == "str":
                    # A declared string field is a runtime string-token value,
                    # even though its physical column is int64.  Publish the
                    # semantic class from the field declaration at the read
                    # itself so method results and formatting follow the same
                    # exact receiver edge instead of rediscovering the type
                    # from a later source expression.
                    string_sources = field_state_sources(
                        receiver,
                        expression.attr,
                        node_identity_cell(graph, int(attribute_id)),
                        refined_field_cell,
                    )
                    _concord_source_value_class(
                        value_class_scope,
                        int(attribute_id),
                        "str",
                        source="declared string field",
                        provenance=(
                            _Derived(string_sources)
                            if string_sources else None
                        ),
                    )
                refined_scalar_dtype = {
                    "int": "int64", "bool": "bool", "float": "float64",
                }.get(refined_annotation)
                if (
                    field_storage.get("dtype") is not None
                    and field_storage.get("record") is None
                    and field_storage.get("aggregate_kind") is None
                    and not field_storage.get("tensor")
                ):
                    graph.G.nodes[attribute_id]["tensor"] = {
                        "shape": (),
                        "dtype": str(field_storage["dtype"]),
                    }
                    graph.G.nodes[attribute_id].setdefault(
                        "attributes", {}
                    )["value_kind"] = "scalar"
                elif refined_scalar_dtype is not None:
                    graph.G.nodes[attribute_id]["tensor"] = {
                        "shape": (), "dtype": refined_scalar_dtype,
                    }
                    refined_attributes = graph.G.nodes[
                        attribute_id
                    ].setdefault("attributes", {})
                    refined_attributes["value_kind"] = "scalar"
                    refined_attributes[
                        "source_class_refinement_cells"
                    ] = tuple(dict.fromkeys((
                        *tuple(refinement_cells), refined_field_cell,
                    )))
                # A field that holds a source-local object: this read
                # yields an instance of that class (``result_class_ref``,
                # the same fact a call returning a class instance carries),
                # so a method call on it resolves through the class table.
                # Not ``class_ref``: that marks a construction, and the
                # deployment side reads its presence as one.
                field_class = semantic_field_class
                if field_class is not None:
                    graph.G.nodes[attribute_id].setdefault(
                        "attributes", {}
                    )["result_class_ref"] = field_class
                    class_sources = field_state_sources(
                        receiver, expression.attr,
                        node_identity_cell(graph, int(attribute_id)),
                    )
                    _concord_source_value_class(
                        value_class_scope,
                        int(attribute_id),
                        field_class,
                        source="declared class field",
                        provenance=(
                            _Derived(class_sources)
                            if class_sources else None
                        ),
                    )
                if field_kind is not None:
                    mapping_contract = dict(
                        (class_field_mapping_contracts or {}).get((
                            str(receiver_class), str(expression.attr)
                        )) or {}
                    )
                    sequence_dtypes = tuple(
                        (class_field_sequence_dtypes or {}).get((
                            str(receiver_class), str(expression.attr)
                        )) or ()
                    )
                    sequence_record = (
                        (class_field_sequence_records or {}).get((
                            str(receiver_class), str(expression.attr)
                        ))
                    )
                    sequence_element_class = (
                        (class_field_sequence_element_classes or {}).get((
                            str(receiver_class), str(expression.attr)
                        ))
                    )
                    graph.G.nodes[attribute_id].setdefault(
                        "attributes", {}
                    ).update({
                        "producer_kind": "record_field",
                        "aggregate_kind": field_kind,
                        "sequence_key_columns": (
                            (0,)
                            if field_kind in {"set", "frozenset", "dict"}
                            else ()
                        ),
                        "sequence_column_count": (
                            2 if field_kind == "dict" else 1
                        ),
                        "sequence_writable": (
                            bool(declared_receiver_field.get("mutable", False))
                            if declared_receiver_field is not None
                            and "mutable" in declared_receiver_field
                            else field_kind not in {
                                "tuple", "frozenset", "bytes", "str",
                            }
                        ),
                        "record_field": (
                            str(receiver_class), str(expression.attr)
                        ),
                        **({
                            "sequence_column_dtypes": sequence_dtypes,
                        } if sequence_dtypes else {}),
                        **({
                            "sequence_value_record": str(sequence_record),
                        } if sequence_record is not None else {}),
                        **({
                            "sequence_element_class_ref": str(
                                sequence_element_class
                            ),
                            "sequence_element_annotation_cell": (
                                refined_field_cell
                            ),
                        } if sequence_element_class is not None
                           and refined_field_cell is not None else {}),
                        **mapping_contract,
                    })
                page_key_cell = page_key_field_schemas.get((
                    int(receiver), str(expression.attr),
                ))
                if (
                    page_key_cell is None
                    and isinstance(expression.value, ast.Name)
                ):
                    page_key_cell = page_key_binding_field_schemas.get((
                        str(expression.value.id), str(expression.attr),
                    ))
                page_key_declaration = source_page_declaration(page_key_cell)
                if page_key_declaration is not None:
                    # This field was consumed earlier as the exact key of the
                    # declared Page. Every later read of the same field-state
                    # row therefore has that Page's key tuple layout. The Ref,
                    # not this graph view, remains the schema authority.
                    graph.G.nodes[attribute_id].setdefault(
                        "attributes", {}
                    ).update({
                        "aggregate_kind": "tuple",
                        "source_tuple_row_fields": tuple(
                            page_key_declaration.row_fields
                        ),
                        "source_page_declaration_cell": page_key_cell,
                    })
                # An ordinary attribute access on a resolved receiver is a
                # real reference-operator node -- ``_replace_inputs`` above
                # already gave it the receiver as a dependency, and
                # ``attribute_slot`` its class-grounded identity where
                # known.  Without returning that identity here, every
                # caller of ``resolve_expression`` -- including ``ast.Call``
                # resolving its own ``func`` for a method call -- silently
                # receives ``None`` instead: the operator resolved
                # correctly but never reported back that it did, severing
                # the receiver as a dependency for anything built from this
                # expression (a method call, a chained attribute, ...).
                # Observation does not assign a new field version.  The
                # first observation of a field with no state yet is the
                # row's first revision, OBSERVED, whose value and effect are
                # this read's own node (plan 70, S3); a later read posts
                # nothing and the ``after_write`` operand above was ordered
                # after the cursor cell's effect.
                if not stable_method_lookup and (int(receiver), str(expression.attr)) not in field_state_cursor:
                    post_field_state(
                        receiver, expression.attr, _FieldStateKind.OBSERVED,
                        int(attribute_id), int(attribute_id),
                        sources=field_state_sources(
                            receiver, expression.attr,
                            node_identity_cell(graph, int(attribute_id)),
                        ),
                        stage=_REDUCER_FIELD_WRITE,
                    )
                if (
                    expression.attr == "__name__"
                    and isinstance(expression.value, ast.Call)
                    and isinstance(expression.value.func, ast.Name)
                    and expression.value.func.id == "type"
                    and len(expression.value.args) == 1
                    and not expression.value.keywords
                ):
                    # ``type(x).__name__`` is a ``str`` by the data model:
                    # the class of the attribute value does not depend on
                    # what ``x`` is.
                    type_name_cell = node_identity_cell(
                        graph, int(attribute_id),
                    )
                    _concord_source_value_class(
                        value_class_scope,
                        int(attribute_id),
                        "str",
                        source="type(x).__name__ result",
                        provenance=(
                            _Derived((type_name_cell,))
                            if type_name_cell is not None else None
                        ),
                    )
                return attribute_id

        if isinstance(expression, ast.Call):
            node_id = id(expression)
            argument_values = {}
            def resolved_call_argument(argument):
                # All call-binding passes read the same authored occurrence.
                # Re-evaluating it after a nested call would read a later
                # field state (and may revisit an already retired node).
                key = id(argument)
                if key not in argument_values:
                    argument_values[key] = resolve_expression(argument)
                return argument_values[key]
            if (
                isinstance(expression.func, ast.Name)
                and expression.func.id
                in (graph.G.graph.get("class_definitions") or ())
                and node_id in graph.G
            ):
                # A source-local class construction, already known from
                # ``map_ir`` at ingestion -- no python_bindings/static
                # reference resolution needed or wanted for this: the
                # class isn't external, it's right here in the source.
                graph.G.nodes[node_id].setdefault(
                    "attributes", {},
                )["class_ref"] = expression.func.id
            if (
                isinstance(expression.func, ast.Attribute)
                and node_id in graph.G
            ):
                # A method call's receiver is wired here, through the same
                # SSA lookup (resolve_expression) every other expression
                # already goes through -- not a raw AST-node id, which is
                # only valid by coincidence (it assumes ingestion happened
                # to walk this exact receiver independently, which is not
                # guaranteed for one reached only through this call
                # expression). The receiver is an ordinary expression --
                # commonly a Name already bound by bind_target, whose real,
                # resolved value resolve_expression looks up directly.
                receiver_value = resolve_expression(expression.func.value)
                receiver_inputs = (
                    ((receiver_value, "operand"),)
                    if isinstance(receiver_value, int)
                    else ()
                )
                receiver_class = (
                    None
                    if not isinstance(receiver_value, int)
                    else _resolved_source_value_class(
                        graph.G, int(receiver_value)
                    )[0]
                )
                if receiver_class is not None:
                    try:
                        method_entry = function_table.entry(
                            f"{receiver_class}.{expression.func.attr}"
                        )
                    except KeyError:
                        method_entry = None
                    if method_entry is not None:
                        method_reference = int(
                            method_entry.reference.address
                        )
                        graph.G.nodes[node_id].setdefault(
                            "attributes", {}
                        ).update({
                            "method_ref": method_reference,
                            "callee_ref": method_reference,
                        })
                        accessor_id = id(expression.func)
                        if accessor_id in graph.G:
                            graph.G.nodes[accessor_id].setdefault(
                                "attributes", {}
                            ).update({
                                "accessor_kind": "method",
                                "method_ref": method_reference,
                            })
                argument_inputs = tuple(
                    (resolved, f"arg{index}")
                    for index, argument in enumerate(expression.args)
                    if isinstance(
                        (resolved := resolved_call_argument(argument)), int
                    )
                )
                keyword_inputs = tuple(
                    (resolved, f"kw:{keyword.arg}" if keyword.arg else "kwargs")
                    for keyword in expression.keywords
                    if isinstance(
                        (resolved := resolved_call_argument(keyword.value)), int
                    )
                )
                if receiver_inputs:
                    _replace_inputs(
                        graph,
                        node_id,
                        (*receiver_inputs, *argument_inputs, *keyword_inputs),
                    )
                # Sequence mutation receipts used to be emitted only while
                # collecting loop state effects below. That omitted a field
                # append outside a loop, such as
                # ``self.offsets.append(len(self.items))``. Resolve the
                # receiver through the same source binding used by call
                # lowering, so a local alias (``offsets = self.offsets;
                # offsets.append(...)``) retains the field-read identity too.
                # The loop collector still owns loop-state semantics; its
                # identical field fact concords with this row.
                if (
                    isinstance(expression.func, ast.Attribute)
                    and isinstance(receiver_value, int)
                    and receiver_value in graph.G
                    and node_id in graph.G
                ):
                    receiver_attributes = dict(
                        graph.G.nodes[receiver_value].get("attributes") or {}
                    )
                    aggregate_kind = str(
                        receiver_attributes.get("aggregate_kind") or ""
                    ).casefold()
                    operation_name = str(expression.func.attr)
                    writable = bool(receiver_attributes.get(
                        "sequence_writable", True,
                    ))
                    sequence_policy = (
                        "unique" if aggregate_kind in {"set", "dict"}
                        else "duplicates" if aggregate_kind in {
                            "list", "tuple", "bytes", "bytearray", "array",
                        }
                        else None
                    )
                    sequence_method_call = (
                        sequence_policy is not None
                        and aggregate_kind not in {"tuple", "bytes"}
                        and writable
                    )
                    mapping_method_call = (
                        aggregate_kind == "dict" and writable
                    )
                    if sequence_method_call or mapping_method_call:
                        from ...compiler.concordance_declarations import (
                            SOURCE_SEQUENCE_MUTATION,
                        )
                        argument_ids = _sequence_mutation_argument_ids(
                            operation_name,
                            (*argument_inputs, *keyword_inputs),
                        )
                        known_mutation = (
                            operation_name in _SEQUENCE_MUTATION_OPERATORS
                            and not (
                                aggregate_kind == "dict"
                                and operation_name == "pop"
                            )
                        ) or operation_name in _MAPPING_MUTATION_OPERATORS
                        mutation_operation = (
                            operation_name if known_mutation
                            else f"unclassified_call:{operation_name}"
                        )
                        mutation_fact = (
                            int(receiver_value), mutation_operation,
                            str(sequence_policy), argument_ids,
                            "mapping" if aggregate_kind == "dict" else "sequence",
                        )
                        mutation_row = (value_class_scope, int(node_id))
                        mutation_page = current_identity_book().page(
                            SOURCE_SEQUENCE_MUTATION
                        )
                        incumbent = mutation_page.latest(mutation_row)
                        if incumbent is not None and tuple(incumbent) != mutation_fact:
                            raise ValueError(
                                "source sequence mutation concordance "
                                f"disagreement for {mutation_row!r}: "
                                f"recorded={incumbent!r}, "
                                f"proposed={mutation_fact!r}"
                            )
                        if incumbent is None:
                            mutation_sources = [
                                node_identity_cell(graph, int(node_id)),
                                node_identity_cell(graph, int(receiver_value)),
                            ]
                            mutation_sources.extend(
                                node_identity_cell(graph, int(argument_id))
                                for argument_id in argument_ids
                            )
                            current_identity_book().post(
                                SOURCE_SEQUENCE_MUTATION,
                                mutation_row,
                                mutation_fact,
                                stage=_REDUCTION,
                                provenance=_Derived(tuple(dict.fromkeys(
                                    cell for cell in mutation_sources
                                    if cell is not None
                                ))),
                                mode=_Mode.CONCORD,
                            )
            callee = resolved_call_argument(expression.func)
            if isinstance(callee, _StaticPythonReference) and node_id in graph.G:
                identity_target = (
                    callee.value.__func__
                    if inspect.ismethod(callee.value)
                    else callee.value
                )
                identity = ".".join(filter(None, (
                    str(getattr(identity_target, "__module__", "")),
                    str(getattr(
                        identity_target,
                        "__qualname__",
                        getattr(identity_target, "__name__", ""),
                    )),
                )))
                identity_program = resolve_python_identity(identity)
                if identity_program is not None:
                    call_attributes = graph.G.nodes[node_id].setdefault(
                        "attributes", {}
                    )
                    call_attributes.update({
                        "python_identity_program": identity_program.mapping(),
                        "python_replacement_kind": identity_program.kind,
                        **identity_program.direct_attributes,
                    })
                    descriptor = (
                        str(identity),
                        str(identity_program.kind),
                        identity_program.direct_operator,
                        tuple(sorted(
                            identity_program.direct_attributes.items()
                        )),
                    )
                    identity_page = current_identity_book().page(
                        "source_python_identity_concordance"
                    )
                    identity_row = (value_class_scope, int(node_id))
                    call_attributes[
                        "source_python_identity_row"
                    ] = identity_row
                    identity_incumbent = identity_page.latest(identity_row)
                    if (
                        identity_incumbent is not None
                        and tuple(identity_incumbent) != descriptor
                    ):
                        raise ValueError(
                            "source Python identity concordance disagreement "
                            f"for {identity_row!r}: "
                            f"recorded={identity_incumbent!r}, "
                            f"resolved={descriptor!r}"
                        )
                    if identity_incumbent is None:
                        identity_book = current_identity_book()
                        identity_cell = (
                            node_identity_cell(graph, int(node_id))
                            if node_id in graph.G else None
                        )
                        if identity_cell is None:
                            raise ValueError(
                                f"{_SOURCE_PYTHON_IDENTITY}: no source cell "
                                f"for {identity_row!r} -- node {node_id} has "
                                "no identity cell on the graph"
                            )
                        identity_book.post(
                            _SOURCE_PYTHON_IDENTITY, identity_row, descriptor,
                            stage=_REDUCTION,
                            provenance=_Derived((identity_cell,)),
                            mode=_Mode.CONCORD,
                        )
                    identity_cell = current_identity_book().latest_ref(
                        _SOURCE_PYTHON_IDENTITY, identity_row,
                    )
                    intrinsic_result_class = {
                        "builtins.bool": "builtins.bool",
                        "builtins.float": "builtins.float",
                        "builtins.int": "builtins.int",
                        # String Core's AGGREGATE_BASE + len(self.domain)
                        # reached this exact static-call identity route, not
                        # extraction_identity below.  The absent len class
                        # left its Add/append operand unproved.  Both routes
                        # read the same authored builtin identity.
                        "builtins.len": "builtins.int",
                    }.get(str(identity))
                    if (
                        intrinsic_result_class is not None
                        and identity_cell is not None
                    ):
                        _concord_source_value_class(
                            value_class_scope,
                            int(node_id),
                            intrinsic_result_class,
                            source="resolved Python identity result",
                            provenance=_Derived((identity_cell,)),
                        )
            if (
                isinstance(callee, _StaticPythonReference)
                and any(
                    callee.value is kind
                    for kind in (tuple, list, set, frozenset, dict, bytes, bytearray)
                )
                and node_id in graph.G
            ):
                constructor = graph.G.nodes[node_id]
                constructor_attributes = constructor.setdefault(
                    "attributes", {}
                )
                aggregate_kind = callee.value.__name__
                constructor_attributes.setdefault(
                    "producer_kind",
                    "aggregate" if not expression.args else (
                        "aggregate_materialization"
                    ),
                )
                constructor_attributes.update({
                    "aggregate_kind": aggregate_kind,
                    "sequence_key_columns": (
                        (0,) if aggregate_kind in {"set", "frozenset", "dict"} else ()
                    ),
                    "sequence_column_count": (
                        2 if aggregate_kind == "dict" else 1
                    ),
                    "sequence_writable": aggregate_kind not in {
                        "tuple", "frozenset", "bytes"
                    },
                })
                constructor_attributes.setdefault(
                    "aggregate_leaf_value_ids",
                    tuple(
                        int(parent)
                        for parent, role in constructor.get("parents") or ()
                        if str(role).startswith(("arg", "kw:"))
                    ),
                )
                # The admitted builtin constructor is the semantic source
                # declaration for its result.  Publish that declaration to
                # the same concordance used by retained comprehension
                # aggregates, so later ABI settlement does not have to infer
                # a container class from element dtypes or inspect a live
                # Python object.
                aggregate_identity_cell = current_identity_book().latest_ref(
                    _SOURCE_PYTHON_IDENTITY,
                    (value_class_scope, int(node_id)),
                )
                aggregate_source_cell = (
                    aggregate_identity_cell
                    or node_identity_cell(graph, int(node_id))
                )
                if aggregate_source_cell is None:
                    raise ValueError(
                        "builtin aggregate constructor has no source cell: "
                        f"value={int(node_id)} "
                        f"identity=builtins.{aggregate_kind}"
                    )
                _concord_source_value_class(
                    value_class_scope,
                    int(node_id),
                    f"builtins.{aggregate_kind}",
                    source="resolved builtin aggregate result",
                    provenance=_Derived((aggregate_source_cell,)),
                )
            if isinstance(callee, int) and callee in graph.G:
                callee_attributes = (
                    graph.G.nodes[callee].get("attributes") or {}
                )
                callee_reference = callee_attributes.get("function_ref")
                if callee_reference is not None and node_id in graph.G:
                    graph.G.nodes[node_id].setdefault(
                        "attributes",
                        {},
                    )["callee_ref"] = callee_reference
                method_reference = callee_attributes.get("method_ref")
                if method_reference is not None and node_id in graph.G:
                    graph.G.nodes[node_id].setdefault(
                        "attributes", {}
                    )["method_ref"] = int(method_reference)
                    call_inputs = tuple(
                        graph.G.nodes[node_id].get("parents") or ()
                    )
                    if not any(
                        parent == callee and str(role) == "callee"
                        for parent, role in call_inputs
                    ):
                        _replace_inputs(
                            graph,
                            node_id,
                            (*call_inputs, (callee, "callee")),
                        )
                if (
                    callee_attributes.get("callable_reference_field")
                    and node_id in graph.G
                ):
                    call_attributes = graph.G.nodes[node_id].setdefault(
                        "attributes", {}
                    )
                    call_attributes.update({
                        "indirect_callable_id": int(callee),
                        "callable_signature": str(
                            callee_attributes["callable_signature"]
                        ),
                        "callable_optional": bool(
                            callee_attributes.get("callable_optional", False)
                        ),
                    })
                    call_inputs = tuple(
                        graph.G.nodes[node_id].get("parents") or ()
                    )
                    if not any(
                        int(parent) == int(callee)
                        and str(role) in {"callee", "function", "func"}
                        for parent, role in call_inputs
                    ):
                        _replace_inputs(
                            graph,
                            node_id,
                            (*call_inputs, (int(callee), "callee")),
                        )
            if isinstance(callee, _StaticPythonReference) and node_id in graph.G:
                reference_node_id = static_reference_node(callee)
                attributes = graph.G.nodes[node_id].setdefault(
                    "attributes",
                    {},
                )
                attributes["static_python_reference"] = callee.path
                reference_attributes = graph.G.nodes[
                    reference_node_id
                ].get("attributes") or {}
                if "function_ref" in reference_attributes:
                    attributes["callee_ref"] = reference_attributes[
                        "function_ref"
                    ]
                if "class_ref" in reference_attributes:
                    attributes["class_ref"] = reference_attributes[
                        "class_ref"
                    ]
                if str(graph.G.nodes[node_id].get("type")) == "Call":
                    _append_operand(
                        graph, node_id, reference_node_id, "callee",
                    )
                else:
                    # A canonical numerical operation already identifies its
                    # implementation by node type.  Preserve the wrapper as
                    # compiler metadata, but never feed it to the operation as
                    # tensor data.
                    attributes["operator_reference_node"] = reference_node_id
            # Every call's arguments need ``resolve_expression`` -- the same
            # reduction/redirection every other expression gets -- regardless
            # of what kind of callee this call has.  This used to run only
            # inside the ``_StaticPythonReference`` branch above, so an
            # ordinary method call (``pending.pop(0)``, a call through a
            # resolved-but-not-static receiver) never had its arguments
            # resolved at all during reduction: a literal like ``0`` was
            # left exactly as ingestion produced it, unreachable by anything
            # that expects reduction to have run -- the same "not translated"
            # shape as any other missing operand.
            if node_id in graph.G:
                attributes = graph.G.nodes[node_id].setdefault(
                    "attributes", {}
                )
                static_arguments = dict(
                    attributes.get("static_call_arguments") or {}
                )
                for index, argument in enumerate(expression.args):
                    resolved = resolved_call_argument(argument)
                    if isinstance(resolved, _StaticPythonReference):
                        role = f"arg:{index}"
                        static_arguments[role] = resolved.path
                        attributes.setdefault(
                            "static_call_values", {}
                        )[role] = resolved.value
                        definition_cell = _static_symbol_definition_cell(
                            resolved.value
                        )
                        if definition_cell is not None:
                            attributes.setdefault(
                                "static_call_definition_cells", {}
                            )[role] = definition_cell
                        graph.G.graph.setdefault(
                            "static_python_values", {}
                        )[resolved.path] = resolved.value
                    elif (
                        isinstance(resolved, int)
                        and resolved in graph.G
                        and (graph.G.nodes[resolved].get("attributes") or {}).get(
                            "first_class_function_ref"
                        ) is not None
                    ):
                        role = f"arg:{index}"
                        _append_operand(graph, node_id, resolved, role)
                for keyword in expression.keywords:
                    if keyword.arg is None:
                        continue
                    resolved = resolved_call_argument(keyword.value)
                    if isinstance(resolved, _StaticPythonReference):
                        role = f"kw:{keyword.arg}"
                        static_arguments[role] = resolved.path
                        attributes.setdefault(
                            "static_call_values", {}
                        )[role] = resolved.value
                        definition_cell = _static_symbol_definition_cell(
                            resolved.value
                        )
                        if definition_cell is not None:
                            attributes.setdefault(
                                "static_call_definition_cells", {}
                            )[role] = definition_cell
                        graph.G.graph.setdefault(
                            "static_python_values", {}
                        )[resolved.path] = resolved.value
                    elif (
                        isinstance(resolved, int)
                        and resolved in graph.G
                        and (graph.G.nodes[resolved].get("attributes") or {}).get(
                            "first_class_function_ref"
                        ) is not None
                    ):
                        role = f"kw:{keyword.arg}"
                        _append_operand(graph, node_id, resolved, role)
                if static_arguments:
                    attributes["static_call_arguments"] = static_arguments

            # A source-defined function may itself be a positional/keyword
            # value (callbacks, policies, hooks).  Its original Name node was
            # intentionally removed, so reconnect the compiler-owned static
            # reference to the call with the argument's real role.
            if node_id in graph.G:
                attributes = graph.G.nodes[node_id].setdefault(
                    "attributes", {}
                )
                static_arguments = dict(
                    attributes.get("static_call_arguments") or {}
                )
                for role, argument in (
                    *tuple(
                        (f"arg:{index}", argument)
                        for index, argument in enumerate(expression.args)
                    ),
                    *tuple(
                        (f"kw:{keyword.arg}", keyword.value)
                        for keyword in expression.keywords
                        if keyword.arg is not None
                    ),
                ):
                    if (
                        isinstance(argument, ast.Name)
                        and isinstance(
                            getattr(builtins, argument.id, None), type
                        )
                    ):
                        static_arguments[role] = argument.id
                        static_type = getattr(builtins, argument.id)
                        attributes.setdefault(
                            "static_call_values", {}
                        )[role] = static_type
                        definition_cell = _static_symbol_definition_cell(
                            static_type
                        )
                        if definition_cell is not None:
                            attributes.setdefault(
                                "static_call_definition_cells", {}
                            )[role] = definition_cell
                        graph.G.graph.setdefault(
                            "static_python_values", {}
                        )[argument.id] = static_type
                if static_arguments:
                    attributes["static_call_arguments"] = static_arguments
                for role, argument in (
                    *tuple(
                        (f"arg:{index}", argument)
                        for index, argument in enumerate(expression.args)
                    ),
                    *tuple(
                        (f"kw:{keyword.arg}", keyword.value)
                        for keyword in expression.keywords
                        if keyword.arg is not None
                    ),
                ):
                    resolved = resolved_call_argument(argument)
                    if not (
                        isinstance(resolved, int)
                        and resolved in graph.G
                        and (graph.G.nodes[resolved].get("attributes") or {}).get(
                            "first_class_function_ref"
                        ) is not None
                    ):
                        continue
                    _append_operand(graph, node_id, resolved, role)

            # Rebuild every call from the values resolved at this lexical
            # program point.  Ingestion may omit a repeated Attribute/Name
            # occurrence even though the enclosing Call is retained; keeping
            # its earlier raw-AST-id inputs then leaves a real argument behind
            # an Untranslated placeholder.  The lexical reducer already owns
            # the authoritative environment, so use those resolved values for
            # ordinary arguments as well as first-class-function arguments.
            if node_id in graph.G:
                call_data = graph.G.nodes[node_id]
                call_attributes = call_data.get("attributes") or {}
                resolved_inputs: list[tuple[int, str]] = []
                if isinstance(expression.func, ast.Attribute):
                    receiver = resolve_expression(expression.func.value)
                    if isinstance(receiver, int):
                        resolved_inputs.append((receiver, "operand"))
                    if (
                        isinstance(callee, int)
                        and callee in graph.G
                        and (graph.G.nodes[callee].get("attributes") or {}).get(
                            "method_ref"
                        ) is not None
                    ):
                        resolved_inputs.append((callee, "callee"))
                elif not (
                    "callee_ref" in call_attributes
                    or "external_callee_ref" in call_attributes
                ):
                    if isinstance(callee, int):
                        resolved_inputs.append((callee, "callee"))
                    elif isinstance(callee, _StaticPythonReference):
                        resolved_inputs.append((
                            static_reference_node(callee),
                            "callee",
                        ))
                for index, argument in enumerate(expression.args):
                    resolved = resolved_call_argument(argument)
                    if isinstance(resolved, int):
                        resolved_inputs.append((resolved, f"arg:{index}"))
                for keyword in expression.keywords:
                    resolved = resolved_call_argument(keyword.value)
                    if isinstance(resolved, int):
                        resolved_inputs.append((
                            resolved,
                            f"kw:{keyword.arg}" if keyword.arg else "kwargs",
                        ))
                callee_reference = call_attributes.get(
                    "callee_ref", call_attributes.get("method_ref")
                )
                for closure_name in lexical_free_names_by_reference.get(
                    int(callee_reference)
                    if callee_reference is not None
                    else -1,
                    (),
                ):
                    closure_value = environment.get(closure_name)
                    if (
                        closure_value is None
                        and closure_name in parameter_names
                    ):
                        closure_value = input_value(
                            closure_name, binding_kind="parameter",
                        )
                    if isinstance(closure_value, int):
                        resolved_inputs.append((
                            closure_value, f"closure:{closure_name}",
                        ))
                # ``total.item()``: the receiver Name was read by the
                # attribute load (``value`` of ``total.item``); the rebuilt
                # call takes the same occurrence as its ``operand``.  That is
                # a second read position of one occurrence -- a fork of the
                # read, which must carry its binding.
                # Keyword arguments are the same shape: ``f(dt_prev=x)``
                # reads ``x`` at the ``keyword`` node's ``value``; the call
                # takes it as ``kw:dt_prev`` (found by the woodshop's
                # ``step_with_dt_control_used`` call in a carried loop).
                # A Name forks from its own occurrence's read (the wrapper
                # may never have been its consumer); any other expression
                # from the wrapper position that consumed it.
                def read_source(value_expression, wrapper_id):
                    if isinstance(value_expression, ast.Name):
                        return ("occurrence", id(value_expression), 0)
                    return (wrapper_id, "value", 0)

                receiver_fork: dict[tuple[str, int], tuple[Any, ...]] = {}
                if (
                    isinstance(expression.func, ast.Attribute)
                    and any(role == "operand" for _v, role in resolved_inputs)
                ):
                    receiver_fork[("operand", 0)] = read_source(
                        expression.func.value, id(expression.func),
                    )
                for keyword in expression.keywords:
                    receiver_fork[(
                        f"kw:{keyword.arg}" if keyword.arg else "kwargs", 0,
                    )] = read_source(keyword.value, id(keyword))
                _replace_inputs(
                    graph, node_id, tuple(resolved_inputs),
                    fork_from=receiver_fork or None,
                )
                if (
                    isinstance(expression.func, ast.Attribute)
                    and expression.func.attr == "strip"
                    and not expression.args
                    and not expression.keywords
                ):
                    receiver_id = next((
                        int(parent)
                        for parent, role in resolved_inputs
                        if str(role) == "operand"
                    ), None)
                    receiver_class, _receiver_width = (
                        _resolved_source_value_class(graph, receiver_id)
                    )
                    if _canonical_source_class_identity(
                        receiver_class
                    ) == "builtins.str":
                        # ``str.strip`` returns a string.  Publish that result
                        # from the exact receiver-class edge while the call's
                        # authored receiver is still present; the glyph
                        # producer is settled separately from this semantic
                        # class fact.
                        call_attributes.update({
                            "result_class_ref": "str",
                            "string_token_transform": "strip",
                        })
                        receiver_class_cell = (
                            current_identity_book().latest_ref(
                                _SOURCE_VALUE_CLASS,
                                (value_class_scope, int(receiver_id)),
                            )
                            if receiver_id is not None else None
                        )
                        class_sources = tuple(dict.fromkeys(filter(None, (
                            node_identity_cell(graph, int(node_id)),
                            node_identity_cell(graph, int(receiver_id)),
                            receiver_class_cell,
                        ))))
                        _concord_source_value_class(
                            value_class_scope,
                            int(node_id),
                            "str",
                            source="builtins.str.strip result",
                            provenance=_Derived(class_sources),
                        )
                if (
                    "builtins.next" in {
                        call_attributes.get("extraction_identity"),
                        call_attributes.get("static_python_reference"),
                    }
                    or call_attributes.get("static_python_reference")
                    == "next"
                ) and len(expression.args) >= 1:
                    # ``next(iter(rows))`` returns one row of the resident
                    # sequence.  A tuple-valued comprehension already owns
                    # the exact row layout on SOURCE_AGGREGATE_LAYOUT; project
                    # that contract onto the query result here, while both
                    # the source row and the authored call still have exact
                    # identity cells.  The aggregate root remains semantic;
                    # control SSA later publishes the physical columns under
                    # these member identities.
                    iterator_id = next((
                        int(parent)
                        for parent, role in resolved_inputs
                        if str(role) == "arg:0" and int(parent) in graph.G
                    ), None)
                    sequence_id = iterator_id
                    if iterator_id is not None:
                        iterator_data = graph.G.nodes[int(iterator_id)]
                        iterator_expression = iterator_data.get("expr_obj")
                        if (
                            isinstance(iterator_expression, ast.Call)
                            and isinstance(iterator_expression.func, ast.Name)
                            and iterator_expression.func.id == "iter"
                        ):
                            sequence_id = next((
                                int(parent)
                                for parent, role in (
                                    iterator_data.get("parents") or ()
                                )
                                if str(role) == "arg:0"
                                and int(parent) in graph.G
                            ), None)
                    sequence_data = (
                        graph.G.nodes[int(sequence_id)]
                        if sequence_id is not None
                        and int(sequence_id) in graph.G else {}
                    )
                    row_id = (
                        (sequence_data.get("attributes") or {}).get(
                            "sequence_row_value_id"
                        )
                        or next((
                            int(parent)
                            for parent, role in (
                                sequence_data.get("parents") or ()
                            )
                            if str(role) == "elt" and int(parent) in graph.G
                        ), None)
                    )
                    row_layout, row_layout_cell = (
                        source_aggregate_layout(int(row_id))
                        if isinstance(row_id, int) else (None, None)
                    )
                    result_layout, _result_layout_cell = (
                        source_aggregate_layout(int(node_id))
                    )
                    if (
                        result_layout is None
                        and isinstance(row_layout, _SourceAggregateLayout)
                        and str(row_layout.aggregate_kind) == "tuple"
                        and row_layout.members
                    ):
                        call_cell = node_identity_cell(graph, int(node_id))
                        result_members = []
                        for index, row_member in enumerate(
                            row_layout.members
                        ):
                            member_sources = tuple(dict.fromkeys(filter(None, (
                                call_cell,
                                row_layout_cell,
                                row_member.value_cell,
                                *tuple(row_member.source_cells),
                            ))))
                            member_id = new_node(
                                "Indexed",
                                f"next aggregate member {index}",
                                attributes={
                                    "aggregate_parent_value_id": int(node_id),
                                    "aggregate_index": int(index),
                                    "producer_kind": "sequence_query_member",
                                },
                                parents=((int(node_id), "base"),),
                                source_cell=member_sources,
                                cause=_AGGREGATE_MEMBER,
                            )
                            result_members.append(_SourceAggregateMember(
                                int(member_id),
                                node_identity_cell(graph, int(member_id)),
                                tuple(dict.fromkeys(filter(None, (
                                    row_layout_cell,
                                    row_member.value_cell,
                                    *tuple(row_member.source_cells),
                                )))),
                            ))
                        call_attributes.update({
                            "producer_kind": "sequence_query_aggregate",
                            "aggregate_kind": "tuple",
                            "aggregate_leaf_value_ids": tuple(
                                member.value_id for member in result_members
                            ),
                        })
                        post_source_aggregate_layout(
                            int(node_id), "tuple", tuple(result_members),
                        )
                if call_attributes.get("extraction_identity") == "builtins.len":
                    # The extraction contract identifies this operation as
                    # Python's resident leading-dimension intrinsic.  Its
                    # result is therefore the authored integer consumed by
                    # both scalar control and glyph formatting.  Publish the
                    # class at the call while the exact intrinsic node still
                    # owns that identity; waiting for SSA scalar lowering is
                    # too late for JoinedStr recipe construction.
                    call_attributes["result_class_ref"] = "int"
                    graph.G.nodes[node_id]["tensor"] = {
                        "shape": (), "dtype": "int64",
                    }
                    call_sources = tuple(filter(None, (
                        node_identity_cell(graph, int(node_id)),
                    )))
                    _concord_source_value_class(
                        value_class_scope,
                        int(node_id),
                        "int",
                        source="builtins.len intrinsic result",
                        provenance=(
                            _Derived(call_sources) if call_sources else None
                        ),
                    )
                page_declaration_cell = None
                if isinstance(expression.func, ast.Attribute):
                    if (
                        isinstance(expression.func.value, ast.Name)
                        and expression.func.value.id in borrowed_page_bindings
                    ):
                        page_declaration_cell = borrowed_page_bindings[
                            expression.func.value.id
                        ]
                    if page_declaration_cell is None:
                        receiver_id = next((
                            int(parent)
                            for parent, role in resolved_inputs
                            if str(role) == "operand" and int(parent) in graph.G
                        ), None)
                        if receiver_id is not None:
                            page_declaration_cell = (
                                graph.G.nodes[receiver_id].get("attributes")
                                or {}
                            ).get("source_page_declaration_cell")
                page_declaration = source_page_declaration(
                    page_declaration_cell
                )
                if (
                    page_declaration is not None
                    and expression.func.attr in {"rows", "latest"}
                ):
                    page_fact_class = str(page_declaration.class_identity)
                    page_row_fields = tuple(page_declaration.row_fields)
                    page_attributes = graph.G.nodes[node_id].setdefault(
                        "attributes", {}
                    )
                    page_attributes[
                        "source_page_declaration_cell"
                    ] = page_declaration_cell
                    if expression.func.attr == "rows":
                        page_attributes.update({
                            "producer_kind": "page_rows",
                            "aggregate_kind": "list",
                            "sequence_key_columns": (),
                            "sequence_column_count": 1,
                            "sequence_writable": False,
                            "sequence_element_aggregate_kind": "tuple",
                            "sequence_element_row_fields": tuple(
                                page_row_fields
                            ),
                        })
                    else:
                        # ``latest`` remains optional.  This is the exact
                        # class carried by a control arm that proves presence,
                        # never a global claim that the result is non-None.
                        # The class as the class table (and every record
                        # projection) names it.
                        page_attributes["optional_result_class_ref"] = (
                            page_fact_class_name(page_declaration_cell)
                            or str(page_fact_class)
                        )
                        key_value_id = next((
                            int(parent)
                            for parent, role in resolved_inputs
                            if str(role) == "arg:0" and int(parent) in graph.G
                        ), None)
                        if key_value_id is not None:
                            key_attributes = graph.G.nodes[
                                key_value_id
                            ].setdefault("attributes", {})
                            key_attributes.update({
                                "aggregate_kind": "tuple",
                                "source_tuple_row_fields": tuple(
                                    page_row_fields
                                ),
                                "source_page_declaration_cell": (
                                    page_declaration_cell
                                ),
                            })
                            key_receiver_id = next((
                                int(parent)
                                for parent, role in graph.G.nodes[
                                    key_value_id
                                ].get("parents") or ()
                                if str(role) == "value" and int(parent) in graph.G
                            ), None)
                            key_field = key_attributes.get("record_field")
                            if (
                                key_receiver_id is not None
                                and isinstance(key_field, tuple)
                                and len(key_field) == 2
                            ):
                                page_key_field_schemas[(
                                    int(key_receiver_id), str(key_field[1]),
                                )] = page_declaration_cell
                result_class = call_attributes.get(
                    "result_class_ref", call_attributes.get("class_ref")
                )
                if result_class is not None:
                    # A width is recorded only where the source states it;
                    # a Precision-bearing result whose width is computed is
                    # stated by its callsite specialization, not guessed here.
                    carries_width = "precision" in (_NUMERIC_TYPE_FEATURES.get(
                        str(result_class).rsplit(".", 1)[-1]
                    ) or ())
                    precision_limbs: int | None = (
                        int(call_attributes["precision_limbs"])
                        if call_attributes.get("precision_limbs")
                        else None if carries_width else 1
                    )
                    if (
                        str(result_class).rsplit(".", 1)[-1]
                        in {"Precision", "ComplexPrecision"}
                        and isinstance(expression.func, ast.Attribute)
                        and expression.func.attr == "of"
                    ):
                        precision_limbs = 2
                        if len(expression.args) >= 2:
                            try:
                                precision_limbs = int(ast.literal_eval(
                                    expression.args[1]
                                ))
                            except (ValueError, TypeError):
                                precision_limbs = None
                        if precision_limbs is not None:
                            call_attributes["precision_limbs"] = max(
                                precision_limbs, 1
                            )
                if result_class is not None and precision_limbs is not None:
                    # The returned-class resolver already reached an authored
                    # callee.  Persist that result identity now, while its
                    # exact call vertex and canonical function address are in
                    # hand.  Waiting for source-pursuit propagation leaves
                    # calls in non-pursued dependency bodies with a class fact
                    # but no predecessor edge; a compilation-unit cut then
                    # quite correctly exposes the broken chain.
                    result_cell = None
                    if callee_reference is not None:
                        callee_entry = next((
                            entry for entry in function_table
                            if int(entry.reference.address)
                            == int(callee_reference)
                        ), None)
                        if callee_entry is not None and callee_entry.graph is not None:
                            callee_identity = tuple(
                                callee_entry.graph.G.graph.get(
                                    "authored_function_identity"
                                ) or ()
                            )
                            equivalent_entries = tuple(
                                entry
                                for entry in function_table
                                if entry.graph is not None
                                and tuple(entry.graph.G.graph.get(
                                    "authored_function_identity"
                                ) or ()) == callee_identity
                            )
                            canonical_entry = min(
                                equivalent_entries,
                                key=lambda entry: int(
                                    entry.reference.address
                                ),
                            ) if equivalent_entries else callee_entry
                            result_row = (
                                value_class_scope, int(node_id),
                            )
                            result_sources = tuple(dict.fromkeys(
                                cell for cell in (
                                    node_identity_cell(graph, int(node_id)),
                                    current_identity_book().latest_ref(
                                        _FUNCTION_ADDRESS,
                                        (function_address_identity(canonical_entry),),
                                    ),
                                )
                                if cell is not None
                            ))
                            if result_sources:
                                result_book = current_identity_book()
                                result_book.post(
                                    _SOURCE_CALL_RESULT_IDENTITY,
                                    result_row,
                                    (
                                        int(canonical_entry.reference.address),
                                        str(result_class),
                                        int(precision_limbs),
                                    ),
                                    stage=_REDUCTION,
                                    provenance=_Derived(result_sources),
                                    mode=_Mode.CONCORD,
                                )
                                result_cell = result_book.latest_ref(
                                    _SOURCE_CALL_RESULT_IDENTITY,
                                    result_row,
                                )
                    if result_cell is not None:
                        _concord_source_value_class(
                            value_class_scope,
                            node_id,
                            str(result_class),
                            precision_limbs=precision_limbs,
                            source="resolved call result",
                            provenance=_Derived((result_cell,)),
                        )
                if (
                    isinstance(expression.func, ast.Attribute)
                    and expression.func.attr == "setdefault"
                    and len(expression.args) >= 2
                ):
                    default_id = resolve_expression(expression.args[1])
                    default_attributes = (
                        graph.G.nodes[default_id].get("attributes") or {}
                        if isinstance(default_id, int) and default_id in graph.G
                        else {}
                    )
                    default_kind = default_attributes.get("aggregate_kind")
                    if default_kind is not None:
                        call_attributes.update({
                            "producer_kind": "mapping_default_result",
                            "aggregate_kind": default_kind,
                            "sequence_key_columns": tuple(
                                default_attributes.get(
                                    "sequence_key_columns", ()
                                )
                            ),
                            "sequence_column_count": int(
                                default_attributes.get(
                                    "sequence_column_count", 1
                                )
                            ),
                            "sequence_writable": bool(
                                default_attributes.get(
                                    "sequence_writable", True
                                )
                            ),
                        })
                        receiver_id = resolve_expression(
                            expression.func.value
                        )
                        if isinstance(receiver_id, int) and receiver_id in graph.G:
                            receiver_contract = graph.G.nodes[
                                receiver_id
                            ].setdefault("attributes", {})
                            receiver_contract[
                                "mapping_value_aggregate_kind"
                            ] = default_kind
                            key_id = resolve_expression(expression.args[0])
                            key_attributes = (
                                graph.G.nodes[key_id].get("attributes") or {}
                                if isinstance(key_id, int) and key_id in graph.G
                                else {}
                            )
                            key_leaves = tuple(
                                key_attributes.get(
                                    "aggregate_leaf_value_ids", ()
                                )
                            )
                            receiver_contract[
                                "mapping_key_column_count"
                            ] = max(1, len(key_leaves))

                if (
                    isinstance(expression.func, ast.Attribute)
                    and expression.func.attr in {"get", "setdefault"}
                ):
                    mapping_id = resolve_expression(expression.func.value)
                    mapping_attrs = (graph.G.nodes[mapping_id].get("attributes") or {}) if isinstance(mapping_id, int) and mapping_id in graph.G else {}
                    child_dtypes = tuple(mapping_attrs.get("mapping_child_column_dtypes") or ())
                    child_kind = mapping_attrs.get("mapping_value_aggregate_kind")
                    if child_kind == "list" and len(child_dtypes) == 1:
                        element_class = {"int64": "builtins.int", "float64": "builtins.float", "bool": "builtins.bool"}.get(child_dtypes[0])
                        call_attributes.update({
                            "producer_kind": "mapping_lookup_result" if expression.func.attr == "get" else "mapping_default_result",
                            "aggregate_kind": child_kind,
                            "sequence_column_count": 1,
                            "sequence_column_dtypes": child_dtypes,
                            **({"sequence_element_class_ref": element_class} if element_class is not None else {}),
                        })

        # A named callee already represented by a function-table reference is
        # not a runtime value.  Its arguments still are.
        children = tuple(source_child_nodes(expression))
        if isinstance(expression, ast.Call):
            call_data = (
                graph.G.nodes[id(expression)]
                if id(expression) in graph.G
                else {}
            )
            call_attributes = call_data.get("attributes") or {}
            if (
                isinstance(expression.func, ast.Name)
                and (
                    "callee_ref" in call_attributes
                    or "external_callee_ref" in call_attributes
                )
            ):
                children = tuple(
                    child
                    for child in children
                    if child is not expression.func
                )
            elif isinstance(callee, _StaticPythonReference):
                children = tuple(
                    child
                    for child in children
                    if child is not expression.func
                )
            elif (
                isinstance(callee, int)
                and callee in graph.G
                and (
                    graph.G.nodes[callee].get("attributes") or {}
                ).get("function_ref") is not None
            ):
                children = tuple(
                    child
                    for child in children
                    if child is not expression.func
                )

        # Resolve children first so the existing executable node receives
        # producer IDs rather than lexical occurrence IDs.
        for child in children:
            if isinstance(child, ast.expr_context):
                continue
            if isinstance(expression, ast.Call) and (
                id(child) in argument_values
                or isinstance(child, ast.keyword) and id(child.value) in argument_values
            ):
                continue
            resolve_expression(child)
        node_id = id(expression)
        if (
            isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Attribute)
            and expression.func.attr == "get"
            and node_id in graph.G
        ):
            call_parents = {
                str(role): int(parent)
                for parent, role in (
                    graph.G.nodes[node_id].get("parents") or ()
                )
            }
            mapping_base_id = call_parents.get(
                "operand", call_parents.get("value")
            )
            mapping_base_attributes = (
                graph.G.nodes[mapping_base_id].get("attributes") or {}
                if mapping_base_id in graph.G else {}
            )
            mapping_value_columns = tuple(
                mapping_base_attributes.get("mapping_value_columns") or ()
            )
            if (
                len(mapping_value_columns) > 1
                and source_aggregate_layout(int(node_id))[0] is None
            ):
                lookup_cell = node_identity_cell(graph, int(node_id))
                base_cell = node_identity_cell(
                    graph, int(mapping_base_id)
                )
                result_members = []
                for index, column in enumerate(mapping_value_columns):
                    member_sources = tuple(dict.fromkeys(filter(None, (
                        lookup_cell, base_cell,
                    ))))
                    member_id = new_node(
                        "Indexed", f"mapping get member {index}",
                        attributes={
                            "aggregate_parent_value_id": int(node_id),
                            "aggregate_index": int(index),
                            "producer_kind": "mapping_lookup_member",
                        },
                        parents=((int(node_id), "base"),),
                        source_cell=member_sources,
                        cause=_AGGREGATE_MEMBER,
                    )
                    dtype = column.get("dtype") if isinstance(
                        column, Mapping
                    ) else None
                    if dtype is not None:
                        graph.G.nodes[int(member_id)]["tensor"] = {
                            "shape": (), "dtype": str(dtype),
                        }
                    result_members.append(_SourceAggregateMember(
                        int(member_id),
                        node_identity_cell(graph, int(member_id)),
                        member_sources,
                    ))
                graph.G.nodes[node_id].setdefault("attributes", {}).update({
                    "producer_kind": "mapping_lookup_aggregate",
                    "aggregate_kind": "tuple",
                    "aggregate_leaf_value_ids": tuple(
                        member.value_id for member in result_members
                    ),
                })
                post_source_aggregate_layout(
                    int(node_id), "tuple", tuple(result_members),
                )
        if isinstance(expression, ast.Subscript) and node_id in graph.G:
            base_id = resolve_expression(expression.value)
            # c636: a helper fills result[i] in a loop, then returns
            # result[:i]; its caller appends len(returned) to array("I").
            # The immediate base is the last IndexedStore effect, whose
            # attributes do not declare a collection. Its existing base-edge
            # storage identity owns that declaration. Read it for the slice
            # contract while retaining base_id as the ordered dataflow edge.
            base_contract_id = (
                _indexed_store_source(graph, base_id)
                if isinstance(expression.slice, ast.Slice) else base_id
            )
            base_attributes = (
                graph.G.nodes[base_contract_id].get("attributes") or {}
                if isinstance(base_contract_id, int) and base_contract_id in graph.G else {}
            )
            base_class_cell = (
                current_identity_book().latest_ref(
                    _SOURCE_VALUE_CLASS,
                    (value_class_scope, int(base_contract_id)),
                )
                if isinstance(base_contract_id, int) else None
            )
            base_class_fact = (
                None if base_class_cell is None else
                current_identity_book().page(_SOURCE_VALUE_CLASS).cell(
                    base_class_cell.row, base_class_cell.column,
                )
            )
            if (
                isinstance(expression.slice, ast.Slice)
                and base_attributes.get("aggregate_kind") in {
                    "list", "set", "frozenset", "tuple",
                }
            ):
                # A sequence slice preserves the declared row contract.  In
                # ``for line in items[1:]`` the iterator is this slice, not
                # the parameter Input, so dropping the element-class edge
                # here made the loop target an untyped int64 token.
                projected = graph.G.nodes[node_id].setdefault(
                    "attributes", {}
                )
                projected.update({
                    "producer_kind": "sequence_slice",
                    "aggregate_kind": base_attributes["aggregate_kind"],
                    "sequence_key_columns": tuple(base_attributes.get(
                        "sequence_key_columns", ()
                    )),
                    "sequence_column_count": int(base_attributes.get(
                        "sequence_column_count", 1
                    )),
                    "sequence_writable": bool(base_attributes.get(
                        "sequence_writable", True
                    )),
                })
                for field in (
                    "sequence_element_dtypes",
                    "sequence_column_dtypes",
                    "sequence_element_class_ref",
                    "sequence_element_annotation_cell",
                    "sequence_element_record",
                ):
                    if field in base_attributes:
                        projected[field] = base_attributes[field]
            if (
                isinstance(expression.slice, ast.Slice)
                and isinstance(base_class_fact, tuple)
                and base_class_fact
                and _canonical_source_class_identity(
                    base_class_fact[0]
                ) == "builtins.str"
            ):
                # Slicing an authored string produces another resident string
                # sequence.  Carry the exact source-value class across the
                # existing base/index edges so f-string materialization can
                # extend from the slice itself instead of inventing a scalar
                # formatter or rejecting it as producerless.
                projected = graph.G.nodes[node_id].setdefault(
                    "attributes", {}
                )
                projected.update({
                    "result_class_ref": "str",
                    "producer_kind": "string_slice",
                    "aggregate_kind": "list",
                    "sequence_key_columns": (),
                    "sequence_column_count": 1,
                    "sequence_writable": True,
                    "sequence_element_dtypes": ("int64",),
                    "resident_string_sequence": True,
                })
                slice_sources = tuple(filter(None, (
                    node_identity_cell(graph, int(node_id)),
                    base_class_cell,
                )))
                _concord_source_value_class(
                    value_class_scope,
                    int(node_id),
                    "str",
                    source="authored string slice",
                    provenance=(
                        _Derived(slice_sources) if slice_sources else None
                    ),
                )
            partition_index = (
                int(expression.slice.value)
                if isinstance(expression.slice, ast.Constant)
                and isinstance(expression.slice.value, int)
                and not isinstance(expression.slice.value, bool)
                else None
            )
            if partition_index is not None and isinstance(base_id, int):
                concord_string_partition_member(
                    int(base_id), int(partition_index), int(node_id),
                )
            mapping_value_record = base_attributes.get(
                "mapping_value_record"
            )
            page_declaration_cell = base_attributes.get(
                "source_page_declaration_cell"
            )
            page_declaration = source_page_declaration(
                page_declaration_cell
            )
            page_row_fields = (
                () if page_declaration is None
                else tuple(page_declaration.row_fields)
            )
            page_column = (
                int(expression.slice.value)
                if isinstance(expression.slice, ast.Constant)
                and isinstance(expression.slice.value, int)
                and not isinstance(expression.slice.value, bool)
                else None
            )
            if (
                page_column is not None
                and 0 <= page_column < len(page_row_fields)
            ):
                field_name, field_kind = page_row_fields[page_column]
                projected = graph.G.nodes[node_id].setdefault(
                    "attributes", {}
                )
                projected.update({
                    "producer_kind": "page_row_projection",
                    "source_page_row_field": (
                        str(field_name), str(field_kind), int(page_column),
                    ),
                    "source_page_declaration_cell": page_declaration_cell,
                })
                if str(field_kind) == "SCOPE":
                    # A scope key is the book's ``(label, serial)`` pair:
                    # a two-column tuple whose row fields are the label
                    # (a string) and the serial (an integer).
                    projected.update({
                        "aggregate_kind": "tuple",
                        "sequence_key_columns": (),
                        "sequence_column_count": 2,
                        "sequence_writable": False,
                        "source_tuple_row_fields": (
                            ("label", "LABEL"), ("serial", "INDEX"),
                        ),
                    })
                elif str(field_kind) in {"INDEX", "VALUE_ID"}:
                    graph.G.nodes[node_id]["tensor"] = {
                        "shape": (), "dtype": "int64",
                    }
                    projected["value_kind"] = "scalar"
                elif str(field_kind) in {"LABEL", "NAME"}:
                    projected.update({
                        "aggregate_kind": "list",
                        "sequence_key_columns": (),
                        "sequence_column_count": 1,
                        "sequence_writable": False,
                        "sequence_element_dtypes": ("int64",),
                        "resident_string_sequence": True,
                    })
            if mapping_value_record is not None:
                # This is the keyed field's value-record edge, transferred to
                # the exact Indexed result while lexical values are being
                # assembled.  It is one concordance fact, not a later cache or
                # an inference from the surrounding call.
                graph.G.nodes[node_id].setdefault("attributes", {})[
                    "result_class_ref"
                ] = str(mapping_value_record)
                field_identity = base_attributes.get("record_field")
                field_cells = ()
                if (
                    isinstance(field_identity, tuple)
                    and len(field_identity) == 2
                ):
                    owner, field = map(str, field_identity)
                    field_page = current_identity_book().page(
                        _CLASS_FIELD_DECLARATION
                    )
                    field_cells = tuple(
                        filter(None, (
                            current_identity_book().latest_ref(
                                _CLASS_FIELD_DECLARATION, row,
                            )
                            for row in field_page.rows()
                            if len(row) == 3
                            and str(row[1]) == owner
                            and str(row[2]) == field
                        ))
                    )
                value_sources = tuple(dict.fromkeys(filter(None, (
                    node_identity_cell(graph, int(node_id)),
                    *field_cells,
                ))))
                if value_sources and field_cells:
                    _concord_source_value_class(
                        value_class_scope,
                        int(node_id),
                        str(mapping_value_record),
                        precision_limbs=1,
                        source="keyed value-record edge",
                        provenance=_Derived(value_sources),
                    )
            mapping_value_columns = tuple(
                base_attributes.get("mapping_value_columns") or ()
            )
            if (
                not isinstance(expression.slice, ast.Slice)
                and len(mapping_value_columns) > 1
                and source_aggregate_layout(int(node_id))[0] is None
            ):
                # A fixed-arity tuple in a mapping value position is stored as
                # one physical column per authored member.  Publish the lookup
                # result as the corresponding tuple aggregate now, while the
                # exact Indexed node and mapping declaration still own their
                # identity cells.  Control lowering consumes these minted
                # member ids as the multi-result lookup's physical outputs.
                lookup_cell = node_identity_cell(graph, int(node_id))
                base_cell = (
                    node_identity_cell(graph, int(base_id))
                    if isinstance(base_id, int) else None
                )
                result_members = []
                for index, column in enumerate(mapping_value_columns):
                    member_sources = tuple(dict.fromkeys(filter(None, (
                        lookup_cell, base_cell,
                    ))))
                    member_id = new_node(
                        "Indexed",
                        f"mapping value member {index}",
                        attributes={
                            "aggregate_parent_value_id": int(node_id),
                            "aggregate_index": int(index),
                            "producer_kind": "mapping_lookup_member",
                        },
                        parents=((int(node_id), "base"),),
                        source_cell=member_sources,
                        cause=_AGGREGATE_MEMBER,
                    )
                    dtype = column.get("dtype") if isinstance(
                        column, Mapping
                    ) else None
                    if dtype is not None:
                        graph.G.nodes[int(member_id)]["tensor"] = {
                            "shape": (), "dtype": str(dtype),
                        }
                    result_members.append(_SourceAggregateMember(
                        int(member_id),
                        node_identity_cell(graph, int(member_id)),
                        member_sources,
                    ))
                projected = graph.G.nodes[node_id].setdefault(
                    "attributes", {}
                )
                projected.update({
                    "producer_kind": "mapping_lookup_aggregate",
                    "aggregate_kind": "tuple",
                    "aggregate_leaf_value_ids": tuple(
                        member.value_id for member in result_members
                    ),
                })
                post_source_aggregate_layout(
                    int(node_id), "tuple", tuple(result_members),
                )
            sequence_element_class = base_attributes.get(
                "sequence_element_class_ref"
            )
            sequence_element_cell = base_attributes.get(
                "sequence_element_annotation_cell"
            )
            if (
                not isinstance(expression.slice, ast.Slice)
                and sequence_element_class is not None
                and isinstance(sequence_element_cell, _Ref)
            ):
                # A scalar index projects the declared element class from the
                # annotated sequence.  This is the non-loop counterpart of
                # ``concord_iterated_target_class``: ``first = rows[0]`` must
                # retain the same record identity as ``for first in rows``.
                graph.G.nodes[node_id].setdefault("attributes", {})[
                    "result_class_ref"
                ] = str(sequence_element_class)
                element_sources = tuple(dict.fromkeys(filter(None, (
                    sequence_element_cell,
                    node_identity_cell(graph, int(base_id)),
                    node_identity_cell(graph, int(node_id)),
                ))))
                _concord_source_value_class(
                    value_class_scope,
                    int(node_id),
                    str(sequence_element_class),
                    source="declared sequence indexed element projection",
                    provenance=_Derived(element_sources),
                )
        if (
            isinstance(expression, (ast.Tuple, ast.List, ast.Set, ast.Dict))
            and node_id in graph.G
        ):
            aggregate = graph.G.nodes[node_id]
            aggregate_attributes = aggregate.setdefault("attributes", {})
            aggregate_attributes["producer_kind"] = "aggregate"
            aggregate_kind = {
                ast.Tuple: "tuple",
                ast.List: "list",
                ast.Set: "set",
                ast.Dict: "dict",
            }[type(expression)]
            aggregate_attributes.update({
                "aggregate_kind": aggregate_kind,
                "sequence_key_columns": (
                    (0,) if aggregate_kind in {"set", "dict"} else ()
                ),
                "sequence_column_count": (
                    2 if aggregate_kind == "dict" else 1
                ),
                "sequence_writable": aggregate_kind != "tuple",
            })
            aggregate_member_positions = tuple(
                (str(role), int(ordinal), int(parent))
                for role, ordinal, parent in _operand_positions(
                    aggregate.get("parents") or ()
                )
                if str(role) in {
                    "elts",
                    "elt",
                    "element",
                    "item",
                    "keys",
                    "values",
                    "key",
                    "value",
                }
            )
            aggregate_attributes["aggregate_leaf_value_ids"] = tuple(
                parent for _role, _ordinal, parent
                in aggregate_member_positions
            )
            source_members = []
            for role, ordinal, member_id in aggregate_member_positions:
                member_cell = node_identity_cell(graph, int(member_id))
                position_cell = aggregate_position_cell(
                    int(node_id), str(role), int(ordinal),
                )
                if member_cell is None or position_cell is None:
                    raise ValueError(
                        "source aggregate member has no exact identity/slot "
                        f"cell: aggregate={int(node_id)} member={member_id} "
                        f"role={role!r} ordinal={ordinal}"
                    )
                _member_layout, member_layout_cell = (
                    source_aggregate_layout(int(member_id))
                )
                source_members.append(_SourceAggregateMember(
                    int(member_id), member_cell,
                    tuple(filter(None, (
                        position_cell, member_layout_cell,
                    ))),
                ))
            post_source_aggregate_layout(
                int(node_id), str(aggregate_kind), tuple(source_members),
            )
            aggregate_class_sources = tuple(filter(None, (
                node_identity_cell(graph, int(node_id)),
                current_identity_book().latest_ref(
                    _SOURCE_AGGREGATE_LAYOUT,
                    (ingestion_read_scope, int(node_id)),
                ),
            )))
            _concord_source_value_class(
                value_class_scope,
                int(node_id),
                f"builtins.{aggregate_kind}",
                source="authored aggregate constructor",
                provenance=(
                    _Derived(aggregate_class_sources)
                    if aggregate_class_sources else None
                ),
            )
        lone_string_projection = (
            isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Name)
            and expression.func.id == "str"
            and len(expression.args) == 1
            and not expression.keywords
        )
        if (
            isinstance(expression, ast.JoinedStr) or lone_string_projection
        ) and node_id in graph.G:
            # A dynamic source string is one ordinary resident sequence whose
            # rows are reversible single-glyph StringTable tokens.  Publish
            # the exact ordered source recipe here, while the JoinedStr /
            # FormattedValue edges still exist.  Later materialization reads
            # this cell; it must not reconstruct the recipe from surviving
            # AST nodes or treat a whole-word string_token as the string.
            from ...compiler.string_table import string_token
            from ...compiler.concordance_declarations import (
                IDENTITY_TRANSITION,
            )

            # Source pursuit can make the same authored JoinedStr reachable
            # through more than one retained function copy.  A dynamic recipe
            # contains projection/formatter nodes minted in THIS copy, so its
            # ingestion row is copy-local as well.  Never reuse the row leaked
            # by another copy: its private producers cannot be mapped into
            # this graph.
            existing_row = (
                graph.G.nodes[node_id].get("attributes") or {}
            ).get("source_glyph_sequence_row")
            if (
                existing_row is not None
                and existing_row[0] == ingestion_read_scope
                and current_identity_book().page(
                    _SOURCE_GLYPH_SEQUENCE
                ).latest(existing_row) is not None
            ):
                return node_id

            def operand_position_cell(
                consumer_id: int, parent_id: int, role: str,
                ordinal: int,
            ) -> Any:
                """The exact authored/rewrite cell owning this edge slot."""

                book = current_identity_book()
                for scope in dict.fromkeys((
                    _operand_position_scope(graph), entry_operand_scope,
                    graph.G.graph.get("ingestion_value_scope"),
                )):
                    if scope is None:
                        continue
                    cell = book.latest_ref(
                        IDENTITY_TRANSITION,
                        (scope, int(consumer_id), str(role), int(ordinal)),
                    )
                    if cell is not None:
                        # The row, not the historical operand payload, is the
                        # identity of this exact consumer slot.  A lexical
                        # redirect can change the parent from its Name
                        # occurrence to the bound value while this cell still
                        # owns (consumer, role, ordinal); the bound value's own
                        # node cell below proves the current endpoint.
                        return cell
                return None

            def contains_source(root: ast.AST, target: ast.AST) -> bool:
                return any(member is target for member in ast.walk(root))

            def isinstance_test_class(
                test: ast.AST, binding: str,
            ) -> tuple[str | None, bool]:
                positive = True
                if isinstance(test, ast.UnaryOp) and isinstance(
                    test.op, ast.Not,
                ):
                    positive = False
                    test = test.operand
                if not (
                    isinstance(test, ast.Call)
                    and isinstance(test.func, ast.Name)
                    and test.func.id == "isinstance"
                    and len(test.args) == 2
                    and isinstance(test.args[0], ast.Name)
                    and test.args[0].id == binding
                    and isinstance(test.args[1], ast.Name)
                    and test.args[1].id
                    in (graph.G.graph.get("class_table") or {})
                ):
                    return None, positive
                return str(test.args[1].id), positive

            def branch_class_refinement(
                target: ast.AST, binding: str,
                *, optional_identity: str | None = None,
                optional_declaration_cell: _Ref | None = None,
            ) -> tuple[str | None, tuple[_Ref, ...]]:
                """Exact class proof owned by the target's control arm."""

                def none_test(
                    test: ast.AST,
                ) -> tuple[bool | None, ast.Compare | None]:
                    """Whether ``binding`` is proven present by ``test``.

                    The bool is true for ``is not None`` and false for
                    ``is None``. A leading conjunct owns the same proof for
                    the body because later conjuncts execute only after it.
                    """

                    candidates = (
                        tuple(test.values)
                        if isinstance(test, ast.BoolOp)
                        and isinstance(test.op, ast.And)
                        else (test,)
                    )
                    for candidate in candidates:
                        if not (
                            isinstance(candidate, ast.Compare)
                            and isinstance(candidate.left, ast.Name)
                            and candidate.left.id == binding
                            and len(candidate.ops) == 1
                            and isinstance(candidate.ops[0], (ast.Is, ast.IsNot))
                            and len(candidate.comparators) == 1
                            and isinstance(candidate.comparators[0], ast.Constant)
                            and candidate.comparators[0].value is None
                        ):
                            continue
                        return isinstance(candidate.ops[0], ast.IsNot), candidate
                    return None, None

                def terminating(block: list[ast.stmt]) -> bool:
                    return bool(block) and isinstance(
                        block[-1], (ast.Return, ast.Raise),
                    )

                def walk_block(block: list[ast.stmt]):
                    carried_class = None
                    carried_sources: tuple[_Ref, ...] = ()
                    for member in block:
                        if contains_source(member, target):
                            if isinstance(member, ast.If):
                                class_identity, positive = (
                                    isinstance_test_class(member.test, binding)
                                )
                                in_body = any(
                                    contains_source(child, target)
                                    for child in member.body
                                )
                                in_else = any(
                                    contains_source(child, target)
                                    for child in member.orelse
                                )
                                selected = (
                                    in_body and positive
                                    or in_else and not positive
                                )
                                if class_identity is not None and selected:
                                    condition_cell = node_identity_cell(
                                        graph, id(member.test),
                                    )
                                    module_identity = str(getattr(
                                        member.test,
                                        "_turing_source_module", "",
                                    ))
                                    class_cell = current_identity_book().latest_ref(
                                        _CLASS_DECLARATION,
                                        (module_identity, class_identity),
                                    )
                                    return class_identity, tuple(
                                        dict.fromkeys(filter(None, (
                                            condition_cell, class_cell,
                                        )))
                                    )
                                present, condition = none_test(member.test)
                                if (
                                    optional_identity is not None
                                    and condition is not None
                                    and (
                                        in_body and present is True
                                        or in_else and present is False
                                    )
                                ):
                                    return str(optional_identity), tuple(
                                        dict.fromkeys(filter(None, (
                                            _authored_node_cell(graph, condition),
                                            optional_declaration_cell,
                                        )))
                                    )
                                if (
                                    optional_identity is not None
                                    and class_identity == optional_identity
                                    and in_body and not positive
                                ):
                                    # Page.latest admits exactly its declared
                                    # fact class or absence. Its negative
                                    # isinstance arm is therefore the literal
                                    # None arm, not an open runtime union.
                                    return "builtins.NoneType", tuple(
                                        dict.fromkeys(filter(None, (
                                            node_identity_cell(
                                                graph, id(member.test),
                                            ),
                                            optional_declaration_cell,
                                        )))
                                    )
                                nested = walk_block(
                                    member.body if in_body else member.orelse
                                )
                                if nested[0] is not None:
                                    return nested
                            return carried_class, carried_sources
                        if isinstance(member, ast.If) and not member.orelse:
                            class_identity, positive = isinstance_test_class(
                                member.test, binding,
                            )
                            if (
                                class_identity is not None
                                and not positive
                                and terminating(member.body)
                            ):
                                condition_cell = node_identity_cell(
                                    graph, id(member.test),
                                )
                                module_identity = str(getattr(
                                    member.test,
                                    "_turing_source_module", "",
                                ))
                                class_cell = current_identity_book().latest_ref(
                                    _CLASS_DECLARATION,
                                    (module_identity, class_identity),
                                )
                                carried_class = class_identity
                                carried_sources = tuple(dict.fromkeys(filter(
                                    None, (condition_cell, class_cell),
                                )))
                    return carried_class, carried_sources

                return walk_block(list(getattr(statement, "body", ())))

            def borrowed_page_refinement(
                target: ast.AST, binding: str,
            ) -> tuple[str | None, tuple[_Ref, ...]]:
                # ``latest`` is optional.  Accept its record class only after
                # the exact ``is None`` early-return proves this use present.
                def containing_block(block: list[ast.stmt]):
                    for member in block:
                        for nested in (
                            getattr(member, "body", ()),
                            getattr(member, "orelse", ()),
                            getattr(member, "finalbody", ()),
                        ):
                            if any(contains_source(child, target) for child in nested):
                                deeper = containing_block(list(nested))
                                return deeper or list(nested)
                    return None

                statements = containing_block(
                    list(getattr(statement, "body", ()))
                ) or list(getattr(statement, "body", ()))
                latest_receiver = None
                target_index = None
                for index, member in enumerate(statements):
                    if contains_source(member, target):
                        target_index = index
                        break
                    for candidate in ast.walk(member):
                        if not (
                            isinstance(candidate, (ast.Assign, ast.AnnAssign))
                        ):
                            continue
                        targets = (
                            tuple(candidate.targets)
                            if isinstance(candidate, ast.Assign)
                            else (candidate.target,)
                        )
                        value = candidate.value
                        if (
                            any(
                                isinstance(item, ast.Name)
                                and item.id == binding for item in targets
                            )
                            and isinstance(value, ast.Call)
                            and isinstance(value.func, ast.Attribute)
                            and value.func.attr == "latest"
                            and isinstance(value.func.value, ast.Name)
                        ):
                            latest_receiver = value.func.value.id
                if latest_receiver is None or target_index is None:
                    return None, ()
                non_none_cell = None
                for member in statements[:target_index]:
                    # ``if x is None: return`` and ``if x is None or <more
                    # on x>: return`` both prove ``x`` present below: the
                    # ``is None`` test is the first operand of the ``or``.
                    presence_test = member.test if isinstance(member, ast.If) else None
                    if (
                        isinstance(presence_test, ast.BoolOp)
                        and isinstance(presence_test.op, ast.Or)
                        and presence_test.values
                    ):
                        presence_test = presence_test.values[0]
                    if not (
                        isinstance(member, ast.If)
                        and not member.orelse
                        and member.body
                        and isinstance(member.body[-1], (ast.Return, ast.Raise))
                        and isinstance(presence_test, ast.Compare)
                        and isinstance(presence_test.left, ast.Name)
                        and presence_test.left.id == binding
                        and len(presence_test.ops) == 1
                        and isinstance(presence_test.ops[0], ast.Is)
                        and len(presence_test.comparators) == 1
                        and isinstance(presence_test.comparators[0], ast.Constant)
                        and presence_test.comparators[0].value is None
                    ):
                        continue
                    # The test's node in THIS graph: a function subgraph
                    # relabels its nodes, so the authored ``Compare`` is
                    # found by the AST object the node still carries.
                    test_node = next((
                        candidate for candidate, candidate_data
                        in graph.G.nodes(data=True)
                        if candidate_data.get("expr_obj") is member.test
                    ), None)
                    non_none_cell = (
                        None if test_node is None
                        else node_identity_cell(graph, test_node)
                    )
                if non_none_cell is None:
                    return None, ()
                page_name = None
                for member in ast.walk(statement):
                    if not isinstance(member, (ast.With, ast.AsyncWith)):
                        continue
                    for item in member.items:
                        context = item.context_expr
                        if not (
                            isinstance(item.optional_vars, ast.Name)
                            and item.optional_vars.id == latest_receiver
                            and isinstance(context, ast.Call)
                            and isinstance(context.func, ast.Attribute)
                            and context.func.attr == "borrowed"
                            and len(context.args) == 1
                            and isinstance(context.args[0], ast.Constant)
                            and isinstance(context.args[0].value, str)
                        ):
                            continue
                        page_name = str(context.args[0].value)
                declared = dict(graph.G.graph.get(
                    "declared_page_fact_classes"
                ) or {}).get(str(page_name))
                if declared is None:
                    return None, ()
                _class_identity, page_cell, _row_fields = declared
                # The class as the class table names it: the declared
                # class's own row (the page declaration derives from it),
                # not the module-qualified spelling of the page fact class.
                class_cell = next((
                    source for source, _stage in book.edges_into(page_cell)
                    if source.page == _CLASS_DECLARATION
                ), None)
                if class_cell is None:
                    return None, ()
                return str(class_cell.row[1]), tuple(dict.fromkeys((
                    page_cell, class_cell, non_none_cell,
                )))

            def projected_literal_component(
                text: str, *sources: _Ref,
            ) -> _SourceGlyphComponent:
                literal_id = new_node(
                    "Const", "glyph projection literal",
                    attributes={
                        "value": tuple(
                            int(string_token(character))
                            for character in str(text)
                        ),
                        "producer_kind": "literal_glyph_sequence",
                        "aggregate_kind": "list",
                        "sequence_key_columns": (),
                        "sequence_column_count": 1,
                        "sequence_writable": False,
                        "sequence_element_dtypes": ("int64",),
                    },
                    source_cell=tuple(dict.fromkeys(filter(None, sources))),
                )
                return _SourceGlyphComponent(
                    kind="literal",
                    component_value_id=int(literal_id),
                    operand_value_id=None,
                    glyph_tokens=tuple(
                        int(string_token(character))
                        for character in str(text)
                    ),
                    conversion=-1,
                    format_spec_value_id=None,
                    projection_kind="literal",
                    record_identity=None,
                )

            def optional_or_absence_owner(
                target: ast.AST, binding: str,
            ) -> tuple[ast.If, ast.Compare] | None:
                """The exact short-circuit absence edge owning ``target``.

                In ``if value is None or mismatch(value):`` the body does not
                prove ``value`` present.  A repr in that body therefore needs
                a nested resident-sequence conditional.  Retain the authored
                comparison itself as the predicate; do not turn the enclosing
                OR into a class assertion.
                """

                for candidate in ast.walk(statement):
                    if not (
                        isinstance(candidate, ast.If)
                        and isinstance(candidate.test, ast.BoolOp)
                        and isinstance(candidate.test.op, ast.Or)
                        and any(
                            contains_source(member, target)
                            for member in candidate.body
                        )
                    ):
                        continue
                    for predicate in candidate.test.values:
                        if (
                            isinstance(predicate, ast.Compare)
                            and isinstance(predicate.left, ast.Name)
                            and predicate.left.id == binding
                            and len(predicate.ops) == 1
                            and isinstance(predicate.ops[0], ast.Is)
                            and len(predicate.comparators) == 1
                            and isinstance(
                                predicate.comparators[0], ast.Constant,
                            )
                            and predicate.comparators[0].value is None
                            and id(predicate) in graph.G
                        ):
                            return candidate, predicate
                return None

            source_components = (
                tuple(expression.values)
                if isinstance(expression, ast.JoinedStr)
                else (expression,)
            )
            components = []
            component_sources = []
            valid = True
            for component_ordinal, component in enumerate(source_components):
                component_id = id(component)
                if component_id not in graph.G:
                    valid = False
                    break
                component_data = graph.G.nodes[component_id]
                component_value_id = int(component_data.get(
                    "value_id", component_id
                ))
                component_cell = node_identity_cell(graph, component_id)
                if component_cell is None:
                    valid = False
                    break
                component_sources.append(component_cell)
                if not lone_string_projection:
                    component_order_cell = operand_position_cell(
                        int(node_id), int(component_id), "values",
                        int(component_ordinal),
                    )
                    if component_order_cell is None:
                        valid = False
                        break
                    component_sources.append(component_order_cell)
                # ``FormattedValue`` children inherit the enclosing f-string
                # source span on CPython's AST.  Two occurrences such as
                # ``f"{value} {value}"`` therefore otherwise have identical
                # structural token chains, and graph insertion order can
                # exchange their canonical ids on a repeated source walk.
                # The operand-position cell above is the causal identity of
                # this exact authored slot.  Keep its stable source spelling
                # as a graph read view so canonical relabeling orders the
                # occurrences by the JoinedStr position and slot ordinal,
                # never by interchangeable operand ids or graph iteration.
                occurrence_owner = (
                    getattr(expression, "lineno", -1),
                    getattr(expression, "col_offset", -1),
                    getattr(expression, "end_lineno", -1),
                    getattr(expression, "end_col_offset", -1),
                    int(component_ordinal),
                )
                component_data.setdefault("attributes", {})[
                    "source_glyph_occurrence"
                ] = occurrence_owner
                if isinstance(component, ast.Constant) and isinstance(
                    component.value, str
                ):
                    components.append(_SourceGlyphComponent(
                        kind="literal",
                        component_value_id=component_value_id,
                        operand_value_id=None,
                        glyph_tokens=tuple(
                            int(string_token(character))
                            for character in component.value
                        ),
                        conversion=-1,
                        format_spec_value_id=None,
                        projection_kind="literal",
                        record_identity=None,
                    ))
                    continue
                if not (
                    isinstance(component, ast.FormattedValue)
                    or lone_string_projection
                ):
                    valid = False
                    break
                operand_role = "arg:0" if lone_string_projection else "value"
                operand_source_role = (
                    "args" if lone_string_projection else "value"
                )
                operand_node_id = next((
                    int(parent)
                    for parent, role in component_data.get("parents") or ()
                    if str(role) == operand_role and int(parent) in graph.G
                ), None)
                if operand_node_id is None:
                    valid = False
                    break
                operand_data = graph.G.nodes[operand_node_id]
                operand_value_id = int(operand_data.get(
                    "value_id", operand_node_id
                ))
                operand_cell = node_identity_cell(graph, operand_node_id)
                if operand_cell is None:
                    valid = False
                    break
                component_sources.append(operand_cell)
                operand_order_cell = operand_position_cell(
                    int(component_id), int(operand_node_id),
                    operand_source_role, 0,
                )
                if operand_order_cell is None:
                    valid = False
                    break
                component_sources.append(operand_order_cell)
                format_spec_value_id = None
                if (
                    isinstance(component, ast.FormattedValue)
                    and component.format_spec is not None
                ):
                    format_node_id = next((
                        int(parent)
                        for parent, role in component_data.get("parents") or ()
                        if str(role) == "format_spec" and int(parent) in graph.G
                    ), None)
                    if format_node_id is None:
                        valid = False
                        break
                    format_data = graph.G.nodes[format_node_id]
                    format_spec_value_id = int(format_data.get(
                        "value_id", format_node_id
                    ))
                    format_cell = node_identity_cell(graph, format_node_id)
                    if format_cell is None:
                        valid = False
                        break
                    component_sources.append(format_cell)
                operand_attributes = operand_data.get("attributes") or {}
                book = current_identity_book()
                value_class_cell = book.latest_ref(
                    _SOURCE_VALUE_CLASS,
                    (value_class_scope, int(operand_value_id)),
                )
                call_result_cell = book.latest_ref(
                    _SOURCE_CALL_RESULT_IDENTITY,
                    (value_class_scope, int(operand_value_id)),
                )
                value_class_fact = (
                    None if value_class_cell is None
                    else book.page(_SOURCE_VALUE_CLASS).cell(
                        value_class_cell.row, value_class_cell.column,
                    )
                )
                call_result_fact = (
                    None if call_result_cell is None
                    else book.page(_SOURCE_CALL_RESULT_IDENTITY).cell(
                        call_result_cell.row, call_result_cell.column,
                    )
                )
                declared_identity = (
                    str(value_class_fact[0])
                    if isinstance(value_class_fact, tuple) and value_class_fact
                    else str(call_result_fact[1])
                    if (
                        isinstance(call_result_fact, tuple)
                        and len(call_result_fact) >= 2
                    )
                    else None
                )
                if declared_identity is None and operand_attributes.get(
                    "optional_result_class_ref"
                ) is not None:
                    # A page ``latest`` result: its declared class is the
                    # page's fact class; whether this use proves it present
                    # is the control arm's (or the optional dispatch's)
                    # decision below.
                    declared_identity = str(
                        operand_attributes["optional_result_class_ref"]
                    )
                source_operand = (
                    expression.args[0]
                    if lone_string_projection else component.value
                )
                # Closed source literals use the compiler's authored glyph
                # formatter.  Never ask the host interpreter for ``repr``:
                # an unsupported literal remains on the ordinary resident
                # value path and is refused unless that path has a producer.
                if (
                    isinstance(component, ast.FormattedValue)
                    and int(component.conversion) == ord("r")
                    and component.format_spec is None
                    and isinstance(source_operand, ast.Constant)
                ):
                    from ...compiler.glyph_sequence_format import (
                        static_literal_repr_glyph_tokens,
                    )
                    literal_glyphs = static_literal_repr_glyph_tokens(
                        source_operand.value
                    )
                    if literal_glyphs is not None:
                        components.append(_SourceGlyphComponent(
                            kind="literal",
                            component_value_id=component_value_id,
                            operand_value_id=operand_value_id,
                            glyph_tokens=tuple(map(int, literal_glyphs)),
                            conversion=ord("r"),
                            format_spec_value_id=None,
                            projection_kind="literal",
                            record_identity=None,
                        ))
                        continue
                enum_name_cell = None
                enum_name_value_id = None
                enum_name_identity = None
                if (
                    isinstance(source_operand, ast.Attribute)
                    and str(source_operand.attr) == "name"
                ):
                    enum_receiver_id = next((
                        int(parent)
                        for parent, role in operand_data.get("parents") or ()
                        if str(role) == "value" and int(parent) in graph.G
                    ), None)
                    if enum_receiver_id is not None:
                        enum_receiver_data = graph.G.nodes[enum_receiver_id]
                        enum_receiver_value_id = int(
                            enum_receiver_data.get(
                                "value_id", enum_receiver_id,
                            )
                        )
                        enum_class_cell = book.latest_ref(
                            _SOURCE_VALUE_CLASS,
                            (
                                value_class_scope,
                                int(enum_receiver_value_id),
                            ),
                        )
                        enum_class_fact = (
                            None if enum_class_cell is None else
                            book.page(_SOURCE_VALUE_CLASS).cell(
                                enum_class_cell.row,
                                enum_class_cell.column,
                            )
                        )
                        enum_identity = (
                            str(enum_class_fact[0])
                            if isinstance(enum_class_fact, tuple)
                            and enum_class_fact else None
                        )
                        if enum_identity is not None:
                            module_identity = (
                                str(value_class_scope[0])
                                if isinstance(value_class_scope, tuple)
                                and value_class_scope else str(getattr(
                                    source_operand,
                                    "_turing_source_module", "",
                                ))
                            )
                            enum_name_cell = book.latest_ref(
                                _SOURCE_ENUM_GLYPH_TABLE,
                                (module_identity, enum_identity),
                            )
                            if enum_name_cell is not None:
                                enum_name_value_id = enum_receiver_value_id
                                enum_name_identity = enum_identity
                                component_sources.extend(tuple(filter(
                                    None, (
                                        enum_class_cell,
                                        node_identity_cell(
                                            graph, enum_receiver_id,
                                        ),
                                        enum_name_cell,
                                    ),
                                )))
                refinement_binding = (
                    source_operand.id
                    if isinstance(source_operand, ast.Name)
                    else source_operand.value.id
                    if (
                        isinstance(source_operand, ast.Attribute)
                        and isinstance(source_operand.value, ast.Name)
                    )
                    else None
                )
                refinement_identity = None
                refinement_cells: tuple[_Ref, ...] = ()
                if refinement_binding is not None:
                    refinement_identity, refinement_cells = (
                        branch_class_refinement(
                            component,
                            str(refinement_binding),
                            optional_identity=(
                                str(operand_attributes[
                                    "optional_result_class_ref"
                                ])
                                if operand_attributes.get(
                                    "optional_result_class_ref"
                                ) is not None else None
                            ),
                            optional_declaration_cell=(
                                operand_attributes.get(
                                    "source_page_declaration_cell"
                                )
                            ),
                        )
                    )
                    if refinement_identity is None:
                        refinement_identity, refinement_cells = (
                            borrowed_page_refinement(
                                component, str(refinement_binding),
                            )
                        )
                    if refinement_identity is None:
                        local_declaration = local_class_declarations.get(
                            str(refinement_binding)
                        )
                        if (
                            local_declaration is not None
                            and local_declaration[1] is not None
                        ):
                            local_identity, local_annotation_cell = (
                                local_declaration
                            )
                            module_identity = (
                                str(value_class_scope[0])
                                if isinstance(value_class_scope, tuple)
                                and value_class_scope else str(getattr(
                                    source_operand,
                                    "_turing_source_module", "",
                                ))
                            )
                            class_cell = book.latest_ref(
                                _CLASS_DECLARATION,
                                (module_identity, str(local_identity)),
                            )
                            refinement_identity = str(local_identity)
                            refinement_cells = tuple(dict.fromkeys(filter(
                                None, (local_annotation_cell, class_cell),
                            )))
                    if refinement_identity is None:
                        parameter_cell = book.latest_ref(
                            _PARAMETER_ANNOTATION,
                            (*tuple(value_class_scope), str(refinement_binding)),
                        )
                        if parameter_cell is not None:
                            parameter_identity = str(book.page(
                                _PARAMETER_ANNOTATION
                            ).cell(
                                parameter_cell.row, parameter_cell.column,
                            ))
                            if parameter_identity in (
                                graph.G.graph.get("class_table") or {}
                            ):
                                module_identity = (
                                    str(value_class_scope[0])
                                    if isinstance(value_class_scope, tuple)
                                    and value_class_scope else str(getattr(
                                        source_operand,
                                        "_turing_source_module", "",
                                    ))
                                )
                                class_cell = book.latest_ref(
                                    _CLASS_DECLARATION,
                                    (module_identity, parameter_identity),
                                )
                                refinement_identity = parameter_identity
                                refinement_cells = tuple(dict.fromkeys(filter(
                                    None, (parameter_cell, class_cell),
                                )))
                if declared_identity is None and isinstance(
                    source_operand, ast.Name,
                ):
                    declared_identity = refinement_identity
                if declared_identity == "builtins.NoneType":
                    components.append(projected_literal_component(
                        "None", *refinement_cells,
                    ))
                    component_sources.extend(refinement_cells)
                    continue
                field_annotation = None
                if (
                    isinstance(source_operand, ast.Attribute)
                    and refinement_identity is not None
                ):
                    module_identity = (
                        str(value_class_scope[0])
                        if isinstance(value_class_scope, tuple)
                        and value_class_scope else str(getattr(
                            source_operand, "_turing_source_module", "",
                        ))
                    )
                    field_cell = book.latest_ref(
                        _CLASS_FIELD_DECLARATION,
                        (
                            module_identity, str(refinement_identity),
                            str(source_operand.attr),
                        ),
                    )
                    if field_cell is not None:
                        field_fact = book.page(
                            _CLASS_FIELD_DECLARATION
                        ).cell(field_cell.row, field_cell.column)
                        field_annotation = str(getattr(
                            field_fact, "annotation", "",
                        ))
                        field_is_tuple = any(
                            part in {
                                "tuple", "builtins.tuple", "<class'tuple'>",
                            }
                            for part in field_annotation.replace(
                                " ", ""
                            ).split("|")
                        )
                        component_sources.append(field_cell)
                        if field_annotation in {
                            "str", "builtins.str", "<class 'str'>",
                        }:
                            declared_identity = "str"
                        elif field_annotation in (
                            graph.G.graph.get("class_table") or {}
                        ):
                            declared_identity = field_annotation
                component_sources.extend(
                    cell for cell in (value_class_cell, call_result_cell)
                    if cell is not None
                )
                component_sources.extend(refinement_cells)
                class_table = graph.G.graph.get("class_table") or {}
                record_identity = (
                    declared_identity
                    if declared_identity in class_table else None
                )
                operand_expression = operand_data.get("expr_obj")
                aggregate_kind = operand_attributes.get("aggregate_kind")
                parameter_annotation_cell = None
                if operand_attributes.get("binding_kind") == "parameter":
                    parameter_name = operand_attributes.get("binding_name")
                    if parameter_name is not None:
                        from ...compiler.concordance_declarations import (
                            PARAMETER_ANNOTATION,
                        )
                        parameter_annotation_cell = book.latest_ref(
                            PARAMETER_ANNOTATION,
                            (*tuple(value_class_scope), str(parameter_name)),
                        )
                parameter_annotation = (
                    None if parameter_annotation_cell is None else
                    book.page(PARAMETER_ANNOTATION).cell(
                        parameter_annotation_cell.row,
                        parameter_annotation_cell.column,
                    )
                )
                if parameter_annotation_cell is not None:
                    component_sources.append(parameter_annotation_cell)
                annotated_string = str(parameter_annotation) in {
                    "str", "builtins.str", "<class 'str'>",
                }
                projection_kind = (
                    "enum_name" if enum_name_cell is not None
                    else "record" if record_identity is not None
                    else "string_token" if annotated_string or declared_identity in {
                        "str", "builtins.str",
                    }
                    else "tuple" if (
                        aggregate_kind == "tuple"
                        or isinstance(operand_expression, ast.Tuple)
                        or field_annotation in {
                            "tuple", "builtins.tuple", "<class 'tuple'>",
                        }
                    )
                    else "scalar"
                )
                projection_names = ()
                projection_value_ids = ()
                projection_components = ()

                def declared_page_tuple_projection(
                    tuple_value_id: int,
                    tuple_value_cell: _Ref,
                    declaration_cell: _Ref,
                    row_fields: tuple[tuple[str, str], ...],
                ) -> tuple[tuple[int, ...], tuple[_SourceGlyphComponent, ...]]:
                    """Project one Page key only through its declaration Ref."""

                    declaration = source_page_declaration(declaration_cell)
                    # The tuple is the page's whole key, or one SCOPE
                    # column of it: a scope key is the book's ``(label,
                    # serial)`` pair, declared by that column's kind.
                    page_row_field = operand_attributes.get(
                        "source_page_row_field"
                    )
                    scope_column = (
                        declaration is not None
                        and isinstance(page_row_field, tuple)
                        and len(page_row_field) == 3
                        and str(page_row_field[1]) == "SCOPE"
                        and 0 <= int(page_row_field[2]) < len(declaration.row_fields)
                        and str(declaration.row_fields[int(page_row_field[2])][1])
                        == "SCOPE"
                        and tuple(row_fields) == (
                            ("label", "LABEL"), ("serial", "INDEX"),
                        )
                    )
                    if declaration is None or (
                        tuple(declaration.row_fields) != tuple(row_fields)
                        and not scope_column
                    ):
                        raise ValueError(
                            "Page tuple glyph projection lacks its exact "
                            "declaration-owned row schema"
                        )
                    values = []
                    recipe = [projected_literal_component(
                        "(", tuple_value_cell, declaration_cell,
                    )]
                    for ordinal, (field_name, field_kind) in enumerate(
                        row_fields
                    ):
                        if ordinal:
                            recipe.append(projected_literal_component(
                                ", ", declaration_cell,
                            ))
                        index_id = new_node(
                            "Const", "tuple projection index",
                            attributes={
                                "value": int(ordinal),
                                "value_kind": "scalar",
                            },
                            source_cell=(declaration_cell,),
                        )
                        graph.G.nodes[int(index_id)]["tensor"] = {
                            "shape": (), "dtype": "int64",
                        }
                        field_id = new_node(
                            "Indexed", f"tuple[{ordinal}]",
                            attributes={
                                "source_type": "Subscript",
                                "producer_kind": "page_scope_projection",
                                "source_tuple_row_field": (
                                    str(field_name), str(field_kind),
                                    int(ordinal),
                                ),
                                "value_kind": "scalar",
                            },
                            parents=(
                                (int(tuple_value_id), "base"),
                                (int(index_id), "index"),
                            ),
                            source_cell=(tuple_value_cell, declaration_cell),
                        )
                        graph.G.nodes[int(field_id)]["tensor"] = {
                            "shape": (), "dtype": "int64",
                        }
                        values.append(int(field_id))
                        kind = (
                            "string_token"
                            if str(field_kind) in {"LABEL", "NAME"}
                            else "scalar"
                        )
                        formatter_id = None
                        if kind == "scalar" and str(field_kind) in {
                            "INDEX", "VALUE_ID",
                        }:
                            formatter = next((
                                entry for entry in function_table
                                if str(entry.qualified_name) == (
                                    "src.compiler.glyph_sequence_format."
                                    "decimal_integer_glyph_tokens"
                                )
                            ), None)
                            if formatter is not None:
                                formatter_id = new_node(
                                    "Call", "decimal_integer_glyph_tokens",
                                    attributes={
                                        "callee_ref": int(
                                            formatter.reference.address
                                        ),
                                        "callee_resolution": (
                                            "source-glyph-formatter"
                                        ),
                                        "producer_kind": (
                                            "formatted_glyph_sequence"
                                        ),
                                        "aggregate_kind": "list",
                                        "sequence_key_columns": (),
                                        "sequence_column_count": 1,
                                        "sequence_writable": True,
                                        "sequence_element_dtypes": ("int64",),
                                    },
                                    parents=((int(field_id), "arg:0"),),
                                    source=component,
                                    source_cell=(declaration_cell,),
                                )
                        recipe.append(_SourceGlyphComponent(
                            kind="formatted",
                            component_value_id=int(field_id),
                            operand_value_id=int(field_id), glyph_tokens=(),
                            conversion=ord("r"), format_spec_value_id=None,
                            projection_kind=kind, record_identity=None,
                            formatted_sequence_value_id=formatter_id,
                        ))
                    if len(row_fields) == 1:
                        recipe.append(projected_literal_component(
                            ",", declaration_cell,
                        ))
                    recipe.append(projected_literal_component(
                        ")", tuple_value_cell, declaration_cell,
                    ))
                    return tuple(values), tuple(recipe)

                if projection_kind == "record":
                    record = class_table.get(str(record_identity)) or {}
                    projection_names = tuple(map(str, record.get(
                        "fields", ()
                    )))
                    module_identity = (
                        value_class_scope[0]
                        if isinstance(value_class_scope, tuple)
                        and value_class_scope
                        else value_class_scope
                    )
                    field_cells = tuple(
                        book.latest_ref(
                            _CLASS_FIELD_DECLARATION,
                            (
                                module_identity, str(record_identity),
                                str(field_name),
                            ),
                        )
                        for field_name in projection_names
                    )
                    if not projection_names or any(
                        cell is None for cell in field_cells
                    ):
                        valid = False
                        break
                    component_sources.extend(field_cells)
                    projected_values = []
                    projected_components = [projected_literal_component(
                        f"{record_identity}(", operand_cell,
                    )]
                    for field_ordinal, (field_name, field_cell) in enumerate(
                        zip(projection_names, field_cells)
                    ):
                        field_fact = book.page(
                            _CLASS_FIELD_DECLARATION
                        ).cell(field_cell.row, field_cell.column)
                        field_annotation = str(getattr(
                            field_fact, "annotation", "",
                        ))
                        field_is_tuple = any(
                            part in {
                                "tuple", "builtins.tuple", "<class'tuple'>",
                            }
                            for part in field_annotation.replace(
                                " ", ""
                            ).split("|")
                        )
                        field_id = new_node(
                            "GetAttr", f"getattr[{field_name}]",
                            attributes={
                                "attribute": str(field_name),
                                "attribute_slot": (
                                    str(record_identity), int(field_ordinal),
                                ),
                                "record_field": (
                                    str(record_identity), str(field_name),
                                ),
                                **({
                                    "value_kind": "scalar",
                                } if field_annotation in {"int", "builtins.int"}
                                else {}),
                            },
                            parents=((int(operand_value_id), "value"),),
                            source=component,
                            source_cell=(operand_cell, field_cell),
                        )
                        page_key_cell = page_key_field_schemas.get((
                            int(operand_value_id), str(field_name),
                        ))
                        if (
                            page_key_cell is None
                            and refinement_binding is not None
                        ):
                            page_key_cell = (
                                page_key_binding_field_schemas.get((
                                    str(refinement_binding), str(field_name),
                                ))
                            )
                        page_key_declaration = source_page_declaration(
                            page_key_cell
                        )
                        if (
                            page_key_declaration is not None
                            and field_is_tuple
                        ):
                            graph.G.nodes[int(field_id)].setdefault(
                                "attributes", {}
                            ).update({
                                "aggregate_kind": "tuple",
                                "source_tuple_row_fields": tuple(
                                    page_key_declaration.row_fields
                                ),
                                "source_page_declaration_cell": page_key_cell,
                            })
                        if field_annotation in {"int", "builtins.int"}:
                            graph.G.nodes[int(field_id)]["tensor"] = {
                                "shape": (), "dtype": "int64",
                            }
                        projected_values.append(int(field_id))
                        if field_ordinal:
                            projected_components.append(
                                projected_literal_component(", ", field_cell)
                            )
                        projected_components.append(
                            projected_literal_component(
                                f"{field_name}=", field_cell,
                            )
                        )
                        member_kind = (
                            "string_token" if field_annotation in {
                                "str", "builtins.str", "<class 'str'>",
                            }
                            else "tuple" if field_is_tuple
                            else "record" if field_annotation in class_table
                            else "scalar"
                        )
                        member_sequence_id = None
                        if field_annotation in {"int", "builtins.int"}:
                            member_formatter = next((
                                entry for entry in function_table
                                if str(entry.qualified_name) == (
                                    "src.compiler.glyph_sequence_format."
                                    "decimal_integer_glyph_tokens"
                                )
                            ), None)
                            if member_formatter is not None:
                                member_sequence_id = new_node(
                                    "Call", "decimal_integer_glyph_tokens",
                                    attributes={
                                        "callee_ref": int(
                                            member_formatter.reference.address
                                        ),
                                        "callee_resolution": (
                                            "source-glyph-formatter"
                                        ),
                                        "producer_kind": (
                                            "formatted_glyph_sequence"
                                        ),
                                        "aggregate_kind": "list",
                                        "sequence_key_columns": (),
                                        "sequence_column_count": 1,
                                        "sequence_writable": True,
                                        "sequence_element_dtypes": ("int64",),
                                    },
                                    parents=((int(field_id), "arg:0"),),
                                    source=component,
                                    source_cell=(field_cell,),
                                )
                        projected_components.append(_SourceGlyphComponent(
                            kind="formatted",
                            component_value_id=int(field_id),
                            operand_value_id=int(field_id),
                            glyph_tokens=(), conversion=ord("r"),
                            format_spec_value_id=None,
                            projection_kind=member_kind,
                            record_identity=(
                                field_annotation
                                if member_kind == "record" else None
                            ),
                            formatted_sequence_value_id=(
                                None if member_sequence_id is None
                                else int(member_sequence_id)
                            ),
                        ))
                    projected_components.append(
                        projected_literal_component(")", operand_cell)
                    )
                    projection_value_ids = tuple(projected_values)
                    projection_components = tuple(projected_components)
                elif projection_kind == "tuple":
                    projection_value_ids = tuple(map(
                        int,
                        operand_attributes.get(
                            "aggregate_leaf_value_ids", ()
                        ),
                    ))
                    runtime_row_fields = tuple(
                        operand_attributes.get("source_tuple_row_fields", ())
                    )
                    runtime_projection = bool(
                        not projection_value_ids and runtime_row_fields
                    )
                    runtime_projection_components = ()
                    authored_empty_tuple = (
                        isinstance(operand_expression, ast.Tuple)
                        and not operand_expression.elts
                    )
                    structured_projection = bool(
                        projection_value_ids
                        or runtime_row_fields
                        or authored_empty_tuple
                    )
                    if runtime_projection:
                        declaration_cell = operand_attributes.get(
                            "source_page_declaration_cell"
                        )
                        # This tuple shape came from a Page row.  The Ref is
                        # the authority that survived the graph cut; a copied
                        # attribute is never enough to authorize projections.
                        if source_page_declaration(declaration_cell) is None:
                            valid = False
                            break
                        (
                            projection_value_ids,
                            runtime_projection_components,
                        ) = declared_page_tuple_projection(
                            int(operand_value_id), operand_cell,
                            declaration_cell, runtime_row_fields,
                        )
                    component_sources.extend(
                        cell
                        for value_id in projection_value_ids
                        for cell in (node_identity_cell(graph, value_id),)
                        if cell is not None
                    )
                    leaf_positions = tuple(
                        (str(role), int(ordinal), int(parent_id))
                        for role, ordinal, parent_id in _operand_positions(
                            operand_data.get("parents") or ()
                        )
                        if str(role) in {
                            "elts", "elt", "element", "item", "value",
                        }
                    )
                    if structured_projection and not runtime_projection and (
                        len(leaf_positions) != len(projection_value_ids)
                        or any(
                            parent_id != value_id
                            for (_role, _ordinal, parent_id), value_id in zip(
                                leaf_positions, projection_value_ids
                            )
                        )
                    ):
                        valid = False
                        break
                    for (role, ordinal, _parent_id), value_id in (
                        () if runtime_projection else zip(
                            leaf_positions, projection_value_ids
                        )
                    ):
                        position_cell = operand_position_cell(
                            int(operand_node_id), int(value_id), role, ordinal,
                        )
                        if position_cell is None:
                            valid = False
                            break
                        component_sources.append(position_cell)
                    if not valid:
                        break
                    projected_components = (
                        list(runtime_projection_components)
                        if runtime_projection else
                        [projected_literal_component("(", operand_cell)]
                        if structured_projection else []
                    )
                    for leaf_ordinal, value_id in enumerate(
                        () if runtime_projection else projection_value_ids
                    ):
                        if leaf_ordinal:
                            projected_components.append(
                                projected_literal_component(", ", operand_cell)
                            )
                        leaf_data = graph.G.nodes[int(value_id)]
                        leaf_expression = leaf_data.get("expr_obj")
                        leaf_attributes = leaf_data.get("attributes") or {}
                        runtime_field_kind = (
                            str(runtime_row_fields[leaf_ordinal][1])
                            if runtime_projection else None
                        )
                        leaf_kind = (
                            "string_token" if runtime_field_kind in {
                                "LABEL", "NAME",
                            }
                            else "scalar" if runtime_field_kind in {
                                "INDEX", "VALUE_ID",
                            }
                            else
                            "string_token" if isinstance(
                                leaf_expression, ast.Constant,
                            ) and isinstance(leaf_expression.value, str)
                            else "tuple" if leaf_attributes.get(
                                "aggregate_kind"
                            ) == "tuple" else "scalar"
                        )
                        leaf_sequence_id = None
                        leaf_parameter_cell = None
                        leaf_binding_name = leaf_attributes.get("binding_name")
                        if leaf_binding_name is not None:
                            leaf_parameter_cell = book.latest_ref(
                                _PARAMETER_ANNOTATION,
                                (*tuple(value_class_scope), str(leaf_binding_name)),
                            )
                        # A field read off an annotated parameter
                        # (``fact.left`` with ``fact: Publication``): the
                        # leaf's class is the declared field's annotation,
                        # read through the parameter's annotation cell and
                        # the class field declaration cell.
                        leaf_field_cell = None
                        leaf_field_annotation = None
                        if (
                            isinstance(leaf_expression, ast.Attribute)
                            and isinstance(leaf_expression.value, ast.Name)
                        ):
                            leaf_receiver_cell = book.latest_ref(
                                _PARAMETER_ANNOTATION,
                                (
                                    *tuple(value_class_scope),
                                    str(leaf_expression.value.id),
                                ),
                            )
                            if leaf_receiver_cell is not None:
                                leaf_receiver_class = str(book.page(
                                    _PARAMETER_ANNOTATION
                                ).cell(
                                    leaf_receiver_cell.row,
                                    leaf_receiver_cell.column,
                                ))
                                leaf_field_cell = book.latest_ref(
                                    _CLASS_FIELD_DECLARATION,
                                    (
                                        str(value_class_scope[0])
                                        if isinstance(value_class_scope, tuple)
                                        and value_class_scope else "",
                                        leaf_receiver_class,
                                        str(leaf_expression.attr),
                                    ),
                                )
                                if leaf_field_cell is not None:
                                    leaf_field_annotation = str(getattr(
                                        book.page(_CLASS_FIELD_DECLARATION).cell(
                                            leaf_field_cell.row,
                                            leaf_field_cell.column,
                                        ),
                                        "annotation", "",
                                    ))
                                    leaf_parameter_cell = (
                                        leaf_field_cell if leaf_parameter_cell is None
                                        else leaf_parameter_cell
                                    )
                        leaf_integer = (
                            runtime_field_kind in {"INDEX", "VALUE_ID"}
                            or
                            isinstance(leaf_expression, ast.Constant)
                            and isinstance(leaf_expression.value, int)
                            and not isinstance(leaf_expression.value, bool)
                            or leaf_parameter_cell is not None
                            and leaf_parameter_cell.page == _PARAMETER_ANNOTATION
                            and book.page(_PARAMETER_ANNOTATION).cell(
                                leaf_parameter_cell.row,
                                leaf_parameter_cell.column,
                            ) == "int"
                            or leaf_field_annotation in {"int", "builtins.int"}
                        )
                        if (
                            leaf_kind == "scalar"
                            and leaf_integer
                        ):
                            leaf_formatter = next((
                                entry for entry in function_table
                                if str(entry.qualified_name) == (
                                    "src.compiler.glyph_sequence_format."
                                    "decimal_integer_glyph_tokens"
                                )
                            ), None)
                            if leaf_formatter is not None:
                                leaf_sequence_id = new_node(
                                    "Call", "decimal_integer_glyph_tokens",
                                    attributes={
                                        "callee_ref": int(
                                            leaf_formatter.reference.address
                                        ),
                                        "callee_resolution": (
                                            "source-glyph-formatter"
                                        ),
                                        "producer_kind": (
                                            "formatted_glyph_sequence"
                                        ),
                                        "aggregate_kind": "list",
                                        "sequence_key_columns": (),
                                        "sequence_column_count": 1,
                                        "sequence_writable": True,
                                        "sequence_element_dtypes": ("int64",),
                                    },
                                    parents=((int(value_id), "arg:0"),),
                                    source_cell=tuple(dict.fromkeys(filter(
                                        None, (
                                            node_identity_cell(
                                                graph, int(value_id),
                                            ),
                                            leaf_parameter_cell,
                                        ),
                                    ))),
                                )
                        projected_components.append(_SourceGlyphComponent(
                            kind="formatted",
                            component_value_id=int(value_id),
                            operand_value_id=int(value_id),
                            glyph_tokens=(), conversion=ord("r"),
                            format_spec_value_id=None,
                            projection_kind=leaf_kind,
                            record_identity=None,
                            formatted_sequence_value_id=(
                                None if leaf_sequence_id is None
                                else int(leaf_sequence_id)
                            ),
                        ))
                    if (
                        structured_projection and not runtime_projection
                        and len(projection_value_ids) == 1
                    ):
                        projected_components.append(
                            projected_literal_component(",", operand_cell)
                        )
                    if structured_projection and not runtime_projection:
                        projected_components.append(
                            projected_literal_component(")", operand_cell)
                        )
                    projection_components = tuple(projected_components)
                projection_transform = operand_attributes.get(
                    "string_token_transform"
                )
                projection_source_value_id = (
                    next((
                        int(parent)
                        for parent, role in operand_data.get("parents", ())
                        if str(role) == "operand"
                    ), None)
                    if projection_transform == "strip" else None
                )
                projection_operation_cell = (
                    node_identity_cell(graph, int(operand_value_id))
                    if projection_source_value_id is not None
                    and operand_value_id is not None else None
                )
                formatted_component = _SourceGlyphComponent(
                    kind="formatted",
                    component_value_id=component_value_id,
                    operand_value_id=(
                        int(enum_name_value_id)
                        if enum_name_value_id is not None
                        else int(projection_source_value_id)
                        if projection_source_value_id is not None
                        else operand_value_id
                    ),
                    glyph_tokens=(),
                    conversion=(
                        -1 if lone_string_projection
                        else int(component.conversion)
                    ),
                    format_spec_value_id=format_spec_value_id,
                    projection_kind=projection_kind,
                    record_identity=(
                        enum_name_identity
                        if enum_name_identity is not None
                        else record_identity
                    ),
                    projection_names=projection_names,
                    projection_value_ids=projection_value_ids,
                    projection_components=projection_components,
                    enum_table_cell=enum_name_cell,
                    projection_source_value_id=projection_source_value_id,
                    projection_transform=projection_transform,
                    projection_operation_cell=projection_operation_cell,
                )
                optional_dispatch = (
                    optional_or_absence_owner(
                        component, str(refinement_binding),
                    )
                    if (
                        projection_kind == "record"
                        and refinement_identity is None
                        and refinement_binding is not None
                        and isinstance(component, ast.FormattedValue)
                        and int(component.conversion) == ord("r")
                        and component.format_spec is None
                        and operand_attributes.get(
                            "optional_result_class_ref"
                        ) == record_identity
                        and source_page_declaration(
                            operand_attributes.get(
                                "source_page_declaration_cell"
                            )
                        ) is not None
                    ) else None
                )
                if optional_dispatch is None:
                    components.append(formatted_component)
                    continue

                owner_if, absence_test = optional_dispatch
                declaration_cell = operand_attributes[
                    "source_page_declaration_cell"
                ]
                absence_cell = _authored_node_cell(graph, absence_test)
                present_id = new_node(
                    "FormattedGlyphSequence",
                    "optional present glyph sequence",
                    attributes={
                        "producer_kind": "glyph_sequence",
                        "aggregate_kind": "list",
                        "sequence_key_columns": (),
                        "sequence_column_count": 1,
                        "sequence_writable": True,
                        "sequence_element_dtypes": ("int64",),
                    },
                    source=component,
                    source_cell=tuple(dict.fromkeys(filter(None, (
                        component_cell, operand_cell, declaration_cell,
                        absence_cell,
                    )))),
                )
                present_fact = _SourceGlyphSequence(tuple(
                    formatted_component.projection_components
                ))
                present_row = (ingestion_read_scope, int(present_id))
                book.post(
                    _SOURCE_GLYPH_SEQUENCE, present_row, present_fact,
                    stage=_REDUCTION,
                    provenance=_Derived(tuple(dict.fromkeys(filter(None, (
                        node_identity_cell(graph, present_id),
                        component_cell, operand_cell, declaration_cell,
                        absence_cell,
                    ))))),
                    mode=_Mode.CONCORD,
                )
                graph.G.nodes[int(present_id)]["attributes"].update({
                    "source_glyph_sequence_row": present_row,
                })

                absent_id = new_node(
                    "FormattedGlyphSequence",
                    "optional absent glyph sequence",
                    attributes={
                        "producer_kind": "literal_glyph_sequence",
                        "aggregate_kind": "list",
                        "sequence_key_columns": (),
                        "sequence_column_count": 1,
                        "sequence_writable": False,
                        "sequence_element_dtypes": ("int64",),
                    },
                    source=component,
                    source_cell=(declaration_cell, absence_cell),
                )
                absent_fact = _SourceGlyphSequence((_SourceGlyphComponent(
                    kind="literal", component_value_id=int(absent_id),
                    operand_value_id=None,
                    glyph_tokens=tuple(
                        int(string_token(character)) for character in "None"
                    ),
                    conversion=-1, format_spec_value_id=None,
                    projection_kind="literal", record_identity=None,
                ),))
                absent_row = (ingestion_read_scope, int(absent_id))
                book.post(
                    _SOURCE_GLYPH_SEQUENCE, absent_row, absent_fact,
                    stage=_REDUCTION,
                    provenance=_Derived(tuple(dict.fromkeys(filter(None, (
                        node_identity_cell(graph, absent_id), declaration_cell,
                        absence_cell,
                    ))))),
                    mode=_Mode.CONCORD,
                )
                graph.G.nodes[int(absent_id)]["attributes"].update({
                    "source_literal_glyph_sequence_row": absent_row,
                })

                def projection_tree(root):
                    yield root
                    for child in root.projection_components:
                        yield from projection_tree(child)

                present_components = tuple(
                    item
                    for root in formatted_component.projection_components
                    for item in projection_tree(root)
                )
                present_callsites = tuple(dict.fromkeys(
                    int(item.formatted_sequence_value_id)
                    for item in present_components
                    if item.formatted_sequence_value_id is not None
                    and int(item.formatted_sequence_value_id) in graph.G
                    and str((graph.G.nodes[
                        int(item.formatted_sequence_value_id)
                    ].get("attributes") or {}).get(
                        "callee_resolution", ""
                    )) == "source-glyph-formatter"
                ))
                present_projection_sequences = tuple(dict.fromkeys((
                    int(present_id),
                    *(
                        int(item.component_value_id)
                        for item in present_components
                        if item.projection_components
                        or (
                            item.kind == "formatted"
                            and item.projection_kind in {
                                "string_token", "enum_name",
                            }
                        )
                    ),
                )))
                graph.G.nodes[int(component_value_id)].setdefault(
                    "attributes", {}
                )["source_optional_glyph_dispatch"] = {
                    "owner_conditional_id": int(id(owner_if)),
                    "conditional_value_id": int(id(absence_test)),
                    "present_value_id": int(present_id),
                    "absent_value_id": int(absent_id),
                    "present_callsite_ids": present_callsites,
                    "present_projection_sequence_ids": (
                        present_projection_sequences
                    ),
                    "predicate_expect_true": False,
                    "source_page_declaration_cell": declaration_cell,
                }
                components.append(_dataclass_replace(
                    formatted_component,
                    projection_kind="optional_glyph_sequence",
                    projection_names=(), projection_value_ids=(),
                    projection_components=(),
                    formatted_sequence_value_id=int(component_value_id),
                ))
            if lone_string_projection and valid:
                # ``str(aggregate)`` is itself the destination resident
                # sequence.  Its projection children are therefore the
                # top-level recipe; retaining the synthetic wrapper would
                # ask the sequence ABI to extend the destination from itself.
                if (
                    len(components) != 1
                    or not components[0].projection_components
                ):
                    valid = False
                else:
                    components = list(components[0].projection_components)
            joined_cell = node_identity_cell(graph, node_id)
            if valid and joined_cell is not None:
                fact = _SourceGlyphSequence(tuple(components))
                book = current_identity_book()
                row = (ingestion_read_scope, int(node_id))
                incumbent = book.page(_SOURCE_GLYPH_SEQUENCE).latest(row)
                if incumbent is not None and incumbent != fact:
                    raise ValueError(
                        "source glyph sequence concordance disagreement for "
                        f"{row!r}: recorded={incumbent!r}, proposed={fact!r}"
                    )
                if incumbent is None:
                    glyph_cell = book.post(
                        _SOURCE_GLYPH_SEQUENCE,
                        row,
                        fact,
                        stage=_REDUCTION,
                        provenance=_Derived(tuple(dict.fromkeys((
                            joined_cell, *component_sources,
                        )))),
                        mode=_Mode.CONCORD,
                    )
                else:
                    glyph_cell = book.latest_ref(
                        _SOURCE_GLYPH_SEQUENCE, row,
                    )
                if glyph_cell is not None:
                    # A JoinedStr and ``str(x)`` evaluate to a ``str`` by
                    # Python's own semantics; their authored glyph recipe is
                    # the producer.  Record the class the way every other
                    # string producer does (the string slice above), so a
                    # consumer f-string takes the existing string_token path.
                    _concord_source_value_class(
                        value_class_scope,
                        int(node_id),
                        "str",
                        source=(
                            "builtins.str call result"
                            if lone_string_projection
                            else "authored joined string result"
                        ),
                        provenance=_Derived(tuple(
                            cell for cell in (glyph_cell, joined_cell)
                            if cell is not None
                        )),
                    )
                # A formatted scalar is an ordinary call to the authored
                # decimal formatter (``_link_integer_glyph_formatter_calls``:
                # the same link is repeated once the call-edge class facts
                # have settled).  The canonical relabel below publishes
                # CALL_BINDING from the call cell and FUNCTION_ADDRESS before
                # compilation-unit division.
                components = _link_integer_glyph_formatter_calls(
                    graph, function_table,
                    row=row, glyph_cell=glyph_cell, components=components,
                    value_class_scope=value_class_scope,
                    format_spec_scopes=(ingestion_read_scope, value_class_scope),
                    new_node=new_node,
                )
                # Only a successfully posted recipe admits the JoinedStr as
                # resident sequence storage.  These attributes are a graph
                # view of the concordance cell, not a second type decision.
                joined_attributes = graph.G.nodes[node_id].setdefault(
                    "attributes", {}
                )
                joined_attributes.update({
                    "producer_kind": "glyph_sequence",
                    "aggregate_kind": "list",
                    "sequence_key_columns": (),
                    "sequence_column_count": 1,
                    "sequence_writable": True,
                    "sequence_element_dtypes": ("int64",),
                    "source_glyph_sequence_row": row,
                })
                for ordinal, component in enumerate(components):
                    if component.kind != "formatted":
                        continue
                    formatted_attributes = graph.G.nodes[
                        int(component.component_value_id)
                    ].setdefault("attributes", {})
                    formatted_attributes.update({
                        "producer_kind": "formatted_glyph_sequence",
                        "aggregate_kind": "list",
                        "sequence_key_columns": (),
                        "sequence_column_count": 1,
                        "sequence_writable": True,
                        "sequence_element_dtypes": ("int64",),
                        "source_glyph_component": (row, int(ordinal)),
                    })
                for component in components:
                    if (
                        component.projection_transform is None
                        or component.projection_source_value_id is None
                        or component.projection_operation_cell is None
                    ):
                        continue
                    operation_id = _cell_node_id(
                        component.projection_operation_cell
                    )
                    source_id = int(component.projection_source_value_id)
                    if operation_id is None or operation_id not in graph.G:
                        continue
                    consumers = {
                        int(child)
                        for child, _role in (
                            graph.G.nodes[operation_id].get("children") or ()
                        )
                    }
                    if consumers != {int(component.component_value_id)}:
                        # The recipe owns this transformed value only when
                        # the FormattedValue is its sole consumer.  Any other
                        # use still needs a general string-operation lowering
                        # and must remain visible to the compiler.
                        continue
                    # The SOURCE_GLYPH_SEQUENCE fact now owns the strip
                    # operation and names its exact source token.  Retire the
                    # otherwise producerless Call from the execution graph;
                    # the ordinary graph edge into FormattedValue becomes the
                    # source token edge, while the immutable recipe retains
                    # the authored operation identity and transform.
                    _redirect_value(graph, operation_id, source_id)
        if lone_string_projection and node_id in graph.G:
            # ``str(x)`` evaluates to a ``str`` whether or not its argument
            # has a glyph recipe: the class is the builtin's own result
            # class, recorded on the call like ``len``'s ``int``.
            str_call_cell = node_identity_cell(graph, int(node_id))
            _concord_source_value_class(
                value_class_scope,
                int(node_id),
                "str",
                source="builtins.str call result",
                provenance=(
                    _Derived((str_call_cell,))
                    if str_call_cell is not None else None
                ),
            )
        if (
            isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Name)
            and expression.func.id == "sorted"
            and len(expression.args) == 1
            and node_id in graph.G
            and (graph.G.nodes[node_id].get("attributes") or {}).get(
                "static_python_reference"
            ) == "sorted"
        ):
            materializer = graph.G.nodes[node_id]
            materializer_attributes = materializer.setdefault(
                "attributes", {}
            )
            materializer_attributes.update({
                "producer_kind": "sorted_materialization",
                "aggregate_kind": "list",
                "sequence_key_columns": (),
                "sequence_column_count": 1,
                "sequence_writable": True,
                "materialization_axis": 0,
                "materialized_source_value_ids": tuple(
                    int(parent)
                    for parent, role in materializer.get("parents") or ()
                    if str(role) == "arg:0"
                ),
                "collection_iterable_value_id": next((
                    int(parent)
                    for parent, role in materializer.get("parents") or ()
                    if str(role) == "arg:0"
                ), None),
                "source_sorted_call": True,
                "extraction_identity": "builtins.list",
            })
        if (
            isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Name)
            and expression.func.id in {"tuple", "list", "frozenset"}
            and len(expression.args) == 1
            and node_id in graph.G
        ):
            materializer = graph.G.nodes[node_id]
            materializer_attributes = materializer.setdefault(
                "attributes",
                {},
            )
            materializer_attributes["producer_kind"] = (
                "loop_materialization"
                if isinstance(expression.args[0], ast.GeneratorExp)
                else "aggregate_materialization"
            )
            materializer_attributes["materialization_axis"] = 0
            materializer_attributes["materialized_source_value_ids"] = tuple(
                int(parent)
                for parent, role in materializer.get("parents") or ()
                if str(role).startswith("arg:")
            )
        if (
            isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Name)
            and expression.func.id in {"tuple", "list"}
            and len(expression.args) == 1
            and isinstance(expression.args[0], ast.GeneratorExp)
            and node_id in graph.G
        ):
            # This re-resolves generator_expression.elt, which the
            # (ListComp, SetComp, DictComp, GeneratorExp) branch above
            # already resolved once, inside its own scoped push/pop of the
            # generator's `for` target names. resolve_expression() is not
            # memoized for Name lookups -- it re-reads `environment` on
            # every call -- so this second, unscoped pass through the same
            # `elt` subtree re-looks-up the target name(s) (e.g. `address`
            # in `tuple(f(address) for address in xs)`) after that first
            # pass already popped them, silently creating a fresh
            # "external input" binding for what should be, and already
            # was, a properly loop-scoped local. That stray rebinding then
            # leaked into whatever unrelated code came later in the
            # function and happened to reuse the same name. Same
            # push/pop discipline as above, applied to this second walk.
            generator_expression = expression.args[0]
            comprehension_target_names = {
                name
                for generator in generator_expression.generators
                for name in loop_target_names(generator.target)
            }
            shadowed_bindings = {
                name: environment[name]
                for name in comprehension_target_names
                if name in environment
            }
            for generator in generator_expression.generators:
                bind_loop_target(generator.target)
            value_id = resolve_expression(generator_expression.elt)
            for generator in generator_expression.generators[-1:]:
                generator_id = id(generator)
                if (
                    generator_id not in graph.G
                    or not isinstance(value_id, int)
                    or value_id not in graph.G
                ):
                    continue
                attributes = graph.G.nodes[generator_id].setdefault(
                    "attributes",
                    {},
                )
                outputs = list(
                    attributes.get("loop_iteration_outputs", ())
                )
                outputs.append({
                    "value_id": value_id,
                    "result_value_id": node_id,
                    "materializer_node_id": node_id,
                })
                attributes["loop_iteration_outputs"] = tuple(outputs)
            for name in comprehension_target_names:
                if name in shadowed_bindings:
                    environment[name] = shadowed_bindings[name]
                else:
                    environment.pop(name, None)
        if (
            isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Name)
            and expression.func.id == "sorted"
            and len(expression.args) == 1
            and node_id in graph.G
        ):
            # ``sorted(<generator>)`` / ``sorted(chain.from_iterable(<gen>))``:
            # the generator's loop collects the ARGUMENT of ``sorted`` -- the
            # generator (or ``from_iterable``) value, ``arg:0`` of the call --
            # exactly as ``list(<generator>)`` collects into its own value.
            # The sorted Call is a different value: a copy of that collection
            # ordered by the source sort contract posted for it
            # (destination = the call, source = the argument), the same
            # replace + sort that ``sorted(d)`` on a real sequence makes.
            # Naming the call as the loop's materializer gave the loop's
            # arena the call's identity while the contract still named the
            # argument as source and the call as destination: three ids for
            # one Python value, and a sort ordered before the loop filled
            # anything.  ``chain.from_iterable`` is a transparent iterator
            # wrapper for this purpose: its nested generator still owns the
            # stream.  Record that ownership while the exact AST topology is
            # present.
            source_expression = expression.args[0]
            generator_expression = (
                source_expression
                if isinstance(source_expression, ast.GeneratorExp)
                else source_expression.args[0]
                if (
                    isinstance(source_expression, ast.Call)
                    and isinstance(source_expression.func, ast.Attribute)
                    and source_expression.func.attr == "from_iterable"
                    and len(source_expression.args) == 1
                    and isinstance(source_expression.args[0], ast.GeneratorExp)
                )
                else None
            )
            argument_id = next((
                int(parent)
                for parent, role in graph.G.nodes[node_id].get("parents") or ()
                if str(role) == "arg:0" and int(parent) in graph.G
            ), None)
            if generator_expression is not None and argument_id is not None:
                graph.G.nodes[argument_id].setdefault("attributes", {}).update({
                    "producer_kind": "loop_materialization",
                    "aggregate_kind": "list",
                    "sequence_key_columns": (),
                    "sequence_column_count": 1,
                    "sequence_writable": True,
                    "materialization_axis": 0,
                })
                comprehension_target_names = {
                    name
                    for generator in generator_expression.generators
                    for name in loop_target_names(generator.target)
                }
                shadowed_bindings = {
                    name: environment[name]
                    for name in comprehension_target_names
                    if name in environment
                }
                for generator in generator_expression.generators:
                    bind_loop_target(generator.target)
                value_id = resolve_expression(generator_expression.elt)
                for generator in generator_expression.generators[-1:]:
                    generator_id = id(generator)
                    if (
                        generator_id not in graph.G
                        or not isinstance(value_id, int)
                        or value_id not in graph.G
                    ):
                        continue
                    attributes = graph.G.nodes[generator_id].setdefault(
                        "attributes", {}
                    )
                    outputs = list(attributes.get(
                        "loop_iteration_outputs", ()
                    ))
                    outputs.append({
                        "value_id": value_id,
                        "result_value_id": argument_id,
                        "materializer_node_id": argument_id,
                    })
                    attributes["loop_iteration_outputs"] = tuple(outputs)
                for name in comprehension_target_names:
                    if name in shadowed_bindings:
                        environment[name] = shadowed_bindings[name]
                    else:
                        environment.pop(name, None)
        if (
            isinstance(expression, ast.Call)
            and node_id in graph.G
            and (
                isinstance(expression.func, ast.Attribute)
                and expression.func.attr == "sort"
                or isinstance(expression.func, ast.Name)
                and expression.func.id == "sorted"
            )
        ):
            # Posted after the loop-materialization records of this
            # expression are stamped: a sort whose source is materialized by
            # a loop has its source identity minted by the loop composer,
            # which posts the contract (see post_source_sort_contract).
            post_source_sort_contract(node_id, expression)
        return node_id if node_id in graph.G else None

    def bind_target(
        target: ast.AST,
        value: int | _StaticPythonReference | None,
        *, value_occurrence: ast.AST | None = None,
    ) -> None:
        if value is None:
            return
        if isinstance(target, ast.Name):
            deleted_names.discard(target.id)
            if isinstance(value, _StaticPythonReference):
                environment.pop(target.id, None)
                static_environment[target.id] = value
                _remove_node(graph, id(target))
                return
            static_environment.pop(target.id, None)
            # This propagation is only for an explicit local declaration
            # whose AnnAssign was normalized away before lexical reduction.
            # Parameter aggregate contracts already own every rebinding of a
            # parameter; stamping a post-mutation SSA version here declares a
            # second resident sequence for the same parameter identity.
            aggregate_kind = (local_aggregate_kinds or {}).get(target.id)
            if aggregate_kind is not None and int(value) in graph.G:
                aggregate_attributes = graph.G.nodes[int(value)].setdefault(
                    "attributes", {}
                )
                aggregate_attributes.update({
                    "producer_kind": "annotated_aggregate_binding",
                    "aggregate_kind": aggregate_kind,
                    "sequence_key_columns": (
                        (0,) if aggregate_kind in {"set", "dict"} else ()
                    ),
                    "sequence_column_count": (
                        2 if aggregate_kind == "dict" else 1
                    ),
                    "sequence_writable": aggregate_kind not in {"tuple", "bytes"},
                    **dict(
                        (local_mapping_contracts or {}).get(target.id) or {}
                    ),
                })
                element_declaration = local_sequence_element_declarations.get(
                    target.id
                )
                if element_declaration is not None:
                    element_class, element_annotation_cell = (
                        element_declaration
                    )
                    aggregate_attributes.update({
                        "sequence_element_class_ref": str(element_class),
                        "sequence_element_annotation_cell": (
                            element_annotation_cell
                        ),
                    })
            local_class_declaration = local_class_declarations.get(target.id)
            if local_class_declaration is not None and int(value) in graph.G:
                class_identity, annotation_cell = local_class_declaration
                graph.G.nodes[int(value)].setdefault(
                    "attributes", {}
                )["result_class_ref"] = class_identity
                class_sources = tuple(filter(None, (
                    node_identity_cell(graph, int(value)),
                    annotation_cell,
                )))
                _concord_source_value_class(
                    value_class_scope,
                    int(value),
                    class_identity,
                    source=f"authored local annotation {target.id}",
                    provenance=(
                        _Derived(class_sources) if class_sources else None
                    ),
                )
            source_binding = None
            source_version = None
            if isinstance(value_occurrence, ast.Name):
                source_binding = value_occurrence.id
                source_version = next((
                    version for version in range(len(identity_bindings.get(source_binding, ())) - 1, -1, -1)
                    if identity_bindings[source_binding][version] == value
                ), None)
            environment[target.id] = value
            identity_bindings.setdefault(target.id, []).append(value)
            record_ingestion_definition(target.id, value, target)
            if source_version is not None:
                from ...compiler.concordance_declarations import NAME_BINDING_CAPTURE
                book = current_identity_book()
                row = (ingestion_read_scope, target.id, len(identity_bindings[target.id]) - 1)
                source_row = (ingestion_read_scope, source_binding, source_version)
                read_row = (ingestion_read_scope, "occurrence", id(value_occurrence), 0)
                owner = binding_loop_owners.get(id(target))
                cells = tuple(cell for cell in (
                    book.latest_ref(_NAME_BINDING, row), book.latest_ref(_NAME_BINDING, source_row),
                    book.latest_ref(_LEXICAL_READ_BINDING, read_row),
                    node_identity_cell(graph, owner) if owner is not None else None,
                ) if cell is not None)
                book.post(NAME_BINDING_CAPTURE, row, (source_binding, source_version, owner),
                          stage=_REDUCTION, provenance=_Derived(cells), mode=_Mode.CONCORD)
            _remove_node(graph, id(target))
            return
        if isinstance(target, ast.Attribute):
            static_value_path = None
            if isinstance(value, _StaticPythonReference):
                # Retain the Python/runtime seam explicitly. Autograd tape and
                # similar bookkeeping references are not numerical values, but
                # assigning one must not truncate the surrounding mathematical
                # program. StaticReference is the planner's established host
                # boundary node and keeps the effect visible in full geometry.
                static_value_path = value.path
                value = static_reference_node(value)
            receiver = resolve_expression(target.value)
            static_receiver = (
                receiver if isinstance(receiver, _StaticPythonReference) else None
            )
            if static_receiver is not None:
                receiver = static_reference_node(static_receiver)
            if not isinstance(receiver, int) or not isinstance(value, int):
                raise TypeError(
                    "attribute assignment requires resolved object and value "
                    f"nodes in {statement.name}: "
                    f"target={ast.dump(target, include_attributes=False)}, "
                    f"receiver={receiver!r}, value={value!r}"
                )
            node_id = id(target)
            if node_id not in graph.G:
                # Resolving a compile-time receiver's literal attribute read
                # redirects and removes the source Attribute wrapper.  The
                # subsequent write is still a distinct runtime effect.
                node_id = new_node(
                    "SetAttr",
                    f"setattr[{target.attr}]",
                    attributes={"attribute": target.attr},
                    # The write's own statement anchors it lexically: an
                    # unanchored SetAttr inside a loop body was not owned by
                    # the loop (`is_lexical_body_node`), so port
                    # materialization rewired the loop's own effect chain
                    # onto its own result port and closed a cycle.
                    source=target,
                )
            # In ``object.field += value`` the Attribute node is the read
            # feeding the AugAssign result.  Reusing that same node as the
            # write would create ``Attribute -> AugAssign -> SetAttr`` while
            # SetAttr is still the Attribute node: an artificial dataflow
            # cycle.  Keep the read and write as distinct program events.
            if node_id == value or nx.has_path(graph.G, node_id, value):
                node_id = new_node(
                    "SetAttr",
                    f"setattr[{target.attr}]",
                    attributes={"attribute": target.attr},
                    # The write's own statement anchors it lexically: an
                    # unanchored SetAttr inside a loop body was not owned by
                    # the loop (`is_lexical_body_node`), so port
                    # materialization rewired the loop's own effect chain
                    # onto its own result port and closed a cycle.
                    source=target,
                )
            node_data = graph.G.nodes[node_id]
            node_data["type"] = "SetAttr"
            node_data["op"] = "setattr"
            node_data.setdefault("attributes", {})["attribute"] = target.attr
            if static_value_path is not None:
                node_data["attributes"]["static_value_boundary"] = (
                    static_value_path
                )
            _replace_inputs(
                graph,
                node_id,
                (
                    (receiver, "object"),
                    (value, "value"),
                ),
                fork_from=(
                    {("value", 0): ("occurrence", id(value_occurrence), 0)}
                    if isinstance(value_occurrence, ast.Name) else None
                ),
            )
            if static_receiver is not None:
                # A compile-time receiver's field takes the RHS node: page
                # ``static_attribute_state`` keyed by the reference's path
                # (plan 70, section 1.2), DERIVED(receiver node cell, RHS
                # node cell).
                field_state_book.post(
                    _STATIC_ATTRIBUTE_STATE,
                    (ingestion_read_scope, static_receiver.path, str(target.attr)),
                    node_identity_cell(graph, int(value)),
                    stage=_REDUCER_FIELD_WRITE,
                    provenance=_Derived(tuple(dict.fromkeys((
                        node_identity_cell(graph, int(receiver)),
                        node_identity_cell(graph, int(value)),
                    )))),
                    mode=_Mode.REVISE,
                )
            # The write is the field's next version: WRITTEN, value = the
            # RHS node, effect = this SetAttr (plan 70, S4).  The written
            # cell is stamped on the SetAttr so a consumer names the cell,
            # never the RHS id or the SetAttr id.
            declared_field_cell = declared_field_schema_cell(
                str(method_owner)
                if method_owner is not None
                and isinstance(target.value, ast.Name)
                and target.value.id in {"self", "cls"}
                else receiver_class_identity(receiver),
                target.attr,
            )
            if declared_field_cell is not None:
                node_data.setdefault("attributes", {})[
                    "field_declaration_cell"
                ] = declared_field_cell
            written_cell = post_field_state(
                receiver, target.attr, _FieldStateKind.WRITTEN,
                int(value), int(node_id),
                sources=field_state_sources(
                    receiver, target.attr,
                    node_identity_cell(graph, int(value)),
                    node_identity_cell(graph, int(node_id)),
                    declared_field_cell,
                ),
                stage=_REDUCER_FIELD_WRITE,
            )
            node_data.setdefault("attributes", {})["field_state_cell"] = (
                written_cell
            )
            # A plain-named receiver (``counter.value = ...``) gets its own
            # identity binding the same way a bare ``ast.Name`` target does
            # above -- the field write is already a real, correctly wired
            # SetAttr node; it was just never named, so it never reached
            # ``identity_table`` for anything downstream to select by name.
            if isinstance(target.value, ast.Name):
                field_identity = f"{target.value.id}.{target.attr}"
                identity_bindings.setdefault(
                    field_identity, []
                ).append(node_id)
                record_ingestion_definition(field_identity, node_id, target)
                # ``callee_ref``/``method_ref``/``class_ref`` each let a
                # dependency walk recurse into the thing a node depends on --
                # a real node reference grounded in the class's own layout,
                # not a label invented at this call site.  ``attribute_slot``
                # is the field's actual, deterministic position in its
                # class's declared instance storage, resolved through
                # ``ClassNavigationTable.resolve_dot`` (see
                # ``navigation_table``/``_resolve_instance_attribute_slot``
                # above), known only when the receiver's static class
                # identity is known -- an annotated parameter naming a
                # locally-defined class.  Nothing is invented when it is not
                # known; the write remains correctly wired via
                # ``object``/``value`` either way.
                class_identity = parameter_class_names.get(target.value.id)
                if class_identity is not None:
                    slot = _resolve_instance_attribute_slot(
                        class_identity, target.attr
                    )
                    if slot is not None:
                        node_data.setdefault("attributes", {})[
                            "attribute_slot"
                        ] = (class_identity, slot)
            return
        if isinstance(target, ast.Subscript):
            if isinstance(value, _StaticPythonReference):
                try:
                    target_source = ast.unparse(target)
                except Exception:  # noqa: BLE001 -- diagnostic only
                    target_source = repr(target)
                raise TypeError(
                    "a static Python reference cannot be assigned through "
                    "a runtime tensor index; "
                    f"target={target_source!r}; reference={value.path!r}"
                )
            base = resolve_expression(target.value)
            index_expressions = (
                tuple(target.slice.elts)
                if isinstance(target.slice, ast.Tuple)
                else (target.slice,)
            )
            indices = tuple(
                resolve_expression(index) for index in index_expressions
            )
            if not isinstance(base, int) or not isinstance(value, int) or not all(
                isinstance(index, int) for index in indices
            ):
                try:
                    assignment_source = ast.unparse(
                        ast.Assign(targets=[target], value=ast.Constant(None))
                    ).removesuffix(" = None")
                except Exception:  # noqa: BLE001 -- diagnostic only
                    assignment_source = ast.dump(
                        target, include_attributes=False
                    )
                def component_identity(component: Any) -> str:
                    if isinstance(component, _StaticPythonReference):
                        return f"static:{component.path}"
                    if not isinstance(component, int):
                        return repr(component)
                    if component not in graph.G:
                        return f"node:{component}:absent"
                    data = graph.G.nodes[component]
                    attributes = data.get("attributes") or {}
                    binding = attributes.get("binding_name")
                    suffix = f":binding={binding}" if binding else ""
                    return (
                        f"node:{component}:{data.get('type')}:"
                        f"{data.get('label')}{suffix}"
                    )
                raise TypeError(
                    "indexed assignment requires resolved tensor, index, "
                    f"and value nodes in {statement.name}: "
                    f"target={assignment_source!r}; "
                    f"base={component_identity(base)}; "
                    "indices=("
                    + ", ".join(component_identity(index) for index in indices)
                    + "); "
                    f"value={component_identity(value)}"
                )
            node_id = id(target)
            if (
                node_id not in graph.G
                or node_id == base
                or node_id == value
                or nx.has_path(graph.G, node_id, value)
            ):
                # The store has no authored node of its own (the target
                # Subscript's node is the read, ``m[:2] -= t``).  Its
                # identity is a minted ``indexed_store_site`` cell rooted at
                # the target's span with the effect nodes as provenance,
                # and the store node's row derives from that cell: branch
                # membership and placement read the site through the edge.
                site_cell = post_indexed_store_site(
                    graph, ingestion_read_scope, target,
                    (id(target), value),
                )
                node_id = new_node(
                    "IndexedStore", "indexed_store", source_cell=site_cell,
                )
                # Program: ``d[1] += 5`` (scratch c201).  Wrong record: the
                # minted store carried its site only as a cell, while
                # placement reads a node's ``source_span``; the store sorted
                # after every later read (a control order cycle).  Rule: the
                # store states the span its site cell was minted from.
                graph.G.nodes[node_id].setdefault("source_span", {
                    "line": int(getattr(target, "lineno", 0) or 0),
                    "column": int(getattr(target, "col_offset", 0) or 0),
                    "end_line": int(getattr(target, "end_lineno", 0) or 0),
                    "end_column": int(getattr(target, "end_col_offset", 0) or 0),
                })
            node_data = graph.G.nodes[node_id]
            node_data["type"] = "IndexedStore"
            node_data["op"] = "IndexedStore"
            node_data.setdefault("attributes", {})[
                "source_type"
            ] = "SubscriptStore"
            # ``heap[size] = node`` in the compiler's integer graph kernel:
            # resolving the RHS Name removes its occurrence and the Assign
            # wrapper. The new store's value operand was an unattributed
            # Append, so a loop-carried ``node`` sharing a zero seed refused
            # control lowering. Fork this new operand from the existing RHS
            # occurrence receipt; never infer a binding from the seed value.
            _replace_inputs(
                graph,
                node_id,
                (
                    (base, "base"),
                    *((index, "index") for index in indices),
                    (value, "value"),
                ),
                fork_from=(
                    {("value", 0): ("occurrence", id(value_occurrence), 0)}
                    if isinstance(value_occurrence, ast.Name) else None
                ),
            )
            # Preserve indexed writes on the exact resolved sequence value.
            # Calls such as ``items.append(v)`` already post
            # SOURCE_SEQUENCE_MUTATION above; without this writer,
            # ``items[i] = v`` could be an unrecorded store in a later
            # owned-column proof. The receipt is deliberately generic: a
            # setitem is evidence of a writer, never evidence that its value
            # fits any narrower logical domain.
            base_attributes = dict(
                graph.G.nodes[base].get("attributes") or {}
            )
            aggregate_kind = str(
                base_attributes.get("aggregate_kind") or ""
            ).casefold()
            sequence_policy = (
                "unique" if aggregate_kind in {"set", "dict"}
                else "duplicates" if aggregate_kind in {
                    "list", "tuple", "bytes", "bytearray", "array",
                }
                else None
            )
            if sequence_policy is not None:
                from ...compiler.concordance_declarations import (
                    SOURCE_SEQUENCE_MUTATION,
                )
                mutation_values = tuple(map(int, (*indices, value)))
                mutation_fact = (
                    int(base), "setitem", str(sequence_policy),
                    mutation_values,
                    "mapping" if aggregate_kind == "dict" else "sequence",
                )
                mutation_row = (value_class_scope, int(node_id))
                mutation_page = current_identity_book().page(
                    SOURCE_SEQUENCE_MUTATION
                )
                incumbent = mutation_page.latest(mutation_row)
                if incumbent is not None and tuple(incumbent) != mutation_fact:
                    raise ValueError(
                        "source sequence mutation concordance disagreement "
                        f"for {mutation_row!r}: recorded={incumbent!r}, "
                        f"proposed={mutation_fact!r}"
                    )
                if incumbent is None:
                    mutation_sources = [
                        node_identity_cell(graph, int(node_id)),
                        node_identity_cell(graph, int(base)),
                    ]
                    mutation_sources.extend(
                        node_identity_cell(graph, int(value_id))
                        for value_id in mutation_values
                    )
                    current_identity_book().post(
                        SOURCE_SEQUENCE_MUTATION,
                        mutation_row,
                        mutation_fact,
                        stage=_REDUCTION,
                        provenance=_Derived(tuple(dict.fromkeys(
                            cell for cell in mutation_sources
                            if cell is not None
                        ))),
                        mode=_Mode.CONCORD,
                    )
            # A keyed store authors one runtime mapping-entry layout.  Keep
            # the exact ordered index operands followed by the stored value
            # on the source aggregate page while those operand-position
            # cells still exist.  ``mapping_key_dtype`` is only the physical
            # column type: it cannot distinguish a string token from an
            # ordinary integer, and therefore cannot carry the source class
            # through ``mapping.items()`` destructuring.
            base_attributes = graph.G.nodes[int(base)].get("attributes") or {}
            if base_attributes.get("aggregate_kind") == "dict":
                mapping_entry_members = []
                for role, ordinal, member_id in (
                    *(("index", index, int(member_id))
                      for index, member_id in enumerate(indices)),
                    ("value", 0, int(value)),
                ):
                    member_cell = node_identity_cell(graph, int(member_id))
                    position_cell = aggregate_position_cell(
                        int(node_id), str(role), int(ordinal),
                    )
                    if member_cell is None or position_cell is None:
                        raise ValueError(
                            "indexed mapping entry has no exact identity/slot "
                            f"cell: store={int(node_id)} member={member_id} "
                            f"role={role!r} ordinal={ordinal}"
                        )
                    _nested_layout, nested_layout_cell = (
                        source_aggregate_layout(int(member_id))
                    )
                    mapping_entry_members.append(_SourceAggregateMember(
                        int(member_id), member_cell,
                        tuple(filter(None, (
                            position_cell, nested_layout_cell,
                        ))),
                    ))
                post_source_aggregate_layout(
                    int(node_id), "dict", tuple(mapping_entry_members),
                )
            if isinstance(target.value, ast.Name):
                bind_target(target.value, node_id)
            elif isinstance(target.value, ast.Attribute) and isinstance(
                target.value.value, ast.Name
            ):
                # ``obj.field[i, j] = ...`` mutates ``obj.field`` in place
                # without rebinding ``obj`` itself, so the ``ast.Name`` path
                # above never fires here. Record the mutation the same way a
                # whole-attribute ``SetAttr`` does, keyed by the resolved
                # receiver of ``obj`` (not ``base``, which is the GetAttr
                # node for ``obj.field`` and does not change), so a later
                # bare read of ``obj.field`` can depend on this write.
                outer_receiver = resolve_expression(target.value.value)
                if isinstance(outer_receiver, int):
                    # ELEMENT_WRITTEN: value and effect are both the store
                    # (plan 70, section 1.3), DERIVED(outer receiver cell,
                    # field schema cell, IndexedStore cell).
                    element_cell = post_field_state(
                        outer_receiver, target.value.attr,
                        _FieldStateKind.ELEMENT_WRITTEN,
                        int(node_id), int(node_id),
                        sources=field_state_sources(
                            outer_receiver, target.value.attr,
                            node_identity_cell(graph, int(node_id)),
                        ),
                        stage=_REDUCER_FIELD_WRITE,
                    )
                    node_data.setdefault("attributes", {})[
                        "field_state_cell"
                    ] = element_cell
            return
        if isinstance(target, (ast.Tuple, ast.List)):
            if isinstance(value, _StaticPythonReference):
                raise TypeError(
                    "a static Python reference cannot be destructured as "
                    "a runtime graph value"
                )
            starred = tuple(
                index
                for index, element in enumerate(target.elts)
                if isinstance(element, ast.Starred)
            )
            if len(starred) > 1:
                raise ValueError("destructuring permits at most one starred target")
            starred_index = starred[0] if starred else None
            trailing = (
                len(target.elts) - starred_index - 1
                if starred_index is not None else 0
            )
            for index, element in enumerate(target.elts):
                if isinstance(element, ast.Starred):
                    projection = slice(
                        index,
                        -trailing if trailing else None,
                    )
                    binding_target = element.value
                else:
                    projection = (
                        index - len(target.elts)
                        if starred_index is not None and index > starred_index
                        else index
                    )
                    binding_target = element
                # Both stand for the authored target element they
                # destructure into.
                index_id = new_node(
                    "Constant",
                    repr(projection),
                    attributes={"value": projection},
                    source=element,
                )
                projected_id = new_node(
                    "Indexed",
                    f"unpack[{projection!r}]",
                    parents=(
                        (value, "base"),
                        (index_id, "index"),
                    ),
                    source=element,
                )
                if isinstance(projection, int):
                    # The direct ProcessGraph path lowers destructuring here;
                    # the pre-normalized compiler path reaches the equivalent
                    # Subscript branch in ``resolve_expression``.  Both post
                    # the same member-class fact from the same base/index
                    # edges.
                    concord_string_partition_member(
                        int(value), int(projection), int(projected_id),
                    )
                bind_target(binding_target, projected_id)

    def delete_target(target: ast.AST) -> int | None:
        """Lower one Python deletion target to its explicit state effect."""

        if isinstance(target, ast.Name):
            environment.pop(target.id, None)
            static_environment.pop(target.id, None)
            deleted_names.add(target.id)
            _remove_node(graph, id(target))
            return None
        if isinstance(target, ast.Attribute):
            receiver = resolve_expression(target.value)
            if isinstance(receiver, _StaticPythonReference):
                receiver = static_reference_node(receiver)
            if not isinstance(receiver, int):
                raise TypeError(
                    "attribute deletion requires a resolved object node in "
                    f"{statement.name}: "
                    f"target={ast.dump(target, include_attributes=False)}, "
                    f"receiver={receiver!r}"
                )
            node_id = id(target)
            if node_id not in graph.G:
                node_id = new_node(
                    "DelAttr",
                    f"delattr[{target.attr}]",
                    attributes={"attribute": target.attr},
                    source=target,
                )
            node_data = graph.G.nodes[node_id]
            node_data["type"] = "DelAttr"
            node_data["op"] = "delattr"
            node_data.setdefault("attributes", {})["attribute"] = target.attr
            _replace_inputs(graph, node_id, ((receiver, "object"),))
            return node_id
        if isinstance(target, ast.Subscript):
            base = resolve_expression(target.value)
            indices = (
                tuple(target.slice.elts)
                if isinstance(target.slice, ast.Tuple)
                else (target.slice,)
            )
            resolved_indices = tuple(resolve_expression(index) for index in indices)
            if not isinstance(base, int) or not all(
                isinstance(index, int) for index in resolved_indices
            ):
                raise TypeError(
                    "indexed deletion requires resolved container and index "
                    f"nodes in {statement.name}: "
                    f"target={ast.dump(target, include_attributes=False)}"
                )
            node_id = id(target)
            if node_id not in graph.G:
                node_id = new_node("DelItem", "delitem", source=target)
            node_data = graph.G.nodes[node_id]
            node_data["type"] = "DelItem"
            node_data["op"] = "delitem"
            node_data.setdefault("attributes", {})["source_type"] = "Subscript"
            _replace_inputs(
                graph,
                node_id,
                (
                    (base, "base"),
                    *((index, "index") for index in resolved_indices),
                ),
            )
            container = dict(
                graph.G.nodes[base].get("attributes") or {}
            )
            aggregate_kind = str(
                container.get("aggregate_kind") or ""
            ).casefold()
            sequence_policy = (
                "unique" if aggregate_kind in {"set", "dict"}
                else "duplicates" if aggregate_kind in {
                    "list", "tuple", "bytes", "bytearray", "array",
                }
                else None
            )
            if sequence_policy is not None:
                from ...compiler.concordance_declarations import (
                    SOURCE_SEQUENCE_MUTATION,
                )
                arguments = tuple(map(int, resolved_indices))
                fact = (
                    int(base), "delitem", sequence_policy, arguments,
                    "mapping" if aggregate_kind == "dict" else "sequence",
                )
                row = (value_class_scope, int(node_id))
                page = current_identity_book().page(
                    SOURCE_SEQUENCE_MUTATION
                )
                incumbent = page.latest(row)
                if incumbent is not None and tuple(incumbent) != fact:
                    raise ValueError(
                        "source sequence mutation concordance disagreement "
                        f"for {row!r}: recorded={incumbent!r}, proposed={fact!r}"
                    )
                if incumbent is None:
                    sources = [
                        node_identity_cell(graph, int(node_id)),
                        node_identity_cell(graph, int(base)),
                    ]
                    sources.extend(
                        node_identity_cell(graph, value_id)
                        for value_id in arguments
                    )
                    current_identity_book().post(
                        SOURCE_SEQUENCE_MUTATION, row, fact,
                        stage=_REDUCTION,
                        provenance=_Derived(tuple(dict.fromkeys(
                            cell for cell in sources if cell is not None
                        ))),
                        mode=_Mode.CONCORD,
                    )
            return node_id
        if isinstance(target, (ast.Tuple, ast.List)):
            effects = [delete_target(element) for element in target.elts]
            return next((effect for effect in reversed(effects) if effect is not None), None)
        raise TypeError(
            "unsupported Python deletion target: "
            f"{ast.dump(target, include_attributes=False)}"
        )

    def reduce_state_dispatch(dispatch: ast.Match) -> int:
        """Ingest the ``match`` a marked state machine's ``transition`` is.

        The statement is a dispatch construct, not a value: its node keeps
        the statement's identity and takes the state selector as its
        ``state`` operand and each literal case's constant as a ``case``
        operand, in case order (a case with no constant node, a bare
        ``True``/``False`` singleton, has no operand).  The case bodies are
        reduced as exclusive paths -- the calls they make are ordinary call
        nodes the planner places in the arms (``install_state_machine_control``)
        -- and every path starts from the environment the dispatch was
        entered with, which is also the environment after it: a planned
        dispatch's arms are single method calls and rebind no name.
        """

        # Parameters exist from function entry; mint every one this statement
        # reads before any arm does (the rule ``if`` and loops apply).
        for read_name in _source_entry_names(dispatch):
            if (
                read_name in parameter_names
                and read_name not in environment
                and read_name not in static_environment
            ):
                input_value(read_name, binding_kind="parameter")
        state_value = resolve_expression(dispatch.subject)
        if not isinstance(state_value, int):
            # No value to dispatch on: leave the construct as it was.
            record_translation_shortfall(
                graph, pass_name="state_dispatch", node_id=id(dispatch),
                operation="Match", role=value_class_scope,
                reason="the state selector did not resolve to a graph value",
            )
            return id(dispatch) if id(dispatch) in graph.G else None
        case_values = [
            resolve_expression(case.pattern.value)
            if isinstance(case.pattern, ast.MatchValue) else None
            for case in dispatch.cases
        ]
        before = dict(environment)
        before_field_cells = dict(field_state_cursor)
        for case in dispatch.cases:
            for nested in case.body:
                reduce_statement(nested)
            environment.clear()
            environment.update(before)
            field_state_cursor.clear()
            field_state_cursor.update(before_field_cells)
        # The pattern syntax carries no value of its own once the literals
        # are operands of the dispatch.
        for case in dispatch.cases:
            _remove_node(graph, id(case.pattern))
            _remove_node(graph, id(case))
        operands = [(int(state_value), "state")]
        operands.extend(
            (int(value), f"case:{index}")
            for index, value in enumerate(case_values)
            if isinstance(value, int)
        )
        if id(dispatch) in graph.G:
            _replace_inputs(graph, id(dispatch), tuple(operands))
            graph.G.nodes[id(dispatch)].setdefault("attributes", {}).update({
                "state_machine_dispatch": True,
                "state_machine_case_count": len(dispatch.cases),
            })
        return id(dispatch)

    def capture_loop_field_entries(body_statement: ast.stmt) -> None:
        """Push the pre-loop value of every constructed-record field the
        loop body writes (``loop_field_entry_values``).  A ``while``
        pushes before its test, which is read every iteration."""

        entry_values: dict[tuple[int, str], tuple[str, int]] = {}
        for nested in body_statement.body:
            for member in source_walk(nested):
                for target in (
                    member.targets if isinstance(member, ast.Assign)
                    else (member.target,)
                    if isinstance(member, (ast.AugAssign, ast.AnnAssign))
                    else ()
                ):
                    if not (
                        isinstance(target, ast.Attribute)
                        and isinstance(target.value, ast.Name)
                    ):
                        continue
                    receiver_id = environment.get(target.value.id)
                    key = (receiver_id, str(target.attr))
                    if not isinstance(receiver_id, int) or key in entry_values:
                        continue
                    value = constructed_field_value(
                        str(target.value.id), str(target.attr),
                    )
                    if value is not None:
                        entry_values[key] = (str(target.value.id), int(value))
        loop_field_entry_values.append(entry_values)

    def reduce_statement(body_statement: ast.stmt) -> int | None:
        # Individual Call resolution publishes stores after its operands;
        # premarking a whole statement invalidates reads before the call.
        result = reduce_statement_body(body_statement)
        if not isinstance(body_statement, (
            ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef,
        )):
            storing_call_receivers.update(storing_call_names(body_statement))
        return result

    def reduce_statement_body(body_statement: ast.stmt) -> int | None:
        if isinstance(body_statement, (ast.Nonlocal, ast.Global)):
            # Scope declarations affect name binding while parsing; they are
            # not runtime operations and must never reach an execution
            # backend as operator nodes.  The reducer's lexical environments
            # and explicit Input/SetAttr effects carry the resulting values.
            _remove_node(graph, id(body_statement))
            return None
        if isinstance(body_statement, ast.Delete):
            effects = [delete_target(target) for target in body_statement.targets]
            _remove_node(graph, id(body_statement))
            return next(
                (effect for effect in reversed(effects) if effect is not None),
                None,
            )
        if isinstance(body_statement, (ast.Assign, ast.AnnAssign)):
            value = resolve_expression(body_statement.value)
            targets = (
                tuple(body_statement.targets)
                if isinstance(body_statement, ast.Assign)
                else (body_statement.target,)
            )
            for target in targets:
                bind_target(target, value, value_occurrence=body_statement.value)
            _remove_node(graph, id(body_statement))
            return value
        if isinstance(body_statement, ast.AugAssign):
            arena_mask = None
            if isinstance(body_statement.target, ast.Name):
                current = environment.get(body_statement.target.id)
                if current is None:
                    current = input_value(
                        body_statement.target.id,
                        binding_kind=(
                            "parameter"
                            if body_statement.target.id in parameter_names
                            else "exception"
                            if body_statement.target.id in exception_local_names
                            else "external"
                        ),
                        occurrence=body_statement.target,
                    )
            elif (
                isinstance(body_statement.target, ast.Subscript)
                # Program: ``xs = [0, 0, 0, 0]; for i in range(6):
                # xs[i % 4] += i + n`` (corpus c373).  Wrong record: an
                # index that was not a constant or a loop target was taken
                # for a boolean mask by its spelling, so the store became
                # ``where(i % 4, xs + i + n, xs)`` and C had no spelling
                # for it.  Rule: a base whose recorded class is a list or
                # dict takes no array mask, so its subscript is one row.  A
                # base already stored into is read through the stores'
                # ``base`` edges to the sequence that carries the class.
                # A formal not yet read has no Input; its annotation's
                # aggregate kind (the record its Input is built from) says.
                and not (
                    isinstance(body_statement.target.value, ast.Name)
                    and (
                        _is_row_collection(graph, _indexed_store_source(
                            graph,
                            environment.get(body_statement.target.value.id),
                        ))
                        or (
                            environment.get(body_statement.target.value.id)
                            is None
                            and parameter_aggregate_kinds.get(
                                body_statement.target.value.id
                            ) in {"list", "dict"}
                        )
                    )
                )
                and not all(
                    isinstance(item, ast.Slice)
                    or (
                        isinstance(item, ast.Constant)
                        and (
                            isinstance(item.value, int)
                            or item.value is Ellipsis
                        )
                    )
                    or (
                        isinstance(item, ast.Name)
                        and environment.get(item.id)
                        in scalar_loop_binding_ids
                    )
                    for item in (
                        tuple(body_statement.target.slice.elts)
                        if isinstance(body_statement.target.slice, ast.Tuple)
                        else (body_statement.target.slice,)
                    )
                )
            ):
                # Keep aligned boolean-mask updates arena-shaped.  Evaluating
                # ``field[mask] += rhs[mask]`` literally creates two compact,
                # data-dependent vectors and then requires a scatter.  The
                # equivalent functional form
                # ``field = where(mask, field + rhs, field)`` retains the
                # preallocated grid shape through every compiler stage.
                current = resolve_expression(body_statement.target.value)
                arena_mask = resolve_expression(
                    body_statement.target.slice
                )
                target_slice = ast.dump(
                    body_statement.target.slice,
                    include_attributes=False,
                )
                for candidate in source_walk(body_statement.value):
                    if not isinstance(candidate, ast.Subscript):
                        continue
                    if ast.dump(
                        candidate.slice,
                        include_attributes=False,
                    ) != target_slice:
                        continue
                    aligned = resolve_expression(candidate.value)
                    if isinstance(aligned, int):
                        _redirect_value(graph, id(candidate), aligned)
            else:
                current = resolve_expression(body_statement.target)
            if current is not None:
                if isinstance(body_statement.target, ast.Name):
                    # ``name += x`` reads ``name`` without a Load occurrence.
                    _concord_lexical_reads(
                        graph, ingestion_read_scope,
                        id(body_statement.target), body_statement.target.id,
                        binding_cell=current_name_binding_cell(
                            body_statement.target.id, current,
                        ),
                    )
                _redirect_value(
                    graph,
                    id(body_statement.target),
                    current,
                )
            resolve_expression(body_statement.value)
            node_id = id(body_statement)
            if current is None or node_id not in graph.G:
                return None
            if isinstance(arena_mask, int):
                # The ``where`` IS the authored masked augmented assignment
                # in its functional form: it stands on that statement.
                where_id = new_node(
                    "where",
                    "where",
                    attributes={
                        "source_type": "MaskedAugAssign",
                        "arena_shaped": True,
                    },
                    parents=(
                        (arena_mask, "condition"),
                        (node_id, "true"),
                        (current, "false"),
                    ),
                    source=body_statement,
                )
                bind_target(body_statement.target.value, where_id)
                return where_id
            bind_target(body_statement.target, node_id)
            return node_id
        if isinstance(body_statement, ast.Return):
            returned = body_statement.value
            expressions = (
                tuple(returned.elts)
                if _return_display_flattens(statement, returned)
                else (returned,)
            )
            output_names = tuple(
                graph.G.graph.get("function_outputs", ())
            )
            positional_names = set(
                graph.G.graph.get("positional_output_names", ())
            )
            resolved = []
            slot_values: list[int | None] = []
            # The return site's identity is the returned expression's node
            # cell and the construct's is the Return statement's; both are
            # read before the slot expressions resolve, since resolving a
            # ``Name`` redirects and removes its occurrence node.
            return_site_cell = (
                _posted_node_identity_cell(graph, id(returned))
                if returned is not None else None
            )
            return_construct_cell = (
                _posted_node_identity_cell(graph, id(body_statement)) or return_site_cell
            )
            slot_expression_cells = tuple(
                _posted_node_identity_cell(graph, id(expression))
                if expression is not None else None
                for expression in expressions
            )
            for index, expression in enumerate(expressions):
                value = resolve_expression(expression)
                if isinstance(value, _StaticPythonReference):
                    # A returned compiler symbol crosses the same explicit
                    # host boundary as a symbol stored into a field or passed
                    # to a call.  Materialize its existing StaticReference
                    # identity before publishing the return-site receipt;
                    # leaving the ephemeral resolver object here made the
                    # later value-id bookkeeping call ``int()`` on a Python
                    # object and discarded the boundary entirely.
                    value = static_reference_node(value)
                slot_values.append(value if isinstance(value, int) else None)
                if value is None:
                    continue
                resolved.append(value)
                if return_arms_kind is None and index < len(output_names) and (
                    str(output_names[index]) in positional_names
                ):
                    # A positional slot has no binding of its own; its
                    # history is the list of return-site values (each site
                    # is also recorded exactly in `return_slot_values`). A
                    # name-spelled slot IS a variable whose own binding
                    # already holds this value -- appending it again would
                    # only duplicate the entry and make the return site look
                    # like a rebinding to every history consumer.
                    identity_bindings.setdefault(
                        str(output_names[index]), []
                    ).append(value)
                    post_name_binding(
                        str(output_names[index]), int(value), authored=False,
                        span_positions=(None,) * 4, context_sha256="",
                        cells=(),
                    )
            # Every return statement names its OWN value per output slot.
            # The identity history above is a single chain per slot, so any
            # consumer reading ``history[-1]`` sees only the last return;
            # a return nested in a loop or conditional must instead branch to
            # the function exit carrying these exact values, where they are
            # merged per slot (control-aware result merging, see
            # docs/PLAN_CONTROL_AWARE_RESULT_MERGING.md). Key by source span:
            # AST object ids do not survive reduction, spans do.
            if returned is not None and getattr(returned, "lineno", None) is not None:
                return_span = (
                    int(returned.lineno),
                    int(getattr(returned, "col_offset", -1)),
                    int(getattr(returned, "end_lineno", -1)),
                    int(getattr(returned, "end_col_offset", -1)),
                )
                # Three return-site pages (plan 70, section 2), all keyed by
                # the site cell; the legacy span-keyed receipts are read
                # views over them (``return_site_spans`` joins the two).
                return_site_spans[return_site_cell] = return_span
                slot_cells: dict[int, _Ref] = {}
                for index, slot_value in enumerate(slot_values):
                    slot_row = (ingestion_read_scope, return_site_cell, index)
                    if slot_value is None:
                        # The slot's expression resolved to a non-value.
                        slot_cells[index] = field_state_book.post(
                            _RETURN_SITE_SLOT, slot_row,
                            _Unresolved(
                                _RETURN_SLOT_NOT_A_VALUE, (return_construct_cell,),
                            ),
                            stage=_REDUCER_RETURN,
                            provenance=_Derived((return_construct_cell,)),
                            mode=_Mode.CONCORD,
                        )
                        continue
                    slot_cells[index] = field_state_book.post(
                        _RETURN_SITE_SLOT, slot_row,
                        node_identity_cell(graph, int(slot_value)),
                        stage=_REDUCER_RETURN,
                        provenance=_Derived(tuple(dict.fromkeys(
                            cell for cell in (
                                slot_expression_cells[index],
                                return_construct_cell,
                            ) if cell is not None
                        ))),
                        mode=_Mode.CONCORD,
                    )
                # Physical output slots alone cannot distinguish `return x`
                # from `return (x,)`. Preserve authored container semantics
                # beside the same exact return-site receipt before flattening.
                container_cell = field_state_book.post(
                    _RETURN_SITE_CONTAINER,
                    (ingestion_read_scope, return_site_cell),
                    _ContainerKind.VALUE
                    if not _return_display_flattens(statement, returned)
                    else _ContainerKind.TUPLE if isinstance(returned, ast.Tuple)
                    else _ContainerKind.LIST if isinstance(returned, ast.List)
                    else _ContainerKind.VALUE,
                    stage=_REDUCER_RETURN,
                    provenance=_Derived((return_construct_cell,)),
                    mode=_Mode.CONCORD,
                )
                if body_statement is statement.body[-1]:
                    return_tail_sites.add(return_site_cell)
                return_arm_posts.append((
                    return_site_cell, container_cell,
                    tuple(slot_cells[index] for index in sorted(slot_cells)),
                    isinstance(returned, ast.Constant)
                    and returned.value is None,
                ))
                # Record correlation alone does not describe the field state
                # at this return.  For every field row whose receiver is a
                # returned slot, the site names the cursor cell current here,
                # DERIVED(that cell, the slot cell carrying the receiver); the
                # linker may use only values physically available on the
                # corresponding return edge, never the final global ledger.
                for (receiver, field), state_cell in tuple(
                    field_state_cursor.items()
                ):
                    if receiver not in slot_values:
                        continue
                    slot_cell = slot_cells[slot_values.index(receiver)]
                    site_row = (
                        ingestion_read_scope, return_site_cell,
                        int(receiver), str(field),
                    )
                    state = field_state_at(state_cell)
                    field_state_book.post(
                        _RETURN_SITE_FIELD_STATE, site_row,
                        _Unresolved(
                            _FIELD_STATE_UNRESOLVED_AT_RETURN, (state_cell,),
                        ) if isinstance(state, _Unresolved) else state_cell,
                        stage=_REDUCER_RETURN,
                        provenance=_Derived((state_cell, slot_cell)),
                        mode=_Mode.CONCORD,
                    )
                for construct_id in {id(body_statement), id(returned)}:
                    if construct_id in graph.G:
                        graph.G.nodes[construct_id].setdefault(
                            "attributes", {}
                        )["return_site_cell"] = return_site_cell
            if len(expressions) == 1:
                value = resolved[0] if resolved else None
                if value is not None:
                    graph.G.graph.setdefault(
                        "return_value_nodes",
                        {},
                    )[id(body_statement)] = value
                    if isinstance(expressions[0], ast.Name):
                        return_root_bindings.setdefault(
                            int(value), {}
                        ).setdefault(str(expressions[0].id), []).append(
                            expressions[0]
                        )
                return value
            # Preserve the structural tuple/list node for callers that consume
            # it as one Python-shaped value while the output identities above
            # expose each semantic result directly to compiled call binding.
            value = resolve_expression(returned)
            if value is not None:
                graph.G.graph.setdefault(
                    "return_value_nodes",
                    {},
                )[id(body_statement)] = value
            return value
        if isinstance(body_statement, (ast.With, ast.AsyncWith)):
            static_contexts = []
            for item in body_statement.items:
                context_value = resolve_expression(item.context_expr)
                if context_value is not None and context_value in graph.G:
                    context_data = graph.G.nodes[context_value]
                    reference = (
                        context_data.get("attributes") or {}
                    ).get("static_python_reference")
                    if reference == "autograd.no_grad":
                        static_contexts.append(
                            {
                                "reference": reference,
                                "effect": "disable_backward_recording",
                                "lineno": getattr(
                                    item.context_expr,
                                    "lineno",
                                    None,
                                ),
                                "end_lineno": getattr(
                                    item.context_expr,
                                    "end_lineno",
                                    None,
                                ),
                            }
                        )
                        _remove_node(graph, context_value)
                resolve_expression(item.optional_vars)
            result = None
            for nested in body_statement.body:
                result = reduce_statement(nested)
            if static_contexts:
                recorded = list(
                    graph.G.graph.get("static_contexts", ())
                )
                recorded.extend(static_contexts)
                graph.G.graph["static_contexts"] = tuple(recorded)
                for item in body_statement.items:
                    _remove_node(graph, id(item))
                _remove_node(graph, id(body_statement))
            return result
        if isinstance(body_statement, ast.Match):
            from ...compiler.state_machine_ast import (
                dispatch_arms_are_effects, planned_dispatch,
            )

            if planned_dispatch(
                graph.G.graph.get("state_machine_controls"),
                value_class_scope, statement, body_statement,
            ) is not None:
                if dispatch_arms_are_effects(body_statement):
                    return reduce_state_dispatch(body_statement)
                # A ``return`` in a case arm is a return edge the tick would
                # have to merge per output slot; that merge is not built.
                # The construct keeps the reducer's ordinary handling and
                # says so, rather than run the arms' calls unconditionally.
                record_translation_shortfall(
                    graph, pass_name="state_dispatch",
                    node_id=id(body_statement), operation="Match",
                    role=value_class_scope,
                    reason=(
                        "a case arm returns its call's value; the tick does "
                        "not merge return edges across its arms"
                    ),
                )
        if isinstance(body_statement, ast.If):
            # Python parameters exist from function entry.  A parameter first
            # read inside one arm is minted there and dropped with that arm's
            # environment, so the next read mints a SECOND Input for the same
            # parameter: two formals for one authored argument, and a returned
            # in/out parameter whose storage the caller can no longer bind.
            # Mint every parameter this statement reads BEFORE the snapshot,
            # the rule loops already apply; ``input_value`` is idempotent.
            for read_name in _source_entry_names(body_statement):
                if (
                    read_name in parameter_names
                    and read_name not in environment
                    and read_name not in static_environment
                ):
                    input_value(read_name, binding_kind="parameter")
            test_value = resolve_expression(body_statement.test)
            # Control-flow value merging remains a planner responsibility.
            # Reduce lexical occurrences within each arm without pretending
            # that either arm executed unconditionally.
            before = dict(environment)
            # Field state: the book is append-only, so an arm's revisions
            # stay on their rows; what is captured and reset at each arm
            # boundary is the CURSOR (which cell is current per field row).
            before_field_cells = dict(field_state_cursor)
            body_environment = dict(before)
            environment.clear()
            environment.update(body_environment)
            body_result = None
            for nested in body_statement.body:
                body_result = reduce_statement(nested)
            body_environment = dict(environment)
            body_field_cells = dict(field_state_cursor)
            environment.clear()
            environment.update(before)
            field_state_cursor.clear()
            field_state_cursor.update(before_field_cells)
            else_result = None
            for nested in body_statement.orelse:
                else_result = reduce_statement(nested)
            else_environment = dict(environment)
            else_field_cells = dict(field_state_cursor)
            environment.clear()
            environment.update(before)
            field_state_cursor.clear()
            field_state_cursor.update(before_field_cells)

            def terminal_branch(statements: list[ast.stmt]) -> bool:
                if not statements:
                    return False
                terminal = statements[-1]
                if isinstance(
                    terminal,
                    (ast.Return, ast.Raise, ast.Continue, ast.Break),
                ):
                    return True
                if not isinstance(terminal, ast.If):
                    return False
                return (
                    bool(terminal.orelse)
                    and terminal_branch(terminal.body)
                    and terminal_branch(terminal.orelse)
                ) or (
                    id(terminal) in graph.G
                    and bool(
                        (graph.G.nodes[id(terminal)].get("attributes") or {}).get(
                            "terminal_return_merge"
                        )
                    )
                )

            body_terminal = terminal_branch(body_statement.body)
            else_terminal = terminal_branch(body_statement.orelse)

            # A guard clause -- `if cond: body else: raise` or its mirror --
            # has only one arm that can ever reach the statement after the
            # if.  The other arm's bindings (an old value the raising arm
            # never rebinds, or a value the raising arm never gets to use)
            # are not an alternative the merge point can observe; inventing
            # a Phi between them and the live arm's value merges a value
            # that no execution ever actually produces on that edge, which
            # a downstream backend then has no real producer for.  Skip the
            # merge and let the single reachable arm's environment stand.
            conditional_cell = (
                node_identity_cell(graph, id(body_statement))
                if id(body_statement) in graph.G
                else node_identity_cell(graph, int(test_value))
                if isinstance(test_value, int) else None
            )

            def select_live_arm(arm_cells: dict) -> None:
                """The one reachable arm's field state stands after the
                conditional: for every field row whose live-arm cell differs
                from the pre-branch cell, ARM_SELECTED with that arm's value
                and effect, DERIVED(live arm cell, conditional cell) (plan
                70, S8).  The terminal arm's last state is not lost: it is
                the cell the terminal arm's own return row derived from."""

                for field_key, live_cell in arm_cells.items():
                    if before_field_cells.get(field_key) == live_cell:
                        field_state_cursor[field_key] = live_cell
                        continue
                    live_state = field_state_at(live_cell)
                    if not isinstance(live_state, _FieldState):
                        # An unresolved arm state stays the cursor cell; the
                        # return site that reads it records the absence.
                        field_state_cursor[field_key] = live_cell
                        continue
                    receiver_id, attribute_name = field_key
                    post_field_state(
                        receiver_id, attribute_name,
                        _FieldStateKind.ARM_SELECTED,
                        _cell_node_id(live_state.value),
                        _cell_node_id(live_state.effect),
                        sources=tuple(dict.fromkeys(
                            cell for cell in (live_cell, conditional_cell)
                            if cell is not None
                        )),
                        stage=_REDUCER_FIELD_MERGE,
                    )

            if body_terminal and not else_terminal:
                environment.update(else_environment)
                select_live_arm(else_field_cells)
            elif else_terminal and not body_terminal:
                environment.update(body_environment)
                select_live_arm(body_field_cells)
            else:
                for name in set(before) | set(body_environment) | set(
                    else_environment
                ):
                    body_value = body_environment.get(name, before.get(name))
                    else_value = else_environment.get(name, before.get(name))
                    if body_value == else_value:
                        if body_value is not None:
                            environment[name] = body_value
                        continue
                    if (
                        isinstance(test_value, int)
                        and isinstance(body_value, int)
                        and isinstance(else_value, int)
                    ):
                        merged_attributes = {
                            "binding_name": name,
                            "source_conditional_id": id(body_statement),
                            **({
                                "initial_value_id": int(before[name]),
                            } if isinstance(before.get(name), int) else {}),
                        }
                        body_attributes = (
                            graph.G.nodes[body_value].get("attributes") or {}
                        )
                        else_attributes = (
                            graph.G.nodes[else_value].get("attributes") or {}
                        )
                        body_kind = body_attributes.get("aggregate_kind")
                        if (
                            body_kind is not None
                            and body_kind == else_attributes.get(
                                "aggregate_kind"
                            )
                        ):
                            merged_attributes.update({
                                key: body_attributes[key]
                                for key in (
                                    "aggregate_kind",
                                    "sequence_key_columns",
                                    "sequence_column_count",
                                    "sequence_writable",
                                )
                                if key in body_attributes
                            })
                            merged_attributes["producer_kind"] = (
                                "aggregate_phi"
                            )
                        # A Phi is its incoming values selected by the test
                        # at this ``if``: its row derives from their cells
                        # and the statement's span (edges lane C).
                        merged_value = new_node(
                            "Phi",
                            name,
                            attributes=merged_attributes,
                            parents=(
                                (test_value, "test"),
                                (body_value, "body"),
                                (else_value, "orelse"),
                            ),
                            source_cell=(
                                node_identity_cell(graph, int(test_value)),
                                node_identity_cell(graph, int(body_value)),
                                node_identity_cell(graph, int(else_value)),
                                _post_source_span(body_statement),
                            ),
                        )
                        if merged_attributes.get("producer_kind") == (
                            "aggregate_phi"
                        ):
                            post_conditional_aggregate_layout(
                                int(merged_value), int(test_value),
                                int(body_value), int(else_value),
                                conditional_cell,
                            )
                        environment[name] = merged_value
                        # The identity history is the authoritative lexical
                        # version chain used by conditional-control lowering.
                        # Omitting the merge made a nested branch's continuation
                        # visible to later expressions but invisible to the
                        # control overlay, so no executable Phi was emitted for
                        # either the inner or enclosing conditional.
                        identity_bindings.setdefault(name, []).append(
                            merged_value
                        )
                        post_name_binding(
                            name, int(merged_value), authored=False,
                            span_positions=(None,) * 4, context_sha256="",
                            cells=(),
                        )

                # A record field is state just as a local name is.  Its
                # explicit GetAttr projection is the incoming SSA value, while
                # SetAttr contributes its RHS rather than its effect node.
                # First observation in an arm still names the receiver's
                # physical field. Seed the other edge from that projection,
                # never from an invented scalar Input or a read-history Phi.
                # Every arm state below is a CELL of the field's row, so the
                # merge names the arm's version, never an id that a later
                # lowering could confuse with another node's.
                def arm_effect_cell(arm_cells: dict, field_key: tuple) -> Any:
                    """The arm's cell when the arm CHANGED the field (a write,
                    a merge, a selected arm); None when the arm left the
                    pre-branch cell in place or only observed the field."""

                    cell = arm_cells.get(field_key)
                    if cell is None or cell == before_field_cells.get(field_key):
                        return None
                    state = field_state_at(cell)
                    if (
                        isinstance(state, _FieldState)
                        and state.kind is _FieldStateKind.OBSERVED
                    ):
                        return None
                    return cell

                def arm_effect_node(arm_cells: dict, field_key: tuple) -> int | None:
                    state = field_state_at(arm_effect_cell(arm_cells, field_key))
                    return (
                        _cell_node_id(state.effect)
                        if isinstance(state, _FieldState) else None
                    )

                for field_key in tuple(dict.fromkeys(
                    (*body_field_cells, *else_field_cells)
                )):
                    carried_entry = next((
                        entries[field_key]
                        for entries in reversed(loop_field_entry_values)
                        if field_key in entries
                    ), None)
                    if field_key in before_field_cells:
                        entered_cell = before_field_cells[field_key]
                        entered = field_state_at(entered_cell)
                        if not (
                            carried_entry is not None
                            and isinstance(entered, _FieldState)
                            and entered.kind is not _FieldStateKind.OBSERVED
                            and _cell_node_id(entered.value)
                            == int(carried_entry[1])
                        ):
                            continue
                        # The branch is entered with the field unchanged
                        # since the loop began: a write BEFORE the loop.  Its
                        # version is the pre-loop one, but inside the loop
                        # the field is the carried value.  Re-enter as an
                        # observation of that value (below), so the arm that
                        # leaves it alone reads the loop's version.
                        for arm_cells in (body_field_cells, else_field_cells):
                            if arm_cells.get(field_key) in (None, entered_cell):
                                arm_cells.pop(field_key, None)
                        before_field_cells.pop(field_key)
                    if carried_entry is not None:
                        # Inside a loop that carries this field, the state
                        # before the branch is the carried value, not a read
                        # of the record's storage: field writes are versions,
                        # and the storage still holds the construction.
                        seeded_cell = post_field_state(
                            field_key[0], field_key[1],
                            _FieldStateKind.OBSERVED,
                            int(carried_entry[1]), int(carried_entry[1]),
                            sources=field_state_sources(
                                field_key[0], field_key[1],
                                node_identity_cell(graph, int(carried_entry[1])),
                            ),
                            stage=_REDUCER_FIELD_MERGE,
                        )
                        before_field_cells[field_key] = seeded_cell
                        for arm_cells in (body_field_cells, else_field_cells):
                            if arm_effect_cell(arm_cells, field_key) is None:
                                arm_cells[field_key] = seeded_cell
                        continue
                    receiver_id, attribute_name = field_key
                    receiver_class = receiver_class_identity(receiver_id)
                    if receiver_class is None:
                        effect_classes = {
                            str(slot[0])
                            for effect_id in (
                                arm_effect_node(body_field_cells, field_key),
                                arm_effect_node(else_field_cells, field_key),
                            )
                            if effect_id is not None
                            and int(effect_id) in graph.G
                            for slot in ((
                                graph.G.nodes[int(effect_id)].get(
                                    "attributes"
                                ) or {}
                            ).get("attribute_slot"),)
                            if (
                                isinstance(slot, tuple)
                                and len(slot) == 2
                            )
                        }
                        if len(effect_classes) == 1:
                            receiver_class = next(iter(effect_classes))
                    field_kind = (
                        (class_field_aggregate_kinds or {}).get((
                            str(receiver_class), str(attribute_name)
                        ))
                        if receiver_class is not None else None
                    )
                    initial_attributes = {
                        "attribute": attribute_name,
                        "initial_record_field_state": True,
                    }
                    if field_kind is not None:
                        mapping_contract = dict(
                            (class_field_mapping_contracts or {}).get((
                                str(receiver_class), str(attribute_name)
                            )) or {}
                        )
                        sequence_dtypes = tuple(
                            (class_field_sequence_dtypes or {}).get((
                                str(receiver_class), str(attribute_name)
                            )) or ()
                        )
                        sequence_element_class = (
                            (class_field_sequence_element_classes or {}).get((
                                str(receiver_class), str(attribute_name)
                            ))
                        )
                        sequence_annotation_cell = declared_field_schema_cell(
                            receiver_class, attribute_name,
                        )
                        initial_attributes.update({
                            "producer_kind": "record_field",
                            "aggregate_kind": field_kind,
                            "sequence_key_columns": (
                                (0,)
                                if field_kind in {
                                    "set", "frozenset", "dict",
                                }
                                else ()
                            ),
                            "sequence_column_count": (
                                2 if field_kind == "dict" else 1
                            ),
                            "sequence_writable": field_kind not in {
                                "tuple", "frozenset", "bytes",
                            },
                            "record_field": (
                                str(receiver_class), str(attribute_name)
                            ),
                            **({
                                "sequence_column_dtypes": sequence_dtypes,
                            } if sequence_dtypes else {}),
                            **({
                                "sequence_element_class_ref": str(
                                    sequence_element_class
                                ),
                                "sequence_element_annotation_cell": (
                                    sequence_annotation_cell
                                ),
                            } if sequence_element_class is not None
                               and sequence_annotation_cell is not None else {}),
                            **mapping_contract,
                        })
                    initial = new_node(
                        "GetAttr", f"getattr[{attribute_name}]",
                        attributes=initial_attributes,
                        parents=((int(receiver_id), "value"),),
                        source=body_statement,
                    )
                    # The seeded pre-branch state: OBSERVED at the synthesized
                    # projection, DERIVED(receiver cell, field schema cell,
                    # the initial's own node cell).  It becomes the cursor
                    # cell too, since the pre-branch cursor is what the
                    # merge below reads as "before".
                    seeded_cell = post_field_state(
                        receiver_id, attribute_name, _FieldStateKind.OBSERVED,
                        int(initial), int(initial),
                        sources=field_state_sources(
                            receiver_id, attribute_name,
                            node_identity_cell(graph, int(initial)),
                        ),
                        stage=_REDUCER_FIELD_MERGE,
                    )
                    before_field_cells[field_key] = seeded_cell
                    for arm_cells in (body_field_cells, else_field_cells):
                        if arm_effect_cell(arm_cells, field_key) is None:
                            arm_cells[field_key] = seeded_cell
                for field_key, initial_cell in tuple(before_field_cells.items()):
                    body_cell = body_field_cells.get(field_key, initial_cell)
                    else_cell = else_field_cells.get(field_key, initial_cell)
                    if body_cell == else_cell:
                        # Both arms end at the same cell: the row's state IS
                        # that cell; nothing new to post.
                        field_state_cursor[field_key] = body_cell
                        continue
                    if not isinstance(test_value, int):
                        # A compile-time test: no runtime merge exists.  The
                        # state stays at the pre-branch cell, as today (the
                        # Unresolved reason plan 70 spells for this case is
                        # not declared; see the step-3 report).
                        field_state_cursor[field_key] = initial_cell
                        continue
                    receiver_id, attribute_name = field_key
                    initial_state = field_state_at(initial_cell)
                    body_state = field_state_at(body_cell)
                    else_state = field_state_at(else_cell)
                    if not all(
                        isinstance(state, _FieldState)
                        for state in (initial_state, body_state, else_state)
                    ):
                        # An arm (or the pre-branch state) is Unresolved -- a
                        # loop exit inside the arm -- so no version can be
                        # merged; the unresolved cell stays current and the
                        # return site that reads it records the absence.
                        field_state_cursor[field_key] = next(
                            cell for cell, state in (
                                (body_cell, body_state), (else_cell, else_state),
                                (initial_cell, initial_state),
                            ) if not isinstance(state, _FieldState)
                        )
                        continue
                    initial_value = _cell_node_id(initial_state.value)
                    body_value = _cell_node_id(body_state.value)
                    else_value = _cell_node_id(else_state.value)
                    branch_effect_ids = tuple(
                        int(effect_id)
                        for effect_id in (
                            arm_effect_node(body_field_cells, field_key),
                            arm_effect_node(else_field_cells, field_key),
                        )
                        if effect_id is not None and int(effect_id) in graph.G
                    )
                    if body_value == else_value:
                        # Two versions holding one value node: no runtime
                        # choice exists, exactly as the id comparison decided.
                        field_state_cursor[field_key] = body_cell
                        continue
                    authored_field_names = {
                        f"{effect.value.id}.{effect.attr}"
                        for effect_id in branch_effect_ids
                        for effect in (graph.G.nodes[effect_id].get("expr_obj"),)
                        if isinstance(effect, ast.Attribute)
                        and isinstance(effect.value, ast.Name)
                    }
                    binding_name = (
                        next(iter(authored_field_names))
                        if len(authored_field_names) == 1 else
                        f"field:{receiver_id}.{attribute_name}"
                    )
                    body_attributes = (
                        graph.G.nodes[int(body_value)].get("attributes") or {}
                    )
                    else_attributes = (
                        graph.G.nodes[int(else_value)].get("attributes") or {}
                    )
                    merged_attributes = {
                        "binding_name": binding_name,
                        "source_conditional_id": id(body_statement),
                        "initial_value_id": int(initial_value),
                        "record_field_state": (
                            int(receiver_id), str(attribute_name)
                        ),
                    }
                    body_kind = body_attributes.get("aggregate_kind")
                    if (
                        body_kind is not None
                        and body_kind == else_attributes.get("aggregate_kind")
                    ):
                        merged_attributes.update({
                            key: body_attributes[key]
                            for key in (
                                "aggregate_kind",
                                "sequence_key_columns",
                                "sequence_column_count",
                                "sequence_writable",
                                "record_field",
                            )
                            if key in body_attributes
                        })
                        merged_attributes["producer_kind"] = "aggregate_phi"
                    merged_value = new_node(
                        "Phi",
                        binding_name,
                        attributes=merged_attributes,
                        parents=(
                            (int(test_value), "test"),
                            (int(body_value), "body"),
                            (int(else_value), "orelse"),
                        ),
                        source=body_statement,
                    )
                    carried_entry = next((
                        entries[field_key]
                        for entries in reversed(loop_field_entry_values)
                        if field_key in entries
                    ), None)
                    if carried_entry is not None:
                        # The arm that left a carried field alone reads its
                        # carried version: name that binding on the Phi's
                        # operand, as a Name read would, so the loop header
                        # rebinds it.
                        from ...compiler.concordance_declarations import (
                            OPERAND_POSITION as _OPERAND_POSITION_STAGE,
                        )

                        carried_name = (
                            f"{carried_entry[0]}.{attribute_name}"
                        )
                        for operand_value, operand_role, operand_cell in (
                            (body_value, "body", body_cell),
                            (else_value, "orelse", else_cell),
                        ):
                            if int(operand_value) != int(carried_entry[1]):
                                continue
                            current_identity_book().post(
                                _LEXICAL_READ_BINDING,
                                (
                                    ingestion_read_scope,
                                    int(merged_value), operand_role, 0,
                                ),
                                carried_name,
                                stage=_OPERAND_POSITION_STAGE,
                                provenance=_Derived(_source_cells((
                                    operand_cell,
                                    node_identity_cell(graph, int(merged_value)),
                                ))),
                                mode=_Mode.CONCORD,
                            )
                    if merged_attributes.get("producer_kind") == (
                        "aggregate_phi"
                    ):
                        post_conditional_aggregate_layout(
                            int(merged_value), int(test_value),
                            int(body_value), int(else_value),
                            conditional_cell,
                        )
                    identity_bindings.setdefault(binding_name, []).append(
                        merged_value
                    )
                    post_name_binding(
                        binding_name, int(merged_value), authored=False,
                        span_positions=(None,) * 4, context_sha256="",
                        cells=(),
                    )
                    # MERGED: value and effect are the Phi, DERIVED(body arm
                    # cell, else arm cell, test node cell, the Phi's own node
                    # cell) (plan 70, S5-S7).  The Phi carries the merged
                    # cell and its three arm/test cells, so the arm a
                    # lowering reads is a CELL of this row -- the SetAttr-id
                    # versus RHS-id mismatch of census 50 cannot recur.
                    test_cell = node_identity_cell(graph, int(test_value))
                    merged_cell = post_field_state(
                        receiver_id, attribute_name, _FieldStateKind.MERGED,
                        int(merged_value), int(merged_value),
                        sources=tuple(dict.fromkeys(
                            cell for cell in (
                                body_cell, else_cell, test_cell,
                                node_identity_cell(graph, int(merged_value)),
                            ) if cell is not None
                        )),
                        stage=_REDUCER_FIELD_MERGE,
                    )
                    graph.G.nodes[merged_value].setdefault("attributes", {}).update({
                        "field_state_cell": merged_cell,
                        "field_state_arms": (body_cell, else_cell, test_cell),
                    })

            if (
                isinstance(test_value, int)
                and isinstance(body_result, int)
                and isinstance(else_result, int)
                and body_terminal
                and else_terminal
                and id(body_statement) in graph.G
            ):
                _replace_inputs(
                    graph,
                    id(body_statement),
                    (
                        (test_value, "test"),
                        (body_result, "body"),
                        (else_result, "orelse"),
                    ),
                )
                graph.G.nodes[id(body_statement)].setdefault(
                    "attributes", {}
                ).update({
                    "terminal_return_merge": True,
                    "terminal_return_values": (
                        int(body_result),
                        int(else_result),
                    ),
                })
            return id(body_statement)
        if isinstance(body_statement, ast.Try):
            # Python parameters exist from function entry.  A parameter first
            # read inside one arm is minted there and dropped with that arm's
            # environment, so the next read mints a SECOND Input for the same
            # parameter: two formals for one authored argument, and a returned
            # in/out parameter whose storage the caller can no longer bind.
            # Mint every parameter this statement reads BEFORE the snapshot,
            # the rule loops already apply; ``input_value`` is idempotent.
            for read_name in _source_entry_names(body_statement):
                if (
                    read_name in parameter_names
                    and read_name not in environment
                    and read_name not in static_environment
                ):
                    input_value(read_name, binding_kind="parameter")
            before = dict(environment)
            for nested in body_statement.body:
                reduce_statement(nested)
            body_environment = dict(environment)

            handler_environments = []
            for handler in body_statement.handlers:
                environment.clear()
                environment.update(before)
                if handler.name:
                    input_value(
                        handler.name,
                        binding_kind="exception",
                        occurrence=handler,
                    )
                for nested in handler.body:
                    reduce_statement(nested)
                handler_environments.append(dict(environment))

            continuing_handler_environments = [
                candidate
                for handler, candidate in zip(
                    body_statement.handlers,
                    handler_environments,
                )
                if not (
                    handler.body
                    and isinstance(
                        handler.body[-1],
                        (ast.Raise, ast.Return),
                    )
                )
            ]
            # ``else`` belongs exclusively to the successful body path.  It
            # must therefore see that body's lexical definitions *before* the
            # successful and handler environments merge for code after the
            # whole try.  Merging first can bind a body value to the enclosing
            # Try node; an else call consuming it then points back to the Try
            # which structurally owns that call, fabricating a cycle.
            environment.clear()
            environment.update(body_environment)
            for nested in body_statement.orelse:
                reduce_statement(nested)
            successful_environment = dict(environment)

            # Only control-flow paths that can reach the statement following
            # the try participate in its lexical-value merge.  A handler
            # ending in raise/return has no continuation edge and therefore
            # cannot turn values assigned by the successful body into
            # invented external inputs.
            environments = [
                successful_environment,
                *continuing_handler_environments,
            ]
            environment.clear()
            if environments:
                common_names = set.intersection(
                    *(set(candidate) for candidate in environments)
                )
                for name in common_names:
                    values = {
                        candidate[name] for candidate in environments
                    }
                    if len(values) == 1:
                        environment[name] = values.pop()
                    elif id(body_statement) in graph.G:
                        # The branches genuinely disagree (a body assignment
                        # vs. a handler's fallback) -- exactly the case
                        # ``ast.If`` resolves with a ``Phi``.  A Try node has
                        # no single test expression to point a Phi at, but it
                        # doesn't need one: this Try's own graph node already
                        # evaluates to "whichever arm actually ran" (see
                        # ``evaluate_node``'s ``ast.Try`` handling, which
                        # re-runs body/handlers and keeps the last value) --
                        # so binding the name straight to the Try node's own
                        # id gives every later reference the same on-demand
                        # resolution a Phi would, without inventing a second
                        # node or a synthetic "did-raise" boolean.
                        environment[name] = id(body_statement)
            for nested in body_statement.finalbody:
                reduce_statement(nested)
            return id(body_statement)
        if isinstance(body_statement, (ast.For, ast.While)):
            if isinstance(body_statement, ast.While):
                capture_loop_field_entries(body_statement)
            # A discarded bound-method result is an effectful body statement
            # unless a later lowering proves otherwise.  Record the actual
            # statement calls here; loop composition must not rediscover
            # state transitions from method-name lists or output reachability.
            def current_loop_walk(node: ast.AST):
                """Walk one loop body without stealing descendant-loop effects."""

                yield node
                if isinstance(node, (ast.For, ast.AsyncFor, ast.While)):
                    return
                for child in source_child_nodes(node):
                    yield from current_loop_walk(child)

            discarded_effect_calls = tuple(
                expression_statement.value
                for nested_statement in body_statement.body
                for expression_statement in current_loop_walk(
                    nested_statement
                )
                if (
                    isinstance(expression_statement, ast.Expr)
                    and isinstance(expression_statement.value, ast.Call)
                    and isinstance(
                        expression_statement.value.func,
                        ast.Attribute,
                    )
                    and isinstance(
                        expression_statement.value.func.value,
                        (ast.Name, ast.Attribute),
                    )
                )
            )
            # Mapping operations can both mutate and return a value.  Unlike
            # append/update used as bare statements, ``pop`` and
            # ``setdefault`` commonly occur inside an assignment or test.
            # Keep the original call identity so lowering must satisfy both
            # the state transition and its result.
            result_effect_calls = tuple(
                member
                for nested_statement in body_statement.body
                for member in current_loop_walk(nested_statement)
                if (
                    isinstance(member, ast.Call)
                    and isinstance(member.func, ast.Attribute)
                    and member.func.attr in {"pop", "setdefault"}
                    and isinstance(member.func.value, (ast.Name, ast.Attribute))
                )
            )
            state_effect_calls = tuple(dict.fromkeys((
                *discarded_effect_calls,
                *result_effect_calls,
            )))
            # Parameter bindings are materialized lazily at their first
            # lexical read, so a parameter first touched INSIDE the loop is
            # absent from the pre-loop snapshot -- and a name missing from
            # ``before_loop`` can never be discovered as loop-carried state.
            # That silently dropped the second carried value of an Adam-shaped
            # loop (``w`` was carried because a pre-loop statement had read
            # it; ``m`` was frozen at its entry value with no shortfall).  In
            # Python a parameter exists from function entry, so materializing
            # every parameter the loop reads BEFORE the snapshot is strictly
            # more faithful, and ``input_value`` is idempotent, so this mints
            # exactly the Input node the body's own first read would have.
            for read_name in _source_entry_names(body_statement):
                if (
                    read_name in parameter_names
                    and read_name not in environment
                    and read_name not in static_environment
                ):
                    input_value(read_name, binding_kind="parameter")
            if isinstance(body_statement, ast.For):
                iterator_value = resolve_expression(body_statement.iter)
                # Parameter/external bindings are materialized lazily at
                # their first lexical read.  Resolve the loop domain before
                # taking the initial-state snapshot so a value first read by
                # the iterator can still become explicit loop-carried state
                # when the body writes it.
                before_loop = dict(environment)
                bind_loop_target(body_statement.target)
                concord_iterated_target_class(
                    iterator_value, body_statement.target,
                )
                iterator_attributes = (
                    graph.G.nodes[int(iterator_value)].get("attributes") or {}
                    if isinstance(iterator_value, int)
                    and int(iterator_value) in graph.G else {}
                )
                iterator_page_cell = iterator_attributes.get(
                    "source_page_declaration_cell"
                )
                iterator_page_declaration = source_page_declaration(
                    iterator_page_cell
                )
                element_row_fields = (
                    tuple(iterator_page_declaration.row_fields)
                    if iterator_page_declaration is not None
                    else () if iterator_page_cell is not None else tuple(
                        iterator_attributes.get(
                            "sequence_element_row_fields", ()
                        )
                    )
                )
                if (
                    iterator_attributes.get(
                        "sequence_element_aggregate_kind"
                    ) == "tuple"
                    and element_row_fields
                    and isinstance(body_statement.target, ast.Name)
                ):
                    row_value = loop_target_bindings_by_ast.get(
                        id(body_statement.target)
                    )
                    if row_value is not None and row_value in graph.G:
                        graph.G.nodes[row_value].setdefault(
                            "attributes", {}
                        ).update({
                            "producer_kind": "page_row",
                            "aggregate_kind": "tuple",
                            "sequence_key_columns": (),
                            "sequence_column_count": len(element_row_fields),
                            "sequence_writable": False,
                            "source_page_declaration_cell": iterator_page_cell,
                        })
                # ``for key, row in mapping.items()`` carries the mapping's
                # declared value-record identity onto the exact row binding.
                # The mapping field annotation is the authority; neither the
                # loop variable's spelling nor a runtime sample is used.
                mapping_value_record, sequence_value_record = (
                    iterated_record_identities(iterator_value)
                )
                # ``IndexedStore`` publishes the mapping entry's ordered
                # key operands and stored value as one immutable source
                # aggregate fact.  Project that exact fact through
                # ``items()`` and the authored nested target positions.  A
                # semantic class therefore follows the same value/cell chain
                # as the mapping row; it is never reconstructed from the
                # target name or from the shared physical int64 dtype.
                mapping_layout = None
                mapping_layout_cell = None
                mapping_store_id = None
                pending_layout_values = (
                    [int(iterator_value)]
                    if isinstance(iterator_value, int) else []
                )
                visited_layout_values: set[int] = set()
                while pending_layout_values and mapping_layout is None:
                    candidate = pending_layout_values.pop()
                    if (
                        candidate in visited_layout_values
                        or candidate not in graph.G
                    ):
                        continue
                    visited_layout_values.add(candidate)
                    candidate_data = graph.G.nodes[candidate]
                    candidate_layout, candidate_layout_cell = (
                        source_aggregate_layout(int(candidate))
                    )
                    if (
                        candidate_data.get("type") == "IndexedStore"
                        and isinstance(
                            candidate_layout, _SourceAggregateLayout,
                        )
                        and candidate_layout.aggregate_kind == "dict"
                        and len(candidate_layout.members) >= 2
                    ):
                        mapping_layout = candidate_layout
                        mapping_layout_cell = candidate_layout_cell
                        mapping_store_id = int(candidate)
                        break
                    pending_layout_values.extend(
                        int(parent)
                        for parent, role in candidate_data.get("parents", ())
                        if str(role) in {
                            "operand", "value", "base", "object",
                            "receiver", "iterable",
                        }
                    )

                def concord_mapping_target_member(
                    target: ast.AST,
                    member: _SourceAggregateMember,
                    *projection_cells: _Ref | None,
                ) -> None:
                    if not isinstance(target, ast.Name):
                        return
                    target_value = loop_target_bindings_by_ast.get(id(target))
                    if target_value is None or target_value not in graph.G:
                        return
                    member_class_cell = current_identity_book().latest_ref(
                        _SOURCE_VALUE_CLASS,
                        (value_class_scope, int(member.value_id)),
                    )
                    if member_class_cell is None:
                        return
                    member_class = current_identity_book().page(
                        _SOURCE_VALUE_CLASS
                    ).cell(member_class_cell.row, member_class_cell.column)
                    if not (
                        isinstance(member_class, tuple)
                        and len(member_class) >= 2
                    ):
                        return
                    class_identity = str(member_class[0])
                    precision_limbs = int(member_class[1])
                    sources = tuple(dict.fromkeys(filter(None, (
                        member_class_cell,
                        mapping_layout_cell,
                        member.value_cell,
                        *member.source_cells,
                        node_identity_cell(graph, int(mapping_store_id)),
                        node_identity_cell(graph, int(iterator_value)),
                        node_identity_cell(graph, int(target_value)),
                        *projection_cells,
                    ))))
                    graph.G.nodes[int(target_value)].setdefault(
                        "attributes", {}
                    )["result_class_ref"] = class_identity
                    _concord_source_value_class(
                        value_class_scope,
                        int(target_value),
                        class_identity,
                        precision_limbs=precision_limbs,
                        source="mapping.items member projection",
                        provenance=_Derived(sources),
                    )

                if (
                    mapping_layout is not None
                    and isinstance(
                        body_statement.target, (ast.Tuple, ast.List),
                    )
                    and len(body_statement.target.elts) == 2
                ):
                    key_target, value_target = body_statement.target.elts
                    key_members = tuple(mapping_layout.members[:-1])
                    value_member = mapping_layout.members[-1]
                    outer_key_cell = aggregate_position_cell(
                        id(body_statement.target), "elts", 0,
                    )
                    outer_value_cell = aggregate_position_cell(
                        id(body_statement.target), "elts", 1,
                    )
                    if (
                        isinstance(key_target, (ast.Tuple, ast.List))
                        and len(key_target.elts) == len(key_members)
                    ):
                        for ordinal, (nested_target, key_member) in enumerate(
                            zip(key_target.elts, key_members)
                        ):
                            concord_mapping_target_member(
                                nested_target,
                                key_member,
                                outer_key_cell,
                                aggregate_position_cell(
                                    id(key_target), "elts", int(ordinal),
                                ),
                            )
                    elif len(key_members) == 1:
                        concord_mapping_target_member(
                            key_target, key_members[0], outer_key_cell,
                        )
                    concord_mapping_target_member(
                        value_target, value_member, outer_value_cell,
                    )
                if (
                    mapping_value_record is not None
                    and isinstance(body_statement.target, (ast.Tuple, ast.List))
                    and len(body_statement.target.elts) >= 2
                ):
                    row_target = body_statement.target.elts[1]
                    row_value = loop_target_bindings_by_ast.get(id(row_target))
                    if row_value is not None and row_value in graph.G:
                        graph.G.nodes[row_value].setdefault(
                            "attributes", {}
                        )["result_class_ref"] = str(mapping_value_record)
                if (
                    mapping_value_record is not None
                    and isinstance(body_statement.target, ast.Name)
                    and isinstance(body_statement.iter, ast.Call)
                    and isinstance(body_statement.iter.func, ast.Attribute)
                    and body_statement.iter.func.attr == "values"
                ):
                    # ``for row in mapping.values()`` projects the same
                    # declared value-record edge as the value member of
                    # ``mapping.items()``.  The annotated mapping node is the
                    # authority and the ``values`` call is the exact
                    # projection; the target spelling contributes no type
                    # information.
                    row_value = loop_target_bindings_by_ast.get(
                        id(body_statement.target)
                    )
                    if row_value is not None and row_value in graph.G:
                        graph.G.nodes[row_value].setdefault(
                            "attributes", {}
                        )["result_class_ref"] = str(mapping_value_record)
                if (
                    sequence_value_record is not None
                    and isinstance(body_statement.target, ast.Name)
                ):
                    row_value = loop_target_bindings_by_ast.get(
                        id(body_statement.target)
                    )
                    if row_value is not None and row_value in graph.G:
                        graph.G.nodes[row_value].setdefault(
                            "attributes", {}
                        )["result_class_ref"] = str(sequence_value_record)
            else:
                resolve_expression(body_statement.test)
                # The same ordering is essential for while loops: a parameter
                # first read by the predicate is the initial version consumed
                # by the header, not a name that appeared only after entry.
                # Snapshotting before this resolution silently lost genuine
                # body updates such as ``data = data[0] if data else []``.
                before_loop = dict(environment)
            before_loop_field_cells = dict(field_state_cursor)
            if not isinstance(body_statement, ast.While):
                capture_loop_field_entries(body_statement)
            loop_body_field_writes.append(frozenset(
                (str(target.value.id), str(target.attr))
                for nested in body_statement.body
                for member in source_walk(nested)
                for target in (
                    member.targets if isinstance(member, ast.Assign)
                    else (member.target,)
                    if isinstance(member, (ast.AugAssign, ast.AnnAssign))
                    else ()
                )
                if isinstance(target, ast.Attribute)
                and isinstance(target.value, ast.Name)
            ))
            loop_body_storing_receivers.append(frozenset(
                name
                for nested in body_statement.body
                for name in storing_call_names(nested)
            ))
            try:
                for nested in body_statement.body:
                    reduce_statement(nested)
            finally:
                loop_body_field_writes.pop()
                loop_body_storing_receivers.pop()
                carried_field_entries = loop_field_entry_values.pop()
            for nested in body_statement.orelse:
                reduce_statement(nested)
            loop_id = id(body_statement)
            # Loop exit (plan 70, section 1.3, decision held for the user):
            # the reducer merges no field state at a loop, so for every
            # field row the body moved, the post-loop state is recorded as
            # Unresolved(LOOP_EXIT_FIELD_STATE_UNMERGED) reading the
            # pre-loop cell, the body-exit cell and the loop construct cell,
            # instead of letting the body's last write stand as fact.
            loop_cell = (
                node_identity_cell(graph, loop_id) if loop_id in graph.G else None
            )
            carried_fields: dict[str, tuple[int, int]] = {}
            for field_key, exit_cell in tuple(field_state_cursor.items()):
                entry_cell = before_loop_field_cells.get(field_key)
                if entry_cell == exit_cell:
                    continue
                exit_state = field_state_at(exit_cell)
                entry = carried_field_entries.get(field_key)
                exit_value = (
                    _cell_node_id(exit_state.value)
                    if isinstance(exit_state, _FieldState) else None
                )
                if (
                    entry is not None
                    and exit_value is not None
                    and exit_value in graph.G
                    and loop_id in graph.G
                    and int(exit_value) != int(entry[1])
                ):
                    # The pre-loop and body-exit versions of a constructed
                    # record's field are a carried pair, like a rebound
                    # name: the loop's realization gives the header and exit
                    # their phi/port.  The post-loop state is LOOP_EXIT at
                    # the body-exit value, which that port continues.
                    binding = f"{entry[0]}.{field_key[1]}"
                    carried_fields[binding] = (int(entry[1]), int(exit_value))
                    read_cells = tuple(dict.fromkeys(
                        cell for cell in (entry_cell, exit_cell, loop_cell)
                        if cell is not None
                    ))
                    field_state_cursor[field_key] = field_state_book.post(
                        _REDUCER_FIELD_STATE, field_state_row(*field_key),
                        _FieldState(
                            _FieldStateKind.LOOP_EXIT,
                            node_identity_cell(graph, int(exit_value)),
                            node_identity_cell(graph, int(loop_id)),
                        ),
                        stage=_REDUCER_FIELD_MERGE,
                        provenance=_Derived(read_cells), mode=_Mode.REVISE,
                    )
                    continue
                # Normalizing ``field[i] = value`` retires the Assign
                # wrapper that the original For body edge named. The field
                # state still identifies the exact IndexedStore effect.
                # Join that effect (or a nested loop's recorded exit) to
                # this loop construct before publishing its unresolved
                # final VALUE. Otherwise even an after-loop read barrier
                # has no dependency path back to the writes it protects.
                body_state = field_state_at(exit_cell)
                body_effects = ()
                if isinstance(body_state, _FieldState) and body_state.kind is not _FieldStateKind.OBSERVED:
                    body_effects = (body_state.effect,)
                elif isinstance(body_state, _Unresolved) and body_state.reason == _LOOP_EXIT_FIELD_STATE_UNMERGED:
                    body_effects = tuple(cell for cell in body_state.read
                        if (effect_id := _cell_node_id(cell)) in graph.G
                        and isinstance(graph.G.nodes[effect_id].get('expr_obj'), (ast.For, ast.While)))
                for effect_cell in body_effects:
                    effect_id = _cell_node_id(effect_cell)
                    if effect_id in graph.G and loop_id in graph.G and effect_id != loop_id:
                        if (effect_id, 'body') not in (graph.G.nodes[loop_id].get('parents') or ()):
                            _append_operand(graph, loop_id, effect_id, 'body')
                read_cells = tuple(dict.fromkeys(
                    cell for cell in (entry_cell, exit_cell, loop_cell)
                    if cell is not None
                ))
                field_state_cursor[field_key] = field_state_book.post(
                    _REDUCER_FIELD_STATE, field_state_row(*field_key),
                    _Unresolved(_LOOP_EXIT_FIELD_STATE_UNMERGED, read_cells),
                    stage=_REDUCER_FIELD_MERGE,
                    provenance=_Derived(read_cells), mode=_Mode.REVISE,
                )
            if loop_id in graph.G:
                body_member_ids = {
                    id(member)
                    for nested in body_statement.body
                    for member in source_walk(nested)
                }
                direct_loop_target_names = (
                    set(loop_target_names(body_statement.target))
                    if isinstance(body_statement, ast.For)
                    else set()
                )
                # Read iteration inputs from the target AST identities that
                # ``bind_loop_target`` recorded, not from the post-body lexical
                # environment.  A body may legally reassign one tuple member
                # (``for op, av in rows: ...; op = replacement``); by this
                # point ``environment['op']`` denotes that later body value,
                # but the loop's row contract still has both ``op`` and ``av``.
                current_loop_bindings = {
                    target_name.id: loop_target_bindings_by_ast[id(target_name)]
                    for target_name in target_name_nodes(body_statement.target)
                    if (
                        id(target_name) in loop_target_bindings_by_ast
                        and before_loop.get(target_name.id)
                        != loop_target_bindings_by_ast[id(target_name)]
                    )
                } if isinstance(body_statement, ast.For) else {}
                # AST ingestion initially wires name occurrences before
                # lexical rebinding is known.  A reused spelling (for example
                # a comprehension's ``width`` followed by a ``for width``)
                # must not leave the second loop body attached to the first
                # binding.  Rewrite only nodes lexically owned by this body.
                for member_id in body_member_ids:
                    if member_id not in graph.G:
                        continue
                    parents = list(
                        graph.G.nodes[member_id].get("parents") or ()
                    )
                    replacements = {
                        old: current_loop_bindings[name]
                        for name in current_loop_bindings
                        for old in identity_bindings.get(name, ())
                        if old != current_loop_bindings[name]
                    }
                    rewritten = [
                        (replacements.get(parent, parent), role)
                        for parent, role in parents
                    ]
                    if rewritten != parents:
                        _replace_inputs(
                            graph,
                            member_id,
                            tuple(rewritten),
                        )
                loop_attributes = graph.G.nodes[loop_id].setdefault(
                    "attributes",
                    {},
                )
                loop_target_bindings = current_loop_bindings
                # A local assigned unconditionally from the current iteration
                # before its first read is not recurrence.  For example
                # ``for p in rows: op, av = p[0]`` gives ``op`` a new value on
                # every iteration; exporting it as a Phi asks the latch for a
                # producer even though the next iteration overwrites it before
                # use.  Preserve genuine state (including conditional writes)
                # by accepting only a direct body assignment reached before
                # any lexical load of the same name.
                overwritten_before_read: set[str] = set()
                candidate_names = before_loop.keys() & environment.keys()
                # A ``while`` test is evaluated before every iteration, so a
                # name it loads is read before any body write: ``go = ...``
                # in the body is the next iteration's test value, never a
                # dead overwrite (``while go: ...; go = second < limit``
                # otherwise re-tested the pre-loop ``go`` forever).
                test_loads = (
                    {
                        member.id
                        for member in source_walk(body_statement.test)
                        if isinstance(member, ast.Name)
                        and isinstance(member.ctx, ast.Load)
                    }
                    if isinstance(body_statement, ast.While) else set()
                )
                for name in candidate_names - test_loads:
                    for nested in body_statement.body:
                        loaded = any(
                            isinstance(member, ast.Name)
                            and isinstance(member.ctx, ast.Load)
                            and member.id == name
                            for member in source_walk(nested)
                        )
                        direct_targets: tuple[ast.AST, ...] = ()
                        if isinstance(nested, ast.Assign):
                            direct_targets = tuple(nested.targets)
                        elif isinstance(nested, ast.AnnAssign):
                            direct_targets = (nested.target,)
                        assigned = any(
                            target_name.id == name
                            for target in direct_targets
                            for target_name in target_name_nodes(target)
                        )
                        if assigned and not loaded:
                            overwritten_before_read.add(name)
                            break
                        if loaded:
                            break
                # Overwrite-before-read proves that a value is not a recurrent
                # body input; it does *not* prove that the pre-loop value is
                # dead. A later lexical load observes the initial value when
                # the loop executes zero times and the final body value
                # otherwise, so that name still requires a loop-result phi.
                # Restrict the scan to this function scope: a nested definition
                # captures a name under a separate invocation and is not a
                # continuation of this loop.
                def same_scope_walk(node: ast.AST):
                    yield node
                    for child in ast.iter_child_nodes(node):
                        if isinstance(child, (
                            ast.FunctionDef, ast.AsyncFunctionDef,
                            ast.ClassDef, ast.Lambda,
                        )):
                            continue
                        yield from same_scope_walk(child)

                loop_end = int(getattr(
                    body_statement, "end_lineno",
                    getattr(body_statement, "lineno", -1),
                ))
                live_after_loop = {
                    member.id
                    for member in same_scope_walk(statement)
                    if isinstance(member, ast.Name)
                    and isinstance(member.ctx, ast.Load)
                    and int(getattr(member, "lineno", -1)) > loop_end
                }
                loop_carried_bindings = {
                    name: (before_loop[name], environment[name])
                    for name in before_loop.keys() & environment.keys()
                    if (
                        before_loop[name] != environment[name]
                        and name not in loop_target_bindings
                        and (
                            name not in overwritten_before_read
                            or name in live_after_loop
                        )
                        # A descendant loop's induction binding remains in
                        # Python's lexical environment after that loop, but it
                        # is not recurrent state of this enclosing loop.  Its
                        # value is produced by the descendant loop domain, not
                        # by an enclosing-loop latch.  Treating it as carried
                        # creates a Phi whose backedge can never have a body
                        # producer (for example pad_cat_'s inner ``i, size``
                        # enumerate target leaking into the outer ``arr``
                        # loop).  This loop's OWN target is not a
                        # descendant's: ``j = -5; for i in range(10): j = i;
                        # if i * i > n: break`` then ``return j`` (scratch
                        # c125) dropped ``j`` and returned -5 on exhaustion.
                        and not (
                            environment[name] not in set(
                                loop_target_bindings.values()
                            )
                            and environment[name] in graph.G
                            and (
                                graph.G.nodes[environment[name]].get(
                                    "attributes"
                                ) or {}
                            ).get("binding_kind") == "loop"
                        )
                    )
                }
                # Program: ``i = -5; for i in range(10): if i * i > n:
                # break`` then ``return i`` (scratch c124).  Wrong record: the
                # loop's own target was excluded from the carried bindings, so
                # a post-loop read resolved to the pre-loop -5 (also at the
                # session base).  Rule: after a ``for`` loop its target holds
                # the element of the last iteration that ran -- the break
                # site's on a break, the final one on exhaustion, the
                # pre-loop value on zero trips.  A target read after the loop
                # with a pre-loop value is therefore carried: (pre-loop value,
                # this iteration's element).
                for name, target_value in dict(loop_target_bindings).items():
                    if (
                        name in live_after_loop
                        and name in before_loop
                        and isinstance(target_value, int)
                        and not isinstance(target_value, bool)
                        and int(before_loop[name]) != int(target_value)
                        and int(target_value) in graph.G
                    ):
                        loop_carried_bindings[name] = (
                            int(before_loop[name]), int(target_value),
                        )
                # A terminal ``continue`` arm does not reach the conditional's
                # ordinary fallthrough environment, by design.  Its bindings
                # nevertheless reach the loop latch and are therefore genuine
                # recurrence.  The control-site ledger captured that exact
                # environment when the Continue statement was reduced.  Use it
                # when every continue edge agrees on one updated identity; if
                # different edges carry different values, a latch Phi must be
                # constructed explicitly and this source-level pass must not
                # guess which value wins.
                loop_start = int(getattr(body_statement, "lineno", -1))
                continue_sites = tuple(
                    site
                    for site_span, site in (
                        graph.G.graph.get("loop_control_site_bindings") or {}
                    ).items()
                    if (
                        site.get("loop_id") is None
                        and site.get("action") == "continue"
                        and loop_start <= int(site_span[0]) <= loop_end
                    )
                )
                for name, initial in before_loop.items():
                    if name in loop_carried_bindings or not continue_sites:
                        continue
                    continuation_values = {
                        int(site.get("bindings", {}).get(name, initial))
                        for site in continue_sites
                    }
                    if (
                        len(continuation_values) == 1
                        and next(iter(continuation_values)) != int(initial)
                    ):
                        loop_carried_bindings[name] = (
                            int(initial), next(iter(continuation_values)),
                        )
                for binding, pair in carried_fields.items():
                    loop_carried_bindings.setdefault(binding, pair)
                loop_attributes["loop_carried_bindings"] = (
                    loop_carried_bindings
                )
                # Claim this loop's break/continue sites (a nested loop has
                # already claimed its own).  For each ``break`` site, every
                # name whose value at the site differs from its pre-loop
                # value reaches the loop exit through that edge, keyed by the
                # pre-loop identity so the exit merge can pair it with the
                # carried (or zero-trip) value.  A name bound ONLY on break
                # paths is not loop-carried (the fall-through path never
                # rebinds it) yet still needs a post-loop identity: its
                # continuation is the last break site's value, which the loop
                # port materialization rewires onto a LoopResult port.
                loop_break_sites: dict[
                    tuple[int, int, int, int], dict[tuple[int, int], int]
                ] = {}
                loop_break_bindings: dict[str, tuple[int, int]] = {}
                for site_span, site in (
                    graph.G.graph.get("loop_control_site_bindings") or {}
                ).items():
                    if (
                        site.get("loop_id") is not None
                        or not (loop_start <= int(site_span[0]) <= loop_end)
                    ):
                        continue
                    site["loop_id"] = loop_id
                    # A ``continue`` edge carries its site's bindings to the
                    # latch exactly as a ``break`` carries them to the exit:
                    # record them and make the site node consume them.  Only
                    # a break creates post-loop break bindings.  (Found by
                    # ``if dt > 0.2: dt = dt * 0.5; continue``: unrecorded,
                    # the continue value had no consumer but a conditional
                    # merge synthesized from ``dt``'s identity history.)
                    is_break = site["action"] == "break"
                    site_values: dict[tuple[int, int], int] = {}
                    for name, value in site["bindings"].items():
                        if (
                            name in loop_target_bindings
                            and name not in loop_carried_bindings
                        ):
                            continue
                        initial = before_loop.get(name)
                        if (
                            initial is None
                            and name in parameter_names
                            and name not in static_environment
                        ):
                            initial = input_value(name, binding_kind="parameter")
                        if (
                            initial is None
                            or (int(initial) == int(value) and name not in loop_carried_bindings)
                            or int(initial) not in graph.G
                            or int(value) not in graph.G
                        ):
                            continue
                        # ``child += 1; if ...: break; position = child``:
                        # child's updated value already dominates the break,
                        # but position has not been assigned. Omitting its
                        # unchanged site value let exit lowering take child's
                        # value through position's future update identity.
                        # Record every carried binding's exact site state,
                        # including an unchanged header generation.
                        # The binding's key is its carried pair: two names
                        # seeded from one pre-loop value (``tried = dt``)
                        # share ``initial`` yet are distinct bindings with
                        # distinct updates and distinct values at a site.
                        carried_pair = loop_carried_bindings.get(name)
                        site_values[
                            (int(carried_pair[0]), int(carried_pair[1]))
                            if carried_pair is not None
                            else (int(initial), int(initial))
                        ] = int(value)
                        if is_break and name not in loop_carried_bindings:
                            loop_break_bindings[name] = (int(initial), int(value))
                    loop_break_sites[site_span] = site_values
                    # The break edge CONSUMES these values (the loop-exit
                    # merge reads them), so the Break node records them as
                    # its inputs.  Without that edge a pre-loop parameter
                    # whose only later reader is the exit merge has no
                    # consumer yet and the planner prunes it as an unused
                    # parameter before the merge exists.
                    site_node_id = site.get("node_id")
                    if site_values and site_node_id in graph.G:
                        _replace_inputs(
                            graph,
                            site_node_id,
                            (
                                *(
                                    (int(initial), "site_initial")
                                    for initial in dict.fromkeys(
                                        key[0] for key in site_values
                                    )
                                ),
                                *(
                                    (int(value), "site_value")
                                    for value in site_values.values()
                                ),
                            ),
                        )
                loop_attributes["loop_break_sites"] = loop_break_sites
                loop_attributes["loop_break_bindings"] = loop_break_bindings
                # The loop READS each carried update through its backedge and
                # each break continuation through its exit.  Those reads are
                # graph edges into the loop node, so every dataflow walk
                # (liveness, dead-call pruning, the collection after loop
                # evaporation) sees them -- a value read only by the loop is
                # not dead.  Without them ``dt_cap``'s last update in the
                # woodshop ``run_superstep`` had out-degree zero and was
                # deleted twice by two different pruners.  Updates are never
                # descendants of their loop (its only children are its
                # result ports), so these edges close no cycle.
                ledger_reads = [
                    (int(updated), "carried_update")
                    for initial, updated in loop_carried_bindings.values()
                    if int(updated) != int(initial)
                ] + [
                    (int(continuation), "break_value")
                    for _initial, continuation in loop_break_bindings.values()
                ]
                for value_id, role in ledger_reads:
                    if value_id not in graph.G or value_id == loop_id:
                        continue
                    if not graph.G.has_edge(value_id, loop_id):
                        graph.G.add_edge(value_id, loop_id, role=role)
                    children = graph.G.nodes[value_id].setdefault(
                        "children", []
                    )
                    if (loop_id, role) not in children:
                        children.append((loop_id, role))
                    _append_operand(graph, loop_id, value_id, role)
                for name, (_initial, continuation) in loop_break_bindings.items():
                    environment[name] = continuation
                loop_attributes["loop_target_bindings"] = (
                    loop_target_bindings
                )
                # A target's pre-loop value is dead setup (the planner's
                # ``loop_target_initializer`` rule) only while the loop
                # overwrites it unread.  A target carried past the loop reads
                # it as the zero-trip value: scratch c124 ``i = -5`` was
                # classified dispatch metadata, never lowered, and the header
                # Phi's entry operand became a minted root formal (value 3).
                loop_attributes["loop_target_initials"] = {
                    name: before_loop[name]
                    for name in loop_target_bindings
                    if name in before_loop
                    and name not in loop_carried_bindings
                }
                # This pass resolves source/value identities only.  It records
                # the body value selected by the lexical continuation, but it
                # must not manufacture a loop latch, exit, collection owner,
                # or backend schedule.  The post-canonical loop reducer will
                # either thread these values through straight-line unrolled
                # SSA or create retained-loop result ports.
                for name, (_initial, updated) in (
                    loop_carried_bindings.items()
                ):
                    environment[name] = updated
                    identity_bindings.setdefault(name, []).append(updated)
                    post_name_binding(
                        name, int(updated), authored=False,
                        span_positions=(None,) * 4, context_sha256="",
                        cells=(),
                    )
                # A discarded bound-method call is retained here only as a
                # source effect fact.  Its Python return value is not the
                # mutated state, and no synthetic state transition belongs in
                # the critical value graph before loop realization is known.
                state_effects = []
                for call in state_effect_calls:
                    receiver_expression = call.func.value
                    name = ast.unparse(receiver_expression)
                    # A parameter first referenced inside this loop is resolved
                    # while reducing the body, after ``before_loop`` was
                    # snapped.  Keep that real input as an opaque effect unless
                    # its storage provenance proves a sequence policy; never
                    # let the mutation disappear merely because its first use
                    # is nested here.
                    call_id = id(call)
                    call_parents = tuple(
                        graph.G.nodes[call_id].get("parents") or ()
                    ) if call_id in graph.G else ()
                    operand = next((
                        int(parent)
                        for parent, role in call_parents
                        if str(role) == "operand"
                    ), None)
                    initial = (
                        before_loop.get(name, environment.get(name))
                        if isinstance(receiver_expression, ast.Name)
                        else operand
                    )
                    if (
                        initial is None
                        or initial not in graph.G
                        or call_id not in graph.G
                        or name in loop_carried_bindings
                    ):
                        continue
                    call_attributes = (
                        graph.G.nodes[call_id].get("attributes") or {}
                    )
                    # A source-linked method is already an ordinary SSA call:
                    # its method_ref selects the complete function-table body,
                    # and its receiver is the explicit ``operand`` input.  It
                    # is not a second, opaque mutation of that receiver.  The
                    # callee's own GetAttr/SetAttr and calls carry its effects.
                    if any(
                        call_attributes.get(key) is not None
                        for key in (
                            "method_ref", "callee_ref", "resolved_ast_parent",
                        )
                    ):
                        continue
                    argument_ids = _sequence_mutation_argument_ids(
                        str(call.func.attr), call_parents,
                    )
                    if isinstance(receiver_expression, ast.Name):
                        environment[name] = initial
                    argument_expression = (
                        call.args[0] if len(call.args) == 1 else None
                    )
                    state_attributes = (
                        graph.G.nodes[initial].get("attributes") or {}
                    )
                    aggregate_kind = state_attributes.get("aggregate_kind")

                    sequence_policy = (
                        "unique"
                        if aggregate_kind in {"set", "dict"}
                        else (
                            "duplicates"
                            if aggregate_kind in {
                                "list", "tuple", "bytes", "bytearray", "array"
                            }
                            else None
                        )
                    )
                    sequence_mutation = (
                        sequence_policy is not None
                        and call.func.attr in _SEQUENCE_MUTATION_OPERATORS
                        and not (
                            aggregate_kind == "dict"
                            and call.func.attr == "pop"
                        )
                        and not (
                            aggregate_kind in {"tuple", "bytes"}
                            or not state_attributes.get(
                                "sequence_writable", True
                            )
                        )
                    )
                    mapping_mutation = (
                        aggregate_kind == "dict"
                        and call.func.attr in _MAPPING_MUTATION_OPERATORS
                        and state_attributes.get("sequence_writable", True)
                    )
                    if sequence_mutation or mapping_mutation:
                        from ...compiler.concordance_declarations import (
                            SOURCE_SEQUENCE_MUTATION,
                        )
                        mutation_page = current_identity_book().page(
                            SOURCE_SEQUENCE_MUTATION
                        )
                        mutation_row = (value_class_scope, int(call_id))
                        mutation_fact = (
                            int(initial), str(call.func.attr),
                            str(sequence_policy), tuple(argument_ids),
                            "mapping" if mapping_mutation else "sequence",
                        )
                        incumbent = mutation_page.latest(mutation_row)
                        if (
                            incumbent is not None
                            and tuple(incumbent) != mutation_fact
                        ):
                            raise ValueError(
                                "source sequence mutation concordance "
                                f"disagreement for {mutation_row!r}: "
                                f"recorded={incumbent!r}, "
                                f"proposed={mutation_fact!r}"
                            )
                        if incumbent is None:
                            mutation_sources = [
                                node_identity_cell(graph, int(call_id)),
                                node_identity_cell(graph, int(initial)),
                            ]
                            mutation_sources.extend(
                                node_identity_cell(graph, int(argument_id))
                                for argument_id in argument_ids
                                if int(argument_id) in graph.G
                            )
                            current_identity_book().post(
                                SOURCE_SEQUENCE_MUTATION,
                                mutation_row, mutation_fact,
                                stage=_REDUCTION,
                                provenance=_Derived(tuple(dict.fromkeys(
                                    mutation_sources
                                ))),
                                mode=_Mode.CONCORD,
                            )
                    state_effects.append({
                        "state_name": name,
                        "operator": call.func.attr,
                        "effect_mode": (
                            "sequence_mutation"
                            if sequence_mutation
                            else (
                                "mapping_mutation"
                                if mapping_mutation else "opaque"
                            )
                        ),
                        "sequence_policy": sequence_policy,
                        "argument_kind": (
                            "generator"
                            if isinstance(argument_expression, ast.GeneratorExp)
                            else (
                                (
                                    "filtered_sequence"
                                    if any(
                                        generator.ifs
                                        for generator in argument_expression.generators
                                    )
                                    else "sequence"
                                )
                                if isinstance(argument_expression, ast.ListComp)
                                else "value"
                            )
                        ),
                        "state_input_id": int(initial),
                        "effect_node_id": int(call_id),
                        "argument_value_ids": argument_ids,
                    })
                if state_effects:
                    loop_attributes["loop_state_effects"] = tuple(
                        state_effects
                    )
            return id(body_statement)
        if isinstance(body_statement, (ast.Break, ast.Continue)):
            # A loop-control site leaves its arm with the arm's OWN bindings
            # (``if c: dt_try = ...; break`` reaches the loop exit with that
            # dt_try).  The ``if`` merge below deliberately drops a terminal
            # arm's bindings from the fall-through environment, so the exit
            # edge must carry them explicitly.  Record the environment at the
            # site, keyed by source span (AST ids do not survive reduction);
            # the enclosing loop claims the site when it finishes reducing.
            graph.G.graph.setdefault("loop_control_site_bindings", {})[(
                int(getattr(body_statement, "lineno", -1)),
                int(getattr(body_statement, "col_offset", -1)),
                int(getattr(body_statement, "end_lineno", -1)),
                int(getattr(body_statement, "end_col_offset", -1)),
            )] = {
                "action": (
                    "break" if isinstance(body_statement, ast.Break)
                    else "continue"
                ),
                "bindings": {
                    str(name): int(value)
                    for name, value in environment.items()
                    if isinstance(value, int) and not isinstance(value, bool)
                },
                "loop_id": None,
                "node_id": id(body_statement),
            }
            return id(body_statement) if id(body_statement) in graph.G else None
        if isinstance(body_statement, ast.Expr):
            return resolve_expression(body_statement.value)
        for child in source_child_nodes(body_statement):
            if isinstance(child, ast.expr):
                resolve_expression(child)
        return id(body_statement) if id(body_statement) in graph.G else None

    def post_return_output_arms() -> None:
        """Mint the ONE output of a function whose returns disagree on arity
        and post its ``return_output_arms`` row.

        ``IdentityPage._resolved`` (``return None`` / ``return row, column``
        in ``while True``): the wrong record was one Phi layout per return.
        Rule now holding: one output Phi, one member Phi per position
        ``k < width`` whose parents are the slot-``k`` values of the arms
        longer than ``k``; the aggregate layout is SOURCE_AGGREGATE_LAYOUT on
        the output; the row derives from every arm's container cell, slot
        cells and the output's cell (slot values are never copied).  A
        VARIADIC record is posted and NOT lowered further in this pass
        (stage 5 is deferred): downstream behaviour for it is unchanged.
        """

        nonlocal return_arms_kind
        from ...compiler.structural_concordance import source_structure

        if not return_arm_posts:
            return
        book = current_identity_book()
        container_cells = tuple(
            container for _site, container, _slots, _absent in return_arm_posts
        )
        all_slot_cells = tuple(
            cell for _site, _container, slots, _absent in return_arm_posts
            for cell in slots
        )
        slot_values_by_arm = []
        slot_cells_by_arm = []
        structural_cells = []
        has_structural_arm = False
        for _site, _container, slots, absent in return_arm_posts:
            values = []
            member_cells = []
            for cell in slots:
                value = _cell_node_id(_cell_fact(book, cell))
                layout, _layout_cell = (
                    (None, None) if value is None else source_aggregate_layout(value)
                )
                if layout is not None and layout.aggregate_kind == "tuple":
                    structure, structure_cell = source_structure(value_class_scope, value, book=book)
                    leaves = structure.leaves()
                    values.extend(leaf.value_id for _path, leaf in leaves)
                    member_cells.extend(leaf.source for _path, leaf in leaves)
                    structural_cells.append(structure_cell)
                    has_structural_arm = True
                else:
                    values.append(value)
                    member_cells.append(cell)
            slot_values_by_arm.append(tuple(values))
            slot_cells_by_arm.append(tuple(member_cells))
        if return_arms_kind is None and has_structural_arm:
            present_lengths = {
                len(values) for values, post in zip(slot_values_by_arm, return_arm_posts)
                if not post[3]
            }
            if (any(post[3] for post in return_arm_posts)
                    and len(present_lengths) == 1 and min(present_lengths) >= 1):
                return_arms_kind = _ReturnArmsKind.OPTIONAL_AGGREGATE
                graph.G.graph["function_outputs"] = ("result_0",)
                graph.G.graph["positional_output_names"] = ("result_0",)
        if return_arms_kind is None and not return_arms_unclassified:
            return
        if return_arms_kind is None or any(
            value is None for values in slot_values_by_arm for value in values
        ):
            # Unclassified (or an Unresolved slot row): no output is minted;
            # the row is keyed by the first site's node id.
            key = _cell_node_id(return_arm_posts[0][0])
            if key is not None:
                book.post(
                    _RETURN_OUTPUT_ARMS, (ingestion_read_scope, int(key)),
                    _Unresolved(_RETURN_ARMS_UNCLASSIFIED, container_cells),
                    stage=_REDUCER_RETURN,
                    provenance=_Derived(container_cells),
                    mode=_Mode.CONCORD,
                )
            return
        arms = []
        for (site, container, slots, absent), values in zip(
            return_arm_posts, slot_values_by_arm
        ):
            arms.append(_ReturnArm(
                site, container, 0 if absent else len(values), bool(absent),
                site in return_tail_sites,
            ))
        width = max(arm.length for arm in arms)
        derived = tuple(dict.fromkeys((*container_cells, *all_slot_cells, *structural_cells)))
        output_id = new_node(
            "Phi", "return output", source_cell=derived,
            attributes={"producer_kind": "aggregate_phi",
                        "aggregate_kind": "tuple"},
        )
        members = []
        for position in range(width):
            arm_slots = tuple(
                (arm_index, slot_cells_by_arm[arm_index][position],
                 slot_values_by_arm[arm_index][position])
                for arm_index, arm in enumerate(arms)
                if arm.length > position
            )
            slot_cells_here = tuple(cell for _arm, cell, _value in arm_slots)
            member_id = new_node(
                "Phi", f"return output member {position}",
                attributes={
                    "aggregate_parent_value_id": int(output_id),
                    "aggregate_index": int(position),
                },
                parents=tuple(
                    (int(value), f"return_arm_{arm_index}")
                    for arm_index, _cell, value in arm_slots
                ),
                source_cell=tuple(dict.fromkeys(
                    (*slot_cells_here, node_identity_cell(graph, int(output_id)))
                )),
            )
            members.append(_SourceAggregateMember(
                int(member_id), node_identity_cell(graph, int(member_id)),
                slot_cells_here,
            ))
        graph.G.nodes[int(output_id)]["attributes"][
            "aggregate_leaf_value_ids"
        ] = tuple(member.value_id for member in members)
        post_source_aggregate_layout(
            int(output_id), "tuple", tuple(members),
        )
        output_cell = node_identity_cell(graph, int(output_id))
        arms_cell = book.post(
            _RETURN_OUTPUT_ARMS, (ingestion_read_scope, int(output_id)),
            _ReturnOutputArms(
                return_arms_kind, tuple(arms), int(width),
                tuple(member.value_cell for member in members),
            ),
            stage=_REDUCER_RETURN,
            provenance=_Derived((*derived, output_cell)),
            mode=_Mode.CONCORD,
        )
        # Program shape: returns of different arity are the arms of ONE
        # output ``result_0``.  Wrong record: the physical Ret slots (the
        # member Phis) standing for the output.  Rule: the semantic output is
        # the aggregate root, derived from its cell and the arms row.
        book.post(
            _SEMANTIC_OUTPUT, (ingestion_read_scope, 0),
            ("result_0", int(output_id)),
            stage=_REDUCER_RETURN,
            provenance=_Derived((output_cell, arms_cell)),
            mode=_Mode.CONCORD,
        )
        identity_bindings.setdefault("result_0", []).append(int(output_id))
        post_name_binding(
            "result_0", int(output_id), authored=False,
            span_positions=(None,) * 4, context_sha256="", cells=(),
        )

    returned_values = []
    for body_statement in statement.body:
        value = reduce_statement(body_statement)
        if isinstance(body_statement, ast.Return) and value is not None:
            returned_values.append(value)
    post_return_output_arms()
    if return_arms_kind is None:
        # Program shape: one arity across every return; slot ``k`` is named
        # ``function_outputs[k]`` and its binding history ends at the value
        # the function returns for it.  Wrong record: leaving the order to
        # structural recovery's own list.  Rule: the reducer fixes the
        # output position -> (name, value) here, from the binding it just
        # completed, DERIVED from that value's node cell.
        semantic_book = current_identity_book()
        for position, output_name in enumerate(
            tuple(graph.G.graph.get("function_outputs") or ())
        ):
            bound = identity_bindings.get(str(output_name))
            if not bound or int(bound[-1]) not in graph.G:
                continue
            semantic_book.post(
                _SEMANTIC_OUTPUT, (ingestion_read_scope, int(position)),
                (str(output_name), int(bound[-1])),
                stage=_REDUCER_RETURN,
                provenance=_Derived((node_identity_cell(graph, int(bound[-1])),)),
                mode=_Mode.CONCORD,
            )
    if returned_values:
        graph.roots = list(dict.fromkeys(returned_values))
        # The function's return is a consumer of its roots: row
        # ``(scope, "return", "root", position)`` names the binding returned
        # there, when every return of that value names one binding.
        for position, root in enumerate(graph.roots):
            names = return_root_bindings.get(int(root)) if isinstance(root, int) else None
            if names and len(names) == 1:
                return_row = (
                    ingestion_read_scope, "return", "root", position,
                )
                # The returned binding is read at the root node: DERIVED
                # from the root's identity cell; a root no longer in the
                # graph stands on the span cells of the ``Name``
                # occurrences that returned it.
                name, occurrences = next(iter(names.items()))
                root_cells = (
                    (node_identity_cell(graph, root),) if root in graph.G
                    else tuple(
                        _post_source_span(occurrence)
                        for occurrence in occurrences
                    )
                )
                current_identity_book().post(
                    _LEXICAL_READ_BINDING, return_row, name,
                    stage=_REDUCTION,
                    provenance=_Derived(_source_cells(root_cells)),
                    mode=_Mode.CONCORD,
                )

    # A source-linked unbound method can arrive with its receiver absent from
    # the owned subgraph even though the Attribute load itself is owned.
    # Restore the ordinary edge before lexical Name cleanup; an Attribute
    # without its receiver is not a valid structural operation. The receiver
    # can be a parameter (``self`` bound directly at the call boundary) or an
    # ordinary local (``machine = load_pe(...)``) -- both are recorded under
    # the same name in ``environment`` by ``bind_target``, so there is no
    # reason to restore only the parameter case and leave a local's receiver
    # permanently unresolved. A chained access (``machine.runner.tick``) puts
    # an Attribute (``machine.runner``), not a Name, in the receiver position
    # of the outer Attribute (``.tick``); that inner Attribute is itself just
    # another node this same loop repairs on its own matching iteration, so
    # linking straight to its node id (when it is still a live node) is
    # enough -- the two repairs do not need to happen in any particular
    # order, since neither removes a node, only reattaches an edge.
    for node_id, data in list(graph.G.nodes(data=True)):
        expression = data.get("expr_obj")
        if not (
            isinstance(expression, ast.Attribute)
            and not data.get("parents")
            and isinstance(expression.value, (ast.Name, ast.Attribute))
        ):
            continue
        if isinstance(expression.value, ast.Name):
            receiver = environment.get(expression.value.id)
            if receiver is None:
                # The free name is read by this receiver occurrence: the
                # Input stands for that read.
                receiver = input_value(
                    expression.value.id,
                    binding_kind=(
                        "parameter"
                        if expression.value.id in parameter_names
                        else "local"
                    ),
                    occurrence=expression.value,
                )
        else:
            inner_id = id(expression.value)
            if inner_id not in graph.G:
                continue
            receiver = inner_id
        _replace_inputs(graph, node_id, ((receiver, "value"),))

    # Any surviving lexical occurrence is either unused syntax or an unresolved
    # source label.  It is not executable work in the reduced value graph --
    # but only when nothing still structurally depends on it. A Name node
    # that still has a real successor (an Attribute load whose receiver is
    # this exact node, say) is not unused syntax; removing it anyway does
    # not erase that dependency, it just strips the successor's own record
    # of it, leaving that successor orphaned for whatever later pass expects
    # to find its receiver -- the exact "receiver Name absent" case the
    # repair above this loop exists to patch after the fact. Checking
    # liveness first means there is nothing left to repair.
    for node_id, data in list(graph.G.nodes(data=True)):
        expression = data.get("expr_obj")
        if isinstance(expression, ast.Name):
            if graph.G.out_degree(node_id) > 0:
                continue
            _remove_node(graph, node_id)
            continue
        if (
            data.get("type") == "Input"
            and graph.G.out_degree(node_id) == 0
            and node_id not in graph.roots
            and (data.get("attributes") or {}).get("binding_kind")
            == "external"
        ):
            # A named Call target initially looks like a lexical external.
            # Once the Call owns a function-table reference, that temporary
            # value has no consumers and must not leak into the public input
            # contract.
            _remove_node(graph, node_id)
            continue
        if (
            data.get("type") == "StaticReference"
            and graph.G.out_degree(node_id) == 0
            and node_id not in graph.roots
            and (data.get("attributes") or {}).get("reference_kind")
            == "function_subgraph"
        ):
            # Resolving a direct named call first encounters the callee as a
            # possible first-class value.  Once the Call has recorded its
            # exact ``callee_ref``, that temporary token has no runtime role:
            # the referenced source body lives in FunctionTable and the Call
            # invokes its compiled slot.  Keep a function reference whenever
            # it is returned or consumed as data; remove only this genuinely
            # disconnected compiler token so it cannot be scheduled as an
            # operator of its own.
            _remove_node(graph, node_id)

    # A compile-time reference left as a root is one nothing consumes at
    # runtime. Whether that is correct depends entirely on whether it is
    # IRREDUCIBLE: pursue into whatever is demanded, and terminate only at
    # content that cannot be reduced further -- never drop something that still
    # has source to pursue.
    #
    #  * Irreducible (a module/builtin/C-extension used only at compile time,
    #    e.g. ``torch`` in ``isinstance(x, torch.Tensor)``): no readable source,
    #    no runtime value. It is a terminal external, not a runtime output, so
    #    drop it from the roots (and remove its node if present).
    #  * Pursuable (a function/class whose source we CAN read): reaching
    #    reduction as an unconsumed root means the pursuit
    #    (``_expand_unresolved_ast_parents``) did not follow it. Dropping that
    #    would silently delete real content, so SURFACE it instead of hiding it.
    #
    # Done before the invariant scan so the scan sees the cleaned graph. A
    # compile-time reference is never a runtime PARENT (that would be a genuine
    # bug), so those remain hard invariants below.
    compile_time_roots = [root for root in graph.roots if type(root) is not int]
    if compile_time_roots:
        pursuable_roots = [
            root for root in compile_time_roots
            if _reference_has_pursuable_source(getattr(root, "value", root))
        ]
        if pursuable_roots:
            raise ValueError(
                "demanded reference(s) reached reduction unresolved but still "
                "have source to pursue -- the frontend pursuit did not follow "
                f"them into their content: {pursuable_roots!r}"
            )
        graph.roots = [root for root in graph.roots if type(root) is int]
        for root in compile_time_roots:
            if root in graph.G:
                _remove_node(graph, root)

    # Stable topological relabeling turns structural token chains into compact
    # dense value IDs without allowing opaque Python object identities to
    # participate in the ordering.
    invalid_node_ids = [
        node_id for node_id in graph.G if type(node_id) is not int
    ]
    invalid_parent_ids = [
        parent_id
        for _node_id, data in graph.G.nodes(data=True)
        for parent_id, _role in data.get("parents", ())
        if type(parent_id) is not int
    ]
    assert not invalid_node_ids, (
        "compile-time references must be represented by integer-keyed "
        f"StaticReference nodes, not graph keys: {invalid_node_ids!r}"
    )
    assert not invalid_parent_ids, (
        "compile-time references must not appear as runtime parent IDs: "
        f"{invalid_parent_ids!r}"
    )
    def stable_token_atom(value: Any) -> str:
        if isinstance(value, str):
            address_repr = re.fullmatch(
                r"<([A-Za-z_][A-Za-z_0-9.]*) object at 0x[0-9A-Fa-f]+>",
                value,
            )
            return (
                address_repr.group(1)
                if address_repr is not None else value
            )
        if value is None or isinstance(value, (bool, float, int)):
            return str(value)
        enum_value = getattr(value, "value", None)
        if isinstance(enum_value, (bool, float, int, str)):
            return str(enum_value)
        value_type = type(value)
        return f"{value_type.__module__}.{value_type.__qualname__}"

    def node_description(node_id: int) -> dict[str, Any]:
        data = graph.G.nodes[node_id]
        expression = data.get("expr_obj")
        source_glyph_occurrence = (
            data.get("attributes") or {}
        ).get("source_glyph_occurrence")
        return {
            "source_span": {
                "line": getattr(expression, "lineno", -1),
                "column": getattr(expression, "col_offset", -1),
                "end_line": getattr(expression, "end_lineno", -1),
                "end_column": getattr(expression, "end_col_offset", -1),
            },
            "ast": (
                ast.dump(expression, include_attributes=False)
                if isinstance(expression, ast.AST) else type(expression).__name__
            ),
            "type": stable_token_atom(data.get("type", "")),
            "op": stable_token_atom(data.get("op", "")),
            "label": stable_token_atom(data.get("label", "")),
            "source_glyph_occurrence": (
                tuple(stable_token_atom(part) for part in source_glyph_occurrence)
                if source_glyph_occurrence is not None else ()
            ),
        }

    base_token_chains: dict[int, tuple[str, ...]] = {}
    for node_id, data in graph.G.nodes(data=True):
        expression = data.get("expr_obj")
        line = getattr(expression, "lineno", -1)
        column = getattr(expression, "col_offset", -1)
        end_line = getattr(expression, "end_lineno", -1)
        end_column = getattr(expression, "end_col_offset", -1)
        missing_position = 10**12
        ordering_prefix = (
            "priority:0" if str(data.get("type", "")) == "Input" else "priority:1",
            f"line:{line if line >= 0 else missing_position:012d}",
            f"column:{column if column >= 0 else missing_position:012d}",
            f"end_line:{end_line if end_line >= 0 else missing_position:012d}",
            f"end_column:{end_column if end_column >= 0 else missing_position:012d}",
        )
        parent_context = tuple(
            {
                "role": str(role),
                "node": node_description(parent_id),
            }
            for parent_id, role in data.get("parents", ())
            if parent_id in graph.G
        )
        base_token_chains[node_id] = (
            *ordering_prefix,
            *structural_context_tokens({
                "node": node_description(node_id),
                "parents": parent_context,
            }),
        )
    chain_versions: dict[tuple[str, ...], int] = {}
    node_token_chains: dict[int, tuple[str, ...]] = {}
    for node_id in graph.G.nodes:
        chain = base_token_chains[node_id]
        version = chain_versions.get(chain, 0)
        chain_versions[chain] = version + 1
        node_token_chains[node_id] = (*chain, f"version:{version}")
    ordered = list(
        lexicographical_topological_order(
            graph.G, key=lambda node_id: node_token_chains[node_id]
        )
    )
    mapping = {
        node_id: value_id for value_id, node_id in enumerate(ordered)
    }
    # Canonical relabeling changes identities, so it necessarily builds a new
    # topology. ``materialize_memory`` defers later layout products; it does
    # not select the ProcessGraph topology implementation. Keep the relabeled
    # authority in the same AbstractTensor memory-graph substrate in both
    # modes instead of reopening the historical NetworkX storage bypass.
    from ...transmogrifier.graph.memory_graph import BitTensorMemoryGraph

    ordered_memory_graph = BitTensorMemoryGraph(size=0)
    ordered_graph = ordered_memory_graph.G
    ordered_graph.graph.update(graph.G.graph)
    ordered_graph.graph["canonical_value_ids"] = True
    # Renumbering changes the id space; a watermark from the AST-id
    # ingestion graph must not leak into canonical allocation.  Seed a new
    # watermark at the top of the canonical id space, though: planner passes
    # can later remove the highest-numbered nodes while the identity book
    # still retains their canonical_value rows.  A subsequent synthesized
    # loop/port node must not reuse one of those historical identities.
    ordered_graph.graph.pop("value_id_watermark", None)
    ordered_graph.graph["value_id_watermark"] = max(mapping.values(), default=-1)
    # The canonical relabel is DERIVED rows, never an in-place renumbering
    # (plan 60, section 3.1): one ``canonical_value`` row per entry of
    # ``mapping``, new id <- the node's ``ingestion_value`` cell, the token
    # chain as the fact.  ``graph.G`` is still the ingestion graph here, so
    # ``node_identity_cell`` answers with ingestion cells; a node no writer
    # gave a row (a non-AST ingestion object) gets one Unsourced under the
    # latch, which is what the audit's worklist lists.
    book = current_identity_book()
    canonical_cells: dict[int, Any] = {}
    for node_id in ordered:
        canonical_cells[node_id] = book.post(
            _CANONICAL_VALUE, (read_scope, mapping[node_id]),
            tuple(node_token_chains[node_id]),
            stage=_CANONICAL_RELABEL_STAGE,
            provenance=_Derived((node_identity_cell(graph, node_id),)),
            mode=_Mode.CONCORD,
        )
    canonical_page = book.page(_CANONICAL_VALUE)
    ordered_graph.graph["ssa_identity_tokens"] = {
        int(row[1]): canonical_page.latest(row)
        for row in canonical_page.scope_rows(read_scope)
    }
    # Every binding ``identity_bindings`` holds has its ``name_binding`` row
    # in the ingestion scope before the relabel (plan 60, section 3.2):
    # ``input_value`` and ``record_ingestion_definition`` post theirs as
    # they bind; a binding site that has not yet posted (a loop target, a
    # return slot, a conditional or loop-carried merge) gets its row here,
    # DERIVED from the value's ingestion cell, ``authored=False``.
    binding_page = book.page(_NAME_BINDING)
    ingestion_binding_cells: dict[tuple[str, int], Any] = {}
    for name, value_ids in identity_bindings.items():
        for version, value_id in enumerate(value_ids):
            row = (ingestion_read_scope, str(name), int(version))
            cell = book.latest_ref(_NAME_BINDING, row)
            if cell is None:
                cell = book.post(
                    _NAME_BINDING, row,
                    _BindingFact(int(value_id), False, (None,) * 4, ""),
                    stage=_REDUCTION,
                    provenance=_Derived(
                        (node_identity_cell(graph, int(value_id)),)
                    ),
                    mode=_Mode.CONCORD,
                )
            ingestion_binding_cells[(str(name), int(version))] = cell
    build_scope = ordered_graph.graph.get("ingestion_value_scope")
    map_ir = dict(ordered_graph.graph.get("map_ir") or {})
    if build_scope is None:
        # A graph no ``build_from_ast`` posted rows for keeps its ids.
        map_ir["schema_node_ids"] = tuple(
            mapping[node_id]
            for node_id in map_ir.get("schema_node_ids", ())
            if node_id in mapping
        )
        map_ir["schema_roots"] = tuple(
            mapping[node_id]
            for node_id in map_ir.get("schema_roots", ())
            if node_id in mapping
        )
    else:
        # ``schema_node`` canonical rows DERIVED(ingestion row); the two
        # tuples are the canonical scope's rows (plan 60, section 3.3 (e)).
        schema_page = book.page(_SCHEMA_NODE)
        schema_roots = set(map_ir.get("schema_roots", ()))
        canonical_schema_ids: list[int] = []
        canonical_schema_roots: list[int] = []
        for row in schema_page.scope_rows(build_scope):
            if row[1] not in mapping:
                continue
            book.post(
                _SCHEMA_NODE, (read_scope, mapping[row[1]]), True,
                stage=_CANONICAL_RELABEL_STAGE,
                provenance=_Derived((book.latest_ref(_SCHEMA_NODE, row),)),
                mode=_Mode.CONCORD,
            )
            canonical_schema_ids.append(mapping[row[1]])
            if row[1] in schema_roots:
                canonical_schema_roots.append(mapping[row[1]])
        map_ir["schema_node_ids"] = tuple(canonical_schema_ids)
        map_ir["schema_roots"] = tuple(canonical_schema_roots)
    ordered_graph.graph["map_ir"] = map_ir
    # ``scalar_parameter`` canonical rows DERIVED(ingestion row) (plan 60,
    # section 3.5 (e)); the node attribute travels with the relabel.
    scalar_page = book.page(_SCALAR_PARAMETER)
    for scope in dict.fromkeys(
        scope for scope in (ingestion_read_scope, build_scope)
        if scope is not None
    ):
        for row in scalar_page.scope_rows(scope):
            if row[1] not in mapping:
                continue
            book.post(
                _SCALAR_PARAMETER, (read_scope, mapping[row[1]]),
                _ValueKind.SCALAR, stage=_CANONICAL_RELABEL_STAGE,
                provenance=_Derived((book.latest_ref(_SCALAR_PARAMETER, row),)),
                mode=_Mode.CONCORD,
            )
    # ``callable_identity_concordance`` rows were written at ingestion ids
    # and never moved (the audit read rows the linker could no longer
    # join); their canonical rows are DERIVED(ingestion row) (plan 60,
    # section 3.8 (e)).
    callable_page = book.page(_CALLABLE_IDENTITY)
    numeric_scope = _source_numeric_scope(graph)
    for row in tuple(callable_page.scope_rows(numeric_scope)):
        if row[1] not in mapping or mapping[row[1]] == row[1]:
            continue
        book.post(
            _CALLABLE_IDENTITY, (numeric_scope, mapping[row[1]]),
            callable_page.latest(row), stage=_CANONICAL_RELABEL_STAGE,
            provenance=_Derived((book.latest_ref(_CALLABLE_IDENTITY, row),)),
            mode=_Mode.REVISE,
        )
    # ``source_python_identity_concordance`` is the exact resolved identity
    # of a source call.  Its ingestion-id row must cross the same canonical
    # rename as the call node; retaining only the copied node attributes
    # isolates consumers from the concordance fact that authorized them.
    python_identity_page = book.page(_SOURCE_PYTHON_IDENTITY)
    canonical_python_identity_rows: dict[int, tuple[Any, int]] = {}
    for row in tuple(python_identity_page.scope_rows(numeric_scope)):
        source_node_id = int(row[1])
        if source_node_id not in mapping:
            continue
        target_row = (numeric_scope, int(mapping[source_node_id]))
        book.post(
            _SOURCE_PYTHON_IDENTITY,
            target_row,
            python_identity_page.latest(row),
            stage=_CANONICAL_RELABEL_STAGE,
            provenance=_Derived((
                book.latest_ref(_SOURCE_PYTHON_IDENTITY, row),
                canonical_cells[source_node_id],
            )),
            mode=_Mode.REVISE,
        )
        canonical_python_identity_rows[source_node_id] = target_row
    for node_id in ordered:
        ordered_graph.add_node(
            mapping[node_id], **graph.G.nodes[node_id].copy()
        )
        identity_row = canonical_python_identity_rows.get(node_id)
        if identity_row is not None:
            ordered_graph.nodes[mapping[node_id]].setdefault(
                "attributes", {}
            )["source_python_identity_row"] = identity_row
    ordered_graph.add_edges_from(
        (
            mapping[source], mapping[target], attributes.copy()
        )
        for source, target, attributes in graph.G.edges(data=True)
    )
    graph.G = ordered_graph
    graph.MG = ordered_memory_graph
    graph.roots = [
        mapping[root] for root in graph.roots if root in mapping
    ]
    graph.levels = {
        mapping[node_id]: level
        for node_id, level in graph.levels.items()
        if node_id in mapping
    }
    # Canonical ``name_binding`` rows: DERIVED(ingestion row, the value's
    # ``canonical_value`` row), one per (name, version) whose value
    # survived; ``identity_table`` is the canonical scope's rows, a name
    # whose every value left the graph keeps its empty tuple as before.
    for (name, version), cell in ingestion_binding_cells.items():
        fact = binding_page.latest(cell.row)
        value_id = int(fact.value_id)
        if value_id not in mapping:
            continue
        book.post(
            _NAME_BINDING, (read_scope, name, version),
            _BindingFact(
                int(mapping[value_id]), fact.authored, fact.span_positions,
                fact.context_sha256,
            ),
            stage=_CANONICAL_RELABEL_STAGE,
            provenance=_Derived((cell, canonical_cells[value_id])),
            mode=_Mode.CONCORD,
        )
        from ...compiler.concordance_declarations import NAME_BINDING_CAPTURE
        capture = book.page(NAME_BINDING_CAPTURE).latest(cell.row)
        if capture is not None:
            source_name, source_version, owner = capture
            source_fact = binding_page.latest((ingestion_read_scope, source_name, source_version))
            if source_fact is not None and int(source_fact.value_id) in mapping:
                book.post(
                    NAME_BINDING_CAPTURE, (read_scope, name, version),
                    (source_name, source_version, None if owner is None else mapping.get(owner)),
                    stage=_CANONICAL_RELABEL_STAGE,
                    provenance=_Derived((book.latest_ref(NAME_BINDING_CAPTURE, cell.row), canonical_cells[value_id])),
                    mode=_Mode.CONCORD,
                )
    canonical_bindings: dict[str, list[tuple[int, Any]]] = {}
    for row in binding_page.scope_rows(read_scope):
        canonical_bindings.setdefault(str(row[1]), []).append(
            (int(row[2]), binding_page.latest(row))
        )
    for entries in canonical_bindings.values():
        entries.sort(key=lambda entry: entry[0])
    graph.G.graph["identity_table"] = {
        name: tuple(
            int(fact.value_id)
            for _version, fact in canonical_bindings.get(str(name), ())
        )
        for name in identity_bindings
    }
    # Class facts this function committed while its values still had
    # ingestion ids follow those values into the canonical id space, exactly
    # as the identity table does; the concordance answers by canonical id.
    # One DERIVED post per row, its cells every column of the ingestion row
    # (plan 60, section 3.1 (e)); the ingestion row stays as history.
    class_page = book.page(_SOURCE_VALUE_CLASS)
    for row in tuple(class_page.rows()):
        if (
            isinstance(row, tuple) and len(row) == 2
            and row[0] == value_class_scope and row[1] in mapping
            and mapping[row[1]] != row[1]
        ):
            history = class_page.history(row)
            book.post(
                _SOURCE_VALUE_CLASS, (value_class_scope, mapping[row[1]]),
                history[-1][1], stage=_CANONICAL_RELABEL_STAGE,
                provenance=_Derived(tuple(
                    _Ref(_SOURCE_VALUE_CLASS, row, column)
                    for column, _fact in history
                )),
                mode=_Mode.REVISE,
            )
    # Aggregate layouts are source facts, not graph metadata.  Carry their
    # owner and ordered member identities into the canonical id space while
    # retaining the exact authored/conditional cells in each immutable fact.
    aggregate_page = book.page(_SOURCE_AGGREGATE_LAYOUT)
    aggregate_canonical_scope = tuple(read_scope)
    graph.G.graph["source_aggregate_layout_scope"] = (
        aggregate_canonical_scope
    )
    for row in tuple(aggregate_page.scope_rows(value_class_scope)):
        if int(row[1]) not in mapping:
            continue
        source_fact = aggregate_page.latest(row)
        if not isinstance(source_fact, _SourceAggregateLayout):
            raise TypeError(
                f"invalid source aggregate layout fact at {row!r}: "
                f"{source_fact!r}"
            )
        member_ids = tuple(
            int(member.value_id) for member in source_fact.members
        )
        missing = tuple(
            value_id for value_id in member_ids
            if value_id not in mapping or value_id not in canonical_cells
        )
        if missing:
            raise ValueError(
                "source aggregate layout cannot be partially canonicalized: "
                f"row={row!r} missing={missing!r}"
            )
        target_row = (
            aggregate_canonical_scope,
            int(mapping[int(row[1])]),
        )
        if target_row == row and all(
            int(mapping[value_id]) == value_id for value_id in member_ids
        ):
            ordered_graph.nodes[int(target_row[1])].setdefault(
                "attributes", {}
            )["source_aggregate_layout_row"] = target_row
            continue
        source_cell = book.latest_ref(_SOURCE_AGGREGATE_LAYOUT, row)
        canonical_members = tuple(
            _SourceAggregateMember(
                int(mapping[int(member.value_id)]),
                canonical_cells[int(member.value_id)],
                tuple(dict.fromkeys((
                    source_cell, member.value_cell, *member.source_cells,
                    canonical_cells[int(member.value_id)],
                ))),
            )
            for member in source_fact.members
        )
        book.post(
            _SOURCE_AGGREGATE_LAYOUT, target_row,
            _SourceAggregateLayout(
                str(source_fact.aggregate_kind), canonical_members,
                source_fact.conditional_cell,
                tuple(source_fact.arm_layout_cells),
            ),
            stage=_CANONICAL_RELABEL_STAGE,
            provenance=_Derived(tuple(dict.fromkeys((
                source_cell,
                canonical_cells[int(row[1])],
                *(member.value_cell for member in canonical_members),
            )))),
            mode=_Mode.CONCORD,
        )
        ordered_graph.nodes[int(target_row[1])].setdefault(
            "attributes", {}
        )["source_aggregate_layout_row"] = target_row
    # Dynamic-string recipes are source facts over graph identities.  Carry
    # both their owner row and every component/operand identity through the
    # same canonical relabel.  The source row remains historical evidence;
    # all downstream sequence materialization reads the canonical row.
    glyph_page = book.page(_SOURCE_GLYPH_SEQUENCE)
    glyph_canonical_scope = tuple(read_scope)
    graph.G.graph["source_glyph_sequence_scope"] = glyph_canonical_scope
    # Dynamic recipes are copy-local because they can name generated
    # projection/formatter producers.  Literal spellings remain authored
    # facts.  Select the local row for an owner when both exist; no row may
    # import a generated producer from another function copy.
    glyph_rows_by_value = {
        int(row[1]): row
        for row in glyph_page.scope_rows(value_class_scope)
        if int(row[1]) in mapping
    }
    glyph_rows_by_value.update({
        int(row[1]): row
        for row in glyph_page.scope_rows(ingestion_read_scope)
        if int(row[1]) in mapping
    })
    for row in tuple(glyph_rows_by_value.values()):
        source_fact = glyph_page.latest(row)
        def glyph_component_value_ids(component):
            yield int(component.component_value_id)
            for value_id in (
                component.operand_value_id,
                component.projection_source_value_id,
                component.format_spec_value_id,
                *component.projection_value_ids,
                component.formatted_sequence_value_id,
                *(
                    arm.sequence_value_id
                    for arm in component.union_alternatives
                ),
            ):
                if value_id is not None:
                    yield int(value_id)
            for child in component.projection_components:
                yield from glyph_component_value_ids(child)

        carried_value_ids = tuple(dict.fromkeys(
            value_id
            for component in source_fact.components
            for value_id in glyph_component_value_ids(component)
        ))
        missing_value_ids = tuple(
            value_id for value_id in carried_value_ids
            if value_id not in mapping or value_id not in canonical_cells
        )
        if missing_value_ids:
            raise ValueError(
                "source glyph sequence cannot be partially canonicalized: "
                f"row={row!r} missing={missing_value_ids!r}"
            )
        def canonical_glyph_component(component):
            return _SourceGlyphComponent(
                kind=component.kind,
                component_value_id=int(mapping[int(
                    component.component_value_id
                )]),
                operand_value_id=(
                    None if component.operand_value_id is None
                    else int(mapping[int(component.operand_value_id)])
                ),
                glyph_tokens=tuple(component.glyph_tokens),
                conversion=int(component.conversion),
                format_spec_value_id=(
                    None if component.format_spec_value_id is None
                    else int(mapping[int(component.format_spec_value_id)])
                ),
                projection_kind=str(component.projection_kind),
                record_identity=component.record_identity,
                projection_names=tuple(component.projection_names),
                projection_value_ids=tuple(
                    int(mapping[int(value_id)])
                    for value_id in component.projection_value_ids
                ),
                projection_components=tuple(
                    canonical_glyph_component(child)
                    for child in component.projection_components
                ),
                formatted_sequence_value_id=(
                    None
                    if component.formatted_sequence_value_id is None
                    else int(mapping[int(
                        component.formatted_sequence_value_id
                    )])
                ),
                enum_table_cell=component.enum_table_cell,
                union_alternatives=tuple(
                    _SourceGlyphUnionAlternative(
                        identity=str(arm.identity),
                        sequence_value_id=int(mapping[int(
                            arm.sequence_value_id
                        )]),
                        source_cells=tuple(arm.source_cells),
                    )
                    for arm in component.union_alternatives
                ),
                projection_source_value_id=(
                    None
                    if component.projection_source_value_id is None
                    else int(mapping[int(
                        component.projection_source_value_id
                    )])
                ),
                projection_transform=component.projection_transform,
                projection_operation_cell=component.projection_operation_cell,
            )
        canonical_components = tuple(
            canonical_glyph_component(component)
            for component in source_fact.components
        )
        # Each reduced graph copy owns its canonical recipe.  Source pursuit
        # may retain several copies of one authored function, and their
        # generated formatter calls are different graph values even when the
        # JoinedStr itself receives the same canonical integer.  Reusing the
        # authored function scope here merged those copies and made the book
        # choose between two formatter identities.  The lexical read scope is
        # the existing exact copy identity used by aggregate layouts above.
        target_row = (glyph_canonical_scope, int(mapping[row[1]]))
        provenance = [book.latest_ref(_SOURCE_GLYPH_SEQUENCE, row)]
        def glyph_component_tree(component):
            yield component
            for child in component.projection_components:
                yield from glyph_component_tree(child)
        provenance.extend(
            canonical_cells[value_id]
            for component in source_fact.components
            for component in glyph_component_tree(component)
            for value_id in (
                int(component.component_value_id),
                component.operand_value_id,
                component.projection_source_value_id,
                component.format_spec_value_id,
                *component.projection_value_ids,
                component.formatted_sequence_value_id,
            )
            if value_id is not None and int(value_id) in canonical_cells
        )
        provenance.extend(
            component.projection_operation_cell
            for component in source_fact.components
            for component in glyph_component_tree(component)
            if component.projection_operation_cell is not None
        )
        book.post(
            _SOURCE_GLYPH_SEQUENCE,
            target_row,
            _SourceGlyphSequence(canonical_components),
            stage=_CANONICAL_RELABEL_STAGE,
            provenance=_Derived(tuple(dict.fromkeys(provenance))),
            mode=_Mode.CONCORD,
        )

        literal_value_representation = (
            len(source_fact.components) == 1
            and source_fact.components[0].kind == "literal"
            and int(source_fact.components[0].component_value_id)
            == int(row[1])
        )
        ordered_graph.nodes[int(mapping[row[1]])].setdefault(
            "attributes", {}
        )[
            "source_literal_glyph_sequence_row"
            if literal_value_representation
            else "source_glyph_sequence_row"
        ] = target_row
        for ordinal, component in enumerate(canonical_components):
            if component.kind != "formatted":
                continue
            source_component = (row, int(ordinal))
            canonical_component = (target_row, int(ordinal))
            ordered_graph.nodes[int(component.component_value_id)].setdefault(
                "attributes", {}
            )["source_glyph_component"] = canonical_component
            if component.formatted_sequence_value_id is not None:
                formatted_attributes = ordered_graph.nodes[
                    int(component.formatted_sequence_value_id)
                ].setdefault("attributes", {})
                formatted_attributes[
                    "source_glyph_component"
                ] = canonical_component
    from ...compiler.concordance_declarations import (
        SOURCE_LITERAL_VALUE, SOURCE_SEQUENCE_MUTATION,
        SOURCE_SORT_CONTRACT, SourceSortContract,
    )
    literal_page = book.page(SOURCE_LITERAL_VALUE)
    for row in tuple(literal_page.scope_rows(value_class_scope)):
        if int(row[1]) not in mapping:
            continue
        book.post(
            SOURCE_LITERAL_VALUE,
            (value_class_scope, int(mapping[int(row[1])])),
            literal_page.latest(row),
            stage=_CANONICAL_RELABEL_STAGE,
            provenance=_Derived((
                book.latest_ref(SOURCE_LITERAL_VALUE, row),
                canonical_cells[int(row[1])],
            )),
            mode=_Mode.CONCORD,
        )
    sort_page = book.page(SOURCE_SORT_CONTRACT)
    canonical_sort_contract_cells = {}
    mutation_page = book.page(SOURCE_SEQUENCE_MUTATION)
    for row in tuple(mutation_page.scope_rows(value_class_scope)):
        if int(row[1]) not in mapping:
            continue
        initial, operator, policy, argument_ids, kind = mutation_page.latest(row)
        if int(initial) not in mapping or any(
            int(value_id) not in mapping for value_id in argument_ids
        ):
            continue
        target_row = (value_class_scope, int(mapping[int(row[1])]))
        mapped_fact = (
            int(mapping[int(initial)]), str(operator), str(policy),
            tuple(int(mapping[int(value_id)]) for value_id in argument_ids),
            str(kind),
        )
        provenance = [book.latest_ref(SOURCE_SEQUENCE_MUTATION, row)]
        provenance.extend(
            canonical_cells[int(value_id)]
            for value_id in (int(row[1]), int(initial), *argument_ids)
        )
        book.post(
            SOURCE_SEQUENCE_MUTATION, target_row, mapped_fact,
            stage=_CANONICAL_RELABEL_STAGE,
            provenance=_Derived(tuple(dict.fromkeys(provenance))),
            mode=_Mode.CONCORD,
        )
    for row in tuple(sort_page.scope_rows(value_class_scope)):
        if int(row[1]) not in mapping:
            continue
        source_fact = sort_page.latest(row)
        if not isinstance(source_fact, SourceSortContract):
            continue
        target_row = (value_class_scope, int(mapping[int(row[1])]))
        mapped_arguments = tuple(
            int(mapping[int(value_id)])
            for value_id in source_fact.argument_value_ids
            if int(value_id) in mapping
        )
        if len(mapped_arguments) != len(source_fact.argument_value_ids):
            continue
        destination_value_id = (
            None if source_fact.destination_value_id is None else
            mapping.get(int(source_fact.destination_value_id))
        )
        source_value_id = (
            None if source_fact.source_value_id is None else
            mapping.get(int(source_fact.source_value_id))
        )
        if (
            source_fact.destination_value_id is not None
            and destination_value_id is None
            or source_fact.source_value_id is not None
            and source_value_id is None
        ):
            continue
        provenance = [book.latest_ref(SOURCE_SORT_CONTRACT, row)]
        provenance.extend(
            canonical_cells[int(value_id)]
            for value_id in (
                int(row[1]), *source_fact.argument_value_ids,
                source_fact.destination_value_id,
                source_fact.source_value_id,
            )
            if value_id is not None and int(value_id) in canonical_cells
        )
        canonical_sort_contract_cells[int(target_row[1])] = book.post(
            SOURCE_SORT_CONTRACT, target_row,
            SourceSortContract(
                source_fact.argument_kind, mapped_arguments,
                source_fact.key_column, source_fact.reverse,
                destination_value_id, source_fact.operation,
                source_fact.policy, source_value_id,
            ),
            stage=_CANONICAL_RELABEL_STAGE,
            provenance=_Derived(tuple(dict.fromkeys(provenance))),
            mode=_Mode.CONCORD,
        )
        ordered_graph.nodes[int(mapping[int(row[1])])].setdefault(
            "attributes", {}
        )["source_sort_contract_row"] = target_row
    # The reducer field-state and return-site pages (plan 70) follow the
    # same relabel once their canonical node cells exist.
    relabel_field_state_pages = globals().get("_relabel_field_state_pages")
    if relabel_field_state_pages is not None:
        relabel_field_state_pages(book, read_scope, mapping)
    # The per-read bindings follow their consumers into canonical ids.  A
    # scope reduced again revises its canonical rows rather than keeping a
    # previous reduction's facts.
    read_page = current_identity_book().page("lexical_read_binding")
    for row in read_page.scope_rows(ingestion_read_scope):
        # A position an operand rewrite vacated holds an ``Unresolved``
        # revision (None before the withdrawal named its cause): no fact to
        # carry.
        if not isinstance(read_page.latest(row), str):
            continue
        if len(row) == 4 and (row[1] == "return" or row[1] in mapping):
            # The canonical row is the ingestion row relabeled: DERIVED
            # from that cell, same fact.
            target_row = (
                (read_scope, *row[1:]) if row[1] == "return"
                else (read_scope, mapping[row[1]], row[2], row[3])
            )
            book.post(
                _LEXICAL_READ_BINDING, target_row, read_page.latest(row),
                stage=_CANONICAL_RELABEL_STAGE,
                provenance=_Derived((book.latest_ref(
                    _LEXICAL_READ_BINDING, row,
                ),)),
                mode=_Mode.CONCORD,
            )
    # Step 9 (plan 100, 1.1): the operand-position rows follow their
    # consumers into canonical ids, so the canonical graph's edges are the
    # latest ``identity_transition`` facts under its own scope.  The scope
    # the graph arrived with first (an extracted subgraph's own fork of the
    # build scope's ``ProcessGraph.connect`` Appends), then this
    # reduction's rewrites, which supersede them; each canonical row is
    # DERIVED from the row it continues.  A fact naming an id that left the
    # graph has no canonical spelling and stays where it is.
    from ...compiler.concordance_declarations import (
        IDENTITY_TRANSITION as _IDENTITY_TRANSITION_PAGE,
        OperandAppend as _OperandAppend,
        OperandFork as _OperandFork,
        OperandMove as _OperandMove,
        OperandTransition as _OperandTransition,
    )
    transition_page = book.page(_IDENTITY_TRANSITION_PAGE)
    for transition_scope in dict.fromkeys(
        tuple(scope)
        for scope in (
            entry_operand_scope or build_scope, ingestion_read_scope,
        )
        if scope is not None
    ):
        for row in tuple(transition_page.scope_rows(transition_scope)):
            if len(row) != 4 or row[1] not in mapping:
                continue
            fact = transition_page.latest(row)
            if isinstance(fact, _OperandAppend):
                if fact.operand not in mapping:
                    continue
                fact = _OperandAppend(fact.cause, mapping[fact.operand])
            elif isinstance(fact, _OperandMove):
                if fact.consumer not in mapping:
                    continue
                fact = _OperandMove(
                    fact.cause, mapping[fact.consumer], fact.role, fact.ordinal,
                )
            elif isinstance(fact, _OperandFork):
                if fact.source_consumer not in mapping:
                    continue
                fact = _OperandFork(
                    fact.cause, mapping[fact.source_consumer],
                    fact.source_role, fact.source_ordinal,
                )
            elif not isinstance(fact, _OperandTransition):
                continue
            canonical_row = (read_scope, mapping[row[1]], row[2], row[3])
            if transition_page.latest(canonical_row) == fact:
                continue
            book.post(
                _IDENTITY_TRANSITION_PAGE, canonical_row, fact,
                stage=_CANONICAL_RELABEL_STAGE,
                provenance=_Derived(
                    (book.latest_ref(_IDENTITY_TRANSITION_PAGE, row),)
                ),
                mode=_Mode.REVISE,
            )
    graph.G.graph["lexical_read_scope"] = read_scope
    graph.G.graph["operand_position_scope"] = read_scope
    # Compiler-authored glyph producer calls are introduced only after the
    # source recipe exists.  Now that their canonical node cells and caller
    # scope exist, publish the ordinary call binding before any compilation
    # unit can inspect topology.  ``callee_ref`` is the graph view of this
    # exact row, never a name/coordinate reconstruction.
    from ...compiler.planner_concordance_posts import _post_call_binding
    for call_id, call_data in graph.G.nodes(data=True):
        call_attributes = call_data.get("attributes") or {}
        if call_attributes.get("callee_resolution") not in {
            "source-glyph-formatter",
        }:
            continue
        formatter_reference = int(call_attributes["callee_ref"])
        _post_call_binding(
            graph, int(call_id), formatter_reference, "callsite_shell",
        )
    # The return-site receipts (``return_slot_values``,
    # ``return_record_field_states``, ``return_container_kinds``) are read
    # views over the return-site pages (plan 70, section 2); they follow the
    # scope just set, and their canonical rows were posted by
    # ``_relabel_field_state_pages`` above.  Nothing is renumbered in place.
    # ``identity_table`` remains the compact compatibility map used by older
    # lowering code.  This ledger preserves the original common spelling and
    # its authored rebinding version before any SSA-only phi/capture/temp
    # values are introduced.
    # Materialized from the canonical ``name_binding`` rows (the authored
    # ones); the token payload joins from ``ingestion_definitions`` because
    # ``BindingFact`` carries the context sha, not the tokens.
    ingestion_identity_table: dict[str, tuple] = {}
    for name, definitions in ingestion_definitions.items():
        authored = [
            fact for _version, fact in canonical_bindings.get(str(name), ())
            if fact.authored
        ]
        entries = []
        for version, (value_id, source) in enumerate(definitions):
            if value_id not in mapping:
                continue
            fact = next(
                (
                    candidate for candidate in authored
                    if int(candidate.value_id) == mapping[value_id]
                ),
                None,
            )
            if fact is None:
                raise ValueError(
                    f"name_binding has no canonical authored row for "
                    f"{name!r} version {version}"
                )
            authored.remove(fact)
            entries.append({
                "spelling": str(name),
                "version": version,
                "value_id": int(fact.value_id),
                "source_span": dict(zip(
                    ("line", "column", "end_line", "end_column"),
                    fact.span_positions,
                )),
                **({
                    "context": source["context"],
                    "context_tokens": source["context_tokens"],
                    "context_token_ids": source["context_token_ids"],
                    "context_sha256": source["context_sha256"],
                } if "context" in source else {}),
            })
        ingestion_identity_table[str(name)] = tuple(entries)
    graph.G.graph["ingestion_identity_table"] = ingestion_identity_table
    for value_id, data in graph.G.nodes(data=True):
        data["value_id"] = value_id
        attributes = data.get("attributes") or {}
        if "source_optional_glyph_dispatch" in attributes:
            dispatch = dict(attributes["source_optional_glyph_dispatch"])
            scalar_ids = (
                "owner_conditional_id", "conditional_value_id",
                "present_value_id", "absent_value_id",
            )
            if all(int(dispatch[key]) in mapping for key in scalar_ids):
                for key in scalar_ids:
                    dispatch[key] = int(mapping[int(dispatch[key])])
                dispatch["present_callsite_ids"] = tuple(
                    int(mapping[int(item)])
                    for item in dispatch.get("present_callsite_ids", ())
                    if int(item) in mapping
                )
                dispatch["present_projection_sequence_ids"] = tuple(
                    int(mapping[int(item)])
                    for item in dispatch.get(
                        "present_projection_sequence_ids", ()
                    )
                    if int(item) in mapping
                )
                attributes["source_optional_glyph_dispatch"] = dispatch
            else:
                attributes.pop("source_optional_glyph_dispatch", None)
        if "loop_carried_bindings" in attributes:
            attributes["loop_carried_bindings"] = {
                name: (mapping[initial], mapping[updated])
                for name, (initial, updated) in attributes[
                    "loop_carried_bindings"
                ].items()
                if initial in mapping and updated in mapping
            }
        if "loop_break_bindings" in attributes:
            attributes["loop_break_bindings"] = {
                name: (mapping[initial], mapping[continuation])
                for name, (initial, continuation) in attributes[
                    "loop_break_bindings"
                ].items()
                if initial in mapping and continuation in mapping
            }
        if "loop_break_sites" in attributes:
            attributes["loop_break_sites"] = {
                span: {
                    (mapping[initial], mapping[updated]): mapping[value]
                    for (initial, updated), value in site_values.items()
                    if initial in mapping and updated in mapping
                    and value in mapping
                }
                for span, site_values in attributes["loop_break_sites"].items()
            }
        if "loop_target_bindings" in attributes:
            attributes["loop_target_bindings"] = {
                name: mapping[target]
                for name, target in attributes[
                    "loop_target_bindings"
                ].items()
                if target in mapping
            }
        if "loop_target_initials" in attributes:
            attributes["loop_target_initials"] = {
                name: mapping[initial]
                for name, initial in attributes[
                    "loop_target_initials"
                ].items()
                if initial in mapping
            }
        if "source_conditional_id" in attributes:
            source_conditional_id = attributes["source_conditional_id"]
            if source_conditional_id in mapping:
                attributes["source_conditional_id"] = mapping[
                    source_conditional_id
                ]
        if "initial_value_id" in attributes:
            initial_value_id = attributes["initial_value_id"]
            if initial_value_id in mapping:
                attributes["initial_value_id"] = mapping[initial_value_id]
        if "enum_value_receiver_id" in attributes:
            enum_value_receiver_id = attributes["enum_value_receiver_id"]
            if enum_value_receiver_id in mapping:
                attributes["enum_value_receiver_id"] = mapping[
                    enum_value_receiver_id
                ]
        if "record_field_state" in attributes:
            receiver_id, attribute_name = attributes["record_field_state"]
            if receiver_id in mapping:
                attributes["record_field_state"] = (
                    mapping[receiver_id], attribute_name,
                )
        if "terminal_return_values" in attributes:
            attributes["terminal_return_values"] = tuple(
                mapping[value_id]
                for value_id in attributes["terminal_return_values"]
                if value_id in mapping
            )
        if "loop_state_effects" in attributes:
            def canonical_loop_effect(effect):
                effect_node_id = int(mapping[effect["effect_node_id"]])
                source_contract_cell = effect.get("source_contract_cell")
                if str(effect.get("operator")) == "sort":
                    source_contract_cell = canonical_sort_contract_cells.get(
                        effect_node_id
                    )
                    if source_contract_cell is None:
                        raise ValueError(
                            "canonical loop sort effect has no exact source "
                            f"contract cell: effect={effect_node_id}"
                        )
                return {
                    **effect,
                    "state_input_id": mapping[effect["state_input_id"]],
                    "effect_node_id": effect_node_id,
                    "argument_value_ids": tuple(
                        mapping[value_id]
                        for value_id in effect["argument_value_ids"]
                        if value_id in mapping
                    ),
                    "source_contract_cell": source_contract_cell,
                }
            attributes["loop_state_effects"] = tuple(
                canonical_loop_effect(effect)
                for effect in attributes["loop_state_effects"]
                if all(
                    effect[key] in mapping
                    for key in (
                        "state_input_id",
                        "effect_node_id",
                    )
                )
            )
        if "loop_iteration_outputs" in attributes:
            attributes["loop_iteration_outputs"] = tuple(
                {
                    key: mapping[output[key]]
                    for key in (
                        "value_id",
                        "result_value_id",
                        "materializer_node_id",
                    )
                }
                for output in attributes["loop_iteration_outputs"]
                if all(
                    output[key] in mapping
                    for key in (
                        "value_id",
                        "result_value_id",
                        "materializer_node_id",
                    )
                )
            )
        pending_sort = attributes.get("source_sort_contract_pending")
        if pending_sort is not None:
            attributes["source_sort_contract_pending"] = {
                **pending_sort,
                "argument_value_ids": tuple(
                    mapping[value_id]
                    for value_id in pending_sort["argument_value_ids"]
                    if value_id in mapping
                ),
            }
        for key in (
            "aggregate_leaf_value_ids",
            "materialized_source_value_ids",
        ):
            if key in attributes:
                attributes[key] = tuple(
                    mapping[value_id]
                    for value_id in attributes[key]
                    if value_id in mapping
                )
        _set_operands(graph, value_id, [
            (mapping[parent_id], role)
            for parent_id, role in data.get("parents", ())
            if parent_id in mapping
        ], cause=_CANONICAL_RELABEL_OPERANDS, same=mapping, materialize=False)
        # The relabel renames the view: ``add_edges_from`` above already
        # carried the edges into the canonical ids, and the ``children``
        # list follows the same mapping here; ``_set_operands`` moves the
        # rows only (``materialize=False``).
        data["children"] = [
            (mapping[child_id], role)
            for child_id, role in data.get("children", ())
            if child_id in mapping
        ]

    # Optional glyph carries are authored by the reducer's exact Phi edges.
    # Publish them here, while those operand-position cells and each arm's
    # source glyph/None producer are resident; deployment only reads this
    # page and never reconstructs it from a later control-program view.
    from ...compiler.concordance_declarations import (
        IDENTITY_TRANSITION,
        SOURCE_LITERAL_VALUE,
        SOURCE_OPTIONAL_GLYPH_CARRY,
        SourceOptionalGlyphArm,
        SourceOptionalGlyphCarry,
    )
    optional_page = book.page(SOURCE_OPTIONAL_GLYPH_CARRY)
    # A carry names its arms' glyph cells, which live in this retained
    # copy's canonical glyph scope.  Two copies of one authored function
    # therefore never share a carry row: keying it by the authored scope made
    # the second copy post the same key with its own arm cells.
    optional_cells = {
        int(row[1]): book.latest_ref(SOURCE_OPTIONAL_GLYPH_CARRY, row)
        for row in optional_page.scope_rows(glyph_canonical_scope)
    }

    def optional_arm(value_id: int):
        if int(value_id) not in graph.G:
            return None
        # The canonical glyph row is part of the value's graph view.  Dynamic
        # recipes are copy-local because they name generated formatter and
        # projection producers; literal recipes cross the same canonical
        # relabel.  Reconstructing a row from ``value_class_scope`` therefore
        # looks in the authored scope and loses both kinds of present arm.
        # Follow the exact row the relabel attached to this value instead.
        value_attributes = graph.G.nodes[int(value_id)].get(
            "attributes",
        ) or {}
        glyph_row = (
            value_attributes.get("source_glyph_sequence_row")
            or value_attributes.get("source_literal_glyph_sequence_row")
        )
        glyph_cell = (
            None if glyph_row is None else
            book.latest_ref(_SOURCE_GLYPH_SEQUENCE, tuple(glyph_row))
        )
        if glyph_cell is not None:
            return SourceOptionalGlyphArm(
                int(value_id), True, glyph_cell, int(value_id),
            )
        literal_cell = book.latest_ref(
            SOURCE_LITERAL_VALUE, (value_class_scope, int(value_id)),
        )
        literal_value = (
            object() if literal_cell is None else
            book.page(SOURCE_LITERAL_VALUE).cell(
                literal_cell.row, literal_cell.column,
            )
        )
        if literal_cell is not None and literal_value is None:
            return SourceOptionalGlyphArm(
                int(value_id), False, literal_cell, None,
            )
        inherited = optional_cells.get(int(value_id))
        if inherited is not None:
            return SourceOptionalGlyphArm(
                int(value_id), None, inherited, int(value_id),
            )
        return None

    # A Page.latest value used under ``value is None or ...`` has no authored
    # Phi: the f-string exists wholly inside the outer true arm.  The reducer
    # retained that exact comparison and the Page declaration on the merged
    # formatted-value node.  Publish the same optional payload/presence
    # contract used by ordinary Phis, with distinct present and literal-None
    # resident sequences.  Control assembly will place the present recipe's
    # calls and mutations inside a nested conditional owned by this cell.
    for merged_id, merged_data in graph.G.nodes(data=True):
        dispatch = (merged_data.get("attributes") or {}).get(
            "source_optional_glyph_dispatch"
        )
        if not isinstance(dispatch, dict):
            continue
        present_id = int(dispatch["present_value_id"])
        absent_id = int(dispatch["absent_value_id"])
        control_id = int(dispatch["conditional_value_id"])
        present_arm = optional_arm(present_id)
        absent_arm = optional_arm(absent_id)
        if present_arm is None or absent_arm is None:
            raise ValueError(
                "Page optional glyph dispatch lost an arm recipe: "
                f"merged={merged_id} present={present_id} absent={absent_id}"
            )
        row = (glyph_canonical_scope, int(merged_id))
        fact = SourceOptionalGlyphCarry(
            conditional_value_id=control_id,
            true_value_id=present_id,
            false_value_id=absent_id,
            initial_value_id=None,
            merged_value_id=int(merged_id),
            true_arm=present_arm,
            false_arm=absent_arm,
            initial_arm=None,
            payload_sequence_value_id=int(merged_id),
            present_callsite_ids=tuple(map(
                int, dispatch.get("present_callsite_ids", ()),
            )),
            present_projection_sequence_ids=tuple(map(
                int, dispatch.get("present_projection_sequence_ids", ()),
            )),
            predicate_expect_true=bool(dispatch.get(
                "predicate_expect_true", True,
            )),
            owner_conditional_id=int(dispatch["owner_conditional_id"]),
        )
        sources = tuple(dict.fromkeys(filter(None, (
            present_arm.presence_source,
            absent_arm.presence_source,
            node_identity_cell(graph, int(merged_id)),
            node_identity_cell(graph, control_id),
            dispatch.get("source_page_declaration_cell"),
        ))))
        cell = book.post(
            SOURCE_OPTIONAL_GLYPH_CARRY, row, fact,
            stage=_CANONICAL_RELABEL_STAGE,
            provenance=_Derived(sources),
            mode=_Mode.CONCORD,
        )
        optional_cells[int(merged_id)] = cell
        merged_data.setdefault("attributes", {}).update({
            "producer_kind": "optional_glyph_sequence",
            "aggregate_kind": "list",
            "sequence_key_columns": (),
            "sequence_column_count": 1,
            "sequence_writable": True,
            "sequence_element_dtypes": ("int64",),
            "source_optional_glyph_carry_row": row,
        })

    pending_optional = []
    for phi_id, phi_data in graph.G.nodes(data=True):
        attributes = phi_data.get("attributes") or {}
        if (
            str(phi_data.get("type") or phi_data.get("op") or "").casefold()
            != "phi"
            or attributes.get("source_conditional_id") is None
        ):
            continue
        parents = {
            str(role): int(parent)
            for parent, role in phi_data.get("parents") or ()
            if int(parent) in graph.G
        }
        if not {"body", "orelse"}.issubset(parents):
            continue
        initial_value_id = attributes.get("initial_value_id")
        pending_optional.append((
            int(phi_id), int(attributes["source_conditional_id"]),
            int(parents["body"]), int(parents["orelse"]),
            None if initial_value_id is None else int(initial_value_id),
        ))
    progressed = True
    while pending_optional and progressed:
        progressed = False
        remainder = []
        for phi_id, control_id, true_id, false_id, initial_id in pending_optional:
            arms = (
                optional_arm(true_id), optional_arm(false_id),
                None if initial_id is None else optional_arm(initial_id),
            )
            if any(arm is None for arm in arms):
                if initial_id is None and arms[0] is not None and arms[1] is not None:
                    pass
                else:
                    remainder.append((
                        phi_id, control_id, true_id, false_id, initial_id,
                    ))
                    continue
            concrete_arms = tuple(arm for arm in arms if arm is not None)
            if all(arm.presence is True for arm in concrete_arms):
                continue
            true_arm, false_arm, initial_arm = arms
            row = (glyph_canonical_scope, int(phi_id))
            fact = SourceOptionalGlyphCarry(
                conditional_value_id=control_id,
                true_value_id=true_id, false_value_id=false_id,
                initial_value_id=initial_id, merged_value_id=phi_id,
                true_arm=true_arm, false_arm=false_arm,
                initial_arm=initial_arm,
                payload_sequence_value_id=phi_id,
            )
            sources = [
                true_arm.presence_source, false_arm.presence_source,
                node_identity_cell(graph, phi_id),
                node_identity_cell(graph, control_id),
            ]
            if initial_arm is not None:
                sources.append(initial_arm.presence_source)
            position_scope = graph.G.graph.get("operand_position_scope")
            if position_scope is not None:
                for role, ordinal, _parent in _operand_positions(
                    graph.G.nodes[phi_id].get("parents") or ()
                ):
                    position_cell = book.latest_ref(
                        IDENTITY_TRANSITION,
                        (tuple(position_scope), phi_id, str(role), int(ordinal)),
                    )
                    if position_cell is not None:
                        sources.append(position_cell)
            cell = book.post(
                SOURCE_OPTIONAL_GLYPH_CARRY, row, fact,
                stage=_CANONICAL_RELABEL_STAGE,
                provenance=_Derived(tuple(dict.fromkeys(sources))),
                mode=_Mode.CONCORD,
            )
            optional_cells[phi_id] = cell
            graph.G.nodes[phi_id].setdefault("attributes", {}).update({
                "producer_kind": "optional_glyph_sequence",
                "aggregate_kind": "list",
                "sequence_key_columns": (),
                "sequence_column_count": 1,
                "sequence_writable": True,
                "sequence_element_dtypes": ("int64",),
                "source_optional_glyph_carry_row": row,
            })
            progressed = True
        pending_optional = remainder

    terminal_merges = [
        int(node_id)
        for node_id, data in graph.G.nodes(data=True)
        if (data.get("attributes") or {}).get("terminal_return_merge")
    ]
    for merge_id in terminal_merges:
        branch_values = set(
            (graph.G.nodes[merge_id].get("attributes") or {}).get(
                "terminal_return_values", ()
            )
        )
        if branch_values and branch_values.issubset(graph.roots):
            graph.roots = [
                root for root in graph.roots if root not in branch_values
            ]
            graph.roots.append(merge_id)

    return dict(lexical_free_names_by_reference)


def normalize_python_attribute_special_cases(graph: Any) -> None:
    """Canonicalize Python attribute loads on a graph already in the table.

    Dependency linking can attach a previously extracted Python function
    after the root reduction pass. Apply the same AST special-case overlay to
    those graphs before deployment so linked functions cannot retain raw
    ``ast.Attribute`` nodes that backends would mistake for external values.
    """

    if str(getattr(graph, "source_language", "")).casefold() != "python":
        return
    for node_id, data in graph.G.nodes(data=True):
        expression = data.get("expr_obj")
        augmented_target_read = bool(
            isinstance(expression, ast.Attribute)
            and isinstance(expression.ctx, ast.Store)
            and any(
                str(role) == "lhs"
                and child_id in graph.G
                and isinstance(
                    graph.G.nodes[child_id].get("expr_obj"), ast.AugAssign,
                )
                for child_id, role in data.get("children") or ()
            )
        )
        if not (
            isinstance(expression, ast.Attribute)
            and (
                isinstance(expression.ctx, ast.Load)
                or augmented_target_read
            )
        ):
            continue
        special_expression = expression
        if augmented_target_read:
            # Python gives an AugAssign target Store context, but the operation
            # is read-modify-write. This graph node supplies the read operand;
            # the reducer's separate SetAttr node owns the write effect.
            special_expression = copy.deepcopy(expression)
            special_expression.ctx = ast.Load()
        special = interpret_python_special_case(special_expression)
        if special is None:
            continue
        data["type"] = special.type
        data["op"] = special.type
        data["attributes"] = {
            **dict(data.get("attributes") or {}),
            **dict(special.attributes),
        }
        data["extra_args"] = {
            **dict(data.get("extra_args") or {}),
            **dict(special.attributes),
        }


def reduce_abstract_tensor_topology(graph: Any) -> Any:
    """Apply existing ProcessGraph names to the three structural AST nodes."""

    from ...compiler.shell_telemetry import compile_substage, compile_iter

    compile_substage("topology: numeric annotations and lexical owners")
    _record_numeric_annotation_descriptors(graph)
    function_table = getattr(graph, "function_table", None)
    if function_table is None:
        function_table = FunctionTable()
        graph.function_table = function_table
    external_function_table = getattr(
        graph,
        "external_function_table",
        None,
    )
    if external_function_table is None:
        external_function_table = ExternalFunctionTable()
        graph.external_function_table = external_function_table

    function_nodes: dict[int, Any] = {}
    function_return_values: dict[int, list[int]] = {}
    call_owners: dict[int, Any] = {}
    method_owners: dict[int, str] = {}
    class_definitions: dict[str, ast.ClassDef] = {}
    external_owner_classes: dict[str, type] = {}
    lexical_parent_by_function: dict[int, int] = {}
    function_definitions = {
        int(node_id): node_data.get("expr_obj")
        for node_id, node_data in graph.G.nodes(data=True)
        if is_runnable_definition(node_data.get("expr_obj"))
    }

    class _DirectNestedFunctionVisitor(ast.NodeVisitor):
        def __init__(self, owner_id: int):
            self.owner_id = int(owner_id)

        def visit_FunctionDef(self, node):
            lexical_parent_by_function[id(node)] = self.owner_id

        visit_AsyncFunctionDef = visit_FunctionDef

        def visit_Lambda(self, node):
            lexical_parent_by_function[id(node)] = self.owner_id

        def visit_ClassDef(self, node):
            # A class body is not itself a closure scope, but methods of a
            # class defined inside a function can close directly over that
            # function. ``interchange_reduction_loops`` does exactly this:
            # ``_RegisterBlockRewriter.visit_For`` writes the outer
            # ``state: dict``. Skipping the class body left the method with no
            # lexical parent, so closure aggregate discovery rebuilt ``state``
            # from its live Python value as ``static:state``. The indexed
            # store then disagreed with the authored dict identity and failed
            # during lexical reduction. Record methods against the enclosing
            # function; their own nested definitions are visited later from
            # the method's function record.
            for member in node.body:
                if isinstance(
                    member, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda),
                ):
                    lexical_parent_by_function[id(member)] = self.owner_id
                elif isinstance(member, ast.ClassDef):
                    self.visit_ClassDef(member)
            return None

    authored_definitions_by_name: dict[str, tuple[Any, ...]] = {}
    for definition in function_definitions.values():
        if isinstance(definition, (ast.FunctionDef, ast.AsyncFunctionDef)):
            authored_definitions_by_name[str(definition.name)] = (
                *authored_definitions_by_name.get(str(definition.name), ()),
                definition,
            )

    for owner_id, definition in compile_iter(function_definitions.items(),
            "lexical-owners", label="Lexical function owners indexed"):
        if not isinstance(
            definition, (ast.FunctionDef, ast.AsyncFunctionDef)
        ):
            continue
        visitor = _DirectNestedFunctionVisitor(owner_id)
        for body_member in definition.body:
            visitor.visit(body_member)

    def local_aggregate_kinds(definition: Any) -> dict[str, str]:
        """Return aggregate storage owned by one lexical scope.

        Parameters are part of that scope's storage contract too. A nested
        function captures the outer parameter object, not a new untyped host
        value. ``_bind_sequence_storage_members.bind`` captures the annotated
        ``storage_bindings: dict[int, int]`` parameter and mutates it. Omitting
        annotated parameters here made that exact mapping reappear as a static
        Python closure value at the nested boundary.
        """

        if not isinstance(
            definition, (ast.FunctionDef, ast.AsyncFunctionDef)
        ):
            return {}
        def annotated_kind(annotation: ast.AST | None) -> str | None:
            if isinstance(annotation, ast.Name) and annotation.id in {
                "list", "set", "dict", "tuple", "bytes", "bytearray",
            }:
                return annotation.id
            if isinstance(annotation, ast.Subscript):
                return annotated_kind(annotation.value)
            if isinstance(annotation, ast.BinOp) and isinstance(
                annotation.op, ast.BitOr,
            ):
                alternatives = tuple(filter(None, (
                    annotated_kind(annotation.left),
                    annotated_kind(annotation.right),
                )))
                return (
                    alternatives[0]
                    if alternatives and len(set(alternatives)) == 1
                    else None
                )
            return None

        kinds: dict[str, str] = {}
        source_identity = getattr(definition, "_python_source_identity", None)
        qualified_name = (
            str(source_identity[1])
            if isinstance(source_identity, tuple) and len(source_identity) == 2
            else str(
                getattr(
                    definition,
                    "_turing_source_qualname",
                    getattr(definition, "name", ""),
                )
            )
        )
        schema = dict(
            (graph.G.graph.get("map_ir") or {}).get("schema") or {}
        )
        for function_schema in tuple(schema.get("functions") or ()):
            if str(function_schema.get("identity") or "") != qualified_name:
                continue
            for declaration in tuple(function_schema.get("locals") or ()):
                annotation_text = str(declaration.get("annotation") or "")
                try:
                    annotation = ast.parse(annotation_text, mode="eval").body
                except SyntaxError:
                    continue
                kind = annotated_kind(annotation)
                if kind is not None:
                    kinds[str(declaration["name"])] = kind
        for argument in (
            *definition.args.posonlyargs,
            *definition.args.args,
            *definition.args.kwonlyargs,
        ):
            kind = annotated_kind(argument.annotation)
            if kind is not None:
                kinds[argument.arg] = kind
        pending = list(reversed(definition.body))
        while pending:
            member = pending.pop()
            if isinstance(
                member,
                (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda),
            ):
                continue
            if isinstance(member, (ast.Assign, ast.AnnAssign)):
                value = member.value
                kind = (
                    annotated_kind(member.annotation)
                    if isinstance(member, ast.AnnAssign) else None
                )
                if isinstance(value, (ast.List, ast.ListComp)):
                    kind = "list"
                elif isinstance(value, (ast.Set, ast.SetComp)):
                    kind = "set"
                elif isinstance(value, (ast.Dict, ast.DictComp)):
                    kind = "dict"
                elif isinstance(value, ast.Tuple):
                    kind = "tuple"
                elif isinstance(value, ast.Name):
                    # Source pursuit records constructor classes in
                    # ``_python_bindings`` for discovery.  They are not the
                    # runtime identity of an authored alias.  Preserve the
                    # exact lexical storage relation here so a nested
                    # function capturing ``trace`` after
                    # ``trace = _selection_trace`` receives the same keyed
                    # storage input instead of resolving the weaker
                    # discovery marker ``trace: dict`` as a static Python
                    # reference.
                    kind = kinds.get(value.id)
                elif (
                    isinstance(value, ast.Call)
                    and isinstance(value.func, ast.Name)
                    and value.func.id in {
                        "list", "set", "dict", "tuple", "bytes", "bytearray"
                    }
                ):
                    kind = value.func.id
                targets = (
                    tuple(member.targets)
                    if isinstance(member, ast.Assign)
                    else (member.target,)
                )
                if kind is not None:
                    for target in targets:
                        if isinstance(target, ast.Name):
                            kinds[target.id] = kind
            pending.extend(reversed(tuple(source_child_nodes(member))))
        return kinds

    compile_substage("topology: class fields and aggregate contracts")
    local_aggregate_kinds_by_function = {
        definition_id: local_aggregate_kinds(definition)
        for definition_id, definition in function_definitions.items()
    }

    def locally_declared_aggregate_names(definition: Any) -> set[str]:
        source_identity = getattr(definition, "_python_source_identity", None)
        qualified_name = (
            str(source_identity[1])
            if isinstance(source_identity, tuple) and len(source_identity) == 2
            else str(
                getattr(
                    definition,
                    "_turing_source_qualname",
                    getattr(definition, "name", ""),
                )
            )
        )
        schema = dict(
            (graph.G.graph.get("map_ir") or {}).get("schema") or {}
        )
        parameter_names = {
            str(argument.arg)
            for argument in (
                *definition.args.posonlyargs,
                *definition.args.args,
                *definition.args.kwonlyargs,
            )
        }
        return {
            str(declaration["name"])
            for function_schema in tuple(schema.get("functions") or ())
            if str(function_schema.get("identity") or "") == qualified_name
            for declaration in tuple(function_schema.get("locals") or ())
            if str(declaration["name"]) not in parameter_names
        }

    local_declared_aggregate_kinds_by_function = {
        definition_id: {
            name: kind
            for name, kind in local_aggregate_kinds_by_function.get(
                definition_id, {}
            ).items()
            if name in locally_declared_aggregate_names(definition)
        }
        for definition_id, definition in function_definitions.items()
    }

    def closure_aggregate_kinds(definition_id: int) -> dict[str, str]:
        """Aggregate identities inherited from lexical parent scopes."""

        inherited: dict[str, str] = {}
        parent_id = lexical_parent_by_function.get(definition_id)
        ancestry = []
        while parent_id is not None:
            ancestry.append(parent_id)
            parent_id = lexical_parent_by_function.get(parent_id)
        for ancestor_id in reversed(ancestry):
            inherited.update(
                local_aggregate_kinds_by_function.get(ancestor_id, {})
            )
        return inherited
    for _node_id, node_data in graph.G.nodes(data=True):
        class_definition = node_data.get("expr_obj")
        if isinstance(
            class_definition,
            (ast.FunctionDef, ast.AsyncFunctionDef),
        ):
            source_identity = getattr(
                class_definition,
                "_python_source_identity",
                None,
            )
            qualified = (
                str(source_identity[1])
                if (
                    isinstance(source_identity, tuple)
                    and len(source_identity) == 2
                )
                else ""
            )
            parts = tuple(
                part for part in qualified.split(".") if part != "<locals>"
            )
            if "<locals>" not in qualified and len(parts) >= 2:
                method_owners[id(class_definition)] = parts[-2]
                module_name = str(source_identity[0])
                try:
                    module = importlib.import_module(module_name)
                    owner_class = getattr(module, parts[-2])
                except (ImportError, AttributeError, TypeError):
                    owner_class = None
                if inspect.isclass(owner_class):
                    external_owner_classes[parts[-2]] = owner_class
        if not isinstance(class_definition, ast.ClassDef):
            continue
        class_definitions[class_definition.name] = class_definition
        class_source_identity = getattr(
            class_definition, "_python_source_identity", None
        )
        if (
            isinstance(class_source_identity, tuple)
            and len(class_source_identity) == 2
        ):
            module_name, qualified_name = map(str, class_source_identity)
            target: Any = None
            try:
                target = importlib.import_module(module_name)
                for part in qualified_name.split("."):
                    if part == "<locals>":
                        target = None
                        break
                    target = getattr(target, part)
            except (ImportError, AttributeError, TypeError):
                target = None
            if inspect.isclass(target):
                external_owner_classes[class_definition.name] = target
        for member in class_definition.body:
            if isinstance(member, (ast.FunctionDef, ast.AsyncFunctionDef)):
                method_owners[id(member)] = class_definition.name
    class_field_aggregate_kinds: dict[tuple[str, str], str] = {
        (str(owner), str(field)): str(kind)
        for (owner, field), kind in dict(
            graph.G.graph.get("external_class_field_aggregate_kinds") or {}
        ).items()
    }
    declared_class_field_contracts = dict(
        graph.G.graph.get("declared_class_field_contracts") or {}
    )
    # ProgramABI is the retained declaration authority when source pursuit
    # carries a method without every nested record's ClassDef.  In
    # IdentityPage._fork_of_scope the method graph retains
    # IdentityPage.book -> IdentityBook -> Registry, but the intermediate
    # GetAttr reads cannot recover those classes from the method owner's AST.
    # Index the exact record receipts once so every downstream field view uses
    # the same authored identity rather than requiring a duplicate ClassDef.
    program_abi_field_contracts = {
        (str(record.get("identity") or record_name), str(field_name)): dict(field)
        for record_name, record in dict(
            (graph.G.graph.get("program_abi") or {}).get("records") or {}
        ).items()
        for field_name, field in dict(record.get("fields") or {}).items()
        if isinstance(field, Mapping)
    }
    for key, receipt in declared_class_field_contracts.items():
        aggregate_kind = receipt.get("aggregate_kind")
        if aggregate_kind is not None:
            class_field_aggregate_kinds.setdefault(
                (str(key[0]), str(key[1])), str(aggregate_kind),
            )
    for key, receipt in program_abi_field_contracts.items():
        aggregate_kind = receipt.get("aggregate_kind")
        if aggregate_kind is not None:
            class_field_aggregate_kinds.setdefault(key, str(aggregate_kind))
    # (owner, field) -> the source-local class an instance field HOLDS.
    # ``self.ordnance = OrdnanceField()`` in a method of the owner, or
    # ``ordnance: OrdnanceField`` declared on the class, states it. A field
    # read ``self.ordnance`` then yields an object of that class, and the
    # method call ``self.ordnance.step(...)`` resolves its ``method_ref``
    # through the class table exactly as ``self.step(...)`` already does --
    # which is what makes it a source-linked call the callee owns instead
    # of an opaque state effect no model can be formed for. Recorded only
    # when every assignment names ONE class; two classes for one field is
    # not a fact this table may state.
    class_field_classes: dict[tuple[str, str], str] = {}
    contested_field_classes: set[tuple[str, str]] = set()

    def note_field_class(owner: str, field: str, class_name: str) -> None:
        key = (str(owner), str(field))
        if key in contested_field_classes:
            return
        known = class_field_classes.get(key)
        if known is None:
            class_field_classes[key] = str(class_name)
        elif known != str(class_name):
            del class_field_classes[key]
            contested_field_classes.add(key)

    for (owner_name, field_name), receipt in (
        program_abi_field_contracts.items()
    ):
        if (
            str(receipt.get("storage") or "") == "record"
            and receipt.get("record") is not None
        ):
            note_field_class(
                owner_name, field_name, str(receipt["record"]),
            )

    def declared_field_class(annotation: ast.AST | None) -> str | None:
        """The one source-local class named by a field annotation.

        ``T | None`` is still a declaration of ``T`` storage.  Flatten only
        that authored union and accept it only when exactly one non-None
        member names a class in this source; no use-site inference enters the
        decision.
        """

        if isinstance(annotation, ast.Constant) and isinstance(
            annotation.value, str
        ):
            try:
                annotation = ast.parse(annotation.value, mode="eval").body
            except SyntaxError:
                return None
        pending = [annotation]
        identities: list[str] = []
        while pending:
            member = pending.pop()
            if isinstance(member, ast.BinOp) and isinstance(
                member.op, ast.BitOr
            ):
                pending.extend((member.right, member.left))
            elif (
                isinstance(member, ast.Constant) and member.value is None
            ) or (
                isinstance(member, ast.Name) and member.id == "None"
            ):
                continue
            elif (
                isinstance(member, ast.Name)
                and (
                    member.id in class_definitions
                    or member.id in external_owner_classes
                )
            ):
                identities.append(member.id)
            else:
                return None
        distinct = tuple(dict.fromkeys(identities))
        return distinct[0] if len(distinct) == 1 else None

    for owner_name, class_definition in class_definitions.items():
        for member in class_definition.body:
            declared_class = (
                declared_field_class(member.annotation)
                if isinstance(member, ast.AnnAssign) else None
            )
            if declared_class is not None and isinstance(
                member.target, ast.Name
            ):
                note_field_class(
                    owner_name, member.target.id, declared_class
                )
                continue
            if not isinstance(member, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            for node in source_walk(member):
                if (
                    isinstance(node, ast.AnnAssign)
                    and isinstance(node.target, ast.Attribute)
                    and isinstance(node.target.value, ast.Name)
                    and node.target.value.id in {"self", "cls"}
                ):
                    declared_class = declared_field_class(node.annotation)
                    if declared_class is not None:
                        note_field_class(
                            owner_name, node.target.attr, declared_class,
                        )
                if (
                    isinstance(node, ast.Assign)
                    and len(node.targets) == 1
                    and isinstance(node.targets[0], ast.Attribute)
                    and isinstance(node.targets[0].value, ast.Name)
                    and node.targets[0].value.id in {"self", "cls"}
                    and isinstance(node.value, ast.Call)
                    and isinstance(node.value.func, ast.Name)
                    and node.value.func.id in class_definitions
                ):
                    note_field_class(
                        owner_name, node.targets[0].attr, node.value.func.id
                    )
    class_field_mapping_contracts: dict[
        tuple[str, str], dict[str, Any]
    ] = {
        (str(owner), str(field)): {
            "mapping_key_dtype": "int64",
            "mapping_value_dtype": str(
                receipt.get("dtype") or "unknown"
            ),
            **({
                "mapping_value_tensor": True,
                "mapping_value_python_type": "AbstractTensor",
            } if receipt.get("value_tensor") else {}),
            **({
                "mapping_value_record": str(receipt["value_record"]),
            } if receipt.get("value_record") is not None else {}),
            "mapping_value_optional": bool(
                receipt.get("value_optional", False)
            ),
        }
        for (owner, field), receipt in declared_class_field_contracts.items()
        if (
            str(receipt.get("storage") or "") == "keyed"
            or receipt.get("mapping_value_dtype") is not None
        )
    }
    for key, receipt in declared_class_field_contracts.items():
        if receipt.get("mapping_value_dtype") is None:
            continue
        class_field_mapping_contracts[(str(key[0]), str(key[1]))] = {
            name: receipt[name]
            for name in (
                "mapping_key_dtype", "mapping_value_dtype",
                "mapping_value_record", "mapping_value_optional",
            )
            if receipt.get(name) is not None
        }
    class_field_sequence_records: dict[tuple[str, str], str] = {
        (str(owner), str(field)): str(receipt["row_record"])
        for (owner, field), receipt in declared_class_field_contracts.items()
        if receipt.get("row_record") is not None
    }
    class_field_sequence_dtypes: dict[
        tuple[str, str], tuple[str, ...]
    ] = {
        key: (str(receipt["dtype"]),)
        for key, receipt in program_abi_field_contracts.items()
        if (
            receipt.get("aggregate_kind") is not None
            and receipt.get("dtype") is not None
        )
    }
    class_field_sequence_element_classes: dict[
        tuple[str, str], str
    ] = {}

    def _annotation_storage(annotation: ast.AST) -> dict[str, Any]:
        """Return the exact scalar/record handle stated by one annotation."""

        if isinstance(annotation, ast.BinOp) and isinstance(
            annotation.op, ast.BitOr
        ):
            concrete = tuple(
                member for member in (annotation.left, annotation.right)
                if not (
                    isinstance(member, ast.Constant)
                    and member.value is None
                )
                and not (
                    isinstance(member, ast.Name) and member.id == "None"
                )
            )
            if len(concrete) == 1:
                return {
                    **_annotation_storage(concrete[0]),
                    "optional": True,
                }
        if isinstance(annotation, ast.Subscript):
            container = (
                annotation.value.id
                if isinstance(annotation.value, ast.Name)
                else annotation.value.attr
                if isinstance(annotation.value, ast.Attribute)
                else ""
            )
            aggregate = str(container).casefold()
            if aggregate in {
                "list", "sequence", "iterable", "collection", "set",
                "frozenset", "tuple", "dict", "mapping", "mutablemapping",
                "bytes", "bytearray",
            }:
                # Nested authored aggregates cross a table boundary by their
                # resident row handle. Their own element schema remains on
                # the child sequence; the outer mapping stores the integral
                # handle, never a Python object.
                normalized = {
                    "sequence": "list",
                    "iterable": "list",
                    "collection": "list",
                    "mapping": "dict",
                    "mutablemapping": "dict",
                }.get(aggregate, aggregate)
                receipt: dict[str, Any] = {
                    "dtype": "int64", "aggregate_kind": normalized,
                }
                if normalized == "tuple":
                    elements = (
                        tuple(annotation.slice.elts)
                        if isinstance(annotation.slice, ast.Tuple)
                        else (annotation.slice,)
                    )
                    element_receipts = tuple(
                        _annotation_storage(element) for element in elements
                    )
                    if (
                        elements
                        and not any(
                            isinstance(element, ast.Constant)
                            and element.value is Ellipsis
                            for element in elements
                        )
                        and all(
                            element_receipt.get("dtype") is not None
                            and element_receipt.get("aggregate_kind") is None
                            and not element_receipt.get("tensor")
                            for element_receipt in element_receipts
                        )
                    ):
                        receipt["columns"] = element_receipts
                return receipt
        name = (
            annotation.id if isinstance(annotation, ast.Name)
            else annotation.attr if isinstance(annotation, ast.Attribute)
            else ""
        )
        dtype = {
            "bool": "bool", "int": "int64", "float": "float64",
            # Source strings are repository string-table tokens at this
            # boundary, not Python objects.
            "str": "int64",
        }.get(str(name))
        if dtype is not None:
            return {"dtype": dtype}
        if tensor_annotation_identity(
            annotation, getattr(graph, "python_bindings", {}) or {},
        ) is not None:
            return {
                "dtype": "unknown",
                "tensor": True,
                "python_type": "AbstractTensor",
            }
        if name:
            # Repository records cross table boundaries by a deterministic
            # integer row handle; their physical fields remain described by
            # the record table rather than being collapsed into this scalar.
            return {"dtype": "int64", "record": str(name)}
        return {}

    class_field_storage_contracts: dict[
        tuple[str, str], dict[str, Any]
    ] = {
        key: {
            name: receipt[name]
            for name in (
                "dtype", "record", "aggregate_kind", "tensor",
                "python_type", "optional",
            )
            if receipt.get(name) is not None
        }
        for key, receipt in program_abi_field_contracts.items()
        if receipt.get("dtype") is not None or receipt.get("record") is not None
    }

    def _mapping_annotation(annotation: ast.AST | None) -> dict[str, Any]:
        if isinstance(annotation, ast.BinOp) and isinstance(
            annotation.op, ast.BitOr
        ):
            concrete = tuple(
                member for member in (annotation.left, annotation.right)
                if not (
                    isinstance(member, ast.Constant)
                    and member.value is None
                )
                and not (
                    isinstance(member, ast.Name) and member.id == "None"
                )
            )
            if len(concrete) == 1:
                annotation = concrete[0]
        if not isinstance(annotation, ast.Subscript):
            return {}
        container = (
            annotation.value.id
            if isinstance(annotation.value, ast.Name)
            else annotation.value.attr
            if isinstance(annotation.value, ast.Attribute)
            else ""
        )
        if str(container).casefold() not in {"dict", "mapping", "mutablemapping"}:
            return {}
        columns = (
            tuple(annotation.slice.elts)
            if isinstance(annotation.slice, ast.Tuple)
            else (annotation.slice,)
        )
        if len(columns) != 2:
            return {}
        key = _annotation_storage(columns[0])
        value = _annotation_storage(columns[1])
        # Program: ``values: dict[int, Any] = {}`` then
        # ``values[key] = arguments[key]`` (SSAReferenceEvaluator.run).
        # Wrong record: an ``Any`` value fell to the record branch of
        # ``_annotation_storage``, so the row declared an int64 handle of a
        # record named 'Any' and the store of the opaque value refused as a
        # row dtype disagreement.  Rule: a mapping's arbitrary-object VALUE
        # is the fixed-width opaque handle, as in the keyed-value receipt
        # (``_authored_annotation_field_receipt``).  An ``Any`` key and an
        # ``Any`` inside a nested aggregate keep their integer row handle.
        if (
            isinstance(columns[1], ast.Name)
            and columns[1].id in {"Any", "object"}
        ) or (
            isinstance(columns[1], ast.Attribute)
            and columns[1].attr == "Any"
        ):
            value = {"dtype": "opaque_ref"}
        if key.get("dtype") is None or value.get("dtype") is None:
            return {}
        return {
            "mapping_key_dtype": str(key["dtype"]),
            "mapping_value_dtype": str(value["dtype"]),
            **({
                "mapping_value_aggregate_kind": str(value["aggregate_kind"]),
            } if value.get("aggregate_kind") is not None else {}),
            **({
                "mapping_value_tensor": True,
                "mapping_value_python_type": "AbstractTensor",
            } if value.get("tensor") else {}),
            **({
                "mapping_value_record": str(value["record"]),
            } if value.get("record") is not None else {}),
            **({
                "mapping_value_column_count": len(value["columns"]),
                "mapping_value_columns": tuple(value["columns"]),
            } if value.get("columns") else {}),
            "mapping_value_optional": bool(value.get("optional", False)),
        }

    def _aggregate_annotation_kind(
        annotation: ast.AST | str | Any,
    ) -> str | None:
        """Return the aggregate kind stated by one source annotation."""

        if not isinstance(annotation, ast.AST):
            try:
                annotation = ast.parse(str(annotation), mode="eval").body
            except SyntaxError:
                return None
        if isinstance(annotation, ast.BinOp) and isinstance(
            annotation.op, ast.BitOr
        ):
            concrete = tuple(
                member for member in (annotation.left, annotation.right)
                if not (
                    isinstance(member, ast.Constant)
                    and member.value is None
                )
                and not (
                    isinstance(member, ast.Name) and member.id == "None"
                )
            )
            if len(concrete) == 1:
                annotation = concrete[0]
        target = annotation.value if isinstance(
            annotation, ast.Subscript
        ) else annotation
        name = (
            target.id if isinstance(target, ast.Name)
            else target.attr if isinstance(target, ast.Attribute)
            else ""
        )
        return {
            "sequence": "list",
            "iterable": "list",
            "collection": "list",
            "list": "list",
            "set": "set",
            "frozenset": "frozenset",
            "tuple": "tuple",
            "dict": "dict",
            "mapping": "dict",
            "mutablemapping": "dict",
            "bytes": "bytes",
            "bytearray": "bytearray",
        }.get(str(name).casefold())

    def _function_local_mapping_contracts(
        definition: ast.AST,
    ) -> dict[str, dict[str, Any]]:
        """Aggregate row contracts authored in one exact function scope."""

        def sequence_row_dtypes(annotation: ast.AST) -> tuple[str, ...]:
            if not isinstance(annotation, ast.Subscript):
                return ()
            container = (
                annotation.value.id
                if isinstance(annotation.value, ast.Name)
                else annotation.value.attr
                if isinstance(annotation.value, ast.Attribute)
                else ""
            )
            if str(container).casefold() not in {
                "list", "sequence", "iterable", "collection", "set",
                "frozenset", "tuple",
            }:
                return ()
            element = annotation.slice
            if isinstance(element, ast.Subscript):
                row_container = (
                    element.value.id
                    if isinstance(element.value, ast.Name)
                    else element.value.attr
                    if isinstance(element.value, ast.Attribute)
                    else ""
                )
                if str(row_container).casefold() == "tuple":
                    members = (
                        tuple(element.slice.elts)
                        if isinstance(element.slice, ast.Tuple)
                        else (element.slice,)
                    )
                    if not (
                        len(members) == 2
                        and isinstance(members[1], ast.Constant)
                        and members[1].value is Ellipsis
                    ):
                        dtypes = tuple(
                            str(_annotation_storage(member).get("dtype") or "")
                            for member in members
                        )
                        if dtypes and all(dtypes):
                            return dtypes
            dtype = _annotation_storage(element).get("dtype")
            return (str(dtype),) if dtype is not None else ()

        source_identity = getattr(definition, "_python_source_identity", None)
        qualified_name = (
            str(source_identity[1])
            if isinstance(source_identity, tuple) and len(source_identity) == 2
            else str(getattr(
                definition, "_turing_source_qualname",
                getattr(definition, "name", ""),
            ))
        )
        contracts: dict[str, dict[str, Any]] = {}
        schema = dict(
            (graph.G.graph.get("map_ir") or {}).get("schema") or {}
        )
        for function_schema in tuple(schema.get("functions") or ()):
            if str(function_schema.get("identity") or "") != qualified_name:
                continue
            for declaration in tuple(function_schema.get("locals") or ()):
                try:
                    annotation = ast.parse(
                        str(declaration.get("annotation") or ""), mode="eval",
                    ).body
                except SyntaxError:
                    continue
                contract = _mapping_annotation(annotation)
                if contract:
                    contracts[str(declaration["name"])] = contract
                    continue
                dtypes = sequence_row_dtypes(annotation)
                if dtypes:
                    contracts[str(declaration["name"])] = {
                        "sequence_column_count": len(dtypes),
                        "sequence_element_dtypes": dtypes,
                    }
        return contracts

    local_mapping_contracts_by_function = {
        definition_id: _function_local_mapping_contracts(definition)
        for definition_id, definition in function_definitions.items()
    }

    def _sequence_annotation_dtypes(
        annotation: ast.AST | str | Any,
    ) -> tuple[str, ...]:
        if not isinstance(annotation, ast.AST):
            try:
                annotation = ast.parse(str(annotation), mode="eval").body
            except SyntaxError:
                return ()
        if not isinstance(annotation, ast.Subscript):
            return ()
        container = (
            annotation.value.id
            if isinstance(annotation.value, ast.Name)
            else annotation.value.attr
            if isinstance(annotation.value, ast.Attribute)
            else ""
        )
        if container not in {
            "Sequence", "Iterable", "Collection", "List", "list",
            "Tuple", "tuple", "Set", "set", "FrozenSet", "frozenset",
        }:
            return ()
        columns = (
            tuple(annotation.slice.elts)
            if isinstance(annotation.slice, ast.Tuple)
            else (annotation.slice,)
        )
        if (
            len(columns) == 2
            and isinstance(columns[1], ast.Constant)
            and columns[1].value is Ellipsis
        ):
            columns = columns[:1]
        if len(columns) != 1:
            return ()
        storage = _annotation_storage(columns[0])
        dtype = storage.get("dtype")
        return (str(dtype),) if dtype is not None else ()

    def _sequence_annotation_element_class(
        annotation: ast.AST | str | Any,
    ) -> str | None:
        """Return the semantic class declared for each sequence element."""

        if not isinstance(annotation, ast.AST):
            try:
                annotation = ast.parse(str(annotation), mode="eval").body
            except SyntaxError:
                return None
        if not isinstance(annotation, ast.Subscript):
            return None
        container = (
            annotation.value.id
            if isinstance(annotation.value, ast.Name)
            else annotation.value.attr
            if isinstance(annotation.value, ast.Attribute)
            else ""
        )
        if container not in {
            "Sequence", "Iterable", "Collection", "List", "list",
            "Tuple", "tuple", "Set", "set", "FrozenSet", "frozenset",
        }:
            return None
        element = annotation.slice
        if (
            isinstance(element, ast.Tuple)
            and len(element.elts) == 2
            and isinstance(element.elts[1], ast.Constant)
            and element.elts[1].value is Ellipsis
        ):
            element = element.elts[0]
        identity = (
            element.id if isinstance(element, ast.Name)
            else element.attr if isinstance(element, ast.Attribute)
            else None
        )
        return {
            "str": "builtins.str",
            "bool": "builtins.bool",
            "int": "builtins.int",
            "float": "builtins.float",
        }.get(str(identity)) or (
            str(identity)
            if identity in class_definitions
            or identity in dict((graph.G.graph.get("program_abi") or {}).get(
                "records"
            ) or {})
            else None
        )

    def note_sequence_element_class(
        owner: str, field: str, annotation: ast.AST | str | Any,
    ) -> None:
        element_class = _sequence_annotation_element_class(annotation)
        if element_class is not None:
            class_field_sequence_element_classes[
                (str(owner), str(field))
            ] = str(element_class)

    def _sequence_annotation_record(
        annotation: ast.AST | str | Any,
    ) -> str | None:
        """Return the declared record identity of each sequence row."""

        if not isinstance(annotation, ast.AST):
            try:
                annotation = ast.parse(str(annotation), mode="eval").body
            except SyntaxError:
                return None
        if not isinstance(annotation, ast.Subscript):
            return None
        container = (
            annotation.value.id
            if isinstance(annotation.value, ast.Name)
            else annotation.value.attr
            if isinstance(annotation.value, ast.Attribute)
            else ""
        )
        if container not in {
            "Sequence", "Iterable", "Collection", "List", "list",
            "Tuple", "tuple", "Set", "set", "FrozenSet", "frozenset",
        }:
            return None
        element = annotation.slice
        identity = (
            element.id if isinstance(element, ast.Name)
            else element.attr if isinstance(element, ast.Attribute)
            else None
        )
        known_records = set(class_definitions) | set(
            dict((graph.G.graph.get("program_abi") or {}).get(
                "records"
            ) or {})
        )
        return str(identity) if identity in known_records else None

    # AST ingestion normalizes an annotated assignment into its executable
    # assignment form, but MapIR deliberately retains the authored annotation
    # as schema data.  Read that durable copy; it is the exact cross-function
    # source of truth for fields declared in ``__init__``.
    for class_record in tuple(
        (graph.G.graph.get("map_ir") or {}).get("objects") or ()
    ):
        class_name = str(class_record.get("class_identity") or "")
        for field_record in tuple(class_record.get("attributes") or ()):
            annotation = field_record.get("annotation")
            if not class_name or not annotation:
                continue
            try:
                annotation_node = ast.parse(
                    str(annotation), mode="eval"
                ).body
            except SyntaxError:
                continue
            storage = _annotation_storage(annotation_node)
            if storage.get("dtype") is not None:
                class_field_storage_contracts[(
                    class_name, str(field_record.get("name") or ""),
                )] = storage
            aggregate_kind = _aggregate_annotation_kind(annotation_node)
            if aggregate_kind is not None:
                class_field_aggregate_kinds.setdefault((
                    class_name, str(field_record.get("name") or ""),
                ), aggregate_kind)
            contract = _mapping_annotation(annotation_node)
            if contract:
                class_field_mapping_contracts[(
                    class_name, str(field_record.get("name") or ""),
                )] = contract
            dtypes = _sequence_annotation_dtypes(annotation_node)
            if dtypes:
                class_field_sequence_dtypes[(
                    class_name, str(field_record.get("name") or ""),
                )] = dtypes
            note_sequence_element_class(
                class_name,
                str(field_record.get("name") or ""),
                annotation_node,
            )
            row_record = _sequence_annotation_record(annotation_node)
            if row_record is not None:
                class_field_sequence_records[(
                    class_name, str(field_record.get("name") or ""),
                )] = row_record

    for class_name, definition in class_definitions.items():
        for member in definition.body:
            candidates: list[ast.AnnAssign] = []
            if isinstance(member, ast.AnnAssign):
                candidates.append(member)
            elif isinstance(member, (ast.FunctionDef, ast.AsyncFunctionDef)):
                candidates.extend(
                    node for node in ast.walk(member)
                    if isinstance(node, ast.AnnAssign)
                )
            for declaration in candidates:
                field_name = (
                    declaration.target.id
                    if isinstance(declaration.target, ast.Name)
                    else declaration.target.attr
                    if (
                        isinstance(declaration.target, ast.Attribute)
                        and isinstance(declaration.target.value, ast.Name)
                        and declaration.target.value.id in {"self", "cls"}
                    )
                    else None
                )
                if field_name is None:
                    continue
                storage = _annotation_storage(declaration.annotation)
                if storage.get("dtype") is not None:
                    class_field_storage_contracts[(
                        str(class_name), str(field_name),
                    )] = storage
                aggregate_kind = _aggregate_annotation_kind(
                    declaration.annotation
                )
                if aggregate_kind is not None:
                    class_field_aggregate_kinds.setdefault(
                        (str(class_name), str(field_name)), aggregate_kind,
                    )
                contract = _mapping_annotation(declaration.annotation)
                if contract:
                    class_field_mapping_contracts[
                        (str(class_name), str(field_name))
                    ] = contract
                dtypes = _sequence_annotation_dtypes(declaration.annotation)
                if dtypes:
                    class_field_sequence_dtypes[
                        (str(class_name), str(field_name))
                    ] = dtypes
                note_sequence_element_class(
                    str(class_name), str(field_name), declaration.annotation,
                )
                row_record = _sequence_annotation_record(
                    declaration.annotation
                )
                if row_record is not None:
                    class_field_sequence_records[
                        (str(class_name), str(field_name))
                    ] = row_record
    # The FunctionTable's retained method definitions are the authoritative
    # source bodies.  Some ingestion paths retain a skeletal ClassDef while
    # storing the complete method AST separately, so survey those definitions
    # as well instead of making the class wrapper a hidden prerequisite.
    for definition_id, class_name in method_owners.items():
        definition = function_definitions.get(int(definition_id))
        if not isinstance(definition, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        for declaration in (
            node for node in ast.walk(definition)
            if isinstance(node, ast.AnnAssign)
            and isinstance(node.target, ast.Attribute)
            and isinstance(node.target.value, ast.Name)
            and node.target.value.id in {"self", "cls"}
        ):
            storage = _annotation_storage(declaration.annotation)
            if storage.get("dtype") is not None:
                class_field_storage_contracts[(
                    str(class_name), str(declaration.target.attr),
                )] = storage
            aggregate_kind = _aggregate_annotation_kind(
                declaration.annotation
            )
            if aggregate_kind is not None:
                class_field_aggregate_kinds.setdefault((
                    str(class_name), str(declaration.target.attr),
                ), aggregate_kind)
            contract = _mapping_annotation(declaration.annotation)
            if contract:
                class_field_mapping_contracts[
                    (str(class_name), str(declaration.target.attr))
                ] = contract
            dtypes = _sequence_annotation_dtypes(declaration.annotation)
            if dtypes:
                class_field_sequence_dtypes[
                    (str(class_name), str(declaration.target.attr))
                ] = dtypes
            note_sequence_element_class(
                str(class_name), str(declaration.target.attr),
                declaration.annotation,
            )
            row_record = _sequence_annotation_record(declaration.annotation)
            if row_record is not None:
                class_field_sequence_records[
                    (str(class_name), str(declaration.target.attr))
                ] = row_record

    # Imported dataclasses are legitimate authored record contracts even when
    # their class bodies are intentionally outside this compilation unit.
    # Read only declared dataclass metadata; do not instantiate the class or
    # invoke its factories.  The factory identity is enough to establish the
    # resident aggregate kind deterministically.
    for binding_name, bound_value in dict(
        getattr(graph, "python_bindings", {}) or {}
    ).items():
        if not isinstance(bound_value, type) or not is_dataclass(bound_value):
            continue
        for declared_field in fields(bound_value):
            factory = declared_field.default_factory
            aggregate_kind = next((
                kind.__name__
                for kind in (list, set, frozenset, dict, tuple, bytes, bytearray)
                if factory is kind
            ), None)
            if aggregate_kind is None:
                aggregate_kind = next((
                    kind.__name__
                    for kind in (
                        list, set, frozenset, dict, tuple, bytes, bytearray,
                    )
                    if type(declared_field.default) is kind
                ), None)
            if aggregate_kind is not None:
                class_field_aggregate_kinds.setdefault(
                    (str(binding_name), str(declared_field.name)),
                    aggregate_kind,
                )
            annotation_kind = _aggregate_annotation_kind(
                declared_field.type
            )
            if annotation_kind is not None:
                class_field_aggregate_kinds.setdefault(
                    (str(binding_name), str(declared_field.name)),
                    annotation_kind,
                )
            dtypes = _sequence_annotation_dtypes(declared_field.type)
            if dtypes:
                class_field_sequence_dtypes.setdefault(
                    (str(binding_name), str(declared_field.name)), dtypes,
                )
            note_sequence_element_class(
                str(binding_name), str(declared_field.name),
                declared_field.type,
            )
            row_record = _sequence_annotation_record(declared_field.type)
            if row_record is not None:
                class_field_sequence_records.setdefault(
                    (str(binding_name), str(declared_field.name)), row_record,
                )

    def aggregate_expression_kind(expression: ast.AST | None) -> str | None:
        if isinstance(expression, (ast.List, ast.ListComp)):
            return "list"
        if isinstance(expression, (ast.Set, ast.SetComp)):
            return "set"
        if isinstance(expression, (ast.Dict, ast.DictComp)):
            return "dict"
        if isinstance(expression, ast.Tuple):
            return "tuple"
        if (
            isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Name)
            and expression.func.id in {
                "list", "set", "frozenset", "dict", "tuple",
                "bytes", "bytearray",
            }
        ):
            return expression.func.id
        return None

    class_factory_aggregate_kinds: dict[tuple[str, str], str] = {}
    class_declared_field_aliases: set[tuple[str, str, str]] = set()
    class_field_value_aggregate_kinds: dict[tuple[str, str], str] = {}
    field_value_kind_conflicts: set[tuple[str, str]] = set()
    class_bases: dict[str, tuple[str, ...]] = {}
    for class_name, definition in class_definitions.items():
        class_bases[str(class_name)] = tuple(
            base.id for base in definition.bases if isinstance(base, ast.Name)
        )
        for member in definition.body:
            if not isinstance(member, (ast.Assign, ast.AnnAssign)):
                continue
            targets = (
                tuple(member.targets)
                if isinstance(member, ast.Assign)
                else (member.target,)
            )
            value = member.value
            if isinstance(value, ast.Name):
                for target in targets:
                    if isinstance(target, ast.Name) and target.id != value.id:
                        class_declared_field_aliases.add((
                            str(class_name), str(target.id), str(value.id)
                        ))
            kind = (
                value.id
                if isinstance(value, ast.Name)
                and value.id in {
                    "list", "set", "frozenset", "dict", "tuple",
                    "bytes", "bytearray",
                }
                else None
            )
            if kind is None:
                continue
            for target in targets:
                if isinstance(target, ast.Name):
                    class_factory_aggregate_kinds[(
                        str(class_name), str(target.id)
                    )] = kind
    for owner_name, owner_class in external_owner_classes.items():
        # Pursued external methods may arrive without their containing
        # ClassDef. Read the exact class and base-class source declarations so
        # class-level factories remain compiler facts. No class is
        # instantiated and no factory is called.
        for source_class in reversed(owner_class.__mro__):
            try:
                source = textwrap.dedent(inspect.getsource(source_class))
                parsed = ast.parse(source)
            except (OSError, TypeError, SyntaxError, IndentationError):
                continue
            definition = next(
                (
                    member for member in parsed.body
                    if isinstance(member, ast.ClassDef)
                ),
                None,
            )
            if definition is None:
                continue
            for member in definition.body:
                if not isinstance(member, (ast.Assign, ast.AnnAssign)):
                    continue
                targets = (
                    tuple(member.targets)
                    if isinstance(member, ast.Assign)
                    else (member.target,)
                )
                value = member.value
                if isinstance(value, ast.Name):
                    for target in targets:
                        if isinstance(target, ast.Name) and target.id != value.id:
                            class_declared_field_aliases.add((
                                str(owner_name), str(target.id), str(value.id)
                            ))
                kind = (
                    value.id
                    if isinstance(value, ast.Name)
                    and value.id in {
                        "list", "set", "frozenset", "dict", "tuple",
                        "array.array", "bytes", "bytearray",
                    }
                    else None
                )
                if kind is None:
                    continue
                for target in targets:
                    if isinstance(target, ast.Name):
                        class_factory_aggregate_kinds[(
                            str(owner_name), str(target.id)
                        )] = kind
            for source_member in ast.walk(definition):
                if isinstance(source_member, ast.Assign):
                    targets = tuple(source_member.targets)
                    value = source_member.value
                elif isinstance(source_member, ast.AnnAssign):
                    targets = (source_member.target,)
                    value = source_member.value
                    declared_target = source_member.target
                    declared_field = (
                        declared_target.id
                        if isinstance(declared_target, ast.Name)
                        else declared_target.attr
                        if (
                            isinstance(declared_target, ast.Attribute)
                            and isinstance(declared_target.value, ast.Name)
                            and declared_target.value.id in {"self", "cls"}
                        )
                        else None
                    )
                    if declared_field is not None:
                        held_class = declared_field_class(
                            source_member.annotation
                        )
                        if held_class is not None:
                            note_field_class(
                                str(owner_name), str(declared_field),
                                held_class,
                            )
                        storage = _annotation_storage(
                            source_member.annotation
                        )
                        if storage.get("dtype") is not None:
                            class_field_storage_contracts.setdefault(
                                (str(owner_name), str(declared_field)),
                                storage,
                            )
                        aggregate_kind = _aggregate_annotation_kind(
                            source_member.annotation
                        )
                        if aggregate_kind is not None:
                            class_field_aggregate_kinds.setdefault(
                                (str(owner_name), str(declared_field)),
                                aggregate_kind,
                            )
                        mapping_contract = _mapping_annotation(
                            source_member.annotation
                        )
                        if mapping_contract:
                            class_field_mapping_contracts.setdefault(
                                (str(owner_name), str(declared_field)),
                                mapping_contract,
                            )
                        sequence_dtypes = _sequence_annotation_dtypes(
                            source_member.annotation
                        )
                        if sequence_dtypes:
                            class_field_sequence_dtypes.setdefault(
                                (str(owner_name), str(declared_field)),
                                sequence_dtypes,
                            )
                        note_sequence_element_class(
                            str(owner_name), str(declared_field),
                            source_member.annotation,
                        )
                else:
                    continue
                outer_kind = aggregate_expression_kind(value)
                if (
                    outer_kind is None
                    and isinstance(value, ast.Call)
                    and isinstance(value.func, ast.Attribute)
                    and isinstance(value.func.value, ast.Name)
                    and value.func.value.id in {"self", "cls"}
                ):
                    outer_kind = class_factory_aggregate_kinds.get((
                        str(owner_name), str(value.func.attr)
                    ))
                alias_source = (
                    str(value.attr)
                    if (
                        isinstance(value, ast.Attribute)
                        and isinstance(value.value, ast.Name)
                        and value.value.id in {"self", "cls"}
                    )
                    else None
                )
                for target in targets:
                    if not (
                        isinstance(target, ast.Attribute)
                        and isinstance(target.value, ast.Name)
                        and target.value.id in {"self", "cls"}
                    ):
                        continue
                    if alias_source is not None:
                        pending = (
                            str(owner_name), str(target.attr), alias_source
                        )
                        if pending not in class_declared_field_aliases:
                            class_declared_field_aliases.add(pending)
                    target_kind = outer_kind
                    if target_kind is None:
                        from ...transmogrifier.graph.graph_express2 import (
                            _ast_aggregate_kind,
                            _class_field_reference,
                        )

                        target_kind = _ast_aggregate_kind(
                            _class_field_reference(
                                source_class, str(target.attr), frozenset()
                            )
                        )

                    if target_kind is not None:
                        class_field_aggregate_kinds.setdefault(
                            (str(owner_name), str(target.attr)), target_kind
                        )
                if not (
                    isinstance(value, ast.Call)
                    and isinstance(value.func, ast.Attribute)
                    and isinstance(value.func.value, ast.Name)
                    and value.func.value.id in {"self", "cls"}
                ):
                    continue
                value_kind = class_factory_aggregate_kinds.get((
                    str(owner_name), str(value.func.attr)
                ))
                if value_kind is None:
                    continue
                for target in targets:
                    if not (
                        isinstance(target, ast.Subscript)
                        and isinstance(target.value, ast.Attribute)
                        and isinstance(target.value.value, ast.Name)
                        and target.value.value.id in {"self", "cls"}
                    ):
                        continue
                    value_key = (
                        str(owner_name), str(target.value.attr)
                    )
                    previous = class_field_value_aggregate_kinds.setdefault(
                        value_key, value_kind
                    )
                    if previous != value_kind:
                        class_field_value_aggregate_kinds.pop(value_key, None)
                        field_value_kind_conflicts.add(value_key)
    changed = True
    while changed:
        changed = False
        for class_name, bases in class_bases.items():
            for base in bases:
                for (owner, factory), kind in tuple(
                    class_factory_aggregate_kinds.items()
                ):
                    if owner != base:
                        continue
                    key = (class_name, factory)
                    if key not in class_factory_aggregate_kinds:
                        class_factory_aggregate_kinds[key] = kind
                        changed = True

    field_kind_conflicts: set[tuple[str, str]] = set()
    class_field_aliases: dict[tuple[str, str], str] = {}
    pending_field_aliases: list[tuple[str, str, str]] = list(
        sorted(class_declared_field_aliases)
    )
    for class_name, definition in class_definitions.items():
        for member in definition.body:
            if not isinstance(member, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            for statement_member in source_walk(member):
                if (
                    isinstance(statement_member, ast.Call)
                    and isinstance(statement_member.func, ast.Attribute)
                    and statement_member.func.attr == "append"
                    and len(statement_member.args) == 1
                    and isinstance(statement_member.func.value, ast.Call)
                ):
                    default_call = statement_member.func.value
                    if (
                        isinstance(default_call.func, ast.Attribute)
                        and default_call.func.attr == "setdefault"
                        and isinstance(default_call.func.value, ast.Attribute)
                        and isinstance(default_call.func.value.value, ast.Name)
                        and default_call.func.value.value.id in {"self", "cls"}
                        and len(default_call.args) == 2
                        and isinstance(default_call.args[1], ast.List)
                        and not default_call.args[1].elts
                        and isinstance(statement_member.args[0], ast.Name)
                    ):
                        arguments = {a.arg: a.annotation for a in (*member.args.posonlyargs, *member.args.args, *member.args.kwonlyargs)}
                        annotation = arguments.get(statement_member.args[0].id)
                        row = _annotation_storage(annotation) if annotation is not None else {}
                        if row.get("dtype") in {"int64", "float64", "bool"} and row.get("aggregate_kind") is None:
                            if any(isinstance(part, ast.Name) and part.id == statement_member.args[0].id
                                   and isinstance(part.ctx, (ast.Store, ast.Del)) for part in source_walk(member)):
                                raise ValueError("mapping child append operand has a reassigned parameter binding; exact value evidence is required")
                            key = (str(class_name), str(default_call.func.value.attr))
                            contract = class_field_mapping_contracts.setdefault(key, {})
                            proposed = (str(row["dtype"]),)
                            incumbent = contract.get("mapping_child_column_dtypes")
                            if incumbent is not None and incumbent != proposed:
                                raise ValueError(f"mapping child writers disagree: {key!r}: {incumbent!r} != {proposed!r}")
                            contract["mapping_child_column_dtypes"] = proposed
                            contract["mapping_value_aggregate_kind"] = "list"
                # ``self.table.setdefault(k, []).append(v)`` writes the
                # same child-list contract as ``self.table[k] = []``.  The
                # old survey saw only assignments: readers in another
                # method therefore reconstructed a keyed child table.
                if (
                    isinstance(statement_member, ast.Call)
                    and isinstance(statement_member.func, ast.Attribute)
                    and statement_member.func.attr == "setdefault"
                    and isinstance(statement_member.func.value, ast.Attribute)
                    and isinstance(statement_member.func.value.value, ast.Name)
                    and statement_member.func.value.value.id in {"self", "cls"}
                    and len(statement_member.args) == 2
                ):
                    value_kind = aggregate_expression_kind(statement_member.args[1])
                    value_key = (str(class_name), str(statement_member.func.value.attr))
                    if value_kind is not None and value_key not in field_value_kind_conflicts:
                        incumbent = class_field_value_aggregate_kinds.setdefault(value_key, value_kind)
                        if incumbent != value_kind:
                            class_field_value_aggregate_kinds.pop(value_key, None)
                            field_value_kind_conflicts.add(value_key)
                        if isinstance(statement_member.args[0], ast.Tuple):
                            width = len(statement_member.args[0].elts)
                            if width:
                                contract = class_field_mapping_contracts.setdefault(value_key, {})
                                incumbent_width = contract.setdefault("mapping_key_column_count", width)
                                if incumbent_width != width:
                                    raise ValueError(f"mapping key writers disagree on tuple width: {value_key!r}")
                if isinstance(statement_member, ast.Assign):
                    targets = tuple(statement_member.targets)
                    value = statement_member.value
                elif isinstance(statement_member, ast.AnnAssign):
                    targets = (statement_member.target,)
                    value = statement_member.value
                else:
                    continue
                kind = aggregate_expression_kind(value)
                if kind is None and isinstance(value, ast.Name):
                    kind = local_aggregate_kinds_by_function.get(
                        id(member), {}
                    ).get(value.id)
                if (
                    kind is None
                    and isinstance(value, ast.Call)
                    and isinstance(value.func, ast.Attribute)
                    and isinstance(value.func.value, ast.Name)
                    and value.func.value.id in {"self", "cls"}
                ):
                    kind = class_factory_aggregate_kinds.get((
                        str(class_name), str(value.func.attr)
                    ))
                alias_source = (
                    str(value.attr)
                    if (
                        isinstance(value, ast.Attribute)
                        and isinstance(value.value, ast.Name)
                        and value.value.id in {"self", "cls"}
                    )
                    else None
                )
                if alias_source is not None:
                    for target in targets:
                        if (
                            isinstance(target, ast.Attribute)
                            and isinstance(target.value, ast.Name)
                            and target.value.id in {"self", "cls"}
                        ):
                            pending_field_aliases.append((
                                str(class_name),
                                str(target.attr),
                                alias_source,
                            ))
                if kind is None and alias_source is not None:
                    kind = class_field_aggregate_kinds.get((
                        str(class_name), alias_source
                    ))
                for target in targets:
                    if not (
                        isinstance(target, ast.Subscript)
                        and isinstance(target.value, ast.Attribute)
                        and isinstance(target.value.value, ast.Name)
                        and target.value.value.id in {"self", "cls"}
                    ):
                        continue
                    value_kind = aggregate_expression_kind(value)
                    if (
                        value_kind is None
                        and isinstance(value, ast.Call)
                        and isinstance(value.func, ast.Attribute)
                        and isinstance(value.func.value, ast.Name)
                        and value.func.value.id in {"self", "cls"}
                    ):
                        value_kind = class_factory_aggregate_kinds.get((
                            str(class_name), str(value.func.attr)
                        ))
                    if value_kind is None:
                        continue
                    value_key = (
                        str(class_name), str(target.value.attr)
                    )
                    previous_value_kind = (
                        class_field_value_aggregate_kinds.setdefault(
                            value_key, value_kind
                        )
                    )
                    if previous_value_kind != value_kind:
                        class_field_value_aggregate_kinds.pop(value_key, None)
                        field_value_kind_conflicts.add(value_key)
                if kind is None:
                    continue
                for target in targets:
                    if (
                        isinstance(target, ast.Attribute)
                        and isinstance(target.value, ast.Name)
                        and target.value.id in {"self", "cls"}
                    ):
                        key = (str(class_name), str(target.attr))
                        if key in field_kind_conflicts:
                            continue
                        previous = class_field_aggregate_kinds.setdefault(
                            key, kind
                        )
                        if previous != kind:
                            # Conflicting assignments deliberately erase the
                            # storage proof; no method spelling may restore it.
                            class_field_aggregate_kinds.pop(key, None)
                            field_kind_conflicts.add(key)
                        elif alias_source is not None:
                            class_field_aliases[key] = alias_source
    changed = True
    while changed:
        changed = False
        for class_name, alias, target in pending_field_aliases:
            alias_key = (class_name, alias)
            target_kind = class_field_aggregate_kinds.get((
                class_name, target
            ))
            if target_kind is None or alias_key in field_kind_conflicts:
                continue
            previous = class_field_aggregate_kinds.setdefault(
                alias_key, target_kind
            )
            if previous != target_kind:
                class_field_aggregate_kinds.pop(alias_key, None)
                class_field_aliases.pop(alias_key, None)
                field_kind_conflicts.add(alias_key)
                changed = True
            elif class_field_aliases.get(alias_key) != target:
                class_field_aliases[alias_key] = target
                changed = True
            target_value_kind = class_field_value_aggregate_kinds.get((
                class_name, target
            ))
            if (
                target_value_kind is not None
                and alias_key not in field_value_kind_conflicts
            ):
                value_kind_was_present = (
                    alias_key in class_field_value_aggregate_kinds
                )
                previous_value_kind = class_field_value_aggregate_kinds.setdefault(
                    alias_key, target_value_kind
                )
                if previous_value_kind != target_value_kind:
                    class_field_value_aggregate_kinds.pop(alias_key, None)
                    field_value_kind_conflicts.add(alias_key)
                elif not value_kind_was_present:
                    changed = True
    compile_substage("topology: declare authored functions")
    for node_id, data in graph.G.nodes(data=True):
        statement = data.get("expr_obj")
        if not is_runnable_definition(statement):
            continue
        function_name = runnable_definition_name(statement)
        owner_name = method_owners.get(node_id)

        def lexical_qualified_name(definition_id: int) -> str:
            definition = function_definitions[definition_id]
            identity = getattr(definition, "_python_source_identity", None)
            if isinstance(identity, tuple) and len(identity) == 2:
                module_name, python_qualified = map(str, identity)
                return ".".join(
                    part
                    for part in (module_name, python_qualified)
                    if part
                )
            parent_id = lexical_parent_by_function.get(definition_id)
            if parent_id is not None:
                return (
                    f"{lexical_qualified_name(parent_id)}.<locals>."
                    f"{getattr(definition, 'name', function_name)}"
                )
            method_owner = method_owners.get(definition_id)
            return (
                f"{method_owner}.{getattr(definition, 'name', function_name)}"
                if method_owner is not None
                else str(getattr(definition, "name", function_name))
            )

        qualified_name = lexical_qualified_name(node_id)
        reference = function_table.declare(
            function_name,
            qualified_name=qualified_name,
            source=_post_source_span(statement),
            metadata={
                "source_type": type(statement).__name__,
                "source_node": node_id,
                # A method is never a bare name's lexical callee
                # (``FunctionTable.lexical_reference``).
                **(
                    {"method_owner": str(method_owners[node_id])}
                    if method_owners.get(node_id) is not None
                    else {}
                ),
                # The authored (module, qualname) of a discovered
                # definition: two modules' same-named functions never share
                # it (``FunctionTable.reference_by_source_identity``).
                **(
                    {"source_identity": tuple(map(str, getattr(
                        function_definitions[node_id],
                        "_python_source_identity",
                    )))}
                    if isinstance(getattr(
                        function_definitions[node_id],
                        "_python_source_identity", None,
                    ), tuple)
                    and len(getattr(
                        function_definitions[node_id],
                        "_python_source_identity",
                    )) == 2
                    else {}
                ),
                **(
                    {
                        "process_graph_boundary": getattr(
                            statement,
                            "_process_graph_boundary",
                        )
                    }
                    if hasattr(statement, "_process_graph_boundary")
                    else {}
                ),
                **(
                    {
                        "host_ssa_module": getattr(
                            statement, "_linked_repository_ssa_module"
                        ),
                        "host_ssa_root": str(getattr(
                            statement, "_linked_repository_ssa_root"
                        )),
                        "host_ssa_outputs": dict(getattr(
                            statement, "_linked_repository_ssa_outputs", {}
                        )),
                        "host_repository_ssa_complete": True,
                        "host_machine_state_complete": False,
                        "host_ssa_blockers": (),
                        "host_ssa_hard_blockers": (),
                        "host_ssa_legalization_shortfalls": (),
                        "host_ssa_unresolved_dependencies": (),
                        "implementation_kind": "linked-repository-ssa",
                        "implementation_variants": ("repository-ssa",),
                    }
                    if hasattr(statement, "_linked_repository_ssa_module")
                    else {}
                ),
            },
        )
        boundary_callable = getattr(
            statement,
            "_process_graph_boundary_callable",
            None,
        )
        if boundary_callable is not None:
            function_table.resolve_callable(reference, boundary_callable)
        data.setdefault("attributes", {})[
            "function_ref"
        ] = reference.address
        function_nodes[node_id] = reference
        if isinstance(statement, ast.Lambda):
            # A lambda's body is one expression, not a list of statements,
            # and is itself the implicit return value -- no explicit
            # Return-shaped node exists to walk to. Python-only construct;
            # nothing here needs generalizing for another language.
            function_return_values[node_id] = [id(statement.body)]
        else:
            _record_owned_calls_and_returns(
                graph, reference, node_id, call_owners, function_return_values,
            )

    # Source-less host callables are not external runtime handlers.  Source
    # pursuit may attach a decompiled repository-SSA module to the exact Call;
    # give its root an ordinary FunctionTable reference so all later call and
    # module machinery sees the implementation as compiled interior code.
    compile_substage("topology: declare accepted native call references")
    for node_id, data in graph.G.nodes(data=True):
        expression = data.get("expr_obj")
        if not isinstance(expression, ast.Call):
            continue
        host_module = getattr(expression, "_host_ssa_module", None)
        host_root = getattr(expression, "_host_ssa_root", None)
        if host_module is None or host_root is None:
            continue
        if isinstance(expression.func, ast.Name):
            local_name = expression.func.id
        elif isinstance(expression.func, ast.Attribute):
            local_name = expression.func.attr
        else:
            local_name = str(host_root)
        reference = function_table.declare(
            local_name,
            qualified_name=f"host-ssa.{host_root}",
            source=_post_source_span(expression),
            metadata={
                "host_ssa_module": host_module,
                "host_ssa_root": str(host_root),
                "host_ssa_blockers": tuple(getattr(
                    expression, "_host_ssa_blockers", ()
                )),
                "host_ssa_raw_blockers": tuple(getattr(
                    expression, "_host_ssa_raw_blockers", ()
                )),
                "host_ssa_hard_blockers": tuple(getattr(
                    expression, "_host_ssa_hard_blockers", ()
                )),
                "host_ssa_legalization_shortfalls": tuple(getattr(
                    expression, "_host_ssa_legalization_shortfalls", ()
                )),
                "host_machine_state_complete": bool(getattr(
                    expression, "_host_machine_state_complete", False
                )),
                "host_machine_bodies_complete": bool(getattr(
                    expression, "_host_machine_bodies_complete", False
                )),
                "host_dependency_context_complete": bool(getattr(
                    expression, "_host_dependency_context_complete", False
                )),
                "host_repository_ssa_complete": bool(getattr(
                    expression, "_host_repository_ssa_complete", False
                )),
                "host_uses_machine_state_dialect": bool(getattr(
                    expression, "_host_uses_machine_state_dialect", False
                )),
                "host_native_module": getattr(
                    expression, "_host_native_module", None
                ),
                "host_ssa_cache_key": getattr(
                    expression, "_host_ssa_cache_key", None
                ),
                "host_ssa_cache_path": getattr(
                    expression, "_host_ssa_cache_path", None
                ),
                "host_ssa_cache_hit": bool(getattr(
                    expression, "_host_ssa_cache_hit", False
                )),
                "host_ssa_library_cache_keys": tuple(getattr(
                    expression, "_host_ssa_library_cache_keys", ()
                )),
                "host_ssa_library_cache_paths": tuple(getattr(
                    expression, "_host_ssa_library_cache_paths", ()
                )),
                "host_ssa_dependency_edges": tuple(getattr(
                    expression, "_host_ssa_dependency_edges", ()
                )),
                "host_ssa_unresolved_dependencies": tuple(getattr(
                    expression, "_host_ssa_unresolved_dependencies", ()
                )),
                "implementation_kind": "decompiled-host-ssa",
                "implementation_variants": tuple(
                    variant for variant, available in (
                        ("repository-ssa", bool(getattr(
                            expression, "_host_repository_ssa_complete", False
                        ))),
                        ("machine-state-ssa", bool(getattr(
                            expression, "_host_machine_state_complete", False
                        )) and bool(getattr(
                            expression, "_host_uses_machine_state_dialect", False
                        ))),
                        ("retained-native-module", getattr(
                            expression, "_host_native_module", None
                        ) is not None),
                    ) if available
                ),
            },
        )
        data.setdefault("attributes", {}).update({
            "callee_ref": int(reference.address),
            "host_ssa_root": str(host_root),
            "host_ssa_cache_key": getattr(
                expression, "_host_ssa_cache_key", None
            ),
            "host_ssa_blocker_count": len(tuple(getattr(
                expression, "_host_ssa_blockers", ()
            ))),
            "host_repository_ssa_complete": bool(getattr(
                expression, "_host_repository_ssa_complete", False
            )),
            "host_ssa_dependency_count": len(tuple(getattr(
                expression, "_host_ssa_dependency_edges", ()
            ))),
            "host_ssa_unresolved_dependency_count": len(tuple(getattr(
                expression, "_host_ssa_unresolved_dependencies", ()
            ))),
        })

    def class_field_defaults(definition: ast.ClassDef) -> dict[str, Any]:
        """Retain literal class-field defaults as structural compiler facts."""

        def is_literal(value: Any) -> bool:
            if value is None or isinstance(
                value,
                (bool, bytes, complex, float, int, str),
            ):
                return True
            if isinstance(value, (tuple, list)):
                return all(is_literal(item) for item in value)
            if isinstance(value, dict):
                return all(
                    is_literal(key) and is_literal(item)
                    for key, item in value.items()
                )
            return False

        defaults: dict[str, Any] = {}
        for member in definition.body:
            if not (
                isinstance(member, ast.AnnAssign)
                and isinstance(member.target, ast.Name)
                and member.value is not None
            ):
                continue
            try:
                value = ast.literal_eval(member.value)
            except (ValueError, TypeError, SyntaxError):
                continue
            if is_literal(value):
                defaults[member.target.id] = value
        return defaults

    def class_field_callables(definition: ast.ClassDef) -> dict[str, str]:
        """``field -> Callable annotation`` for fields that hold a callable.

        A field is a callable slot when its declaration says so: a class
        level ``f: Callable[...]``, ``self.f: Callable[...] = ...`` in
        ``__init__``, or ``self.f = p`` in ``__init__`` where ``p`` is a
        parameter annotated ``Callable[...]`` (``Optional``/``| None``
        included).
        Every declaring store must state the same annotation; a field with a
        store that states none, or a different one, is left out, so a call
        through it stays refused.
        """

        def callable_text(annotation: ast.AST | None) -> str | None:
            if annotation is None:
                return None
            if isinstance(annotation, ast.Constant) and isinstance(
                annotation.value, str,
            ):
                try:
                    annotation = ast.parse(annotation.value, mode="eval").body
                except SyntaxError:
                    return None
            text = ast.unparse(annotation)
            return text if "Callable" in {
                node.id if isinstance(node, ast.Name) else node.attr
                for node in ast.walk(annotation)
                if isinstance(node, (ast.Name, ast.Attribute))
            } else None

        stated: dict[str, set[str | None]] = {}
        for member in definition.body:
            if isinstance(member, ast.AnnAssign) and isinstance(
                member.target, ast.Name,
            ):
                stated.setdefault(member.target.id, set()).add(
                    callable_text(member.annotation)
                )
        for method in definition.body:
            if not isinstance(method, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            parameters = {
                argument.arg: argument.annotation
                for argument in (
                    *method.args.posonlyargs, *method.args.args,
                    *method.args.kwonlyargs,
                )
            }
            for statement in source_walk(method):
                # Only the constructor binds a callable slot: a store in any
                # other method would change, mid-object, the callable the
                # host supplies to each call.
                constructor = method.name == "__init__"
                if isinstance(statement, ast.AnnAssign):
                    targets = (statement.target,)
                    annotation = (
                        callable_text(statement.annotation)
                        if constructor else None
                    )
                elif isinstance(statement, ast.Assign):
                    targets = tuple(statement.targets)
                    annotation = (
                        callable_text(parameters.get(statement.value.id))
                        if constructor and isinstance(statement.value, ast.Name)
                        else None
                    )
                else:
                    continue
                for target in targets:
                    if (
                        isinstance(target, ast.Attribute)
                        and isinstance(target.value, ast.Name)
                        and target.value.id == "self"
                    ):
                        stated.setdefault(target.attr, set()).add(annotation)
        return {
            name: next(iter(annotations))
            for name, annotations in stated.items()
            if len(annotations) == 1 and None not in annotations
        }

    graph.G.graph["class_table"] = {
        class_name: {
            "methods": {
                member.name: function_nodes[id(member)].address
                for member in definition.body
                if isinstance(member, (ast.FunctionDef, ast.AsyncFunctionDef))
                and id(member) in function_nodes
            },
            "fields": tuple(
                dict.fromkeys((
                    *(
                        member.target.id
                        for member in definition.body
                        if isinstance(member, ast.AnnAssign)
                        and isinstance(member.target, ast.Name)
                    ),
                    *(
                        target.attr
                        for member in definition.body
                        if isinstance(
                            member,
                            (ast.FunctionDef, ast.AsyncFunctionDef),
                        )
                        for target in source_walk(member)
                        if isinstance(target, ast.Attribute)
                        and isinstance(target.ctx, ast.Store)
                        and isinstance(target.value, ast.Name)
                        and target.value.id in {"self", "cls"}
                    ),
                    *(
                        field_name
                        for (owner, field_name), _kind
                        in class_field_aggregate_kinds.items()
                        if owner == class_name
                    ),
                ))
            ),
            # An omitted dataclass/class field is not an unknown shell input.
            # Its source-level literal default is part of the class schema,
            # just like the field order.  Preserve only literal data here:
            # arbitrary Python objects and executable default factories remain
            # unresolved and must be represented by ordinary graph structure.
            "field_defaults": class_field_defaults(definition),
            "field_classes": {
                field_name: held_class
                for (owner, field_name), held_class
                in class_field_classes.items()
                if owner == class_name
            },
            "field_callables": class_field_callables(definition),
        }
        for class_name, definition in class_definitions.items()
    }
    def _resolve_python_bindings():
        """Resolve the authored imports into ``graph.python_bindings``
        (and the contextual requirements): run once before the
        module-level page declarations are read (an imported page
        factory is bound here) and again at the static-binding stage.
        Returns the import bindings by local name and the static bindings."""

        compile_substage("topology: resolve imports and lexical static bindings")
        contextual_requirements = list(
            graph.G.graph.get("contextual_requirements", ())
        )
        # local name -> (qualified name, imported name, requirement, the import
        # statement's ``source_span`` cell)
        import_bindings: dict[
            str,
            tuple[str, str, dict[str, Any], Any],
        ] = {}
        for node_id, data in graph.G.nodes(data=True):
            statement = data.get("expr_obj")
            if not isinstance(statement, (ast.Import, ast.ImportFrom)):
                continue
            requirement = {
                "kind": (
                    "import_from"
                    if isinstance(statement, ast.ImportFrom)
                    else "import"
                ),
                "module": (
                    statement.module
                    if isinstance(statement, ast.ImportFrom)
                    else None
                ),
                "level": (
                    int(statement.level)
                    if isinstance(statement, ast.ImportFrom)
                    else 0
                ),
                "names": tuple(
                    (imported.name, imported.asname)
                    for imported in statement.names
                ),
            }
            if requirement not in contextual_requirements:
                contextual_requirements.append(requirement)
            data.setdefault("attributes", {})[
                "contextual_requirement"
            ] = requirement
            for imported in statement.names:
                local_name = imported.asname or imported.name.split(".")[0]
                if isinstance(statement, ast.ImportFrom):
                    module = "." * int(statement.level) + (
                        statement.module or ""
                    )
                    qualified_name = (
                        f"{module}.{imported.name}"
                        if module
                        else imported.name
                    )
                else:
                    qualified_name = imported.name
                # The import statement's span cell: the source an external
                # declaration made for this binding derives from.
                import_bindings[local_name] = (
                    qualified_name,
                    imported.name,
                    requirement,
                    _post_source_span(statement),
                )
                imported_id = id(imported)
                if imported_id in graph.G:
                    graph.G.nodes[imported_id].setdefault("attributes", {})[
                        "contextual_requirement"
                    ] = requirement
            logger.info(
                "retaining ProcessGraph import as a contextual requirement: %s",
                requirement,
            )
        graph.G.graph["contextual_requirements"] = tuple(
            contextual_requirements
        )
        static_bindings = dict(getattr(graph, "python_bindings", {}) or {})
        # Parent-source expansion is optional, but literal module constants are
        # required static bindings in either ingestion mode.  Recover only
        # assignments outside function/class bodies; locals remain SSA values.
        scoped_member_ids = {
            id(member)
            for _owner_id, owner_data in graph.G.nodes(data=True)
            for owner in (owner_data.get("expr_obj"),)
            if isinstance(
                owner,
                (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda),
            )
            for member in source_walk(owner)
            if member is not owner
        }
        for _node_id, node_data in graph.G.nodes(data=True):
            expression = node_data.get("expr_obj")
            if id(expression) in scoped_member_ids:
                continue
            if isinstance(expression, ast.Assign):
                targets = expression.targets
                value_node = expression.value
            elif isinstance(expression, ast.AnnAssign):
                targets = (expression.target,)
                value_node = expression.value
            else:
                continue
            if value_node is None:
                continue
            try:
                literal = ast.literal_eval(value_node)
            except (TypeError, ValueError, SyntaxError):
                if not (
                    isinstance(value_node, ast.Call)
                    and isinstance(value_node.func, ast.Name)
                    and value_node.func.id in {
                        "tuple", "list", "set", "frozenset", "dict",
                    }
                    and not value_node.keywords
                    and len(value_node.args) <= 1
                ):
                    continue
                try:
                    argument = (
                        () if not value_node.args
                        else ast.literal_eval(value_node.args[0])
                    )
                    literal = {
                        "tuple": tuple,
                        "list": list,
                        "set": set,
                        "frozenset": frozenset,
                        "dict": dict,
                    }[value_node.func.id](argument)
                except (TypeError, ValueError, SyntaxError):
                    continue
            for target in targets:
                if isinstance(target, ast.Name):
                    static_bindings[target.id] = literal
        python_package = getattr(graph, "python_package", None)
        for local_name, (
            qualified_name,
            imported_name,
            requirement,
            _import_cell,
        ) in import_bindings.items():
            try:
                if requirement["kind"] == "import_from":
                    module_name = (
                        "." * int(requirement.get("level", 0))
                        + str(requirement.get("module") or "")
                    )
                    module = importlib.import_module(
                        module_name,
                        package=python_package,
                    )
                    static_bindings[local_name] = getattr(
                        module,
                        imported_name,
                    )
                elif requirement["kind"] == "import":
                    static_bindings[local_name] = importlib.import_module(
                        qualified_name,
                        package=python_package,
                    )
            except (ImportError, AttributeError, TypeError, ValueError):
                # The contextual requirement remains available to deployment even
                # when it cannot be resolved in the compiler's current process.
                continue
        for builtin_name, value in vars(builtins).items():
            static_bindings.setdefault(builtin_name, value)
        graph.python_bindings = static_bindings
        return import_bindings, static_bindings

    _resolve_python_bindings()
    # Import resolution above is the first point at which an authored
    # external dataclass is guaranteed to be present in ``python_bindings``.
    # The earlier schema survey also accepts pre-bound classes, but an
    # ordinary ``from ... import Metrics`` reaches the compiler here.  Index
    # its declared sequence element class now, before function graphs read
    # record fields; the field declaration remains the provenance cell used
    # by ``_normalize_lexical_values``.
    for binding_name, bound_value in dict(
        getattr(graph, "python_bindings", {}) or {}
    ).items():
        if not isinstance(bound_value, type) or not is_dataclass(bound_value):
            continue
        for declared_field in fields(bound_value):
            factory = declared_field.default_factory
            aggregate_kind = next((
                kind.__name__
                for kind in (
                    list, set, frozenset, dict, tuple, bytes, bytearray,
                )
                if factory is kind
            ), None)
            if aggregate_kind is None:
                aggregate_kind = next((
                    kind.__name__
                    for kind in (
                        list, set, frozenset, dict, tuple, bytes, bytearray,
                    )
                    if type(declared_field.default) is kind
                ), None)
            annotation_kind = _aggregate_annotation_kind(
                declared_field.type
            )
            if annotation_kind is not None:
                aggregate_kind = annotation_kind
            key = (str(binding_name), str(declared_field.name))
            if aggregate_kind is not None:
                class_field_aggregate_kinds.setdefault(key, aggregate_kind)
            dtypes = _sequence_annotation_dtypes(declared_field.type)
            if dtypes:
                class_field_sequence_dtypes.setdefault(key, dtypes)
            row_record = _sequence_annotation_record(declared_field.type)
            if row_record is not None:
                class_field_sequence_records.setdefault(key, row_record)
            try:
                annotation_node = (
                    declared_field.type
                    if isinstance(declared_field.type, ast.AST)
                    else ast.parse(
                        str(declared_field.type), mode="eval"
                    ).body
                )
            except SyntaxError:
                annotation_node = None
            if annotation_node is not None:
                storage = _annotation_storage(annotation_node)
                if storage.get("dtype") is not None:
                    class_field_storage_contracts.setdefault(key, storage)
            note_sequence_element_class(
                str(binding_name), str(declared_field.name),
                declared_field.type,
            )
    # A named concordance page declares the class of every fact it can hold.
    # Retain that source relation before function subgraphs split away from
    # the module-level ``declare_page`` call.  A later ``book.borrowed(name)``
    # read can then carry the exact page fact class through ``latest`` without
    # guessing from the local variable spelling.
    declared_page_fact_classes: dict[
        str, tuple[str, _Ref, tuple[tuple[str, str], ...]]
    ] = {}
    declared_page_bindings: dict[str, _Ref] = {}
    declaration_book = current_identity_book()
    # The page factory and its row-field classes may be present only by
    # reference -- an import this reduction resolved into
    # ``python_bindings``, not source submitted to the compile.  Their
    # declarations are then ingested by reference, as a class field's
    # constructor is, before the exact cells are read below.
    factory_module_identity = "src.compiler.identity_concordance"
    bound_page_factory = next((
        value for value in (getattr(graph, "python_bindings", {}) or {}).values()
        if inspect.ismethod(value)
        and getattr(value.__func__, "__module__", "") == factory_module_identity
        and getattr(value.__func__, "__qualname__", "") == "Registry.declare_page"
    ), None)
    if bound_page_factory is not None:
        from ...transmogrifier.graph.graph_express2 import (
            ingest_class_declaration_by_reference,
        )

        factory_module = inspect.getmodule(bound_page_factory.__func__)
        for factory_class_name in ("Registry", "RowField", "RowFieldKind"):
            if declaration_book.latest_ref(
                _CLASS_DECLARATION,
                (factory_module_identity, factory_class_name),
            ) is None:
                ingest_class_declaration_by_reference(
                    getattr(factory_module, factory_class_name, None),
                )
    row_field_class_cell = declaration_book.latest_ref(
        _CLASS_DECLARATION,
        ("src.compiler.identity_concordance", "RowField"),
    )
    row_kind_class_cell = declaration_book.latest_ref(
        _CLASS_DECLARATION,
        ("src.compiler.identity_concordance", "RowFieldKind"),
    )
    row_kind_enum_cell = declaration_book.latest_ref(
        _SOURCE_ENUM_GLYPH_TABLE,
        ("src.compiler.identity_concordance", "RowFieldKind"),
    )
    builtin_fact_types = frozenset({
        "bool", "bytearray", "bytes", "complex", "dict", "float",
        "frozenset", "int", "list", "object", "set", "str", "tuple",
    })

    page_factory_identity = (
        "src.compiler.identity_concordance",
        "Registry.declare_page",
        "src.compiler.identity_concordance.Registry",
    )

    def exact_page_factory_method_cell() -> _Ref | None:
        """The authored signature behind the exported bound page factory."""

        return declaration_book.latest_ref(
            _CLASS_METHOD_DECLARATION,
            (
                "src.compiler.identity_concordance",
                "Registry", "declare_page",
            ),
        )

    def exact_page_factory_definition_cell() -> _Ref | None:
        """Return/post the canonical callable identity from its method cell."""

        method_cell = exact_page_factory_method_cell()
        if method_cell is None:
            return None
        incumbent = declaration_book.latest_ref(
            _STATIC_SYMBOL_DEFINITION, page_factory_identity,
        )
        if incumbent is not None:
            fact = declaration_book.page(
                _STATIC_SYMBOL_DEFINITION
            ).cell(incumbent.row, incumbent.column)
            return declaration_book.post(
                _STATIC_SYMBOL_DEFINITION,
                page_factory_identity, fact,
                stage=_REDUCTION,
                provenance=_Derived((method_cell,)),
                mode=_Mode.CONCORD,
            )
        return declaration_book.post(
            _STATIC_SYMBOL_DEFINITION,
            page_factory_identity,
            _StaticSymbolFact(_StaticSymbolKind.BOUND_METHOD, None),
            stage=_REDUCTION,
            provenance=_Derived((method_cell,)),
            mode=_Mode.CONCORD,
        )

    def page_factory_parameters(
        definition_cell: _Ref | None,
    ) -> tuple[str, ...]:
        """Read the exact source method signature for a proven factory."""

        if (
            not isinstance(definition_cell, _Ref)
            or definition_cell.page != _STATIC_SYMBOL_DEFINITION
            or tuple(definition_cell.row) != page_factory_identity
            or declaration_book.latest_ref(
                _STATIC_SYMBOL_DEFINITION, definition_cell.row,
            ) != definition_cell
        ):
            return ()
        method_cell = exact_page_factory_method_cell()
        if method_cell is None:
            return ()
        method = declaration_book.page(
            _CLASS_METHOD_DECLARATION
        ).cell(method_cell.row, method_cell.column)
        parameters = tuple(getattr(method, "parameters", ()) or ())
        return tuple(map(str, parameters[1:])) if parameters else ()

    def bind_page_factory_arguments(
        declaration: ast.Call, parameters: tuple[str, ...],
    ) -> dict[str, ast.AST]:
        """Bind syntax through the factory's authored parameter ABI."""

        if not parameters:
            return {}
        bound: dict[str, ast.AST] = {}
        for index, argument in enumerate(declaration.args):
            if index >= len(parameters):
                return {}
            bound[parameters[index]] = argument
        for keyword in declaration.keywords:
            if keyword.arg is None or keyword.arg not in parameters:
                return {}
            if keyword.arg in bound:
                return {}
            bound[str(keyword.arg)] = keyword.value
        return bound

    def graph_call_definition_cell(
        declaration_node_id: int,
    ) -> _Ref | None:
        """Follow the exact callee node's concordance edge to its symbol."""

        call_data = graph.G.nodes[int(declaration_node_id)]
        # ``callee`` is the reducer's role for the position; a module-level
        # call the reduction never visited still carries ingestion's ``func``.
        callee_ids = tuple(
            int(parent) for parent, role in call_data.get("parents") or ()
            if str(role) in {"callee", "func"} and int(parent) in graph.G
        )
        if len(callee_ids) != 1:
            return None
        callee_cell = node_identity_cell(graph, callee_ids[0])
        if callee_cell is None:
            return None
        direct = tuple(
            source for source, _stage in declaration_book.edges_into(
                callee_cell
            )
            if source.page == _STATIC_SYMBOL_DEFINITION
            and tuple(source.row) == page_factory_identity
        )
        if len(direct) == 1:
            return direct[0]
        if direct:
            return None
        # A module-level callee name the reduction never turned into a
        # StaticReference: when the import bound it to the page factory,
        # the callee node derives from the factory's definition cell (the
        # same edge a StaticReference node carries from its mint).
        expression = graph.G.nodes[callee_ids[0]].get("expr_obj")
        bound = (
            (getattr(graph, "python_bindings", {}) or {}).get(expression.id)
            if isinstance(expression, ast.Name) else None
        )
        if bound is not bound_page_factory or bound is None:
            return None
        definition_cell = exact_page_factory_definition_cell()
        if definition_cell is None:
            return None
        fact = declaration_book.page(callee_cell.page).cell(
            callee_cell.row, callee_cell.column,
        )
        declaration_book.post(
            callee_cell.page, callee_cell.row, fact, stage=_REDUCTION,
            provenance=_Derived((callee_cell, definition_cell)),
            mode=_Mode.REVISE,
        )
        return definition_cell

    def exact_fact_class(
        expression: ast.AST, module_identity: str,
        *, local_classes: Mapping[str, ast.ClassDef],
        imported_owner: Callable[[str], tuple[str, str] | None] | None = None,
    ) -> tuple[str, _Ref] | None:
        """Resolve one Page fact class to its exact definition cell."""

        spelling = authored_page_fact_identity(expression)
        if spelling is None:
            return None
        if isinstance(expression, ast.Name) and expression.id in builtin_fact_types:
            identity = f"builtins.{expression.id}"
            span = _post_source_span(expression)
            if span is None:
                return None
            row = ("builtins", str(expression.id), "")
            cell = declaration_book.latest_ref(
                _STATIC_SYMBOL_DEFINITION, row,
            )
            if cell is None:
                cell = declaration_book.post(
                    _STATIC_SYMBOL_DEFINITION, row,
                    _StaticSymbolFact(_StaticSymbolKind.CLASS, None),
                    stage=_REDUCTION,
                    provenance=_Derived((span,)), mode=_Mode.CONCORD,
                )
            else:
                fact = declaration_book.page(
                    _STATIC_SYMBOL_DEFINITION
                ).cell(cell.row, cell.column)
                cell = declaration_book.post(
                    _STATIC_SYMBOL_DEFINITION, row, fact,
                    stage=_REDUCTION,
                    provenance=_Derived((span,)), mode=_Mode.CONCORD,
                )
            return identity, cell
        owner = None
        if isinstance(expression, ast.Name) and expression.id in local_classes:
            owner = (module_identity, str(expression.id))
        elif imported_owner is not None:
            owner = imported_owner(str(spelling))
        if owner is None:
            return None
        cell = declaration_book.latest_ref(_CLASS_DECLARATION, tuple(owner))
        return (
            (".".join(map(str, owner)), cell)
            if cell is not None else None
        )

    def authored_page_fact_identity(expression: ast.AST) -> str | None:
        """Canonical fact identity stated by a ``declare_page`` call.

        Builtin fact types have no source-local ``ClassDef`` to cite, but the
        authored AST still names their canonical definition.  This allowlist
        is the language's builtin namespace, not inspection of a live object.
        User/imported types retain their source spelling until their exact
        CLASS_DECLARATION edge resolves the definition owner.
        """

        if isinstance(expression, ast.Name):
            return (
                f"builtins.{expression.id}"
                if expression.id in builtin_fact_types
                else str(expression.id)
            )
        if isinstance(expression, ast.Attribute):
            owner = authored_page_fact_identity(expression.value)
            return (
                str(expression.attr)
                if owner is None else f"{owner}.{expression.attr}"
            )
        return None

    def exact_import_identity(
        statements: Iterable[ast.AST], module_identity: str, binding: str,
    ) -> tuple[str, str] | None:
        """Resolve one lexical import without loading its Python object."""

        head, dot, tail = str(binding).partition(".")
        for statement in statements:
            if isinstance(statement, ast.ImportFrom):
                alias = next((
                    item for item in statement.names
                    if str(item.asname or item.name) == head
                ), None)
                if alias is None:
                    continue
                module_parts = str(module_identity).split(".")
                level = int(statement.level or 0)
                owner_parts = module_parts[:-level] if level else []
                if statement.module:
                    owner_parts.extend(str(statement.module).split("."))
                identity = str(alias.name)
                if dot:
                    identity = f"{identity}.{tail}"
                return ".".join(owner_parts), identity
            if isinstance(statement, ast.Import):
                alias = next((
                    item for item in statement.names
                    if str(item.asname or item.name.split(".")[0]) == head
                ), None)
                if alias is None:
                    continue
                return str(alias.name), str(tail or alias.name.rsplit(".", 1)[-1])
        return None

    def authored_row_kind_aliases(
        statements: Iterable[ast.AST], module_identity: str,
    ) -> dict[str, str]:
        """RowFieldKind aliases proven by the exact imported enum."""

        statements = tuple(statements)
        aliases: dict[str, str] = {}
        for statement in statements:
            if not isinstance(statement, (ast.Assign, ast.AnnAssign)):
                continue
            targets = (
                tuple(statement.targets)
                if isinstance(statement, ast.Assign)
                else (statement.target,)
            )
            value = statement.value
            if not isinstance(value, ast.Attribute):
                continue
            owner = authored_page_fact_identity(value.value)
            if owner is None or exact_import_identity(
                statements, module_identity, owner,
            ) != (
                "src.compiler.identity_concordance", "RowFieldKind",
            ):
                continue
            for target in targets:
                if isinstance(target, ast.Name):
                    aliases[str(target.id)] = str(value.attr)
        return aliases

    def authored_row_kind(
        expression: ast.AST, aliases: Mapping[str, str],
        statements: Iterable[ast.AST], module_identity: str,
    ) -> str | None:
        def admitted(member: str) -> str | None:
            if row_kind_enum_cell is None:
                return None
            table = declaration_book.page(
                _SOURCE_ENUM_GLYPH_TABLE
            ).cell(row_kind_enum_cell.row, row_kind_enum_cell.column)
            return (
                str(member)
                if any(
                    str(getattr(item, "member_identity", ""))
                    == str(member)
                    for item in getattr(table, "members", ())
                ) else None
            )

        if isinstance(expression, ast.Attribute):
            owner = authored_page_fact_identity(expression.value)
            if owner is not None and exact_import_identity(
                statements, module_identity, owner,
            ) == (
                "src.compiler.identity_concordance", "RowFieldKind",
            ):
                return admitted(str(expression.attr))
        if isinstance(expression, ast.Name):
            member = aliases.get(str(expression.id))
            return None if member is None else admitted(str(member))
        return None

    def is_exact_row_field_constructor(
        expression: ast.AST,
        statements: Iterable[ast.AST], module_identity: str,
    ) -> bool:
        if not isinstance(expression, ast.Call):
            return False
        binding = authored_page_fact_identity(expression.func)
        return binding is not None and exact_import_identity(
            statements, module_identity, binding,
        ) == ("src.compiler.identity_concordance", "RowField")

    local_statements = tuple(
        statement_data.get("expr_obj")
        for _statement_id, statement_data in graph.G.nodes(data=True)
        if isinstance(statement_data.get("expr_obj"), ast.AST)
    )
    local_source_modules = tuple(dict.fromkeys(
        str(row[0]) for statement in local_statements
        for row in (getattr(statement, "_turing_source_span_row", None),)
        if isinstance(row, tuple) and row
    ))
    local_module_identity = (
        local_source_modules[0] if len(local_source_modules) == 1 else ""
    )
    # Publish authored inheritance once, beside the class declarations that
    # establish both identities.  Native ``isinstance`` consumes this page;
    # it must never reproduce Python's hierarchy in a predicate helper.
    if local_module_identity:
        from ...compiler.concordance_declarations import (
            ensure_builtin_class_topology as _ensure_builtin_class_topology,
        )

        _ensure_builtin_class_topology(declaration_book)
        builtin_names = {
            "bool", "bytearray", "bytes", "complex", "dict", "float",
            "frozenset", "int", "list", "object", "set", "str", "tuple",
        }
        for class_name, authored_bases in class_bases.items():
            derived_identity = f"{local_module_identity}.{class_name}"
            derived_cell = declaration_book.latest_ref(
                _CLASS_DECLARATION,
                (local_module_identity, str(class_name)),
            )
            if derived_cell is None:
                continue
            bases = tuple(authored_bases) or ("object",)
            for base_name in bases:
                local_base_cell = declaration_book.latest_ref(
                    _CLASS_DECLARATION,
                    (local_module_identity, str(base_name)),
                )
                builtin_base_cell = declaration_book.latest_ref(
                    _STATIC_SYMBOL_DEFINITION,
                    ("builtins", str(base_name), ""),
                )
                if local_base_cell is not None:
                    base_identity = (
                        f"{local_module_identity}.{base_name}"
                    )
                    sources = (derived_cell, local_base_cell)
                elif (
                    str(base_name) in builtin_names
                    and builtin_base_cell is not None
                ):
                    base_identity = f"builtins.{base_name}"
                    sources = (derived_cell, builtin_base_cell)
                else:
                    # Imported/qualified bases require their exact resolved
                    # declaration edge.  A bare spelling is not identity
                    # evidence and is intentionally not published.
                    continue
                row = (derived_identity, base_identity)
                declaration_book.post(
                    _CLASS_SUBTYPE, row, row, stage=_REDUCTION,
                    provenance=_Derived(sources), mode=_Mode.CONCORD,
                )
    def exact_class_field_order(
        class_cell: _Ref | None,
    ) -> tuple[str, ...]:
        """Read dataclass field order through declaration provenance edges."""

        if (
            not isinstance(class_cell, _Ref)
            or class_cell.page != _CLASS_DECLARATION
            or declaration_book.latest_ref(
                _CLASS_DECLARATION, class_cell.row,
            ) != class_cell
        ):
            return ()
        field_cells = tuple(
            source for source, _stage in declaration_book.edges_into(
                class_cell
            )
            if source.page == _CLASS_FIELD_DECLARATION
            and tuple(source.row[:2]) == tuple(class_cell.row)
            and declaration_book.latest_ref(
                _CLASS_FIELD_DECLARATION, source.row,
            ) == source
        )
        ordered: list[tuple[tuple[tuple[int, object], ...], str]] = []
        for field_cell in field_cells:
            spans = tuple(
                source for source, _stage in declaration_book.edges_into(
                    field_cell
                )
                if source.page == _SOURCE_SPAN
                and tuple(source.row[:2]) == tuple(class_cell.row)
            )
            if len(spans) != 1:
                return ()
            path = tuple(spans[0].row[2])
            order_key = tuple(
                (0, int(component))
                if isinstance(component, int) and not isinstance(component, bool)
                else (1, str(component))
                for component in path
            )
            ordered.append((order_key, str(field_cell.row[2])))
        ordered.sort(key=lambda item: item[0])
        return tuple(field_name for _path, field_name in ordered)

    row_field_parameter_names = exact_class_field_order(
        row_field_class_cell
    )

    def bind_row_field_arguments(
        expression: ast.Call,
    ) -> dict[str, ast.AST]:
        bound: dict[str, ast.AST] = {}
        for index, argument in enumerate(expression.args):
            if index >= len(row_field_parameter_names):
                return {}
            bound[row_field_parameter_names[index]] = argument
        for keyword in expression.keywords:
            if (
                keyword.arg is None
                or keyword.arg not in row_field_parameter_names
                or keyword.arg in bound
            ):
                return {}
            bound[str(keyword.arg)] = keyword.value
        return bound

    local_row_kind_aliases = authored_row_kind_aliases(
        local_statements, local_module_identity,
    )

    graph_page_bindings = {
        id(statement.value): str(target.id)
        for _statement_id, statement_data in graph.G.nodes(data=True)
        for statement in (statement_data.get("expr_obj"),)
        if isinstance(statement, (ast.Assign, ast.AnnAssign))
        and statement.value is not None
        for target in (
            tuple(statement.targets)
            if isinstance(statement, ast.Assign)
            else (statement.target,)
        )
        if isinstance(target, ast.Name)
    }
    for declaration_node_id, declaration_data in graph.G.nodes(data=True):
        declaration = declaration_data.get("expr_obj")
        definition_cell = (
            graph_call_definition_cell(int(declaration_node_id))
            if isinstance(declaration, ast.Call) else None
        )
        semantic_arguments = (
            bind_page_factory_arguments(
                declaration, page_factory_parameters(definition_cell),
            )
            if isinstance(declaration, ast.Call) else {}
        )
        page_name_expression = semantic_arguments.get("name")
        row_field_expression = semantic_arguments.get("row_fields")
        fact_type_expression = semantic_arguments.get("fact_type")
        if not (
            isinstance(declaration, ast.Call)
            and definition_cell is not None
            and isinstance(page_name_expression, ast.Constant)
            and isinstance(page_name_expression.value, str)
            and isinstance(row_field_expression, (ast.Tuple, ast.List))
            and fact_type_expression is not None
        ):
            continue
        source_span_row = getattr(
            declaration, "_turing_source_span_row", None,
        )
        module_identity = str(
            source_span_row[0]
            if isinstance(source_span_row, tuple) and source_span_row
            else getattr(declaration, "_turing_source_module", "")
        )
        class_resolution = exact_fact_class(
            fact_type_expression, module_identity,
            local_classes=class_definitions,
            imported_owner=lambda binding: exact_import_identity(
                local_statements, module_identity, binding,
            ),
        )
        if class_resolution is None:
            continue
        class_identity, class_cell = class_resolution
        page_name = str(page_name_expression.value)
        row_fields: list[tuple[str, str]] = []
        row_field_cells: list[_Ref] = []
        for field_declaration in (
            row_field_expression.elts
            if isinstance(row_field_expression, (ast.Tuple, ast.List))
            else ()
        ):
            field_arguments = (
                bind_row_field_arguments(field_declaration)
                if isinstance(field_declaration, ast.Call) else {}
            )
            field_name_expression = field_arguments.get("name")
            field_kind_expression = field_arguments.get("kind")
            if not (
                isinstance(field_declaration, ast.Call)
                and row_field_class_cell is not None
                and row_kind_class_cell is not None
                and row_kind_enum_cell is not None
                and is_exact_row_field_constructor(
                    field_declaration,
                    local_statements, module_identity,
                )
                and isinstance(field_name_expression, ast.Constant)
                and isinstance(field_name_expression.value, str)
                and field_kind_expression is not None
                and authored_row_kind(
                    field_kind_expression, local_row_kind_aliases,
                    local_statements, module_identity,
                ) is not None
            ):
                row_fields = []
                row_field_cells = []
                break
            row_fields.append((
                str(field_name_expression.value),
                str(authored_row_kind(
                    field_kind_expression, local_row_kind_aliases,
                    local_statements, module_identity,
                )),
            ))
            row_field_cells.extend(filter(None, (
                row_field_class_cell,
                row_kind_class_cell,
                row_kind_enum_cell,
                node_identity_cell(graph, id(field_declaration)),
                node_identity_cell(graph, id(field_name_expression)),
                node_identity_cell(graph, id(field_kind_expression)),
            )))
        if not row_fields:
            continue
        call_cell = node_identity_cell(graph, int(declaration_node_id))
        page_name_cell = node_identity_cell(
            graph, id(page_name_expression),
        )
        fact_type_cell = node_identity_cell(
            graph, id(fact_type_expression),
        )
        source_ast_nodes: list[ast.AST] = [
            declaration, page_name_expression, fact_type_expression,
        ]
        for field_declaration in (
            row_field_expression.elts
            if isinstance(row_field_expression, (ast.Tuple, ast.List))
            else ()
        ):
            field_arguments = (
                bind_row_field_arguments(field_declaration)
                if isinstance(field_declaration, ast.Call) else {}
            )
            source_ast_nodes.extend((
                field_declaration,
                *tuple(filter(None, (
                    field_arguments.get("name"),
                    field_arguments.get("kind"),
                ))),
            ))
        source_span_cells = tuple(dict.fromkeys(filter(None, (
            _post_source_span(source_node)
            for source_node in source_ast_nodes
        ))))
        sources = tuple(dict.fromkeys(filter(None, (
            definition_cell, class_cell, fact_type_cell,
            page_name_cell, call_cell,
            *row_field_cells, *source_span_cells,
        ))))
        if not sources:
            continue
        page_cell = declaration_book.post(
            _SOURCE_PAGE_FACT_CLASS,
            (module_identity, page_name),
            _SourcePageFactClass(
                page_name, class_identity, tuple(row_fields),
            ),
            stage=_REDUCTION,
            provenance=_Derived(sources),
            mode=_Mode.CONCORD,
        )
        declared_page_fact_classes[page_name] = (
            class_identity, page_cell, tuple(row_fields),
        )
        binding_name = graph_page_bindings.get(id(declaration))
        if binding_name is not None:
            declared_page_bindings[binding_name] = page_cell

    # An ExtractionContract ``with_sources`` entry is authored source even
    # when source pursuit needs none of its executable function bodies.  Page
    # constants are module-level declarations, so callable-only pursuit could
    # never discover them and their imported uses degraded to live-Python
    # external Inputs.  Publish those exact declarations from their admitted
    # ASTs into the same IdentityBook.  The fact derives from the class,
    # declaration call, page-name, and RowField source spans; no live Page is
    # inspected and no schema is reconstructed from a runtime value.
    from ...transmogrifier.graph.graph_express2 import (
        _annotate_visual_source_owners,
        _map_ir_from_ast,
    )

    for declared_module, declared_tree in tuple(
        graph.G.graph.pop("declared_source_modules", ()) or ()
    ):
        _annotate_visual_source_owners(
            declared_tree, module_name=str(declared_module),
        )
        # ``with_sources`` admits this complete authored module. Publish its
        # class/method/field declaration cells through the same source mapper
        # used for the executable tree before Page declarations cite them.
        # The returned descriptive view is intentionally discarded: the
        # concordance cells and their source edges are the authority.
        _map_ir_from_ast(declared_tree)
        external_classes = {
            statement.name: statement
            for statement in declared_tree.body
            if isinstance(statement, ast.ClassDef)
        }
        external_row_kind_aliases = authored_row_kind_aliases(
            declared_tree.body, str(declared_module),
        )

        def imported_class_owner(
            binding: str,
        ) -> tuple[str, str] | None:
            """Resolve an authored import spelling to its declaration row.

            This reads only the admitted module AST.  It does not import the
            module or inspect the live class; the resulting row is useful
            only when ingestion has already published that exact class
            declaration into the shared concordance.
            """

            head, dot, tail = str(binding).partition(".")
            for import_statement in declared_tree.body:
                if isinstance(import_statement, ast.ImportFrom):
                    imported = next((
                        alias for alias in import_statement.names
                        if str(alias.asname or alias.name) == head
                    ), None)
                    if imported is None:
                        continue
                    module_parts = str(declared_module).split(".")
                    level = int(import_statement.level or 0)
                    owner_parts = (
                        module_parts[:-level]
                        if level else []
                    )
                    if import_statement.module:
                        owner_parts.extend(
                            str(import_statement.module).split(".")
                        )
                    owner_module = ".".join(owner_parts)
                    owner_name = str(imported.name)
                    if dot:
                        owner_name = f"{owner_name}.{tail}"
                    return owner_module, owner_name
                if isinstance(import_statement, ast.Import):
                    imported = next((
                        alias for alias in import_statement.names
                        if str(alias.asname or alias.name.split(".")[0])
                        == head
                    ), None)
                    if imported is None:
                        continue
                    owner_module = str(imported.name)
                    if not dot:
                        return owner_module, owner_module.rsplit(".", 1)[-1]
                    return owner_module, str(tail)
            return None

        def external_page_factory_cell(
            expression: ast.AST,
        ) -> tuple[_Ref, _Ref] | None:
            """Resolve the factory use through this module's import edge."""

            imported_binding = None
            import_statement = None
            if isinstance(expression, ast.Name):
                imported_binding = str(expression.id)
            elif (
                isinstance(expression, ast.Attribute)
                and isinstance(expression.value, ast.Name)
            ):
                imported_binding = str(expression.value.id)
            if imported_binding is None:
                return None
            for candidate in declared_tree.body:
                if isinstance(candidate, ast.ImportFrom):
                    owner_parts = str(declared_module).split(".")
                    level = int(candidate.level or 0)
                    resolved_parts = owner_parts[:-level] if level else []
                    if candidate.module:
                        resolved_parts.extend(str(candidate.module).split("."))
                    resolved_module = ".".join(resolved_parts)
                    alias = next((
                        item for item in candidate.names
                        if str(item.asname or item.name) == imported_binding
                    ), None)
                    if (
                        alias is not None
                        and resolved_module
                        == "src.compiler.identity_concordance"
                        and (
                            isinstance(expression, ast.Name)
                            and str(alias.name) == "declare_page"
                            or isinstance(expression, ast.Attribute)
                            and str(alias.name) in {
                                "identity_concordance", "*",
                            }
                            and expression.attr == "declare_page"
                        )
                    ):
                        import_statement = candidate
                        break
                elif (
                    isinstance(candidate, ast.Import)
                    and isinstance(expression, ast.Attribute)
                ):
                    alias = next((
                        item for item in candidate.names
                        if str(item.asname or item.name.split(".")[0])
                        == imported_binding
                    ), None)
                    if (
                        alias is not None
                        and str(alias.name)
                        == "src.compiler.identity_concordance"
                        and expression.attr == "declare_page"
                    ):
                        import_statement = candidate
                        break
            definition = exact_page_factory_definition_cell()
            import_cell = (
                None if import_statement is None else
                _post_source_span(import_statement)
            )
            return (
                (definition, import_cell)
                if definition is not None and import_cell is not None
                else None
            )

        for statement in declared_tree.body:
            targets = (
                tuple(statement.targets)
                if isinstance(statement, ast.Assign)
                else (statement.target,)
                if isinstance(statement, ast.AnnAssign)
                else ()
            )
            declaration = (
                statement.value
                if isinstance(statement, (ast.Assign, ast.AnnAssign))
                else None
            )
            binding_names = tuple(
                str(target.id) for target in targets
                if isinstance(target, ast.Name)
            )
            factory_resolution = (
                external_page_factory_cell(declaration.func)
                if isinstance(declaration, ast.Call) else None
            )
            definition_cell = (
                None if factory_resolution is None else factory_resolution[0]
            )
            import_cell = (
                None if factory_resolution is None else factory_resolution[1]
            )
            semantic_arguments = (
                bind_page_factory_arguments(
                    declaration, page_factory_parameters(definition_cell),
                )
                if isinstance(declaration, ast.Call) else {}
            )
            page_name_expression = semantic_arguments.get("name")
            row_field_expression = semantic_arguments.get("row_fields")
            fact_type_expression = semantic_arguments.get("fact_type")
            if not (
                binding_names
                and isinstance(declaration, ast.Call)
                and definition_cell is not None
                and isinstance(page_name_expression, ast.Constant)
                and isinstance(page_name_expression.value, str)
                and isinstance(row_field_expression, (ast.Tuple, ast.List))
                and fact_type_expression is not None
            ):
                continue
            class_resolution = exact_fact_class(
                fact_type_expression, str(declared_module),
                local_classes=external_classes,
                imported_owner=imported_class_owner,
            )
            if class_resolution is None:
                continue
            class_identity, class_cell = class_resolution
            page_name = str(page_name_expression.value)
            row_fields: list[tuple[str, str]] = []
            source_nodes: list[ast.AST] = [
                external_classes.get(
                    getattr(fact_type_expression, "id", ""),
                    fact_type_expression,
                ),
                declaration,
                page_name_expression,
            ]
            for field_declaration in (
                row_field_expression.elts
                if isinstance(row_field_expression, (ast.Tuple, ast.List))
                else ()
            ):
                field_arguments = (
                    bind_row_field_arguments(field_declaration)
                    if isinstance(field_declaration, ast.Call) else {}
                )
                field_name_expression = field_arguments.get("name")
                field_kind_expression = field_arguments.get("kind")
                if not (
                    isinstance(field_declaration, ast.Call)
                    and row_field_class_cell is not None
                    and row_kind_class_cell is not None
                    and row_kind_enum_cell is not None
                    and is_exact_row_field_constructor(
                        field_declaration,
                        declared_tree.body, str(declared_module),
                    )
                    and isinstance(field_name_expression, ast.Constant)
                    and isinstance(field_name_expression.value, str)
                    and field_kind_expression is not None
                    and authored_row_kind(
                        field_kind_expression,
                        external_row_kind_aliases,
                        declared_tree.body, str(declared_module),
                    ) is not None
                ):
                    row_fields = []
                    source_nodes = []
                    break
                row_fields.append((
                    str(field_name_expression.value),
                    str(authored_row_kind(
                        field_kind_expression,
                        external_row_kind_aliases,
                        declared_tree.body, str(declared_module),
                    )),
                ))
                source_nodes.extend((
                    field_declaration,
                    field_name_expression,
                    field_kind_expression,
                ))
            if not row_fields:
                continue
            source_cells = tuple(dict.fromkeys(filter(None, (
                row_field_class_cell,
                row_kind_class_cell,
                row_kind_enum_cell,
                *(_post_source_span(node) for node in source_nodes),
            ))))
            if not source_cells:
                continue
            page_cell = declaration_book.post(
                _SOURCE_PAGE_FACT_CLASS,
                (str(declared_module), page_name),
                _SourcePageFactClass(
                    page_name, class_identity, tuple(row_fields),
                ),
                stage=_REDUCTION,
                provenance=_Derived(tuple(dict.fromkeys(filter(None, (
                    definition_cell, import_cell, class_cell, *source_cells,
                ))))),
                mode=_Mode.CONCORD,
            )
            declaration_receipt = (
                class_identity, page_cell, tuple(row_fields),
            )
            incumbent = declared_page_fact_classes.get(page_name)
            if incumbent is not None and incumbent != declaration_receipt:
                raise ValueError(
                    "source page declaration disagreement for "
                    f"{page_name!r}: {incumbent!r} != "
                    f"{declaration_receipt!r}"
                )
            declared_page_fact_classes[page_name] = declaration_receipt
            for binding_name in binding_names:
                declared_page_bindings[binding_name] = page_cell
    graph.G.graph["declared_page_fact_classes"] = (
        declared_page_fact_classes
    )
    graph.G.graph["declared_page_bindings"] = declared_page_bindings
    # Class navigation owns Python's inherited method surface as well as the
    # methods written directly in each body. Retained numerical wrappers are
    # intentionally thin (for example ComplexRationalPrecision inherits its
    # arithmetic from _ComplexRationalBase), so omitting this relation loses
    # the exact dunder dependency even though both class definitions and the
    # base edge are already present in the graph. Copy only absent members;
    # an override on the derived class remains authoritative.
    inheritance_changed = True
    while inheritance_changed:
        inheritance_changed = False
        for class_name, bases in class_bases.items():
            descriptor = graph.G.graph["class_table"].get(class_name)
            if descriptor is None:
                continue
            for base_name in bases:
                base_descriptor = graph.G.graph["class_table"].get(base_name)
                if base_descriptor is None:
                    continue
                for method_name, method_reference in dict(
                    base_descriptor.get("methods") or {}
                ).items():
                    if method_name not in descriptor["methods"]:
                        descriptor["methods"][method_name] = method_reference
                        inheritance_changed = True
                inherited_fields = tuple(dict.fromkeys((
                    *tuple(base_descriptor.get("fields") or ()),
                    *tuple(descriptor.get("fields") or ()),
                )))
                if inherited_fields != tuple(descriptor.get("fields") or ()):
                    descriptor["fields"] = inherited_fields
                    inheritance_changed = True
                for metadata_name in (
                    "field_defaults", "field_classes", "field_callables",
                ):
                    inherited = {
                        **dict(base_descriptor.get(metadata_name) or {}),
                        **dict(descriptor.get(metadata_name) or {}),
                    }
                    if inherited != dict(descriptor.get(metadata_name) or {}):
                        descriptor[metadata_name] = inherited
                        inheritance_changed = True
    for function_node_id, owner_name in method_owners.items():
        reference = function_nodes.get(function_node_id)
        if reference is None:
            continue
        descriptor = graph.G.graph["class_table"].setdefault(
            owner_name,
            {"methods": {}, "fields": (), "field_defaults": {}},
        )
        function_definition = graph.G.nodes[function_node_id].get(
            "expr_obj"
        )
        descriptor["fields"] = tuple(dict.fromkeys((
            *tuple(descriptor.get("fields") or ()),
            *(
                target.attr
                for target in (
                    source_walk(function_definition)
                    if isinstance(
                        function_definition,
                        (ast.FunctionDef, ast.AsyncFunctionDef),
                    )
                    else ()
                )
                if isinstance(target, ast.Attribute)
                and isinstance(target.ctx, ast.Store)
                and isinstance(target.value, ast.Name)
                and target.value.id in {"self", "cls"}
            ),
            *(
                field_name
                for (owner, field_name), _kind
                in class_field_aggregate_kinds.items()
                if owner == owner_name
            ),
        )))
        if isinstance(
            function_definition,
            (ast.FunctionDef, ast.AsyncFunctionDef),
        ):
            descriptor["methods"][function_definition.name] = int(
                reference.address
            )
    method_owner_by_reference = {
        int(reference.address): method_owners.get(function_node_id)
        for function_node_id, reference in function_nodes.items()
        if method_owners.get(function_node_id) is not None
    }
    returned_class_by_reference: dict[int, str] = {}

    def authored_return_class_identities(annotation: ast.AST | None) -> tuple[str, ...]:
        """Concrete source classes stated by one authored return annotation."""

        if isinstance(annotation, ast.Constant) and isinstance(
            annotation.value, str
        ):
            try:
                annotation = ast.parse(annotation.value, mode="eval").body
            except SyntaxError:
                return ()
        if isinstance(annotation, ast.BinOp) and isinstance(annotation.op, ast.BitOr):
            left = authored_return_class_identities(annotation.left)
            right = authored_return_class_identities(annotation.right)
            if not left or not right:
                return ()
            return tuple(sorted(dict.fromkeys((*left, *right))))
        if isinstance(annotation, ast.Constant) and annotation.value is None:
            return ("builtins.NoneType",)
        if isinstance(annotation, ast.Name):
            if annotation.id == "None":
                return ("builtins.NoneType",)
            if annotation.id in {"Any", "object"}:
                return ()
            if annotation.id in {
                "bool", "bytearray", "bytes", "dict", "float",
                "frozenset", "int", "list", "set", "str", "tuple",
            }:
                return (f"builtins.{annotation.id}",)
            class_page = current_identity_book().page(_CLASS_DECLARATION)
            matches = tuple(
                row for row in class_page.rows()
                if len(row) == 2
                and (
                    str(row[1]) == str(annotation.id)
                    or str(row[1]).endswith(f".{annotation.id}")
                )
            )
            return (str(annotation.id),) if len(matches) == 1 else ()
        if isinstance(annotation, ast.Subscript):
            container = (
                annotation.value.id
                if isinstance(annotation.value, ast.Name)
                else annotation.value.attr
                if isinstance(annotation.value, ast.Attribute)
                else ""
            )
            if container == "Optional":
                member = authored_return_class_identities(annotation.slice)
                return (
                    tuple(sorted(dict.fromkeys((*member, "builtins.NoneType"))))
                    if member else ()
                )
            concrete = {
                "Dict": "dict", "FrozenSet": "frozenset", "List": "list",
                "Set": "set", "Tuple": "tuple", "dict": "dict",
                "frozenset": "frozenset", "list": "list", "set": "set",
                "tuple": "tuple",
            }.get(container)
            return () if concrete is None else (f"builtins.{concrete}",)
        return ()

    def returned_class(definition: Any) -> str | None:
        if isinstance(definition, int) and definition in graph.G:
            definition = graph.G.nodes[definition].get("expr_obj")
        if not isinstance(
            definition, (ast.FunctionDef, ast.AsyncFunctionDef)
        ):
            return None
        known_record_classes = {
            str(owner) for owner, _field in class_field_aggregate_kinds
        }
        declared_spelling = (
            definition.returns.id
            if isinstance(definition.returns, ast.Name)
            else definition.returns.value
            if isinstance(definition.returns, ast.Constant)
            and isinstance(definition.returns.value, str)
            else None
        )
        declared_class = (
            str(declared_spelling)
            if declared_spelling is not None
            and (
                str(declared_spelling) in graph.G.graph["class_table"]
                or str(declared_spelling) in known_record_classes
            )
            else None
        )
        returned_classes = {
            returned.func.id
            for returned in (
                node.value for node in ast.walk(definition)
                if isinstance(node, ast.Return) and node.value is not None
            )
            if isinstance(returned, ast.Call)
            and isinstance(returned.func, ast.Name)
            and returned.func.id in graph.G.graph["class_table"]
        }
        inferred_class = declared_class or (
            next(iter(returned_classes))
            if len(returned_classes) == 1 else None
        )
        return None if inferred_class is None else str(inferred_class)

    # Lane D, D2.  Program: ``def single(n) -> list[int]: return [n]``;
    # ``t = single(n); t[0]`` (corpus c215).  The call's result was stamped
    # only as a list, so ``t[0]`` took the float64 domain default until the
    # callee's linked ABI arrived.  Rule: a declared sequence return whose
    # element is one primitive class (``list[int]``, ``tuple[int, int]``,
    # ``tuple[int, ...]``) states the call result's element class, with its
    # ``function_return_annotation`` cell, as a parameter annotation does.
    primitive_element_classes = {
        "int": "builtins.int", "float": "builtins.float",
        "bool": "builtins.bool",
    }
    returned_element_by_reference: dict[int, tuple[str, Any]] = {}

    def returned_element(definition: Any) -> tuple[str, Any] | None:
        if isinstance(definition, int) and definition in graph.G:
            definition = graph.G.nodes[definition].get("expr_obj")
        if not isinstance(definition, (ast.FunctionDef, ast.AsyncFunctionDef)):
            return None
        annotation = definition.returns
        if isinstance(annotation, ast.Constant) and isinstance(
            annotation.value, str
        ):
            try:
                annotation = ast.parse(annotation.value, mode="eval").body
            except SyntaxError:
                return None
        if not isinstance(annotation, ast.Subscript):
            return None
        container = (
            annotation.value.id if isinstance(annotation.value, ast.Name)
            else ""
        )
        if container not in {
            "list", "List", "set", "Set", "frozenset", "tuple", "Tuple",
        }:
            return None
        element = annotation.slice
        if container in {"tuple", "Tuple"} and isinstance(element, ast.Tuple):
            positions = [
                item for item in element.elts
                if not (
                    isinstance(item, ast.Constant) and item.value is Ellipsis
                )
            ]
            if not positions or (
                len(positions) != len(element.elts)
                and not (len(positions) == 1 and len(element.elts) == 2)
            ):
                return None
            names = {
                item.id if isinstance(item, ast.Name) else None
                for item in positions
            }
            if len(names) != 1:
                return None
            element = positions[0]
        if not isinstance(element, ast.Name):
            return None
        element_class = primitive_element_classes.get(element.id)
        row = getattr(definition, "_turing_source_span_row", None)
        if element_class is None or not isinstance(row, tuple) or len(row) < 2:
            return None
        cell = current_identity_book().latest_ref(
            _FUNCTION_RETURN_ANNOTATION, (row[0], str(row[1])),
        )
        return None if cell is None else (element_class, cell)

    for function_node_id, reference in function_nodes.items():
        definition = graph.G.nodes.get(function_node_id, {}).get("expr_obj")
        inferred_class = returned_class(definition)
        if inferred_class is not None:
            returned_class_by_reference[int(reference.address)] = inferred_class
        declared_element = returned_element(definition)
        if declared_element is not None:
            returned_element_by_reference[int(reference.address)] = (
                declared_element
            )
    for entry in function_table:
        inferred_class = returned_class(
            entry.metadata.get("source_node")
        )
        if inferred_class is not None:
            returned_class_by_reference[int(entry.reference.address)] = (
                inferred_class
            )
        declared_element = returned_element(entry.metadata.get("source_node"))
        if declared_element is not None:
            returned_element_by_reference.setdefault(
                int(entry.reference.address), declared_element,
            )

    def propagate_returned_receiver_types(target_graph: Any) -> None:
        target_class_table = graph.G.graph.get("class_table", {})
        calls = tuple(target_graph.nodes(data=True))
        for _node_id, call_data in calls:
            expression = call_data.get("expr_obj")
            if not isinstance(expression, ast.Call):
                continue
            attributes = call_data.setdefault("attributes", {})
            if attributes.get("python_precision_boundary"):
                continue
            # Method calls can already have their exact source reference even
            # when the later generic call-correlation pass has not mirrored
            # it into ``callee_ref`` yet.  Both fields name the same function
            # table entry; refusing ``method_ref`` here loses the returned
            # object's class and therefore every field-storage contract on a
            # value such as ``self.fresh_value().accounting``.
            callee_reference = attributes.get(
                "callee_ref", attributes.get("method_ref")
            )
            return_declaration_cell = None
            returned_class = (
                None if callee_reference is None
                else returned_class_by_reference.get(int(callee_reference))
            )
            declared_element = (
                None if callee_reference is None
                else returned_element_by_reference.get(int(callee_reference))
            )
            if (
                declared_element is not None
                and "sequence_element_class_ref" not in attributes
            ):
                attributes.update({
                    "sequence_element_class_ref": declared_element[0],
                    "sequence_element_annotation_cell": declared_element[1],
                })
            if (
                returned_class is None
                and isinstance(expression.func, ast.Attribute)
            ):
                receiver_id = next((
                    int(parent)
                    for parent, role in call_data.get("parents") or ()
                    if str(role) in {
                        "operand", "receiver", "object", "base",
                    }
                ), None)
                receiver_identity = ""
                if receiver_id is not None and receiver_id in target_graph:
                    receiver_attributes = (
                        target_graph.nodes[receiver_id].get("attributes") or {}
                    )
                    receiver_identity = str(
                        receiver_attributes.get("result_class_ref")
                        or receiver_attributes.get("class_ref") or ""
                    )
                method_page = current_identity_book().page(
                    _CLASS_METHOD_DECLARATION
                )
                method_rows = tuple(
                    row for row in method_page.rows()
                    if len(row) == 3
                    and str(row[2]) == str(expression.func.attr)
                    and (
                        str(row[1]) == receiver_identity
                        or str(row[1]).endswith(f".{receiver_identity}")
                    )
                    and str(getattr(
                        method_page.latest(row), "return_annotation", "",
                    ))
                )
                if len(method_rows) == 1:
                    return_declaration_cell = current_identity_book().latest_ref(
                        _CLASS_METHOD_DECLARATION, method_rows[0],
                    )
                    return_spelling = str(getattr(
                        method_page.latest(method_rows[0]),
                        "return_annotation", "",
                    ))
                    try:
                        return_annotation = ast.parse(
                            return_spelling, mode="eval",
                        ).body
                    except SyntaxError:
                        return_annotation = None
                    return_classes = authored_return_class_identities(
                        return_annotation
                    )
                    attributes.update({
                        "declared_return_annotation": return_spelling,
                        "method_return_declaration_cell": (
                            return_declaration_cell
                        ),
                        "declared_return_class_refs": return_classes,
                    })
                    if len(return_classes) == 1:
                        returned_class = return_classes[0]
            if returned_class is not None:
                attributes["result_class_ref"] = returned_class
                carries_width = "precision" in (
                    _NUMERIC_TYPE_FEATURES.get(
                        str(returned_class).rsplit(".", 1)[-1]
                    ) or ()
                )
                callee_entry = (
                    None if callee_reference is None else next((
                        entry for entry in function_table
                        if int(entry.reference.address)
                        == int(callee_reference)
                    ), None)
                )
                if (
                    not carries_width
                    and callee_entry is not None
                    and callee_entry.graph is not None
                ):
                    callee_identity = tuple(
                        callee_entry.graph.G.graph.get(
                            "authored_function_identity"
                        ) or ()
                    )
                    equivalent_entries = tuple(
                        entry
                        for entry in function_table
                        if entry.graph is not None
                        and tuple(entry.graph.G.graph.get(
                            "authored_function_identity"
                        ) or ()) == callee_identity
                    )
                    canonical_entry = min(
                        equivalent_entries,
                        key=lambda entry: int(entry.reference.address),
                    ) if equivalent_entries else callee_entry
                    caller_scope = _source_numeric_scope(target_graph)
                    result_row = (caller_scope, int(_node_id))
                    result_book = current_identity_book()
                    result_sources = tuple(dict.fromkeys(
                        cell for cell in (
                            node_identity_cell(target_graph, int(_node_id)),
                            result_book.latest_ref(
                                _FUNCTION_ADDRESS,
                                (function_address_identity(canonical_entry),),
                            ),
                        )
                        if cell is not None
                    ))
                    if result_sources:
                        result_book.post(
                            _SOURCE_CALL_RESULT_IDENTITY,
                            result_row,
                            (
                                int(canonical_entry.reference.address),
                                str(returned_class),
                                1,
                            ),
                            stage=_REDUCTION,
                            provenance=_Derived(result_sources),
                            mode=_Mode.CONCORD,
                        )
                        result_cell = result_book.latest_ref(
                            _SOURCE_CALL_RESULT_IDENTITY, result_row,
                        )
                        _concord_source_value_class(
                            caller_scope,
                            int(_node_id),
                            str(returned_class),
                            precision_limbs=1,
                            source="authored call result declaration",
                            provenance=_Derived((result_cell,)),
                        )
                if return_declaration_cell is not None:
                    caller_scope = _source_numeric_scope(target_graph)
                    result_sources = tuple(dict.fromkeys(
                        cell for cell in (
                            node_identity_cell(target_graph, int(_node_id)),
                            return_declaration_cell,
                        ) if cell is not None
                    ))
                    _concord_source_value_class(
                        caller_scope, int(_node_id), str(returned_class),
                        precision_limbs=1,
                        source="authored method return annotation",
                        provenance=_Derived(result_sources),
                    )
        for _node_id, call_data in calls:
            expression = call_data.get("expr_obj")
            attributes = call_data.setdefault("attributes", {})
            if (
                not isinstance(expression, ast.Call)
                or not isinstance(expression.func, ast.Attribute)
                or attributes.get("python_precision_boundary")
                or attributes.get("method_ref") is not None
            ):
                continue
            receiver_id = next((
                int(parent)
                for parent, role in call_data.get("parents", ())
                if str(role) in {"operand", "value", "base", "object"}
            ), None)
            receiver_class = (
                None if receiver_id is None
                else _resolved_source_value_class(target_graph, receiver_id)[0]
            )
            method_reference = (
                target_class_table.get(str(receiver_class), {})
                .get("methods", {})
                .get(expression.func.attr)
            )
            if method_reference is None:
                continue
            method_reference = int(method_reference)
            attributes.update({
                "method_ref": method_reference,
                "callee_ref": method_reference,
            })
            accessor_id = id(expression.func)
            if accessor_id in target_graph:
                target_graph.nodes[accessor_id].setdefault(
                    "attributes", {}
                    ).update({
                        "accessor_kind": "method",
                        "method_ref": method_reference,
                    })

    binary_special_methods = {
        ast.Add: ("__add__", "__radd__"),
        ast.Sub: ("__sub__", "__rsub__"),
        ast.Mult: ("__mul__", "__rmul__"),
        ast.Div: ("__truediv__", "__rtruediv__"),
        ast.FloorDiv: ("__floordiv__", "__rfloordiv__"),
        ast.Mod: ("__mod__", "__rmod__"),
        ast.Pow: ("__pow__", "__rpow__"),
        ast.MatMult: ("__matmul__", "__rmatmul__"),
        ast.BitAnd: ("__and__", "__rand__"),
        ast.BitOr: ("__or__", "__ror__"),
        ast.BitXor: ("__xor__", "__rxor__"),
        ast.LShift: ("__lshift__", "__rlshift__"),
        ast.RShift: ("__rshift__", "__rrshift__"),
    }
    unary_special_methods = {
        ast.USub: "__neg__",
        ast.UAdd: "__pos__",
        ast.Invert: "__invert__",
    }

    def specialize_concorded_same_type_numeric_operator(
        target_wrapper: Any,
    ) -> bool:
        """Bind a generic wrapper dunder to its authored same-type body.

        A retained dunder is normalized before call edges have specialized its
        ``self`` and ``other`` formals.  The source-AST specialization can
        therefore cover an annotated root expression but not an operator
        reached later through another wrapper's component algebra.  Once both
        formals carry the same concorded numeric descriptor, the generic
        ``_composed_binary(op, left, right)`` promotion is provably redundant:
        its own eager contract dispatches that exact case to ``_binary_same``.
        Rebind the already-existing call and constant operation argument; do
        not synthesize algebra or infer a type from the dunder spelling.
        """

        target_graph = target_wrapper.G
        scope = _source_numeric_scope(target_graph)
        method_name = str(target_graph.graph.get("function_name") or "")
        if method_name not in {
            "__add__", "__radd__", "__sub__", "__rsub__",
            "__mul__", "__rmul__", "__truediv__", "__rtruediv__",
        }:
            return False
        inputs = {
            str(attributes.get("binding_name")): int(node_id)
            for node_id, data in target_graph.nodes(data=True)
            for attributes in (data.get("attributes") or {},)
            if data.get("type") == "Input"
            and attributes.get("binding_name") is not None
        }
        if not {"self", "other"} <= set(inputs):
            return False
        self_descriptor = _concorded_numeric_descriptor(
            target_graph, inputs["self"]
        )
        other_descriptor = _concorded_numeric_descriptor(
            target_graph, inputs["other"]
        )
        if self_descriptor is None or self_descriptor != other_descriptor:
            return False
        class_table = graph.G.graph.get("class_table", {})
        method_reference = (
            class_table.get(self_descriptor.type_name, {})
            .get("methods", {})
            .get("_binary_same")
        )
        if method_reference is None:
            return False
        changed = False
        page = current_identity_book().page(
            _SOURCE_NUMERIC_OPERATOR_SPECIALIZATION
        )
        for node_id, data in tuple(target_graph.nodes(data=True)):
            attributes = data.setdefault("attributes", {})
            if attributes.get("static_python_reference") != "_composed_binary":
                continue
            actuals = {
                str(role): int(parent)
                for parent, role in data.get("parents", ())
                if int(parent) in target_graph
            }
            operation_id = actuals.get("arg:0")
            receiver_id = actuals.get("arg:1")
            other_id = actuals.get("arg:2")
            if None in (operation_id, receiver_id, other_id):
                continue
            receiver_descriptor = _concorded_numeric_descriptor(
                target_graph, receiver_id
            )
            argument_descriptor = _concorded_numeric_descriptor(
                target_graph, other_id
            )
            if receiver_descriptor != self_descriptor or (
                argument_descriptor != self_descriptor
            ):
                continue
            fact = (
                int(receiver_id), int(other_id), int(operation_id),
                self_descriptor.receipt(), int(method_reference),
            )
            row = (scope, int(node_id))
            incumbent = page.latest(row)
            if incumbent is not None and tuple(incumbent) != fact:
                raise ValueError(
                    "source numeric operator specialization concordance "
                    f"disagreement for {row!r}: recorded={incumbent!r}, "
                    f"proposed={fact!r}"
                )
            # DERIVED from the call and the three operands it relates.
            current_identity_book().post(
                _SOURCE_NUMERIC_OPERATOR_SPECIALIZATION, row, fact,
                stage=_REDUCTION,
                provenance=_Derived(_node_identity_cells(
                    target_wrapper, node_id, receiver_id, other_id,
                    operation_id,
                )),
                mode=_Mode.CONCORD,
            )
            for field in ("static_python_reference", "reference_kind"):
                attributes.pop(field, None)
            attributes.update({
                "method_ref": int(method_reference),
                "callee_ref": int(method_reference),
                "numeric_same_type_specialization": True,
                "numeric_feature_descriptor": self_descriptor.receipt(),
                "result_class_ref": self_descriptor.type_name,
                "precision_limbs": int(self_descriptor.limbs),
            })
            data["type"] = "Call"
            data["op"] = "call"
            _replace_inputs(target_wrapper, int(node_id), (
                (int(receiver_id), "operand"),
                (int(other_id), "arg:0"),
                (int(operation_id), "arg:1"),
            ))
            # DERIVED from the call, its three operands, and the class cells
            # of the receiver, the argument and the two formals whose
            # concorded descriptors decided the specialization.
            _concord_source_value_class(
                scope, int(node_id), self_descriptor.type_name,
                precision_limbs=self_descriptor.limbs,
                source="concorded same-type numeric operator specialization",
                provenance=_Derived(_source_cells((
                    *_node_identity_cells(
                        target_wrapper, node_id, receiver_id, other_id,
                        operation_id,
                    ),
                    *(
                        current_identity_book().latest_ref(
                            _SOURCE_VALUE_CLASS, (scope, int(value_id)),
                        )
                        for value_id in (
                            receiver_id, other_id,
                            inputs["self"], inputs["other"],
                        )
                    ),
                ))),
            )
            changed = True
        return changed

    def resolve_concorded_receiver_constructor(target_wrapper: Any) -> bool:
        """Bind ``type(receiver)(...)`` to the receiver's concorded class.

        ``type(self)`` names no class lexically; the receiver's class is the
        source-value class concordance fact the call edges already committed
        for ``self``.  Once that fact exists the call is an ordinary
        constructor of that class: stamp ``class_ref`` (which call planning
        resolves through the class table's ``__new__``/``__init__``), feed it
        only its authored arguments, and commit the constructed value's class
        at the receiver's width.  Nothing is inferred from a spelling.
        """

        target_graph = target_wrapper.G
        scope = _source_numeric_scope(target_graph)
        class_table = graph.G.graph.get("class_table", {})
        class_page = current_identity_book().page(
            "source_value_class_concordance"
        )
        page = current_identity_book().page(_SOURCE_RECEIVER_CONSTRUCTOR)
        changed = False
        for node_id, data in tuple(target_graph.nodes(data=True)):
            if str(data.get("type") or "") != "Call":
                continue
            attributes = data.setdefault("attributes", {})
            if attributes.get("class_ref") is not None:
                continue
            roles = {
                str(role): int(parent)
                for parent, role in data.get("parents", ())
                if int(parent) in target_graph
            }
            callee_id = roles.get("callee")
            if callee_id is None:
                continue
            callee = target_graph.nodes[callee_id]
            callee_roles = {
                str(role): int(parent)
                for parent, role in callee.get("parents", ())
                if int(parent) in target_graph
            }
            if (
                (callee.get("attributes") or {}).get(
                    "static_python_reference"
                ) != "type"
                or set(callee_roles) != {"callee", "arg:0"}
            ):
                continue
            receiver_id = callee_roles["arg:0"]
            concorded = class_page.latest((scope, int(receiver_id)))
            if not isinstance(concorded, tuple) or len(concorded) < 2:
                continue
            class_identity, limbs = str(concorded[0]), int(concorded[1])
            if class_identity not in class_table:
                continue
            fact = (int(receiver_id), class_identity, limbs)
            row = (scope, int(node_id))
            incumbent = page.latest(row)
            if incumbent is not None and tuple(incumbent) != fact:
                raise ValueError(
                    "source receiver constructor concordance disagreement "
                    f"for {row!r}: recorded={incumbent!r}, proposed={fact!r}"
                )
            # DERIVED from the call, its receiver and the receiver's class
            # cell the constructed class was read from.
            current_identity_book().post(
                _SOURCE_RECEIVER_CONSTRUCTOR, row, fact, stage=_REDUCTION,
                provenance=_Derived(_source_cells((
                    *_node_identity_cells(target_wrapper, node_id, receiver_id),
                    current_identity_book().latest_ref(
                        _SOURCE_VALUE_CLASS, (scope, int(receiver_id)),
                    ),
                ))),
                mode=_Mode.CONCORD,
            )
            attributes.update({
                "class_ref": class_identity,
                "result_class_ref": class_identity,
                "precision_limbs": limbs,
            })
            descriptor = numeric_feature_descriptor(
                class_identity + (f"[{limbs}]" if limbs > 1 else "")
            )
            if descriptor is not None:
                attributes["numeric_feature_descriptor"] = descriptor.receipt()
            _replace_inputs(target_wrapper, int(node_id), tuple(
                (parent, role)
                for parent, role in data.get("parents", ())
                if str(role) != "callee"
            ))
            # The same cells as the constructor row: the call, its receiver
            # and the receiver's class cell the class was read from.
            _concord_source_value_class(
                scope, int(node_id), class_identity,
                precision_limbs=limbs,
                source="concorded receiver constructor",
                provenance=_Derived(_source_cells((
                    *_node_identity_cells(target_wrapper, node_id, receiver_id),
                    current_identity_book().latest_ref(
                        _SOURCE_VALUE_CLASS, (scope, int(receiver_id)),
                    ),
                ))),
            )
            changed = True
        return changed

    def propagate_numeric_field_projections(target_wrapper: Any) -> bool:
        """Carry exact composite coefficient types after call specialization.

        Lexical normalization can run before an unannotated method formal has
        received its caller's numeric descriptor. Revisit existing GetAttr
        edges after that transfer so nested fields inherit the same arbitrary
        Precision width. This is a monotone publication of the receiver-edge
        fact, not a reconstruction from the field spelling alone.
        """

        target_graph = target_wrapper.G
        scope = _source_numeric_scope(target_graph)
        changed = False
        settling = True
        while settling:
            settling = False
            for node_id, data in tuple(target_graph.nodes(data=True)):
                expression = data.get("expr_obj")
                if not (
                    isinstance(expression, ast.Call)
                    and isinstance(expression.func, ast.Attribute)
                ):
                    continue
                method = str(expression.func.attr)
                receiver_id = next((
                    int(parent)
                    for parent, role in data.get("parents", ())
                    if str(role) in {"operand", "value", "object", "receiver"}
                    and int(parent) in target_graph
                ), None)
                if receiver_id is None:
                    continue
                receiver_attributes = (
                    target_graph.nodes[receiver_id].get("attributes") or {}
                )
                receiver_descriptor = _concorded_numeric_descriptor(
                    target_graph, receiver_id
                )
                if receiver_descriptor is None:
                    continue
                components = numeric_feature_method_components(
                    receiver_descriptor, method
                )
                if not components:
                    continue
                results = tuple(
                    {
                        "path": (
                            *tuple(receiver_attributes.get(
                                "numeric_component_path", ()
                            )),
                            *path,
                        ),
                        "descriptor": (
                            None if descriptor is None
                            else descriptor.receipt()
                        ),
                    }
                    for path, descriptor in components
                )
                attributes = data.setdefault("attributes", {})
                page = current_identity_book().page(
                    _SOURCE_NUMERIC_INTRINSIC
                )
                row = (scope, int(node_id))
                fact = (int(receiver_id), method, results)
                incumbent = page.latest(row)
                if incumbent is not None and tuple(incumbent) != fact:
                    raise ValueError(
                        "source numeric intrinsic concordance disagreement "
                        f"for {row!r}: recorded={incumbent!r}, "
                        f"proposed={fact!r}"
                    )
                # DERIVED from the call and the receiver it projects.
                current_identity_book().post(
                    _SOURCE_NUMERIC_INTRINSIC, row, fact, stage=_REDUCTION,
                    provenance=_Derived(_node_identity_cells(
                        target_wrapper, node_id, receiver_id,
                    )),
                    mode=_Mode.CONCORD,
                )
                if attributes.get("numeric_component_results") != results:
                    attributes["numeric_component_results"] = results
                    changed = settling = True

            for node_id, data in tuple(target_graph.nodes(data=True)):
                if str(data.get("type") or "") != "Indexed":
                    continue
                parents = {
                    str(role): int(parent)
                    for parent, role in data.get("parents", ())
                    if int(parent) in target_graph
                }
                base_id, index_id = parents.get("base"), parents.get("index")
                if base_id is None or index_id is None:
                    continue
                results = tuple(
                    (target_graph.nodes[base_id].get("attributes") or {}).get(
                        "numeric_component_results", ()
                    )
                )
                index = (target_graph.nodes[index_id].get("attributes") or {}).get(
                    "value"
                )
                if not isinstance(index, int) or not (0 <= index < len(results)):
                    continue
                selected = dict(results[index])
                descriptor = _numeric_feature_descriptor_from_receipt(
                    selected.get("descriptor")
                )
                path = tuple(map(str, selected.get("path") or ()))
                attributes = data.setdefault("attributes", {})
                proposed = {
                    "numeric_component_path": path,
                    "numeric_component_receiver_id": int(base_id),
                    "numeric_component_attribute": f"result[{index}]",
                    "precision_limbs": (
                        int(descriptor.limbs) if descriptor is not None else 1
                    ),
                }
                if descriptor is not None:
                    proposed.update({
                        "numeric_feature_descriptor": descriptor.receipt(),
                        "result_class_ref": descriptor.type_name,
                    })
                    # DERIVED from the projection, the intrinsic call and
                    # the index it selects, and the intrinsic row the
                    # component results were read from.
                    _concord_source_value_class(
                        scope, int(node_id), descriptor.type_name,
                        precision_limbs=descriptor.limbs,
                        source="numeric-intrinsic-result-projection",
                        provenance=_Derived(_source_cells((
                            *_node_identity_cells(
                                target_wrapper, node_id, base_id, index_id,
                            ),
                            current_identity_book().latest_ref(
                                _SOURCE_NUMERIC_INTRINSIC,
                                (scope, int(base_id)),
                            ),
                        ))),
                    )
                _concord_numeric_feature_projection(
                    scope, int(node_id), int(base_id), f"result[{index}]",
                    path, descriptor,
                    cells=_node_identity_cells(target_wrapper, node_id, base_id),
                )
                if any(attributes.get(key) != value
                       for key, value in proposed.items()):
                    attributes.update(proposed)
                    changed = settling = True

            for node_id, data in tuple(target_graph.nodes(data=True)):
                expression = data.get("expr_obj")
                attributes = data.setdefault("attributes", {})
                attribute = (
                    expression.attr
                    if isinstance(expression, ast.Attribute)
                    else attributes.get("attribute")
                    if str(data.get("type") or "") == "GetAttr"
                    else None
                )
                if attribute not in {
                    "real", "imag", "numerator", "denominator",
                }:
                    continue
                receiver_id = next((
                    int(parent)
                    for parent, role in data.get("parents", ())
                    if str(role) in {"value", "object", "base", "operand"}
                    and int(parent) in target_graph
                ), None)
                if receiver_id is None:
                    continue
                receiver_attributes = (
                    target_graph.nodes[receiver_id].get("attributes") or {}
                )
                receiver_descriptor = _concorded_numeric_descriptor(
                    target_graph, receiver_id
                )
                if receiver_descriptor is None:
                    continue
                structural = (
                    (attribute in {"real", "imag"}
                     and "complex" in receiver_descriptor.features)
                    or (attribute in {"numerator", "denominator"}
                        and "rational" in receiver_descriptor.features)
                )
                if not structural:
                    continue
                projected = numeric_feature_field_projection(
                    receiver_descriptor, str(attribute)
                )
                path = (
                    *tuple(receiver_attributes.get(
                        "numeric_component_path", ()
                    )),
                    str(attribute),
                )
                proposed = {
                    "numeric_component_path": path,
                    "numeric_component_receiver_id": int(receiver_id),
                    "numeric_component_attribute": str(attribute),
                    "precision_limbs": (
                        int(projected.limbs) if projected is not None else 1
                    ),
                }
                if projected is not None:
                    proposed.update({
                        "numeric_feature_descriptor": projected.receipt(),
                        "result_class_ref": projected.type_name,
                    })
                    # DERIVED from the projection, its receiver and the
                    # receiver's class cell the descriptor was read from.
                    _concord_source_value_class(
                        scope, int(node_id), projected.type_name,
                        precision_limbs=projected.limbs,
                        source="post-call numeric-component-projection",
                        provenance=_Derived(_source_cells((
                            *_node_identity_cells(
                                target_wrapper, node_id, receiver_id,
                            ),
                            current_identity_book().latest_ref(
                                _SOURCE_VALUE_CLASS, (scope, int(receiver_id)),
                            ),
                        ))),
                    )
                _concord_numeric_feature_projection(
                    scope, int(node_id), int(receiver_id), str(attribute),
                    path, projected,
                    cells=_node_identity_cells(
                        target_wrapper, node_id, receiver_id,
                    ),
                )
                if any(attributes.get(key) != value
                       for key, value in proposed.items()):
                    attributes.update(proposed)
                    changed = settling = True
        return changed

    def lower_class_operator_calls(
        target_wrapper: Any, *, settled: bool = False,
    ) -> None:
        """Bind authored operators through the receiver's class table.

        Lexical normalization has already replaced every Name occurrence by
        its exact producer at this seam.  Consequently the receiver edge, not
        a source spelling or an operand position guessed later, determines
        whether Python's class dispatch applies.  The concordance row commits
        that decision once for all later call planning and storage binding.
        """

        target_graph = target_wrapper.G
        scope = _source_numeric_scope(target_graph)
        class_table = graph.G.graph.get("class_table", {})
        page = current_identity_book().page(_SOURCE_OPERATOR_DISPATCH)

        def descriptor(value_id: Any) -> tuple[str | None, int]:
            return _resolved_source_value_class(target_graph, value_id)

        def commit(
            node_id: int,
            receiver_id: int,
            class_identity: str,
            method_name: str,
            method_reference: int,
            reflected: bool,
        ) -> None:
            fact = (
                int(receiver_id), str(class_identity), str(method_name),
                int(method_reference), bool(reflected),
            )
            row = (scope, int(node_id))
            incumbent = page.latest(row)
            if incumbent is not None and tuple(incumbent) != fact:
                raise ValueError(
                    "source operator dispatch concordance disagreement for "
                    f"{row!r}: recorded={incumbent!r}, proposed={fact!r}"
                )
            # DERIVED from the operator, its receiver and the receiver's
            # class cell the dispatch was decided from.
            book = current_identity_book()
            book.post(
                _SOURCE_OPERATOR_DISPATCH, row, fact, stage=_REDUCTION,
                provenance=_Derived(_source_cells((
                    *_node_identity_cells(target_wrapper, node_id, receiver_id),
                    book.latest_ref(
                        _SOURCE_VALUE_CLASS, (scope, int(receiver_id)),
                    ),
                ))),
                mode=_Mode.CONCORD,
            )

        changed = True
        while changed:
            changed = False
            for node_id, data in tuple(target_graph.nodes(data=True)):
                expression = data.get("expr_obj")
                attributes = data.setdefault("attributes", {})
                if (
                    attributes.get("class_operator_dispatch")
                    or attributes.get("python_precision_operator")
                ):
                    continue
                parents = {
                    str(role): int(parent)
                    for parent, role in data.get("parents", ())
                    if int(parent) in target_graph
                }
                receiver_id = other_id = None
                class_identity = method_name = None
                reflected = False
                if isinstance(expression, ast.BinOp):
                    methods = binary_special_methods.get(type(expression.op))
                    left_id = parents.get("lhs")
                    right_id = parents.get("rhs")
                    if methods is None or left_id is None or right_id is None:
                        continue
                    left_class, _left_limbs = descriptor(left_id)
                    right_class, _right_limbs = descriptor(right_id)
                    if left_class is None and not settled:
                        # The left operand decides first; while its type is
                        # still being settled, the reflected method is not
                        # yet the answer.
                        continue
                    candidates = (
                        (left_id, right_id, left_class, methods[0], False),
                        (right_id, left_id, right_class, methods[1], True),
                    )
                    selected = next((
                        candidate for candidate in candidates
                        if candidate[2] is not None
                        and class_table.get(str(candidate[2]), {})
                        .get("methods", {}).get(candidate[3]) is not None
                    ), None)
                    if selected is None:
                        continue
                    (
                        receiver_id, other_id, class_identity,
                        method_name, reflected,
                    ) = selected
                elif isinstance(expression, ast.UnaryOp):
                    method_name = unary_special_methods.get(type(expression.op))
                    receiver_id = parents.get("operand")
                    if method_name is None or receiver_id is None:
                        continue
                    class_identity, _limbs = descriptor(receiver_id)
                    if (
                        class_identity is None
                        or class_table.get(str(class_identity), {})
                        .get("methods", {}).get(method_name) is None
                    ):
                        continue
                else:
                    continue
                method_reference = int(
                    class_table[str(class_identity)]["methods"][method_name]
                )
                returned_class = returned_class_by_reference.get(
                    method_reference
                )
                numeric_descriptor = _concorded_numeric_descriptor(
                    target_graph, node_id
                )
                if returned_class is None and numeric_descriptor is not None:
                    returned_class = numeric_descriptor.type_name
                attributes.update({
                    "source_type": type(expression).__name__,
                    "class_operator_dispatch": True,
                    "operator_receiver_class": str(class_identity),
                    "operator_method": str(method_name),
                    "operator_reflected": bool(reflected),
                    "method_ref": method_reference,
                    "callee_ref": method_reference,
                })
                attributes.pop("numeric_composite_pending", None)
                if returned_class is not None:
                    attributes["result_class_ref"] = str(returned_class)
                    # DERIVED from the operator and its operands, the
                    # operands' class cells the dispatch and the width were
                    # read from, the operator's own class cell when the
                    # returned class is its concorded descriptor, and the
                    # dispatched method's address cell when the class was
                    # read from that method's authored definition.
                    dispatch_book = current_identity_book()
                    method_entry = next((
                        entry for entry in function_table
                        if int(entry.reference.address) == method_reference
                    ), None)
                    _concord_source_value_class(
                        scope,
                        int(node_id),
                        str(returned_class),
                        precision_limbs=max(
                            descriptor(receiver_id)[1],
                            descriptor(other_id)[1]
                            if other_id is not None else 1,
                        ),
                        source=f"operator method {method_name}",
                        provenance=_Derived(_source_cells((
                            *_node_identity_cells(
                                target_wrapper, node_id, receiver_id,
                                *(() if other_id is None else (other_id,)),
                            ),
                            *(
                                dispatch_book.latest_ref(
                                    _SOURCE_VALUE_CLASS, (scope, int(value_id)),
                                )
                                for value_id in (receiver_id, other_id, node_id)
                                if value_id is not None
                            ),
                            *(
                                () if method_entry is None else (
                                    dispatch_book.latest_ref(
                                        _FUNCTION_ADDRESS,
                                        (function_address_identity(method_entry),),
                                    ),
                                )
                            ),
                        ))),
                    )
                data["type"] = "Call"
                data["op"] = "call"
                call_inputs = [(int(receiver_id), "operand")]
                if other_id is not None:
                    call_inputs.append((int(other_id), "arg:0"))
                _replace_inputs(
                    target_wrapper, int(node_id), tuple(call_inputs)
                )
                commit(
                    int(node_id), int(receiver_id), str(class_identity),
                    str(method_name), method_reference, bool(reflected),
                )
                changed = True

    def lower_python_precision(target_wrapper: Any) -> None:
        """Lower the authored Precision surface to its repository operators.

        ``Precision.of`` and ``collapse`` are boundary declarations, not
        runtime calls into the eager Python implementation.  The former
        commits the class/width descriptor carried by that source occurrence;
        the latter consumes it.  Arithmetic between those boundaries is the
        existing ``precision_*`` vocabulary consumed by
        ``apply_precision_pipeline``.  This pass runs only after lexical
        normalization, so every descriptor follows the exact producer edge.
        """

        target_graph = target_wrapper.G
        scope = _source_numeric_scope(target_graph)

        def is_real_precision(identity: Any) -> bool:
            return (
                identity is not None
                and str(identity).rsplit(".", 1)[-1] == "Precision"
            )

        def concord_operator(
            node_id: int,
            operation: str,
            receiver_id: int,
            class_identity: str,
            limbs: int,
        ) -> None:
            """Commit the exact source operation carried by a wide value."""

            book = current_identity_book()
            page = book.page(_SOURCE_PRECISION_OPERATOR)
            row = (scope, int(node_id))
            proposed = (
                str(operation), int(receiver_id), str(class_identity),
                max(int(limbs or 1), 1),
            )
            incumbent = page.latest(row)
            if incumbent is not None and tuple(incumbent) != proposed:
                raise ValueError(
                    "source precision operator concordance disagreement for "
                    f"{row!r}: recorded={incumbent!r}, proposed={proposed!r}"
                )
            # DERIVED from the operator node and the receiver it reads.
            book.post(
                _SOURCE_PRECISION_OPERATOR, row, proposed, stage=_REDUCTION,
                provenance=_Derived(_node_identity_cells(
                    target_wrapper, node_id, receiver_id,
                )),
                mode=_Mode.CONCORD,
            )

        for node_id, data in tuple(target_graph.nodes(data=True)):
            expression = data.get("expr_obj")
            if not (
                isinstance(expression, ast.Call)
                and isinstance(expression.func, ast.Attribute)
            ):
                continue
            attributes = data.setdefault("attributes", {})
            parents = tuple(data.get("parents", ()))
            if (
                expression.func.attr == "of"
                and is_real_precision(attributes.get(
                    "result_class_ref", attributes.get("class_ref")
                ))
            ):
                value_id = next((
                    int(parent) for parent, role in parents
                    if str(role) in {"arg:0", "arg0"}
                ), None)
                if value_id is None:
                    continue
                limbs = 2
                if len(expression.args) >= 2:
                    try:
                        limbs = max(int(ast.literal_eval(expression.args[1])), 1)
                    except (TypeError, ValueError, SyntaxError):
                        continue
                class_identity = str(attributes.get(
                    "result_class_ref", attributes.get("class_ref")
                ))
                attributes.update({
                    "precision_limbs": limbs,
                    "result_class_ref": class_identity,
                    "python_precision_boundary": "promote",
                })
                for field in (
                    "callee_ref", "method_ref", "constructor_ref", "class_ref",
                ):
                    attributes.pop(field, None)
                accessor_id = id(expression.func)
                if accessor_id in target_graph:
                    accessor_attributes = target_graph.nodes[
                        accessor_id
                    ].setdefault("attributes", {})
                    for field in (
                        "callee_ref", "method_ref", "bound_method_ref",
                    ):
                        accessor_attributes.pop(field, None)
                    accessor_attributes[
                        "python_precision_boundary"
                    ] = "promote-selector"
                data["type"] = "Cast"
                data["op"] = "Cast"
                _replace_inputs(
                    target_wrapper, int(node_id), ((value_id, "operand"),)
                )
                # The class and width are read off the ``Precision.of`` call
                # node and the value it promotes: DERIVED from both cells.
                _concord_source_value_class(
                    scope, int(node_id), class_identity,
                    precision_limbs=limbs,
                    source="Precision.of boundary",
                    provenance=_Derived(_node_identity_cells(
                        target_wrapper, node_id, value_id,
                    )),
                )
                _concord_source_precision_boundary(
                    scope,
                    int(node_id),
                    "promote",
                    int(value_id),
                    precision_limbs=limbs,
                    cells=_node_identity_cells(
                        target_wrapper, node_id, value_id,
                    ),
                )

        precision_methods = {
            "sqrt": "Sqrt",
            "exp": "Exp",
            "log": "Log",
        }
        # A method can feed an operator and an operator can feed a method.
        # Settle both from the same producer-edge identities to a fixed point;
        # ordering these as two one-shot loops lost `(wide.exp() - 1)` between
        # the two and left the following collapse without a class descriptor.
        changed = True
        while changed:
            changed = False
            for node_id, data in tuple(target_graph.nodes(data=True)):
                expression = data.get("expr_obj")
                if not isinstance(expression, (ast.BinOp, ast.UnaryOp)):
                    continue
                attributes = data.setdefault("attributes", {})
                if attributes.get("python_precision_operator"):
                    continue
                parents = {
                    str(role): int(parent)
                    for parent, role in data.get("parents", ())
                    if int(parent) in target_graph
                }
                if isinstance(expression, ast.BinOp):
                    operand_ids = (
                        parents.get("lhs"), parents.get("rhs")
                    )
                    if None in operand_ids:
                        continue
                    descriptors = tuple(
                        _resolved_source_value_class(target_graph, value_id)
                        for value_id in operand_ids
                    )
                    precision = tuple(
                        item for item in descriptors
                        if is_real_precision(item[0])
                    )
                    if not precision:
                        continue
                    limbs = max(item[1] for item in precision)
                    operation = _qualified_handler(
                        "binop", expression.op, limbs=limbs
                    )
                else:
                    operand_id = parents.get("operand")
                    if operand_id is None:
                        continue
                    class_identity, limbs = _resolved_source_value_class(
                        target_graph, operand_id
                    )
                    if not is_real_precision(class_identity):
                        continue
                    operation = _qualified_handler(
                        "unaryop", expression.op, limbs=limbs
                    )
                class_identity = str(precision[0][0]) if isinstance(
                    expression, ast.BinOp
                ) else str(class_identity)
                # The operands the class and width were read from (their
                # ``source_value_class`` rows, under this graph's scope).
                read_ids = (
                    tuple(int(value_id) for value_id in operand_ids)
                    if isinstance(expression, ast.BinOp)
                    else (int(operand_id),)
                )
                data["type"] = operation
                data["op"] = operation
                attributes.update({
                    "python_precision_operator": True,
                    "precision_limbs": int(limbs),
                    "result_class_ref": class_identity,
                })
                _concord_source_value_class(
                    scope, int(node_id), class_identity,
                    precision_limbs=int(limbs),
                    source=f"Precision {type(expression).__name__}",
                    provenance=_Derived(_source_cells((
                        *_node_identity_cells(
                            target_wrapper, node_id, *read_ids,
                        ),
                        *(
                            current_identity_book().latest_ref(
                                _SOURCE_VALUE_CLASS, (scope, int(value_id)),
                            )
                            for value_id in read_ids
                        ),
                    ))),
                )
                receiver_id = (
                    int(operand_ids[0]) if isinstance(expression, ast.BinOp)
                    else int(operand_id)
                )
                concord_operator(
                    int(node_id), str(operation), receiver_id,
                    class_identity, int(limbs),
                )
                changed = True
            for node_id, data in tuple(target_graph.nodes(data=True)):
                expression = data.get("expr_obj")
                attributes = data.setdefault("attributes", {})
                if (
                    attributes.get("python_precision_operator")
                    or not isinstance(expression, ast.Call)
                    or not isinstance(expression.func, ast.Attribute)
                    or expression.func.attr not in precision_methods
                ):
                    continue
                receiver_id = next((
                    int(parent) for parent, role in data.get("parents", ())
                    if str(role) in {"operand", "receiver", "value"}
                ), None)
                if receiver_id is None:
                    continue
                receiver_class, receiver_limbs = (
                    _resolved_source_value_class(target_graph, receiver_id)
                )
                if not is_real_precision(receiver_class):
                    continue
                source_operation = precision_methods[expression.func.attr]
                operation = PRECISION_SINGULAR_NAMES[source_operation]
                attributes.update({
                    "python_precision_operator": True,
                    "precision_limbs": int(receiver_limbs),
                    "result_class_ref": str(receiver_class),
                    "precision_source_operation": source_operation,
                })
                for field in (
                    "callee_ref", "method_ref", "constructor_ref",
                    "class_ref",
                ):
                    attributes.pop(field, None)
                accessor_id = id(expression.func)
                if accessor_id in target_graph:
                    accessor_attributes = target_graph.nodes[
                        accessor_id
                    ].setdefault("attributes", {})
                    for field in (
                        "callee_ref", "method_ref", "bound_method_ref",
                    ):
                        accessor_attributes.pop(field, None)
                    accessor_attributes["python_precision_operator"] = (
                        f"{expression.func.attr}-selector"
                    )
                data["type"] = operation
                data["op"] = operation
                _replace_inputs(
                    target_wrapper,
                    int(node_id),
                    ((int(receiver_id), "operand"),),
                )
                # The class and width are the receiver's, read from its
                # ``source_value_class`` row: DERIVED from the call node,
                # the receiver node and that row.
                _concord_source_value_class(
                    scope, int(node_id), str(receiver_class),
                    precision_limbs=int(receiver_limbs),
                    source=f"Precision {expression.func.attr}",
                    provenance=_Derived(_source_cells((
                        *_node_identity_cells(
                            target_wrapper, node_id, receiver_id,
                        ),
                        current_identity_book().latest_ref(
                            _SOURCE_VALUE_CLASS, (scope, int(receiver_id)),
                        ),
                    ))),
                )
                concord_operator(
                    int(node_id), source_operation, int(receiver_id),
                    str(receiver_class), int(receiver_limbs),
                )
                changed = True

        for node_id, data in tuple(target_graph.nodes(data=True)):
            expression = data.get("expr_obj")
            if not (
                isinstance(expression, ast.Call)
                and isinstance(expression.func, ast.Attribute)
                and expression.func.attr == "collapse"
            ):
                continue
            receiver_id = next((
                int(parent) for parent, role in data.get("parents", ())
                if str(role) == "operand"
            ), None)
            if receiver_id is None:
                continue
            receiver_class, receiver_limbs = (
                _resolved_source_value_class(target_graph, receiver_id)
            )
            if not is_real_precision(receiver_class):
                continue
            data.setdefault("attributes", {}).update({
                "python_precision_boundary": "collapse",
                "precision_limbs": int(receiver_limbs),
            })
            attributes = data["attributes"]
            for field in (
                "callee_ref", "method_ref", "constructor_ref", "class_ref",
            ):
                attributes.pop(field, None)
            accessor_id = id(expression.func)
            if accessor_id in target_graph:
                accessor_attributes = target_graph.nodes[
                    accessor_id
                ].setdefault("attributes", {})
                for field in (
                    "callee_ref", "method_ref", "bound_method_ref",
                ):
                    accessor_attributes.pop(field, None)
                accessor_attributes[
                    "python_precision_boundary"
                ] = "collapse-selector"
            data["type"] = "Cast"
            data["op"] = "Cast"
            _replace_inputs(
                target_wrapper,
                int(node_id),
                ((int(receiver_id), "operand"),),
            )
            _concord_source_precision_boundary(
                scope,
                int(node_id),
                "collapse",
                int(receiver_id),
                precision_limbs=int(receiver_limbs),
                cells=_node_identity_cells(
                    target_wrapper, node_id, receiver_id,
                ),
            )

    compile_substage("topology: propagate exact receiver types")
    propagated_graphs = {id(graph.G)}
    propagate_returned_receiver_types(graph.G)
    for entry in function_table:
        entry_graph = getattr(getattr(entry, "graph", None), "G", None)
        if entry_graph is None or id(entry_graph) in propagated_graphs:
            continue
        propagated_graphs.add(id(entry_graph))
        propagate_returned_receiver_types(entry_graph)
    # Source pursuit has already made an exact definition->call dependency
    # edge. Preserve that identity directly in SSA call metadata instead of
    # attempting receiver-name inference again. This is especially important
    # for a method reached through an argument (``G.remove_node``): its owner
    # is proven by actual-argument provenance, not by the local spelling ``G``.
    for call_id, call_data in graph.G.nodes(data=True):
        expression = call_data.get("expr_obj")
        if not isinstance(expression, ast.Call):
            continue
        resolved_parent = (call_data.get("attributes") or {}).get(
            "resolved_ast_parent"
        )
        reference = function_nodes.get(int(resolved_parent)) if (
            resolved_parent is not None
        ) else None
        if reference is None:
            continue
        attributes = call_data.setdefault("attributes", {})
        attributes["callee_ref"] = int(reference.address)
        returned_class = returned_class_by_reference.get(
            int(reference.address)
        )
        if returned_class is not None:
            attributes["result_class_ref"] = returned_class
        if isinstance(expression.func, ast.Attribute):
            attributes["method_ref"] = int(reference.address)
            accessor_id = id(expression.func)
            if accessor_id in graph.G:
                graph.G.nodes[accessor_id].setdefault("attributes", {}).update({
                    "accessor_kind": "method",
                    "method_ref": int(reference.address),
                })

    # The exact callee references above are attached after lexical child
    # graphs have been normalized.  Re-run the returned-object propagation on
    # this graph now that those identities are available.
    propagate_returned_receiver_types(graph.G)

    import_bindings, static_bindings = _resolve_python_bindings()
    function_parameters_by_address = {}
    for function_node_id, reference in function_nodes.items():
        definition = graph.G.nodes[function_node_id].get("expr_obj")
        if not isinstance(
            definition,
            (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda),
        ):
            continue
        function_parameters_by_address[reference.address] = {
            argument.arg
            for argument in (
                *definition.args.posonlyargs,
                *definition.args.args,
                *definition.args.kwonlyargs,
                *(
                    (definition.args.vararg,)
                    if definition.args.vararg is not None
                    else ()
                ),
                *(
                    (definition.args.kwarg,)
                    if definition.args.kwarg is not None
                    else ()
                ),
            )
        }
    lexical_functions_by_owner: dict[int, dict[str, Any]] = {}
    for child_id, parent_id in lexical_parent_by_function.items():
        child_reference = function_nodes.get(child_id)
        parent_reference = function_nodes.get(parent_id)
        child_definition = function_definitions.get(child_id)
        if (
            child_reference is None
            or parent_reference is None
            or not isinstance(
                child_definition,
                (ast.FunctionDef, ast.AsyncFunctionDef),
            )
        ):
            continue
        lexical_functions_by_owner.setdefault(
            int(parent_reference.address), {}
        )[child_definition.name] = child_reference

    # Function extraction and structural rewrites can copy an authored Python
    # Attribute after its original ingestion overlay was applied. Reassert the
    # language special case at this AST-to-shared-graph seam.
    compile_substage("topology: normalize source attributes and operators")
    normalize_python_attribute_special_cases(graph)

    for _node_id, data in graph.G.nodes(data=True):
        source_type = data.get("type")
        process_type = _AST_PROCESS_GRAPH_ALIASES.get(source_type)
        if process_type is None:
            continue
        data["type"] = process_type
        data["op"] = process_type
        data.setdefault("attributes", {})["source_type"] = source_type

    for node_id, data in list(graph.G.nodes(data=True)):
        expression = data.get("expr_obj")
        # --- C (pycparser c_ast) canonicalization -------------------------
        # Dispatched on the type *name*, never isinstance, so this module
        # never imports pycparser (it is a frontend-optional dependency; a
        # pure-Python compile must not require it to be installed).
        #
        # This is the same universalization the Python branches below
        # perform, and it belongs here for the same reason: once a syntactic
        # element is canonicalized into the shared operator vocabulary
        # (Add/Load/Store/Call/Constant), no downstream pass needs to know
        # which language it came from. Skipping it is precisely what let raw
        # C node types survive all the way to the lexical-value pass.
        c_type_name = type(expression).__name__
        if expression is not None and c_type_name in _C_COMPILE_TIME_SYNTAX:
            # Pure type machinery, with no runtime value of its own: the
            # C counterpart of Python's Nonlocal/Global handling below.
            _remove_node(graph, node_id)
            continue
        if c_type_name == "Decl" and not isinstance(expression, ast.AST):
            # `int total = expr;` -- a declaration is not itself an
            # operation. Its initializer is the value the declared name
            # denotes, so the Decl collapses onto that value exactly the way
            # Python's own Name-store nodes collapse onto their producer.
            # A declaration with no initializer (`int total;`) names no
            # value at all yet and carries no runtime effect of its own.
            initializer = getattr(expression, "init", None)
            if initializer is not None and id(initializer) in graph.G:
                _redirect_value(graph, node_id, id(initializer))
            else:
                _remove_node(graph, node_id)
            continue
        if c_type_name == "Constant" and not isinstance(expression, ast.AST):
            value = _c_constant_value(expression)
            data["type"] = "Constant"
            data["op"] = "const"
            data["constant"] = value
            data.setdefault("attributes", {})["value"] = value
            continue
        if c_type_name == "BinaryOp":
            operation = _c_qualified_handler("binaryop", expression.op)
            data["type"] = operation
            data["op"] = operation
            data.setdefault("attributes", {})["source_type"] = "BinaryOp"
            # Absent operands are handled uniformly by _replace_inputs, which
            # substitutes an explicit non-operation and records a shortfall.
            # Filtering them out here instead would drop the operand
            # silently, leaving an operation short an argument -- a wrong
            # program rather than an honestly incomplete one.
            _replace_inputs(
                graph,
                node_id,
                (
                    (id(expression.left), "lhs"),
                    (id(expression.right), "rhs"),
                ),
            )
            continue
        if c_type_name == "UnaryOp" and not isinstance(expression, ast.AST):
            if str(expression.op) in {"+", "&", "*"}:
                # Unary plus is a no-op conversion, the same reading Python's
                # ast.UAdd gets below.
                #
                # Address-of and dereference are identity *in this value
                # graph specifically*: a node here denotes a value, and the
                # graph has no separate address space for `&x` to point
                # into that `x` does not already name. The cpp shell emits
                # `&obj` for every method receiver, and `obj`'s own node is
                # already exactly the receiver the callee needs. These stay
                # registered as GetElementPtr/Load in ssa_registry (their
                # true meanings, which a real memory model would need) --
                # collapsing them is a property of this representation, not
                # a claim that C's & and * are no-ops. Revisit when pointer
                # arithmetic or aliasing enters the shell's scope; today it
                # is excluded by CPP_LIKE_SHELL_FOR_C_INTENT.md.
                _redirect_value(graph, node_id, id(expression.expr))
                continue
            operation = _c_qualified_handler("unaryop", expression.op)
            data["type"] = operation
            data["op"] = operation
            data.setdefault("attributes", {})["source_type"] = "UnaryOp"
            _replace_inputs(
                graph,
                node_id,
                ((id(expression.expr), "operand"),),
            )
            continue
        if isinstance(expression, (ast.Nonlocal, ast.Global)):
            # Root whole-graph deployment regions are formed from this graph,
            # not only from the normalized per-function copies below.  Scope
            # declarations are compile-time syntax in both representations.
            _remove_node(graph, node_id)
            continue
        if isinstance(expression, ast.Delete):
            # The target nodes carry the executable deletion effects.  The
            # statement wrapper is ordering syntax, not an operator.
            _remove_node(graph, node_id)
            continue
        if (
            isinstance(expression, ast.Name)
            and isinstance(expression.ctx, ast.Del)
        ):
            # Deleting a lexical binding has no object-level runtime effect.
            _remove_node(graph, node_id)
            continue
        if (
            isinstance(expression, ast.Attribute)
            and isinstance(expression.ctx, ast.Del)
        ):
            data["type"] = "DelAttr"
            data["op"] = "delattr"
            data.setdefault("attributes", {})["attribute"] = expression.attr
            _replace_inputs(
                graph,
                node_id,
                ((id(expression.value), "object"),),
            )
            continue
        if isinstance(expression, ast.Constant):
            data["type"] = "Constant"
            data["op"] = "const"
            data["constant"] = expression.value
            data.setdefault("attributes", {})["value"] = expression.value
        elif isinstance(expression, ast.BinOp):
            folded = _static_sequence_literal(expression)
            if folded is not None:
                # Sequence replication is table allocation, not arithmetic.
                data["type"] = "Constant"
                data["op"] = "const"
                data["constant"] = folded
                attributes = data.setdefault("attributes", {})
                attributes["value"] = folded
                attributes["source_type"] = "BinOp"
                attributes["constant_folded"] = "sequence-replication"
                continue
            left_descriptor = _operand_numeric_descriptor(
                graph, expression.left
            )
            right_descriptor = _operand_numeric_descriptor(
                graph, expression.right
            )
            numeric_descriptor = join_numeric_feature_descriptors(
                left_descriptor, right_descriptor,
            )
            attributes = data.setdefault("attributes", {})
            if numeric_descriptor is not None:
                attributes["numeric_feature_descriptor"] = (
                    numeric_descriptor.receipt()
                )
                if numeric_descriptor.features != frozenset({"precision"}):
                    attributes["numeric_composite_pending"] = True
            left_limbs, left_type = (
                (left_descriptor.limbs, left_descriptor.element_type)
                if left_descriptor is not None
                and left_descriptor.features == frozenset({"precision"})
                else (1, None)
            )
            right_limbs, right_type = (
                (right_descriptor.limbs, right_descriptor.element_type)
                if right_descriptor is not None
                and right_descriptor.features == frozenset({"precision"})
                else (1, None)
            )
            operand_limbs = max(left_limbs, right_limbs)
            operand_element = _widest_element(left_type, right_type)
            operation = _qualified_handler(
                "binop", expression.op,
                limbs=operand_limbs, dtype=operand_element,
            )
            data["type"] = operation
            data["op"] = operation
            if operand_limbs > 1:
                attributes["precision_limbs"] = operand_limbs
                attributes["precision_element"] = operand_element
            attributes["source_type"] = "BinOp"
            sequence_operand = (
                expression.left
                if isinstance(expression.left, (ast.List, ast.Tuple))
                else expression.right
                if isinstance(expression.right, (ast.List, ast.Tuple))
                else None
            )
            if isinstance(expression.op, ast.Mult) and sequence_operand is not None:
                attributes.update({
                    "producer_kind": "sequence_replication",
                    "aggregate_kind": (
                        "list" if isinstance(sequence_operand, ast.List)
                        else "tuple"
                    ),
                    "sequence_key_columns": (),
                    "sequence_column_count": 1,
                    "sequence_writable": isinstance(sequence_operand, ast.List),
                    "sequence_fill_value_ids": tuple(
                        id(element) for element in sequence_operand.elts
                    ),
                })
            _replace_inputs(
                graph,
                node_id,
                (
                    (id(expression.left), "lhs"),
                    (id(expression.right), "rhs"),
                ),
            )
        elif isinstance(expression, ast.AugAssign):
            operation = _qualified_handler("binop", expression.op)
            data["type"] = operation
            data["op"] = operation
            data.setdefault("attributes", {})["source_type"] = "AugAssign"
            _replace_inputs(
                graph,
                node_id,
                (
                    (id(expression.target), "lhs"),
                    (id(expression.value), "rhs"),
                ),
            )
        elif isinstance(expression, ast.UnaryOp):
            if isinstance(expression.op, ast.UAdd):
                _redirect_value(
                    graph,
                    node_id,
                    id(expression.operand),
                )
                continue
            numeric_descriptor = _operand_numeric_descriptor(
                graph, expression.operand
            )
            attributes = data.setdefault("attributes", {})
            if numeric_descriptor is not None:
                attributes["numeric_feature_descriptor"] = (
                    numeric_descriptor.receipt()
                )
                if numeric_descriptor.features != frozenset({"precision"}):
                    attributes["numeric_composite_pending"] = True
            operand_limbs, operand_type = (
                (numeric_descriptor.limbs, numeric_descriptor.element_type)
                if numeric_descriptor is not None
                and numeric_descriptor.features == frozenset({"precision"})
                else (1, None)
            )
            operation = _qualified_handler(
                "unaryop", expression.op, limbs=operand_limbs,
                dtype=operand_type,
            )
            data["type"] = operation
            data["op"] = operation
            if operand_limbs > 1:
                attributes["precision_limbs"] = operand_limbs
                attributes["precision_element"] = _widest_element(operand_type)
            attributes["source_type"] = "UnaryOp"
            _replace_inputs(
                graph,
                node_id,
                ((id(expression.operand), "operand"),),
            )
        elif isinstance(expression, ast.BoolOp):
            # The guarded operand is ordinary work owned by the operator's
            # short-circuit arm (``_short_circuit_control_program``), never
            # coordinator work evaluated beside the first operand.
            data.setdefault("attributes", {})["source_type"] = "BoolOp"
            _replace_inputs(
                graph,
                node_id,
                tuple(
                    (id(value), f"value:{index}")
                    for index, value in enumerate(expression.values)
                ),
            )
        elif isinstance(expression, ast.Compare) and len(expression.ops) == 1:
            operation = _qualified_handler("compare", expression.ops[0])
            data["type"] = operation
            data["op"] = operation
            data.setdefault("attributes", {})["source_type"] = "Compare"
            _replace_inputs(
                graph,
                node_id,
                (
                    (id(expression.left), "lhs"),
                    (id(expression.comparators[0]), "rhs"),
                ),
            )
        elif isinstance(expression, ast.Subscript):
            # Indexing is one operation over the parent tensor and the complete
            # index tuple.  In particular, Ellipsis is not an independent
            # scalar operation: AbstractTensor.__getitem__ and each specialized
            # backend resolve it against the parent tensor's rank.
            index_expressions = (
                tuple(expression.slice.elts)
                if isinstance(expression.slice, ast.Tuple)
                else (expression.slice,)
            )
            deleting = isinstance(expression.ctx, ast.Del)
            data["type"] = "DelItem" if deleting else "Indexed"
            data["op"] = "delitem" if deleting else "Indexed"
            attributes = data.setdefault("attributes", {})
            attributes["source_type"] = "Subscript"
            _replace_inputs(
                graph,
                node_id,
                (
                    (id(expression.value), "base"),
                    *(
                        (id(index_expression), "index")
                        for index_expression in index_expressions
                    ),
                ),
            )
            # The AST Tuple only grouped the index components.  Once those
            # components feed Indexed directly, retaining the wrapper would
            # incorrectly schedule a second tuple-producing computation.
            slice_id = id(expression.slice)
            if (
                isinstance(expression.slice, ast.Tuple)
                and slice_id in graph.G
                and graph.G.out_degree(slice_id) == 0
            ):
                _set_operands(graph, slice_id, [], cause=_DISSOLVE_WRAPPER)
                graph.G.remove_node(slice_id)
        elif (
            isinstance(expression, ast.Call)
            and isinstance(expression.func, ast.Attribute)
        ):
            operation = expression.func.attr
            data["type"] = operation
            data["op"] = operation
            data.setdefault("attributes", {})["source_type"] = "Call"
            receiver_name = (
                expression.func.value.id
                if isinstance(expression.func.value, ast.Name)
                else None
            )
            call_owner = call_owners.get(node_id)
            lexical_class = (
                method_owner_by_reference.get(int(call_owner.address))
                if call_owner is not None
                else None
            )
            if receiver_name in {"self", "cls"} and lexical_class is not None:
                method_reference = (
                    graph.G.graph.get("class_table", {})
                    .get(lexical_class, {})
                    .get("methods", {})
                    .get(expression.func.attr)
                )
                if method_reference is not None:
                    method_reference = int(method_reference)
                    data.setdefault("attributes", {})["method_ref"] = (
                        method_reference
                    )
                    accessor_id = id(expression.func)
                    if accessor_id in graph.G:
                        accessor = graph.G.nodes[accessor_id]
                        accessor.setdefault("attributes", {}).update({
                            "accessor_kind": "method",
                            "method_ref": method_reference,
                        })
            if data.get("attributes", {}).get("method_ref") is None:
                receiver_id = next((
                    int(parent)
                    for parent, role in data.get("parents", ())
                    if str(role) in {"operand", "value", "base", "object"}
                ), None)
                receiver_attributes = (
                    {}
                    if receiver_id is None or receiver_id not in graph.G
                    else graph.G.nodes[receiver_id].get("attributes") or {}
                )
                receiver_class = receiver_attributes.get(
                    "result_class_ref",
                    receiver_attributes.get("class_ref"),
                )
                method_reference = (
                    graph.G.graph.get("class_table", {})
                    .get(str(receiver_class), {})
                    .get("methods", {})
                    .get(expression.func.attr)
                )
                if method_reference is not None:
                    method_reference = int(method_reference)
                    data.setdefault("attributes", {})["method_ref"] = (
                        method_reference
                    )
                    data["attributes"]["callee_ref"] = method_reference
                    accessor_id = id(expression.func)
                    if accessor_id in graph.G:
                        graph.G.nodes[accessor_id].setdefault(
                            "attributes", {}
                        ).update({
                            "accessor_kind": "method",
                            "method_ref": method_reference,
                        })
            # Wiring the receiver/arguments as this node's own ``parents``
            # used to happen right here, keyed by ``id(expression.func.
            # value)`` -- the raw Python id() of the AST node, not a real
            # graph reference.  That is only ever valid by coincidence: it
            # assumes ingestion already walked this exact receiver
            # independently, which is not guaranteed (a receiver reached
            # only through this call expression, inside a nested try/loop,
            # was never separately ingested).  ``orchestrator`` here is an
            # ordinary local variable; it already has a real, resolved SSA
            # value the moment its own assignment is processed
            # (``bind_target`` -> ``environment``) -- fabricating a new
            # node for it, or guessing at a raw id, both bypass that
            # existing value instead of looking it up.  The actual lookup
            # operator for "what did this expression resolve to" is
            # ``resolve_expression`` itself, which only becomes available
            # once lexical normalization runs (this pass runs earlier, over
            # whatever ingestion already produced). Wiring is done instead
            # in ``resolve_expression``'s own ``ast.Call`` handling
            # (``_normalize_lexical_values``, run later during reduction),
            # where ``resolve_expression`` can be called directly on the
            # receiver and arguments -- the same SSA lookup every other
            # expression in the program already goes through.
        elif isinstance(expression, ast.Call):
            call_inputs: list[tuple[int, str]] = [
                (
                    id(argument),
                    f"arg:{index}",
                )
                for index, argument in enumerate(expression.args)
            ]
            call_inputs.extend(
                (
                    id(keyword.value),
                    (
                        f"kw:{keyword.arg}"
                        if keyword.arg is not None
                        else "kwargs"
                    ),
                )
                for keyword in expression.keywords
            )
            if isinstance(expression.func, ast.Name):
                callee_name = expression.func.id
                owner = call_owners.get(node_id)
                callee_is_parameter = (
                    owner is not None
                    and callee_name in function_parameters_by_address.get(
                        owner.address,
                        (),
                    )
                )
                if callee_is_parameter:
                    attributes = data.setdefault("attributes", {})
                    attributes.pop("callee_ref", None)
                    attributes.pop("external_callee_ref", None)
                    call_inputs.insert(
                        0,
                        (id(expression.func), "callee"),
                    )
                    reference = None
                else:
                    owner_identity = (
                        None if owner is None
                        else function_table.entry(owner).metadata.get(
                            "source_identity"
                        )
                    )
                    reference = function_table.lexical_reference(
                        callee_name,
                        module=(
                            None if not owner_identity
                            else str(owner_identity[0])
                        ),
                    )
                if (
                    not callee_is_parameter
                    and reference is None
                    and callee_name in import_bindings
                ):
                    (
                        qualified_name,
                        imported_name,
                        requirement,
                        import_cell,
                    ) = import_bindings[
                        callee_name
                    ]
                    external_reference = external_function_table.declare(
                        callee_name,
                        qualified_name=qualified_name,
                        external=True,
                        metadata={
                            "contextual_requirement": requirement,
                            "imported_name": imported_name,
                        },
                        source=import_cell,
                    )
                    data.setdefault("attributes", {})[
                        "external_callee_ref"
                    ] = external_reference.address
                elif (
                    not callee_is_parameter
                    and reference is not None
                ):
                    data.setdefault("attributes", {})[
                        "callee_ref"
                    ] = reference.address
                elif not callee_is_parameter:
                    call_inputs.insert(
                        0,
                        (id(expression.func), "callee"),
                    )
            else:
                call_inputs.insert(0, (id(expression.func), "callee"))
            _replace_inputs(graph, node_id, tuple(call_inputs))

            # Keyword nodes carry only source spelling once their value and
            # name have been transferred to the Call edge role.
            for keyword in expression.keywords:
                keyword_id = id(keyword)
                if (
                    keyword_id not in graph.G
                    or graph.G.out_degree(keyword_id) != 0
                ):
                    continue
                _set_operands(graph, keyword_id, [], cause=_DISSOLVE_WRAPPER)
                graph.G.remove_node(keyword_id)

    compile_substage("topology: normalize authored loop inputs")
    for node_id, data in list(graph.G.nodes(data=True)):
        statement = data.get("expr_obj")
        if not isinstance(statement, ast.For):
            continue
        attributes = data.setdefault("attributes", {})
        attributes["source_type"] = "For"
        attributes["target"] = (
            statement.target.id
            if isinstance(statement.target, ast.Name)
            else ast.dump(statement.target, include_attributes=False)
        )
        loop_inputs: list[tuple[int, str]] = []
        iterator = statement.iter
        if (
            isinstance(iterator, ast.Call)
            and isinstance(iterator.func, ast.Name)
            and iterator.func.id == "range"
        ):
            attributes["iterator_kind"] = "arithmetic_sequence"
            range_arguments = tuple(iterator.args)
            if not 1 <= len(range_arguments) <= 3:
                raise ValueError("range loop requires one to three arguments")
            roles = (
                ("stop",)
                if len(range_arguments) == 1
                else ("start", "stop")
                if len(range_arguments) == 2
                else ("start", "stop", "step")
            )
            if len(range_arguments) == 1:
                attributes["start"] = 0
                attributes["step"] = 1
            elif len(range_arguments) == 2:
                attributes["step"] = 1
            loop_inputs.extend(
                (id(argument), role)
                for argument, role in zip(range_arguments, roles)
            )
        else:
            attributes["iterator_kind"] = "iterable"
            loop_inputs.append((id(iterator), "iterable"))
        loop_inputs.extend(
            (id(body_statement), "body")
            for body_statement in statement.body
        )
        loop_inputs.extend(
            (id(else_statement), "else")
            for else_statement in statement.orelse
        )
        _replace_inputs(graph, node_id, tuple(loop_inputs))

        if isinstance(iterator, ast.Call) and id(iterator) in graph.G:
            iterator_id = id(iterator)
            if graph.G.out_degree(iterator_id) == 0:
                _set_operands(graph, iterator_id, [], cause=_DISSOLVE_WRAPPER)
                graph.G.remove_node(iterator_id)

    compile_substage("topology: dissolve expression wrappers")
    for node_id, data in list(graph.G.nodes(data=True)):
        if data.get("type") != "Expr":
            continue
        # An Expr statement wraps its value(s) and is dissolved: every consumer
        # of the wrapper is reconnected directly to the wrapped value(s). There
        # is no artificial cap of one value -- a wrapper standing in for several
        # values (e.g. a call whose arguments the builder attached directly)
        # fans its slot out to all of them, preserving their order.
        predecessors = tuple(graph.G.predecessors(node_id))
        successors = tuple(graph.G.successors(node_id))
        for successor in successors:
            successor_data = graph.G.nodes[successor]
            replacement_parents = []
            for parent_id, role in successor_data.get("parents", ()):
                if parent_id != node_id:
                    replacement_parents.append((parent_id, role))
                else:
                    for predecessor in predecessors:
                        replacement_parents.append((predecessor, role))
            _set_operands(
                graph, successor, replacement_parents, cause=_DISSOLVE_EXPR,
                same=(
                    {node_id: predecessors[0]} if len(predecessors) == 1
                    else None
                ),
            )
        # The wrapper's own positions retire; its parents' ``children``
        # entries and edges go with them.
        _set_operands(graph, node_id, [], cause=_DISSOLVE_EXPR)
        # Roots holding the wrapper are replaced by every value it wrapped
        # (deduplicated, order preserved); a wrapper with no value is dropped.
        new_roots: list = []
        for root_id in graph.roots:
            if root_id != node_id:
                new_roots.append(root_id)
            else:
                new_roots.extend(predecessors)
        seen: set = set()
        graph.roots = [
            root for root in new_roots if not (root in seen or seen.add(root))
        ]
        graph.G.remove_node(node_id)

    compile_substage("topology: dissolve return wrappers")
    for node_id, data in list(graph.G.nodes(data=True)):
        if data.get("type") != "Return":
            continue
        # A Return wrapper carries its returned value(s) and is dissolved into
        # them. There is no artificial cap of one value -- a multi-value return
        # (a tuple of results) publishes every one of its values as a root,
        # order preserved.
        predecessors = tuple(graph.G.predecessors(node_id))
        for successor in tuple(graph.G.successors(node_id)):
            _set_operands(graph, successor, [
                (parent_id, role)
                for parent_id, role in graph.G.nodes[successor].get(
                    "parents", ()
                )
                if parent_id != node_id
            ], cause=_DISSOLVE_RETURN)
        _set_operands(graph, node_id, [], cause=_DISSOLVE_RETURN)
        for returned in predecessors:
            if returned not in graph.roots:
                graph.roots.append(returned)
        graph.roots = [root for root in graph.roots if root != node_id]
        graph.G.remove_node(node_id)

    compile_substage("topology: classify recursive call components")
    call_graph = live_digraph()
    function_addresses = frozenset(
        reference.address for reference in function_nodes.values()
    )
    call_graph.add_nodes_from(reference.address for reference in function_nodes.values())
    referenced_calls: list[tuple[int, Any, Any]] = []
    for call_id, owner in call_owners.items():
        if call_id not in graph.G:
            continue
        callee_address = (
            graph.G.nodes[call_id].get("attributes") or {}
        ).get("callee_ref")
        if callee_address is None:
            continue
        referenced_calls.append((call_id, owner, callee_address))
        try:
            callee_entry = function_table.entry(callee_address)
        except KeyError:
            continue
        if callee_entry.graph is None and callee_address not in function_addresses:
            continue
        call_graph.add_edge(owner.address, callee_address)

    recursive_edges: set[tuple[int, int]] = set()
    for component in nx.strongly_connected_components(call_graph):
        if len(component) > 1:
            recursive_edges.update(
                (source, target)
                for source, target in call_graph.edges(component)
                if target in component
            )
        else:
            address = next(iter(component))
            if call_graph.has_edge(address, address):
                recursive_edges.add((address, address))
    for call_id, owner, callee_address in referenced_calls:
        if (owner.address, callee_address) not in recursive_edges:
            continue
        graph.G.nodes[call_id].setdefault("attributes", {})[
            "recursive_backedge"
        ] = True
        function_table.entry(owner).recursive = True

    lexical_free_names_by_function: dict[int, tuple[str, ...]] = {}
    compile_substage("topology: extract lexical function graphs")
    # The bootstrap's 621 function entries share one reduced source graph.
    # Its terminal merges are already installed; function normalization below
    # writes each detached function graph, not new merges into this source.
    # Find the candidates once, retaining source order and the same exact
    # return-value subset test for each function.
    terminal_merge_candidates = tuple(
        int(member)
        for member, data in graph.G.nodes(data=True)
        if (data.get("attributes") or {}).get("terminal_return_merge")
    )
    for node_id, reference in compile_iter(function_nodes.items(),
            "lexical-functions", label="Lexical function graphs extracted"):
        if node_id not in graph.G:
            continue
        return_values = [
            value
            for value in function_return_values.get(node_id, ())
            if value in graph.G
        ]
        terminal_merges = [
            int(member)
            for member in terminal_merge_candidates
            if (
                (graph.G.nodes[member].get("attributes") or {}).get(
                    "terminal_return_merge"
                )
                and set(
                    (graph.G.nodes[member].get("attributes") or {}).get(
                        "terminal_return_values", ()
                    )
                ).issubset(return_values)
            )
        ]
        if terminal_merges:
            merged_values = {
                int(value)
                for member in terminal_merges
                for value in (
                    graph.G.nodes[member].get("attributes") or {}
                ).get("terminal_return_values", ())
            }
            return_values = [
                value for value in return_values if value not in merged_values
            ]
            return_values.extend(terminal_merges)
        statement = graph.G.nodes[node_id].get("expr_obj")
        # Every function inherits the module imports resolved above.  Source
        # pursuit may attach additional definition-local bindings, but an
        # existing empty/partial ``_python_bindings`` mapping is not a
        # replacement for that module environment (it previously erased an
        # ordinary ``from ... import Metrics`` at this boundary).
        definition_static_bindings = dict(static_bindings)
        definition_static_bindings.update(dict(
            getattr(statement, "_python_bindings", {}) or {}
        ))
        for builtin_name, builtin_value in vars(builtins).items():
            definition_static_bindings.setdefault(
                builtin_name,
                builtin_value,
            )
        # Function ownership is already exact in the saved Python AST.  Use
        # that ownership directly: graph ancestry from only the return value
        # silently discarded assignments, calls, loops, and side effects.
        #
        # This deliberately still walks the raw ``ast`` tree, not
        # ``graph.G`` -- unlike ``_record_owned_calls_and_returns`` above,
        # which runs right after ingestion while the graph still mirrors the
        # source tree 1:1. By the time this loop runs, earlier reduction
        # passes have already restructured ``graph.G`` (edges no longer
        # necessarily match the original AST parent/child shape), so a
        # graph-native walk here would silently miss nodes a raw-tree walk
        # still finds (confirmed empirically: a graph-based version of this
        # walk lost the Return node itself for a plain `return (...)`
        # function body). Generalizing *this* walk to a foreign language
        # needs its own graph-native traversal designed against the
        # post-reduction graph shape, not a drop-in swap -- tracked
        # separately, not attempted here.
        owned_members: set[int] = set()

        def record_owned_member(member: Any) -> None:
            if isinstance(member, ast.ClassDef):
                # A class's body belongs to its own methods' entries.
                return
            if is_runnable_definition(member):
                # A nested definition's body belongs to another
                # function-table entry, not to this enclosing shell. A
                # lambda is still itself a value the enclosing scope
                # references, so it is owned without being descended into.
                if isinstance(member, ast.Lambda) and id(member) in graph.G:
                    owned_members.add(id(member))
                return
            if id(member) in graph.G and not isinstance(
                member,
                (
                    ast.arguments,
                    ast.arg,
                    ast.expr_context,
                    ast.operator,
                    ast.unaryop,
                    ast.boolop,
                    ast.cmpop,
                    ast.keyword,
                    ast.alias,
                    ast.Import,
                    ast.ImportFrom,
                ),
            ):
                owned_members.add(id(member))
            for child in source_child_nodes(member):
                record_owned_member(child)

        if isinstance(statement, ast.Lambda):
            # A lambda's body is one expression, and is the body itself
            # rather than a list of statements -- descend into it directly
            # instead of treating it as a nested-definition boundary.
            for child in source_child_nodes(statement.body):
                record_owned_member(child)
            if id(statement.body) in graph.G:
                owned_members.add(id(statement.body))
        else:
            for body_member in source_body_statements(statement):
                record_owned_member(body_member)
        included = owned_members
        included = {
            member
            for member in included
            if (
                member in return_values
                # An ordered side effect remains part of its lexical body
                # even when reduction detached its value operands.
                or graph.G.nodes[member].get("attributes", {}).get("ordered_effect", False)
                or any(
                    neighbor in included
                    for neighbor in graph.G.predecessors(member)
                )
                or any(
                    neighbor in included
                    for neighbor in graph.G.successors(member)
                )
            )
        }
        function_graph = copy.copy(graph)
        if not hasattr(graph.G, "_induced_copy"):
            raise TypeError(
                "ProcessGraph function extraction requires its authoritative "
                "BitTensorMemoryGraph topology"
            )
        function_graph.G = graph.G._induced_copy(included)
        function_graph.MG = function_graph.G.bit_tensor_memory_graph
        # NetworkX copies each node-data dictionary but not mutable values
        # nested inside it.  Topology normalization writes the ``attributes``
        # view of the detached function graph.  Without a distinct mapping,
        # the first retained copy of an authored f-string published its
        # copy-local glyph row into the root graph and every later copy.
        # Keep the authored ``expr_obj`` identity shared; detach only the
        # mutable graph view that this pass owns and updates.
        for _member, member_data in function_graph.G.nodes(data=True):
            member_data["attributes"] = dict(
                member_data.get("attributes") or {}
            )
        # The subgraph's operand rewrites (parameter Inputs, the filter
        # below) post into its own scope: a copy-on-read fork of the
        # source's rows, projected onto the subgraph's nodes.
        fork_operand_position_scope(
            function_graph, included, "function_subgraph",
            source_graph=graph,
        )
        # Extraction decisions are occurrence contracts, not merely a root-
        # graph audit log.  Several reducer rewrites rebuild a Call node's
        # attributes while preserving its source AST identity; the global
        # boundary ledger survives that rewrite, but the per-function graph
        # previously lost the receipt needed by shell/native-call planning.
        # Restore it by exact source occurrence before detaching the function
        # graph.  This does not re-resolve or pursue the callable.
        statement_name = str(getattr(statement, "name", ""))
        statement_identity = getattr(statement, "_python_source_identity", None)
        boundary_by_location = {
            (int(boundary["line"]), int(boundary["column"])): dict(
                boundary["extraction_contract"]
            )
            for boundary in graph.G.graph.get(
                "extraction_boundary_calls", ()
            )
            if boundary.get("line") is not None
            and boundary.get("column") is not None
            and isinstance(boundary.get("extraction_contract"), Mapping)
            and (
                (
                    statement_identity is None
                    and str(boundary.get("owner_name") or "")
                    == statement_name
                )
                or (
                    statement_identity is not None
                    and tuple(boundary.get("owner_source_identity") or ())
                    == tuple(statement_identity)
                )
            )
        }
        for _member_id, member_data in function_graph.G.nodes(data=True):
            expression = member_data.get("expr_obj")
            if not isinstance(expression, ast.Call):
                continue
            # AST special-case expansion owns the generated operation's
            # receipt. Several generated operations can share one original
            # source location; the source ledger cannot distinguish them.
            receipt = getattr(expression, "_extraction_contract", None) if getattr(
                expression, "_turing_dispatch_operation", None
            ) else boundary_by_location.get((
                int(getattr(expression, "lineno", -1)),
                int(getattr(expression, "col_offset", -1)),
            ))
            if receipt is None:
                continue
            expression._extraction_contract = receipt
            special_case = interpret_python_special_case(expression)
            if special_case is not None:
                member_data.setdefault("attributes", {}).update(
                    special_case.attributes
                )
        # The definition may carry literal module constants and source-local
        # imports beyond the root graph's generic binding set.  Preserve that
        # exact static environment on the function graph consumed by compiled
        # shells; otherwise those globals reappear as missing runtime inputs.
        function_graph.python_bindings = definition_static_bindings
        function_graph.levels = {
            member: level
            for member, level in graph.levels.items()
            if member in included
        }
        function_graph.roots = return_values or [node_id]
        function_graph.function_table = function_table
        positional_parameters = ()
        keyword_only_parameters = ()
        variadic_parameters = ()
        if isinstance(
            statement,
            (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda),
        ):
            positional_parameters = tuple(
                argument.arg
                for argument in (
                    *statement.args.posonlyargs,
                    *statement.args.args,
                )
            )
            keyword_only_parameters = tuple(
                argument.arg for argument in statement.args.kwonlyargs
            )
            variadic_parameters = tuple(
                argument.arg
                for argument in (statement.args.vararg, statement.args.kwarg)
                if argument is not None
            )
        parameter_names = (
            *positional_parameters,
            *keyword_only_parameters,
            *variadic_parameters,
        )
        static_parameter_bindings = _concorded_static_parameter_bindings(
            statement,
            parameter_names,
        )
        static_parameter_receipts = tuple(
            (
                name,
                "static_class",
                str(getattr(value, "__module__", "")),
                str(getattr(
                    value,
                    "__qualname__",
                    getattr(value, "__name__", ""),
                )),
            )
            for name, value in static_parameter_bindings.items()
        )
        parameter_defaults = {}
        if isinstance(
            statement,
            (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda),
        ):
            if statement.args.vararg is not None:
                parameter_defaults[statement.args.vararg.arg] = ()
            if statement.args.kwarg is not None:
                parameter_defaults[statement.args.kwarg.arg] = {}
        scalar_parameter_names = set()
        if isinstance(
            statement,
            (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda),
        ):
            for argument in (
                *statement.args.posonlyargs,
                *statement.args.args,
                *statement.args.kwonlyargs,
            ):
                if (
                    isinstance(argument.annotation, ast.Name)
                    and argument.annotation.id
                    in {"bool", "bytes", "complex", "float", "int", "str"}
                ):
                    scalar_parameter_names.add(argument.arg)
            positional_defaults = zip(
                positional_parameters[
                    len(positional_parameters) - len(statement.args.defaults):
                ],
                statement.args.defaults,
            )
            keyword_defaults = zip(
                keyword_only_parameters,
                statement.args.kw_defaults,
            )
            for name, default_expression in (
                *positional_defaults,
                *keyword_defaults,
            ):
                if default_expression is None:
                    continue
                try:
                    value = ast.literal_eval(default_expression)
                except (ValueError, TypeError):
                    if (
                        not isinstance(default_expression, ast.Name)
                        or default_expression.id
                        not in definition_static_bindings
                    ):
                        continue
                    value = definition_static_bindings[default_expression.id]
                # ``parameter_defaults`` is executable/persisted graph data,
                # not the source resolver's live Python namespace.  Objects
                # such as compiler registries remain available in
                # ``definition_static_bindings`` while their uses are
                # normalized, but are never mislabeled as literal arguments
                # or embedded in a worker checkpoint.
                if not is_python_static_literal(value):
                    continue
                parameter_defaults[name] = value
                if isinstance(
                    value,
                    (bool, bytes, complex, float, int, str),
                ):
                    scalar_parameter_names.add(name)
        definition_row = getattr(statement, "_turing_source_span_row", None)
        function_graph.G.graph.update(
            authored_function_identity=(
                tuple(definition_row if isinstance(statement, ast.Lambda) else definition_row[:2])
                if definition_row is not None else None),
            function_ref=reference.address,
            function_name=function_table.entry(reference).name,
            source_pursuit_active=bool(
                getattr(statement, "_source_pursuit_active", False)
            ),
            method_owner=method_owners.get(node_id),
            method_binding=(
                "class"
                if isinstance(
                    statement,
                    (ast.FunctionDef, ast.AsyncFunctionDef),
                )
                and any(
                    isinstance(decorator, ast.Name)
                    and decorator.id == "classmethod"
                    for decorator in statement.decorator_list
                )
                else (
                    "static"
                    if isinstance(
                        statement,
                        (ast.FunctionDef, ast.AsyncFunctionDef),
                    )
                    and any(
                        isinstance(decorator, ast.Name)
                        and decorator.id == "staticmethod"
                        for decorator in statement.decorator_list
                    )
                    else (
                        "instance"
                        if method_owners.get(node_id) is not None
                        else None
                    )
                )
            ),
            function_parameters=parameter_names,
            static_parameter_bindings=static_parameter_receipts,
            positional_parameters=positional_parameters,
            keyword_only_parameters=keyword_only_parameters,
            parameter_defaults=parameter_defaults,
            scalar_parameters=tuple(sorted(scalar_parameter_names)),
            function_body=(
                tuple(statement.body)
                if isinstance(
                    statement,
                    (ast.FunctionDef, ast.AsyncFunctionDef),
                )
                else ()
            ),
            class_field_aggregate_kinds={
                field: kind
                for (owner, field), kind in class_field_aggregate_kinds.items()
                if owner == method_owners.get(node_id)
            },
            class_field_aliases={
                field: target
                for (owner, field), target in class_field_aliases.items()
                if owner == method_owners.get(node_id)
            },
            class_field_value_aggregate_kinds={
                field: kind
                for (owner, field), kind
                in class_field_value_aggregate_kinds.items()
                if owner == method_owners.get(node_id)
            },
            class_field_mapping_contracts={
                field: dict(contract)
                for (owner, field), contract in class_field_mapping_contracts.items()
                if owner == method_owners.get(node_id)
            },
        )
        parameter_contracts = _known_parameter_memory_contracts(
            statement,
            parameter_names,
            method_owner=method_owners.get(node_id),
            static_parameter_names=frozenset(static_parameter_bindings),
        )
        if parameter_contracts:
            function_table.set_parameter_contracts(
                reference,
                parameter_contracts,
            )
        for member in function_graph.G:
            member_data = function_graph.G.nodes[member]
            expression = member_data.get("expr_obj")
            if (
                isinstance(expression, ast.Name)
                and isinstance(expression.ctx, ast.Load)
                and expression.id in parameter_names
            ):
                member_data["type"] = "Input"
                member_data["op"] = "input"
                member_data["label"] = expression.id
                _set_operands(
                    function_graph, member, [], cause=_PARAMETER_INPUT,
                )
            if (
                member_data.get("type") == "Input"
                and (
                    member_data.get("attributes") or {}
                ).get("binding_name") in scalar_parameter_names
            ):
                # A ``scalar_parameter`` row for the ingested Input (plan
                # 60, section 3.5): DERIVED from (i) the parameter's
                # ``parameter_annotation`` row or (ii) the span of its
                # scalar literal default, and the Input's own cell.  The
                # attribute is the row's read view.  The Inputs
                # ``_normalize_lexical_values`` mints for the same names
                # post their rows in ``input_value``; the relabel tail
                # posts the canonical rows.
                member_data.setdefault("attributes", {})[
                    "value_kind"
                ] = "scalar"
                post_scalar_parameter(
                    function_graph, member,
                    str(member_data["attributes"]["binding_name"]),
                    statement,
                )
            _set_operands(function_graph, member, [
                (parent, role)
                for parent, role in member_data.get("parents", ())
                if parent in included
            ], cause=_FUNCTION_SUBGRAPH_FILTER)
            # Entries naming nodes outside the subgraph: those consumers
            # are not in ``function_graph``, so no ``_set_operands`` call
            # of theirs can clear them.
            member_data["children"] = [
                (child, role)
                for child, role in member_data.get("children", ())
                if child in included
            ]
        normalization_statement = statement
        if isinstance(statement, ast.Lambda):
            normalization_statement = ast.copy_location(
                ast.FunctionDef(
                    name=function_table.entry(reference).name,
                    args=statement.args,
                    body=[
                        ast.copy_location(
                            ast.Return(value=statement.body),
                            statement.body,
                        )
                    ],
                    decorator_list=[],
                    returns=None,
                    type_comment=None,
                ),
                statement,
            )
        # Normalize attributes with returned receiver classes already
        # attached.  This lets a field on an authored method result inherit
        # the class's aggregate/storage contract just like ``self.field``.
        propagate_returned_receiver_types(function_graph.G)
        local_mapping_contracts = dict(class_field_mapping_contracts)
        local_owner = method_owners.get(node_id)
        if local_owner is not None:
            for declaration in (
                candidate for candidate in ast.walk(normalization_statement)
                if isinstance(candidate, ast.AnnAssign)
                and isinstance(candidate.target, ast.Attribute)
                and isinstance(candidate.target.value, ast.Name)
                and candidate.target.value.id in {"self", "cls"}
            ):
                contract = _mapping_annotation(declaration.annotation)
                if contract:
                    local_mapping_contracts[
                        (str(local_owner), str(declaration.target.attr))
                    ] = contract
        nested_lexical_free_names = _normalize_lexical_values(
            function_graph,
            normalization_statement,
            definition_static_bindings,
            function_table,
            lexical_functions_by_owner.get(int(reference.address), {}),
            closure_aggregate_kinds(node_id),
            local_declared_aggregate_kinds_by_function.get(node_id, {}),
            local_mapping_contracts_by_function.get(node_id, {}),
            lexical_free_names_by_function.get(int(reference.address), ()),
            method_owner=method_owners.get(node_id),
            class_field_aggregate_kinds=class_field_aggregate_kinds,
            class_field_mapping_contracts=local_mapping_contracts,
            class_field_sequence_dtypes=class_field_sequence_dtypes,
            class_field_sequence_element_classes=(
                class_field_sequence_element_classes
            ),
            class_field_sequence_records=class_field_sequence_records,
            class_field_storage_contracts=class_field_storage_contracts,
            class_field_classes=class_field_classes,
            static_parameter_bindings=static_parameter_bindings,
            authored_definitions_by_name=authored_definitions_by_name,
        )
        lexical_free_names_by_function.update(nested_lexical_free_names)
        generator_yields = tuple(
            node_id
            for node_id, node_data in function_graph.G.nodes(data=True)
            if isinstance(
                node_data.get("expr_obj"),
                (ast.Yield, ast.YieldFrom),
            )
        )
        if generator_yields:
            function_graph.G.graph["generator_stream"] = {
                "yield_nodes": generator_yields,
                "flow_control": "downstream_capacity",
                "execution_owner": "planner_shell",
            }
        # The canonical ``scalar_parameter`` rows (and the ``value_kind``
        # attribute on the Inputs ``input_value`` minted) are the relabel
        # tail's job (plan 60, section 3.5 (c)); no second write here.
        if hasattr(statement, "_python_bindings"):
            delattr(statement, "_python_bindings")
        if hasattr(statement, "_python_aggregate_binding_kinds"):
            delattr(statement, "_python_aggregate_binding_kinds")
        function_graph.python_bindings = canonicalize_python_static_bindings(
            function_graph.python_bindings
        )
        function_table.resolve_graph(reference, function_graph)
    # Function graphs are attached only after the earlier root-graph pass.
    # Reuse that exact provenance propagation now that every callee body is
    # available, so a call in a function body retains its returned class.
    def propagate_call_formal_numeric_types() -> bool:
        """Carry exact numeric class facts over authored call edges.

        A retained base method deliberately does not hard-code the concrete
        wrapper used at a callsite.  The call edge is the proof: its actual
        has an already-concorded class/width, and the callee formal is the
        same value.  Commit that identity through the concordance book before
        publishing it on the formal node; copied AST annotations are not an
        independent typing channel.
        """

        entries = {
            int(entry.reference.address): entry
            for entry in function_table
            if getattr(entry, "graph", None) is not None
        }

        changed = False
        formal_evidence: dict[
            tuple[str, int], dict[str, Any]
        ] = {}
        numeric_class_identities = set(_NUMERIC_TYPE_FEATURES)
        pending_numeric_bases = list(numeric_class_identities)
        while pending_numeric_bases:
            derived = pending_numeric_bases.pop()
            for base in class_bases.get(derived, ()):
                if base not in numeric_class_identities:
                    numeric_class_identities.add(base)
                    pending_numeric_bases.append(base)

        def publish_formal_class(
            callee_scope: str,
            formal_id: int,
            callee: Any,
            class_identity: str,
            limbs: int,
            transfer_source: str,
            provenance_cells: tuple[Any, ...],
        ) -> None:
            nonlocal changed
            formal_attributes = callee.nodes[formal_id].setdefault(
                "attributes", {}
            )
            prior = (
                formal_attributes.get("result_class_ref"),
                int(formal_attributes.get("precision_limbs") or 1),
            )
            _concord_source_value_class(
                callee_scope,
                formal_id,
                str(class_identity),
                precision_limbs=int(limbs),
                source=transfer_source,
                provenance=_Derived(tuple(dict.fromkeys(
                    cell for cell in provenance_cells
                    if isinstance(cell, _Ref)
                ))),
            )
            # The actual-to-formal edge transfers the instance's class
            # identity; it does not turn the formal Input into a constructor.
            # ``class_ref`` is consumed by deployment as a request to call
            # ``__init__``.  Stamping it here recursively constructed every
            # specialized ``self`` and ``other`` parameter and exported the
            # resulting private frames all the way to the root ABI.
            formal_attributes.pop("class_ref", None)
            formal_attributes.update({
                "result_class_ref": str(class_identity),
                "precision_limbs": int(limbs),
                "numeric_identity_source": transfer_source,
            })
            descriptor = numeric_feature_descriptor(
                str(class_identity) + (
                    f"[{int(limbs)}]" if int(limbs) > 1 else ""
                )
            )
            if descriptor is not None:
                formal_attributes["numeric_feature_descriptor"] = (
                    descriptor.receipt()
                )
            changed = changed or prior != (
                str(class_identity), int(limbs),
            )
        for caller_entry in entries.values():
            caller = caller_entry.graph.G
            if not caller.graph.get("source_pursuit_active"):
                continue
            caller_scope = _source_numeric_scope(caller, caller_entry.name)
            for call_id, call_data in tuple(caller.nodes(data=True)):
                call_attributes = call_data.get("attributes") or {}
                callee_ref = call_attributes.get(
                    "callee_ref", call_attributes.get("method_ref")
                )
                if callee_ref is None or int(callee_ref) not in entries:
                    continue
                callee_entry = entries[int(callee_ref)]
                callee = callee_entry.graph.G
                callee_scope = _source_numeric_scope(
                    callee, callee_entry.name
                )
                reachability_page = current_identity_book().page(
                    "source_function_reachability_concordance"
                )
                from ...compiler.concordance_declarations import (
                    SOURCE_FUNCTION_REACHABILITY as _SOURCE_FUNCTION_REACHABILITY,
                )
                reachability_row = (
                    caller_scope, int(call_id), callee_scope,
                )
                incumbent_reachability = reachability_page.latest(
                    reachability_row
                )
                if incumbent_reachability is not None and (
                    incumbent_reachability is not True
                ):
                    raise ValueError(
                        "source function reachability concordance "
                        f"disagreement for {reachability_row!r}: "
                        f"recorded={incumbent_reachability!r}, proposed=True"
                    )
                if incumbent_reachability is None:
                    # DERIVED(the call node's cell, the callee's address).
                    reach_book = current_identity_book()
                    reach_cells = tuple(
                        cell for cell in (
                            node_identity_cell(caller_entry.graph, int(call_id)),
                            reach_book.latest_ref(
                                _FUNCTION_ADDRESS,
                                (function_address_identity(callee_entry),),
                            ),
                        )
                        if cell is not None
                    )
                    reach_book.post(
                        _SOURCE_FUNCTION_REACHABILITY, reachability_row, True,
                        stage=_REDUCTION,
                        provenance=_Derived(reach_cells),
                        mode=_Mode.CONCORD,
                    )
                if not callee.graph.get("source_pursuit_active"):
                    callee.graph["source_pursuit_active"] = True
                    changed = True
                output_histories = dict(
                    callee.graph.get("identity_table") or {}
                )
                returned_value_ids = tuple(
                    int(history[-1])
                    for output_name in tuple(
                        callee.graph.get("function_outputs") or ()
                    )
                    for history in (tuple(
                        output_histories.get(str(output_name)) or ()
                    ),)
                    if history and int(history[-1]) in callee
                )
                returned_facts = tuple(dict.fromkeys(
                    _resolved_source_value_class(callee, value_id)
                    for value_id in returned_value_ids
                    if _resolved_source_value_class(
                        callee, value_id
                    )[0] is not None
                ))
                # Program: ``def compact(n) -> tuple[list[int], bool]:
                # ... return out, len(out) > 2`` then ``t, big =
                # compact(n)`` (A6 probe c984).  Wrong record: the call
                # result took the class of the one member that had a class
                # fact (``out``: list), so the tuple result was concorded
                # as a list and its contract became a list/tuple union.
                # Rule: a call result is a returned member's class only
                # when the callee returns ONE value; several outputs are
                # one tuple, never any member.
                if len(returned_facts) == 1 and len(returned_value_ids) == 1:
                    returned_class, returned_limbs = returned_facts[0]
                    result_book = current_identity_book()
                    result_page = result_book.page(
                        _SOURCE_CALL_RESULT_IDENTITY
                    )
                    result_row = (caller_scope, int(call_id))
                    callee_identity = tuple(
                        callee.graph.get("authored_function_identity") or ()
                    )
                    equivalent_entries = tuple(
                        entry
                        for entry in function_table
                        if entry.graph is not None
                        and tuple(entry.graph.G.graph.get(
                            "authored_function_identity"
                        ) or ()) == callee_identity
                    )
                    canonical_entry = min(
                        equivalent_entries,
                        key=lambda entry: int(entry.reference.address),
                    ) if equivalent_entries else callee_entry
                    result_fact = (
                        int(canonical_entry.reference.address),
                        str(returned_class),
                        int(returned_limbs),
                    )
                    incumbent_result = result_page.latest(result_row)
                    if incumbent_result is not None and tuple(
                        incumbent_result
                    ) != result_fact:
                        raise ValueError(
                            "source call result identity concordance "
                            f"disagreement for {result_row!r}: "
                            f"recorded={incumbent_result!r}, "
                            f"proposed={result_fact!r}"
                        )
                    result_sources = tuple(dict.fromkeys(
                        cell for cell in (
                            node_identity_cell(
                                caller_entry.graph, int(call_id)
                            ),
                            result_book.latest_ref(
                                _FUNCTION_ADDRESS,
                                (function_address_identity(canonical_entry),),
                            ),
                            *(
                                result_book.latest_ref(
                                    _SOURCE_VALUE_CLASS,
                                    (_source_numeric_scope(callee), value_id),
                                )
                                for value_id in returned_value_ids
                            ),
                        )
                        if cell is not None
                    ))
                    result_book.post(
                        _SOURCE_CALL_RESULT_IDENTITY,
                        result_row,
                        result_fact,
                        stage=_REDUCTION,
                        provenance=_Derived(result_sources),
                        mode=_Mode.CONCORD,
                    )
                    call_result_attributes = caller.nodes[
                        int(call_id)
                    ].setdefault("attributes", {})
                    prior_result = (
                        call_result_attributes.get("result_class_ref"),
                        int(call_result_attributes.get(
                            "precision_limbs"
                        ) or 1),
                    )
                    _concord_source_value_class(
                        caller_scope,
                        int(call_id),
                        str(returned_class),
                        precision_limbs=int(returned_limbs),
                        source=f"call result {callee_scope}",
                        provenance=_Derived((
                            result_book.latest_ref(
                                _SOURCE_CALL_RESULT_IDENTITY, result_row,
                            ),
                        )),
                    )
                    call_result_attributes.update({
                        "result_class_ref": str(returned_class),
                        "precision_limbs": int(returned_limbs),
                        "numeric_identity_source": (
                            f"call result {callee_scope}"
                        ),
                    })
                    returned_descriptor = numeric_feature_descriptor(
                        str(returned_class) + (
                            f"[{int(returned_limbs)}]"
                            if int(returned_limbs) > 1 else ""
                        )
                    )
                    if returned_descriptor is not None:
                        call_result_attributes[
                            "numeric_feature_descriptor"
                        ] = returned_descriptor.receipt()
                    changed = changed or prior_result != (
                        str(returned_class), int(returned_limbs),
                    )
                receiver, positional, _all_parameters = (
                    _method_parameter_layout(callee)
                )
                formal_nodes = {
                    str(attributes.get("binding_name")): int(node_id)
                    for node_id, data in callee.nodes(data=True)
                    for attributes in (data.get("attributes") or {},)
                    if data.get("type") == "Input"
                    and attributes.get("binding_name") is not None
                }
                # ``self.helper(arg)`` retains ``self`` as the attribute
                # operand even when ``helper`` is a staticmethod.  The old
                # local positional sorter treated every operand as formal 0,
                # assigning the caller's class to ``helper(name: str, ...)``.
                # Bind through the shared authored ABI mechanism: it consults
                # the callee's exact method_binding receipt and therefore
                # binds an operand only for instance/class methods.
                for actual_id, role in _expanded_callsite_argument_edges(
                    caller_entry.graph, int(call_id)
                ):
                    parameter_name = _callsite_parameter_name(
                        str(role), receiver, positional
                    )
                    formal_id = formal_nodes.get(str(parameter_name))
                    if formal_id is None:
                        continue
                    formal_key = (callee_scope, formal_id)
                    evidence = formal_evidence.setdefault(formal_key, {
                        "graph": callee,
                        "facts": [],
                    })
                    class_page = current_identity_book().page(
                        "source_value_class_concordance"
                    )
                    concorded = class_page.latest((
                        caller_scope, int(actual_id),
                    ))
                    actual_class_cell = current_identity_book().latest_ref(
                        _SOURCE_VALUE_CLASS,
                        (caller_scope, int(actual_id)),
                    )
                    class_identity, limbs = (
                        (str(concorded[0]), int(concorded[1]))
                        if isinstance(concorded, tuple)
                        and len(concorded) >= 2
                        else _resolved_source_value_class(
                            caller, int(actual_id)
                        )
                    )
                    if class_identity is None:
                        continue
                    actual_attributes = (
                        caller.nodes[int(actual_id)].get("attributes") or {}
                    )
                    transfer_source = (
                        f"call actual {caller_scope}:{actual_id}"
                        + (
                            " via "
                            + str(actual_attributes["numeric_identity_source"])
                            if actual_attributes.get("numeric_identity_source")
                            else ""
                        )
                    )
                    transfer_cells = tuple(dict.fromkeys(
                        cell for cell in (
                            actual_class_cell,
                            node_identity_cell(caller, int(call_id)),
                            node_identity_cell(callee, int(formal_id)),
                        )
                        if isinstance(cell, _Ref)
                    ))
                    if str(class_identity) in numeric_class_identities:
                        publish_formal_class(
                            callee_scope, formal_id, callee,
                            str(class_identity), int(limbs), transfer_source,
                            transfer_cells,
                        )
                    else:
                        evidence["facts"].append((
                            str(class_identity), int(limbs), transfer_source,
                            transfer_cells,
                        ))
        for (callee_scope, formal_id), evidence in formal_evidence.items():
            facts = tuple(evidence["facts"])
            class_page = current_identity_book().page(
                "source_value_class_concordance"
            )
            declared = class_page.latest((callee_scope, int(formal_id)))
            if (
                isinstance(declared, tuple)
                and len(declared) >= 3
                and str(declared[2]).startswith("parameter annotation")
            ):
                # A non-numeric annotation is the callee's authored record
                # interface, not a promise that every Python actual has the
                # same nominal class.  The dt controller deliberately passes
                # its wider Metrics publication record to helpers annotated
                # with the narrower StepSpans interface.  Keep the declared
                # formal class; only a nominally identical actual adds another
                # concordance edge.  Record-field lowering remains responsible
                # for proving every field the callee actually reads.
                matching = tuple(
                    fact for fact in facts
                    if (
                        _canonical_source_class_identity(fact[0]),
                        int(fact[1]),
                    ) == (
                        str(declared[0]), int(declared[1]),
                    )
                )
                if matching:
                    publish_formal_class(
                        callee_scope, formal_id, evidence["graph"],
                        str(declared[0]), int(declared[1]),
                        matching[0][2],
                        tuple(dict.fromkeys(
                            cell
                            for _identity, _limbs, _source, cells in matching
                            for cell in cells
                        )),
                    )
                continue
            distinct = {
                (class_identity, limbs)
                for class_identity, limbs, _source, _cells in facts
            }
            # A formal owns one class concordance row.  Publish it only when
            # all resolved authored incoming call edges prove the same
            # identity.  Multiple legitimate record variants mean the formal
            # remains generic; selecting the first call would invent an
            # identity and make traversal order semantic.  Unknown actuals
            # supply no contradictory class fact and may settle in a later
            # fixed-point round.
            if len(distinct) != 1:
                continue
            class_identity, limbs = next(iter(distinct))
            transfer_source = facts[0][2]
            transfer_cells = tuple(dict.fromkeys(
                cell
                for _identity, _limbs, _source, cells in facts
                for cell in cells
            ))
            callee = evidence["graph"]
            publish_formal_class(
                callee_scope, formal_id, callee,
                str(class_identity), int(limbs), transfer_source,
                transfer_cells,
            )
        return changed

    # Operators reveal new exact callees; those call edges reveal the
    # concrete type of an unannotated ``self``/``other`` formal.  Settle the
    # two facts together rather than relying on traversal order.
    compile_substage("topology: settle numeric operator call contracts")
    for _round in range(max(len(tuple(function_table)), 1) + 1):
        operator_classes_changed = False
        for entry in compile_iter(function_table, "numeric-call-contracts",
                label="Numeric operator call contracts settled"):
            entry_wrapper = getattr(entry, "graph", None)
            if entry_wrapper is not None:
                propagate_returned_receiver_types(entry_wrapper.G)
                propagate_numeric_field_projections(entry_wrapper)
                lower_python_precision(entry_wrapper)
                specialize_concorded_same_type_numeric_operator(entry_wrapper)
                resolve_concorded_receiver_constructor(entry_wrapper)
                lower_class_operator_calls(entry_wrapper)
                if _propagate_builtin_scalar_operator_classes(entry_wrapper):
                    operator_classes_changed = True
        if not propagate_call_formal_numeric_types() and not operator_classes_changed:
            break
    # String Core computes token = AGGREGATE_BASE + len(self.domain), then
    # appends that exact value to two field-owned child lists.  The AST survey
    # knew neither the computed payload nor a named tuple key's layout: put
    # had four key columns while __init__/read retained one.  Read the settled
    # append operand and tuple layout, sharing only through the canonical
    # field declaration.  These dictionaries are views of the referenced
    # book cells, not a second source-value identity.
    mapping_contract_views = {}
    mapping_contract_evidence = []
    unproved_mapping_fields = set()
    for entry in function_table:
        wrapper = getattr(entry, "graph", None)
        if wrapper is None:
            continue
        target = wrapper.G
        scope = _source_numeric_scope(wrapper)
        for append_id, append_data in target.nodes(data=True):
            if str(append_data.get("type") or append_data.get("op")).casefold() != "append":
                continue
            parents = dict((str(role), int(parent)) for parent, role in append_data.get("parents") or ())
            selected_id, payload_id = parents.get("operand"), parents.get("arg:0")
            if selected_id not in target or payload_id not in target:
                continue
            selected = target.nodes[selected_id]
            if str(selected.get("type") or selected.get("op")).casefold() != "setdefault":
                continue
            selected_parents = dict((str(role), int(parent)) for parent, role in selected.get("parents") or ())
            field_id, key_id = selected_parents.get("operand"), selected_parents.get("arg:0")
            if field_id not in target or key_id not in target:
                continue
            field_attrs = target.nodes[field_id].get("attributes") or {}
            field_cell = field_attrs.get("field_declaration_cell")
            if not isinstance(field_cell, _Ref) or field_cell.page != _CLASS_FIELD_DECLARATION:
                continue
            payload_value = int(target.nodes[payload_id].get("value_id", payload_id))
            class_cell = current_identity_book().latest_ref(_SOURCE_VALUE_CLASS, (scope, payload_value))
            if class_cell is None:
                unproved_mapping_fields.add(field_cell)
                continue
            class_fact = current_identity_book().page(_SOURCE_VALUE_CLASS).cell(class_cell.row, class_cell.column)
            if int(class_fact[1]) != 1:
                unproved_mapping_fields.add(field_cell)
                continue
            storage = _annotation_storage(ast.Name(id=str(class_fact[0]).rsplit(".", 1)[-1]))
            dtype = storage.get("dtype")
            if str(class_fact[0]) not in {"builtins.int", "builtins.float", "builtins.bool"} or dtype not in {"int64", "float64", "bool"}:
                unproved_mapping_fields.add(field_cell)
                continue
            key_attrs = target.nodes[key_id].get("attributes") or {}
            layout_row = key_attrs.get("source_aggregate_layout_row")
            layout_cell = None if layout_row is None else current_identity_book().latest_ref(_SOURCE_AGGREGATE_LAYOUT, tuple(layout_row))
            if layout_cell is None:
                unproved_mapping_fields.add(field_cell)
                continue
            layout = current_identity_book().page(_SOURCE_AGGREGATE_LAYOUT).cell(layout_cell.row, layout_cell.column)
            if layout.aggregate_kind != "tuple" or not layout.members:
                unproved_mapping_fields.add(field_cell)
                continue
            key_class_cells = tuple(
                current_identity_book().latest_ref(
                    _SOURCE_VALUE_CLASS, (scope, int(member.value_id)),
                ) for member in layout.members
            )
            key_dtypes = tuple(
                {"builtins.int": "int64", "builtins.float": "float64", "builtins.bool": "bool"}.get(
                    str(current_identity_book().page(_SOURCE_VALUE_CLASS).cell(cell.row, cell.column)[0]), "unknown",
                ) if cell is not None else "unknown"
                for cell in key_class_cells
            )
            proposed = {"mapping_child_column_dtypes": (str(dtype),), "mapping_value_aggregate_kind": "list", "mapping_key_column_count": len(layout.members), "mapping_key_column_dtypes": key_dtypes, "mapping_value_dtype": "int64"}
            incumbent = mapping_contract_views.setdefault(field_cell, proposed)
            if incumbent != proposed:
                raise ValueError(f"mapping child writers disagree for declaration {field_cell!r}")
            mapping_contract_evidence.append({"field_cell": field_cell, "class_cell": class_cell, "key_layout_cell": layout_cell, "dtype": str(dtype), "key_width": len(layout.members), "key_class_cells": key_class_cells, "key_dtypes": key_dtypes})
    if unproved_mapping_fields.intersection(mapping_contract_views):
        raise ValueError("mapping child writers include an unproved payload or key layout for the same field declaration")
    for entry in function_table:
        wrapper = getattr(entry, "graph", None)
        if wrapper is None:
            continue
        target = wrapper.G
        contracts = target.graph.setdefault("class_field_mapping_contracts", {})
        owned_field_cells = {
            (data.get("attributes") or {}).get("field_declaration_cell")
            for _node, data in target.nodes(data=True)
        }
        for field_cell, contract in mapping_contract_views.items():
            if field_cell in owned_field_cells:
                contracts.setdefault(str(field_cell.row[2]), {}).update(contract)
        for _node, data in target.nodes(data=True):
            attrs = data.setdefault("attributes", {})
            contract = mapping_contract_views.get(attrs.get("field_declaration_cell"))
            if contract is not None:
                attrs.update(contract)
        for _node, data in target.nodes(data=True):
            operation = str(data.get("type") or data.get("op")).casefold()
            if operation not in {"get", "setdefault"}:
                continue
            field_id = next((int(parent) for parent, role in data.get("parents") or () if str(role) == "operand"), None)
            if field_id not in target:
                continue
            contract = mapping_contract_views.get((target.nodes[field_id].get("attributes") or {}).get("field_declaration_cell"))
            if contract is not None:
                data.setdefault("attributes", {}).update({"producer_kind": "mapping_lookup_result" if operation == "get" else "mapping_default_result", "aggregate_kind": "list", "sequence_column_count": 1, "sequence_column_dtypes": contract["mapping_child_column_dtypes"], "sequence_element_class_ref": {"int64": "builtins.int", "float64": "builtins.float", "bool": "builtins.bool"}[contract["mapping_child_column_dtypes"][0]]})
    graph.G.graph["mapping_child_contract_evidence"] = tuple(mapping_contract_evidence)

    # An unannotated formal's class arrives on the call edge above, after
    # its function's glyph recipes were authored and linked; link the
    # integer formatter again now that the facts have settled.
    compile_substage("topology: link settled glyph formatters")
    for entry in compile_iter(function_table, "settled-glyph-formatters",
            label="Settled glyph formatters linked"):
        entry_wrapper = getattr(entry, "graph", None)
        if entry_wrapper is not None:
            _relink_settled_glyph_formatters(entry_wrapper, function_table)

    compile_substage("topology: finalize extracted graph operators")
    for entry in compile_iter(function_table, "final-graph-operators",
            label="Extracted graph operators finalized"):
        entry_wrapper = getattr(entry, "graph", None)
        entry_graph = getattr(entry_wrapper, "G", None)
        if entry_graph is not None:
            # AugAssign read-modify-write structure and child roles are final
            # only after lexical normalization. Canonicalize its attribute
            # read at this post-extraction seam as well as on the root graph.
            normalize_python_attribute_special_cases(entry_wrapper)
            propagate_returned_receiver_types(entry_graph)
            propagate_numeric_field_projections(entry_wrapper)
            lower_python_precision(entry_wrapper)
            specialize_concorded_same_type_numeric_operator(entry_wrapper)
            lower_class_operator_calls(entry_wrapper, settled=True)
            # Operator calls can themselves return class instances.  Resolve
            # a following method (for example ``wide_product.collapse()``)
            # from the just-concorded result identity before call planning.
            propagate_returned_receiver_types(entry_graph)
    # External call references and static Python bindings are two views of the
    # same compile-time environment.  Join them once after every call has been
    # declared so compiled shells can invoke imported constructors/functions
    # without a second lookup mechanism.
    from array import array as _source_array_type
    source_array_external_refs = set()
    for entry in external_function_table:
        target = static_bindings.get(entry.name)
        if callable(target):
            external_function_table.resolve_callable(entry.reference, target)
            if target is _source_array_type:
                source_array_external_refs.add(entry.reference.address)
    # c632's allocation identity belongs to its exact lexical import, which
    # can live in an ingested constructor rather than the root module. Real
    # Vocabulary.__init__ retained array's callee edge and local binding, so
    # the root-only external-reference join missed its owned allocation.
    for source_wrapper in (graph, *(
        member.graph for member in function_table
        if getattr(member, "graph", None) is not None
    )):
        source_bindings = getattr(source_wrapper, "python_bindings", {}) or {}
        for _node_id, source_data in source_wrapper.G.nodes(data=True):
            source_attributes = source_data.get("attributes") or {}
            if str(source_data.get("type") or source_data.get("op") or "").casefold() != "call":
                continue
            reference = source_attributes.get("static_python_reference")
            if (
                source_bindings.get(reference) is not _source_array_type
                and source_attributes.get("external_callee_ref") not in source_array_external_refs
            ):
                continue
            # The callee edge retains the exact static callable identity;
            # only argument edges determine whether this is an empty array.
            if tuple(role for _parent, role in source_data.get("parents") or ()
                     if role != "callee") != ("arg:0",):
                continue
            source_data.setdefault("attributes", {}).update({
                "aggregate_kind": "array",
                "producer_kind": "sequence_materialization",
                "sequence_column_count": 1,
                "sequence_key_columns": (),
                "sequence_writable": True,
            })
    graph.python_bindings = canonicalize_python_static_bindings(
        graph.python_bindings
    )
    # Source discovery annotates definitions with their exact lexical Python
    # environment.  Most annotations are removed when their function graph is
    # finalized, but ProcessGraph.node_map deliberately retains every source
    # occurrence.  Canonicalize any surviving environment through the same
    # Python special case so a dead frontend annotation cannot reintroduce the
    # live wrapper after all actual uses have become Constant leaves.
    for expression in graph.node_map.values():
        bindings = getattr(expression, "_python_bindings", None)
        if isinstance(bindings, Mapping):
            expression._python_bindings = canonicalize_python_static_bindings(
                bindings
            )
    return graph


__all__ = [
    "normalize_python_attribute_special_cases",
    "reduce_abstract_tensor_topology",
    "specialize_python_precision_widths",
]
